class Loot {
    constructor(rarityTable) {
        this.rarityTable = rarityTable;
    }

    generateLoot() {
        const rarity = this.rarityTable.getRandomRarity();
        const item = this.rarityTable.getItemForRarity(rarity);
        return { rarity, item };
    }
}

class RarityTable {
    constructor(table) {
        this.table = table;
    }

    getRandomRarity() {
        const totalWeight = this.table.reduce((sum, entry) => sum + entry.weight, 0);
        const randomWeight = Math.random() * totalWeight;
        let cumulativeWeight = 0;

        for (const entry of this.table) {
            cumulativeWeight += entry.weight;
            if (randomWeight <= cumulativeWeight) {
                return entry.rarity;
            }
        }
        return null; // This should never happen with valid input
    }

    getItemForRarity(rarity) {
        const entry = this.table.find(entry => entry.rarity === rarity);
        return entry ? entry.item : null;
    }
}

class Inventory {
    constructor() {
        this.items = [];
    }

    addItem(item) {
        this.items.push(item);
    }

    getInventory() {
        return this.items;
    }
}

// Demo
const rarityTableData = [
    { rarity: 'Common', item: 'Potion', weight: 60 },
    { rarity: 'Uncommon', item: 'Scroll', weight: 30 },
    { rarity: 'Rare', item: 'Wand', weight: 9 },
    { rarity: 'Epic', item: 'Armor', weight: 1 }
];

const rarityTable = new RarityTable(rarityTableData);
const lootSystem = new Loot(rarityTable);
const inventory = new Inventory();

// Generate and add 5 loots to the inventory
for (let i = 0; i < 5; i++) {
    const loot = lootSystem.generateLoot();
    inventory.addItem(loot);
    console.log(`Generated loot: ${loot.item} (${loot.rarity})`);
}

// Display the entire inventory
console.log('Inventory:', inventory.getInventory());
