class Combat {
    constructor(healthSystem) {
        this.healthSystem = healthSystem;
    }

    attack(attacker, defender, damage) {
        console.log(`${attacker} attacks ${defender} for ${damage} damage.`);
        this.healthSystem.takeDamage(defender, damage);
    }
