// Health System
class Health {
    constructor() {
        this.healthPool = new Map();
    }

    setHealth(entity, health) {
        this.healthPool.set(entity, health);
        console.log(`${entity} has ${health} health.`);
    }

    takeDamage(entity, damage) {
        if (this.healthPool.has(entity)) {
            const currentHealth = this.healthPool.get(entity);
            const newHealth = Math.max(0, currentHealth - damage);
            this.healthPool.set(entity, newHealth);
            console.log(`${entity} takes ${damage} damage and now has ${newHealth} health.`);
            if (newHealth === 0) {
                console.log(`${entity} has been defeated.`);
            }
        } else {
            console.log(`${entity} does not exist in the health pool.`);
        }
    }
}

// Loot System
class Loot {
    constructor() {
        this.lootPool = new Map();
    }

    addLoot(entity, item) {
        if (!this.lootPool.has(entity)) {
            this.lootPool.set(entity, []);
        }
        this.lootPool.get(entity).push(item);
        console.log(`${entity} receives loot: ${item}.`);
    }

    getLoot(entity) {
        return this.lootPool.get(entity) || [];
    }
}

