// Bank System
class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

// Market System
class Market {
  constructor(prices) {
    this.prices = prices; // prices is an object mapping item names to their prices
  }

  buy(item, bank) {
    const price = this.prices[item];
    if (price && bank.withdraw(price)) {
      return true;
    }
    return false;
  }

  sell(item, bank) {
    const price = this.prices[item];
    if (price) {
      bank.deposit(price);
      return true;
    }
    return false;
  }

  getPrice(item) {
    return this.prices[item] || null;
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

// Demo
const bank = new Bank();
const market = new Market({ apple: 10, banana: 5 });
const inventory = new Inventory();

console.log("Initial Balance:", bank.getBalance()); // Initial Balance: 0

// Deposit some money into the bank
bank.deposit(100);
console.log("Balance after deposit:", bank.getBalance()); // Balance after deposit: 100

// Buy an apple from the market
if (market.buy("apple", bank)) {
  console.log("Bought an apple.");
  inventory.addItem("apple");
} else {
  console.log("Failed to buy an apple.");
}
console.log("Balance after buying apple:", bank.getBalance()); // Balance after buying apple: 90
console.log("Inventory:", inventory.getInventory()); // Inventory: { apple: 1 }

// Sell the apple back to the market
if (market.sell("apple", bank)) {
  console.log("Sold an apple.");
  inventory.removeItem("apple");
} else {
  console.log("Failed to sell an apple.");
}
console.log("Balance after selling apple:", bank.getBalance()); // Balance after selling apple: 100
console.log("Inventory:", inventory.getInventory()); // Inventory: {}

// Attempt to buy a banana with insufficient funds
if (!market.buy("banana", bank)) {
  console.log("Failed to buy a banana due to insufficient funds.");
}
console.log("Balance after failed banana purchase:", bank.getBalance()); // Balance after failed banana purchase: 100

// Attempt to sell a non-existent item
if (!market.sell("orange", bank)) {
  console.log("Failed to sell a non-existent item.");
}
console.log("Balance after failed orange sale:", bank.getBalance()); // Balance after failed orange sale: 100
