class Economy {
  constructor(initialBalance = 100) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  credit(amount) {
    this.balance += amount;
  }
}

class Store {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getItemPrice(item) {
    return this.prices[item];
  }

  purchase(item, economy) {
    const price = this.getItemPrice(item);
    if (price !== undefined && economy.debit(price)) {
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
  }

  getInventory() {
    return this.items;
  }
}

// Demo
const economy = new Economy(150);
const store = new Store({ sword: 50, shield: 30, potion: 10 });
const inventory = new Inventory();

console.log("Initial Economy Balance:", economy.getBalance());
console.log("Initial Inventory:", inventory.getInventory());

