class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      if (this.items[item]) {
        this.items[item] += quantity;
      } else {
        this.items[item] = quantity;
      }
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
    this.prices = {};
  }

  setPrice(item, price) {
    if (price > 0) {
      this.prices[item] = price;
      return true;
    }
    return false;
  }

  buyItem(item, quantity) {
    const price = this.prices[item];
    if (price && this.inventory.getItemCount(item) >= quantity) {
      const totalCost = price * quantity;
      if (this.economy.withdraw(totalCost)) {
        this.inventory.removeItem(item, quantity);
        return true;
      }
    }
    return false;
  }

  sellItem(item, quantity) {
    const price = this.prices[item];
    if (price) {
      const totalRevenue = price * quantity;
      if (this.economy.deposit(totalRevenue)) {
        this.inventory.addItem(item, quantity);
        return true;
      }
    }
    return false;
  }
}

// Demo
