const inventory = new Inventory();
const store = new Store(economy, inventory);

store.setPrice('sword', 50);
store.setPrice('shield', 30);

console.log('Initial Balance:', economy.getBalance()); // 1000
console.log('Initial Inventory:', inventory.items); // {}

store.buyItem('sword', 2);
console.log('After buying 2 swords:', economy.getBalance()); // 900
