class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  calculatePrice(quantity) {
    // Simple pricing model: price increases by 10% for each additional unit
    return this.basePrice * (1 + 0.1 * quantity);
  }
}

class Demand {
  constructor(baseDemand) {
    this.baseDemand = baseDemand;
  }

  calculateDemand(price) {
    // Simple demand model: demand decreases by 5% for each 10% increase in price
    return this.baseDemand * Math.pow(0.95, price / this.basePrice - 1);
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sell(quantity) {
    const price = this.pricing.calculatePrice(quantity);
    const demand = this.demand.calculateDemand(price);
    const actualQuantitySold = Math.min(quantity, demand);
    const revenue = price * actualQuantitySold;
    return { price, demand, actualQuantitySold, revenue };
  }
}

