class Crafting {
  constructor(recipeSystem, inventorySystem) {
    this.recipeSystem = recipeSystem;
    this.inventorySystem = inventorySystem;
  }

  canCraft(recipeName) {
    const recipe = this.recipeSystem.getRecipe(recipeName);
    if (!recipe) return false;
    for (const [item, amount] of Object.entries(recipe)) {
      if (this.inventorySystem.getQuantity(item) < amount) return false;
    }
    return true;
  }

  craft(recipeName) {
    if (!this.canCraft(recipeName)) {
      console.log(`Cannot craft ${recipeName}: insufficient materials.`);
      return false;
    }
    const recipe = this.recipeSystem.getRecipe(recipeName);
    for (const [item, amount] of Object.entries(recipe)) {
      this.inventorySystem.remove(item, amount);
    }
