class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients;
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return { ...this.ingredients };
  }
}

class Crafting {
  constructor(recipeBook, inventory) {
    this.recipeBook = recipeBook;
    this.inventory = inventory;
  }

  canCraft(recipeName) {
    const recipe = this.recipeBook.find(r => r.getName() === recipeName);
    if (!recipe) return false;

    const ingredients = recipe.getIngredients();
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (this.inventory.getItemCount(item) < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName) {
    const recipe = this.recipeBook.find(r => r.getName() === recipeName);
    if (!recipe) return false;

    if (!this.canCraft(recipeName)) return false;

    const ingredients = recipe.getIngredients();
    for (const [item, quantity] of Object.entries(ingredients)) {
      this.inventory.removeItem(item, quantity);
    }

    // Assuming the crafted item is named after the recipe
    this.inventory.addItem(recipe.getName(), 1);
    return true;
  }

  getCraftableRecipes() {
    return this.recipeBook.filter(recipe => this.canCraft(recipe.getName()));
  }
}

