    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Bank {
  constructor(eventBus) {
    this.balance = 0;
    this.eventBus = eventBus;
    this.eventBus.subscribe('sellItem', this.onSellItem.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}, new balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (amount > this.balance) {
      console.log('Insufficient funds');
      return false;
    }
    this.balance -= amount;
    console.log(`Withdrew ${amount}, new balance: ${this.balance}`);
    return true;
  }

  onSellItem(data) {
    const { price } = data;
    if (this.withdraw(price)) {
      console.log(`Sold item for ${price}`);
      this.eventBus.emit('itemSold', { price });
    } else {
      console.log('Failed to sell item due to insufficient funds');
    }
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemSold', this.onItemSold.bind(this));
  }

  sellItem(price) {
    console.log(`Item for sale at ${price}`);
    this.eventBus.emit('sellItem', { price });
  }

  onItemSold(data) {
    const { price } = data;
    console.log(`Received ${price} for sold item`);
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = [];
    this.eventBus = eventBus;
  }

  addItem(item) {
    this.items.push(item);
    console.log(`Added item: ${item}`);
  }

  sellItem(item, price) {
    if (this.items.includes(item)) {
      this.items = this.items.filter(i => i !== item);
      console.log(`Removed item: ${item}`);
      this.eventBus.emit('sellItem', { price });
    } else {
      console.log('Item not found in inventory');
    }
  }
}

