// Inventory System
class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    hasIngredients(recipe) {
        const ingredients = recipe.getIngredients();
        for (const [item, quantity] of Object.entries(ingredients)) {
            if (!this.items[item] || this.items[item] < quantity) {
                return false;
            }
        }
        return true;
    }
}

// Crafting System
class Crafting {
    constructor(inventory, recipes) {
        this.inventory = inventory;
        this.recipes = recipes;
    }

    craft(recipeName) {
        const recipe = this.recipes.find(r => r.getName() === recipeName);
        if (!recipe) {
            console.log(`Recipe "${recipeName}" not found.`);
            return false;
        }

        if (!this.inventory.hasIngredients(recipe)) {
            console.log(`Missing ingredients for "${recipeName}".`);
            return false;
        }

        for (const [item, quantity] of Object.entries(recipe.getIngredients())) {
            this.inventory.removeItem(item, quantity);
        }

        console.log(`Crafted "${recipeName}".`);
        return true;
    }

    getRecipes() {
        return this.recipes.map(recipe => recipe.getName());
    }
}

