class Loot {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('generateLoot', this.handleGenerateLoot.bind(this));
    }

    handleGenerateLoot() {
        const loot = this.rollLoot();
        this.eventBus.emit('lootGenerated', loot);
    }

    rollLoot() {
        const rarities = ['Common', 'Uncommon', 'Rare', 'Epic', 'Legendary'];
        const rarity = rarities[Math.floor(Math.random() * rarities.length)];
        return { item: `Item of ${rarity}`, rarity };
    }
}

class RarityTable {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('lootGenerated', this.handleLootGenerated.bind(this));
    }

    handleLootGenerated(loot) {
        const dropChance = this.getDropChance(loot.rarity);
        console.log(`Loot: ${loot.item} (Drop Chance: ${dropChance}%)`);
        this.eventBus.emit('dropChanceCalculated', { loot, dropChance });
    }

    getDropChance(rarity) {
        switch (rarity) {
            case 'Common': return 80;
            case 'Uncommon': return 40;
            case 'Rare': return 15;
            case 'Epic': return 5;
            case 'Legendary': return 1;
            default: return 0;
        }
    }
}

class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('dropChanceCalculated', this.handleDropChanceCalculated.bind(this));
        this.items = [];
    }

    handleDropChanceCalculated({ loot, dropChance }) {
        const isDropped = Math.random() * 100 < dropChance;
        if (isDropped) {
            this.items.push(loot.item);
            console.log(`Item added to inventory: ${loot.item}`);
        } else {
            console.log(`Item not added to inventory: ${loot.item}`);
        }
    }

    listItems() {
        console.log('Inventory Items:', this.items);
    }
}

