    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(callback => callback(data));
    }
  }
}

class Bank {
  constructor(eventBus) {
    this.balance = 0;
    this.eventBus = eventBus;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      this.eventBus.emit('balanceChanged', { balance: this.balance });
      console.log(`Deposited ${amount}, new balance: ${this.balance}`);
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      this.eventBus.emit('balanceChanged', { balance: this.balance });
      console.log(`Withdrew ${amount}, new balance: ${this.balance}`);
    }
  }
}

class Market {
  constructor(eventBus) {
    this.prices = { apple: 1, banana: 2 };
    this.eventBus = eventBus;
    this.eventBus.subscribe('buy', this.buy.bind(this));
  }

  buy(item, quantity) {
    const price = this.prices[item];
    if (price) {
      const totalCost = price * quantity;
      this.eventBus.emit('requestWithdrawal', { amount: totalCost, callback: (success) => {
        if (success) {
          console.log(`Bought ${quantity} ${item}(s) for ${totalCost}`);
          this.eventBus.emit('marketTransaction', { item, quantity });
        } else {
          console.log(`Insufficient funds to buy ${quantity} ${item}(s)`);
        }
      }});
    } else {
      console.log(`Item ${item} not available in the market.`);
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = { apple: 0, banana: 0 };
    this.eventBus = eventBus;
    this.eventBus.subscribe('marketTransaction', this.addItems.bind(this));
  }

  addItems({ item, quantity }) {
    if (this.items[item] !== undefined) {
      this.items[item] += quantity;
      console.log(`Added ${quantity} ${item}(s) to inventory. Current inventory:`, this.items);
    }
  }
}

