class Farm {
  constructor(market) {
    this.market = market;
    this.crops = [];
    this.balance = 0;
  }

  plantCrop(crop) {
    this.crops.push(crop);
  }

  harvestCrops() {
    let totalHarvest = 0;
    this.crops.forEach(crop => {
      totalHarvest += crop.harvest();
    });
    return totalHarvest;
  }

  sellCrops() {
    let totalEarnings = 0;
    this.crops.forEach(crop => {
      const price = this.market.getPrice(crop);
      totalEarnings += price * crop.yieldPerHarvest;
    });
    this.balance += totalEarnings;
    this.crops = [];
    return totalEarnings;
  }

  getBalance() {
    return this.balance;
  }
}

