console.log('Initial Resources:', coordinator.getResources());
console.log('Initial Reputation:', coordinator.getReputation());
console.log('Initial Faction Standing:', coordinator.getFactionStanding());

const tradeSuccess = coordinator.tradeResource('wood', 10, 20);
console.log('Trade Success:', tradeSuccess);

console.log('Updated Resources:', coordinator.getResources());
console.log('Updated Reputation:', coordinator.getReputation());
console.log('Updated Faction Standing:', coordinator.getFactionStanding());
