class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes; // { recipeName: Recipe }
  }

  canCraft(recipeName) {
    const recipe = this.recipes[recipeName];
    if (!recipe) return false;

    const ingredients = recipe.getIngredients();
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (this.inventory.getItems()[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName) {
    const recipe = this.recipes[recipeName];
    if (!recipe) return false;

    if (this.canCraft(recipeName)) {
      const ingredients = recipe.getIngredients();
      for (const [item, quantity] of Object.entries(ingredients)) {
        this.inventory.removeItem(item, quantity);
      }
      console.log(`Crafted: ${recipe.getName()}`);
      return true;
    }
    console.log(`Cannot craft: ${recipe.getName()}`);
    return false;
  }
}

