class EventBus {
    constructor() {
        this.listeners = {};
    }

    subscribe(event, callback) {
        if (!this.listeners[event]) {
            this.listeners[event] = [];
        }
        this.listeners[event].push(callback);
    }

    emit(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(callback => callback(data));
        }
    }
}

class Bank {
    constructor(eventBus) {
        this.balance = 0;
        this.eventBus = eventBus;
        this.eventBus.subscribe('deposit', this.deposit.bind(this));
        this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
    }

    deposit(amount) {
        this.balance += amount;
        console.log(`Deposited ${amount}, new balance is ${this.balance}`);
        this.eventBus.emit('balanceChanged', { balance: this.balance });
    }

    withdraw(amount) {
        if (amount > this.balance) {
            console.log('Insufficient funds');
            return;
        }
        this.balance -= amount;
        console.log(`Withdrew ${amount}, new balance is ${this.balance}`);
        this.eventBus.emit('balanceChanged', { balance: this.balance });
    }
}

class Market {
    constructor(eventBus) {
        this.prices = { apple: 1, banana: 2 };
        this.eventBus = eventBus;
        this.eventBus.subscribe('sell', this.sell.bind(this));
    }

    sell(item, quantity) {
        const price = this.prices[item];
        if (!price) {
            console.log('Item not available');
            return;
        }
        const total = price * quantity;
        console.log(`Sold ${quantity} ${item} for ${total}`);
        this.eventBus.emit('sellCompleted', { item, quantity, total });
    }
}

class Inventory {
    constructor(eventBus) {
        this.items = { apple: 0, banana: 0 };
        this.eventBus = eventBus;
        this.eventBus.subscribe('buy', this.buy.bind(this));
        this.eventBus.subscribe('sellCompleted', this.sellCompleted.bind(this));
    }

    buy(item, quantity) {
        console.log(`Buying ${quantity} ${item}`);
        this.eventBus.emit('sell', { item, quantity });
    }

    sellCompleted(data) {
        this.items[data.item] = (this.items[data.item] || 0) + data.quantity;
        console.log(`Added ${data.quantity} ${data.item} to inventory, new stock is ${this.items[data.item]}`);
    }
}

