class Bank {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(prices) {
        this.prices = prices; // { item: price }
    }

    getPrice(item) {
        return this.prices[item] || null;
    }

    updatePrice(item, newPrice) {
        if (newPrice >= 0) {
            this.prices[item] = newPrice;
            return true;
        }
        return false;
    }
}

class Inventory {
    constructor() {
        this.items = {}; // { item: quantity }
    }

    addItem(item, quantity = 1) {
        if (quantity > 0) {
            this.items[item] = (this.items[item] || 0) + quantity;
            return true;
        }
        return false;
    }

    removeItem(item, quantity = 1) {
        if (quantity > 0 && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    getInventory() {
        return this.items;
    }
}

