class Resource {
  constructor(name, initialAmount = 0) {
    this.name = name;
    this.amount = initialAmount;
  }

  add(amount) {
    this.amount += amount;
    return `Added ${amount} ${this.name}, total: ${this.amount}`;
  }

  consume(amount) {
    if (this.amount >= amount) {
      this.amount -= amount;
      return `Consumed ${amount} ${this.name}, remaining: ${this.amount}`;
    } else {
      throw new Error(`Not enough ${this.name} to consume`);
    }
  }

  getAmount() {
    return this.amount;
  }
}

class Economy {
  constructor() {
    this.resources = {};
  }

  addResource(name, initialAmount = 0) {
    this.resources[name] = new Resource(name, initialAmount);
    return `Added resource: ${name}`;
  }

  produceResource(resourceName, amount) {
    if (this.resources[resourceName]) {
      return this.resources[resourceName].add(amount);
    } else {
      throw new Error(`Resource ${resourceName} not found`);
    }
  }

  consumeResource(resourceName, amount) {
    if (this.resources[resourceName]) {
      return this.resources[resourceName].consume(amount);
    } else {
      throw new Error(`Resource ${resourceName} not found`);
    }
  }

  getResourceAmount(resourceName) {
    if (this.resources[resourceName]) {
      return this.resources[resourceName].getAmount();
    } else {
      throw new Error(`Resource ${resourceName} not found`);
    }
  }
}

