class Inventory {
    constructor() {
        this.items = {}; // { item: quantity }
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    hasItems(ingredients) {
        for (const [item, quantity] of Object.entries(ingredients)) {
            if (!this.items[item] || this.items[item] < quantity) {
                return false;
            }
        }
        return true;
    }

    getItems() {
        return this.items;
    }
}

class Crafting {
    constructor(inventory, recipes) {
        this.inventory = inventory;
        this.recipes = recipes; // { name: Recipe }
    }

    canCraft(recipeName) {
        const recipe = this.recipes[recipeName];
        if (!recipe) return false;
        return this.inventory.hasItems(recipe.getIngredients());
    }

    craft(recipeName) {
        const recipe = this.recipes[recipeName];
        if (!recipe || !this.canCraft(recipeName)) return false;
        for (const [item, quantity] of Object.entries(recipe.getIngredients())) {
            this.inventory.removeItem(item, quantity);
        }
        console.log(`Crafted ${recipe.getName()}`);
        return true;
    }

    listRecipes() {
        return Object.keys(this.recipes);
    }
}

