class Loot {
  constructor(name, value) {
    this.name = name;
    this.value = value;
  }

  static generateRandomLoot(rarityTable) {
    const roll = Math.random();
    let cumulativeProbability = 0;

    for (const { item, probability } of rarityTable) {
      cumulativeProbability += probability;
      if (roll < cumulativeProbability) {
        return new Loot(item, Math.floor(Math.random() * 100) + 1);
      }
    }

    return null;
  }
}

class RarityTable {
  constructor() {
    this.table = [];
