    this.eventBus = eventBus;
    this.eventBus.subscribe('harvestCrop', this.harvest.bind(this));
    this.crops = [];
  }

  plantCrop(type) {
    this.crops.push({ type, stage: 'planted' });
    console.log(`Planted a ${type} crop.`);
  }

  harvest(type) {
    this.crops = this.crops.filter(crop => crop.type !== type);
    console.log(`Harvested all ${type} crops.`);
    this.eventBus.emit('cropHarvested', type);
  }
}

class Crop {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('cropGrown', this.onGrow.bind(this));
    this.eventBus.subscribe('cropHarvested', this.onHarvest.bind(this));
    this.grownCrops = {};
  }

  onGrow(type) {
    if (!this.grownCrops[type]) {
      this.grownCrops[type] = 0;
    }
    this.grownCrops[type]++;
    console.log(`A ${type} crop has grown. Total grown: ${this.grownCrops[type]}`);
  }

  onHarvest(type) {
    if (this.grownCrops[type]) {
      this.grownCrops[type] = 0;
      console.log(`All ${type} crops have been harvested.`);
    }
  }
}

