    this.eventBus = eventBus;
    this.eventBus.subscribe('cropHarvested', this.sellCrop.bind(this));
    this.inventory = {};
  }

  sellCrop(type) {
    if (!this.inventory[type]) {
      this.inventory[type] = 0;
    }
    this.inventory[type]++;
    console.log(`Sold a batch of ${type} crops. Total in inventory: ${this.inventory[type]}`);
  }
}

