      'Common': 0.7,
      'Uncommon': 0.2,
      'Rare': 0.08,
      'Epic': 0.01,
      'Legendary': 0.01
    };
  }

  getRandomRarity() {
    const rand = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.table)) {
      cumulativeProbability += probability;
      if (rand < cumulativeProbability) {
        return rarity;
      }
    }

    return 'Common'; // Fallback to common
