class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount <= 0) throw new Error("Deposit amount must be positive");
    this.balance += amount;
  }

  withdraw(amount) {
    if (amount <= 0) throw new Error("Withdrawal amount must be positive");
    if (amount > this.balance) throw new Error("Insufficient funds");
    this.balance -= amount;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getPrices() {
    return { ...this.prices };
  }

  setPrice(item, price) {
    if (price < 0) throw new Error("Price must be non-negative");
    this.prices[item] = price;
  }

  getPrice(item) {
    return this.prices[item] !== undefined ? this.prices[item] : null;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity <= 0) throw new Error("Quantity must be positive");
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (quantity <= 0) throw new Error("Quantity must be positive");
    if (!this.items[item] || this.items[item] < quantity) {
      throw new Error("Insufficient quantity in inventory");
    }
    this.items[item] -= quantity;
    if (this.items[item] === 0) {
      delete this.items[item];
    }
  }

  getInventory() {
    return { ...this.items };
  }
}

