  constructor(skillName) {
    this.name = skillName;
    this.level = 1;
  }

  getLevel() {
    return this.level;
  }

  increaseLevel() {
    this.level += 1;
    console.log(`${this.name} level increased to ${this.level}`);
  }
}

// Experience System
class Experience {
  constructor(skill) {
    this.skill = skill;
    this.currentExperience = 0;
    this.experienceToNextLevel = 10;
  }

  addExperience(amount) {
    this.currentExperience += amount;
    console.log(`Added ${amount} experience. Current: ${this.currentExperience}`);

    while (this.currentExperience >= this.experienceToNextLevel) {
      this.skill.increaseLevel();
      this.currentExperience -= this.experienceToNextLevel;
      this.experienceToNextLevel *= 2; // Exponential growth for levels
    }
  }
}

// LevelUp System
class LevelUp {
  constructor(experience) {
    this.experience = experience;
  }

  levelUp(skillName) {
    const skill = new Skill(skillName);
    const experience = new Experience(skill);
    this.experience = experience;
    console.log(`LevelUp system initialized for ${skillName}`);
  }

  gainExperience(amount) {
    if (this.experience) {
      this.experience.addExperience(amount);
    } else {
      console.log('No skill initialized for experience gain.');
    }
  }
}

// Economy System
