  constructor() {
    this.balance = 100;
    this.prices = {
      skillA: 20,
      skillB: 30,
      skillC: 40
    };
  }

  getBalance() {
    return this.balance;
  }

  getSkillPrice(skillName) {
    return this.prices[skillName] || 0;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Debited ${amount}. New balance: ${this.balance}`);
      return true;
    } else {
      console.log('Insufficient balance for purchase.');
      return false;
    }
  }
}

