class FactionSystem {
    constructor() {
        this.factions = { 'Trader Guild': 0, 'Mercenaries': 0, 'Black Market': 0 };
    }

    changeFactionAlignment(faction, amount) {
        if (this.factions[faction] !== undefined) {
            this.factions[faction] += amount;
            console.log(`Alignment with ${faction} changed by ${amount}. Current alignment: ${this.factions[faction]}.`);
        } else {
