class GameCoordinator {
    constructor() {
        this.tradeSystem = new TradeSystem();
        this.reputationSystem = new ReputationSystem();
        this.factionSystem = new FactionSystem();
    }

    conductTrade(item, quantity, price) {
        this.tradeSystem.recordTrade(item, quantity, price);
        this.reputationSystem.modifyReputation(1); // Positive trade reputation
        this.factionSystem.changeFactionAlignment('Trader Guild', 1); // Align with Trader Guild
    }

    tradeWithMercenaries() {
        this.tradeSystem.recordTrade('Mercenary Service', 1, 100);
        this.reputationSystem.modifyReputation(-2); // Negative trade reputation
        this.factionSystem.changeFactionAlignment('Mercenaries', 2); // Align with Mercenaries
    }

    engageInBlackMarketTrade(item, quantity, price) {
        this.tradeSystem.recordTrade(item, quantity, price);
        this.reputationSystem.modifyReputation(-3); // Negative trade reputation
        this.factionSystem.changeFactionAlignment('Black Market', 3); // Align with Black Market
    }

    displayStatus() {
        console.log('Trade History:', this.tradeSystem.getTradeHistory());
        console.log('Reputation:', this.reputationSystem.getReputation());
        console.log('Faction Alignments:', this.factionSystem.getFactionAlignments());
    }
}

