  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Loot {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('generateLoot', this.generate.bind(this));
  }

  generate(itemType) {
    const rarity = this.eventBus.emit('determineRarity', itemType);
    const item = this.createItem(itemType, rarity);
    this.eventBus.emit('addItemToInventory', item);
  }

  createItem(itemType, rarity) {
    return { type: itemType, rarity };
  }
}

class RarityTable {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('determineRarity', this.determine.bind(this));
  }

  determine(itemType) {
    const rarities = ['Common', 'Uncommon', 'Rare', 'Epic', 'Legendary'];
    const rarityIndex = Math.floor(Math.random() * rarities.length);
    return rarities[rarityIndex];
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = [];
    this.eventBus.subscribe('addItemToInventory', this.addItem.bind(this));
  }

