class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredient1: quantity1, ingredient2: quantity2, ... }
  }

  canCraft(inventory) {
    for (let [ingredient, quantity] of Object.entries(this.ingredients)) {
      if (inventory[ingredient] < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(inventory) {
    for (let [ingredient, quantity] of Object.entries(this.ingredients)) {
      inventory[ingredient] -= quantity;
    }
    return true;
  }
}

class Crafting {
  constructor(recipes) {
    this.recipes = new Map(recipes.map(recipe => [recipe.name, recipe]));
  }

  getRecipe(name) {
    return this.recipes.get(name);
  }

  canCraft(name, inventory) {
    const recipe = this.getRecipe(name);
    return recipe ? recipe.canCraft(inventory) : false;
  }

  craft(name, inventory) {
    const recipe = this.getRecipe(name);
    return recipe ? recipe.craft(inventory) : false;
  }
}

class Economy {
  constructor(prices) {
    this.prices = new Map(prices.map(([item, price]) => [item, price]));
  }

  getPrice(item) {
    return this.prices.get(item) || 0;
  }

  debit(item, quantity, inventory, balance) {
    const price = this.getPrice(item);
    if (balance >= price * quantity) {
      inventory[item] = (inventory[item] || 0) + quantity;
      balance -= price * quantity;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor(items = {}) {
    this.items = items; // { item1: quantity1, item2: quantity2, ... }
  }

  getItemQuantity(item) {
    return this.items[item] || 0;
  }

  addItem(item, quantity) {
    this.items[item] = (this.items[item] || 0) + quantity;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item, quantity, balance) {
    return this.economy.debit(item, quantity, this.inventory.items, balance);
  }
}

