class Trade {
    constructor() {
        this.resources = { gold: 100, wood: 50, stone: 30 };
    }

    buy(resource, amount, pricePerUnit) {
        if (this.resources.gold >= pricePerUnit * amount) {
            this.resources.gold -= pricePerUnit * amount;
            this.resources[resource] = (this.resources[resource] || 0) + amount;
            return true;
        }
        return false;
    }

    sell(resource, amount, pricePerUnit) {
        if (this.resources[resource] >= amount) {
            this.resources[resource] -= amount;
            this.resources.gold += pricePerUnit * amount;
            return true;
        }
        return false;
    }

    getResources() {
        return { ...this.resources };
    }
}

class Reputation {
    constructor() {
        this.standing = 50; // Neutral standing
    }

    improve(amount) {
        this.standing = Math.min(100, this.standing + amount);
    }

    deteriorate(amount) {
        this.standing = Math.max(0, this.standing - amount);
    }

    getStanding() {
        return this.standing;
    }
}

class Faction {
    constructor() {
        this.allies = [];
        this.enemies = [];
    }

    declareWar(faction) {
        this.enemies.push(faction);
    }

    makePeace(faction) {
        this.enemies = this.enemies.filter(e => e !== faction);
        this.allies.push(faction);
    }

    getEnemies() {
        return [...this.enemies];
    }

    getAllies() {
        return [...this.allies];
    }
}

class GameCoordinator {
    constructor() {
        this.trade = new Trade();
        this.reputation = new Reputation();
        this.faction = new Faction();
    }

    tradeResources(resource, amount, pricePerUnit) {
        const success = this.trade.buy(resource, amount, pricePerUnit);
        if (success) {
            this.reputation.improve(5); // Good trade improves reputation
        } else {
            this.reputation.deteriorate(5); // Failed trade deteriorates reputation
        }
        return success;
    }

    sellResources(resource, amount, pricePerUnit) {
        const success = this.trade.sell(resource, amount, pricePerUnit);
        if (success) {
            this.reputation.improve(5); // Good trade improves reputation
        } else {
            this.reputation.deteriorate(5); // Failed trade deteriorates reputation
        }
        return success;
    }

    getTradeResources() {
        return this.trade.getResources();
    }

    getReputationStanding() {
        return this.reputation.getStanding();
    }

    declareWar(faction) {
        this.faction.declareWar(faction);
    }

    makePeace(faction) {
        this.faction.makePeace(faction);
    }

    getEnemies() {
        return this.faction.getEnemies();
    }

    getAllies() {
        return this.faction.getAllies();
    }
}

