        this.resourceSystem.addResource(type, amount);
    }

    removeResource(type, amount) {
        return this.resourceSystem.removeResource(type, amount);
    }

    hasResources(cost) {
        return this.resourceSystem.hasResources(cost);
    }

    getResources() {
        return this.resourceSystem.getResources();
    }
}

