  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Wallet System
class Wallet {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('purchase', this.handlePurchase.bind(this));
    this.eventBus.subscribe('refund', this.handleRefund.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited: $${amount}, New Balance: $${this.balance}`);
  }

  withdraw(amount) {
    if (amount > this.balance) {
      console.log(`Insufficient funds: $${amount} > $${this.balance}`);
      return false;
    }
    this.balance -= amount;
    console.log(`Withdrew: $${amount}, New Balance: $${this.balance}`);
    return true;
  }

  handlePurchase(amount) {
    if (this.withdraw(amount)) {
      this.eventBus.emit('purchaseSuccess', { amount });
    } else {
      this.eventBus.emit('purchaseFailure', { amount });
    }
  }

  handleRefund(amount) {
    this.deposit(amount);
    console.log(`Refunded: $${amount}`);
  }
}

// Shop System
class Shop {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.inventory = { 'sword': 50, 'potion': 10 };
    this.eventBus.subscribe('buy', this.handleBuy.bind(this));
  }

  listItems() {
    console.log('Shop Inventory:');
    for (const [item, price] of Object.entries(this.inventory)) {
      console.log(`${item}: $${price}`);
    }
  }

  handleBuy(item) {
    if (this.inventory[item]) {
      const price = this.inventory[item];
      console.log(`Purchasing ${item} for $${price}`);
      this.eventBus.emit('purchase', price);
    } else {
      console.log(`Item not found: ${item}`);
    }
  }
}

// Inventory System
class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('purchaseSuccess', this.handlePurchaseSuccess.bind(this));
    this.eventBus.subscribe('refund', this.handleRefund.bind(this));
  }

  addItem(item, quantity) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
    console.log(`Added ${quantity} ${item}(s) to inventory.`);
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      console.log(`Removed ${quantity} ${item}(s) from inventory.`);
      return true;
    }
    console.log(`Insufficient ${item}(s) in inventory.`);
    return false;
  }

  handlePurchaseSuccess({ amount, item }) {
    this.addItem(item, 1);
  }

  handleRefund({ item }) {
    this.removeItem(item, 1);
  }
}

