class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
    this.balance = 0;
  }

  purchase(item, quantity) {
    const price = this.pricing.getPrice(item);
    const demand = this.demand.getDemand(item);

    if (price <= 0 || demand <= 0 || quantity <= 0) {
      console.log(`Purchase failed: Invalid item or quantity.`);
      return false;
    }

    const totalCost = price * quantity;
    if (this.balance < totalCost) {
      console.log(`Purchase failed: Insufficient funds.`);
      return false;
    }

    this.balance -= totalCost;
    this.inventory[item] = (this.inventory[item] || 0) + quantity;
    console.log(`Purchased ${quantity} ${item}(s) for ${totalCost}.`);
    return true;
  }

  addToBalance(amount) {
    this.balance += amount;
    console.log(`Added ${amount} to balance. Current balance: ${this.balance}.`);
  }

  getInventory() {
    return this.inventory;
  }
}

