        this.items = {};
        this.eventBus = eventBus;
        this.eventBus.subscribe('itemAdded', this.addItem.bind(this));
        this.eventBus.subscribe('itemRemoved', this.removeItem.bind(this));
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
        console.log(`Added ${quantity} ${item}(s). Total: ${this.items[item]}`);
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            console.log(`Removed ${quantity} ${item}(s). Remaining: ${this.items[item] || 0}`);
        } else {
            console.log(`Not enough ${item}(s) to remove.`);
        }
    }

    getItems() {
        return this.items;
    }
}

// Recipe System
class Recipe {
    constructor(eventBus) {
        this.recipes = {};
        this.eventBus = eventBus;
        this.eventBus.subscribe('recipeAdded', this.addRecipe.bind(this));
        this.eventBus.subscribe('craftItem', this.craftItem.bind(this));
    }

    addRecipe(name, ingredients) {
        this.recipes[name] = ingredients;
        console.log(`Added recipe for ${name}:`, ingredients);
    }

    craftItem(name) {
        if (this.recipes[name]) {
            const ingredients = this.recipes[name];
            this.eventBus.emit('checkIngredients', { name, ingredients });
        } else {
            console.log(`No recipe found for ${name}.`);
        }
    }
}

// Crafting System
class Crafting {
    constructor(eventBus, inventory) {
        this.inventory = inventory;
        this.eventBus = eventBus;
        this.eventBus.subscribe('checkIngredients', this.checkIngredients.bind(this));
    }

    checkIngredients({ name, ingredients }) {
        let canCraft = true;
        for (const [item, quantity] of Object.entries(ingredients)) {
            if (this.inventory.getItems()[item] < quantity) {
                console.log(`Not enough ${item}(s) to craft ${name}.`);
                canCraft = false;
                break;
            }
        }
        if (canCraft) {
            for (const [item, quantity] of Object.entries(ingredients)) {
                this.inventory.removeItem(item, quantity);
            }
            this.inventory.addItem(name, 1);
            console.log(`Crafted ${name}.`);
        }
    }
}

