class LevelUp {
    constructor(skill, experience, levelThresholds) {
        this.skill = skill;
        this.experience = experience;
        this.levelThresholds = levelThresholds;
    }

    gainExperience(points) {
        this.experience.addPoints(points);
        this.checkLevelUp();
