class Inventory {
  constructor() {
    this.items = new Map();
  }

  addItem(item, quantity = 1) {
    this.items.set(item, (this.items.get(item) || 0) + quantity);
  }

  removeItem(item, quantity = 1) {
    if (this.items.has(item)) {
      const currentQuantity = this.items.get(item);
      if (currentQuantity > quantity) {
        this.items.set(item, currentQuantity - quantity);
      } else {
        this.items.delete(item);
      }
    }
  }

  hasItem(item, quantity = 1) {
    return (this.items.get(item) || 0) >= quantity;
  }

  getItemCount(item) {
    return this.items.get(item) || 0;
  }
}

class Recipe {
  constructor(inputs, output) {
    this.inputs = inputs; // Map of item: quantity
    this.output = output; // { item: quantity }
  }

  canCraft(inventory) {
    for (const [item, quantity] of this.inputs) {
      if (!inventory.hasItem(item, quantity)) {
        return false;
      }
    }
    return true;
  }

  craft(inventory) {
    for (const [item, quantity] of this.inputs) {
      inventory.removeItem(item, quantity);
    }
    inventory.addItem(this.output.item, this.output.quantity);
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes; // Array of Recipe instances
  }

  listRecipes() {
    return this.recipes.map(recipe => {
      const inputs = Array.from(recipe.inputs).map(([item, quantity]) => `${item}: ${quantity}`).join(', ');
      return `${inputs} -> ${recipe.output.item}: ${recipe.output.quantity}`;
    });
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.output.item === recipeName);
    if (recipe && recipe.canCraft(this.inventory)) {
      recipe.craft(this.inventory);
      console.log(`Crafted ${recipe.output.item}`);
      return true;
    } else {
      console.log(`Cannot craft ${recipeName}`);
      return false;
    }
  }
}

