        recipe.ingredients.forEach(ingredient => {
          this.eventBus.inventory.removeItem(ingredient.name, ingredient.quantity);
        });
        this.eventBus.inventory.addItem(recipe.result.name, recipe.result.quantity);
        console.log(`Crafted: ${recipe.result.name}`);
      } else {
        console.log(`Cannot craft ${recipe.result.name}: missing ingredients`);
      }
    } else {
      console.log(`No recipe found for ${itemName}`);
    }
  }
}

