class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  getCurrentPrice(demandLevel) {
    // Simple pricing model: price increases with demand
    return this.basePrice + (demandLevel * 0.5);
  }
}

class Demand {
  constructor(initialDemand) {
    this.demand = initialDemand;
  }

  updateDemand(change) {
    this.demand += change;
    return this.demand;
  }

  getCurrentDemand() {
    return this.demand;
  }
}

class Store {
  constructor(pricingSystem, demandSystem) {
    this.pricingSystem = pricingSystem;
    this.demandSystem = demandSystem;
  }

  sellItem() {
    // Each sale increases demand slightly
    const newDemand = this.demandSystem.updateDemand(1);
    const currentPrice = this.pricingSystem.getCurrentPrice(newDemand);
    console.log(`Sold item at price: $${currentPrice.toFixed(2)}, New demand: ${newDemand}`);
    return currentPrice;
  }
}

// Top-level coordinator to wire the systems together
function runGame() {
  const pricing = new Pricing(10.0); // Base price of $10.00
  const demand = new Demand(50); // Initial demand of 50
  const store = new Store(pricing, demand);

  // Simulate selling items
  store.sellItem(); // Initial sale
  store.sellItem(); // Second sale, demand increases
  store.sellItem(); // Third sale, demand increases further
}

// Run the demo
runGame();
