// Crafting System
class Crafting {
    constructor() {
        this.craftingTable = new Map();
    }

    registerRecipe(recipe) {
        this.craftingTable.set(recipe.name, recipe);
    }

    craft(recipeName, inventory) {
        const recipe = this.craftingTable.get(recipeName);
        if (!recipe) return null;

        for (const [item, count] of recipe.ingredients) {
            if (!inventory.has(item, count)) return null;
        }

        for (const [item, count] of recipe.ingredients) {
            inventory.remove(item, count);
        }

        inventory.add(recipe.output, 1);
        return recipe.output;
    }
}

// Recipe System
class Recipe {
    constructor(name, ingredients, output) {
        this.name = name;
        this.ingredients = ingredients;
        this.output = output;
    }
}

// Inventory System
class Inventory {
    constructor() {
        this.items = new Map();
    }

    add(item, count) {
        this.items.set(item, (this.items.get(item) || 0) + count);
    }

    remove(item, count) {
        if (this.has(item, count)) {
            this.items.set(item, this.items.get(item) - count);
        }
    }

    has(item, count) {
        return (this.items.get(item) || 0) >= count;
    }

    list() {
        return this.items;
    }
}

// Top-level coordinator
class GameCoordinator {
    constructor() {
        this.crafting = new Crafting();
        this.inventory = new Inventory();
    }

    registerRecipe(recipe) {
        this.crafting.registerRecipe(recipe);
    }

    craftRecipe(recipeName) {
        const result = this.crafting.craft(recipeName, this.inventory);
        return result;
    }

    addToInventory(item, count) {
        this.inventory.add(item, count);
    }

    getInventory() {
        return this.inventory.list();
    }
}

