      return false;
    }

    if (this.inventorySystem.hasIngredients(recipe.ingredients)) {
      this.inventorySystem.removeIngredients(recipe.ingredients);
      this.inventorySystem.addItem(itemName);
      console.log(`Crafted ${itemName} successfully.`);
      return true;
    } else {
