class Experience {
  constructor() {
    this.points = 0;
  }

  getPoints() {
    return this.points;
  }

  addPoints(amount) {
    this.points += amount;
  }

  isLevelUpRequired(currentLevel, pointsRequiredForNextLevel) {
    return this.points >= pointsRequiredForNextLevel;
  }
}

class LevelUp {
  constructor(skill, experience) {
    this.skill = skill;
    this.experience = experience;
  }

  levelUp(pointsRequiredForNextLevel) {
    if (this.experience.isLevelUpRequired(this.skill.getLevel(), pointsRequiredForNextLevel)) {
      this.skill.increaseLevel();
      this.experience.addPoints(-pointsRequiredForNextLevel); // Deduct points used for level up
      return true;
    }
    return false;
  }
}

// Coordinator to wire the systems together
