    this.experience.addPoints(points);
    if (this.levelUpSystem.levelUp(10)) { // Assuming 10 points required for each level up
      console.log(`Levelled up! New level: ${this.skill.getLevel()}`);
    } else {
      console.log(`Experience points: ${this.experience.getPoints()}`);
    }
  }
}

