class Loot {
  constructor(name, rarity, value) {
    this.name = name;
    this.rarity = rarity;
    this.value = value;
  }

  toString() {
    return `${this.name} (${this.rarity}) - Value: ${this.value}`;
  }
}

class RarityTable {
  constructor() {
    this.table = {
      'Common': 0.6,
      'Uncommon': 0.3,
      'Rare': 0.09,
      'Epic': 0.01
    };
  }

  getRandomLoot() {
    const total = Object.values(this.table).reduce((acc, prob) => acc + prob, 0);
    const rand = Math.random() * total;
    let cumulative = 0;

    for (const [rarity, prob] of Object.entries(this.table)) {
      cumulative += prob;
      if (rand < cumulative) {
        return new Loot(`Loot of ${rarity}`, rarity, this.calculateValue(rarity));
      }
    }
  }

  calculateValue(rarity) {
    switch (rarity) {
      case 'Common': return Math.floor(Math.random() * 10) + 1;
      case 'Uncommon': return Math.floor(Math.random() * 50) + 10;
      case 'Rare': return Math.floor(Math.random() * 100) + 50;
      case 'Epic': return Math.floor(Math.random() * 500) + 100;
      default: return 0;
    }
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(loot) {
    this.items.push(loot);
    console.log(`Added to inventory: ${loot}`);
  }

  listItems() {
    console.log('Inventory Contents:');
    this.items.forEach(item => console.log(item.toString()));
  }
}

