        if (amount > this.balance) {
            console.log(`Insufficient funds to withdraw ${amount}`);
            return false;
        }
        this.balance -= amount;
        console.log(`Withdrew ${amount}, new balance is ${this.balance}`);
        return true;
    }

    getBalance() {
        return this.balance;
    }
