        this.prices = prices;
    }

    buy(item) {
        if (!this.prices[item]) {
            console.log(`Item ${item} is not available in the market`);
            return false;
        }
        return this.prices[item];
    }

    getPrices() {
        return { ...this.prices };
    }
}

