    };
  }

  getItemPrice(item) {
    return this.items[item]?.price || 0;
  }

  purchaseItem(item, economy) {
    const price = this.getItemPrice(item);
    if (price > 0 && economy.withdraw(price)) {
      this.items[item].stock -= 1;
      return true;
    }
    return false;
  }

  getStock(item) {
    return this.items[item]?.stock || 0;
  }
}

