class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || null;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      if (this.items[item]) {
        this.items[item] += quantity;
      } else {
        this.items[item] = quantity;
      }
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Store {
  constructor(bank, market, inventory) {
    this.bank = bank;
    this.market = market;
    this.inventory = inventory;
  }

  purchase(item, quantity) {
    const price = this.market.getPrice(item);
    if (price !== null) {
      const totalCost = price * quantity;
      if (this.bank.withdraw(totalCost)) {
        this.inventory.addItem(item, quantity);
        return true;
      }
    }
    return false;
  }
}

