class Bank {
  constructor(eventBus) {
    this.balance = 0;
    this.eventBus = eventBus;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      this.eventBus.emit('balanceChanged', this.balance);
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      this.eventBus.emit('balanceChanged', this.balance);
    }
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(eventBus) {
    this.prices = { apple: 10, banana: 5 };
    this.eventBus = eventBus;
    this.eventBus.subscribe('buy', this.buy.bind(this));
  }

  buy(item, quantity) {
    const price = this.prices[item];
    if (price !== undefined && quantity > 0) {
      const totalCost = price * quantity;
      this.eventBus.emit('sell', { item, quantity, totalCost });
    }
  }

  getPrices() {
    return this.prices;
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = { apple: 0, banana: 0 };
    this.eventBus = eventBus;
    this.eventBus.subscribe('sell', this.sell.bind(this));
  }

  sell(data) {
    const { item, quantity } = data;
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      this.eventBus.emit('inventoryChanged', this.items);
    }
  }

  getInventory() {
    return this.items;
  }
}

