class RarityTable {
  constructor() {
    this.rarityLevels = {
      Common: 70,
      Uncommon: 20,
      Rare: 8,
      Epic: 2
    };
  }

  getRandomRarity() {
    const total = Object.values(this.rarityLevels).reduce((sum, value) => sum + value, 0);
    const random = Math.floor(Math.random() * total);
    let cumulative = 0;

    for (const [rarity, chance] of Object.entries(this.rarityLevels)) {
      cumulative += chance;
      if (random < cumulative) {
        return rarity;
      }
    }
  }
