  canCraft() {
    for (const [item, quantity] of Object.entries(this.recipe)) {
      if (this.inventory.removeItem(item, quantity) === false) {
        return false;
      }
    }
    return true;
  }

  craft() {
    if (this.canCraft()) {
      this.inventory.addItem('crafted_item', 1);
      return true;
    }
    return false;
  }
}

