class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(initialStock = {}) {
    this.stock = initialStock;
  }

  buy(item, amount, pricePerUnit) {
    if (this.stock[item] >= amount && pricePerUnit > 0) {
      this.stock[item] -= amount;
      return amount * pricePerUnit;
    }
    return 0;
  }

  sell(item, amount, pricePerUnit) {
    if (amount > 0 && pricePerUnit > 0) {
      this.stock[item] = (this.stock[item] || 0) + amount;
      return amount * pricePerUnit;
    }
    return 0;
  }

  getStock() {
    return { ...this.stock };
  }
}

class Inventory {
  constructor(initialItems = {}) {
    this.items = initialItems;
  }

  addItem(item, amount) {
    if (amount > 0) {
      this.items[item] = (this.items[item] || 0) + amount;
      return true;
    }
    return false;
  }

  removeItem(item, amount) {
    if (this.items[item] >= amount) {
      this.items[item] -= amount;
      return true;
    }
    return false;
  }

  getItems() {
    return { ...this.items };
  }
}

class GameCoordinator {
  constructor() {
    this.bank = new Bank(1000);
    this.market = new Market({ apples: 10, bananas: 5 });
    this.inventory = new Inventory();
  }

  buyFromMarket(item, amount, pricePerUnit) {
    const cost = this.market.buy(item, amount, pricePerUnit);
    if (this.bank.withdraw(cost)) {
      this.inventory.addItem(item, amount);
      return true;
    }
    return false;
  }

  sellToMarket(item, amount, pricePerUnit) {
    const revenue = this.market.sell(item, amount, pricePerUnit);
    if (this.inventory.removeItem(item, amount)) {
      this.bank.deposit(revenue);
      return true;
    }
    return false;
  }

  report() {
    console.log('Bank Balance:', this.bank.getBalance());
    console.log('Market Stock:', this.market.getStock());
    console.log('Inventory Items:', this.inventory.getItems());
  }
}

