class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  calculatePrice(quantity) {
    return this.basePrice * quantity;
  }
}

// Demand System
class Demand {
  constructor(initialDemand) {
    this.currentDemand = initialDemand;
  }

  adjustDemand(change) {
    this.currentDemand += change;
    return this.currentDemand;
  }

  getCurrentDemand() {
    return this.currentDemand;
  }
}

// Store System
class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sell(quantity) {
    if (this.demand.getCurrentDemand() >= quantity) {
      const totalCost = this.pricing.calculatePrice(quantity);
      this.demand.adjustDemand(-quantity);
      return totalCost;
    } else {
      console.log("Not enough demand to sell that quantity.");
      return null;
    }
  }

  restock(quantity) {
    this.demand.adjustDemand(quantity);
  }
}

// Top-level Coordinator
class GameCoordinator {
  constructor() {
    const pricing = new Pricing(10); // Base price of $10
    const demand = new Demand(50); // Initial demand of 50
    this.store = new Store(pricing, demand);
  }

  simulateSales() {
    console.log("Initial demand:", this.store.demand.getCurrentDemand());
    console.log("Selling 10 units for $", this.store.sell(10));
    console.log("Remaining demand:", this.store.demand.getCurrentDemand());
    console.log("Restocking 20 units");
    this.store.restock(20);
    console.log("New demand:", this.store.demand.getCurrentDemand());
    console.log("Selling 15 units for $", this.store.sell(15));
    console.log("Final demand:", this.store.demand.getCurrentDemand());
  }
}

