    this.economy = economy;
    this.items = new Map([
      ['sword', { price: 50, quantity: 10 }],
      ['potion', { price: 20, quantity: 50 }]
    ]);
  }

  listItems() {
    return Array.from(this.items.entries());
  }

  buyItem(itemName) {
    const item = this.items.get(itemName);
    if (item && item.quantity > 0) {
      if (this.economy.subtractFunds(item.price)) {
        item.quantity -= 1;
        return true;
      }
    }
    return false;
  }
}

class Inventory {
