  addItem(itemName) {
    if (this.items.has(itemName)) {
      this.items.set(itemName, this.items.get(itemName) + 1);
    } else {
      this.items.set(itemName, 1);
    }
  }

  getInventory() {
    return Array.from(this.items.entries());
  }
}

