// Economy system
class Economy {
  constructor() {
    this.balance = 1000; // Initial balance
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
  }

  credit(amount) {
    this.balance += amount;
  }
}

// RarityTable system
class RarityTable {
  constructor() {
    this.rarityLevels = {
      COMMON: 70,
      UNCOMMON: 20,
      RARE: 5,
      LEGENDARY: 2,
      MYTHIC: 1
    };
  }

  getRandomItem() {
    const rarityLevels = Object.keys(this.rarityLevels);
    let randomValue = Math.floor(Math.random() * 100) + 1;
    let cumulativeProbability = 0;

    for (let i = 0; i < rarityLevels.length; i++) {
      cumulativeProbability += this.rarityLevels[rarityLevels[i]];
      if (randomValue <= cumulativeProbability) {
        return rarityLevels[i];
      }
    }

    return rarityLevels[rarityLevels.length - 1];
  }
}

// Inventory system
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
  }

  getInventory() {
    return this.items;
  }
}

// Store system
class Store {
  constructor(economy, rarityTable, inventory) {
    this.economy = economy;
    this.rarityTable = rarityTable;
    this.inventory = inventory;
    this.prices = {
      COMMON: 10,
      UNCOMMON: 50,
      RARE: 100,
      LEGENDARY: 500,
      MYTHIC: 1000
    };
  }

  purchaseItem() {
    const item = this.rarityTable.getRandomItem();
    const price = this.prices[item];

    if (price > this.economy.getBalance()) {
      console.log("Purchase failed: Insufficient funds");
      return;
    }

    this.economy.debit(price);
    this.inventory.addItem(item);
    console.log(`Purchased ${item} for ${price}. New balance: ${this.economy.getBalance()}`);
  }
}

