        console.log(`Quest ${questId} started.`);
        // Simulate quest completion after a delay
        setTimeout(() => {
            this.eventBus.emit('questCompleted', { questId });
        }, 2000);
    }

    onQuestCompleted(data) {
        console.log(`Quest ${data.questId} completed.`);
    }
}

// Reward System
