    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('questCompleted', this.onQuestCompleted.bind(this));
    }

    onQuestCompleted(data) {
        console.log(`Rewarding player for completing quest ${data.questId}.`);
