    this.tradeSystem = tradeSystem;
    this.reputationSystem = reputationSystem;
  }

  performTrade(resource, amount, targetFaction) {
    if (this.tradeSystem.trade(resource, amount, targetFaction)) {
      this.reputationSystem.modifyReputation(targetFaction, 1);
    }
  }

