class RarityTable {
  constructor() {
    this.rarityLevels = {
      common: 0.5,
      uncommon: 0.3,
      rare: 0.15,
      legendary: 0.05
    };
  }

  getRandomLoot() {
    const rarities = Object.keys(this.rarityLevels);
    const probabilities = Object.values(this.rarityLevels);
    const random = Math.random();

    let cumulativeProbability = 0;
    for (let i = 0; i < probabilities.length; i++) {
      cumulativeProbability += probabilities[i];
      if (random <= cumulativeProbability) {
        return new Loot(`Item-${i + 1}`, rarities[i]);
      }
    }
    return new Loot('Unknown', 'common');
  }
}

