    if (this.quests.length > 0) {
      this.currentQuest = this.quests.shift();
      console.log(`New quest started: ${this.currentQuest.description}`);
      return true;
    }
    console.log("No more quests available.");
    return false;
  }

  completeCurrentQuest() {
    if (this.currentQuest) {
      console.log(`Quest completed: ${this.currentQuest.description}`);
      return this.currentQuest.rewardId;
    }
    console.log("No quest to complete.");
    return null;
  }
}

class Reward {
  constructor() {
    this.rewards = [
      { id: 1, description: "10 gold" },
      { id: 2, description: "Magic Sword" }
    ];
  }

  claimReward(rewardId) {
    const reward = this.rewards.find(r => r.id === rewardId);
    if (reward) {
      console.log(`Reward claimed: ${reward.description}`);
      return true;
    }
    console.log("Invalid reward ID.");
    return false;
  }
}

class Inventory {
