    console.log("Starting game...");
    this.questSystem.startNextQuest();
  }

  completeQuest() {
    const rewardId = this.questSystem.completeCurrentQuest();
    if (rewardId !== null) {
      if (this.rewardSystem.claimReward(rewardId)) {
        const reward = this.rewardSystem.rewards.find(r => r.id === rewardId);
