class Hunger {
  constructor(maxHunger = 100) {
    this.currentHunger = 0;
    this.maxHunger = maxHunger;
  }

  eat(amount = 20) {
    this.currentHunger = Math.max(0, this.currentHunger - amount);
    return this.currentHunger;
  }

  getHungerLevel() {
    return this.currentHunger;
  }

  update() {
    this.currentHunger = Math.min(this.maxHunger, this.currentHunger + 1);
    return this.currentHunger;
  }
}

class Energy {
  constructor(maxEnergy = 100) {
    this.currentEnergy = maxEnergy;
    this.maxEnergy = maxEnergy;
  }

  rest(amount = 10) {
    this.currentEnergy = Math.min(this.maxEnergy, this.currentEnergy + amount);
    return this.currentEnergy;
  }

  expend(amount = 10) {
    this.currentEnergy = Math.max(0, this.currentEnergy - amount);
    return this.currentEnergy;
  }

  getEnergyLevel() {
    return this.currentEnergy;
  }

  update() {
    this.currentEnergy = Math.max(0, this.currentEnergy - 1);
    return this.currentEnergy;
  }
}

class Clock {
  constructor() {
    this.time = 0;
  }

  tick() {
    this.time += 1;
    return this.time;
  }

  getTime() {
    return this.time;
  }
}

class GameCoordinator {
  constructor() {
    this.hunger = new Hunger();
    this.energy = new Energy();
    this.clock = new Clock();
  }

  tick() {
    this.clock.tick();
    this.hunger.update();
    this.energy.update();

    if (this.hunger.getHungerLevel() >= 90) {
      console.log(`Time: ${this.clock.getTime()}, You are very hungry!`);
    }

    if (this.energy.getEnergyLevel() <= 10) {
