    console.log(`Time: ${this.clock.getTime()}, Hunger: ${this.hunger.getHungerLevel()}, Energy: ${this.energy.getEnergyLevel()}`);
  }

  eat(amount) {
    this.hunger.eat(amount);
  }

  rest(amount) {
    this.energy.rest(amount);
  }

  expendEnergy(amount) {
    this.energy.expend(amount);
  }
}

