  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('priceUpdated', this.onPriceChange.bind(this));
    this.demandLevel = 100; // Initial demand level
  }

  onPriceChange(price) {
    if (price > 50) {
      this.demandLevel -= 10;
    } else {
      this.demandLevel += 10;
    }
    console.log(`Demand: Demand level adjusted to ${this.demandLevel}`);
    this.eventBus.emit('demandUpdated', this.demandLevel);
  }
}

