    this.eventBus = eventBus;
    this.eventBus.subscribe('demandUpdated', this.onDemandChange.bind(this));
    this.stock = 100; // Initial stock level
  }

  onDemandChange(demandLevel) {
    if (demandLevel > 100) {
      this.stock += 10;
    } else if (demandLevel < 100) {
      this.stock -= 10;
    }
    console.log(`Store: Stock level adjusted to ${this.stock}`);
  }

  restock() {
    this.stock += 50;
    console.log(`Store: Restocked, new stock level is ${this.stock}`);
  }
}

