    addItem(item, rarity) {
        this.items.push({ item, rarity });
    }

    getRandomLoot() {
        if (this.items.length === 0) return null;
        const randomIndex = Math.floor(Math.random() * this.items.length);
        return this.items[randomIndex];
    }
}

// RarityTable System
class RarityTable {
    constructor() {
        this.table = {
            common: 0.6,
            uncommon: 0.3,
            rare: 0.09,
            legendary: 0.01
        };
    }

    getRandomRarity() {
        const randomValue = Math.random();
        let cumulativeProbability = 0;

        for (const [rarity, probability] of Object.entries(this.table)) {
            cumulativeProbability += probability;
            if (randomValue <= cumulativeProbability) {
                return rarity;
            }
        }

        return null;
    }
}

// Inventory System
class Inventory {
    constructor() {
        this.items = [];
    }

    addItem(item) {
        this.items.push(item);
    }

    displayItems() {
        console.log("Inventory:");
        this.items.forEach((item, index) => {
            console.log(`${index + 1}. ${item.item} (${item.rarity})`);
        });
    }
}

// Coordinator to wire the systems together
class GameCoordinator {
    constructor() {
        this.lootSystem = new Loot();
        this.rarityTable = new RarityTable();
        this.inventorySystem = new Inventory();
    }

    setupLoot() {
        this.lootSystem.addItem("Potion", "common");
        this.lootSystem.addItem("Sword", "uncommon");
        this.lootSystem.addItem("Shield", "rare");
        this.lootSystem.addItem("Dragon Scale", "legendary");
    }

    generateLoot() {
        const rarity = this.rarityTable.getRandomRarity();
        const loot = this.lootSystem.getRandomLoot();

        if (rarity && loot && loot.rarity === rarity) {
            this.inventorySystem.addItem(loot);
            console.log(`Found: ${loot.item} (${loot.rarity})`);
        } else {
            console.log("No loot found.");
        }
    }

    runDemo() {
        this.setupLoot();
        this.generateLoot();
        this.inventorySystem.displayItems();
    }
}

// Runnable demo
const game = new GameCoordinator();
game.runDemo();
