    constructor() {
        this.prices = {
            apple: 10,
            banana: 5,
            carrot: 3
        };
    }

    getPrices() {
        return { ...this.prices };
    }

    buy(item, quantity, bank) {
        const price = this.prices[item];
        if (price && quantity > 0) {
            const totalCost = price * quantity;
            if (bank.withdraw(totalCost)) {
                console.log(`Bought ${quantity} ${item}(s). Total cost: ${totalCost}`);
                return true;
            } else {
                console.log('Transaction failed due to insufficient funds.');
                return false;
