    const random = Math.random() * 100;
    if (random < this.rarityWeights.common) {
      return 'common';
    } else if (random < this.rarityWeights.common + this.rarityWeights.uncommon) {
      return 'uncommon';
    } else {
      return 'rare';
    }
  }
}

