// Crafting class to handle crafting recipes and outcomes
class Crafting {
  constructor(inventory, economy) {
    this.inventory = inventory;
    this.economy = economy;
    this.recipes = new Map();
  }

  addRecipe(recipe) {
    this.recipes.set(recipe.output, recipe);
  }

  canCraft(output) {
    const recipe = this.recipes.get(output);
    if (recipe) {
      for (const [item, quantity] of recipe.inputs) {
        if (this.inventory.getItemCount(item) < quantity) {
          return false;
        }
      }
      return true;
    }
    return false;
  }

  craft(output) {
    const recipe = this.recipes.get(output);
    if (recipe && this.canCraft(output)) {
      for (const [item, quantity] of recipe.inputs) {
        this.inventory.items.set(item, this.inventory.items.get(item) - quantity);
      }
      this.inventory.addItem(recipe.output);
      console.log(`Crafted ${output}.`);
      return true;
    }
    console.log(`Cannot craft ${output}.`);
    return false;
  }
}

