        this.rewards = [];
    }

    addReward(reward) {
        this.rewards.push(reward);
        console.log(`Reward added: ${reward}`);
    }

    grantReward(quest) {
        const reward = this.rewards.shift();
        if (reward) {
            console.log(`Reward granted for quest ${quest}: ${reward}`);
            return reward;
        }
        console.log(`No rewards available for quest ${quest}`);
        return null;
    }
}

class InventorySystem {
    constructor() {
        this.items = [];
    }

    addItem(item) {
        this.items.push(item);
        console.log(`Item added to inventory: ${item}`);
    }

    useItem(item) {
        const index = this.items.indexOf(item);
        if (index !== -1) {
            this.items.splice(index, 1);
            console.log(`Item used: ${item}`);
            return item;
        }
        console.log(`Item not found in inventory: ${item}`);
        return null;
    }
}

class GameCoordinator {
    constructor() {
        this.questSystem = new QuestSystem();
        this.rewardSystem = new RewardSystem();
        this.inventorySystem = new InventorySystem();
    }

    startQuest(quest, reward) {
        this.questSystem.addQuest(quest);
        this.rewardSystem.addReward(reward);
    }

    completeQuestAndGrantReward(quest) {
        const completedQuest = this.questSystem.completeQuest(quest);
        if (completedQuest) {
            const reward = this.rewardSystem.grantReward(completedQuest);
            if (reward) {
                this.inventorySystem.addItem(reward);
            }
        }
    }

    useInventoryItem(item) {
        this.inventorySystem.useItem(item);
    }
}

