    this.items = {};
  }

  getInventory() {
    return { ...this.items };
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (this.items[item] && quantity > 0 && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }
}

class GameCoordinator {
  constructor() {
    this.wallet = new Wallet(100);
    this.shop = new Shop();
    this.inventory = new Inventory();
  }

  buyItem(itemName) {
    const price = this.shop.getItemPrice(itemName);
    if (price !== null && this.wallet.withdraw(price)) {
      this.inventory.addItem(itemName, 1);
      return true;
    }
    return false;
  }

  sellItem(itemName) {
    const quantity = this.inventory.removeItem(itemName, 1);
    if (quantity) {
      const price = this.shop.getItemPrice(itemName);
      if (price !== null) {
        this.wallet.deposit(price);
        return true;
      }
    }
    return false;
  }

  getWalletBalance() {
    return this.wallet.getBalance();
  }

  getInventory() {
    return this.inventory.getInventory();
  }

  getShopItems() {
    return this.shop.getItems();
  }
}

