class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }
}

class Trade {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('resourceTraded', this.handleResourceTraded.bind(this));
  }

  tradeResource(resource, amount, targetFaction) {
    console.log(`Trading ${amount} of ${resource} with ${targetFaction}`);
    this.eventBus.emit('resourceTraded', { resource, amount, targetFaction });
  }

  handleResourceTraded(data) {
    console.log(`Trade completed for ${data.amount} of ${data.resource} with ${data.targetFaction}`);
  }
}

class Reputation {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('resourceTraded', this.handleResourceTraded.bind(this));
    this.reputations = {};
  }

  handleResourceTraded(data) {
    if (!this.reputations[data.targetFaction]) {
      this.reputations[data.targetFaction] = 0;
    }
    this.reputations[data.targetFaction] += 5;
    console.log(`Reputation with ${data.targetFaction} increased to ${this.reputations[data.targetFaction]}`);
  }
}

class Faction {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('resourceTraded', this.handleResourceTraded.bind(this));
    this.resources = {};
  }

  handleResourceTraded(data) {
    if (!this.resources[data.resource]) {
      this.resources[data.resource] = 0;
    }
    this.resources[data.resource] += data.amount;
    console.log(`Received ${data.amount} of ${data.resource}. Total: ${this.resources[data.resource]}`);
  }
}

