class ReputationSystem {
  constructor() {
    this.reputations = {};
  }

  updateReputation(faction, points) {
    if (!this.reputations[faction]) {
      this.reputations[faction] = 0;
    }
    this.reputations[faction] += points;
    console.log(`Reputation updated for ${faction}: ${this.reputations[faction]} points`);
  }

  getReputation(faction) {
    return this.reputations[faction] || 0;
  }
}

class FactionSystem {
  constructor() {
    this.factions = {};
  }

  addFaction(faction) {
    if (!this.factions[faction]) {
      this.factions[faction] = { resources: {} };
    }
    console.log(`Faction added: ${faction}`);
  }

  updateResource(faction, resource, quantity) {
    if (!this.factions[faction]) {
      this.addFaction(faction);
    }
    if (!this.factions[faction].resources[resource]) {
      this.factions[faction].resources[resource] = 0;
    }
    this.factions[faction].resources[resource] += quantity;
    console.log(`Resource updated for ${faction}: ${resource} - ${this.factions[faction].resources[resource]}`);
  }

  getResources(faction) {
    return this.factions[faction]?.resources || {};
  }
}

class GameCoordinator {
  constructor() {
    this.tradeSystem = new TradeSystem();
    this.reputationSystem = new ReputationSystem();
    this.factionSystem = new FactionSystem();
  }

  performTrade(faction, resource, quantity) {
    this.tradeSystem.recordTrade(resource, quantity, faction);
    this.factionSystem.updateResource(faction, resource, quantity);
    this.reputationSystem.updateReputation(faction, quantity);
  }

  getTransactionHistory() {
    return this.tradeSystem.getTransactionHistory();
  }

  getReputation(faction) {
    return this.reputationSystem.getReputation(faction);
  }

  getResources(faction) {
    return this.factionSystem.getResources(faction);
  }
}

