// Recipe system
class Recipe {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.recipes = {};

        this.eventBus.subscribe('craft', this.handleCraft.bind(this));
    }

    addRecipe(item, ingredients) {
        this.recipes[item] = ingredients;
    }

    handleCraft(item) {
        const ingredients = this.recipes[item];
        if (ingredients) {
            this.eventBus.emit('checkIngredients', { item, ingredients });
        } else {
            console.log(`Recipe for ${item} not found.`);
        }
    }
}

// Inventory system
class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = {};

        this.eventBus.subscribe('checkIngredients', this.checkIngredients.bind(this));
        this.eventBus.subscribe('removeIngredients', this.removeIngredients.bind(this));
    }

    addItem(item, amount) {
        if (!this.items[item]) {
            this.items[item] = 0;
        }
        this.items[item] += amount;
    }

    checkIngredients({ item, ingredients }) {
        let canCraft = true;
        for (const ingredient in ingredients) {
            if (this.items[ingredient] < ingredients[ingredient]) {
                canCraft = false;
                break;
            }
        }
        if (canCraft) {
            this.eventBus.emit('removeIngredients', ingredients);
            console.log(`Crafted ${item}`);
        } else {
            console.log(`Not enough ingredients to craft ${item}`);
        }
    }

    removeIngredients(ingredients) {
        for (const ingredient in ingredients) {
            this.items[ingredient] -= ingredients[ingredient];
        }
    }
}

