class Wallet {
  constructor(eventBus) {
    this.balance = 0;
    this.eventBus = eventBus;
    this.eventBus.subscribe('purchaseAttempt', this.handlePurchaseAttempt.bind(this));
    this.eventBus.subscribe('sellAttempt', this.handleSellAttempt.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. New balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
      return true;
    } else {
      console.log(`Insufficient funds. Balance: ${this.balance}`);
      return false;
    }
  }

  handlePurchaseAttempt({ itemPrice, item }) {
    if (this.withdraw(itemPrice)) {
      this.eventBus.emit('purchaseSuccess', { item });
    } else {
      this.eventBus.emit('purchaseFailure', { item });
    }
  }

  handleSellAttempt({ itemPrice, item }) {
    this.deposit(itemPrice);
    console.log(`Sold ${item} for ${itemPrice}. New balance: ${this.balance}`);
  }
}

class Shop {
  constructor(eventBus) {
    this.items = {
      sword: { price: 50 },
      shield: { price: 30 },
      potion: { price: 10 }
    };
    this.eventBus = eventBus;
    this.eventBus.subscribe('purchaseSuccess', this.handlePurchaseSuccess.bind(this));
    this.eventBus.subscribe('sellAttempt', this.handleSellAttempt.bind(this));
  }

  listItems() {
    return Object.keys(this.items).map(item => `${item}: ${this.items[item].price}`);
  }

  purchaseItem(item) {
    const itemInfo = this.items[item];
    if (itemInfo) {
      this.eventBus.emit('purchaseAttempt', { itemPrice: itemInfo.price, item });
    } else {
      console.log(`Item not found: ${item}`);
    }
  }

  sellItem(item, price) {
    this.eventBus.emit('sellAttempt', { itemPrice: price, item });
  }

  handlePurchaseSuccess({ item }) {
    console.log(`Purchase successful: ${item}`);
  }

  handleSellAttempt({ itemPrice, item }) {
    console.log(`Sell attempt for ${item} at ${itemPrice}`);
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('purchaseSuccess', this.handlePurchaseSuccess.bind(this));
    this.eventBus.subscribe('sellAttempt', this.handleSellAttempt.bind(this));
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
    console.log(`Added ${item} to inventory.`);
  }

  removeItem(item) {
    if (this.items[item] > 0) {
      this.items[item]--;
      console.log(`Removed ${item} from inventory.`);
      return true;
    } else {
      console.log(`Item not found in inventory: ${item}`);
      return false;
    }
  }

  handlePurchaseSuccess({ item }) {
    if (this.removeItem(item)) {
      this.eventBus.emit('sellAttempt', { itemPrice: this.getPrice(item), item });
    }
  }

  handleSellAttempt({ itemPrice, item }) {
    this.addItem(item);
  }

  getPrice(item) {
    return {
      sword: 40,
      shield: 25,
      potion: 8
    }[item] || 0;
  }
}

