class Pricing {
    constructor(basePrice) {
        this.basePrice = basePrice;
    }

    calculatePrice(quantity) {
        return this.basePrice * quantity;
    }

    setBasePrice(newBasePrice) {
        this.basePrice = newBasePrice;
    }
}

class Demand {
    constructor(initialDemand) {
        this.demand = initialDemand;
    }

    adjustDemand(change) {
        this.demand += change;
    }

    getCurrentDemand() {
        return this.demand;
    }
}

class Store {
    constructor(pricing, demand) {
        this.pricing = pricing;
        this.demand = demand;
    }

    restock(quantity) {
        console.log(`Restocked ${quantity} items.`);
    }

    sell(quantity) {
        if (quantity > this.demand.getCurrentDemand()) {
            console.log(`Cannot sell ${quantity} items, demand is only ${this.demand.getCurrentDemand()}.`);
            return;
        }

        const price = this.pricing.calculatePrice(quantity);
        console.log(`Sold ${quantity} items for ${price} gold.`);
        this.demand.adjustDemand(-quantity);
    }

    updatePrice(newBasePrice) {
        this.pricing.setBasePrice(newBasePrice);
        console.log(`Updated base price to ${newBasePrice} gold.`);
    }
}

