class RarityTable {
    constructor() {
        this.rarityLevels = {
            COMMON: 0.7,
            UNCOMMON: 0.2,
            RARE: 0.08,
            LEGENDARY: 0.02
        };
    }

    getRandomRarity() {
        const roll = Math.random();
        let cumulative = 0;
        for (const [rarity, chance] of Object.entries(this.rarityLevels)) {
            cumulative += chance;
            if (roll <= cumulative) {
                return rarity;
            }
        }
        return "COMMON"; // Default to common if something goes wrong
    }
}

class Inventory {
