class TradeSystem {
  constructor() {
    this.resources = {
      gold: 100,
      wood: 50,
      iron: 30
    };
  }

  // Public API
  buyResource(resource, amount) {
    if (this.resources[resource] >= amount) {
      this.resources[resource] -= amount;
      console.log(`Bought ${amount} ${resource}. Remaining: ${this.resources[resource]}`);
      return true;
    } else {
      console.log(`Not enough ${resource} to buy.`);
      return false;
    }
  }

  sellResource(resource, amount) {
    this.resources[resource] += amount;
    console.log(`Sold ${amount} ${resource}. Total: ${this.resources[resource]}`);
    return true;
  }
