    this.reputation += points;
    console.log(`Gained ${points} reputation. Total: ${this.reputation}`);
  }

  loseReputation(points) {
    this.reputation -= points;
    console.log(`Lost ${points} reputation. Total: ${this.reputation}`);
  }
