class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients; // { item: quantity }
    this.result = result; // { item: quantity }
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return this.ingredients;
  }

  getResult() {
    return this.result;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { item: quantity }
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  hasItems(neededItems) {
    for (const [item, quantity] of Object.entries(neededItems)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  getItems() {
    return this.items;
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes; // { recipeName: Recipe }
  }

  canCraft(recipeName) {
    const recipe = this.recipes[recipeName];
    if (!recipe) return false;
    return this.inventory.hasItems(recipe.getIngredients());
  }

  craft(recipeName) {
    const recipe = this.recipes[recipeName];
    if (!recipe || !this.canCraft(recipeName)) return false;
    for (const [item, quantity] of Object.entries(recipe.getIngredients())) {
      this.inventory.removeItem(item, quantity);
    }
    for (const [item, quantity] of Object.entries(recipe.getResult())) {
      this.inventory.addItem(item, quantity);
    }
    return true;
  }

  listRecipes() {
    return Object.keys(this.recipes);
  }
}

// Demo
