  handleReputationChange(data) {
    if (!this.reputations[data.player]) {
      this.reputations[data.player] = 0;
    }
    this.reputations[data.player] += data.change;
    console.log(`Reputation: ${data.player}'s reputation is now ${this.reputations[data.player]}.`);
