    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Purchase successful. Deducted ${amount}. New balance: ${this.balance}`);
      this.eventBus.emit('purchaseSuccess', amount);
    } else {
      console.log('Purchase failed. Insufficient funds');
      this.eventBus.emit('purchaseFailure', amount);
    }
  }

  handleRefund(amount) {
    this.balance += amount;
    console.log(`Refunded ${amount}. New balance: ${this.balance}`);
  }
}

