class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    this.balance += amount;
    return this.balance;
  }

  withdraw(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
    return this.balance;
  }

  getBalance() {
    return this.balance;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (!this.items[item] || this.items[item] < quantity) {
      throw new Error("Insufficient item quantity");
    }
    this.items[item] -= quantity;
    if (this.items[item] === 0) {
      delete this.items[item];
    }
  }

  getInventory() {
    return { ...this.items };
  }
}

class Shop {
  constructor(wallet, inventory) {
    this.wallet = wallet;
    this.inventory = inventory;
    this.prices = {
      "sword": 50,
      "potion": 10,
      "shield": 30
    };
  }

  buyItem(item, quantity = 1) {
    if (!this.prices[item]) {
      throw new Error("Item not available for purchase");
    }
    const totalCost = this.prices[item] * quantity;
    this.wallet.withdraw(totalCost);
    this.inventory.addItem(item, quantity);
    return `Bought ${quantity} ${item}(s) for ${totalCost} gold. New balance: ${this.wallet.getBalance()} gold.`;
  }

  sellItem(item, quantity = 1) {
    if (!this.inventory.items[item]) {
      throw new Error("Item not available for sale");
    }
    const totalRevenue = this.prices[item] * quantity;
    this.wallet.deposit(totalRevenue);
    this.inventory.removeItem(item, quantity);
    return `Sold ${quantity} ${item}(s) for ${totalRevenue} gold. New balance: ${this.wallet.getBalance()} gold.`;
  }
}

