// RarityTable class to determine item rarity
class RarityTable {
  constructor() {
    this.rarityMap = {
      common: 70,
      uncommon: 20,
      rare: 5,
      epic: 3,
      legendary: 2
    };
  }

  getRandomRarity() {
    const total = Object.values(this.rarityMap).reduce((a, b) => a + b, 0);
    const rand = Math.floor(Math.random() * total);
    let sum = 0;

    for (const [rarity, chance] of Object.entries(this.rarityMap)) {
      sum += chance;
      if (rand < sum) {
        return rarity;
      }
    }
    return "common"; // Default to common if something goes wrong
  }
}

