      if (this.inventory.items[result]) {
        this.inventory.items[result]++;
      } else {
        this.inventory.items[result] = 1;
      }
    } else {
      console.log(`Failed to craft ${recipeName}`);
    }
  }

  displayInventory() {
    console.log('Inventory:');
    for (const [item, quantity] of Object.entries(this.inventory.items)) {
      console.log(`${item}: ${quantity}`);
    }
  }
}

