    constructor(initialLevel = 100) {
        this.level = initialLevel;
    }

    rest(amount = 10) {
        this.level = Math.min(100, this.level + amount);
        console.log(`Rested ${amount}, Energy: ${this.level}`);
    }

    expend(amount = 5) {
        this.level = Math.max(0, this.level - amount);
        console.log(`Expended ${amount}, Energy: ${this.level}`);
    }
}

// Clock System
