    if (buyer.balance < totalCost) {
      console.log(`${buyer.name} does not have enough money to buy ${quantity} of ${itemName}.`);
      return false;
    }

    buyer.balance -= totalCost;
    seller.balance += totalCost;
    console.log(`${buyer.name} bought ${quantity} of ${itemName} from ${seller.name} for ${totalCost}.`);
    return true;
  }
}

