class Economy {
  constructor() {
    this.balance = 1000; // Starting balance
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  credit(amount) {
    this.balance += amount;
  }
}

class RarityTable {
  constructor() {
    this.rarityWeights = {
      'Common': 0.6,
      'Uncommon': 0.3,
      'Rare': 0.1
    };
  }

  getRandomRarity() {
    const rarities = Object.keys(this.rarityWeights);
    const weights = Object.values(this.rarityWeights);
    const totalWeight = weights.reduce((acc, w) => acc + w, 0);
    const random = Math.random() * totalWeight;

    let cumulativeWeight = 0;
    for (let i = 0; i < rarities.length; i++) {
      cumulativeWeight += weights[i];
      if (random < cumulativeWeight) {
        return rarities[i];
      }
    }
    return rarities[rarities.length - 1]; // Fallback to last rarity
  }
}

class Loot {
  constructor(rarityTable) {
    this.rarityTable = rarityTable;
    this.prices = {
      'Common': 10,
      'Uncommon': 50,
      'Rare': 100
    };
  }

  generateLoot() {
    const rarity = this.rarityTable.getRandomRarity();
    return { rarity, price: this.prices[rarity] };
  }

  getPrice(rarity) {
    return this.prices[rarity] || 0;
  }
}

