class Recipe {
  constructor(id, ingredients, result) {
    this.id = id;
    this.ingredients = ingredients; // { ingredientId: quantity }
    this.result = result; // { itemId: quantity }
  }

  getRecipeId() {
    return this.id;
  }

  getIngredients() {
    return this.ingredients;
  }

  getResult() {
    return this.result;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { itemId: quantity }
  }

  addItem(itemId, quantity) {
    if (this.items[itemId]) {
      this.items[itemId] += quantity;
    } else {
      this.items[itemId] = quantity;
    }
  }

  removeItems(itemsToRemove) {
    for (const [itemId, quantity] of Object.entries(itemsToRemove)) {
      if (this.items[itemId] >= quantity) {
        this.items[itemId] -= quantity;
        if (this.items[itemId] === 0) {
          delete this.items[itemId];
        }
      } else {
        throw new Error(`Not enough ${itemId} in inventory.`);
      }
    }
  }

  hasIngredients(recipeIngredients) {
    for (const [itemId, quantity] of Object.entries(recipeIngredients)) {
      if (!this.items[itemId] || this.items[itemId] < quantity) {
        return false;
      }
    }
    return true;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes; // Map of recipeId to Recipe object
  }

  canCraft(recipeId) {
    const recipe = this.recipes.get(recipeId);
    if (!recipe) {
      throw new Error(`Recipe ${recipeId} not found.`);
    }
    return this.inventory.hasIngredients(recipe.getIngredients());
  }

  craft(recipeId) {
    const recipe = this.recipes.get(recipeId);
    if (!recipe) {
      throw new Error(`Recipe ${recipeId} not found.`);
    }
    if (!this.canCraft(recipeId)) {
      throw new Error(`Cannot craft ${recipeId}: missing ingredients.`);
    }
    this.inventory.removeItems(recipe.getIngredients());
    this.inventory.addItem(Object.keys(recipe.getResult())[0], Object.values(recipe.getResult())[0]);
  }
}

