}

class RarityTable {
  constructor() {
    this.rarityToProbability = {
      'common': 0.6,
      'uncommon': 0.3,
      'rare': 0.08,
      'epic': 0.01,
      'legendary': 0.01
    };
  }

  getRandomLoot() {
    const rarities = Object.keys(this.rarityToProbability);
    let random = Math.random();
    let cumulativeProbability = 0;

    for (let rarity of rarities) {
      cumulativeProbability += this.rarityToProbability[rarity];
      if (random <= cumulativeProbability) {
        return new Loot(`Item-${rarity}`, rarity);
      }
    }
    return null; // This should never happen
  }
}

