class Economy {
    constructor() {
        this.balances = {};
    }

    getBalance(player) {
        return this.balances[player] || 0;
    }

    debit(player, amount) {
        if (this.balances[player] >= amount) {
            this.balances[player] -= amount;
            return true;
        }
        return false;
    }

    credit(player, amount) {
        this.balances[player] = (this.balances[player] || 0) + amount;
    }
}

class RarityTable {
    constructor() {
        this.table = [
            { rarity: 'Common', weight: 60 },
            { rarity: 'Uncommon', weight: 30 },
            { rarity: 'Rare', weight: 5 },
            { rarity: 'Epic', weight: 3 },
            { rarity: 'Legendary', weight: 2 }
        ];
    }

    rollRarity() {
        let totalWeight = this.table.reduce((sum, item) => sum + item.weight, 0);
        let random = Math.floor(Math.random() * totalWeight);
        for (let item of this.table) {
            random -= item.weight;
            if (random < 0) {
                return item.rarity;
            }
        }
        return 'Common'; // Fallback to common if something goes wrong
    }
}

class Loot {
    constructor(rarityTable) {
        this.rarityTable = rarityTable;
    }

    generateLoot() {
        const rarity = this.rarityTable.rollRarity();
        return { name: `Loot of ${rarity}`, rarity: rarity, price: this.getPrice(rarity) };
    }

    getPrice(rarity) {
        const priceMap = { 'Common': 5, 'Uncommon': 10, 'Rare': 20, 'Epic': 50, 'Legendary': 100 };
        return priceMap[rarity] || 5; // Default to 5 if rarity is not found
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(player, item) {
        if (!this.items[player]) {
            this.items[player] = [];
        }
        this.items[player].push(item);
    }

    listItems(player) {
        return this.items[player] || [];
    }
}

class Store {
    constructor(loot, economy, inventory) {
        this.loot = loot;
        this.economy = economy;
        this.inventory = inventory;
    }

    purchase(player) {
        const item = this.loot.generateLoot();
        const price = item.price;
        if (this.economy.debit(player, price)) {
            this.inventory.addItem(player, item);
            return { success: true, item: item };
        }
        return { success: false, message: 'Insufficient funds' };
    }
}

