class Wallet {
  constructor(initialAmount = 0) {
    this.amount = initialAmount;
  }

  deposit(amount) {
    if (amount > 0) {
      this.amount += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.amount >= amount) {
      this.amount -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.amount;
  }
}

