class Kitchen {
    constructor() {
        this.inventory = {};
    }

    addItem(item, quantity) {
        if (this.inventory[item]) {
            this.inventory[item] += quantity;
        } else {
            this.inventory[item] = quantity;
        }
    }

    hasIngredients(order) {
        const { item, quantity } = order;
        return (this.inventory[item] || 0) >= quantity;
    }

    useIngredients(order) {
        const { item, quantity } = order;
        this.inventory[item] -= quantity;
    }
}

class Customer {
    constructor() {
        this.orders = [];
    }

    placeOrder(item, quantity) {
        this.orders.push(new Order(item, quantity));
    }

    getOrders() {
        return this.orders;
    }
}

