class Store {
    constructor(economy, kitchen, customer) {
        this.economy = economy;
        this.kitchen = kitchen;
        this.customer = customer;
    }

    processOrders() {
        const orders = this.customer.getOrders();
        for (const order of orders) {
            const price = this.economy.getPrice(order.item);
            order.setPrice(price);
            const totalPrice = order.getTotalPrice();
            if (this.kitchen.hasIngredients(order)) {
                this.economy.debit(totalPrice);
                this.kitchen.useIngredients(order);
                console.log(`Processed order for ${order.quantity} ${order.item} at $${price} each.`);
            } else {
                console.log(`Insufficient ingredients for order of ${order.quantity} ${order.item}.`);
            }
        }
    }
}

