class Skill {
    constructor(name) {
        this.name = name;
        this.level = 1;
        this.experiencePoints = 0;
    }

    gainExperience(points) {
        this.experiencePoints += points;
        console.log(`Gained ${points} experience points in ${this.name}. Total: ${this.experiencePoints}`);
    }

    getExperiencePoints() {
        return this.experiencePoints;
    }

    getName() {
        return this.name;
    }
