// Experience System
class Experience {
    constructor() {
        this.skills = [];
    }

    addSkill(skill) {
        this.skills.push(skill);
    }

    distributeExperience(skillName, points) {
        const skill = this.skills.find(s => s.getName() === skillName);
        if (skill) {
            skill.gainExperience(points);
        } else {
            console.log(`Skill ${skillName} not found.`);
        }
    }

    getTotalExperience() {
        return this.skills.reduce((total, skill) => total + skill.getExperiencePoints(), 0);
    }
}

// LevelUp System
class LevelUp {
    constructor() {
        this.thresholds = {
            1: 100,
            2: 300,
            3: 600
        };
    }

    checkLevel(skill) {
        const currentLevel = skill.level;
        const experiencePoints = skill.getExperiencePoints();
        for (let level = currentLevel + 1; level <= Object.keys(this.thresholds).length; level++) {
            if (experiencePoints >= this.thresholds[level]) {
                skill.level = level;
                console.log(`${skill.getName()} leveled up to level ${level}!`);
                return true;
            }
        }
        return false;
    }
}

// Coordinator to wire the systems together
class GameCoordinator {
    constructor() {
        this.experienceSystem = new Experience();
        this.levelUpSystem = new LevelUp();
    }

    addSkill(skill) {
        this.experienceSystem.addSkill(skill);
    }

    gainExperience(skillName, points) {
        this.experienceSystem.distributeExperience(skillName, points);
        const skill = this.experienceSystem.skills.find(s => s.getName() === skillName);
        if (skill) {
            this.levelUpSystem.checkLevel(skill);
        }
    }

    getTotalExperience() {
        return this.experienceSystem.getTotalExperience();
    }
}

