class Building {
  constructor(name, resourceRequirements) {
    this.name = name;
    this.resourceRequirements = resourceRequirements;
  }

  build(economy) {
    const canBuild = Object.entries(this.resourceRequirements).every(([resource, amount]) => {
      return economy.hasResource(resource, amount);
    });

    if (canBuild) {
      Object.entries(this.resourceRequirements).forEach(([resource, amount]) => {
        economy.consumeResource(resource, amount);
      });
      console.log(`${this.name} built successfully.`);
      return true;
    } else {
      console.log(`Insufficient resources to build ${this.name}.`);
      return false;
    }
  }
}

class Resource {
  constructor(name, quantity) {
    this.name = name;
    this.quantity = quantity;
  }
}

class Economy {
  constructor() {
    this.resources = {};
  }

  addResource(name, quantity) {
    if (this.resources[name]) {
      this.resources[name].quantity += quantity;
    } else {
      this.resources[name] = new Resource(name, quantity);
    }
  }

  hasResource(name, amount) {
    return this.resources[name] && this.resources[name].quantity >= amount;
  }

  consumeResource(name, amount) {
    if (this.resources[name] && this.resources[name].quantity >= amount) {
      this.resources[name].quantity -= amount;
    }
  }

  getResources() {
    return Object.entries(this.resources).map(([name, resource]) => ({
      name: resource.name,
      quantity: resource.quantity
    }));
  }
}

