    this.balance = 0;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited: ${amount}, New Balance: ${this.balance}`);
      this.eventBus.emit('balanceChanged', { balance: this.balance });
    } else {
      console.log('Deposit amount must be positive');
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew: ${amount}, New Balance: ${this.balance}`);
      this.eventBus.emit('balanceChanged', { balance: this.balance });
    } else {
      console.log('Insufficient funds or invalid amount');
    }
  }
}

