        this.hungerLevel -= amount;
        this.hungerLevel = Math.max(0, this.hungerLevel);
    }

    update() {
        if (this.hungerLevel < 100) {
            this.hungerLevel += 1;
        }
    }

    getHungerLevel() {
        return this.hungerLevel;
    }
}

class Energy {
    constructor() {
        this.energyLevel = 100;
    }

    rest(amount) {
        this.energyLevel += amount;
        this.energyLevel = Math.min(100, this.energyLevel);
    }

    consume(amount) {
        this.energyLevel -= amount;
        this.energyLevel = Math.max(0, this.energyLevel);
    }

    update() {
        if (this.energyLevel < 100) {
            this.energyLevel += 1;
        }
    }

    getEnergyLevel() {
        return this.energyLevel;
    }
}

class Clock {
    constructor() {
        this.time = 0;
    }

    tick() {
        this.time += 1;
    }

    getTime() {
        return this.time;
    }
}

