class Wallet {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.balance = 0;
        this.eventBus.subscribe('purchase', this.onPurchase.bind(this));
    }

    deposit(amount) {
        this.balance += amount;
        console.log(`Deposited ${amount}, new balance: ${this.balance}`);
