    withdraw(amount) {
        if (amount > this.balance) {
            console.log(`Insufficient funds: ${amount} > ${this.balance}`);
            return false;
        }
        this.balance -= amount;
        console.log(`Withdrew ${amount}, new balance: ${this.balance}`);
        return true;
