class Bank {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            console.log(`Deposited ${amount}. New balance: ${this.balance}`);
        } else {
            console.log('Deposit amount must be positive.');
        }
    }

    withdraw(amount) {
        if (amount > 0 && amount <= this.balance) {
            this.balance -= amount;
            console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
        } else if (amount > this.balance) {
            console.log('Insufficient funds.');
        } else {
            console.log('Withdrawal amount must be positive.');
        }
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(prices = {}) {
        this.prices = prices;
    }

    buy(item, quantity, bank) {
        const price = this.prices[item];
        if (price) {
            const totalCost = price * quantity;
            if (bank.getBalance() >= totalCost) {
                bank.withdraw(totalCost);
                console.log(`Bought ${quantity} of ${item} for ${totalCost}.`);
                return true;
            } else {
                console.log('Insufficient funds to buy the item.');
                return false;
            }
        } else {
            console.log(`Item ${item} is not available in the market.`);
            return false;
        }
    }

    sell(item, quantity, bank) {
        const price = this.prices[item];
        if (price) {
            const totalRevenue = price * quantity;
            bank.deposit(totalRevenue);
            console.log(`Sold ${quantity} of ${item} for ${totalRevenue}.`);
            return true;
        } else {
            console.log(`Item ${item} is not available in the market.`);
            return false;
        }
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (quantity > 0) {
            this.items[item] = (this.items[item] || 0) + quantity;
            console.log(`Added ${quantity} of ${item}. Total: ${this.items[item]}`);
        } else {
            console.log('Quantity must be positive.');
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && quantity > 0 && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            console.log(`Removed ${quantity} of ${item}. Remaining: ${this.items[item]}`);
            return true;
        } else if (!this.items[item]) {
            console.log(`Item ${item} not found in inventory.`);
            return false;
        } else if (quantity > this.items[item]) {
            console.log('Insufficient quantity in inventory.');
            return false;
        } else {
            console.log('Quantity must be positive.');
            return false;
        }
    }

    getInventory() {
        return this.items;
    }
}

