class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
    this.result = result; // { itemName: quantity }
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(itemName, quantity) {
    if (this.items[itemName]) {
      this.items[itemName] += quantity;
    } else {
      this.items[itemName] = quantity;
    }
  }

  removeItem(itemName, quantity) {
    if (this.items[itemName] && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
      return true;
    }
    return false;
  }

  hasIngredients(ingredients) {
    for (const [ingredientName, quantity] of Object.entries(ingredients)) {
      if (!this.items[ingredientName] || this.items[ingredientName] < quantity) {
        return false;
      }
    }
    return true;
  }

  getItems() {
    return { ...this.items };
  }
}

class Crafting {
  constructor() {
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe) {
      return inventory.hasIngredients(recipe.ingredients);
    }
    return false;
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe && this.canCraft(recipeName, inventory)) {
      for (const [ingredientName, quantity] of Object.entries(recipe.ingredients)) {
        inventory.removeItem(ingredientName, quantity);
      }
      for (const [itemName, quantity] of Object.entries(recipe.result)) {
        inventory.addItem(itemName, quantity);
      }
      return true;
    }
    return false;
  }
}

