class Demand {
  constructor(initialDemand, changeRate) {
    this.currentDemand = initialDemand;
    this.changeRate = changeRate;
  }

  adjustDemand(change) {
    this.currentDemand += change * this.changeRate;
    return this.currentDemand;
  }
}

