class Recipe {
    constructor(name, ingredients, result) {
        this.name = name;
        this.ingredients = ingredients; // { item: quantity }
        this.result = result; // { item: quantity }
    }
}

class Inventory {
    constructor() {
        this.items = new Map();
    }

    addItem(item, quantity) {
        if (this.items.has(item)) {
            this.items.set(item, this.items.get(item) + quantity);
        } else {
            this.items.set(item, quantity);
        }
    }

    removeItem(item, quantity) {
        if (this.items.has(item) && this.items.get(item) >= quantity) {
            this.items.set(item, this.items.get(item) - quantity);
            return true;
        }
        return false;
    }

    hasItems(ingredients) {
        for (const [item, quantity] of Object.entries(ingredients)) {
            if (!this.items.has(item) || this.items.get(item) < quantity) {
                return false;
            }
        }
        return true;
    }

    getInventory() {
        return this.items;
    }
}

class Crafting {
    constructor(inventory, recipes) {
        this.inventory = inventory;
        this.recipes = recipes; // Map of name to Recipe
    }

    craft(recipeName) {
        const recipe = this.recipes.get(recipeName);
        if (!recipe) {
            console.log(`Recipe "${recipeName}" not found.`);
            return false;
        }

        if (!this.inventory.hasItems(recipe.ingredients)) {
            console.log(`Missing ingredients for recipe "${recipeName}".`);
            return false;
        }

        for (const [item, quantity] of Object.entries(recipe.ingredients)) {
            this.inventory.removeItem(item, quantity);
        }

        for (const [item, quantity] of Object.entries(recipe.result)) {
            this.inventory.addItem(item, quantity);
        }

        console.log(`Crafted "${recipeName}".`);
        return true;
    }
}

