class Economy {
    constructor(startingBalance = 0) {
        this.balance = startingBalance;
    }

    getBalance() {
        return this.balance;
    }

    addMoney(amount) {
        this.balance += amount;
    }

    subtractMoney(amount) {
        if (amount > this.balance) {
            throw new Error("Insufficient funds");
        }
        this.balance -= amount;
    }
}

class Store {
    constructor() {
        this.items = {
            "sword": { price: 50 },
            "shield": { price: 30 },
            "potion": { price: 10 }
        };
