class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemAdded', this.addItem.bind(this));
    this.eventBus.subscribe('itemRemoved', this.removeItem.bind(this));
  }

  addItem(item, quantity) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
    console.log(`Added ${quantity} ${item}(s) to inventory. Total: ${this.items[item]}`);
  }

  removeItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      console.log(`Removed ${quantity} ${item}(s) from inventory. Remaining: ${this.items[item]}`);
    } else {
      console.log(`Not enough ${item}(s) in inventory to remove.`);
    }
  }

  hasItem(item, quantity) {
    return this.items[item] >= quantity;
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
  }

  addRecipe(name, ingredients) {
    this.recipes[name] = ingredients;
  }

  canCraft(name) {
    const ingredients = this.recipes[name];
    if (!ingredients) {
      return false;
    }
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.eventBus.emit('checkItem', { item, quantity })) {
        return false;
      }
    }
    return true;
  }

  craft(name) {
    if (this.canCraft(name)) {
      const ingredients = this.recipes[name];
      for (const [item, quantity] of Object.entries(ingredients)) {
        this.eventBus.emit('removeItem', { item, quantity });
      }
      console.log(`Crafted ${name}.`);
    } else {
      console.log(`Cannot craft ${name}. Missing ingredients.`);
    }
  }
}

class Crafting {
  constructor(eventBus, inventory, recipe) {
    this.eventBus = eventBus;
    this.inventory = inventory;
    this.recipe = recipe;
    this.eventBus.subscribe('craft', this.handleCraft.bind(this));
    this.eventBus.subscribe('checkItem', this.handleCheckItem.bind(this));
    this.eventBus.subscribe('removeItem', this.handleRemoveItem.bind(this));
  }

  handleCraft({ name }) {
    this.recipe.craft(name);
  }

  handleCheckItem({ item, quantity }) {
    return this.inventory.hasItem(item, quantity);
  }

  handleRemoveItem({ item, quantity }) {
    this.inventory.removeItem(item, quantity);
  }
}

// Demo
