    const damage = this.attacks[attackName] || 0;
    return { attacker, defender, attackName, damage };
  }
}

class Health {
  constructor() {
    this.healthPoints = {};
  }

  setHealth(entity, hp) {
    this.healthPoints[entity] = hp;
  }

  getHealth(entity) {
    return this.healthPoints[entity] || 0;
  }

  takeDamage(entity, damage) {
    this.healthPoints[entity] = Math.max(0, this.healthPoints[entity] - damage);
  }
}

class Loot {
  constructor() {
    this.lootTable = {};
  }

  registerLoot(item, chance) {
    this.lootTable[item] = chance;
  }

  rollForLoot() {
    const items = Object.keys(this.lootTable);
    let totalChance = items.reduce((sum, item) => sum + this.lootTable[item], 0);
    const roll = Math.random() * totalChance;

    let cumulativeChance = 0;
    for (const item of items) {
      cumulativeChance += this.lootTable[item];
      if (roll <= cumulativeChance) {
        return item;
      }
    }
    return null;
  }
}

