class Crafting {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
    this.recipes = {
      sword: { wood: 1, iron: 2 },
      shield: { wood: 2, stone: 1 }
    };
  }

  craft(item) {
    const recipe = this.recipes[item];
    if (!recipe) {
      console.log(`No recipe for ${item}.`);
      return false;
    }

    const canCraft = Object.keys(recipe).every(ingredient => 
      this.inventory.getItemCount(ingredient) >= recipe[ingredient]
    );

    if (!canCraft) {
      console.log(`Not enough resources to craft ${item}.`);
      return false;
    }

    Object.keys(recipe).forEach(ingredient => 
      this.inventory.addItem(ingredient, -recipe[ingredient])
    );

    const cost = Object.keys(recipe).reduce((total, ingredient) => 
      total + this.economy.getPrice(ingredient) * recipe[ingredient], 0
    );

    this.economy.debit(cost);
    this.inventory.addItem(item);

    console.log(`Crafted ${item}.`);
    return true;
  }
}

