// RarityTable System
class RarityTable {
  constructor() {
    this.rarityMap = {
      common: 0.6,
      uncommon: 0.3,
      rare: 0.1
    };
  }

  getRandomRarity() {
    const rand = Math.random();
    let cumulativeProbability = 0;
    for (const [rarity, probability] of Object.entries(this.rarityMap)) {
      cumulativeProbability += probability;
      if (rand < cumulativeProbability) {
        return rarity;
      }
    }
    return 'common'; // Fallback to common if something goes wrong
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.contents = {};
  }

  addItem(item) {
    if (this.contents[item]) {
      this.contents[item]++;
    } else {
      this.contents[item] = 1;
    }
  }

  getContents() {
    return { ...this.contents };
  }
}

// Coordinator to wire the systems together
