    const item = `${rarity} item`;
    this.loot.addItem(item);
    console.log(`Generated loot: ${item}`);
  }

  collectLoot() {
    const items = this.loot.getAllItems();
    items.forEach(item => this.inventory.addItem(item));
    this.loot.items = []; // Clear the loot after collecting
    console.log('Loot collected into inventory.');
