// Inventory system
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] -= quantity;
      if (this.items[item] <= 0) {
        delete this.items[item];
      }
    }
  }

  hasItems(items) {
    for (const [item, quantity] of Object.entries(items)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }
}

// Crafting system
class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes;
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) return false;
    return this.inventory.hasItems(recipe.ingredients);
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) return false;
    if (!this.canCraft(recipeName)) return false;

    for (const [item, quantity] of Object.entries(recipe.ingredients)) {
      this.inventory.removeItem(item, quantity);
    }

    this.inventory.addItem(recipeName);
    return true;
  }
}

