// Event Bus Implementation
class EventBus {
    constructor() {
        this.events = {};
    }

    subscribe(event, listener) {
        if (!this.events[event]) {
            this.events[event] = [];
        }
        this.events[event].push(listener);
    }

    emit(event, data) {
        if (this.events[event]) {
            this.events[event].forEach(listener => listener(data));
        }
    }
}

// Pricing System
class Pricing {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('updatePrice', this.updatePrice.bind(this));
        this.price = 10; // Initial price
    }

    updatePrice(newPrice) {
        this.price = newPrice;
        console.log(`Price updated to: $${this.price}`);
        this.eventBus.emit('priceChanged', this.price);
    }

    setPrice(price) {
        this.eventBus.emit('updatePrice', price);
    }
}

// Demand System
class Demand {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('priceChanged', this.adjustDemand.bind(this));
        this.demand = 100; // Initial demand
    }

    adjustDemand(price) {
        if (price < 10) {
            this.demand += 20;
        } else if (price > 10) {
            this.demand -= 20;
        }
        console.log(`Demand adjusted to: ${this.demand}`);
        this.eventBus.emit('demandChanged', this.demand);
    }
}

// Store System
