        this.eventBus = eventBus;
        this.eventBus.subscribe('demandChanged', this.updateStock.bind(this));
        this.stock = 50; // Initial stock
    }

    updateStock(demand) {
        this.stock = demand > 100 ? 0 : 100; // Simple stock adjustment logic
        console.log(`Stock updated to: ${this.stock}`);
    }
}

