class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { item: quantity }
  }

  canCraft(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      if (!inventory.items[item] || inventory.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(inventory) {
    if (this.canCraft(inventory)) {
      for (const [item, quantity] of Object.entries(this.ingredients)) {
        inventory.removeItem(item, quantity);
      }
      return true;
    }
    return false;
  }
}

