    const recipe = this.recipes[recipeName];
    if (recipe) {
      return recipe.craft(inventory);
    }
    return false;
  }

  canCraft(inventory, recipeName) {
    const recipe = this.recipes[recipeName];
    if (recipe) {
      return recipe.canCraft(inventory);
    }
    return false;
  }
}

