// Pricing System
class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  calculatePrice(quantity) {
    // Simple price calculation: base price multiplied by quantity
    return this.basePrice * quantity;
  }
}

// Demand System
class Demand {
  constructor(initialDemand) {
    this.demand = initialDemand;
  }

  adjustDemand(change) {
    // Adjust demand based on external factors (positive or negative)
    this.demand += change;
    // Ensure demand doesn't go below zero
    this.demand = Math.max(0, this.demand);
  }

  getCurrentDemand() {
    return this.demand;
  }
}

// Store System
class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sell(quantity) {
    if (quantity > this.demand.getCurrentDemand()) {
      console.log("Not enough demand to sell that quantity.");
      return 0;
    }
    const totalPrice = this.pricing.calculatePrice(quantity);
    this.demand.adjustDemand(-quantity);
    console.log(`Sold ${quantity} items for a total of $${totalPrice}.`);
    return totalPrice;
  }

  restock(quantity) {
    this.demand.adjustDemand(quantity);
    console.log(`Restocked with ${quantity} items.`);
  }
}

// Coordinator
