    console.log(`Demand: ${this.store.demand.getCurrentDemand()}`);

    console.log("\nSelling 10 items:");
    this.store.sell(10);

    console.log("\nRestocking 20 items:");
    this.store.restock(20);

    console.log("\nSelling 30 items:");
    this.store.sell(30);

