class Bank {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            console.log(`Deposited ${amount}. New balance: ${this.balance}`);
        } else {
            console.log('Deposit amount must be positive.');
        }
    }

    withdraw(amount) {
        if (amount > 0 && amount <= this.balance) {
            this.balance -= amount;
            console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
        } else {
            console.log('Invalid withdrawal amount.');
        }
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(prices = {}) {
        this.prices = prices;
    }

    getItemPrice(item) {
        return this.prices[item] || null;
    }

    setItemPrice(item, price) {
        if (price >= 0) {
            this.prices[item] = price;
            console.log(`Set price for ${item} to ${price}`);
        } else {
            console.log('Price must be non-negative.');
        }
    }

    getPrices() {
        return { ...this.prices };
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (quantity > 0) {
            this.items[item] = (this.items[item] || 0) + quantity;
            console.log(`Added ${quantity} of ${item}. New inventory:`, this.items);
        } else {
            console.log('Quantity must be positive.');
        }
    }

    removeItem(item, quantity = 1) {
        if (this.items[item] && quantity > 0 && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            console.log(`Removed ${quantity} of ${item}. New inventory:`, this.items);
        } else {
            console.log('Invalid removal quantity.');
        }
    }

    getInventory() {
        return { ...this.items };
    }
}

