class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, callback) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(callback => callback(data));
    }
  }
}

class Wallet {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('purchase', this.handlePurchase.bind(this));
    this.eventBus.subscribe('addMoney', this.handleAddMoney.bind(this));
  }

  handlePurchase(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Purchase successful. New balance: ${this.balance}`);
      this.eventBus.emit('purchaseSuccess', amount);
    } else {
      console.log('Insufficient funds for purchase.');
      this.eventBus.emit('purchaseFailure');
    }
  }

  handleAddMoney(amount) {
    this.balance += amount;
    console.log(`Added ${amount} to wallet. New balance: ${this.balance}`);
  }

  getBalance() {
    return this.balance;
  }
}

