class Farm {
    constructor(market) {
        this.market = market;
        this.crops = [];
    }

    plantCrop(crop) {
        this.crops.push(crop);
        console.log(`Planted ${crop.name}`);
    }

    harvestCrop(name) {
        const cropIndex = this.crops.findIndex(crop => crop.name === name);
        if (cropIndex !== -1) {
            const crop = this.crops.splice(cropIndex, 1)[0];
            this.market.sellCrop(crop);
            console.log(`Harvested and sold ${crop.name}`);
        } else {
            console.log(`Crop ${name} not found`);
        }
    }

    listCrops() {
        console.log("Crops in the farm:");
        this.crops.forEach(crop => console.log(`- ${crop.name} (${crop.quantity})`));
    }
}

class Crop {
    constructor(name, quantity) {
        this.name = name;
        this.quantity = quantity;
    }
}

class Market {
    constructor() {
        this.inventory = {};
    }

    sellCrop(crop) {
        if (this.inventory[crop.name]) {
            this.inventory[crop.name].quantity += crop.quantity;
        } else {
            this.inventory[crop.name] = { ...crop };
        }
        console.log(`Sold ${crop.quantity} of ${crop.name}`);
    }

    listInventory() {
        console.log("Market inventory:");
        Object.keys(this.inventory).forEach(name => {
            const crop = this.inventory[name];
            console.log(`- ${crop.name} (${crop.quantity})`);
        });
    }
}

