class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemAdded', this.handleItemAdded.bind(this));
  }

  addItem(item, quantity) {
    this.items[item] = (this.items[item] || 0) + quantity;
    this.eventBus.emit('itemAdded', { item, quantity });
  }

  removeItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getItems() {
    return { ...this.items };
  }

  handleItemAdded({ item, quantity }) {
    console.log(`Item added: ${item} x${quantity}`);
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('craftRequested', this.handleCraftRequested.bind(this));
  }

  addRecipe(name, ingredients) {
    this.recipes[name] = ingredients;
  }

  requestCraft(name) {
    this.eventBus.emit('craftRequested', name);
  }

  handleCraftRequested(name) {
    if (this.recipes[name]) {
      this.eventBus.emit('craftPossible', { name, ingredients: this.recipes[name] });
    } else {
      console.log(`Recipe not found: ${name}`);
    }
