  }

  handleCraftPossible({ name, ingredients }) {
    const canCraft = Object.keys(ingredients).every(item => {
      return this.inventory.removeItem(item, ingredients[item]);
    });

    if (canCraft) {
      this.inventory.addItem(name, 1);
      console.log(`Crafted: ${name}`);
    } else {
      console.log(`Failed to craft: ${name}`);
    }
  }
}

