// RarityTable System
class RarityTable {
  constructor(rarityList) {
    this.rarityList = rarityList;
  }

  getRandomRarity() {
    const totalWeight = this.rarityList.reduce((sum, rarity) => sum + rarity.weight, 0);
    let randomWeight = Math.random() * totalWeight;
    for (const rarity of this.rarityList) {
      if (randomWeight < rarity.weight) {
        return rarity.name;
      }
      randomWeight -= rarity.weight;
    }
    return this.rarityList[this.rarityList.length - 1].name; // Fallback to last rarity
  }
}

