    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Shop {
  constructor() {
    this.items = new Map([
      ['apple', { price: 1, quantity: 10 }],
      ['banana', { price: 2, quantity: 5 }],
      ['orange', { price: 3, quantity: 8 }]
    ]);
  }

  getItemPrice(item) {
    const itemInfo = this.items.get(item);
    return itemInfo ? itemInfo.price : null;
  }

  purchaseItem(item, wallet) {
    const itemInfo = this.items.get(item);
    if (itemInfo && itemInfo.quantity > 0) {
      const price = itemInfo.price;
      if (wallet.withdraw(price)) {
        itemInfo.quantity -= 1;
        return true;
      }
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  addItem(item) {
    this.items.set(item, (this.items.get(item) || 0) + 1);
  }

  getItemCount(item) {
    return this.items.get(item) || 0;
  }
}

