    return { ...this.prices };
  }
}

class Store {
  constructor(economy, kitchen) {
    this.economy = economy;
    this.kitchen = kitchen;
  }

  processOrder(order) {
    const prices = this.economy.getCurrentPrices();
    const totalPrice = order.getTotalPrice(prices);

    if (totalPrice > 0) {
      this.economy.debit(totalPrice);
      order.orderItems.forEach(({ item, quantity }) => {
        this.kitchen.addItem(item, quantity);
      });
      console.log(`Order processed for ${totalPrice}`);
    } else {
      console.log('Order failed: Total price is zero or negative');
    }
  }
}

