class Trade {
  constructor() {
    this.resources = { gold: 100, wood: 50, stone: 30 };
  }

  sell(resource, amount) {
    if (this.resources[resource] >= amount) {
      this.resources[resource] -= amount;
      console.log(`Sold ${amount} ${resource}. Remaining: ${this.resources[resource]}`);
      return true;
    } else {
      console.log(`Not enough ${resource} to sell.`);
      return false;
    }
  }

  buy(resource, amount, price) {
    if (this.resources.gold >= price * amount) {
      this.resources.gold -= price * amount;
      this.resources[resource] += amount;
      console.log(`Bought ${amount} ${resource} for ${price * amount} gold. Remaining gold: ${this.resources.gold}`);
      return true;
    } else {
      console.log(`Not enough gold to buy ${amount} ${resource}.`);
      return false;
    }
  }
}

class Reputation {
  constructor() {
    this.standing = 50;
  }

  improve(amount) {
    this.standing += amount;
    console.log(`Reputation improved by ${amount}. Current standing: ${this.standing}`);
  }

  degrade(amount) {
    this.standing -= amount;
    console.log(`Reputation degraded by ${amount}. Current standing: ${this.standing}`);
  }

  getStanding() {
    return this.standing;
  }
}

class Faction {
  constructor(trade, reputation) {
    this.trade = trade;
    this.reputation = reputation;
  }

  tradeWithOtherFaction(resource, amount, price) {
