      this.reputation.improve(10);
    } else {
      this.reputation.degrade(5);
    }
  }

  sellToOtherFaction(resource, amount, price) {
    if (this.trade.sell(resource, amount)) {
      this.reputation.improve(10);
    } else {
      this.reputation.degrade(5);
    }
  }

  getReputation() {
    return this.reputation.getStanding();
  }
}

