        if (index >= 0 && index < this.quests.length) {
            this.quests[index].completed = true;
            return this.quests[index].reward;
        }
        return null;
    }

    getQuests() {
        return this.quests.map((quest, index) => ({
            index,
            description: quest.description,
            completed: quest.completed
        }));
    }
