        this.buildingSystem = buildingSystem;
        this.resourceSystem = resourceSystem;
    }

    upgradeBuilding(name, cost) {
        if (this.resourceSystem.spend('gold', cost.gold) && this.resourceSystem.spend('wood', cost.wood)) {
            this.buildingSystem.build(name, cost);
            return true;
        }
        return false;
    }

