        this.balance = 1000; // Initial balance
    }

    getBalance() {
        return this.balance;
    }

    debit(amount) {
        if (amount > this.balance) {
            throw new Error("Insufficient funds");
        }
        this.balance -= amount;
    }

    credit(amount) {
        this.balance += amount;
    }
}

// Loot system
class Loot {
    constructor(name, price, rarity) {
        this.name = name;
        this.price = price;
        this.rarity = rarity;
    }

    static generateLoot(rarityTable) {
        const rarity = rarityTable.getRandomRarity();
        const price = Math.floor(Math.random() * 100) + 1; // Random price between 1 and 100
        return new Loot(`Item-${price}`, price, rarity);
    }
}

// RarityTable system
class RarityTable {
    constructor() {
        this.rarities = ['Common', 'Uncommon', 'Rare', 'Epic', 'Legendary'];
    }

    getRandomRarity() {
        const randomIndex = Math.floor(Math.random() * this.rarities.length);
        return this.rarities[randomIndex];
    }
}

// Inventory system
