class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Shop {
  constructor(wallet, inventory) {
    this.wallet = wallet;
    this.inventory = inventory;
    this.items = {
      sword: { price: 50, quantity: 10 },
      shield: { price: 30, quantity: 15 },
      potion: { price: 10, quantity: 20 }
    };
  }

  buyItem(itemName) {
    const item = this.items[itemName];
    if (item && item.quantity > 0 && this.wallet.withdraw(item.price)) {
      this.inventory.addItem(itemName);
      item.quantity--;
      return true;
    }
    return false;
  }

  getItemPrice(itemName) {
    return this.items[itemName]?.price || 0;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(itemName) {
    if (this.items[itemName]) {
      this.items[itemName]++;
    } else {
      this.items[itemName] = 1;
    }
  }

  getItemCount(itemName) {
    return this.items[itemName] || 0;
  }
}

// Demo
const wallet = new Wallet(100);
const inventory = new Inventory();
const shop = new Shop(wallet, inventory);

