class Order {
    constructor(items) {
        this.items = items;
    }

    getTotalPrice(prices) {
        return this.items.reduce((total, item) => total + (prices[item] || 0), 0);
    }
}

class Kitchen {
    constructor() {
        this.orders = [];
    }

    addOrder(order) {
        this.orders.push(order);
    }

    processOrders(prices) {
        const processedOrders = this.orders.map(order => {
            const totalPrice = order.getTotalPrice(prices);
            return { items: order.items, totalPrice };
        });
        this.orders = [];
        return processedOrders;
    }
}

class Customer {
    constructor(name, wallet) {
        this.name = name;
        this.wallet = wallet;
    }

    placeOrder(kitchen, order) {
        kitchen.addOrder(order);
    }

    canAfford(prices, order) {
        const totalPrice = order.getTotalPrice(prices);
        return totalPrice <= this.wallet;
    }
}

class Economy {
    constructor(prices) {
        this.prices = prices;
    }

    debit(price) {
        if (this.wallet >= price) {
            this.wallet -= price;
            return true;
        }
        return false;
    }

    getPrices() {
        return this.prices;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item) {
        this.items[item] = (this.items[item] || 0) + 1;
    }

    addItems(items) {
        items.forEach(item => this.addItem(item));
    }
}

class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
        this.kitchen = new Kitchen();
    }

    purchase(customer, order) {
        const prices = this.economy.getPrices();
        if (customer.canAfford(prices, order)) {
            const totalPrice = order.getTotalPrice(prices);
            if (this.economy.debit(totalPrice)) {
                customer.placeOrder(this.kitchen, order);
                return true;
            }
        }
        return false;
    }

    processOrders() {
        const prices = this.economy.getPrices();
        const processedOrders = this.kitchen.processOrders(prices);
        processedOrders.forEach(order => this.inventory.addItems(order.items));
        return processedOrders;
    }
}

// Demo
const prices = { burger: 5, fries: 3, drink: 2 };
const economy = new Economy(prices);
const inventory = new Inventory();
const store = new Store(economy, inventory);
const customer = new Customer('John', 15);

const order1 = new Order(['burger', 'fries']);
const order2 = new Order(['drink', 'drink']);

console.log('Customer can afford order1:', customer.canAfford(prices, order1)); // true
console.log('Store purchase order1:', store.purchase(customer, order1)); // true
console.log('Customer wallet after order1:', customer.wallet); // 7

console.log('Customer can afford order2:', customer.canAfford(prices, order2)); // true
console.log('Store purchase order2:', store.purchase(customer, order2)); // true
console.log('Customer wallet after order2:', customer.wallet); // 2

console.log('Processing orders...');
const processedOrders = store.processOrders();
console.log('Processed orders:', processedOrders);
console.log('Inventory after processing:', inventory.items); // { burger: 1, fries: 1, drink: 2 }
