  }

  getHungerLevel() {
    return this.hungerLevel;
  }
}

class Energy {
  constructor() {
    this.energyLevel = 100; // Full
  }

  rest(amount = 20) {
    this.energyLevel = Math.min(100, this.energyLevel + amount);
    console.log(`Rested ${amount}. Energy level is now ${this.energyLevel}.`);
  }

  expend(amount = 10) {
    this.energyLevel = Math.max(0, this.energyLevel - amount);
    console.log(`Expend ${amount} energy. Energy level is now ${this.energyLevel}.`);
  }

  getEnergyLevel() {
    return this.energyLevel;
  }
}

