    this.time += 1;
    console.log(`Time is now ${this.time}.`);
    return this.time;
  }

  getTime() {
    return this.time;
  }
}

class GameCoordinator {
  constructor() {
    this.hunger = new Hunger();
    this.energy = new Energy();
    this.clock = new Clock();
  }

  simulateDay() {
    console.log("Simulating a day...");

    // Morning
    this.clock.tick(); // Time 1
    this.energy.expend(10); // Energy at 90
    this.hunger.eat(5); // Hunger at 105 capped to 100

    // Midday
    this.clock.tick(); // Time 2
    this.energy.expend(15); // Energy at 75
    this.hunger.eat(10); // Hunger at 115 capped to 100

    // Evening
    this.clock.tick(); // Time 3
    this.energy.expend(5); // Energy at 70
    this.hunger.eat(15); // Hunger at 115 capped to 100

    // Night
    this.clock.tick(); // Time 4
    this.energy.rest(30); // Energy at 100
    this.hunger.eat(20); // Hunger at 120 capped to 100

    console.log("Day simulation complete.");
  }
}

