class Trade {
    constructor() {
        this._trades = {};
    }

    recordTrade(commodity, quantity, faction) {
        if (!this._trades[commodity]) {
            this._trades[commodity] = 0;
        }
        this._trades[commodity] += quantity;
        return `Recorded ${quantity} units of ${commodity} for faction ${faction}.`;
    }

    getTradeHistory(commodity) {
        return this._trades[commodity] || 0;
    }
}

class Reputation {
    constructor() {
        this._reputations = {};
    }

    changeReputation(faction, points) {
        if (!this._reputations[faction]) {
            this._reputations[faction] = 0;
        }
        this._reputations[faction] += points;
        return `Reputation for ${faction} changed by ${points} points.`;
    }

    getReputation(faction) {
        return this._reputations[faction] || 0;
    }
}

class Faction {
    constructor(tradeSystem, reputationSystem) {
        this._tradeSystem = tradeSystem;
        this._reputationSystem = reputationSystem;
    }

    conductTrade(commodity, quantity) {
        const faction = "Galactic Republic";
        const tradeResult = this._tradeSystem.recordTrade(commodity, quantity, faction);
        this._reputationSystem.changeReputation(faction, quantity); // Assume more trade = better rep
        return `${tradeResult} New reputation: ${this._reputationSystem.getReputation(faction)}`;
    }
}

// Top-level coordinator
