class LevelUp {
  constructor(experience, skill) {
    this.experience = experience;
    this.skill = skill;
  }

  checkLevelUp(levelUpThreshold) {
    if (this.experience.isLevelUp(this.skill, levelUpThreshold)) {
      this.skill.levelUp();
      this.experience.addPoints(-levelUpThreshold); // Reset points after level up
      console.log(`Skill ${this.skill.getName()} leveled up to level ${this.skill.getLevel()}!`);
    }
  }
}

