class Bank {
  constructor(balance = 0) {
    this.balance = balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && quantity <= this.items[item]) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Market {
  constructor(prices) {
    this.prices = prices;
  }

  getPrices() {
    return { ...this.prices };
  }

  buyItem(item, quantity, bank, inventory) {
    const price = this.prices[item];
    if (price && bank.withdraw(price * quantity)) {
      inventory.addItem(item, quantity);
      return true;
    }
    return false;
  }
}

