  }

  sellCrop(cropName) {
    const index = this.inventory.findIndex(crop => crop.name === cropName);
    if (index !== -1) {
      const soldCrop = this.inventory.splice(index, 1)[0];
      console.log(`Sold ${soldCrop.name} for ${soldCrop.price}`);
