class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemAdded', this.handleItemAdded.bind(this));
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
    this.eventBus.emit('inventoryUpdated', { item, quantity: this.items[item] });
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      this.eventBus.emit('inventoryUpdated', { item, quantity: this.items[item] });
    }
  }

  handleItemAdded(data) {
    this.addItem(data.item, data.quantity);
  }

  getInventory() {
    return this.items;
  }
}

class Crafting {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('recipeAdded', this.handleRecipeAdded.bind(this));
    this.eventBus.subscribe('craftItem', this.handleCraftItem.bind(this));
  }

  addRecipe(recipeName, recipe) {
    this.recipes[recipeName] = recipe;
    this.eventBus.emit('recipeAdded', { recipeName, recipe });
  }

  craftItem(recipeName) {
    if (this.recipes[recipeName]) {
      const recipe = this.recipes[recipeName];
      const canCraft = Object.keys(recipe).every(item => {
        const requiredAmount = recipe[item];
        const availableAmount = this.eventBus.emit('checkItemQuantity', { item });
        return availableAmount >= requiredAmount;
      });

      if (canCraft) {
        Object.keys(recipe).forEach(item => {
          const requiredAmount = recipe[item];
          this.eventBus.emit('removeItem', { item, quantity: requiredAmount });
        });
        this.eventBus.emit('craftResult', { item: recipeName, quantity: 1 });
      } else {
        console.log(`Not enough resources to craft ${recipeName}`);
      }
    } else {
      console.log(`Recipe ${recipeName} not found`);
    }
  }

  handleRecipeAdded(data) {
    this.recipes[data.recipeName] = data.recipe;
  }

  handleCraftItem(data) {
    this.craftItem(data.recipeName);
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('recipeAdded', this.handleRecipeAdded.bind(this));
  }

  addRecipe(recipeName, recipe) {
    this.recipes[recipeName] = recipe;
    this.eventBus.emit('recipeAdded', { recipeName, recipe });
  }

  handleRecipeAdded(data) {
    this.recipes[data.recipeName] = data.recipe;
  }

  getRecipes() {
    return this.recipes;
  }
}

