class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients;
    this.result = result;
  }
}

class Crafting {
  constructor() {
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) return false;
    for (const [item, amount] of Object.entries(recipe.ingredients)) {
      if (inventory.count(item) < amount) return false;
    }
    return true;
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) return null;
    for (const [item, amount] of Object.entries(recipe.ingredients)) {
      inventory.remove(item, amount);
    }
    return recipe.result;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  add(item, amount) {
    if (this.items[item]) {
      this.items[item] += amount;
    } else {
      this.items[item] = amount;
    }
  }

  remove(item, amount) {
    if (this.items[item] >= amount) {
      this.items[item] -= amount;
    } else {
      throw new Error(`Not enough ${item} in inventory.`);
    }
  }

  count(item) {
    return this.items[item] || 0;
  }
}

class Economy {
  constructor(prices) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  debit(item, amount) {
    if (this.prices[item] >= amount) {
      this.prices[item] -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item, amount) {
    const price = this.economy.getPrice(item);
    if (this.economy.debit(item, price * amount)) {
      this.inventory.add(item, amount);
      return true;
    }
    return false;
  }
}

