class Recipe {
  constructor(name, ingredients, output) {
    this.name = name;
    this.ingredients = ingredients;
    this.output = output;
  }

  matchesIngredients(inventory) {
    for (const [item, quantity] of this.ingredients) {
      if (inventory.get(item) < quantity) {
        return false;
      }
    }
    return true;
  }

  consumeIngredients(inventory) {
    for (const [item, quantity] of this.ingredients) {
      inventory.remove(item, quantity);
    }
  }

  getOutput() {
    return this.output;
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  add(item, quantity) {
    this.items.set(item, (this.items.get(item) || 0) + quantity);
  }

  remove(item, quantity) {
    if (this.items.has(item)) {
      const currentQuantity = this.items.get(item);
      if (currentQuantity >= quantity) {
        this.items.set(item, currentQuantity - quantity);
      } else {
        throw new Error(`Not enough ${item} to remove`);
      }
    } else {
      throw new Error(`${item} not found in inventory`);
    }
  }

  get(item) {
    return this.items.get(item) || 0;
  }

  list() {
    return Array.from(this.items.entries());
  }
}

class Crafting {
  constructor() {
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  craft(inventory, recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) {
      throw new Error(`Recipe ${recipeName} not found`);
    }
    if (!recipe.matchesIngredients(inventory)) {
      throw new Error(`Ingredients for ${recipeName} not available`);
    }
    recipe.consumeIngredients(inventory);
    inventory.add(recipe.getOutput(), 1);
  }

  listRecipes() {
    return this.recipes.map(recipe => recipe.name);
  }
}

// Top-level coordinator
class Game {
  constructor() {
    this.inventory = new Inventory();
    this.crafting = new Crafting();
    this.initializeRecipes();
  }

  initializeRecipes() {
    this.crafting.addRecipe(new Recipe('Wooden Sword', [['Wood', 2]], 'Sword'));
    this.crafting.addRecipe(new Recipe('Stone Axe', [['Stone', 3]], 'Axe'));
