  constructor() {
    this.resources = {
      wood: new Resource('Wood', 0),
      stone: new Resource('Stone', 0),
      gold: new Resource('Gold', 0)
    };
  }

  canAfford(resourcesNeeded) {
    for (const [resourceName, amountNeeded] of Object.entries(resourcesNeeded)) {
      if (this.resources[resourceName].quantity < amountNeeded) {
        return false;
      }
    }
    return true;
  }

  spendResources(resourcesNeeded) {
    for (const [resourceName, amountNeeded] of Object.entries(resourcesNeeded)) {
      this.resources[resourceName].updateQuantity(-amountNeeded);
    }
  }

  addResources(resourcesToAdd) {
    for (const [resourceName, amountToAdd] of Object.entries(resourcesToAdd)) {
      this.resources[resourceName].updateQuantity(amountToAdd);
    }
  }
}

