class RarityTable {
  constructor() {
    this.table = {
      common: 0.7,
      uncommon: 0.2,
      rare: 0.08,
      legendary: 0.02
    };
  }

  rollRarity() {
    const random = Math.random();
    let cumulativeProbability = 0;

    for (const rarity in this.table) {
      cumulativeProbability += this.table[rarity];
      if (random <= cumulativeProbability) {
        return rarity;
      }
    }

    return "common"; // Default to common if something goes wrong
  }

  generateLoot() {
    const rarity = this.rollRarity();
    let value = 0;

    switch (rarity) {
      case "common":
        value = Math.floor(Math.random() * 10) + 1;
        break;
      case "uncommon":
        value = Math.floor(Math.random() * 50) + 10;
        break;
      case "rare":
        value = Math.floor(Math.random() * 100) + 50;
        break;
      case "legendary":
        value = Math.floor(Math.random() * 500) + 100;
        break;
    }

    return new Loot(`Loot-${rarity}`, value);
  }
}

