class RarityTable {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.rarityMap = {
            common: 0.7,
            uncommon: 0.2,
            rare: 0.1
        };
    }

    rollRarity() {
        const random = Math.random();
        let cumulativeProbability = 0;

        for (const [rarity, probability] of Object.entries(this.rarityMap)) {
            cumulativeProbability += probability;
            if (random < cumulativeProbability) {
                this.eventBus.emit('rarityRolled', rarity);
                return rarity;
            }
        }
    }
}

class Loot {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.lootTable = {
            common: ['Gold', 'Potion'],
            uncommon: ['Silver', 'Wand'],
            rare: ['Ruby', 'Sword']
        };
    }

    generateLoot(rarity) {
        if (this.lootTable[rarity]) {
            const loot = this.lootTable[rarity][Math.floor(Math.random() * this.lootTable[rarity].length)];
            this.eventBus.emit('lootGenerated', loot);
            return loot;
        }
        return null;
    }
}

