class Quest {
    constructor(flags, dialogue) {
        this.flags = flags;
        this.dialogue = dialogue;
    }

    startQuest(questName) {
        this.flags.set(`quest_${questName}_started`, true);
        this.dialogue.speak('Narrator', `Quest "${questName}" has started.`);
    }

    completeQuest(questName) {
        if (this.flags.get(`quest_${questName}_started`)) {
            this.flags.set(`quest_${questName}_completed`, true);
            this.dialogue.speak('Narrator', `Quest "${questName}" has been completed.`);
        } else {
            this.dialogue.speak('Narrator', `Quest "${questName}" cannot be completed as it has not been started.`);
        }
    }

    checkQuestStatus(questName) {
        const started = this.flags.get(`quest_${questName}_started`);
        const completed = this.flags.get(`quest_${questName}_completed`);
        if (started) {
            this.dialogue.conditionalSpeak('Narrator', `Quest "${questName}" is ongoing.`, `quest_${questName}_completed`, false);
            this.dialogue.conditionalSpeak('Narrator', `Quest "${questName}" has been completed.`, `quest_${questName}_completed`, true);
        } else {
            this.dialogue.speak('Narrator', `Quest "${questName}" has not been started.`);
        }
    }
}

