    this.skills = {};

    this.eventBus.subscribe('levelUp', this.handleLevelUp.bind(this));
  }

  addSkill(skillName, level) {
    this.skills[skillName] = level;
    console.log(`Skill ${skillName} added at level ${level}`);
  }

  handleLevelUp(level) {
    for (let skill in this.skills) {
