class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.experiencePoints = 0;
    this.experienceNeeded = 100;
  }

  gainExperience(points) {
    this.experiencePoints += points;
    console.log(`Gained ${points} experience points. Total: ${this.experiencePoints}`);

    if (this.experiencePoints >= this.experienceNeeded) {
      this.levelUp();
    }
  }

  levelUp() {
    const levelsGained = Math.floor(this.experiencePoints / this.experienceNeeded);
    this.experiencePoints %= this.experienceNeeded;
    console.log(`Leveled up by ${levelsGained} levels!`);

    this.eventBus.emit('levelUp', levelsGained);
  }
}

