class Pricing {
  constructor(basePrice, priceIncrease) {
    this.basePrice = basePrice;
    this.priceIncrease = priceIncrease;
  }

  getPrice(stockLevel) {
    return this.basePrice + (this.priceIncrease * stockLevel);
  }
