    return this.pricing.getPrice(this.stockLevel);
  }

  updateDemand(price) {
    return this.demand.getDemand(price);
  }

  sellProduct() {
    const price = this.updatePrice();
    const demand = this.updateDemand(price);
    if (demand > 0) {
