    withdraw(amount) {
        if (this.balance >= amount) {
            this.balance -= amount;
            console.log(`Wallet: Withdrew ${amount}, new balance is ${this.balance}`);
            return true;
        } else {
            console.log('Wallet: Insufficient funds');
            return false;
