class RarityTable {
    constructor() {
        this.table = {
            'Common': 0.6,
            'Uncommon': 0.3,
            'Rare': 0.09,
            'Epic': 0.009,
            'Legendary': 0.001
        };
    }

    getRandomLoot() {
        const rand = Math.random();
        let cumulativeProbability = 0;

        for (const [rarity, probability] of Object.entries(this.table)) {
            cumulativeProbability += probability;
            if (rand <= cumulativeProbability) {
                const value = Math.floor(Math.random() * 100) + 1;
                return new Loot(`Item-${rarity}`, value, rarity);
            }
        }
    }
}

