class RarityTable {
  constructor() {
    this.rarityMap = {
      common: { min: 0, max: 50 },
      uncommon: { min: 51, max: 75 },
      rare: { min: 76, max: 90 },
      epic: { min: 91, max: 99 },
      legendary: { min: 100, max: 100 }
    };
  }

  rollRarity() {
    const roll = Math.floor(Math.random() * 101);
    for (const [rarity, range] of Object.entries(this.rarityMap)) {
      if (roll >= range.min && roll <= range.max) {
        return rarity;
      }
    }
    return 'common'; // Default to common if no match
  }
}

class Inventory {
