    console.log(`Reputation improved by ${amount}. Current standing: ${this.standing}`);
  }

  degrade(amount) {
    this.standing -= amount;
    console.log(`Reputation degraded by ${amount}. Current standing: ${this.standing}`);
  }

  getStanding() {
    return this.standing;
  }
}

class Faction {
  constructor() {
    this.allies = [];
    this.enemies = [];
  }

  allyWith(factionName) {
    if (!this.enemies.includes(factionName)) {
      this.allies.push(factionName);
      console.log(`Allied with ${factionName}.`);
    } else {
      console.log(`Cannot ally with ${factionName} (they are an enemy).`);
    }
  }

  declareWar(factionName) {
    if (!this.allies.includes(factionName)) {
      this.enemies.push(factionName);
      console.log(`Declared war on ${factionName}.`);
    } else {
      console.log(`Cannot declare war on ${factionName} (they are an ally).`);
    }
  }

  getFactions() {
    return { allies: [...this.allies], enemies: [...this.enemies] };
  }
}

class Coordinator {
