    this.trade = new Trade();
    this.reputation = new Reputation();
    this.faction = new Faction();
  }

  executeTradeAction(action, resource, amount) {
    if (action === 'sell') {
      this.trade.sell(resource, amount);
    } else if (action === 'buy') {
      this.trade.buy(resource, amount);
    }
  }

  executeReputationAction(action, amount) {
    if (action === 'improve') {
      this.reputation.improve(amount);
    } else if (action === 'degrade') {
      this.reputation.degrade(amount);
    }
  }

  executeFactionAction(action, factionName) {
