class Pricing {
  constructor() {
    this.prices = {};
  }

  setPrice(item, price) {
    this.prices[item] = price;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }
}

class Demand {
  constructor() {
    this.demand = {};
  }

  setDemand(item, amount) {
    this.demand[item] = amount;
  }

  getDemand(item) {
    return this.demand[item] || 0;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
    this.balance = 1000; // Initial balance for the store
  }

  purchase(item, quantity) {
    const pricePerItem = this.pricing.getPrice(item);
    const totalCost = pricePerItem * quantity;
    const availableDemand = this.demand.getDemand(item);

    if (this.balance >= totalCost && availableDemand >= quantity) {
      this.balance -= totalCost;
      this.demand.setDemand(item, availableDemand - quantity);

      if (this.inventory[item]) {
        this.inventory[item] += quantity;
      } else {
        this.inventory[item] = quantity;
      }

      console.log(`Purchased ${quantity} ${item}(s) for ${totalCost} units. Remaining balance: ${this.balance}`);
      return true;
    } else {
      console.log(`Insufficient funds or demand for ${item}.`);
      return false;
    }
  }

  getInventory() {
    return this.inventory;
  }

  getBalance() {
    return this.balance;
  }
}

// Demo
