pricing.setPrice('apple', 10);
pricing.setPrice('banana', 5);

const demand = new Demand();
demand.setDemand('apple', 20);
demand.setDemand('banana', 15);

const store = new Store(pricing, demand);

store.purchase('apple', 3); // Should succeed
store.purchase('banana', 5); // Should succeed
store.purchase('apple', 10); // Should fail due to insufficient demand
store.purchase('banana', 20); // Should fail due to insufficient funds

console.log('Final Inventory:', store.getInventory());
console.log('Final Balance:', store.getBalance());
