class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemAdded', this.onItemAdded.bind(this));
    this.eventBus.subscribe('itemRemoved', this.onItemRemoved.bind(this));
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
    this.eventBus.emit('itemAdded', { item, quantity });
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      this.eventBus.emit('itemRemoved', { item, quantity });
    }
  }

  onItemAdded({ item, quantity }) {
    console.log(`Inventory: Added ${quantity} ${item}(s)`);
  }

  onItemRemoved({ item, quantity }) {
    console.log(`Inventory: Removed ${quantity} ${item}(s)`);
  }

  getItems() {
    return this.items;
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('craftRequest', this.onCraftRequest.bind(this));
  }

  addRecipe(recipeName, ingredients) {
    this.recipes[recipeName] = ingredients;
  }

  craft(recipeName) {
    const ingredients = this.recipes[recipeName];
    if (ingredients) {
      this.eventBus.emit('craftRequest', { recipeName, ingredients });
    } else {
      console.log(`Recipe not found: ${recipeName}`);
    }
  }

  onCraftRequest({ recipeName, ingredients }) {
    this.eventBus.emit('craftAttempt', { recipeName, ingredients });
  }
}

class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('craftAttempt', this.onCraftAttempt.bind(this));
    this.eventBus.subscribe('itemAdded', this.onItemAdded.bind(this));
    this.eventBus.subscribe('itemRemoved', this.onItemRemoved.bind(this));
  }

  onCraftAttempt({ recipeName, ingredients }) {
    const canCraft = Object.keys(ingredients).every(item => {
      return this.eventBus.emit('checkInventory', { item, quantity: ingredients[item] });
    });

    if (canCraft) {
      Object.keys(ingredients).forEach(item => {
        this.eventBus.emit('itemRemoved', { item, quantity: ingredients[item] });
      });
      this.eventBus.emit('itemAdded', { item: recipeName, quantity: 1 });
      console.log(`Crafting: Successfully crafted ${recipeName}`);
    } else {
      console.log(`Crafting: Failed to craft ${recipeName} due to insufficient ingredients`);
    }
  }

  onItemAdded({ item, quantity }) {
    console.log(`Crafting: Item added to inventory - ${item}: ${quantity}`);
  }

  onItemRemoved({ item, quantity }) {
    console.log(`Crafting: Item removed from inventory - ${item}: ${quantity}`);
  }
}

