      console.log("Out of energy!");
      return;
    }
    this.energyLevel -= amount;
    if (this.energyLevel < 0) this.energyLevel = 0;
    console.log(`Energy decreased by ${amount}, energy is now ${this.energyLevel}`);
  }

  update() {
    if (this.clockSystem.isMidnight()) {
      this.energyLevel += 5;
      if (this.energyLevel > 100) this.energyLevel = 100;
