class RarityTable {
    constructor(rarityWeights) {
        this.rarityWeights = rarityWeights;
        this.totalWeight = Object.values(rarityWeights).reduce((acc, weight) => acc + weight, 0);
    }

    getRarityWeight(rarity) {
        return this.rarityWeights[rarity] || 0;
    }

    getRandomRarity() {
        let rand = Math.random() * this.totalWeight;
        for (const [rarity, weight] of Object.entries(this.rarityWeights)) {
            if (rand < weight) {
                return rarity;
            }
            rand -= weight;
        }
        return null; // Should never happen if weights are normalized
    }
}

