  prepareOrder(order) {
    const canPrepare = order.items.every(({ item, quantity }) => {
      return this.inventory[item] >= quantity;
    });

    if (canPrepare) {
      order.items.forEach(({ item, quantity }) => {
        this.inventory[item] -= quantity;
