class Trade {
  constructor() {
    this.resources = { gold: 100, wood: 50, stone: 30 };
  }

  buy(resource, amount) {
    if (this.resources[resource] >= amount) {
      this.resources[resource] -= amount;
      return true;
    }
    return false;
  }

  sell(resource, amount) {
    this.resources[resource] += amount;
    return true;
  }

  getResources() {
    return { ...this.resources };
  }
}

class Reputation {
  constructor() {
    this.standing = 0;
  }

  improve(amount) {
    this.standing += amount;
  }

  degrade(amount) {
    this.standing -= amount;
  }

  getStanding() {
    return this.standing;
  }
}

class Faction {
  constructor() {
    this.allies = [];
    this.enemies = [];
  }

  allyWith(factionName) {
    if (!this.enemies.includes(factionName)) {
      this.allies.push(factionName);
    }
  }

  declareWar(factionName) {
    if (!this.allies.includes(factionName)) {
      this.enemies.push(factionName);
    }
  }

  getRelations() {
    return { allies: [...this.allies], enemies: [...this.enemies] };
  }
}

class Coordinator {
  constructor() {
    this.trade = new Trade();
    this.reputation = new Reputation();
    this.faction = new Faction();
  }

  executeTrade(resource, amount, isBuy) {
    if (isBuy) {
      const success = this.trade.buy(resource, amount);
      if (success) {
        this.reputation.degrade(5); // Buying degrades reputation slightly
      }
      return success;
    } else {
      const success = this.trade.sell(resource, amount);
      if (success) {
        this.reputation.improve(3); // Selling improves reputation slightly
      }
      return success;
    }
  }

  changeReputation(amount) {
    this.reputation.improve(amount);
  }

  formAlliance(factionName) {
    this.faction.allyWith(factionName);
    this.reputation.improve(10); // Forming an alliance improves reputation
  }

  declareWarOn(factionName) {
    this.faction.declareWar(factionName);
    this.reputation.degrade(15); // Declaring war degrades reputation
  }

  getStatus() {
    return {
      resources: this.trade.getResources(),
      reputation: this.reputation.getStanding(),
      relations: this.faction.getRelations(),
    };
  }
}

