class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount <= 0) throw new Error("Deposit amount must be positive");
    this.balance += amount;
  }

  withdraw(amount) {
    if (amount <= 0) throw new Error("Withdrawal amount must be positive");
    if (amount > this.balance) throw new Error("Insufficient funds");
    this.balance -= amount;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor() {
    this.prices = {
      apple: 1,
      bread: 2,
      cheese: 3
    };
  }

  getPrice(item) {
    if (!this.prices[item]) throw new Error("Item not available in market");
    return this.prices[item];
  }

  buy(item, quantity, bank) {
    const pricePerItem = this.getPrice(item);
    const totalCost = pricePerItem * quantity;
    bank.withdraw(totalCost);
  }
}

class Inventory {
  constructor() {
    this.items = {
      apple: 0,
      bread: 0,
      cheese: 0
    };
  }

  addItem(item, quantity) {
    if (quantity <= 0) throw new Error("Quantity must be positive");
    this.items[item] += quantity;
  }

  getItemCount(item) {
    return this.items[item];
  }
}

class Coordinator {
  constructor(bank, market, inventory) {
    this.bank = bank;
    this.market = market;
    this.inventory = inventory;
  }

  buyItem(item, quantity) {
    const pricePerItem = this.market.getPrice(item);
    const totalCost = pricePerItem * quantity;

    if (this.bank.getBalance() < totalCost) {
      console.log(`Insufficient funds to buy ${quantity} ${item}(s)`);
      return;
    }

    this.market.buy(item, quantity, this.bank);
    this.inventory.addItem(item, quantity);

    console.log(`Bought ${quantity} ${item}(s) for ${totalCost}.`);
    console.log(`Remaining balance: ${this.bank.getBalance()}`);
    console.log(`Inventory: ${this.inventory.getItemCount(item)} ${item}(s)`);
  }
}

