class Economy {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    getBalance() {
        return this.balance;
    }

    addFunds(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    subtractFunds(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }
}

class Store {
    constructor() {
        this.items = {};
    }

    addItem(itemName, price) {
        if (price > 0) {
            this.items[itemName] = price;
            return true;
        }
        return false;
    }

    getItemPrice(itemName) {
        return this.items[itemName] || null;
    }

    getItems() {
        return Object.keys(this.items);
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(itemName, quantity) {
        if (quantity > 0) {
            this.items[itemName] = (this.items[itemName] || 0) + quantity;
            return true;
        }
        return false;
    }

    removeItem(itemName, quantity) {
        if (this.items[itemName] >= quantity) {
            this.items[itemName] -= quantity;
            if (this.items[itemName] === 0) {
                delete this.items[itemName];
            }
            return true;
        }
        return false;
    }

    getItemCount(itemName) {
        return this.items[itemName] || 0;
    }

    getInventory() {
        return this.items;
    }
}

