        const price = this.store.getItemPrice(itemName);
        if (price !== null && this.economy.subtractFunds(price)) {
            this.inventory.addItem(itemName, 1);
            console.log(`Bought ${itemName} for ${price}. Remaining balance: ${this.economy.getBalance()}`);
            return true;
        }
        console.log(`Failed to buy ${itemName}.`);
        return false;
    }

    sellItem(itemName) {
        const quantity = this.inventory.getItemCount(itemName);
        if (quantity > 0) {
            const price = this.store.getItemPrice(itemName);
            if (price !== null) {
                this.economy.addFunds(price);
                this.inventory.removeItem(itemName, 1);
                console.log(`Sold ${itemName} for ${price}. New balance: ${this.economy.getBalance()}`);
                return true;
            }
        }
        console.log(`Failed to sell ${itemName}.`);
        return false;
    }

    displayStatus() {
