class Trade {
  constructor() {
    this.resources = { gold: 0, wood: 0, stone: 0 };
  }

  getResources() {
    return { ...this.resources };
  }

  trade(tradeOffer) {
    for (const resource in tradeOffer) {
      if (this.resources[resource] >= tradeOffer[resource]) {
        this.resources[resource] -= tradeOffer[resource];
      } else {
        throw new Error(`Insufficient ${resource}`);
      }
    }
  }

  receive(tradeOffer) {
    for (const resource in tradeOffer) {
      this.resources[resource] = (this.resources[resource] || 0) + tradeOffer[resource];
    }
  }
}

class Reputation {
  constructor() {
    this.standing = 0;
  }

  getStanding() {
    return this.standing;
  }

  improve(amount) {
    this.standing += amount;
  }

  degrade(amount) {
    this.standing -= amount;
  }
}

class Faction {
