        this.energyRate = energyRate;
    }

    update() {
        this.currentEnergy += this.energyRate;
        if (this.currentEnergy > 100) this.currentEnergy = 100;
        console.log(`Energy level: ${this.currentEnergy}`);
    }

    consume(amount) {
        this.currentEnergy -= amount;
        if (this.currentEnergy < 0) this.currentEnergy = 0;
        console.log(`Used ${amount} energy, new energy level: ${this.currentEnergy}`);
    }
}

