// Economy class to handle prices and transactions
class Economy {
  constructor() {
    this.prices = {
      'sword': 10,
      'potion': 5,
      'shield': 15
    };
    this.balance = 100; // Initial balance for the economy
  }

  getBalance() {
    return this.balance;
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  debit(amount) {
    if (amount > this.balance) {
      return false; // Not enough balance
    }
    this.balance -= amount;
    return true;
  }
}

// Wallet class to handle user's money
class Wallet {
  constructor(economy) {
    this.economy = economy;
    this.balance = 0;
  }

  deposit(amount) {
    this.balance += amount;
  }

  withdraw(amount) {
    if (amount > this.balance) {
      return false; // Not enough money in wallet
    }
    this.balance -= amount;
    return true;
  }

  getBalance() {
    return this.balance;
  }

  transferToEconomy(amount) {
    if (this.withdraw(amount)) {
      this.economy.debit(amount);
      return true;
    }
    return false;
  }
}

// Inventory class to handle items
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  getInventory() {
    return this.items;
  }
}

// Shop class to handle purchases
class Shop {
  constructor(economy, wallet, inventory) {
    this.economy = economy;
    this.wallet = wallet;
    this.inventory = inventory;
  }

  purchaseItem(item) {
    const price = this.economy.getPrice(item);
    if (price === 0) {
      console.log(`Item ${item} not found.`);
      return false;
    }

    if (this.wallet.transferToEconomy(price)) {
      this.inventory.addItem(item);
      console.log(`Purchased ${item} for ${price}.`);
      return true;
    } else {
      console.log(`Insufficient funds to purchase ${item}.`);
      return false;
    }
  }
}

