    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Shop {
  constructor(items = {}) {
    this.items = items; // { itemId: { name, price } }
  }

  getItemPrice(itemId) {
    return this.items[itemId]?.price || null;
  }

  listItems() {
    return Object.keys(this.items).map(id => ({
      id,
      name: this.items[id].name,
      price: this.items[id].price
    }));
  }
}

class Inventory {
  constructor(items = {}) {
    this.items = items; // { itemId: quantity }
  }

  addItem(itemId, quantity = 1) {
    if (quantity > 0) {
      this.items[itemId] = (this.items[itemId] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(itemId, quantity = 1) {
    if (quantity > 0 && this.items[itemId] >= quantity) {
      this.items[itemId] -= quantity;
      if (this.items[itemId] === 0) {
        delete this.items[itemId];
      }
      return true;
    }
    return false;
  }

  getItemCount(itemId) {
    return this.items[itemId] || 0;
  }
}

