class RarityTable {
  constructor() {
    this.rarityWeights = {
      Common: 0.6,
      Uncommon: 0.3,
      Rare: 0.09,
      Epic: 0.01
    };
  }

  getRandomLoot() {
    const rarities = Object.keys(this.rarityWeights);
    const weights = Object.values(this.rarityWeights);
    const totalWeight = weights.reduce((acc, weight) => acc + weight, 0);
    let random = Math.random() * totalWeight;

    for (let i = 0; i < rarities.length; i++) {
      random -= weights[i];
      if (random < 0) {
        const rarity = rarities[i];
        const value = Math.floor(Math.random() * (100 * (i + 1))) + 1;
        return new Loot(`Item-${i}`, rarity, value);
      }
    }
    return null;
  }
}

