class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}, new balance: ${this.balance}`);
    } else {
      console.log("Deposit amount must be positive");
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}, new balance: ${this.balance}`);
    } else {
      console.log("Insufficient funds or invalid amount");
    }
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor() {
    this.prices = {
      apple: 1,
      banana: 2,
      carrot: 3
    };
  }

  getPrices() {
    return { ...this.prices };
  }

  buy(item, quantity) {
    if (this.prices[item] !== undefined && quantity > 0) {
      const totalCost = this.prices[item] * quantity;
      console.log(`Bought ${quantity} ${item}(s) for ${totalCost}`);
      return totalCost;
    } else {
      console.log("Invalid item or quantity");
      return 0;
    }
  }
}

class Inventory {
  constructor() {
    this.items = {
      apple: 0,
      banana: 0,
      carrot: 0
    };
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] += quantity;
      console.log(`Added ${quantity} ${item}(s), new count: ${this.items[item]}`);
    } else {
      console.log("Invalid quantity");
    }
  }

  getInventory() {
    return { ...this.items };
  }
}

class GameCoordinator {
  constructor() {
    this.bank = new Bank();
    this.market = new Market();
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    const totalCost = this.market.buy(item, quantity);
    if (totalCost > 0 && this.bank.getBalance() >= totalCost) {
      this.bank.withdraw(totalCost);
      this.inventory.addItem(item, quantity);
      console.log(`Transaction successful: ${quantity} ${item}(s) purchased and added to inventory.`);
    } else {
      console.log("Transaction failed: insufficient funds or invalid item.");
    }
  }

  checkStatus() {
    console.log("Bank Balance:", this.bank.getBalance());
    console.log("Market Prices:", this.market.getPrices());
    console.log("Inventory:", this.inventory.getInventory());
  }
}

