class EventBus {
  constructor() {
    this.listeners = {};
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }
}

class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients; // { item: quantity }
    this.result = result; // { item: quantity }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {}; // { item: quantity }
    this.eventBus.subscribe('craft', this.handleCraft.bind(this));
  }

  addItem(item, quantity) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
    console.log(`Added ${quantity} ${item} to inventory.`);
  }

  hasIngredients(recipe) {
    for (const [item, quantity] of Object.entries(recipe.ingredients)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  consumeIngredients(recipe) {
    for (const [item, quantity] of Object.entries(recipe.ingredients)) {
      this.items[item] -= quantity;
    }
  }

  handleCraft(recipe) {
    if (this.hasIngredients(recipe)) {
      this.consumeIngredients(recipe);
      this.addItem(recipe.result.item, recipe.result.quantity);
      console.log(`Crafted ${recipe.result.quantity} ${recipe.result.item}.`);
    } else {
      console.log(`Not enough ingredients to craft ${recipe.name}.`);
    }
  }
}

class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
    console.log(`Added recipe for ${recipe.name}.`);
  }

  craft(name) {
    const recipe = this.recipes.find(r => r.name === name);
    if (recipe) {
      this.eventBus.emit('craft', recipe);
    } else {
      console.log(`No recipe found for ${name}.`);
    }
  }
}

