    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(listener);
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(listener => listener(data));
    }
  }
}

class Trade {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('tradeOffer', this.handleTradeOffer.bind(this));
  }

  makeTradeOffer(item, quantity, faction) {
    console.log(`Making trade offer for ${quantity} ${item} to ${faction}`);
    this.eventBus.emit('tradeOfferAccepted', { item, quantity, faction });
  }

  handleTradeOffer(data) {
    console.log(`Received trade offer for ${data.quantity} ${data.item} from ${data.faction}`);
    // Simulate trade acceptance
    this.eventBus.emit('tradeCompleted', { item: data.item, quantity: data.quantity, faction: data.faction });
  }
}

class Reputation {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.reputations = {};
    this.eventBus.subscribe('tradeCompleted', this.updateReputation.bind(this));
    this.eventBus.subscribe('reputationChange', this.applyReputationChange.bind(this));
  }

  updateReputation(data) {
    console.log(`Trade completed with ${data.faction}, updating reputation.`);
    if (!this.reputations[data.faction]) {
      this.reputations[data.faction] = 0;
    }
    this.reputations[data.faction] += 10;
    console.log(`${data.faction} reputation is now ${this.reputations[data.faction]}`);
    this.eventBus.emit('reputationChange', { faction: data.faction, change: 10 });
  }

  applyReputationChange(data) {
    console.log(`Applying reputation change of ${data.change} to ${data.faction}`);
    this.reputations[data.faction] = (this.reputations[data.faction] || 0) + data.change;
    console.log(`${data.faction} reputation is now ${this.reputations[data.faction]}`);
  }
}

class Faction {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('tradeCompleted', this.onTradeCompleted.bind(this));
  }

  onTradeCompleted(data) {
    console.log(`Trade completed with ${data.faction}, faction records updated.`);
  }
}

