        this.balance = initialBalance;
    }

    addMoney(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    removeMoney(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

