class Loot {
  constructor(lootTable) {
    this.lootTable = lootTable;
  }

  generateLoot() {
    const loot = {};
    for (const [item, chance] of Object.entries(this.lootTable)) {
      if (Math.random() < chance) {
        loot[item] = (loot[item] || 0) + 1;
      }
    }
    return loot;
  }
}

class RarityTable {
  constructor() {
    this.rarityTable = {
      common: 0.7,
      uncommon: 0.2,
      rare: 0.08,
      epic: 0.01,
      legendary: 0.005
    };
  }

  getRarityTable() {
    return this.rarityTable;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    this.items[item] = (this.items[item] || 0) + quantity;
  }

  getInventory() {
    return this.items;
  }
}

class GameCoordinator {
  constructor() {
    const rarityTable = new RarityTable();
    const lootTable = rarityTable.getRarityTable();
    this.lootSystem = new Loot(lootTable);
    this.inventorySystem = new Inventory();
  }

  performLootAndStore() {
    const loot = this.lootSystem.generateLoot();
    for (const [item, quantity] of Object.entries(loot)) {
      this.inventorySystem.addItem(item, quantity);
    }
  }

  displayInventory() {
    console.log("Current Inventory:", this.inventorySystem.getInventory());
  }
}

