class Demand {
  constructor(initialDemand) {
    this.currentDemand = initialDemand;
  }

  adjustDemand(change) {
    this.currentDemand += change;
    return this.currentDemand;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sell(quantity) {
    if (this.demand.currentDemand >= quantity) {
      this.demand.adjustDemand(-quantity);
      const totalPrice = this.pricing.calculatePrice(quantity);
      console.log(`Sold ${quantity} items for $${totalPrice}`);
      return totalPrice;
    } else {
      console.log('Not enough demand to fulfill the order');
      return 0;
    }
  }
}

