class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }
}

// RarityTable System
class RarityTable {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.rarityMap = {
      common: 0.7,
      uncommon: 0.2,
      rare: 0.08,
      legendary: 0.02
    };

    this.eventBus.subscribe('generateLoot', this.handleGenerateLoot.bind(this));
  }

  handleGenerateLoot() {
    const roll = Math.random();
    let rarity;
    if (roll < this.rarityMap.common) {
      rarity = 'common';
    } else if (roll < this.rarityMap.common + this.rarityMap.uncommon) {
      rarity = 'uncommon';
    } else if (roll < this.rarityMap.common + this.rarityMap.uncommon + this.rarityMap.rare) {
      rarity = 'rare';
    } else {
      rarity = 'legendary';
    }
    this.eventBus.emit('lootGenerated', { rarity });
  }
}

// Inventory System
class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = [];

    this.eventBus.subscribe('lootGenerated', this.handleLootGenerated.bind(this));
  }

