class Inventory {
    constructor(items = {}) {
        this.items = items; // { itemName: quantity }
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    hasItems(recipeIngredients) {
        for (const [item, quantity] of Object.entries(recipeIngredients)) {
            if (!this.items[item] || this.items[item] < quantity) {
                return false;
            }
        }
        return true;
    }

    getItems() {
        return this.items;
    }
}

class Crafting {
    constructor(inventory, recipes) {
        this.inventory = inventory;
        this.recipes = recipes; // { recipeName: Recipe }
    }

    addRecipe(recipe) {
        this.recipes[recipe.getName()] = recipe;
    }

    craft(recipeName) {
        const recipe = this.recipes[recipeName];
        if (!recipe) {
            console.log(`Recipe "${recipeName}" does not exist.`);
            return false;
        }

        const ingredients = recipe.getIngredients();
        if (this.inventory.hasItems(ingredients)) {
            for (const [item, quantity] of Object.entries(ingredients)) {
                this.inventory.removeItem(item, quantity);
            }
            console.log(`Crafted "${recipeName}".`);
            return true;
        } else {
            console.log(`Insufficient ingredients to craft "${recipeName}".`);
            return false;
        }
    }
}

