    if (this.checkResources(cost)) {
      this.deductResources(cost);
      this.buildings[type] = (this.buildings[type] || 0) + 1;
      console.log(`Built ${type}`);
      this.eventBus.emit('buildingBuilt', { type });
    } else {
      console.log(`Not enough resources to build ${type}`);
