      if (this.resources[resource] < amount) {
        return false;
      }
    }
    return true;
  }

  deductResources(cost) {
    for (let [resource, amount] of Object.entries(cost)) {
      this.resources[resource] -= amount;
    }
  }

  onResourceGenerated(data) {
    this.resources = { ...this.resources, ...data };
  }
