class Pricing {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('store.productSold', this.onProductSold.bind(this));
    }

    setBasePrice(product, price) {
        this.basePrices = this.basePrices || {};
        this.basePrices[product] = price;
        this.eventBus.emit('pricing.basePriceSet', { product, price });
    }

    onProductSold(data) {
        const { product } = data;
        if (this.basePrices && this.basePrices[product]) {
            const newPrice = this.basePrices[product] * 0.95; // 5% discount after each sale
            this.setBasePrice(product, newPrice);
        }
    }
}

class Demand {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('store.productSold', this.onProductSold.bind(this));
        this.demand = {};
    }

    getDemand(product) {
        return this.demand[product] || 0;
    }

    onProductSold(data) {
        const { product } = data;
        this.demand[product] = (this.demand[product] || 0) + 1;
        this.eventBus.emit('demand.update', { product, demand: this.demand[product] });
    }
}

class Store {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.inventory = {};
    }

    stockProduct(product, quantity) {
        this.inventory[product] = (this.inventory[product] || 0) + quantity;
        this.eventBus.emit('store.productStocked', { product, quantity });
    }

    sellProduct(product) {
        if (this.inventory[product] > 0) {
            this.inventory[product]--;
            this.eventBus.emit('store.productSold', { product });
            console.log(`Sold ${product}. Remaining stock: ${this.inventory[product]}`);
        } else {
            console.log(`Out of stock for ${product}`);
        }
    }
}

