      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
      return true;
    } else {
      console.log(`Insufficient funds. Balance: ${this.balance}`);
      return false;
    }
  }

  handleBuyItem({ price, itemId }) {
    if (this.withdraw(price)) {
      this.eventBus.emit('itemBought', { itemId, price });
    }
  }
}

