            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    hasIngredients(recipe) {
        for (const [ingredient, requiredQuantity] of Object.entries(recipe.ingredients)) {
            if (!this.items[ingredient] || this.items[ingredient] < requiredQuantity) {
                return false;
            }
        }
        return true;
    }
}

class Crafting {
    constructor(inventory) {
        this.inventory = inventory;
        this.recipes = [];
    }

    addRecipe(recipe) {
        this.recipes.push(recipe);
    }

    canCraft(recipeName) {
        const recipe = this.recipes.find(r => r.name === recipeName);
        if (!recipe) return false;
        return this.inventory.hasIngredients(recipe);
    }

    craft(recipeName) {
        const recipe = this.recipes.find(r => r.name === recipeName);
        if (!recipe || !this.inventory.hasIngredients(recipe)) return false;

        for (const [ingredient, quantity] of Object.entries(recipe.ingredients)) {
            this.inventory.removeItem(ingredient, quantity);
        }

        console.log(`Crafted: ${recipeName}`);
        return true;
    }
}

