class RarityTable {
  constructor() {
    this.table = {
      common: 50,
      uncommon: 30,
      rare: 15,
      epic: 5
    };
  }

  rollRarity() {
    const total = Object.values(this.table).reduce((sum, value) => sum + value, 0);
    const roll = Math.floor(Math.random() * total);
    let cumulative = 0;

    for (const [rarity, weight] of Object.entries(this.table)) {
      cumulative += weight;
      if (roll < cumulative) {
        return rarity;
      }
    }

    return 'common'; // Default to common if no match found
  }
}

