class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices;
  }

  buy(item, bank) {
    const price = this.prices[item];
    if (price && bank.withdraw(price)) {
      return { success: true, item, price };
    }
    return { success: false };
  }

  sell(item, bank) {
    const price = this.prices[item];
    if (price && bank.deposit(price)) {
      return { success: true, item, price };
    }
    return { success: false };
  }

  getPrice(item) {
    return this.prices[item];
  }
}

class Inventory {
