class Crafting {
  constructor(recipes) {
    this.recipes = {};
    recipes.forEach(recipe => {
      this.recipes[recipe.name] = recipe;
    });
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes[recipeName];
    if (!recipe) return false;
    return recipe.ingredients.every(([item, quantity]) => inventory.hasItem(item, quantity));
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes[recipeName];
    if (!recipe) return false;
    if (!this.canCraft(recipeName, inventory)) return false;

    recipe.ingredients.forEach(([item, quantity]) => {
      inventory.removeItem(item, quantity);
    });

    inventory.addItem(recipe.result);
    return true;
  }
}

