    this.eventBus = eventBus;
    this.balance = 0;

    this.eventBus.subscribe('itemSold', this.handleItemSold.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited ${amount}. New balance: ${this.balance}`);
  }

  withdraw(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
      return true;
    } else {
      console.log(`Insufficient funds. Current balance: ${this.balance}`);
      return false;
    }
  }

  handleItemSold(data) {
    const { price } = data;
    this.deposit(price);
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {
      'sword': { price: 50 },
      'shield': { price: 30 },
      'potion': { price: 10 }
    };
  }

  sellItem(itemName) {
