class Crop {
    constructor(name, growthTime) {
        this.name = name;
        this.growthTime = growthTime; // in days
        this.daysGrown = 0;
    }

    grow() {
        this.daysGrown++;
    }

    isReady() {
        return this.daysGrown >= this.growthTime;
    }

    harvest() {
        if (this.isReady()) {
            const harvestAmount = Math.floor(Math.random() * 5) + 1; // 1-5 units
            this.daysGrown = 0;
            return harvestAmount;
        }
        return 0;
    }
}

class Farm {
    constructor(market) {
        this.market = market;
        this.crops = [];
    }

    plantCrop(crop) {
        this.crops.push(crop);
    }

    simulateDay() {
        this.crops.forEach(crop => crop.grow());
        const readyCrops = this.crops.filter(crop => crop.isReady());
        readyCrops.forEach(crop => {
            const harvestAmount = crop.harvest();
            this.market.sellCrop(crop.name, harvestAmount);
        });
    }
}

