  constructor() {
    this.rarityMap = {
      common: 70,
      uncommon: 20,
      rare: 5,
      legendary: 1
    };
  }

  getRandomItem() {
    const total = Object.values(this.rarityMap).reduce((acc, val) => acc + val, 0);
    const random = Math.floor(Math.random() * total);

    let cumulative = 0;
    for (const [rarity, chance] of Object.entries(this.rarityMap)) {
      cumulative += chance;
      if (random < cumulative) {
        return rarity;
      }
    }
    return 'common'; // Fallback, should never hit
