class Recipe {
    constructor(item, ingredients) {
        this.item = item;
        this.ingredients = ingredients; // { ingredient: amount }
    }
}

class Crafting {
    constructor(recipes) {
        this.recipes = new Map();
        recipes.forEach(recipe => this.recipes.set(recipe.item, recipe));
    }

    canCraft(item, inventory) {
        const recipe = this.recipes.get(item);
        if (!recipe) return false;
        for (const [ingredient, amount] of Object.entries(recipe.ingredients)) {
            if (inventory.getAmount(ingredient) < amount) {
                return false;
            }
        }
        return true;
    }

    craft(item, inventory) {
        const recipe = this.recipes.get(item);
        if (!recipe) return false;
        for (const [ingredient, amount] of Object.entries(recipe.ingredients)) {
            inventory.decreaseAmount(ingredient, amount);
        }
        inventory.increaseAmount(item, 1);
        return true;
    }
}

class Inventory {
    constructor() {
        this.items = new Map();
    }

    increaseAmount(item, amount) {
        this.items.set(item, (this.items.get(item) || 0) + amount);
    }

    decreaseAmount(item, amount) {
        const currentAmount = this.items.get(item) || 0;
        if (currentAmount >= amount) {
            this.items.set(item, currentAmount - amount);
        } else {
            throw new Error(`Not enough ${item} in inventory`);
        }
    }

    getAmount(item) {
        return this.items.get(item) || 0;
    }
}

class Economy {
    constructor(prices) {
        this.prices = prices; // { item: price }
    }

    getPrice(item) {
        return this.prices[item] || 0;
    }

    debit(amount) {
        if (amount > this.balance) {
            throw new Error('Insufficient funds');
        }
        this.balance -= amount;
    }

    getBalance() {
        return this.balance;
    }

    setBalance(balance) {
        this.balance = balance;
    }
}

class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
    }

    purchase(item) {
        const price = this.economy.getPrice(item);
        if (price > 0) {
            this.economy.debit(price);
            this.inventory.increaseAmount(item, 1);
            return true;
        }
        return false;
    }
}

