class EventBus {
    constructor() {
        this.listeners = {};
    }

    subscribe(event, listener) {
        if (!this.listeners[event]) {
            this.listeners[event] = [];
        }
        this.listeners[event].push(listener);
    }

    emit(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(listener => listener(data));
        }
    }
}

class Inventory {
    constructor(eventBus) {
        this.items = {};
        this.eventBus = eventBus;

        this.eventBus.subscribe('itemAdded', this.onItemAdded.bind(this));
        this.eventBus.subscribe('itemRemoved', this.onItemRemoved.bind(this));
    }

    addItem(item, quantity = 1) {
        if (!this.items[item]) {
            this.items[item] = 0;
        }
        this.items[item] += quantity;
        this.eventBus.emit('inventoryUpdated', { item, quantity, action: 'added' });
    }

    removeItem(item, quantity = 1) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            this.eventBus.emit('inventoryUpdated', { item, quantity, action: 'removed' });
        }
    }

    onItemAdded(data) {
        console.log(`Inventory: Added ${data.quantity} ${data.item}(s).`);
    }

    onItemRemoved(data) {
        console.log(`Inventory: Removed ${data.quantity} ${data.item}(s).`);
    }

    hasItem(item, quantity = 1) {
        return this.items[item] && this.items[item] >= quantity;
    }
}

class Recipe {
    constructor(eventBus) {
        this.recipes = {};
        this.eventBus = eventBus;

        this.eventBus.subscribe('recipeAdded', this.onRecipeAdded.bind(this));
        this.eventBus.subscribe('recipeCrafted', this.onRecipeCrafted.bind(this));
    }

    addRecipe(name, ingredients) {
        this.recipes[name] = ingredients;
        this.eventBus.emit('recipeAdded', { name, ingredients });
    }

    craft(name) {
        const recipe = this.recipes[name];
        if (recipe) {
            const inventory = new Inventory(this.eventBus);
            const canCraft = Object.keys(recipe).every(item => inventory.hasItem(item, recipe[item]));
            if (canCraft) {
                Object.keys(recipe).forEach(item => inventory.removeItem(item, recipe[item]));
                this.eventBus.emit('recipeCrafted', { name });
                return true;
            }
        }
        return false;
    }

    onRecipeAdded(data) {
        console.log(`Recipe: Added recipe for ${data.name}.`);
    }

    onRecipeCrafted(data) {
        console.log(`Recipe: Crafted ${data.name}.`);
    }
}

class Crafting {
    constructor(eventBus) {
        this.eventBus = eventBus;

        this.eventBus.subscribe('recipeCrafted', this.onRecipeCrafted.bind(this));
    }

    craftRecipe(name) {
        this.eventBus.emit('recipeCraft', { name });
    }

    onRecipeCrafted(data) {
        console.log(`Crafting: ${data.name} crafted successfully.`);
    }
}

