class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && quantity > 0 && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
    this.prices = {};
  }

  setPrice(item, price) {
    if (price > 0) {
      this.prices[item] = price;
    }
  }

  buyItem(item, quantity = 1) {
    const price = this.prices[item];
    const totalCost = price * quantity;

    if (price && quantity > 0 && this.economy.withdraw(totalCost)) {
      this.inventory.addItem(item, quantity);
      return true;
    }
    return false;
  }

  sellItem(item, quantity = 1) {
    const price = this.prices[item];
    const totalRevenue = price * quantity;

    if (price && quantity > 0 && this.inventory.removeItem(item, quantity)) {
      this.economy.deposit(totalRevenue);
      return true;
    }
    return false;
  }
}

