class Bank {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.balance = 0;
        this.eventBus.subscribe('deposit', this.deposit.bind(this));
        this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
    }

    deposit(amount) {
        this.balance += amount;
        console.log(`Deposited ${amount}, new balance: ${this.balance}`);
        this.eventBus.emit('balanceUpdated', this.balance);
    }

    withdraw(amount) {
        if (amount > this.balance) {
            console.log('Insufficient funds');
            return;
        }
        this.balance -= amount;
        console.log(`Withdrew ${amount}, new balance: ${this.balance}`);
        this.eventBus.emit('balanceUpdated', this.balance);
    }
}

class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.prices = { 'apple': 10, 'banana': 5 };
        this.eventBus.subscribe('sell', this.sell.bind(this));
        this.eventBus.subscribe('buy', this.buy.bind(this));
    }

    sell(item, amount) {
        const price = this.prices[item] || 0;
        const total = price * amount;
        console.log(`Sold ${amount} ${item} for ${total}`);
        this.eventBus.emit('withdraw', total);
    }

    buy(item, amount) {
        const price = this.prices[item] || 0;
        const total = price * amount;
        console.log(`Bought ${amount} ${item} for ${total}`);
        this.eventBus.emit('deposit', total);
    }
}

class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = { 'apple': 0, 'banana': 0 };
        this.eventBus.subscribe('stock', this.stock.bind(this));
        this.eventBus.subscribe('restock', this.restock.bind(this));
    }

    stock(item, amount) {
        this.items[item] = (this.items[item] || 0) - amount;
        console.log(`Stocked ${amount} ${item}, remaining: ${this.items[item]}`);
    }

    restock(item, amount) {
        this.items[item] = (this.items[item] || 0) + amount;
        console.log(`Restocked ${amount} ${item}, new total: ${this.items[item]}`);
    }
}

