class Demand {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('demandUpdateRequest', this.updateDemand.bind(this));
  }

  updateDemand(item) {
    // Simulate demand change
    const newDemand = item.demand + 10; // Increase demand by 10 units
