class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.inventory = [
      { name: 'Widget', price: 10.00, demand: 50 },
      { name: 'Gadget', price: 20.00, demand: 30 }
    ];
    this.eventBus.subscribe('priceUpdated', this.onPriceUpdated.bind(this));
    this.eventBus.subscribe('demandUpdated', this.onDemandUpdated.bind(this));
  }

  requestPriceUpdate(itemName) {
    const item = this.inventory.find(item => item.name === itemName);
    if (item) {
      console.log(`Requesting price update for ${itemName}`);
      this.eventBus.emit('priceUpdateRequest', item);
    } else {
      console.log(`Item ${itemName} not found in inventory.`);
    }
  }

  requestDemandUpdate(itemName) {
    const item = this.inventory.find(item => item.name === itemName);
    if (item) {
      console.log(`Requesting demand update for ${itemName}`);
      this.eventBus.emit('demandUpdateRequest', item);
    } else {
      console.log(`Item ${itemName} not found in inventory.`);
    }
  }

  onPriceUpdated(updatedItem) {
    const index = this.inventory.findIndex(item => item.name === updatedItem.name);
    if (index !== -1) {
      this.inventory[index] = updatedItem;
      console.log(`Inventory updated: ${updatedItem.name} now costs $${updatedItem.price.toFixed(2)}`);
    }
  }

  onDemandUpdated(updatedItem) {
    const index = this.inventory.findIndex(item => item.name === updatedItem.name);
    if (index !== -1) {
      this.inventory[index] = updatedItem;
      console.log(`Inventory updated: ${updatedItem.name} now has demand of ${updatedItem.demand}`);
    }
  }
}

