class RarityTable {
    constructor() {
        this.table = {
            "Common": 50,
            "Uncommon": 30,
            "Rare": 15,
            "Epic": 4,
            "Legendary": 1
        };
    }

    generateLoot() {
        const rarities = Object.keys(this.table);
        const weights = Object.values(this.table);
        const totalWeight = weights.reduce((acc, weight) => acc + weight, 0);

        let random = Math.random() * totalWeight;
        for (let i = 0; i < rarities.length; i++) {
            random -= weights[i];
            if (random < 0) {
                return new Loot(`Item-${i + 1}`, rarities[i]);
            }
        }

        throw new Error("Failed to generate loot");
    }
}

