class Bank {
    constructor() {
        this.balance = 0;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor() {
        this.prices = {};
    }

    setPrice(item, price) {
        if (price >= 0) {
            this.prices[item] = price;
            return true;
        }
        return false;
    }

    getPrice(item) {
        return this.prices[item] !== undefined ? this.prices[item] : null;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (quantity > 0) {
            if (this.items[item]) {
                this.items[item] += quantity;
            } else {
                this.items[item] = quantity;
            }
            return true;
        }
        return false;
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    getItemCount(item) {
        return this.items[item] !== undefined ? this.items[item] : 0;
    }
}

class Coordinator {
    constructor() {
        this.bank = new Bank();
        this.market = new Market();
        this.inventory = new Inventory();
    }

    buyItem(item, quantity) {
        const price = this.market.getPrice(item);
        const totalCost = price * quantity;

        if (price !== null && this.bank.withdraw(totalCost)) {
            this.inventory.addItem(item, quantity);
            return true;
        }
        return false;
    }

    sellItem(item, quantity) {
        const price = this.market.getPrice(item);
        const totalEarnings = price * quantity;

        if (this.inventory.removeItem(item, quantity)) {
            this.bank.deposit(totalEarnings);
            return true;
        }
        return false;
    }

    displayStatus() {
        console.log(`Bank Balance: $${this.bank.getBalance()}`);
        console.log('Market Prices:');
        Object.keys(this.market.prices).forEach(item => {
            console.log(`  ${item}: $${this.market.prices[item]}`);
        });
        console.log('Inventory:');
        Object.keys(this.inventory.items).forEach(item => {
            console.log(`  ${item}: ${this.inventory.items[item]}`);
        });
    }
}

