    if (this.canCraft(inventory)) {
      for (let ingredient of this.ingredients) {
        inventory.removeItem(ingredient.item, ingredient.amount);
      }
      inventory.addItem(this.result.item, this.result.amount);
      return true;
    }
    return false;
  }
}

class Crafting {
  constructor(recipes) {
    this.recipes = recipes; // Array of Recipe instances
  }

  getRecipes() {
    return this.recipes;
  }

  craftRecipe(recipeName, inventory) {
    let recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe) {
      return recipe.craft(inventory);
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { 'item1': amount, 'item2': amount, ... }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }

  addItem(item, amount) {
    this.items[item] = (this.items[item] || 0) + amount;
  }

  removeItem(item, amount) {
    if (this.items[item] >= amount) {
      this.items[item] -= amount;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
    }
  }
}

class Economy {
  constructor(prices) {
    this.prices = prices; // { 'item1': price, 'item2': price, ... }
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  debit(item, amount) {
    if (this.prices[item] && this.prices[item] >= amount) {
      this.prices[item] -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  buyItem(item, amount) {
    let price = this.economy.getPrice(item);
    if (price * amount <= this.economy.getPrice('money')) {
      if (this.economy.debit('money', price * amount)) {
        this.inventory.addItem(item, amount);
        return true;
      }
    }
    return false;
  }
}

