class CombatSystem {
  constructor() {
    this.listeners = [];
  }

  // Public API: Register a listener for combat events
  onCombatEvent(callback) {
    this.listeners.push(callback);
  }

  // Public API: Trigger a combat event
  triggerCombatEvent(attacker, defender, damage) {
    this.listeners.forEach(callback => callback({ attacker, defender, damage }));
  }
}

class HealthSystem {
  constructor() {
    this.health = { attacker: 100, defender: 100 };
  }

  // Public API: Get current health
  getHealth(entity) {
    return this.health[entity];
  }

  // Public API: Apply damage to an entity
  applyDamage(entity, damage) {
    if (this.health[entity] > 0) {
      this.health[entity] -= damage;
      if (this.health[entity] < 0) {
        this.health[entity] = 0;
      }
    }
  }
}

class LootSystem {
  constructor() {
    this.loot = { attacker: 0, defender: 0 };
  }

  // Public API: Get current loot
  getLoot(entity) {
    return this.loot[entity];
  }

  // Public API: Award loot to an entity
  awardLoot(entity, amount) {
    this.loot[entity] += amount;
  }
}

// Top-level coordinator
class GameCoordinator {
  constructor() {
    this.combat = new CombatSystem();
    this.health = new HealthSystem();
    this.loot = new LootSystem();

    // Wire the systems together
    this.combat.onCombatEvent(({ attacker, defender, damage }) => {
      this.health.applyDamage(defender, damage);
      this.loot.awardLoot(attacker, 5); // Example: attacker gains 5 loot for each hit
      console.log(`${attacker} hits ${defender} for ${damage} damage. ${defender} now has ${this.health.getHealth(defender)} health.`);
      console.log(`${attacker} gains 5 loot. Total loot: ${this.loot.getLoot(attacker)}`);
    });
  }

  // Public API: Start a combat round
  startCombatRound(attacker, defender, damage) {
    this.combat.triggerCombatEvent(attacker, defender, damage);
  }
}

// Runnable demo
