class Hunger {
  constructor(initialLevel, maxLevel, consumptionRate) {
    this.level = initialLevel;
    this.maxLevel = maxLevel;
    this.consumptionRate = consumptionRate;
  }

  decrease() {
    this.level = Math.max(0, this.level - this.consumptionRate);
  }

  eat(amount) {
    this.level = Math.min(this.maxLevel, this.level + amount);
  }

  getLevel() {
    return this.level;
  }
}

class Energy {
  constructor(initialLevel, maxLevel, consumptionRate, regenerationRate) {
    this.level = initialLevel;
    this.maxLevel = maxLevel;
    this.consumptionRate = consumptionRate;
    this.regenerationRate = regenerationRate;
  }

  decrease() {
    this.level = Math.max(0, this.level - this.consumptionRate);
  }

  regenerate(amount) {
    this.level = Math.min(this.maxLevel, this.level + amount);
  }

  getLevel() {
    return this.level;
  }
}

class Clock {
  constructor(onTick) {
    this.onTick = onTick;
    this.time = 0;
  }

  tick() {
    this.time++;
    this.onTick();
  }

  getTime() {
    return this.time;
  }
}

