class Recipe {
    constructor(item, ingredients) {
        this.item = item;
        this.ingredients = ingredients;
    }

    matches(ingredients) {
        for (let [ingredient, amount] of Object.entries(this.ingredients)) {
            if (ingredients[ingredient] < amount) {
                return false;
            }
        }
        return true;
    }

    consumeIngredients(ingredients) {
        for (let [ingredient, amount] of Object.entries(this.ingredients)) {
            ingredients[ingredient] -= amount;
        }
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, amount = 1) {
        if (this.items[item]) {
            this.items[item] += amount;
        } else {
            this.items[item] = amount;
        }
    }

    removeItem(item, amount = 1) {
        if (this.items[item] && this.items[item] >= amount) {
            this.items[item] -= amount;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
        }
    }

    hasItem(item, amount = 1) {
        return this.items[item] && this.items[item] >= amount;
    }

    getItems() {
        return { ...this.items };
    }
}

class Crafting {
    constructor() {
        this.recipes = [];
    }

    addRecipe(recipe) {
        this.recipes.push(recipe);
    }

    canCraft(recipe, ingredients) {
        return recipe.matches(ingredients);
    }

    craft(recipe, ingredients) {
        if (this.canCraft(recipe, ingredients)) {
            recipe.consumeIngredients(ingredients);
            return true;
        }
        return false;
    }
}

class Coordinator {
    constructor() {
        this.inventory = new Inventory();
        this.crafting = new Crafting();
    }

    addRecipe(recipe) {
        this.crafting.addRecipe(recipe);
    }

    addItemToInventory(item, amount) {
        this.inventory.addItem(item, amount);
    }

    craftItem(item) {
        const recipe = this.crafting.recipes.find(r => r.item === item);
        if (recipe) {
            if (this.crafting.craft(recipe, this.inventory.getItems())) {
                this.inventory.addItem(item);
                console.log(`Crafted ${item}`);
                return true;
            } else {
                console.log(`Cannot craft ${item}: insufficient ingredients`);
                return false;
            }
        }
        console.log(`No recipe found for ${item}`);
        return false;
    }

    showInventory() {
        console.log('Inventory:', this.inventory.getItems());
    }
}

