    return this.items[item]?.price || 0;
  }

  listItems() {
    return Object.keys(this.items);
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
