class Crop {
  constructor(type, growthTime) {
    this.type = type;
    this.growthTime = growthTime;
    this.age = 0;
  }

  grow(timePassed) {
    this.age += timePassed;
    if (this.age >= this.growthTime) {
      return true;
    }
    return false;
  }

  harvest() {
    console.log(`Harvested ${this.type} crop.`);
    return { type: this.type, quantity: 1 };
  }
}

class Market {
  constructor() {
    this.inventory = {};
  }

  buyCrop(crop, quantity) {
    if (this.inventory[crop.type] >= quantity) {
      this.inventory[crop.type] -= quantity;
      console.log(`Bought ${quantity} ${crop.type} from market.`);
      return true;
    }
    console.log(`Not enough ${crop.type} in market.`);
    return false;
  }

  receiveCrops(crops) {
    crops.forEach(crop => {
      if (this.inventory[crop.type]) {
        this.inventory[crop.type] += crop.quantity;
      } else {
        this.inventory[crop.type] = crop.quantity;
      }
    });
    console.log('Received crops at market.');
  }

  checkInventory() {
    console.log('Market inventory:', this.inventory);
  }
}

