  }

  growCrops(timePassed) {
    this.farm.crops.forEach(crop => crop.grow(timePassed));
  }

  harvestAndSellCrops() {
    const harvestedCrops = this.farm.harvestCrops();
    this.market.receiveCrops(harvestedCrops);
  }

  buyCrop(type, quantity) {
    this.market.buyCrop({ type }, quantity);
  }

  checkMarketInventory() {
    this.market.checkInventory();
  }
}

