    this.quests[id] = { description, completed: false };
  }

  completeQuest(id) {
    if (this.quests[id]) {
      this.quests[id].completed = true;
    }
  }

  getQuestStatus(id) {
    return this.quests[id] ? this.quests[id].completed : false;
  }
