// Coordinator
class Coordinator {
  constructor() {
    this.dialogue = new Dialogue();
    this.flags = new Flags();
    this.quest = new Quest();
  }

  start() {
    this.dialogue.addResponse("greet", "Hello! Welcome to the adventure.");
    this.dialogue.addResponse("questStatus", "Your quest status:");
    this.flags.setFlag("playerAlive", true);
    this.quest.addQuest("findTreasure", "Go find the hidden treasure.");
  }

  interact(input) {
    if (input === "greet") {
      return this.dialogue.getResponse(input);
    } else if (input === "questStatus") {
      let status = this.dialogue.getResponse(input);
      for (let id in this.quest.quests) {
        status += `\n${id}: ${this.quest.getQuestStatus(id) ? "Completed" : "Not Completed"}`;
      }
      return status;
    }
    return "I don't understand that.";
  }

  completeQuest(id) {
    this.quest.completeQuest(id);
  }
}

