class RarityTable {
  constructor(rarityWeights) {
    this.rarityWeights = rarityWeights;
  }

  getRandomRarity() {
    const totalWeight = Object.values(this.rarityWeights).reduce((sum, weight) => sum + weight, 0);
    let random = Math.random() * totalWeight;
    for (let [rarity, weight] of Object.entries(this.rarityWeights)) {
      if (random < weight) {
        return rarity;
      }
      random -= weight;
    }
    return null; // Fallback, should not happen with valid weights
  }
}

