    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
  }

  purchase(item, quantity) {
    const price = this.pricing.getPrice(item);
    const demand = this.demand.getDemand(item);

    if (quantity > demand) {
      console.log(`Not enough demand for ${quantity} ${item}(s). Available demand: ${demand}`);
      return;
    }

