    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  addFunds(amount) {
    this.balance += amount;
  }

  subtractFunds(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor() {
    this.items = {
      'apple': { price: 1, quantity: 10 },
      'banana': { price: 2, quantity: 5 },
      'cherry': { price: 3, quantity: 20 }
    };
