class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = {};

        this.eventBus.subscribe('craft', this.onCraft.bind(this));
    }

    addItem(item, amount = 1) {
        if (!this.items[item]) {
            this.items[item] = 0;
        }
        this.items[item] += amount;
        this.eventBus.emit('inventoryChange', { item, amount: this.items[item] });
    }

    removeItems(items) {
        let canRemove = true;
        for (const [item, amount] of Object.entries(items)) {
            if (!this.items[item] || this.items[item] < amount) {
                canRemove = false;
                break;
            }
        }

        if (canRemove) {
            for (const [item, amount] of Object.entries(items)) {
                this.items[item] -= amount;
                this.eventBus.emit('inventoryChange', { item, amount: this.items[item] });
            }
            return true;
        }
        return false;
    }

    hasItems(items) {
        for (const [item, amount] of Object.entries(items)) {
            if (!this.items[item] || this.items[item] < amount) {
                return false;
            }
        }
        return true;
    }

    onCraft(recipe) {
        if (this.hasItems(recipe.ingredients)) {
            this.removeItems(recipe.ingredients);
            this.addItem(recipe.result);
            console.log(`Crafted: ${recipe.result}`);
        } else {
