        this.eventBus = eventBus;
        this.eventBus.subscribe('craftAttempt', this.handleCraftAttempt.bind(this));
        this.eventBus.subscribe('craftSuccess', this.handleCraftSuccess.bind(this));
        this.eventBus.subscribe('craftFailure', this.handleCraftFailure.bind(this));
    }

    handleCraftAttempt(event) {
        const { name, ingredients } = event;
        let canCraft = true;
        ingredients.forEach(ingredient => {
            if (!this.inventory.hasItem(ingredient.item, ingredient.quantity)) {
                canCraft = false;
            }
        });

        if (canCraft) {
            ingredients.forEach(ingredient => {
                this.inventory.removeItem(ingredient.item, ingredient.quantity);
            });
            this.eventBus.emit('craftSuccess', name);
        } else {
            this.eventBus.emit('craftFailure', name);
        }
    }

    handleCraftSuccess(name) {
        console.log(`Crafting: Successfully crafted ${name}`);
    }

    handleCraftFailure(name) {
        console.log(`Crafting: Failed to craft ${name} due to missing ingredients`);
    }
