// Farm system
class Farm {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.crops = [];

    this.eventBus.subscribe('market:buyCrop', this.buyCrop.bind(this));
  }

  plantCrop(name) {
    const crop = new Crop(name);
    this.crops.push(crop);
    console.log(`Crop ${name} planted.`);
    this.eventBus.emit('farm:cropPlanted', { crop });
  }

  buyCrop({ cropName, quantity }) {
    const availableCrops = this.crops.filter(crop => crop.name === cropName);
    if (availableCrops.length >= quantity) {
      const boughtCrops = availableCrops.splice(0, quantity);
      console.log(`Bought ${quantity} ${cropName} from farm.`);
      this.eventBus.emit('market:sellCrop', { boughtCrops });
    } else {
      console.log(`Not enough ${cropName} available.`);
    }
  }
}

// Crop class
class Crop {
  constructor(name) {
    this.name = name;
  }
}

// Market system
class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.stock = {};

    this.eventBus.subscribe('farm:cropPlanted', this.updateStock.bind(this));
    this.eventBus.subscribe('market:sellCrop', this.sellCrop.bind(this));
  }

  updateStock({ crop }) {
    if (!this.stock[crop.name]) {
      this.stock[crop.name] = 0;
    }
    this.stock[crop.name]++;
