    }
}

class Resource {
    constructor(name, initialAmount) {
        this.name = name;
        this.amount = initialAmount;
    }

    consume(amount) {
        if (amount > this.amount) {
            console.log(`Not enough ${this.name} to consume.`);
            return false;
        }
        this.amount -= amount;
        return true;
    }

    produce(amount) {
        this.amount += amount;
        return true;
    }

    getAmount() {
        return this.amount;
    }
}

class Economy {
    constructor() {
        this.resources = {};
    }

    registerResource(name, initialAmount) {
        if (this.resources[name]) {
            console.log(`${name} resource already registered.`);
            return false;
        }
        this.resources[name] = new Resource(name, initialAmount);
        return true;
    }

    consumeResource(name, amount) {
        const resource = this.resources[name];
        if (!resource) {
            console.log(`${name} resource not found.`);
            return false;
        }
        return resource.consume(amount);
    }

    produceResource(name, amount) {
        const resource = this.resources[name];
        if (!resource) {
            console.log(`${name} resource not found.`);
            return false;
        }
        return resource.produce(amount);
    }

    getResourceAmount(name) {
        const resource = this.resources[name];
        if (!resource) {
            console.log(`${name} resource not found.`);
            return null;
        }
        return resource.getAmount();
    }
}

