      if (this.items[item]) {
        this.items[item] += quantity;
      } else {
        this.items[item] = quantity;
      }
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Shop {
  constructor(economy) {
    this.economy = economy;
  }

  buyItem(item, wallet, inventory) {
    const price = this.economy.getPrice(item);
    if (price !== null && wallet.withdraw(price)) {
      inventory.addItem(item);
      this.economy.debit(price);
      return true;
    }
    return false;
  }
}

