class EventBus {
  constructor() {
    this.events = {};
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(callback => callback(data));
    }
  }

  subscribe(eventName, callback) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(callback);
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemCrafted', this.addItem.bind(this));
  }

  addItem(item) {
    if (this.items[item.name]) {
      this.items[item.name] += item.quantity;
    } else {
      this.items[item.name] = item.quantity;
    }
    console.log(`Inventory updated: ${item.name} x${this.items[item.name]}`);
  }

  hasItem(name, quantity = 1) {
    return (this.items[name] || 0) >= quantity;
  }

  useItem(name, quantity = 1) {
    if (this.hasItem(name, quantity)) {
      this.items[name] -= quantity;
      console.log(`Used ${quantity} ${name}. Remaining: ${this.items[name]}`);
    } else {
      console.log(`Not enough ${name} in inventory.`);
    }
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('craftRequest', this.craft.bind(this));
  }

  addRecipe(name, ingredients) {
    this.recipes[name] = ingredients;
  }

  craft(recipeName) {
    const recipe = this.recipes[recipeName];
    if (recipe) {
      const canCraft = Object.keys(recipe).every(item =>
        this.eventBus.emit('checkItem', { item, quantity: recipe[item] })
      );
      if (canCraft) {
        this.eventBus.emit('itemCrafted', { name: recipeName, quantity: 1 });
        Object.keys(recipe).forEach(item =>
          this.eventBus.emit('useItem', { item, quantity: recipe[item] })
        );
        console.log(`${recipeName} crafted successfully.`);
      } else {
        console.log(`Missing ingredients for ${recipeName}.`);
      }
    } else {
      console.log(`No recipe found for ${recipeName}.`);
    }
  }
}

class Crafting {
  constructor(eventBus, inventory, recipe) {
    this.eventBus = eventBus;
    this.inventory = inventory;
    this.recipe = recipe;
    this.eventBus.subscribe('useItem', this.inventory.useItem.bind(this.inventory));
    this.eventBus.subscribe('checkItem', this.checkItem.bind(this));
  }

  checkItem({ item, quantity }) {
    this.eventBus.emit('inventoryCheck', { item, quantity });
  }

  requestCraft(recipeName) {
    this.eventBus.emit('craftRequest', recipeName);
  }
}

