class EventBus {
  constructor() {
    this.events = {};
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(callback => callback(data));
    }
  }

  subscribe(eventName, callback) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(callback);
  }
}

// Inventory system
class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemUsed', this.useItem.bind(this));
    this.eventBus.subscribe('itemCrafted', this.addItem.bind(this));
  }

  addItem(itemName, quantity) {
    if (this.items[itemName]) {
      this.items[itemName] += quantity;
    } else {
      this.items[itemName] = quantity;
    }
    console.log(`Added ${quantity} ${itemName}(s). Total: ${this.items[itemName]}`);
  }

  removeItem(itemName, quantity) {
    if (this.items[itemName] && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      console.log(`Removed ${quantity} ${itemName}(s). Remaining: ${this.items[itemName]}`);
      return true;
    } else {
      console.log(`Not enough ${itemName}(s) to remove.`);
      return false;
    }
  }

  useItem(itemName, quantity) {
    if (this.removeItem(itemName, quantity)) {
      console.log(`Used ${quantity} ${itemName}(s).`);
    }
  }
}

// Recipe system
class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('craftItem', this.craftItem.bind(this));
  }

  addRecipe(recipeName, ingredients) {
    this.recipes[recipeName] = ingredients;
    console.log(`Added recipe for ${recipeName}:`, ingredients);
  }

  craftItem(recipeName) {
    const ingredients = this.recipes[recipeName];
    if (ingredients) {
      const allIngredientsAvailable = Object.keys(ingredients).every(item => {
        return this.eventBus.emit('checkInventory', { item, quantity: ingredients[item] });
      });

      if (allIngredientsAvailable) {
        Object.keys(ingredients).forEach(item => {
          this.eventBus.emit('useItem', { item, quantity: ingredients[item] });
        });
        this.eventBus.emit('itemCrafted', recipeName);
        console.log(`Crafted ${recipeName} successfully.`);
      } else {
        console.log(`Not enough ingredients to craft ${recipeName}.`);
      }
    } else {
      console.log(`No recipe found for ${recipeName}.`);
    }
  }
}

