class Loot {
  constructor() {
    this.lootTable = {
      common: ['Potion', 'Small Coin'],
      uncommon: ['Scroll', 'Medium Coin'],
      rare: ['Ring', 'Large Coin'],
      legendary: ['Sword', 'Golden Coin']
    };
  }

  generateLoot(rarity) {
    if (this.lootTable[rarity]) {
      const loot = this.lootTable[rarity][Math.floor(Math.random() * this.lootTable[rarity].length)];
      return loot;
    }
    return null;
  }
}

class RarityTable {
  constructor() {
    this.rarityWeights = {
      common: 50,
      uncommon: 30,
      rare: 15,
      legendary: 5
    };
  }

  rollForRarity() {
    const totalWeight = Object.values(this.rarityWeights).reduce((acc, weight) => acc + weight, 0);
    const randomWeight = Math.floor(Math.random() * totalWeight);

    let cumulativeWeight = 0;
    for (const rarity in this.rarityWeights) {
      cumulativeWeight += this.rarityWeights[rarity];
      if (randomWeight < cumulativeWeight) {
        return rarity;
      }
    }
    return null;
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  listItems() {
    return this.items;
  }
}

// Coordinator to wire the systems together
class GameCoordinator {
  constructor() {
    this.lootSystem = new Loot();
    this.raritySystem = new RarityTable();
    this.inventorySystem = new Inventory();
  }

  generateAndStoreLoot() {
    const rarity = this.raritySystem.rollForRarity();
    const loot = this.lootSystem.generateLoot(rarity);
    if (loot) {
      this.inventorySystem.addItem(loot);
      console.log(`Generated and stored loot: ${loot} (Rarity: ${rarity})`);
    } else {
      console.log('No loot generated.');
    }
  }

  displayInventory() {
    const items = this.inventorySystem.listItems();
    console.log('Inventory:', items);
  }
}

// Runnable demo
const coordinator = new GameCoordinator();

// Generate and store loot multiple times
coordinator.generateAndStoreLoot();
coordinator.generateAndStoreLoot();
coordinator.generateAndStoreLoot();

// Display the current inventory
