class Pricing {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.price = 10; // Initial price
        this.eventBus.subscribe('updatePrice', this.handlePriceUpdate.bind(this));
    }

    handlePriceUpdate(priceChange) {
        this.price += priceChange;
        this.eventBus.emit('priceChanged', this.price);
        console.log(`Price updated to: $${this.price}`);
    }

    adjustPrice(change) {
        this.eventBus.emit('updatePrice', change);
    }
}

class Demand {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.demand = 50; // Initial demand
        this.eventBus.subscribe('priceChanged', this.handlePriceChange.bind(this));
    }

    handlePriceChange(newPrice) {
        if (newPrice < 10) {
            this.demand += 10;
        } else if (newPrice > 15) {
            this.demand -= 10;
        }
        this.eventBus.emit('demandChanged', this.demand);
        console.log(`Demand changed to: ${this.demand}`);
    }
}

class Store {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.stock = 100; // Initial stock
        this.eventBus.subscribe('demandChanged', this.handleDemandChange.bind(this));
    }

    handleDemandChange(newDemand) {
        if (newDemand > 60) {
            this.stock += 20;
        } else if (newDemand < 40) {
            this.stock -= 20;
        }
        console.log(`Stock changed to: ${this.stock}`);
    }

    restock(amount) {
        this.stock += amount;
        console.log(`Stock restocked by ${amount}: ${this.stock}`);
    }
}

