class RarityTable {
    constructor() {
        this.rarityWeights = {
            "Common": 0.6,
            "Uncommon": 0.3,
            "Rare": 0.08,
            "Epic": 0.02
        };
    }

    getRandomRarity() {
        const rarities = Object.keys(this.rarityWeights);
        const weights = Object.values(this.rarityWeights);
        let totalWeight = 0;

        weights.forEach(weight => {
            totalWeight += weight;
        });

        let randomWeight = Math.random() * totalWeight;
        let cumulativeWeight = 0;

        for (let i = 0; i < weights.length; i++) {
            cumulativeWeight += weights[i];
            if (randomWeight < cumulativeWeight) {
                return rarities[i];
            }
        }

        return rarities[rarities.length - 1]; // Fallback to last rarity if something goes wrong
    }
}

