        this.attacks = {
            punch: { damage: 10 },
            kick: { damage: 15 }
        };
    }

    attack(attacker, defender, attackType) {
        const attack = this.attacks[attackType];
        if (!attack) return;

        const damage = attack.damage;
        console.log(`${attacker.name} attacks ${defender.name} with ${attackType} for ${damage} damage.`);
