class HealthSystem {
    constructor() {
        this.healthPool = {};
    }

    setHealth(entity, health) {
        this.healthPool[entity.name] = health;
        console.log(`${entity.name} has ${health} health.`);
    }

    takeDamage(entity, damage) {
        if (!this.healthPool[entity.name]) return;

        this.healthPool[entity.name] -= damage;
        console.log(`${entity.name} takes ${damage} damage. Remaining health: ${this.healthPool[entity.name]}.`);

        if (this.healthPool[entity.name] <= 0) {
            console.log(`${entity.name} is defeated.`);
        }
    }

    getHealth(entity) {
        return this.healthPool[entity.name] || 0;
    }
}

class LootSystem {
    constructor() {
        this.lootPool = {
            common: ['potion', 'coin'],
            rare: ['magic scroll', 'gold bar']
        };
    }

    dropLoot(entity) {
        const lootType = Math.random() < 0.5 ? 'common' : 'rare';
        const loot = this.lootPool[lootType];
        const item = loot[Math.floor(Math.random() * loot.length)];
        console.log(`${entity.name} drops a ${item}.`);
        return item;
    }
}

class GameCoordinator {
    constructor() {
        this.combat = new CombatSystem();
        this.health = new HealthSystem();
        this.loot = new LootSystem();
    }

    startCombat(attacker, defender) {
        this.health.setHealth(attacker, 100);
        this.health.setHealth(defender, 100);

        while (this.health.getHealth(attacker) > 0 && this.health.getHealth(defender) > 0) {
            const attackType = Math.random() < 0.5 ? 'punch' : 'kick';
            const damage = this.combat.attack(attacker, defender, attackType);
            this.health.takeDamage(defender, damage);

            if (this.health.getHealth(defender) > 0) {
                const counterDamage = this.combat.attack(defender, attacker, attackType);
                this.health.takeDamage(attacker, counterDamage);
            }
        }

        const winner = this.health.getHealth(attacker) > 0 ? attacker : defender;
        const loot = this.loot.dropLoot(winner);
        console.log(`${winner.name} wins and receives a ${loot}.`);
    }
}

