class Crafting {
  constructor(recipes) {
    this.recipes = new Map(recipes.map(recipe => [recipe.name, recipe]));
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.get(recipeName);
    if (!recipe) return false;

    for (const { item, amount } of recipe.ingredients) {
      if ((inventory.get(item) || 0) < amount) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName, inventory) {
    if (!this.canCraft(recipeName, inventory)) {
      throw new Error('Cannot craft: insufficient ingredients');
    }

    const recipe = this.recipes.get(recipeName);
    for (const { item, amount } of recipe.ingredients) {
      inventory.set(item, (inventory.get(item) || 0) - amount);
    }
    inventory.set(recipe.result.item, (inventory.get(recipe.result.item) || 0) + recipe.result.amount);
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  addItem(item, amount) {
    this.items.set(item, (this.items.get(item) || 0) + amount);
  }

  removeItem(item, amount) {
    if ((this.items.get(item) || 0) < amount) {
      throw new Error('Not enough items to remove');
    }
    this.items.set(item, this.items.get(item) - amount);
  }

  getItems() {
    return new Map(this.items);
  }
}

