      return ingredients[item] <= this.eventBus.inventory.hasItem(item, ingredients[item]);
    });
  }

  craft(result) {
    if (this.canCraft(result)) {
      const ingredients = this.recipes[result];
      Object.keys(ingredients).forEach(item => {
        this.eventBus.inventory.addItem(item, -ingredients[item]);
      });
      this.eventBus.emit('itemCrafted', result);
      console.log(`Crafted ${result}`);
    } else {
      console.log(`Cannot craft ${result}`);
    }
  }
}

class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemCrafted', this.onItemCrafted.bind(this));
  }

  onItemCrafted(item) {
    console.log(`Crafting system: ${item} crafted.`);
  }
}

