class Pricing {
  constructor(basePrice, priceAdjustment) {
    this.basePrice = basePrice;
    this.priceAdjustment = priceAdjustment;
  }

  calculatePrice(quantity) {
    return this.basePrice + (this.priceAdjustment * quantity);
  }
}

class Demand {
  constructor(baseDemand, demandAdjustment) {
    this.baseDemand = baseDemand;
    this.demandAdjustment = demandAdjustment;
  }

  calculateDemand(price) {
    return this.baseDemand - (this.demandAdjustment * price);
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sell(quantity) {
    const price = this.pricing.calculatePrice(quantity);
    const demand = this.demand.calculateDemand(price);
    return { price, demand };
  }
}

