        const price = this.store.getPrice(item);
        if (price !== null) {
            const totalCost = price * quantity;
            if (this.economy.withdraw(totalCost)) {
                this.inventory.addItem(item, quantity);
                return true;
            }
        }
        return false;
    }

    sellItem(item, quantity) {
        if (this.inventory.removeItem(item, quantity)) {
            const price = this.store.getPrice(item);
            if (price !== null) {
                this.economy.deposit(price * quantity);
                return true;
            }
        }
        return false;
    }

    getBalance() {
        return this.economy.getBalance();
    }

    getInventory() {
        return this.inventory.getInventory();
    }

    getAllPrices() {
        return this.store.getAllPrices();
    }
}

