        this.flags = flags;
        this.quest = quest;
    }

    getGreeting() {
        if (this.flags.get('hasMetNpc')) {
            return "Hello again! How's your quest coming along?";
        } else {
            this.flags.set('hasMetNpc', true);
            return "Welcome! I'm the village elder. You look like a traveler. Are you on a quest?";
        }
    }

    getQuestOffer() {
        if (!this.flags.get('questAccepted') && this.quest.getQuestStatus() === 'available') {
            this.flags.set('questAccepted', true);
            return "I have a quest for you. Fetch the mystical gem from the nearby mountain. Return it to me.";
        } else if (this.flags.get('questAccepted') && this.quest.getQuestStatus() === 'completed') {
            return "Thank you for bringing back the gem. You've earned the respect of our village.";
        } else {
            return "Are you still on the quest for the mystical gem?";
        }
    }
}

class Flags {
    constructor() {
        this.flags = {};
    }

    set(flag, value) {
        this.flags[flag] = value;
    }

    get(flag) {
        return this.flags[flag] || false;
    }
}

class Quest {
    constructor() {
        this.status = 'available';
    }

    getQuestStatus() {
        return this.status;
    }

    completeQuest() {
        this.status = 'completed';
    }
}

// Runnable demo
