const quest = new Quest();
const dialogue = new Dialogue(flags, quest);

console.log(dialogue.getGreeting()); // Should print initial greeting
console.log(dialogue.getQuestOffer()); // Should offer the quest

quest.completeQuest();

console.log(dialogue.getGreeting()); // Should print greeting again
console.log(dialogue.getQuestOffer()); // Should confirm quest completion
