class Clock {
    constructor() {
        this.time = 0;
    }

    tick() {
        this.time++;
        console.log(`Time: ${this.time}`);
    }
}

class Hunger {
    constructor(clock) {
        this.hungerLevel = 100;
        this.clock = clock;
        this.clockTimeOfLastMeal = this.clock.time;
    }

    eat(amount) {
        this.hungerLevel -= amount;
        if (this.hungerLevel < 0) this.hungerLevel = 0;
        this.clockTimeOfLastMeal = this.clock.time;
        console.log(`Eaten ${amount}. Hunger level: ${this.hungerLevel}`);
    }

    tick() {
        const currentTime = this.clock.time;
        const timeSinceLastMeal = currentTime - this.clockTimeOfLastMeal;
        this.hungerLevel += timeSinceLastMeal;
        if (this.hungerLevel > 100) this.hungerLevel = 100;
        console.log(`Hunger level: ${this.hungerLevel}`);
    }
}

class Energy {
    constructor(clock) {
        this.energyLevel = 100;
        this.clock = clock;
        this.clockTimeOfLastSleep = this.clock.time;
    }

    sleep(hours) {
        this.energyLevel += hours * 10;
        if (this.energyLevel > 100) this.energyLevel = 100;
        this.clockTimeOfLastSleep = this.clock.time;
        console.log(`Slept for ${hours} hours. Energy level: ${this.energyLevel}`);
    }

    tick() {
        const currentTime = this.clock.time;
        const timeSinceLastSleep = currentTime - this.clockTimeOfLastSleep;
        this.energyLevel -= timeSinceLastSleep;
        if (this.energyLevel < 0) this.energyLevel = 0;
        console.log(`Energy level: ${this.energyLevel}`);
    }
}

