class Crafting {
  constructor(recipeManager) {
    this.recipeManager = recipeManager;
  }

  craft(itemName) {
    const recipe = this.recipeManager.getRecipe(itemName);
    if (recipe) {
      console.log(`Crafting ${itemName}...`);
      return recipe;
    } else {
      console.log(`No recipe found for ${itemName}`);
      return null;
    }
  }
}

class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients;
  }
}

class RecipeManager {
  constructor() {
    this.recipes = {};
  }

  addRecipe(recipe) {
    this.recipes[recipe.name] = recipe;
  }

  getRecipe(name) {
    return this.recipes[name];
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, amount = 1) {
    if (this.items[item]) {
      this.items[item] += amount;
    } else {
      this.items[item] = amount;
    }
    console.log(`Added ${amount} ${item}(s) to inventory.`);
  }

  removeItem(item, amount = 1) {
    if (this.items[item] && this.items[item] >= amount) {
      this.items[item] -= amount;
      console.log(`Removed ${amount} ${item}(s) from inventory.`);
    } else {
      console.log(`Not enough ${item}(s) in inventory.`);
    }
  }

  hasIngredients(recipe) {
    for (const [item, amount] of Object.entries(recipe.ingredients)) {
      if (!this.items[item] || this.items[item] < amount) {
        return false;
      }
    }
    return true;
  }

  consumeIngredients(recipe) {
    for (const [item, amount] of Object.entries(recipe.ingredients)) {
      this.removeItem(item, amount);
    }
  }
}

// Top-level coordinator
class GameCoordinator {
  constructor() {
    this.inventory = new Inventory();
    this.recipeManager = new RecipeManager();
    this.crafting = new Crafting(this.recipeManager);

    // Initialize recipes
    this.recipeManager.addRecipe(new Recipe("Sword", { Wood: 2, Iron: 1 }));
    this.recipeManager.addRecipe(new Recipe("Shield", { Leather: 3, Wood: 1 }));

    // Initialize inventory with some items
    this.inventory.addItem("Wood", 5);
    this.inventory.addItem("Iron", 2);
    this.inventory.addItem("Leather", 4);
  }

  craftItem(itemName) {
    const recipe = this.crafting.craft(itemName);
    if (recipe && this.inventory.hasIngredients(recipe)) {
      this.inventory.consumeIngredients(recipe);
      console.log(`Crafted ${itemName} successfully.`);
      this.inventory.addItem(itemName);
    } else {
      console.log(`Failed to craft ${itemName}.`);
    }
  }
}

