    this.name = name;
    this.ingredients = ingredients; // { item: quantity }
  }

  get name() {
    return this._name;
  }

  set name(value) {
    this._name = value;
  }

  get ingredients() {
    return this._ingredients;
  }

  set ingredients(value) {
    this._ingredients = value;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { item: quantity }
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  hasIngredients(recipe) {
    for (const [item, quantity] of Object.entries(recipe.ingredients)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  getItems() {
    return this.items;
  }
}

class Crafting {
  constructor() {
    this.recipes = {};
  }

  addRecipe(recipe) {
    this.recipes[recipe.name] = recipe;
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes[recipeName];
    if (recipe && inventory.hasIngredients(recipe)) {
      for (const [item, quantity] of Object.entries(recipe.ingredients)) {
        inventory.removeItem(item, quantity);
      }
      return true;
    }
    return false;
  }

  getRecipes() {
    return this.recipes;
  }
}

