// Event Bus Implementation
class EventBus {
  constructor() {
    this.events = {};
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(callback => callback(data));
    }
  }

  subscribe(eventName, callback) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(callback);
  }
}

// Loot System
class Loot {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('generateLoot', this.generate.bind(this));
  }

  generate() {
    const lootItem = this.createLootItem();
    console.log(`Generated Loot: ${lootItem.name} (Rarity: ${lootItem.rarity})`);
    this.eventBus.emit('lootGenerated', lootItem);
  }

  createLootItem() {
    return {
      name: `Item${Math.floor(Math.random() * 100)}`,
      rarity: this.getRarity()
    };
  }

  getRarity() {
    const rarities = ['Common', 'Uncommon', 'Rare', 'Epic', 'Legendary'];
    return rarities[Math.floor(Math.random() * rarities.length)];
  }
}

// Rarity Table System
class RarityTable {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('lootGenerated', this.updateRarityTable.bind(this));
  }

  updateRarityTable(lootItem) {
    console.log(`Updating Rarity Table for: ${lootItem.name}`);
    // Simulate updating a rarity table
    this.eventBus.emit('rarityTableUpdated', lootItem.rarity);
  }
}

// Inventory System
