class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
  }

  purchase(item, quantity) {
    const price = this.pricing.getPrice(item);
    const available = this.demand.getDemand(item);

    if (quantity > available) {
      console.log(`Not enough demand for ${item}`);
      return;
    }

    const totalCost = price * quantity;

    if (totalCost > 0) {
      // Assume Economy is debited here
      console.log(`Purchased ${quantity} of ${item} for ${totalCost}`);
    }

    this.inventory[item] = (this.inventory[item] || 0) + quantity;
    this.demand.setDemand(item, available - quantity);
  }

  getInventory() {
    return this.inventory;
  }
}

