  constructor() {
    this.questSystem = new Quest();
    this.rewardSystem = new Reward();
    this.inventorySystem = new Inventory();
  }

  startGame() {
    // Initialize quests
    this.questSystem.addQuest("Defeat the dragon");
    this.questSystem.addQuest("Collect the treasure");

    // Initialize rewards
    this.rewardSystem.addReward("Golden Sword");
    this.rewardSystem.addReward("Magic Shield");
