        console.log(`Received reward: ${reward}`);
      }
    } else {
      console.log("Quest index out of range");
    }
  }

  displayInventory() {
    const items = this.inventorySystem.getItems();
    console.log("Inventory:", items.length ? items.join(", ") : "Empty");
  }
