    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('item-added', this.onItemAdded.bind(this));
    this.eventBus.subscribe('item-removed', this.onItemRemoved.bind(this));
  }

  addItem(item, quantity = 1) {
    this.items[item] = (this.items[item] || 0) + quantity;
    this.eventBus.emit('item-added', { item, quantity });
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      this.eventBus.emit('item-removed', { item, quantity });
    } else {
      console.log(`Not enough ${item} to remove.`);
    }
  }

  onItemAdded({ item, quantity }) {
    console.log(`Added ${quantity} ${item} to inventory.`);
  }

  onItemRemoved({ item, quantity }) {
    console.log(`Removed ${quantity} ${item} from inventory.`);
  }

  getItems() {
    return { ...this.items };
  }
}

class Recipe {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = {};
    this.eventBus.subscribe('recipe-added', this.onRecipeAdded.bind(this));
  }

  addRecipe(name, ingredients) {
    this.recipes[name] = ingredients;
    this.eventBus.emit('recipe-added', { name, ingredients });
  }

  onRecipeAdded({ name, ingredients }) {
    console.log(`Recipe added: ${name}`);
  }

  getRecipes() {
    return { ...this.recipes };
  }
}

class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('craft-item', this.onCraftItem.bind(this));
    this.eventBus.subscribe('recipe-added', this.onRecipeAdded.bind(this));
  }

  onRecipeAdded({ name, ingredients }) {
    console.log(`Crafting system: Recipe learned for ${name}`);
  }

  craftItem(name) {
    this.eventBus.emit('craft-item', name);
  }

  onCraftItem(name) {
    this.eventBus.emit('check-ingredients', { name, callback: this.craft.bind(this) });
  }

  craft({ name, ingredients, callback }) {
    const recipe = this.eventBus.emit('get-recipe', name);
    if (recipe) {
      const hasIngredients = Object.keys(recipe).every(item => {
        const required = recipe[item];
        const available = this.eventBus.emit('get-item', item);
        return available >= required;
      });
      if (hasIngredients) {
        Object.keys(recipe).forEach(item => {
          this.eventBus.emit('remove-item', { item, quantity: recipe[item] });
        });
        this.eventBus.emit('add-item', { item: name, quantity: 1 });
        console.log(`Crafted ${name}`);
      } else {
        console.log(`Missing ingredients for ${name}`);
      }
    } else {
      console.log(`No recipe found for ${name}`);
    }
  }
}

