class Crop {
    constructor(name, growTime, sellPrice) {
        this.name = name;
        this.growTime = growTime;
        this.sellPrice = sellPrice;
        this.ready = false;
    }

    grow(timePassed) {
        if (timePassed >= this.growTime) {
            this.ready = true;
        }
    }

    isReady() {
        return this.ready;
    }

    sell() {
        if (this.ready) {
            const price = this.sellPrice;
            this.ready = false;
            return price;
        }
        return 0;
    }
}

class Farm {
    constructor() {
        this.crops = [];
    }

    plantCrop(crop) {
        this.crops.push(crop);
    }

    update(timePassed) {
        this.crops.forEach(crop => crop.grow(timePassed));
    }

    harvest() {
        let earnings = 0;
        this.crops = this.crops.filter(crop => {
            if (crop.isReady()) {
                earnings += crop.sell();
            }
            return !crop.isReady();
        });
        return earnings;
    }
}

class Market {
    constructor() {
        this.prices = {
            'Wheat': 10,
            'Carrot': 5,
            'Tomato': 8
        };
    }

    getCropPrice(cropName) {
        return this.prices[cropName];
    }
}

