class EventBus {
    constructor() {
        this.events = {};
    }

    emit(eventName, data) {
        if (this.events[eventName]) {
            this.events[eventName].forEach(handler => handler(data));
        }
    }

    subscribe(eventName, handler) {
        if (!this.events[eventName]) {
            this.events[eventName] = [];
        }
        this.events[eventName].push(handler);
    }
}

class Pricing {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.prices = {};
        this.eventBus.subscribe('priceUpdate', this.updatePrice.bind(this));
    }

    setPrice(product, price) {
        this.prices[product] = price;
        this.eventBus.emit('priceChanged', { product, price });
    }

    updatePrice(data) {
        this.prices[data.product] = data.newPrice;
        this.eventBus.emit('priceChanged', { product: data.product, price: data.newPrice });
    }

    getPrice(product) {
        return this.prices[product] || 0;
    }
}

class Demand {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.demands = {};
        this.eventBus.subscribe('priceChanged', this.updateDemand.bind(this));
    }

    setInitialDemand(product, demand) {
        this.demands[product] = demand;
    }

    updateDemand(data) {
        const product = data.product;
        const price = data.price;
        // Simple demand model: demand decreases as price increases
        this.demands[product] = Math.max(0, this.demands[product] - price * 0.1);
        this.eventBus.emit('demandChanged', { product, demand: this.demands[product] });
    }

    getDemand(product) {
        return this.demands[product] || 0;
    }
}

class Store {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.inventory = {};
        this.eventBus.subscribe('demandChanged', this.updateInventory.bind(this));
    }

    setInitialInventory(product, quantity) {
        this.inventory[product] = quantity;
    }

    updateInventory(data) {
        const product = data.product;
        const demand = data.demand;
        // Simple inventory model: restock based on demand
        if (this.inventory[product] < demand) {
            this.inventory[product] += Math.ceil(demand - this.inventory[product]);
            this.eventBus.emit('inventoryUpdated', { product, quantity: this.inventory[product] });
        }
    }

    getInventory(product) {
        return this.inventory[product] || 0;
    }
}

// Runnable demo
