class Crafting {
    constructor() {
        this.recipes = [];
    }

    addRecipe(recipe) {
        this.recipes.push(recipe);
    }

    canCraft(item, inventory) {
        const recipe = this.recipes.find(r => r.item === item);
        if (!recipe) return false;

        for (const [ingredient, amount] of Object.entries(recipe.ingredients)) {
            if (inventory.getItemCount(ingredient) < amount) {
                return false;
            }
        }
        return true;
    }

    craft(item, inventory) {
        if (!this.canCraft(item, inventory)) {
            throw new Error(`Cannot craft ${item}: insufficient ingredients.`);
        }

        const recipe = this.recipes.find(r => r.item === item);
        for (const [ingredient, amount] of Object.entries(recipe.ingredients)) {
            inventory.removeItem(ingredient, amount);
        }
        inventory.addItem(item, 1);
    }
}

class Inventory {
    constructor() {
        this.items = {}; // { item1: amount1, item2: amount2, ... }
    }

    addItem(item, amount) {
        if (this.items[item]) {
            this.items[item] += amount;
        } else {
            this.items[item] = amount;
        }
    }

    removeItem(item, amount) {
        if (!this.items[item] || this.items[item] < amount) {
            throw new Error(`Cannot remove ${amount} of ${item}: insufficient stock.`);
        }
        this.items[item] -= amount;
        if (this.items[item] === 0) {
            delete this.items[item];
        }
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }
}

class Economy {
    constructor(prices) {
        this.prices = prices; // { item1: price1, item2: price2, ... }
    }

    getPrice(item) {
        return this.prices[item] || 0;
    }

    debit(account, amount) {
        if (account.balance < amount) {
            throw new Error(`Insufficient balance to debit ${amount}.`);
        }
        account.balance -= amount;
    }
}

class Store {
    constructor(inventory, economy) {
        this.inventory = inventory;
        this.economy = economy;
    }

    purchase(item, account) {
        const price = this.economy.getPrice(item);
        if (price === 0) {
            throw new Error(`Item ${item} is not for sale.`);
        }

        this.economy.debit(account, price);
        this.inventory.addItem(item, 1);
    }
}

