class Loot {
  constructor(name, value) {
    this.name = name;
    this.value = value;
  }

  toString() {
    return `${this.name} (Value: ${this.value})`;
  }
}

class RarityTable {
  constructor() {
    this.table = [
      { rarity: 'Common', probability: 0.6 },
      { rarity: 'Uncommon', probability: 0.3 },
      { rarity: 'Rare', probability: 0.09 },
      { rarity: 'Epic', probability: 0.01 }
    ];
  }

  generateLoot() {
    const rand = Math.random();
    let cumulativeProbability = 0;

    for (const entry of this.table) {
      cumulativeProbability += entry.probability;
      if (rand < cumulativeProbability) {
        return new Loot(`${entry.rarity} Loot`, this.calculateValue(entry.rarity));
      }
    }

    // Fallback, should never reach here
    return new Loot('Common Loot', this.calculateValue('Common'));
  }

  calculateValue(rarity) {
    switch (rarity) {
      case 'Common': return 10;
      case 'Uncommon': return 25;
      case 'Rare': return 50;
      case 'Epic': return 100;
      default: return 10;
    }
  }
}

class Economy {
  constructor(initialBalance = 100) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error('Insufficient funds');
    }
    this.balance -= amount;
  }

  credit(amount) {
    this.balance += amount;
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  getItems() {
    return this.items;
  }

  getTotalValue() {
    return this.items.reduce((total, item) => total + item.value, 0);
  }
}

class Store {
  constructor(economy, rarityTable, inventory) {
    this.economy = economy;
    this.rarityTable = rarityTable;
    this.inventory = inventory;
  }

  purchaseLoot() {
    const loot = this.rarityTable.generateLoot();
    if (loot.value > this.economy.getBalance()) {
      console.log('Purchase failed: Insufficient funds');
      return;
    }
    this.economy.debit(loot.value);
    this.inventory.addItem(loot);
    console.log(`Purchased: ${loot}`);
    console.log(`Remaining balance: ${this.economy.getBalance()}`);
  }
}

