class Recipe {
    constructor(name, ingredients, result) {
        this.name = name;
        this.ingredients = ingredients; // { ingredientName: quantity }
        this.result = result; // { itemName: quantity }
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(itemName, quantity) {
        if (this.items[itemName]) {
            this.items[itemName] += quantity;
        } else {
            this.items[itemName] = quantity;
        }
    }

    removeItem(itemName, quantity) {
        if (this.items[itemName] && this.items[itemName] >= quantity) {
            this.items[itemName] -= quantity;
            if (this.items[itemName] === 0) {
                delete this.items[itemName];
            }
            return true;
        }
        return false;
    }

    hasItem(itemName, quantity) {
        return this.items[itemName] && this.items[itemName] >= quantity;
    }

    getItems() {
        return this.items;
    }
}

class Crafting {
    constructor(recipes, inventory) {
        this.recipes = recipes; // { recipeName: Recipe }
        this.inventory = inventory;
    }

    craft(recipeName) {
        const recipe = this.recipes[recipeName];
        if (!recipe) {
            console.log(`Recipe ${recipeName} not found.`);
            return false;
        }

        for (const [ingredient, quantity] of Object.entries(recipe.ingredients)) {
            if (!this.inventory.hasItem(ingredient, quantity)) {
                console.log(`Missing ${quantity} of ${ingredient} for ${recipeName}.`);
                return false;
            }
        }

        for (const [ingredient, quantity] of Object.entries(recipe.ingredients)) {
            this.inventory.removeItem(ingredient, quantity);
        }

        for (const [result, quantity] of Object.entries(recipe.result)) {
            this.inventory.addItem(result, quantity);
        }

        console.log(`Crafted ${recipeName} successfully.`);
        return true;
    }
}

class Economy {
    constructor(prices) {
        this.prices = prices; // { itemName: price }
    }

    debit(itemName, quantity) {
        const price = this.prices[itemName];
        if (price === undefined) {
            console.log(`Price for ${itemName} not found.`);
            return false;
        }

        const totalCost = price * quantity;
        console.log(`Debited ${totalCost} for ${quantity} of ${itemName}.`);
        return true;
    }

    getPrice(itemName) {
        return this.prices[itemName];
    }
}

class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
    }

    purchase(itemName, quantity) {
        const price = this.economy.getPrice(itemName);
        if (price === undefined) {
            console.log(`Price for ${itemName} not found.`);
            return false;
        }

        if (!this.economy.debit(itemName, quantity)) {
            return false;
        }

        this.inventory.addItem(itemName, quantity);
        console.log(`Purchased ${quantity} of ${itemName}.`);
        return true;
    }
}

