class Wallet {
    constructor(initialBalance = 0) {
        this._balance = initialBalance;
    }

    get balance() {
        return this._balance;
    }

    deposit(amount) {
        if (amount > 0) {
            this._balance += amount;
        }
    }

    withdraw(amount) {
        if (amount > 0 && this._balance >= amount) {
            this._balance -= amount;
            return true;
        }
        return false;
    }
}

class Shop {
    constructor() {
        this._items = {
            sword: { price: 50 },
            shield: { price: 30 },
            potion: { price: 10 }
        };
    }

    getItemPrice(itemName) {
        return this._items[itemName]?.price || 0;
    }

    purchase(wallet, itemName) {
        const price = this.getItemPrice(itemName);
        if (price > 0 && wallet.withdraw(price)) {
            return true;
        }
        return false;
    }
}

class Inventory {
    constructor() {
        this._items = {};
    }

    addItem(itemName, quantity = 1) {
        if (quantity > 0) {
            this._items[itemName] = (this._items[itemName] || 0) + quantity;
        }
    }

    getInventory() {
        return { ...this._items };
    }
}

class GameCoordinator {
    constructor() {
        this._wallet = new Wallet(100);
        this._shop = new Shop();
        this._inventory = new Inventory();
