        this._wallet.deposit(amount);
    }

    buyItem(itemName) {
        if (this._shop.purchase(this._wallet, itemName)) {
            this._inventory.addItem(itemName);
            return true;
        }
        return false;
    }

    getWalletBalance() {
        return this._wallet.balance;
    }

    getInventory() {
        return this._inventory.getInventory();
    }
}

