class Store {
    constructor(pricing, demand) {
        this.pricing = pricing;
        this.demand = demand;
        this.inventory = new Map();
    }

    purchase(item, quantity) {
        const price = this.pricing.getPrice(item);
        const availableDemand = this.demand.getDemand(item);

        if (availableDemand < quantity) {
            console.log(`Not enough demand for ${item}`);
            return;
        }

        const totalCost = price * quantity;
        this.demand.setDemand(item, availableDemand - quantity);

        // Assuming economy is debited here
        console.log(`Purchased ${quantity} of ${item} for ${totalCost}`);

        // Add to inventory
        this.inventory.set(item, (this.inventory.get(item) || 0) + quantity);
        console.log(`Inventory for ${item}: ${this.inventory.get(item)}`);
    }
}

