class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients; // { itemName: quantity }
    this.result = result; // { itemName: quantity }
  }
}

class Crafting {
  constructor(recipes) {
    this.recipes = new Map(recipes.map(recipe => [recipe.name, recipe]));
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.get(recipeName);
    if (!recipe) return false;

    for (const [itemName, requiredQuantity] of Object.entries(recipe.ingredients)) {
      const availableQuantity = inventory.get(itemName) || 0;
      if (availableQuantity < requiredQuantity) return false;
    }
    return true;
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes.get(recipeName);
    if (!recipe) throw new Error('Recipe not found');

    for (const [itemName, requiredQuantity] of Object.entries(recipe.ingredients)) {
      inventory.set(itemName, (inventory.get(itemName) || 0) - requiredQuantity);
    }

    for (const [itemName, resultQuantity] of Object.entries(recipe.result)) {
      inventory.set(itemName, (inventory.get(itemName) || 0) + resultQuantity);
    }
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  get(itemName) {
    return this.items.get(itemName) || 0;
  }

  add(itemName, quantity) {
    this.items.set(itemName, (this.items.get(itemName) || 0) + quantity);
  }

  remove(itemName, quantity) {
    const currentQuantity = this.items.get(itemName) || 0;
    if (currentQuantity < quantity) throw new Error('Not enough items');
    this.items.set(itemName, currentQuantity - quantity);
  }
}

class Economy {
  constructor(prices) {
    this.prices = new Map(prices);
  }

  getPrice(itemName) {
    return this.prices.get(itemName) || 0;
  }

  debit(itemName, quantity) {
    const price = this.getPrice(itemName);
    const totalCost = price * quantity;
    // In a real system, you would handle the debit logic here
    console.log(`Debited ${quantity} ${itemName} for ${totalCost} credits`);
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(itemName, quantity) {
    const price = this.economy.getPrice(itemName);
    if (price === 0) throw new Error('Item not for sale');

    this.economy.debit(itemName, quantity);
    this.inventory.add(itemName, quantity);
  }
}

// Demo
