  constructor(flags) {
    this.flags = flags;
    this.quests = {};
  }

  addQuest(key, requirement, reward) {
    this.quests[key] = { requirement, reward };
  }

  canCompleteQuest(questKey) {
    const quest = this.quests[questKey];
    if (!quest) return false;
    return this.flags.getFlag(quest.requirement);
  }

  completeQuest(questKey) {
    const quest = this.quests[questKey];
    if (quest && this.canCompleteQuest(questKey)) {
      this.flags.setFlag(questKey, true);
      return quest.reward;
    }
    return "Quest cannot be completed";
  }
}

