    this.economy = economy;
  }

  build() {
    if (this.economy.canAfford(this.resourceCosts)) {
      this.economy.spendResources(this.resourceCosts);
      console.log(`${this.name} built successfully.`);
      return true;
    } else {
      console.log(`${this.name} cannot be built. Not enough resources.`);
      return false;
    }
  }
}

class Resource {
  constructor(name, amount) {
    this.name = name;
    this.amount = amount;
  }

  add(amount) {
    this.amount += amount;
    console.log(`${amount} ${this.name} added. Total: ${this.amount}.`);
  }

  subtract(amount) {
    if (this.amount >= amount) {
      this.amount -= amount;
      console.log(`${amount} ${this.name} subtracted. Remaining: ${this.amount}.`);
      return true;
    } else {
      console.log(`Not enough ${this.name} to subtract. Current: ${this.amount}.`);
      return false;
    }
  }
}

class Economy {
  constructor(resources) {
    this.resources = resources;
  }

  canAfford(costs) {
    for (const [resourceName, cost] of Object.entries(costs)) {
      const resource = this.resources.find(r => r.name === resourceName);
      if (!resource || resource.amount < cost) {
        return false;
      }
    }
    return true;
  }

  spendResources(costs) {
    for (const [resourceName, cost] of Object.entries(costs)) {
      const resource = this.resources.find(r => r.name === resourceName);
      if (resource) {
        resource.subtract(cost);
      }
    }
  }

  addResources(amounts) {
    for (const [resourceName, amount] of Object.entries(amounts)) {
      const resource = this.resources.find(r => r.name === resourceName);
      if (resource) {
        resource.add(amount);
      }
    }
  }
}

// Demo
