const stone = new Resource('Stone', 50);
const economy = new Economy([wood, stone]);

const house = new Building('House', { Wood: 30, Stone: 20 }, economy);
const castle = new Building('Castle', { Wood: 100, Stone: 50 }, economy);

house.build(); // Should build successfully
castle.build(); // Should fail due to insufficient resources

economy.addResources({ Wood: 50, Stone: 30 });
castle.build(); // Should build successfully
