class EventBus {
  constructor() {
    this.events = {};
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(listener => listener(data));
    }
  }

  subscribe(eventName, listener) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(listener);
  }
}

class Pricing {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('priceChangeRequest', this.onPriceChangeRequest.bind(this));
  }

  onPriceChangeRequest(data) {
    const newPrice = data.basePrice * (1 + data.changeFactor);
    this.eventBus.emit('priceChanged', { itemId: data.itemId, newPrice });
  }
}

class Demand {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('demandChangeRequest', this.onDemandChangeRequest.bind(this));
  }

  onDemandChangeRequest(data) {
    const newDemand = data.baseDemand * (1 + data.changeFactor);
    this.eventBus.emit('demandChanged', { itemId: data.itemId, newDemand });
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.prices = {};
    this.demands = {};
    this.eventBus.subscribe('priceChanged', this.onPriceChanged.bind(this));
    this.eventBus.subscribe('demandChanged', this.onDemandChanged.bind(this));
  }

  onPriceChanged(data) {
    this.prices[data.itemId] = data.newPrice;
    console.log(`Price for item ${data.itemId} changed to ${data.newPrice}`);
  }

  onDemandChanged(data) {
    this.demands[data.itemId] = data.newDemand;
    console.log(`Demand for item ${data.itemId} changed to ${data.newDemand}`);
  }

  adjustPrice(itemId, basePrice, changeFactor) {
    this.eventBus.emit('priceChangeRequest', { itemId, basePrice, changeFactor });
  }

  adjustDemand(itemId, baseDemand, changeFactor) {
    this.eventBus.emit('demandChangeRequest', { itemId, baseDemand, changeFactor });
  }
}

