  attemptCraft({ recipeName, ingredients }) {
    const inventory = {};
    this.eventBus.emit('requestInventory', inventory);
    const hasIngredients = Object.keys(ingredients).every(item => 
      inventory[item] && inventory[item] >= ingredients[item]
    );

    if (hasIngredients) {
      Object.keys(ingredients).forEach(item => {
        this.eventBus.emit('itemRemoved', item, ingredients[item]);
      });
      this.eventBus.emit('itemAdded', recipeName, 1);
      console.log(`Crafting: Successfully crafted ${recipeName}.`);
    } else {
      console.log(`Crafting: Missing ingredients for ${recipeName}.`);
    }
  }
}

