class RarityTable {
  constructor() {
    this.table = {
      "Common": 50,
      "Uncommon": 30,
      "Rare": 15,
      "Epic": 5
    };
  }

  generateLoot() {
    const rarities = Object.keys(this.table);
    let totalWeight = 0;
    const weights = rarities.map(rarity => this.table[rarity]);
    const roll = Math.random() * weights.reduce((sum, weight) => sum + weight, 0);

    for (let i = 0; i < rarities.length; i++) {
      totalWeight += weights[i];
      if (roll <= totalWeight) {
        return new Loot(`Loot-${i}`, rarities[i], weights[i] * 10);
      }
    }
    throw new Error("Failed to generate loot");
