class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Pricing {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('priceChangeRequest', this.onPriceChangeRequest.bind(this));
  }

  onPriceChangeRequest(data) {
    const newPrice = data.currentPrice * 1.1; // Increase price by 10%
    console.log(`Pricing: New price set to ${newPrice}`);
    this.eventBus.emit('priceChanged', { itemId: data.itemId, newPrice });
  }
}

class Demand {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('priceChanged', this.onPriceChanged.bind(this));
  }

  onPriceChanged(data) {
    const demandChange = data.newPrice > 10 ? -1 : 1; // Decrease demand if price is high
    console.log(`Demand: Demand for item ${data.itemId} changed by ${demandChange}`);
    this.eventBus.emit('demandChanged', { itemId: data.itemId, demandChange });
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('demandChanged', this.onDemandChanged.bind(this));
    this.items = {
      'item1': { price: 10, demand: 100 }
    };
  }

  onDemandChanged(data) {
    const item = this.items[data.itemId];
    if (item) {
      item.demand += data.demandChange;
      console.log(`Store: Demand for item ${data.itemId} is now ${item.demand}`);
      if (item.demand < 50) {
        this.eventBus.emit('priceChangeRequest', { itemId: data.itemId, currentPrice: item.price });
      }
    }
  }

  requestPriceChange(itemId) {
    const item = this.items[itemId];
    if (item) {
      console.log(`Store: Requesting price change for item ${itemId}`);
      this.eventBus.emit('priceChangeRequest', { itemId, currentPrice: item.price });
    }
  }
}

