class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  hasItem(item, quantity = 1) {
    return this.items[item] && this.items[item] >= quantity;
  }

  getItems() {
    return { ...this.items };
  }
}

class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { item: quantity }
  }

  canCraft(inventory) {
    return Object.keys(this.ingredients).every(item => inventory.hasItem(item, this.ingredients[item]));
  }

  craft(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      if (!inventory.removeItem(item, quantity)) {
        return false;
      }
    }
    return true;
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return { ...this.ingredients };
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes; // Array of Recipe objects
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (recipe) {
      return recipe.canCraft(this.inventory);
    }
    return false;
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (recipe && recipe.canCraft(this.inventory)) {
      recipe.craft(this.inventory);
      return true;
    }
    return false;
  }

  getRecipes() {
    return this.recipes.map(recipe => recipe.getName());
  }
}

