      'sword': { price: 100, quantity: 5 },
      'potion': { price: 50, quantity: 10 }
    };
  }

  getItemPrice(itemName) {
    return this.items[itemName]?.price || 0;
  }

  getItemQuantity(itemName) {
    return this.items[itemName]?.quantity || 0;
  }

  sellItem(itemName, quantity) {
    if (this.items[itemName] && this.items[itemName].quantity >= quantity) {
      this.items[itemName].quantity -= quantity;
      return true;
    }
    return false;
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(itemName, quantity) {
    if (quantity > 0) {
      this.items[itemName] = (this.items[itemName] || 0) + quantity;
      return true;
    }
    return false;
  }

  getItemCount(itemName) {
    return this.items[itemName] || 0;
  }

  useItem(itemName, quantity) {
    if (this.items[itemName] && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      return true;
    }
    return false;
  }
}

// Coordinator to wire systems together
