    const totalCost = price * quantity;

    if (this.wallet.withdraw(totalCost) && this.shop.sellItem(itemName, quantity)) {
      this.inventory.addItem(itemName, quantity);
      return true;
    }
    return false;
  }

  useInventoryItem(itemName, quantity) {
    return this.inventory.useItem(itemName, quantity);
  }

  getWalletBalance() {
    return this.wallet.getBalance();
  }

  getInventoryItemCount(itemName) {
    return this.inventory.getItemCount(itemName);
  }
}

