// Quest System
class QuestSystem {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('flagChanged', this.onFlagChanged.bind(this));
    this.quests = {
      'Rescue the Cat': { requires: { 'catSaved': false } }
    };
  }

  startQuest(questName) {
    console.log(`Starting quest: ${questName}`);
    const quest = this.quests[questName];
    if (quest) {
      this.checkQuestRequirements(quest);
    }
  }

  completeQuest(questName) {
    console.log(`Completing quest: ${questName}`);
    this.eventBus.emit('questCompleted', questName);
  }

  onFlagChanged({ flagName, value }) {
    Object.values(this.quests).forEach(quest => {
      if (quest.requires[flagName] !== undefined && quest.requires[flagName] === value) {
        this.checkQuestRequirements(quest);
      }
    });
  }

  checkQuestRequirements(quest) {
    const requirementsMet = Object.entries(quest.requires).every(([flag, requiredValue]) => {
      return this.eventBus.flagsSystem.getFlag(flag) === requiredValue;
    });

    if (requirementsMet) {
      console.log('All requirements met for this quest!');
      this.completeQuest(Object.keys(this.quests).find(key => this.quests[key] === quest));
    }
  }
}

