  }

  // Public API: Get the price based on quantity
  getPrice(quantity) {
    return this.basePrice * quantity;
  }
}

// Demand System
class Demand {
  constructor(baseDemand) {
    this.baseDemand = baseDemand;
  }

  // Public API: Get demand based on price
  getDemand(price) {
    return this.baseDemand - (price / 10); // Simple model: demand decreases with price
  }
}

// Store System
class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  // Public API: Calculate total sales
  calculateSales(quantity) {
    const price = this.pricing.getPrice(quantity);
    const demand = this.demand.getDemand(price);
    const sales = Math.min(quantity, demand) * price;
    return sales;
  }
}

// Top-level Coordinator
class GameCoordinator {
  constructor() {
    const pricing = new Pricing(10); // Base price of $10
    const demand = new Demand(100); // Base demand of 100 units
    this.store = new Store(pricing, demand);
  }

  // Public API: Simulate sales for a given quantity
  simulateSales(quantity) {
    const sales = this.store.calculateSales(quantity);
    console.log(`Quantity: ${quantity}, Sales: $${sales.toFixed(2)}`);
  }
}

