class Crop {
  constructor(name, growthRate) {
    this.name = name;
    this.growthRate = growthRate;
    this.daysGrown = 0;
  }

  grow() {
    this.daysGrown += this.growthRate;
  }

  isReadyForHarvest() {
    return this.daysGrown >= 30;
  }

  harvest() {
    if (this.isReadyForHarvest()) {
      const harvestAmount = this.daysGrown / this.growthRate;
      this.daysGrown = 0;
      return harvestAmount;
    }
    return 0;
  }
}

class Farm {
  constructor(market) {
    this.market = market;
    this.crops = [];
  }

  plantCrop(crop) {
    this.crops.push(crop);
  }

  growCrops() {
    this.crops.forEach(crop => crop.grow());
  }

  harvestCrops() {
    this.crops.forEach(crop => {
      if (crop.isReadyForHarvest()) {
        const amount = crop.harvest();
        this.market.sellCrop(crop.name, amount);
      }
    });
  }

  getInventory() {
    return this.crops.map(crop => ({
      name: crop.name,
      daysGrown: crop.daysGrown
    }));
  }
}

class Market {
