    this.name = name;
    this.ingredients = ingredients;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }

  hasIngredients(ingredients) {
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }
}

class Crafting {
  constructor(recipes) {
    this.recipes = recipes;
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe) {
      return recipe.ingredients;
    }
    return null;
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe && inventory.hasIngredients(recipe.ingredients)) {
      for (const [item, quantity] of Object.entries(recipe.ingredients)) {
        inventory.removeItem(item, quantity);
      }
      return true;
    }
    return false;
  }
}

