    this.pricing = pricing;
    this.demand = demand;
  }

  sell(quantity) {
    const price = this.pricing.calculatePrice(quantity);
    const demand = this.demand.calculateDemand(price);
    const actualQuantitySold = Math.min(quantity, demand);
    const totalRevenue = price * actualQuantitySold;
    return { actualQuantitySold, totalRevenue };
  }
}

