```js
class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Store {
  constructor(economy, inventory, initialStock = {}) {
    this.economy = economy;
    this.inventory = inventory;
    this.stock = initialStock;
  }

  buyItem(item, price) {
    if (this.economy.withdraw(price) && this.inventory.addItem(item, 1)) {
      this.stock[item] = (this.stock[item] || 0) - 1;
      return true;
    }
    return false;
  }

  sellItem(item, price) {
    if (this.inventory.removeItem(item, 1) && this.economy.deposit(price)) {
      this.stock[item] = (this.stock[item] || 0) + 1;
      return true;
    }
    return false;
  }

  getStock() {
    return { ...this.stock };
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
