class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
    this.result = result; // { itemName: quantity }
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { itemName: quantity }
  }

  addItem(itemName, quantity) {
    if (this.items[itemName]) {
      this.items[itemName] += quantity;
    } else {
      this.items[itemName] = quantity;
    }
  }

  removeItem(itemName, quantity) {
    if (this.items[itemName] && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
      return true;
    }
    return false;
  }

  hasIngredients(ingredients) {
    for (const [itemName, quantity] of Object.entries(ingredients)) {
      if (!this.items[itemName] || this.items[itemName] < quantity) {
        return false;
      }
    }
    return true;
  }

  getItems() {
    return { ...this.items };
  }
}

class Crafting {
  constructor(recipes) {
    this.recipes = {}; // { recipeName: Recipe }
    recipes.forEach(recipe => {
      this.recipes[recipe.name] = recipe;
    });
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes[recipeName];
    if (recipe) {
      return inventory.hasIngredients(recipe.ingredients);
    }
    return false;
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes[recipeName];
    if (recipe && this.canCraft(recipeName, inventory)) {
      for (const [itemName, quantity] of Object.entries(recipe.ingredients)) {
        inventory.removeItem(itemName, quantity);
      }
      for (const [itemName, quantity] of Object.entries(recipe.result)) {
        inventory.addItem(itemName, quantity);
      }
      return true;
    }
    return false;
  }
}

class GameCoordinator {
  constructor() {
    this.inventory = new Inventory();
    this.crafting = new Crafting([
      new Recipe("Wooden Sword", { "Wood": 2 }, { "Wooden Sword": 1 }),
      new Recipe("Stone Axe", { "Stone": 2, "Wood": 1 }, { "Stone Axe": 1 })
    ]);
  }

  addItemToInventory(itemName, quantity) {
    this.inventory.addItem(itemName, quantity);
  }

  craftItem(recipeName) {
    return this.crafting.craft(recipeName, this.inventory);
  }

  getInventoryItems() {
    return this.inventory.getItems();
  }

  canCraftItem(recipeName) {
    return this.crafting.canCraft(recipeName, this.inventory);
  }
}

