class Loot {
  constructor(itemName, rarity) {
    this.itemName = itemName;
    this.rarity = rarity;
  }

  describe() {
    return `${this.itemName} (Rarity: ${this.rarity})`;
  }
}

class RarityTable {
  constructor() {
    this.table = {
      common: 0.6,
      uncommon: 0.3,
      rare: 0.08,
      epic: 0.02
    };
  }

  getRandomLoot() {
    const rarity = this._determineRarity();
    const itemName = this._generateItemName(rarity);
    return new Loot(itemName, rarity);
  }

  _determineRarity() {
    const roll = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.table)) {
      cumulativeProbability += probability;
      if (roll <= cumulativeProbability) {
        return rarity;
      }
    }

    throw new Error("Rarity not determined");
  }

  _generateItemName(rarity) {
    const adjectives = ["Shiny", "Gleaming", "Mysterious", "Ancient"];
    const nouns = ["Sword", "Shield", "Potion", "Ring"];
    const adjective = adjectives[Math.floor(Math.random() * adjectives.length)];
    const noun = nouns[Math.floor(Math.random() * nouns.length)];
    return `${adjective} ${noun} of ${rarity.charAt(0).toUpperCase() + rarity.slice(1)}`;
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(loot) {
    this.items.push(loot);
  }

  listItems() {
    return this.items.map(item => item.describe()).join("\n");
  }
}

