            if (this.buildings.constructBuilding(type).includes('Constructed')) {
                this.resources.resources[type] += 1;
            }
        });
    }

    getEconomyStatus() {
        return {
            buildings: this.buildings.constructBuilding('wood'),
            resources: this.resources.getResources()
        };
    }
