    this.inventory = inventory;
    this.recipe = recipe;
    this.economy = economy;
  }

  craft(item) {
    const recipe = this.recipe.getRecipe(item);
    if (!recipe) {
      console.log(`No recipe found for ${item}`);
      return false;
    }

    const cost = recipe.reduce((total, [ingredient, quantity]) => {
      const price = this.economy.prices[ingredient] || 0;
      return total + price * quantity;
    }, 0);

    if (!this.economy.debit(item, cost)) {
      console.log(`Failed to craft ${item} due to insufficient funds`);
      return false;
    }

    recipe.forEach(([ingredient, quantity]) => {
      this.inventory.addItem(ingredient, quantity);
    });

    console.log(`Crafted ${item}`);
    return true;
  }
}

