class EventBus {
    constructor() {
        this.listeners = {};
    }

    subscribe(event, callback) {
        if (!this.listeners[event]) {
            this.listeners[event] = [];
        }
        this.listeners[event].push(callback);
    }

    emit(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(callback => callback(data));
        }
    }
}

class Trade {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('tradeOffer', this.handleTradeOffer.bind(this));
    }

    makeTradeOffer(item, quantity, faction) {
        console.log(`Trade system: Offering ${quantity} ${item} to ${faction}`);
        this.eventBus.emit('tradeAccepted', { faction, item, quantity });
    }

    handleTradeOffer(data) {
        console.log(`Trade system: Received trade offer for ${data.quantity} ${data.item} from ${data.faction}`);
        this.makeTradeOffer(data.item, data.quantity, data.faction);
    }
}

class Reputation {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.reputation = { faction1: 0, faction2: 0 };
        this.eventBus.subscribe('tradeAccepted', this.updateReputation.bind(this));
    }

    updateReputation(data) {
        console.log(`Reputation system: Updating reputation with ${data.faction}`);
        this.reputation[data.faction] += 10;
        console.log(`Reputation system: ${data.faction} reputation is now ${this.reputation[data.faction]}`);
    }
}

class Faction {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('tradeAccepted', this.onTradeAccepted.bind(this));
    }

