class RarityTable {
  constructor() {
    this.table = {
      common: 0.6,
      uncommon: 0.3,
      rare: 0.05,
      legendary: 0.05
    };
  }

  getRandomLoot() {
    const roll = Math.random();
    let cumulativeProbability = 0;
    for (const [rarity, probability] of Object.entries(this.table)) {
      cumulativeProbability += probability;
      if (roll <= cumulativeProbability) {
        return new Loot(`Loot (${rarity})`, this.getLootValue(rarity));
      }
    }
    return null; // This line should never be reached
  }

  getLootValue(rarity) {
    switch (rarity) {
      case 'common':
        return Math.floor(Math.random() * 10) + 1;
      case 'uncommon':
        return Math.floor(Math.random() * 20) + 10;
      case 'rare':
        return Math.floor(Math.random() * 50) + 30;
      case 'legendary':
        return Math.floor(Math.random() * 100) + 80;
      default:
        return 0;
    }
  }
}

