class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemAdded', this.onItemAdded.bind(this));
    this.eventBus.subscribe('itemUsed', this.onItemUsed.bind(this));
  }

  addItem(item, quantity = 1) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
    this.eventBus.emit('itemAdded', { item, quantity });
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      this.eventBus.emit('itemUsed', { item, quantity });
    } else {
      console.log(`Not enough ${item} in inventory.`);
    }
  }

  getInventory() {
    return this.items;
  }

  onItemAdded({ item, quantity }) {
    console.log(`Added ${quantity} ${item}. Inventory:`, this.getInventory());
  }

  onItemUsed({ item, quantity }) {
    console.log(`Used ${quantity} ${item}. Inventory:`, this.getInventory());
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('craftItem', this.onCraftItem.bind(this));
  }

  addRecipe(recipeName, ingredients) {
    this.recipes[recipeName] = ingredients;
  }

  craftItem(recipeName) {
    const ingredients = this.recipes[recipeName];
    if (ingredients) {
      this.eventBus.emit('craftItemRequested', { recipeName, ingredients });
    } else {
      console.log(`Recipe ${recipeName} not found.`);
    }
  }

  onCraftItem({ recipeName, ingredients }) {
    const inventory = this.eventBus.emit('getInventory', null);
    let canCraft = true;
    ingredients.forEach(({ item, quantity }) => {
      if (inventory[item] < quantity) {
        canCraft = false;
        console.log(`Not enough ${item} to craft ${recipeName}.`);
      }
    });
    if (canCraft) {
      ingredients.forEach(({ item, quantity }) => {
        this.eventBus.emit('removeItem', { item, quantity });
      });
      this.eventBus.emit('itemAdded', { item: recipeName, quantity: 1 });
      console.log(`${recipeName} crafted successfully.`);
    }
  }
}

class Crafting {
  constructor(eventBus, inventory, recipe) {
    this.eventBus = eventBus;
    this.inventory = inventory;
    this.recipe = recipe;
    this.eventBus.subscribe('craftItemRequested', this.onCraftItemRequested.bind(this));
    this.eventBus.subscribe('removeItem', this.inventory.removeItem.bind(this.inventory));
    this.eventBus.subscribe('getInventory', this.inventory.getInventory.bind(this.inventory));
  }

  onCraftItemRequested({ recipeName, ingredients }) {
    this.inventory.removeItem(ingredients);
