        this.responses[key] = response;
    }

    getResponse(key) {
        return this.responses[key] || "I don't understand that.";
    }
}

class Flags {
    constructor() {
        this.flags = {};
    }

    setFlag(key, value) {
        this.flags[key] = value;
    }

    getFlag(key) {
        return this.flags[key];
    }
}

class Quest {
    constructor(flags) {
        this.flags = flags;
        this.steps = {};
    }

    addStep(key, condition, dialogueKey) {
        this.steps[key] = { condition, dialogueKey };
    }

    getNextDialogue(key) {
        const step = this.steps[key];
        if (step && step.condition(this.flags)) {
            return step.dialogueKey;
        }
        return null;
    }
}

class GameCoordinator {
    constructor() {
        this.dialogue = new Dialogue();
        this.flags = new Flags();
        this.quest = new Quest(this.flags);
        this.currentDialogueKey = null;
    }

    setup() {
        this.dialogue.addResponse("greet", "Hello! How can I assist you today?");
        this.dialogue.addResponse("quest", "You are on a quest to find the ancient artifact.");
        this.dialogue.addResponse("complete", "Congratulations! You have completed your quest.");

        this.flags.setFlag("questStarted", false);
        this.flags.setFlag("questCompleted", false);

        this.quest.addStep("start", () => !this.flags.getFlag("questStarted"), "quest");
        this.quest.addStep("complete", () => this.flags.getFlag("questStarted") && !this.flags.getFlag("questCompleted"), "complete");
    }

    start() {
        this.currentDialogueKey = "greet";
        this.displayDialogue();
    }

    displayDialogue() {
        const response = this.dialogue.getResponse(this.currentDialogueKey);
        console.log(response);

        if (this.currentDialogueKey === "greet") {
            this.flags.setFlag("questStarted", true);
            this.currentDialogueKey = this.quest.getNextDialogue("start");
        } else if (this.currentDialogueKey === "quest") {
            this.currentDialogueKey = this.quest.getNextDialogue("complete");
        }
    }
}

