class Quest {
  constructor(flags) {
    this.flags = flags;
    this.quests = {};
  }

  addQuest(key, requirements) {
    this.quests[key] = requirements;
  }

  canCompleteQuest(key) {
    const requirements = this.quests[key];
    if (!requirements) return false;
    return Object.keys(requirements).every(flagKey => this.flags.getFlag(flagKey) === requirements[flagKey]);
  }

  completeQuest(key) {
    if (this.canCompleteQuest(key)) {
      console.log(`Quest ${key} completed!`);
      return true;
    }
    console.log(`Quest ${key} cannot be completed yet.`);
    return false;
  }
}

