class RarityTable {
  constructor() {
    this.rarityWeights = {
      "Common": 70,
      "Uncommon": 20,
      "Rare": 8,
      "Epic": 2
    };
  }

  getRandomRarity() {
    const totalWeight = Object.values(this.rarityWeights).reduce((a, b) => a + b, 0);
    const randomWeight = Math.floor(Math.random() * totalWeight);

    let cumulativeWeight = 0;
    for (const [rarity, weight] of Object.entries(this.rarityWeights)) {
      cumulativeWeight += weight;
      if (randomWeight < cumulativeWeight) {
        return rarity;
      }
    }

    return "Common"; // Fallback, should not happen
  }
}

class Inventory {
  constructor(lootSystem, raritySystem) {
    this.lootSystem = lootSystem;
    this.raritySystem = raritySystem;
    this.items = [];
  }

  addItem() {
    const loot = this.lootSystem.generateLoot();
    loot.rarity = this.raritySystem.getRandomRarity();
    this.items.push(loot);
  }

  listItems() {
    return this.items.map(item => `${item.name} (${item.rarity})`);
  }
