class Crop {
  constructor(name, growthRate, price) {
    this.name = name;
    this.growthRate = growthRate; // in days to maturity
    this.price = price; // in currency units
    this.maturityDays = 0;
  }

  grow(days) {
    this.maturityDays += days;
  }

  isMature() {
    return this.maturityDays >= this.growthRate;
  }

  harvest() {
    if (this.isMature()) {
      this.maturityDays = 0; // reset for next cycle
      return true;
    }
    return false;
  }

  getValue() {
    return this.isMature() ? this.price : 0;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices; // map of crop name to price
  }

  sellCrop(crop) {
    if (crop.harvest()) {
      return this.prices[crop.name] || 0;
    }
    return 0;
  }
}

class Farm {
  constructor(market, cropTypes) {
    this.market = market;
    this.crops = cropTypes.map(type => new Crop(type.name, type.growthRate, type.price));
  }

  plantCrop(typeName) {
    const cropType = this.crops.find(crop => crop.name === typeName);
    if (cropType) {
      this.crops.push(new Crop(cropType.name, cropType.growthRate, cropType.price));
    }
  }

  growAllCrops(days) {
    this.crops.forEach(crop => crop.grow(days));
  }

  sellAllMatureCrops() {
    let totalEarnings = 0;
    this.crops = this.crops.filter(crop => {
      totalEarnings += this.market.sellCrop(crop);
      return !crop.isMature();
    });
    return totalEarnings;
  }
}

// Demo
