  'Wheat': 10,
  'Carrot': 5
});

const farm = new Farm(market, [
  { name: 'Wheat', growthRate: 10, price: 10 },
  { name: 'Carrot', growthRate: 5, price: 5 }
]);

farm.plantCrop('Wheat');
farm.plantCrop('Carrot');

console.log('Initial crops:', farm.crops.map(crop => ({ name: crop.name, maturity: crop.maturityDays })));

farm.growAllCrops(4);
console.log('After 4 days:', farm.crops.map(crop => ({ name: crop.name, maturity: crop.maturityDays })));

farm.growAllCrops(6);
console.log('After 6 more days:', farm.crops.map(crop => ({ name: crop.name, maturity: crop.maturityDays })));

const earnings = farm.sellAllMatureCrops();
console.log('Total earnings:', earnings);
