class EventBus {
  constructor() {
    this.events = {};
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(handler => handler(data));
    }
  }

  subscribe(event, handler) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(handler);
  }
}

class Quest {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('questCompleted', this.handleQuestCompleted.bind(this));
  }

  startQuest(questId) {
    console.log(`Starting quest: ${questId}`);
    // Simulate quest completion
    setTimeout(() => {
      this.eventBus.emit('questCompleted', questId);
    }, 1000);
  }

  handleQuestCompleted(questId) {
    console.log(`Quest ${questId} completed!`);
    this.eventBus.emit('questRewards', questId);
  }
}

class Reward {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('questRewards', this.handleQuestRewards.bind(this));
  }

  handleQuestRewards(questId) {
    console.log(`Processing rewards for quest: ${questId}`);
    // Simulate reward distribution
    setTimeout(() => {
      this.eventBus.emit('rewardsDistributed', { questId, reward: 'Gold Coin' });
    }, 500);
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('rewardsDistributed', this.handleRewardsDistributed.bind(this));
    this.items = [];
  }

