class Resource {
  constructor(name, quantity) {
    this.name = name;
    this.quantity = quantity;
  }

  consume(amount) {
    if (this.quantity >= amount) {
      this.quantity -= amount;
    } else {
      this.quantity = 0;
    }
  }

  produce(amount) {
    this.quantity += amount;
  }
}

class Economy {
  constructor() {
    this.resources = {};
  }

  addResource(name, quantity = 0) {
    this.resources[name] = new Resource(name, quantity);
  }

  consumeResource(name, amount) {
    if (this.resources[name]) {
      this.resources[name].consume(amount);
    }
  }

  produceResource(name, amount) {
    if (this.resources[name]) {
      this.resources[name].produce(amount);
    } else {
      this.addResource(name, amount);
    }
  }

  getResourceQuantity(name) {
    return this.resources[name]?.quantity || 0;
  }
}

