class Trade {
  constructor() {
    this.resources = { food: 0, gold: 0, wood: 0 };
  }

  // Public API
  trade(resource, amount) {
    if (this.resources[resource] >= amount) {
      this.resources[resource] -= amount;
      return true;
    }
    return false;
  }

  receive(resource, amount) {
    this.resources[resource] += amount;
  }

  getResources() {
    return { ...this.resources };
  }
}

class Reputation {
  constructor() {
    this.standing = 0;
  }

  // Public API
  improve(amount) {
    this.standing += amount;
  }

  degrade(amount) {
    this.standing -= amount;
  }

  getStanding() {
    return this.standing;
  }
}

class Faction {
  constructor(tradeSystem, reputationSystem) {
    this.tradeSystem = tradeSystem;
    this.reputationSystem = reputationSystem;
  }

  // Public API
  performTrade(resource, amount) {
    if (this.tradeSystem.trade(resource, amount)) {
      this.reputationSystem.improve(1);
    } else {
      this.reputationSystem.degrade(1);
    }
  }

  receiveResource(resource, amount) {
    this.tradeSystem.receive(resource, amount);
    this.reputationSystem.improve(1);
  }

  getStatus() {
    return {
      resources: this.tradeSystem.getResources(),
      reputation: this.reputationSystem.getStanding(),
    };
  }
}

