  }

  getItemStock(itemName) {
    return this.items[itemName]?.stock || 0;
  }

  sellItem(itemName) {
    if (this.items[itemName] && this.items[itemName].stock > 0) {
      this.items[itemName].stock -= 1;
      return true;
    }
    return false;
  }

  addItem(itemName, price, stock) {
    this.items[itemName] = { price, stock };
  }
}

