// Economy System
class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

// Store System
class Store {
  constructor() {
    this.items = {
      'sword': { price: 50 },
      'shield': { price: 30 },
      'potion': { price: 20 }
    };
  }

  getItemPrice(itemName) {
    const item = this.items[itemName];
    return item ? item.price : null;
  }

  getAllItems() {
    return Object.keys(this.items);
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(itemName, quantity = 1) {
    if (quantity > 0) {
      if (this.items[itemName]) {
        this.items[itemName] += quantity;
      } else {
        this.items[itemName] = quantity;
      }
      return true;
    }
    return false;
  }

  removeItem(itemName, quantity = 1) {
    if (this.items[itemName] && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

// Coordinator
class GameCoordinator {
  constructor() {
    this.economy = new Economy(100);
    this.store = new Store();
    this.inventory = new Inventory();
  }

  buyItem(itemName) {
    const price = this.store.getItemPrice(itemName);
    if (price !== null && this.economy.withdraw(price)) {
      this.inventory.addItem(itemName);
      return true;
    }
    return false;
  }

  sellItem(itemName) {
    if (this.inventory.removeItem(itemName)) {
      const price = this.store.getItemPrice(itemName);
      if (price !== null) {
        this.economy.deposit(price);
        return true;
      }
    }
    return false;
  }

  getEconomyBalance() {
    return this.economy.getBalance();
  }

  getInventory() {
    return this.inventory.getInventory();
  }
}

