        this.economy = new Economy();
        this.store = new Store();
        this.inventory = new Inventory();
    }

    buyItem(itemName) {
        try {
            if (this.store.purchase(itemName, this.economy)) {
                this.inventory.addItem(itemName);
                console.log(`Purchased ${itemName}. New balance: ${this.economy.getBalance()}`);
