class Wallet {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.balance = 0;
        this.eventBus.subscribe('purchase', this.handlePurchase.bind(this));
    }

    deposit(amount) {
        this.balance += amount;
        console.log(`Deposited: $${amount}, New Balance: $${this.balance}`);
    }

    withdraw(amount) {
        if (amount > this.balance) {
            console.log(`Insufficient funds: $${this.balance}`);
        } else {
            this.balance -= amount;
            console.log(`Withdrew: $${amount}, New Balance: $${this.balance}`);
        }
    }

    handlePurchase(amount) {
        if (amount <= this.balance) {
            this.balance -= amount;
            console.log(`Purchased item for $${amount}, Remaining Balance: $${this.balance}`);
            this.eventBus.emit('purchaseSuccess');
        } else {
            console.log(`Purchase failed: Insufficient funds. Current Balance: $${this.balance}`);
        }
    }
}

