class Economy {
    constructor() {
        this._balances = new Map();
    }

    getBalance(account) {
        return this._balances.get(account) || 0;
    }

    debit(account, amount) {
        if (this._balances.has(account)) {
            this._balances.set(account, this._balances.get(account) - amount);
        } else {
            this._balances.set(account, -amount);
        }
    }

    credit(account, amount) {
        if (this._balances.has(account)) {
            this._balances.set(account, this._balances.get(account) + amount);
        } else {
            this._balances.set(account, amount);
        }
    }
}

class Inventory {
    constructor() {
        this._items = new Map();
    }

    addItem(item, quantity = 1) {
        if (this._items.has(item)) {
            this._items.set(item, this._items.get(item) + quantity);
        } else {
            this._items.set(item, quantity);
        }
    }

    getItemCount(item) {
        return this._items.get(item) || 0;
    }
}

class Store {
    constructor(economy, inventory, prices) {
        this._economy = economy;
        this._inventory = inventory;
        this._prices = prices;
    }

    purchase(player, item) {
        const price = this._prices.get(item);
        if (price === undefined) {
            console.log(`Item ${item} not found in store.`);
            return false;
        }

        const balance = this._economy.getBalance(player);
        if (balance < price) {
            console.log(`Player ${player} does not have enough funds to buy ${item}.`);
            return false;
        }

        this._economy.debit(player, price);
        this._inventory.addItem(item);
        console.log(`Player ${player} bought ${item} for ${price}.`);
        return true;
    }
}

