// Economy System
class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

// Store System
class Store {
  constructor(economy, initialItems = {}) {
    this.economy = economy;
    this.items = initialItems; // { itemName: price }
  }

  getItems() {
    return { ...this.items };
  }

  buy(itemName) {
    if (this.items[itemName] !== undefined) {
      const price = this.items[itemName];
      if (this.economy.withdraw(price)) {
        return true;
      }
    }
    return false;
  }

  addItem(itemName, price) {
    if (price > 0) {
      this.items[itemName] = price;
      return true;
    }
    return false;
  }

  removeItem(itemName) {
    if (this.items[itemName] !== undefined) {
      delete this.items[itemName];
      return true;
    }
    return false;
  }
}

// Inventory System
class Inventory {
  constructor(initialItems = {}) {
    this.items = initialItems; // { itemName: quantity }
  }

  getInventory() {
    return { ...this.items };
  }

  addItem(itemName, quantity = 1) {
    if (quantity > 0) {
      if (this.items[itemName] === undefined) {
        this.items[itemName] = 0;
      }
      this.items[itemName] += quantity;
      return true;
    }
    return false;
  }

  removeItem(itemName, quantity = 1) {
    if (this.items[itemName] !== undefined && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
      return true;
    }
    return false;
  }
}

