class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor() {
    this.prices = {
      apple: 1,
      banana: 2,
      orange: 3
    };
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  setPrice(item, price) {
    if (price >= 0) {
      this.prices[item] = price;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      return true;
    }
    return false;
  }

  getInventory() {
    return this.items;
  }
}

class Coordinator {
  constructor() {
    this.bank = new Bank(100);
    this.market = new Market();
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    const price = this.market.getPrice(item);
    const totalCost = price * quantity;

    if (this.bank.withdraw(totalCost)) {
      this.inventory.addItem(item, quantity);
      console.log(`Bought ${quantity} ${item}(s).`);
      return true;
    } else {
      console.log(`Insufficient funds to buy ${quantity} ${item}(s).`);
      return false;
    }
  }

  sellItem(item, quantity) {
    if (this.inventory.removeItem(item, quantity)) {
      const price = this.market.getPrice(item);
      const totalEarnings = price * quantity;
      this.bank.deposit(totalEarnings);
      console.log(`Sold ${quantity} ${item}(s).`);
      return true;
    } else {
      console.log(`Insufficient inventory to sell ${quantity} ${item}(s).`);
      return false;
    }
  }

  checkBalance() {
    console.log(`Current balance: ${this.bank.getBalance()}.`);
  }

  checkInventory() {
    console.log(`Current inventory:`, this.inventory.getInventory());
  }
}

// Demo
