coordinator.checkBalance(); // Current balance: 100.
coordinator.checkInventory(); // Current inventory: {}

coordinator.buyItem('apple', 5); // Bought 5 apple(s).
coordinator.buyItem('banana', 3); // Bought 3 banana(s).
coordinator.buyItem('orange', 10); // Insufficient funds to buy 10 orange(s).

coordinator.checkBalance(); // Current balance: 61.
coordinator.checkInventory(); // Current inventory: { apple: 5, banana: 3 }

coordinator.sellItem('apple', 2); // Sold 2 apple(s).
coordinator.sellItem('orange', 1); // Insufficient inventory to sell 1 orange(s).

