class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  calculatePrice(quantity) {
    // Simple pricing model: price increases with quantity
    return this.basePrice * (1 + 0.1 * quantity);
  }
}

class Demand {
  constructor(initialDemand) {
    this.demand = initialDemand;
  }

  updateDemand(price) {
    // Demand decreases as price increases
    return Math.max(0, this.demand - Math.floor(price / 10));
  }
}

class Store {
  constructor(pricingSystem, demandSystem) {
    this.pricingSystem = pricingSystem;
    this.demandSystem = demandSystem;
  }

  sell(quantity) {
    const price = this.pricingSystem.calculatePrice(quantity);
    const demand = this.demandSystem.updateDemand(price);
    return { price, demand };
  }
}

// Top-level coordinator
function runGameSimulation() {
  const pricing = new Pricing(10);
