class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }

  getIngredients() {
    return this.ingredients;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { itemName: quantity }
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  hasIngredients(recipe) {
    const ingredients = recipe.getIngredients();
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  getInventory() {
    return this.items;
  }
}

class Crafting {
  constructor(inventory) {
    this.inventory = inventory;
    this.recipes = []; // Array of Recipe instances
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe && this.inventory.hasIngredients(recipe)) {
      for (const [item, quantity] of Object.entries(recipe.getIngredients())) {
        this.inventory.removeItem(item, quantity);
      }
      console.log(`Crafted: ${recipeName}`);
      return true;
    } else {
      console.log(`Cannot craft: ${recipeName}`);
      return false;
    }
  }

  listRecipes() {
    return this.recipes.map(recipe => recipe.name);
  }
}

