class Building {
    constructor(resourceSystem, economySystem) {
        this.resourceSystem = resourceSystem;
        this.economySystem = economySystem;
    }

    constructBuilding(type) {
        const resourcesNeeded = this.resourceSystem.getResourcesNeededForBuilding(type);
        if (this.resourceSystem.checkResources(resourcesNeeded)) {
            this.resourceSystem.useResources(resourcesNeeded);
            this.economySystem.increaseGDP(1000); // Assuming GDP increases by 1000 for each building constructed
            console.log(`Constructed a ${type} building. GDP increased by 1000.`);
        } else {
            console.log(`Not enough resources to construct a ${type} building.`);
        }
    }
}

class Resource {
    constructor() {
        this.resources = {
            wood: 1000,
            stone: 500,
            metal: 250
        };
    }

    getResourcesNeededForBuilding(type) {
        switch (type) {
            case 'house':
                return { wood: 100, stone: 50, metal: 25 };
            case 'factory':
                return { wood: 200, stone: 100, metal: 50 };
            default:
                return { wood: 0, stone: 0, metal: 0 };
        }
    }

    checkResources(needed) {
        return Object.keys(needed).every(key => this.resources[key] >= needed[key]);
    }

    useResources(needed) {
        Object.keys(needed).forEach(key => this.resources[key] -= needed[key]);
    }
}

class Economy {
    constructor() {
        this.gdp = 10000; // Initial GDP
    }

    increaseGDP(amount) {
        this.gdp += amount;
    }

    getGDP() {
        return this.gdp;
    }
}

