class Recipe {
    constructor(name, ingredients, result) {
        this.name = name;
        this.ingredients = ingredients; // { item: quantity }
        this.result = result; // { item: quantity }
    }

    canCraft(inventory) {
        for (let [item, quantity] of Object.entries(this.ingredients)) {
            if (!inventory.hasItem(item, quantity)) {
                return false;
            }
        }
        return true;
    }

    craft(inventory) {
        for (let [item, quantity] of Object.entries(this.ingredients)) {
            inventory.removeItem(item, quantity);
        }
        inventory.addItem(this.result.item, this.result.quantity);
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
        }
    }

    hasItem(item, quantity) {
        return this.items[item] && this.items[item] >= quantity;
    }

    listItems() {
        return this.items;
    }
}

class Economy {
    constructor(prices) {
        this.prices = prices; // { item: price }
    }

    getCost(item, quantity) {
        return this.prices[item] * quantity;
    }

    debit(item, quantity) {
        // Simulate a debit from the economy
        console.log(`Debited ${quantity} ${item} for ${this.getCost(item, quantity)} gold.`);
    }
}

class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
    }

    purchase(item, quantity) {
        const cost = this.economy.getCost(item, quantity);
        if (this.inventory.hasItem(item, cost)) {
            this.economy.debit(item, quantity);
            this.inventory.removeItem(item, cost);
            this.inventory.addItem(item, quantity);
            return true;
        }
        return false;
    }
}

