      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
    }
  }

  hasIngredients(recipe) {
    const ingredients = recipe.getIngredients();
    for (const [item, requiredQuantity] of Object.entries(ingredients)) {
      if (!this.items[item] || this.items[item] < requiredQuantity) {
        return false;
      }
    }
    return true;
  }

  getItems() {
    return { ...this.items };
  }
}

class Crafting {
  constructor(inventory) {
    this.inventory = inventory;
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe) return false;
    return this.inventory.hasIngredients(recipe);
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe) return false;
    if (!this.canCraft(recipeName)) return false;

    const ingredients = recipe.getIngredients();
    for (const [item, quantity] of Object.entries(ingredients)) {
      this.inventory.removeItem(item, quantity);
    }

