class Trade {
    constructor(prices) {
        this.prices = prices;
    }

    buy(item, quantity) {
        if (this.prices[item] !== undefined) {
            return quantity * this.prices[item];
        }
        throw new Error(`Item ${item} not available for trade.`);
    }

    sell(item, quantity) {
        if (this.prices[item] !== undefined) {
            return quantity * this.prices[item];
        }
        throw new Error(`Item ${item} not available for trade.`);
    }
}

// Reputation System
class Reputation {
    constructor() {
        this.standing = 0;
    }

    improve(amount) {
        this.standing += amount;
    }

    deteriorate(amount) {
        this.standing -= amount;
    }

    getStanding() {
        return this.standing;
    }
}

// Faction System
class Faction {
    constructor(name, tradeSystem, reputationSystem) {
        this.name = name;
        this.tradeSystem = tradeSystem;
        this.reputationSystem = reputationSystem;
    }

    trade(item, quantity, action) {
        try {
            const cost = action === 'buy' ? this.tradeSystem.buy(item, quantity) : this.tradeSystem.sell(item, quantity);
            this.reputationSystem.improve(1); // Improve reputation for successful trade
            return cost;
        } catch (error) {
            this.reputationSystem.deteriorate(1); // Deteriorate reputation for failed trade
            throw error;
        }
    }

    getReputation() {
        return this.reputationSystem.getStanding();
    }
}

