    this.items = {
      apple: { price: 10, stock: 10 },
      banana: { price: 5, stock: 15 },
      carrot: { price: 3, stock: 20 }
    };
  }

  getItemPrice(item) {
    return this.items[item]?.price || 0;
  }

  getItemStock(item) {
    return this.items[item]?.stock || 0;
  }

  sellItem(item, quantity) {
    if (this.items[item] && this.items[item].stock >= quantity) {
      this.items[item].stock -= quantity;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class GameCoordinator {
  constructor() {
    this.economy = new Economy();
    this.store = new Store();
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    const price = this.store.getItemPrice(item);
    const totalCost = price * quantity;

    if (this.economy.withdraw(totalCost) && this.store.sellItem(item, quantity)) {
      this.inventory.addItem(item, quantity);
      return true;
    }
    return false;
  }

  displayStatus() {
    console.log(`Balance: ${this.economy.getBalance()}`);
    console.log(`Inventory:`, this.inventory.items);
  }
}

