class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Economy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('purchaseMade', this.handlePurchase.bind(this));
  }

  addFunds(amount) {
    this.balance += amount;
    console.log(`Added ${amount} to balance. New balance: ${this.balance}`);
  }

  handlePurchase(data) {
    const { price } = data;
    if (this.balance >= price) {
      this.balance -= price;
      console.log(`Purchase successful. Remaining balance: ${this.balance}`);
      this.eventBus.emit('purchaseConfirmed', data);
    } else {
      console.log('Insufficient funds for purchase.');
    }
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = [
      { name: 'Sword', price: 50 },
      { name: 'Shield', price: 30 }
    ];
    this.eventBus.subscribe('requestItems', this.handleRequestItems.bind(this));
    this.eventBus.subscribe('requestPurchase', this.handleRequestPurchase.bind(this));
  }

  handleRequestItems() {
    console.log('Available items in store:');
    this.items.forEach(item => console.log(`${item.name} - ${item.price}`));
  }

  handleRequestPurchase(data) {
    const { item } = data;
    const selectedItem = this.items.find(i => i.name === item);
    if (selectedItem) {
      console.log(`Attempting to purchase: ${selectedItem.name}`);
      this.eventBus.emit('purchaseMade', { price: selectedItem.price });
    } else {
      console.log('Item not found in store.');
    }
  }

  requestItems() {
    this.eventBus.emit('requestItems');
  }

  requestPurchase(itemName) {
    this.eventBus.emit('requestPurchase', { item: itemName });
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = [];
    this.eventBus.subscribe('purchaseConfirmed', this.handlePurchaseConfirmed.bind(this));
  }

  handlePurchaseConfirmed(data) {
    const { item } = data;
    const selectedItem = this.items.find(i => i.name === item);
    if (selectedItem) {
      selectedItem.quantity++;
    } else {
      this.items.push({ name: item, quantity: 1 });
    }
    console.log('Inventory updated:');
    this.items.forEach(item => console.log(`${item.name} - ${item.quantity}`));
  }
}

