class Clock {
  constructor() {
    this.time = 0;
  }

  tick() {
    this.time++;
    return this.time;
  }

  getTime() {
    return this.time;
  }
}

class Hunger {
  constructor(clock, maxHunger = 100) {
    this.clock = clock;
    this.hunger = 0;
    this.maxHunger = maxHunger;
  }

  update() {
    this.hunger += this.clock.tick();
    if (this.hunger > this.maxHunger) {
      this.hunger = this.maxHunger;
    }
    return this.hunger;
  }

  eat(amount) {
    this.hunger -= amount;
    if (this.hunger < 0) {
      this.hunger = 0;
    }
  }

  getHunger() {
    return this.hunger;
  }
}

class Energy {
  constructor(clock, maxEnergy = 100) {
    this.clock = clock;
    this.energy = maxEnergy;
    this.maxEnergy = maxEnergy;
  }

  update() {
    this.energy -= this.clock.tick();
    if (this.energy < 0) {
      this.energy = 0;
    }
    return this.energy;
  }

  rest(amount) {
    this.energy += amount;
    if (this.energy > this.maxEnergy) {
      this.energy = this.maxEnergy;
    }
  }

  getEnergy() {
    return this.energy;
  }
}

// Demo
const clock = new Clock();
const hunger = new Hunger(clock);
const energy = new Energy(clock);

console.log(`Initial Time: ${clock.getTime()}`);
console.log(`Initial Hunger: ${hunger.getHunger()}`);
console.log(`Initial Energy: ${energy.getEnergy()}`);

for (let i = 0; i < 10; i++) {
  clock.tick();
  hunger.update();
  energy.update();

  console.log(`Time: ${clock.getTime()}`);
  console.log(`Hunger: ${hunger.getHunger()}`);
  console.log(`Energy: ${energy.getEnergy()}`);

  if (i % 3 === 0) {
    hunger.eat(10);
    console.log(`After eating: ${hunger.getHunger()}`);
  }

  if (i % 4 === 0) {
    energy.rest(10);
    console.log(`After resting: ${energy.getEnergy()}`);
  }
}
