class Bank {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(prices = {}) {
        this.prices = prices;
    }

    buy(item, amount) {
        const price = this.prices[item];
        if (price !== undefined && amount > 0) {
            return price * amount;
        }
        return null;
    }

    setPrice(item, price) {
        if (price >= 0) {
            this.prices[item] = price;
            return true;
        }
        return false;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, amount) {
        if (amount > 0) {
            this.items[item] = (this.items[item] || 0) + amount;
            return true;
        }
        return false;
    }

    removeItem(item, amount) {
        if (this.items[item] !== undefined && amount > 0 && this.items[item] >= amount) {
            this.items[item] -= amount;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }
}

class Coordinator {
    constructor() {
        this.bank = new Bank(100);
        this.market = new Market({ apple: 1, banana: 2 });
        this.inventory = new Inventory();
    }

    buyItem(item, amount) {
        const cost = this.market.buy(item, amount);
        if (cost !== null && this.bank.withdraw(cost)) {
            this.inventory.addItem(item, amount);
            console.log(`Bought ${amount} ${item}(s) for ${cost}. Balance: ${this.bank.getBalance()}`);
            return true;
        }
        console.log(`Failed to buy ${amount} ${item}(s).`);
        return false;
    }

    sellItem(item, amount) {
        if (this.inventory.removeItem(item, amount)) {
            const price = this.market.buy(item, amount);
            if (this.bank.deposit(price)) {
                console.log(`Sold ${amount} ${item}(s) for ${price}. Balance: ${this.bank.getBalance()}`);
                return true;
            }
        }
        console.log(`Failed to sell ${amount} ${item}(s).`);
        return false;
    }

    checkInventory() {
        console.log('Inventory:', this.inventory.items);
    }

    checkBalance() {
        console.log('Balance:', this.bank.getBalance());
    }
}

