class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      if (this.items[item]) {
        this.items[item] += quantity;
      } else {
        this.items[item] = quantity;
      }
      return true;
    }
    return false;
  }

  removeItem(item, quantity = 1) {
    if (quantity > 0 && this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Store {
  constructor(economy, inventory, itemPrices) {
    this.economy = economy;
    this.inventory = inventory;
    this.itemPrices = itemPrices;
  }

  buyItem(item, quantity = 1) {
    const price = this.itemPrices[item] * quantity;
    if (price > 0 && this.economy.withdraw(price) && this.inventory.addItem(item, quantity)) {
      return true;
    }
    return false;
  }

  sellItem(item, quantity = 1) {
    const price = this.itemPrices[item] * quantity;
    if (price > 0 && this.inventory.removeItem(item, quantity) && this.economy.deposit(price)) {
      return true;
    }
    return false;
  }
}

