class LevelUp {
  constructor(skill, experience, levelThreshold = 1000) {
    this.skill = skill;
    this.experience = experience;
    this.levelThreshold = levelThreshold;
  }

  checkLevelUp() {
    if (this.experience.getExperience() >= this.levelThreshold) {
      const currentLevel = this.skill.getLevel();
      this.skill.setLevel(currentLevel + 1);
      this.experience.addExperience(-this.levelThreshold);
      return true;
    }
    return false;
  }

  getSkillLevel() {
    return this.skill.getLevel();
  }

  getExperience() {
    return this.experience.getExperience();
  }
}

