    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(handler);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(handler => handler(data));
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('itemUsed', this.removeItem.bind(this));
    this.eventBus.subscribe('itemCrafted', this.addItem.bind(this));
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
    console.log(`Added ${quantity} ${item}(s) to inventory. Current stock: ${this.items[item]}`);
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      console.log(`Removed ${quantity} ${item}(s) from inventory. Current stock: ${this.items[item] || '0'}`);
    } else {
      console.log(`Not enough ${item}(s) in inventory.`);
    }
  }

  hasItems(recipe) {
    for (const [item, quantity] of Object.entries(recipe)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }
}

