class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return this.ingredients;
  }
}

class Inventory {
  constructor(items = {}) {
    this.items = items; // { itemName: quantity }
  }

  addItem(itemName, quantity) {
    this.items[itemName] = (this.items[itemName] || 0) + quantity;
  }

  removeItem(itemName, quantity) {
    if (this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
      return true;
    }
    return false;
  }

  getItems() {
    return this.items;
  }

  hasIngredients(recipe) {
    const ingredients = recipe.getIngredients();
    for (const [ingredient, needed] of Object.entries(ingredients)) {
      if (!this.items[ingredient] || this.items[ingredient] < needed) {
        return false;
      }
    }
    return true;
  }
}

class Crafting {
  constructor(recipeBook, inventory) {
    this.recipeBook = recipeBook; // { recipeName: Recipe }
    this.inventory = inventory;
  }

  canCraft(recipeName) {
    const recipe = this.recipeBook[recipeName];
    if (!recipe) {
      return false;
    }
    return this.inventory.hasIngredients(recipe);
  }

  craft(recipeName) {
    const recipe = this.recipeBook[recipeName];
    if (!recipe) {
      return false;
    }
    if (!this.inventory.hasIngredients(recipe)) {
      return false;
    }
    const ingredients = recipe.getIngredients();
    for (const [ingredient, needed] of Object.entries(ingredients)) {
      this.inventory.removeItem(ingredient, needed);
    }
    return true;
  }
}

// Demo
