  "Iron Armor": new Recipe("Iron Armor", { "Iron": 5, "Leather": 2 })
};

const inventory = new Inventory({
  "Wood": 5,
  "Stone": 2,
  "Iron": 10,
  "Leather": 3
});

const craftingSystem = new Crafting(recipeBook, inventory);

console.log("Can craft Wooden Sword:", craftingSystem.canCraft("Wooden Sword")); // true
console.log("Craft Wooden Sword:", craftingSystem.craft("Wooden Sword")); // true
console.log("Inventory after crafting:", inventory.getItems()); // { Wood: 2, Stone: 1, Iron: 10, Leather: 3 }

