class Crafting {
  constructor(recipeBook, inventory) {
    this.recipeBook = recipeBook; // Map of recipe names to Recipe objects
    this.inventory = inventory;
  }

  canCraft(recipeName) {
    const recipe = this.recipeBook.get(recipeName);
    if (!recipe) return false;

    const ingredients = recipe.getIngredients();
    for (const [ingredient, quantity] of Object.entries(ingredients)) {
      if (!this.inventory.getItems()[ingredient] || this.inventory.getItems()[ingredient] < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName) {
    if (this.canCraft(recipeName)) {
      const recipe = this.recipeBook.get(recipeName);
      const ingredients = recipe.getIngredients();
      for (const [ingredient, quantity] of Object.entries(ingredients)) {
        this.inventory.removeItem(ingredient, quantity);
      }
      console.log(`Crafted: ${recipe.getName()}`);
      return true;
    }
    console.log(`Cannot craft: ${recipeName}`);
    return false;
  }
}

