class Pricing {
    constructor() {
        this.prices = {
            itemA: 10,
            itemB: 20,
            itemC: 30
        };
    }

    getPrice(item) {
        return this.prices[item] || 0;
    }

    updatePrice(item, newPrice) {
        if (this.prices[item] !== undefined) {
            this.prices[item] = newPrice;
        }
    }
}

class Demand {
    constructor() {
        this.demand = {
            itemA: 5,
            itemB: 10,
            itemC: 15
        };
    }

    getDemand(item) {
        return this.demand[item] || 0;
    }

    updateDemand(item, change) {
        if (this.demand[item] !== undefined) {
            this.demand[item] += change;
            if (this.demand[item] < 0) this.demand[item] = 0;
        }
    }
}

class Store {
    constructor(pricing, demand) {
        this.pricing = pricing;
        this.demand = demand;
    }

    sellItem(item, quantity) {
        const price = this.pricing.getPrice(item);
        const demand = this.demand.getDemand(item);

        if (demand >= quantity) {
            this.demand.updateDemand(item, -quantity);
            return { success: true, total: price * quantity };
        } else {
            return { success: false, message: "Not enough demand" };
        }
    }

    restockItem(item, quantity) {
        this.demand.updateDemand(item, quantity);
    }
}

