class Wallet {
  constructor() {
    this.balance = 0;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Shop {
  constructor() {
    this.items = {
      apple: 10,
      banana: 5,
      carrot: 3
    };
  }

  getItems() {
    return { ...this.items };
  }

  getItemPrice(item) {
    return this.items[item] || 0;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (quantity > 0 && this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class GameCoordinator {
  constructor() {
    this.wallet = new Wallet();
    this.shop = new Shop();
    this.inventory = new Inventory();
  }

  buyItem(item) {
    const price = this.shop.getItemPrice(item);
    if (price > 0 && this.wallet.withdraw(price)) {
      this.inventory.addItem(item, 1);
      return true;
    }
    return false;
  }

  sellItem(item) {
    const price = this.shop.getItemPrice(item);
    if (price > 0 && this.inventory.removeItem(item, 1)) {
      this.wallet.deposit(price);
      return true;
    }
    return false;
  }

  getWalletBalance() {
    return this.wallet.getBalance();
  }

  getInventory() {
    return this.inventory.getInventory();
  }

  getShopItems() {
    return this.shop.getItems();
  }
}

