class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('itemAdded', this.handleItemAdded.bind(this));
    this.eventBus.subscribe('itemUsed', this.handleItemUsed.bind(this));
  }

  addItem(item, quantity) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
    this.eventBus.emit('itemAdded', { item, quantity });
  }

  useItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      this.eventBus.emit('itemUsed', { item, quantity });
      return true;
    }
    return false;
  }

  handleItemAdded({ item, quantity }) {
    console.log(`Inventory: Added ${quantity} ${item}(s). Current stock: ${this.items[item]}`);
  }

  handleItemUsed({ item, quantity }) {
    console.log(`Inventory: Used ${quantity} ${item}(s). Remaining stock: ${this.items[item]}`);
  }
}

class Recipe {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = {};
    this.eventBus.subscribe('recipeRegistered', this.handleRecipeRegistered.bind(this));
    this.eventBus.subscribe('craftRequested', this.handleCraftRequested.bind(this));
  }

  registerRecipe(result, ingredients) {
    this.recipes[result] = ingredients;
    this.eventBus.emit('recipeRegistered', { result, ingredients });
  }

  craft(result) {
    if (this.recipes[result]) {
      const ingredients = this.recipes[result];
      this.eventBus.emit('craftRequested', { result, ingredients });
    }
  }

  handleRecipeRegistered({ result, ingredients }) {
    console.log(`Recipe registered: Crafting ${result} requires ${JSON.stringify(ingredients)}`);
  }

  handleCraftRequested({ result, ingredients }) {
    console.log(`Crafting requested: ${result}`);
    this.eventBus.emit('ingredientsChecked', { result, ingredients });
  }
}

class Crafting {
  constructor(eventBus, inventory) {
    this.eventBus = eventBus;
    this.inventory = inventory;
    this.eventBus.subscribe('ingredientsChecked', this.handleIngredientsChecked.bind(this));
  }

  handleIngredientsChecked({ result, ingredients }) {
    const canCraft = Object.keys(ingredients).every(item => this.inventory.useItem(item, ingredients[item]));
    if (canCraft) {
      this.inventory.addItem(result, 1);
      console.log(`Crafting successful: Added 1 ${result}`);
    } else {
      console.log(`Crafting failed: Insufficient ingredients`);
    }
  }
}

