class Hunger {
  constructor(consumptionRate, maxHunger) {
    this.consumptionRate = consumptionRate;
    this.maxHunger = maxHunger;
    this.currentHunger = 0;
  }

  update() {
    this.currentHunger = Math.min(this.currentHunger + this.consumptionRate, this.maxHunger);
  }

  eat(amount) {
    this.currentHunger = Math.max(this.currentHunger - amount, 0);
  }

  getHungerLevel() {
    return this.currentHunger;
  }
}

class Energy {
  constructor(consumptionRate, maxEnergy) {
    this.consumptionRate = consumptionRate;
    this.maxEnergy = maxEnergy;
    this.currentEnergy = maxEnergy;
  }

  update() {
    this.currentEnergy = Math.max(this.currentEnergy - this.consumptionRate, 0);
  }

  rest(amount) {
    this.currentEnergy = Math.min(this.currentEnergy + amount, this.maxEnergy);
  }

  getEnergyLevel() {
    return this.currentEnergy;
  }
}

class Clock {
  constructor(tickRate) {
    this.tickRate = tickRate;
    this.time = 0;
  }

  tick() {
    this.time += this.tickRate;
  }

  getTime() {
    return this.time;
  }
}

// Demo
const hunger = new Hunger(1, 100);
const energy = new Energy(2, 100);
const clock = new Clock(1);

function simulateDay() {
  console.log(`Time: ${clock.getTime()}, Hunger: ${hunger.getHungerLevel()}, Energy: ${energy.getEnergyLevel()}`);

  for (let i = 0; i < 12; i++) {
    clock.tick();
    hunger.update();
    energy.update();

    if (i % 3 === 0) {
      hunger.eat(10);
      console.log(`Ate at time ${clock.getTime()}`);
    }

    if (i % 4 === 0) {
      energy.rest(10);
      console.log(`Rested at time ${clock.getTime()}`);
    }

    console.log(`Time: ${clock.getTime()}, Hunger: ${hunger.getHungerLevel()}, Energy: ${energy.getEnergyLevel()}`);
  }
}

simulateDay();
