// Order System
class Order {
  constructor(orderId, items) {
    this.orderId = orderId;
    this.items = items;
    this.status = 'received';
  }

  markPreparing() {
    this.status = 'preparing';
  }

  markReady() {
    this.status = 'ready';
  }

  markCompleted() {
    this.status = 'completed';
  }

  toString() {
    return `Order ID: ${this.orderId}, Items: ${this.items.join(', ')}, Status: ${this.status}`;
  }
}

// Kitchen System
class Kitchen {
  constructor() {
    this.orders = [];
  }

  addOrder(order) {
    this.orders.push(order);
    order.markPreparing();
    console.log(`Kitchen: ${order.toString()}`);
    return order;
  }

  prepareNextOrder() {
    if (this.orders.length > 0) {
      const order = this.orders[0];
      order.markReady();
      console.log(`Kitchen: ${order.toString()}`);
      this.orders.shift();
    }
  }
}

// Customer System
class Customer {
  constructor() {
    this.orders = [];
  }

  placeOrder(kitchen, items) {
    const orderId = Date.now();
    const order = new Order(orderId, items);
    const newOrder = kitchen.addOrder(order);
    this.orders.push(newOrder);
    return newOrder;
  }

  collectOrder(kitchen) {
    for (let order of this.orders) {
      if (order.status === 'ready') {
        order.markCompleted();
        console.log(`Customer: ${order.toString()}`);
        this.orders = this.orders.filter(o => o !== order);
        return order;
      }
    }
    return null;
  }
}

// Coordinator
class Coordinator {
  constructor() {
    this.kitchen = new Kitchen();
    this.customer = new Customer();
  }

  simulate() {
    console.log('Simulation Start');
    const order1 = this.customer.placeOrder(this.kitchen, ['burger', 'fries']);
    const order2 = this.customer.placeOrder(this.kitchen, ['pizza', 'soda']);
    this.kitchen.prepareNextOrder();
    this.customer.collectOrder(this.kitchen);
    this.kitchen.prepareNextOrder();
    this.customer.collectOrder(this.kitchen);
    console.log('Simulation End');
  }
}

