class Quest {
  constructor() {
    this.steps = {};
    this.currentStep = null;
  }

  addStep(stepName, dialogueKey) {
    this.steps[stepName] = dialogueKey;
  }

  startQuest(stepName) {
    if (this.steps[stepName]) {
      this.currentStep = stepName;
    } else {
      console.log("Quest step not found.");
    }
  }

  getCurrentDialogueKey() {
    return this.currentStep ? this.steps[this.currentStep] : null;
  }
}

class GameCoordinator {
  constructor() {
    this.dialogue = new Dialogue();
    this.flags = new Flags();
    this.quest = new Quest();
  }

  initializeGame() {
    this.dialogue.addResponse("greet", "Hello, adventurer!");
    this.dialogue.addResponse("quest", "Your quest begins now.");
    this.dialogue.addResponse("complete", "Congratulations, you completed the quest!");

    this.quest.addStep("start", "greet");
    this.quest.addStep("beginQuest", "quest");
    this.quest.addStep("finishQuest", "complete");

    this.flags.setFlag("questStarted", false);
  }

  startNewQuest() {
    this.flags.setFlag("questStarted", true);
    this.quest.startQuest("start");
    this.displayDialogue();
  }

  proceedToNextQuestStep() {
    if (this.flags.getFlag("questStarted")) {
      if (this.quest.currentStep === "start") {
        this.quest.startQuest("beginQuest");
      } else if (this.quest.currentStep === "beginQuest") {
        this.quest.startQuest("finishQuest");
      }
      this.displayDialogue();
    } else {
      console.log("No active quest.");
    }
  }

  displayDialogue() {
    const dialogueKey = this.quest.getCurrentDialogueKey();
    if (dialogueKey) {
      console.log(this.dialogue.getResponse(dialogueKey));
    }
  }
}

