class Trade {
    constructor(prices) {
        this.prices = prices;
    }

    getMarketPrice(item) {
        return this.prices[item] || 0;
    }

    trade(item, quantity, buyer, seller) {
        const price = this.getMarketPrice(item);
        if (buyer.balance >= price * quantity && seller.inventory[item] >= quantity) {
            buyer.balance -= price * quantity;
            seller.inventory[item] -= quantity;
            return true;
        }
        return false;
    }
}

class Reputation {
    constructor(initialReputation = 100) {
        this.reputation = initialReputation;
    }

    adjustReputation(change) {
        this.reputation += change;
        if (this.reputation < 0) this.reputation = 0;
    }

    getReputation() {
        return this.reputation;
    }
}

class Faction {
    constructor(name, tradeSystem, reputationSystem) {
        this.name = name;
        this.tradeSystem = tradeSystem;
        this.reputationSystem = reputationSystem;
    }

    performTrade(item, quantity, otherFaction) {
        if (this.tradeSystem.trade(item, quantity, this, otherFaction)) {
            console.log(`${this.name} traded ${quantity} ${item} with ${otherFaction.name}`);
            this.reputationSystem.adjustReputation(10);
            otherFaction.reputationSystem.adjustReputation(5);
        } else {
            console.log(`${this.name} failed to trade ${quantity} ${item} with ${otherFaction.name}`);
            this.reputationSystem.adjustReputation(-5);
        }
    }

    getReputation() {
        return this.reputationSystem.getReputation();
    }
}

