class RarityTable {
    constructor(rarityDistribution) {
        this.rarityDistribution = rarityDistribution;
    }

    getRandomRarity() {
        const total = Object.values(this.rarityDistribution).reduce((acc, val) => acc + val, 0);
        const random = Math.random() * total;
        let cumulative = 0;

        for (const [rarity, weight] of Object.entries(this.rarityDistribution)) {
            cumulative += weight;
            if (random < cumulative) {
                return rarity;
            }
        }
        return null; // Should never reach here
    }
}

