class Farm {
  constructor() {
    this.crops = [];
  }

  plant(seed) {
    const crop = new Crop(seed);
    this.crops.push(crop);
    console.log(`Planted ${seed} crop.`);
    return crop;
  }

  harvest() {
    const ripeCrops = this.crops.filter(crop => crop.isRipe());
    ripeCrops.forEach(crop => {
      console.log(`Harvested ${crop.getSeed()} crop.`);
    });
    this.crops = this.crops.filter(crop => !crop.isRipe());
    return ripeCrops;
  }
}

class Crop {
  constructor(seed) {
    this.seed = seed;
    this.daysGrown = 0;
  }

  grow() {
    this.daysGrown++;
    console.log(`${this.seed} crop has grown for ${this.daysGrown} days.`);
  }

  isRipe() {
    return this.daysGrown >= 3; // Arbitrary ripening condition
  }

  getSeed() {
    return this.seed;
  }
}

class Market {
  constructor() {
    this.inventory = {};
  }

  buyCrop(crop) {
    const seed = crop.getSeed();
    if (!this.inventory[seed]) {
      this.inventory[seed] = 0;
    }
    this.inventory[seed]++;
    console.log(`Bought ${seed} crop. Inventory: ${this.inventory[seed]}`);
  }

  sellCrop(seed) {
    if (this.inventory[seed] > 0) {
      this.inventory[seed]--;
      console.log(`Sold ${seed} crop. Inventory: ${this.inventory[seed]}`);
      return true;
    } else {
      console.log(`No ${seed} crops available to sell.`);
      return false;
    }
  }
}

