    const newAmount = Math.min(this.currentResources + amount, this.capacity);
    this.currentResources = newAmount;
    return this.currentResources;
  }

  useResources(amount) {
    if (this.currentResources >= amount) {
      this.currentResources -= amount;
      return true;
    }
    return false;
  }

  getResources() {
    return this.currentResources;
  }
}

// Resource System
class Resource {
  constructor(name, amount) {
    this.name = name;
    this.amount = amount;
  }

  collect(amount) {
    this.amount += amount;
    return this.amount;
  }

  spend(amount) {
    if (this.amount >= amount) {
      this.amount -= amount;
      return true;
    }
    return false;
  }

  getAmount() {
    return this.amount;
  }
}

// Economy System
class Economy {
  constructor() {
    this.resources = {};
  }

  addResource(name, initialAmount = 0) {
    this.resources[name] = new Resource(name, initialAmount);
  }

  collectResource(name, amount) {
    if (this.resources[name]) {
      return this.resources[name].collect(amount);
    }
    return 0;
  }

  spendResource(name, amount) {
    if (this.resources[name]) {
      return this.resources[name].spend(amount);
    }
    return false;
  }

  getResourceAmount(name) {
    if (this.resources[name]) {
      return this.resources[name].getAmount();
    }
    return 0;
  }
}

