class Crafting {
  constructor() {
    this.recipes = {};
  }

  addRecipe(recipe) {
    this.recipes[recipe.getId()] = recipe;
  }

  canCraft(recipeId) {
    const recipe = this.recipes[recipeId];
    if (recipe) {
      return recipe.getIngredients();
    }
    return null;
  }

  craft(recipeId, inventory) {
    const recipe = this.recipes[recipeId];
    if (recipe && inventory.hasItems(recipe.getIngredients())) {
      const ingredients = recipe.getIngredients();
      for (const [item, quantity] of Object.entries(ingredients)) {
        inventory.removeItem(item, quantity);
      }
      inventory.addItem(recipe.getResult());
      return recipe.getResult();
    }
    return null;
  }
}

