    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe) {
      for (const [item, quantity] of Object.entries(recipe.ingredients)) {
        if (!this.inventory.removeItem(item, quantity)) {
          return false;
        }
      }
      this.inventory.addItem(recipe.result);
      return true;
    }
    return false;
  }

