    this.prices = prices;
  }

  getPrices() {
    return { ...this.prices };
  }

  debit(item, quantity = 1) {
    const price = this.prices[item];
    if (price !== undefined) {
      this.prices[item] -= quantity * price;
      return true;
    }
    return false;
  }
}

