class TradeSystem {
  constructor() {
    this.trades = {};
  }

  recordTrade(participants, resource, amount) {
    const tradeId = `${participants.join('-')}-${resource}`;
    this.trades[tradeId] = { participants, resource, amount };
    return tradeId;
  }

  getTrade(tradeId) {
    return this.trades[tradeId] || null;
  }
}

class ReputationSystem {
  constructor() {
    this.reputation = {};
  }

  updateReputation(entity, points) {
    if (!this.reputation[entity]) {
      this.reputation[entity] = 0;
    }
    this.reputation[entity] += points;
  }

  getReputation(entity) {
    return this.reputation[entity] || 0;
  }
}

class FactionSystem {
  constructor() {
    this.factions = {};
  }

  joinFaction(entity, faction) {
    if (!this.factions[faction]) {
      this.factions[faction] = [];
    }
    if (!this.factions[faction].includes(entity)) {
      this.factions[faction].push(entity);
    }
  }

  getFactionMembers(faction) {
    return this.factions[faction] || [];
  }
}

class Coordinator {
  constructor() {
    this.tradeSystem = new TradeSystem();
    this.reputationSystem = new ReputationSystem();
    this.factionSystem = new FactionSystem();
  }

  conductTrade(participants, resource, amount) {
    const tradeId = this.tradeSystem.recordTrade(participants, resource, amount);
    console.log(`Trade recorded: ${tradeId} - ${resource} (${amount}) between ${participants.join(' and ')}`);
    return tradeId;
  }

  updateReputation(entity, points) {
    this.reputationSystem.updateReputation(entity, points);
    console.log(`Reputation updated: ${entity} now has ${this.reputationSystem.getReputation(entity)} points`);
  }

  joinFaction(entity, faction) {
