class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, callback) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(callback => callback(data));
    }
  }
}

class Economy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;

    this.eventBus.subscribe('itemPurchased', ({ price }) => {
      this.balance -= price;
      console.log(`Economy: Item purchased. New balance: ${this.balance}`);
    });

    this.eventBus.subscribe('itemSold', ({ price }) => {
      this.balance += price;
      console.log(`Economy: Item sold. New balance: ${this.balance}`);
    });
  }

  getBalance() {
    return this.balance;
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {
      sword: { name: 'sword', price: 50 },
      shield: { name: 'shield', price: 30 }
    };

    this.eventBus.subscribe('buyItem', ({ itemName }) => {
      const item = this.items[itemName];
      if (item) {
        this.eventBus.emit('itemPurchased', { price: item.price });
        console.log(`Store: ${itemName} purchased for ${item.price}`);
      } else {
        console.log(`Store: Item ${itemName} not found.`);
      }
    });

    this.eventBus.subscribe('sellItem', ({ itemName, price }) => {
      this.eventBus.emit('itemSold', { price });
      console.log(`Store: ${itemName} sold for ${price}`);
    });
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = [];

    this.eventBus.subscribe('itemPurchased', ({ price }) => {
      const itemName = Object.keys(this.items).find(key => this.items[key] === price);
      if (itemName) {
        this.items[itemName] -= 1;
        if (this.items[itemName] === 0) {
          delete this.items[itemName];
        }
        console.log(`Inventory: ${itemName} removed. Remaining: ${this.items[itemName]}`);
      }
    });

    this.eventBus.subscribe('itemSold', ({ price }) => {
      const itemName = Object.keys(this.items).find(key => this.items[key] === price);
      if (itemName) {
        this.items[itemName] += 1;
        console.log(`Inventory: ${itemName} added. Total: ${this.items[itemName]}`);
      }
    });

    this.eventBus.subscribe('buyItem', ({ itemName }) => {
      this.items[itemName] = (this.items[itemName] || 0) + 1;
    });

    this.eventBus.subscribe('sellItem', ({ itemName }) => {
      if (this.items[itemName]) {
        this.items[itemName] -= 1;
      } else {
        console.log(`Inventory: No ${itemName} to sell.`);
      }
    });
  }

  getItems() {
    return this.items;
  }
}

