class CustomerSystem {
  constructor() {
    this.orders = [];
  }

  receiveNotification(orderId) {
    const order = this.orders.find(o => o.id === orderId);
    if (order) {
      console.log(`Customer received notification for order ${orderId}: Order is ready.`);
    } else {
      console.log(`Order ${orderId} not found in customer's records.`);
    }
  }

  placeOrder(orderSystem, items) {
