    this.orderSystem = new OrderSystem();
    this.kitchenSystem = new KitchenSystem();
    this.customerSystem = new CustomerSystem();

    // Wire systems together
    this.orderSystem.orders.forEach(order => {
      this.kitchenSystem.receiveOrder(order);
    });

    this.kitchenSystem.orders.forEach(order => {
      this.kitchenSystem.notifyOrderReady(order.id);
      this.customerSystem.receiveNotification(order.id);
    });
  }

  // Public API
  placeOrder(items) {
    const orderId = this.customerSystem.placeOrder(this.orderSystem, items);
    this.kitchenSystem.receiveOrder(this.orderSystem.orders.find(o => o.id === orderId));
    return orderId;
  }

  getOrderStatus(orderId) {
    return this.orderSystem.getOrderStatus(orderId);
  }
}

