}

class Crafting {
    constructor() {
        this.recipes = [];
    }

    addRecipe(recipe) {
        this.recipes.push(recipe);
    }

    canCraft(recipeName, inventory) {
        const recipe = this.recipes.find(r => r.getName() === recipeName);
        if (!recipe) return false;

        const ingredients = recipe.getIngredients();
        for (const [item, quantity] of Object.entries(ingredients)) {
            if (inventory.getItemQuantity(item) < quantity) {
                return false;
            }
        }
        return true;
    }

    craft(recipeName, inventory) {
        if (!this.canCraft(recipeName, inventory)) return false;

        const recipe = this.recipes.find(r => r.getName() === recipeName);
        const ingredients = recipe.getIngredients();
        for (const [item, quantity] of Object.entries(ingredients)) {
            inventory.removeItem(item, quantity);
        }

        inventory.addItem(recipe.getName(), 1);
        return true;
    }
}

class Inventory {
    constructor() {
        this.items = {}; // { item: quantity }
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
        }
    }

    getItemQuantity(item) {
        return this.items[item] || 0;
    }

    getInventory() {
        return { ...this.items };
    }
}

