        this.crafting.addRecipe(recipe);
    }

    craftItem(recipeName) {
        return this.crafting.craft(recipeName, this.inventory);
    }

    addItemToInventory(item, quantity) {
        this.inventory.addItem(item, quantity);
    }

    getInventory() {
        return this.inventory.getInventory();
    }
}

