class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { item: quantity }
  }

  hasIngredients(inventory) {
    for (let [item, quantity] of Object.entries(this.ingredients)) {
      if (inventory.count(item) < quantity) {
        return false;
      }
    }
    return true;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    this.items[item] = (this.items[item] || 0) + quantity;
  }

  removeItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
    } else {
      throw new Error(`Not enough ${item} in inventory.`);
    }
  }

  count(item) {
    return this.items[item] || 0;
  }
}

class Crafting {
  constructor(recipes, inventory) {
    this.recipes = recipes;
    this.inventory = inventory;
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) {
      throw new Error(`Recipe ${recipeName} not found.`);
    }
    return recipe.hasIngredients(this.inventory);
  }

  craft(recipeName) {
    if (!this.canCraft(recipeName)) {
      throw new Error(`Cannot craft ${recipeName}: missing ingredients.`);
    }
    const recipe = this.recipes.find(r => r.name === recipeName);
    for (let [item, quantity] of Object.entries(recipe.ingredients)) {
      this.inventory.removeItem(item, quantity);
    }
    console.log(`Crafted ${recipeName}`);
  }
}

