        this.items = items;
    }

    getRandomItem() {
        if (this.items.length === 0) {
            throw new Error("No items available.");
        }
        const randomIndex = Math.floor(Math.random() * this.items.length);
        return this.items[randomIndex];
    }
}

class RarityTable {
    constructor(rarityLevels) {
        this.rarityLevels = rarityLevels;
    }

    getRandomRarity() {
        const totalWeight = this.rarityLevels.reduce((acc, level) => acc + level.weight, 0);
        const randomWeight = Math.random() * totalWeight;
        let cumulativeWeight = 0;

        for (const level of this.rarityLevels) {
            cumulativeWeight += level.weight;
            if (randomWeight <= cumulativeWeight) {
                return level.name;
            }
        }

        throw new Error("Failed to determine rarity.");
    }
}

