class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, callback) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(callback);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(callback => callback(data));
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemAdded', this.onItemAdded.bind(this));
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
    this.eventBus.emit('inventoryUpdated', this.items);
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      this.eventBus.emit('inventoryUpdated', this.items);
    }
  }

  onItemAdded(data) {
    this.addItem(data.item, data.quantity);
  }

  getInventory() {
    return this.items;
  }
}

class Crafting {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('recipeAdded', this.onRecipeAdded.bind(this));
    this.eventBus.subscribe('craftItem', this.onCraftItem.bind(this));
  }

  addRecipe(recipeName, ingredients) {
    this.recipes[recipeName] = ingredients;
    this.eventBus.emit('recipeUpdated', this.recipes);
  }

  onRecipeAdded(data) {
    this.addRecipe(data.recipeName, data.ingredients);
  }

  onCraftItem(data) {
    const recipe = this.recipes[data.recipeName];
    if (recipe) {
      let canCraft = true;
      for (const [item, quantity] of Object.entries(recipe)) {
        if (!data.inventory[item] || data.inventory[item] < quantity) {
          canCraft = false;
          break;
        }
      }
      if (canCraft) {
        for (const [item, quantity] of Object.entries(recipe)) {
          data.inventory.removeItem(item, quantity);
        }
        data.inventory.addItem(data.recipeName, 1);
        console.log(`Crafted ${data.recipeName}`);
      } else {
        console.log(`Insufficient resources to craft ${data.recipeName}`);
      }
    } else {
      console.log(`Recipe ${data.recipeName} not found`);
    }
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('recipeAdded', this.onRecipeAdded.bind(this));
  }

  addRecipe(recipeName, ingredients) {
    this.recipes[recipeName] = ingredients;
    this.eventBus.emit('recipeAdded', { recipeName, ingredients });
  }

  onRecipeAdded(data) {
    this.recipes[data.recipeName] = data.ingredients;
  }
}

