class Loot {
  constructor(name, value) {
    this.name = name;
    this.value = value;
  }
}

class RarityTable {
  constructor() {
    this.table = {
      common: { min: 1, max: 10 },
      uncommon: { min: 11, max: 50 },
      rare: { min: 51, max: 100 },
    };
  }

  getRandomLoot() {
    const rarity = this.getRarity();
    const value = this.getValue(rarity);
    return new Loot(rarity, value);
  }

  getRarity() {
    const roll = Math.floor(Math.random() * 100) + 1;
    if (roll <= 50) return 'common';
    if (roll <= 80) return 'uncommon';
    return 'rare';
  }

  getValue(rarity) {
    const range = this.table[rarity];
    return Math.floor(Math.random() * (range.max - range.min + 1)) + range.min;
  }
}

class Economy {
