    const enemy = new HealthSystem('Enemy', 50);
    while (this.health.isAlive() && enemy.isAlive()) {
      this.combat.attack(this.health, enemy, 'Punch');
      if (enemy.isAlive()) {
        this.combat.attack(enemy, this.health, 'Kick');
      }
    }
    if (enemy.isAlive()) {
      this.loot.dropLoot(this.health);
    } else {
      this.loot.dropLoot(enemy);
    }
