class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.currentExperience = 0;
    this.experienceNeededForNextLevel = 100;
  }

  gainExperience(amount) {
    this.currentExperience += amount;
    console.log(`Gained ${amount} experience, total: ${this.currentExperience}`);
    if (this.currentExperience >= this.experienceNeededForNextLevel) {
      this.levelUp();
    }
  }

