    this.eventBus.emit('levelUp', this.getLevel());
    this.currentExperience -= this.experienceNeededForNextLevel;
    this.experienceNeededForNextLevel *= 1.2; // Increase experience needed for next level
  }

  getLevel() {
    return Math.floor(Math.log(this.experienceNeededForNextLevel / 100) / Math.log(1.2)) + 1;
  }
}

