        if (this.items[item]) {
            this.items[item] += amount;
        } else {
            this.items[item] = amount;
        }
    }

    removeItem(item, amount) {
        if (this.items[item] && this.items[item] >= amount) {
            this.items[item] -= amount;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    hasItems(ingredients) {
        for (const [item, amount] of Object.entries(ingredients)) {
            if (!this.items[item] || this.items[item] < amount) {
                return false;
            }
        }
        return true;
    }

    getItems() {
        return this.items;
    }
}

class Crafting {
    constructor(recipeBook) {
        this.recipeBook = recipeBook; // Array of Recipe instances
    }

    canCraft(recipeName) {
        const recipe = this.recipeBook.find(r => r.getName() === recipeName);
        if (recipe) {
            return recipe.getIngredients();
        }
        return null;
    }

    craft(recipeName, inventory) {
        const recipe = this.recipeBook.find(r => r.getName() === recipeName);
        if (recipe && inventory.hasItems(recipe.getIngredients())) {
            for (const [item, amount] of Object.entries(recipe.getIngredients())) {
                inventory.removeItem(item, amount);
            }
            console.log(`Crafted ${recipeName}`);
            return true;
        }
        console.log(`Cannot craft ${recipeName}`);
        return false;
    }
}

