class Loot {
  constructor(prices) {
    this.prices = prices; // Prices should be an object with rarity keys and price values
  }

  generateLoot(rarity) {
    const price = this.prices[rarity] || this.prices.common; // Fallback to common price if rarity is not found
    return { rarity, price };
  }
}

