class LevelUp {
  constructor(level = 1) {
    this.level = level;
  }

  checkLevelUp(currentXP, xpPerLevel) {
    if (currentXP >= xpPerLevel * this.level) {
      this.level++;
      return true;
    }
    return false;
  }

  getLevel() {
    return this.level;
  }
