class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemAdded', this.onItemAdded.bind(this));
    this.eventBus.subscribe('itemUsed', this.onItemUsed.bind(this));
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
    this.eventBus.emit('itemAdded', { item, quantity });
  }

  useItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      this.eventBus.emit('itemUsed', { item, quantity });
      return true;
    }
    return false;
  }

  onItemAdded({ item, quantity }) {
    console.log(`Added ${quantity} ${item} to inventory.`);
  }

  onItemUsed({ item, quantity }) {
    console.log(`Used ${quantity} ${item} from inventory.`);
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('craftRequested', this.onCraftRequested.bind(this));
  }

  addRecipe(name, ingredients) {
    this.recipes[name] = ingredients;
  }

  requestCraft(name) {
    this.eventBus.emit('craftRequested', name);
  }

  onCraftRequested(name) {
    if (this.recipes[name]) {
      const ingredients = this.recipes[name];
      this.eventBus.emit('craftPossible', { name, ingredients });
    } else {
      console.log(`Recipe ${name} not found.`);
    }
  }
}

class Crafting {
  constructor(eventBus, inventory) {
    this.eventBus = eventBus;
    this.inventory = inventory;
    this.eventBus.subscribe('craftPossible', this.onCraftPossible.bind(this));
  }

  onCraftPossible({ name, ingredients }) {
    if (this.canCraft(ingredients)) {
      this.craftItem(name, ingredients);
      console.log(`Crafted ${name}.`);
    } else {
      console.log(`Not enough ingredients to craft ${name}.`);
    }
  }

  canCraft(ingredients) {
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.inventory.useItem(item, quantity)) {
        return false;
      }
    }
    return true;
  }

  craftItem(name, ingredients) {
    for (const [item, quantity] of Object.entries(ingredients)) {
      this.inventory.addItem(item, quantity);
    }
  }
}

// Demo
