class RarityTable {
    constructor() {
        this.rarityWeights = {
            common: 0.6,
            uncommon: 0.3,
            rare: 0.08,
            epic: 0.01,
            legendary: 0.01
        };
    }

    generateRarity() {
        const rand = Math.random();
        let cumulativeWeight = 0;
        for (const [rarity, weight] of Object.entries(this.rarityWeights)) {
            cumulativeWeight += weight;
            if (rand <= cumulativeWeight) {
                return rarity;
            }
        }
        return "common"; // Fallback to common if something goes wrong
    }
}

