    this.prices = prices; // { item: price }
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }
}

class Demand {
  constructor(demand) {
    this.demand = demand; // { item: demandLevel }
  }

  getDemand(item) {
    return this.demand[item] || 0;
  }
}

class Economy {
  constructor(initialBalance) {
    this.balance = initialBalance;
  }

  debit(amount) {
    if (this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    this.items[item] = (this.items[item] || 0) + quantity;
  }

  getInventory() {
    return this.items;
  }
}

class Store {
  constructor(pricing, demand, economy, inventory) {
    this.pricing = pricing;
    this.demand = demand;
    this.economy = economy;
    this.inventory = inventory;
  }

  canPurchase(item, quantity = 1) {
    const price = this.pricing.getPrice(item);
    const demand = this.demand.getDemand(item);
    const totalCost = price * quantity;

    return this.economy.getBalance() >= totalCost && demand >= quantity;
  }

  purchase(item, quantity = 1) {
    if (this.canPurchase(item, quantity)) {
      const price = this.pricing.getPrice(item);
      const totalCost = price * quantity;
      this.economy.debit(totalCost);
      this.inventory.addItem(item, quantity);
      console.log(`Purchased ${quantity} ${item}(s) for ${totalCost}.`);
      return true;
    } else {
      console.log(`Purchase of ${quantity} ${item}(s) failed.`);
      return false;
    }
  }
}

