class Recipe {
  constructor(item, ingredients) {
    this.item = item;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }

  canCraft(inventory) {
    for (const [ingredient, quantity] of Object.entries(this.ingredients)) {
      if (inventory.getItemCount(ingredient) < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(inventory) {
    if (this.canCraft(inventory)) {
      for (const [ingredient, quantity] of Object.entries(this.ingredients)) {
        inventory.removeItem(ingredient, quantity);
      }
      inventory.addItem(this.item, 1);
      return true;
    }
    return false;
  }
