class Crafting {
  constructor(recipes) {
    this.recipes = recipes; // Array of Recipe instances
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe) return false;

    for (const [ingredient, quantity] of Object.entries(recipe.getIngredients())) {
      if (inventory.hasItem(ingredient, quantity)) continue;
      return false;
    }
    return true;
  }

  craft(recipeName, inventory) {
    if (!this.canCraft(recipeName, inventory)) return false;

    const recipe = this.recipes.find(r => r.getName() === recipeName);
    for (const [ingredient, quantity] of Object.entries(recipe.getIngredients())) {
      inventory.removeItem(ingredient, quantity);
    }
    inventory.addItem(recipeName, 1);
    return true;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { itemName: quantity }
  }

  hasItem(itemName, quantity = 1) {
    return (this.items[itemName] || 0) >= quantity;
  }

  addItem(itemName, quantity = 1) {
    this.items[itemName] = (this.items[itemName] || 0) + quantity;
  }

  removeItem(itemName, quantity = 1) {
    if (this.hasItem(itemName, quantity)) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) delete this.items[itemName];
    }
  }

  getItems() {
    return this.items;
  }
}

