class Recipe {
  constructor(id, ingredients, result) {
    this.id = id;
    this.ingredients = ingredients; // { item: quantity }
    this.result = result; // { item: quantity }
  }

  getId() {
    return this.id;
  }

  getIngredients() {
    return this.ingredients;
  }

  getResult() {
    return this.result;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { item: quantity }
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }

  hasIngredients(recipe) {
    const ingredients = recipe.getIngredients();
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (this.getItemCount(item) < quantity) {
        return false;
      }
    }
    return true;
  }

  consumeIngredients(recipe) {
    const ingredients = recipe.getIngredients();
    for (const [item, quantity] of Object.entries(ingredients)) {
      this.removeItem(item, quantity);
    }
  }

  addItemResult(recipe) {
    const result = recipe.getResult();
    for (const [item, quantity] of Object.entries(result)) {
      this.addItem(item, quantity);
    }
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = new Map(); // { recipeId: Recipe }
    recipes.forEach(recipe => this.recipes.set(recipe.getId(), recipe));
  }

  addRecipe(recipe) {
    this.recipes.set(recipe.getId(), recipe);
  }

  craft(recipeId) {
    const recipe = this.recipes.get(recipeId);
    if (recipe && this.inventory.hasIngredients(recipe)) {
      this.inventory.consumeIngredients(recipe);
      this.inventory.addItemResult(recipe);
      return true;
    }
    return false;
  }

  canCraft(recipeId) {
    const recipe = this.recipes.get(recipeId);
    return recipe ? this.inventory.hasIngredients(recipe) : false;
  }
}

