    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

// Market System
class Market {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getMarketPrice(item) {
    return this.prices[item] || null;
  }

  setMarketPrice(item, price) {
    if (price >= 0) {
      this.prices[item] = price;
      return true;
    }
    return false;
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (quantity > 0 && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

// Top-level Coordinator
class GameCoordinator {
  constructor(initialBalance = 0, initialPrices = {}) {
    this.bank = new Bank(initialBalance);
    this.market = new Market(initialPrices);
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    const price = this.market.getMarketPrice(item);
    const totalCost = price * quantity;

    if (price !== null && this.bank.withdraw(totalCost)) {
      this.inventory.addItem(item, quantity);
      return true;
    }
    return false;
  }

  sellItem(item, quantity) {
    const price = this.market.getMarketPrice(item);
    const totalRevenue = price * quantity;

    if (price !== null && this.inventory.removeItem(item, quantity)) {
      this.bank.deposit(totalRevenue);
      return true;
    }
    return false;
  }

  checkBalance() {
    return this.bank.getBalance();
  }

  checkInventory() {
    return this.inventory.getInventory();
  }

  checkMarketPrices() {
    return this.market.prices;
  }
