class Economy {
    constructor(startingBalance = 0) {
        this.balance = startingBalance;
    }

    getBalance() {
        return this.balance;
    }

    addFunds(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    subtractFunds(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }
}

class Store {
    constructor() {
        this.items = {
            apple: { price: 1, stock: 10 },
            bread: { price: 2, stock: 5 },
            milk: { price: 3, stock: 8 }
        };
    }

    getItemPrice(item) {
        return this.items[item]?.price || 0;
    }

    checkStock(item) {
        return this.items[item]?.stock || 0;
    }

    purchaseItem(item, quantity, onSuccess, onFailure) {
        const itemInfo = this.items[item];
        if (itemInfo && itemInfo.stock >= quantity) {
            this.items[item].stock -= quantity;
            onSuccess(item, quantity);
        } else {
            onFailure(item, quantity);
        }
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }
}

class GameCoordinator {
    constructor() {
        this.economy = new Economy(10);
        this.store = new Store();
        this.inventory = new Inventory();
    }

    buyItem(item, quantity) {
        const price = this.store.getItemPrice(item);
        const stock = this.store.checkStock(item);

        if (quantity > stock) {
            console.log(`Store out of stock for ${item}`);
            return;
        }

        const totalCost = price * quantity;
        if (!this.economy.subtractFunds(totalCost)) {
            console.log(`Insufficient funds to buy ${quantity} ${item}`);
            return;
        }

        this.store.purchaseItem(item, quantity, (item, quantity) => {
            this.inventory.addItem(item, quantity);
            console.log(`Bought ${quantity} ${item}. Total cost: ${totalCost}. Remaining balance: ${this.economy.getBalance()}`);
        }, (item, quantity) => {
            console.log(`Failed to purchase ${quantity} ${item}`);
        });
    }
}

