class Wallet {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    getBalance() {
        return this.balance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && this.balance >= amount) {
            this.balance -= amount;
            return true;
        }
        return false;
    }
}

class Shop {
    constructor(wallet, items) {
        this.wallet = wallet;
        this.items = items;
    }

    listItems() {
        return Object.keys(this.items);
    }

    buyItem(itemName) {
        if (this.items[itemName] && this.wallet.withdraw(this.items[itemName])) {
            return true;
        }
        return false;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(itemName, quantity = 1) {
        if (quantity > 0) {
            this.items[itemName] = (this.items[itemName] || 0) + quantity;
            return true;
        }
        return false;
    }

    removeItem(itemName, quantity = 1) {
        if (this.items[itemName] && this.items[itemName] >= quantity) {
            this.items[itemName] -= quantity;
            if (this.items[itemName] === 0) {
                delete this.items[itemName];
            }
            return true;
        }
        return false;
    }

    getInventory() {
        return { ...this.items };
    }
}

