class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients; // { item: quantity }
    this.result = result; // { item: quantity }
  }

  hasIngredients(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      if (inventory.getItemQuantity(item) < quantity) {
        return false;
      }
    }
    return true;
  }

  consumeIngredients(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      inventory.removeItem(item, quantity);
    }
  }

  getResult() {
    return this.result;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { item: quantity }
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
    }
  }

  getItemQuantity(item) {
    return this.items[item] || 0;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Crafting {
  constructor() {
    this.recipes = [];
    this.inventory = new Inventory();
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  setInventory(inventory) {
    this.inventory = inventory;
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe && recipe.hasIngredients(this.inventory)) {
      recipe.consumeIngredients(this.inventory);
      const result = recipe.getResult();
      for (const [item, quantity] of Object.entries(result)) {
        this.inventory.addItem(item, quantity);
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return this.inventory.getInventory();
  }
}

