// Crafting System
class Crafting {
    constructor() {
        this.recipes = {};
    }

    addRecipe(recipe) {
        this.recipes[recipe.name] = recipe;
    }

    canCraft(recipeName, inventory) {
        const recipe = this.recipes[recipeName];
        if (!recipe) return false;
        for (const [item, amount] of Object.entries(recipe.ingredients)) {
            if (inventory.getItemCount(item) < amount) return false;
        }
        return true;
    }

    craft(recipeName, inventory) {
        if (!this.canCraft(recipeName, inventory)) return null;
        const recipe = this.recipes[recipeName];
        for (const [item, amount] of Object.entries(recipe.ingredients)) {
            inventory.removeItem(item, amount);
        }
        inventory.addItem(recipe.output, 1);
        return recipe.output;
    }
}

// Recipe System
class Recipe {
    constructor(name, ingredients, output) {
        this.name = name;
        this.ingredients = ingredients;
        this.output = output;
    }
}

// Inventory System
class Inventory {
    constructor() {
        this.items = {};
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }

    addItem(item, amount) {
        this.items[item] = (this.items[item] || 0) + amount;
    }

    removeItem(item, amount) {
        if (this.items[item]) {
            this.items[item] -= amount;
            if (this.items[item] < 0) this.items[item] = 0;
        }
    }
}

// Top-level Coordinator
class GameCoordinator {
    constructor() {
        this.crafting = new Crafting();
        this.inventory = new Inventory();
    }

    addRecipe(recipe) {
        this.crafting.addRecipe(recipe);
    }

    craftItem(recipeName) {
        const result = this.crafting.craft(recipeName, this.inventory);
        if (result) {
            console.log(`Crafted: ${result}`);
        } else {
            console.log(`Cannot craft: ${recipeName}`);
        }
    }

    addItemToInventory(item, amount) {
        this.inventory.addItem(item, amount);
        console.log(`Added ${amount} ${item} to inventory.`);
    }

    displayInventory() {
        console.log('Inventory:');
        for (const [item, amount] of Object.entries(this.inventory.items)) {
            console.log(`${item}: ${amount}`);
        }
    }
}

