class Economy {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    getBalance() {
        return this.balance;
    }

    addFunds(amount) {
        this.balance += amount;
    }

    subtractFunds(amount) {
        if (amount > this.balance) {
            throw new Error("Insufficient funds");
        }
        this.balance -= amount;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity = 1) {
        if (!this.items[item] || this.items[item] < quantity) {
            throw new Error("Insufficient item quantity");
        }
        this.items[item] -= quantity;
        if (this.items[item] === 0) {
            delete this.items[item];
        }
    }

    getInventory() {
        return { ...this.items };
    }
}

class Store {
    constructor(economy, inventory, itemPrices) {
        this.economy = economy;
        this.inventory = inventory;
        this.itemPrices = itemPrices;
    }

    buyItem(item, quantity = 1) {
        const price = this.itemPrices[item];
        if (!price) {
            throw new Error("Item not available");
        }
        const totalCost = price * quantity;
        this.economy.subtractFunds(totalCost);
        this.inventory.addItem(item, quantity);
        console.log(`Bought ${quantity} ${item}(s) for ${totalCost}`);
    }

    sellItem(item, quantity = 1) {
        if (!this.inventory.items[item]) {
            throw new Error("Item not in inventory");
        }
        const price = this.itemPrices[item];
        const totalEarnings = price * quantity;
        this.economy.addFunds(totalEarnings);
        this.inventory.removeItem(item, quantity);
        console.log(`Sold ${quantity} ${item}(s) for ${totalEarnings}`);
    }

    checkInventory() {
        return this.inventory.getInventory();
    }
}

