class RarityTable {
    constructor() {
        this.rarityMap = {
            'Common': 0.6,
            'Uncommon': 0.3,
            'Rare': 0.09,
            'Epic': 0.01
        };
    }

    getRandomLoot() {
        const rarityOptions = Object.keys(this.rarityMap);
        let rand = Math.random();
        for (const rarity of rarityOptions) {
            rand -= this.rarityMap[rarity];
            if (rand <= 0) {
                return new Loot(`${rarity} Loot`, rarity, this._getValueForRarity(rarity));
            }
        }
        return null;
    }

    _getValueForRarity(rarity) {
        switch (rarity) {
            case 'Common': return Math.floor(Math.random() * 10) + 1;
            case 'Uncommon': return Math.floor(Math.random() * 50) + 10;
            case 'Rare': return Math.floor(Math.random() * 100) + 50;
            case 'Epic': return Math.floor(Math.random() * 500) + 100;
            default: return 0;
        }
    }
}

