class Loot {
  constructor(name, value) {
    this.name = name;
    this.value = value;
  }
}

class RarityTable {
  constructor() {
    this.rarityLevels = {
      common: 0.7,
      uncommon: 0.2,
      rare: 0.05,
      epic: 0.03,
      legendary: 0.02
    };
  }

  getRandomLoot() {
    const rand = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.rarityLevels)) {
      cumulativeProbability += probability;
      if (rand < cumulativeProbability) {
        return new Loot(rarity, this.calculateValue(rarity));
      }
    }

    return new Loot('common', this.calculateValue('common'));
  }

  calculateValue(rarity) {
    switch (rarity) {
      case 'common': return Math.floor(Math.random() * 10) + 1;
      case 'uncommon': return Math.floor(Math.random() * 50) + 10;
      case 'rare': return Math.floor(Math.random() * 100) + 50;
      case 'epic': return Math.floor(Math.random() * 200) + 100;
      case 'legendary': return Math.floor(Math.random() * 500) + 200;
      default: return 1;
    }
  }
}

