class CraftingSystem {
    constructor(inventory, recipe) {
        this.inventory = inventory;
        this.recipe = recipe;
    }

    canCraft(item) {
        const recipe = this.recipe.getRecipe(item);
        if (!recipe) return false;
        return Object.keys(recipe.ingredients).every(ingredient => {
            return this.inventory.hasItem(ingredient, recipe.ingredients[ingredient]);
        });
    }

    craft(item) {
        if (this.canCraft(item)) {
            const recipe = this.recipe.getRecipe(item);
            Object.keys(recipe.ingredients).forEach(ingredient => {
                this.inventory.removeItem(ingredient, recipe.ingredients[ingredient]);
            });
            this.inventory.addItem(item, 1);
            return true;
        }
        return false;
    }
}

class RecipeSystem {
    constructor() {
        this.recipes = {};
    }

    addRecipe(item, ingredients) {
        this.recipes[item] = { ingredients };
    }

    getRecipe(item) {
        return this.recipes[item];
    }
}

class InventorySystem {
    constructor() {
        this.items = {};
    }

    hasItem(item, amount = 1) {
        return (this.items[item] || 0) >= amount;
    }

    addItem(item, amount) {
        this.items[item] = (this.items[item] || 0) + amount;
    }

    removeItem(item, amount) {
        if (this.hasItem(item, amount)) {
            this.items[item] -= amount;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
        }
    }

    getItems() {
        return { ...this.items };
    }
}

