class Spawner {
    constructor(enemyPool) {
        this.enemyPool = enemyPool;
    }

    spawnEnemy() {
        const enemy = this.enemyPool.acquireEnemy();
        if (enemy) {
            console.log(`Enemy spawned: ${enemy.id}`);
        } else {
            console.log("No available enemies in the pool.");
        }
    }
