class EnemyPool {
    constructor(poolSize) {
        this.pool = Array.from({ length: poolSize }, (_, i) => ({ id: i + 1, active: false }));
    }

    acquireEnemy() {
        for (let enemy of this.pool) {
            if (!enemy.active) {
                enemy.active = true;
                return enemy;
            }
        }
        return null;
    }

    releaseEnemy(enemy) {
        enemy.active = false;
        console.log(`Enemy released: ${enemy.id}`);
    }
}

class Score {
