        this.score -= points;
        console.log(`Points subtracted: ${points}, Total score: ${this.score}`);
    }
}

class Coordinator {
    constructor() {
        this.enemyPool = new EnemyPool(3);
        this.spawner = new Spawner(this.enemyPool);
        this.score = new Score();
    }

    startGame() {
        this.spawner.spawnEnemy();
        this.spawner.spawnEnemy();
        this.spawner.spawnEnemy();
        this.spawner.spawnEnemy(); // This should fail
    }

    enemyDefeated(enemy) {
        this.enemyPool.releaseEnemy(enemy);
        this.score.addPoints(100);
    }

    enemyEscaped(enemy) {
        this.enemyPool.releaseEnemy(enemy);
        this.score.subtractPoints(50);
    }
}

