class Recipe {
  constructor(id, ingredients, result) {
    this.id = id;
    this.ingredients = ingredients;
    this.result = result;
  }
}

class Crafting {
  constructor(recipes) {
    this.recipes = new Map(recipes.map(recipe => [recipe.id, recipe]));
  }

  canCraft(recipeId, inventory) {
    const recipe = this.recipes.get(recipeId);
    if (!recipe) return false;

    for (const [item, quantity] of recipe.ingredients) {
      if (inventory.get(item) < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(recipeId, inventory) {
    const recipe = this.recipes.get(recipeId);
    if (!this.canCraft(recipeId, inventory)) {
      throw new Error('Cannot craft the item with the current inventory');
    }

    for (const [item, quantity] of recipe.ingredients) {
      inventory.set(item, inventory.get(item) - quantity);
    }

    inventory.set(recipe.result, (inventory.get(recipe.result) || 0) + 1);
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  get(item) {
    return this.items.get(item) || 0;
  }

  set(item, quantity) {
    this.items.set(item, quantity);
  }

  add(item, quantity) {
    this.set(item, this.get(item) + quantity);
  }
}

class Economy {
  constructor(prices) {
    this.prices = new Map(prices);
  }

  getPrice(item) {
    return this.prices.get(item) || 0;
  }

  debit(item, quantity) {
    const price = this.getPrice(item);
    const totalCost = price * quantity;
    console.log(`Debited ${totalCost} for ${quantity} ${item}(s)`);
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchase(item, quantity) {
    const price = this.economy.getPrice(item);
    const totalCost = price * quantity;

    if (totalCost > 0) {
      this.economy.debit(item, quantity);
      this.inventory.add(item, quantity);
    }
  }
}

