class TradeSystem {
  constructor() {
    this.balance = 0;
  }

  // Public API
  buy(price) {
    if (this.balance >= price) {
      this.balance -= price;
      return true;
    }
    return false;
  }

  sell(price) {
    this.balance += price;
    return true;
  }

  getBalance() {
    return this.balance;
  }
}

class ReputationSystem {
  constructor() {
    this.reputation = 0;
  }

  // Public API
  gainReputation(amount) {
    this.reputation += amount;
  }

  loseReputation(amount) {
    this.reputation -= amount;
  }

  getReputation() {
    return this.reputation;
  }
}

class FactionSystem {
  constructor() {
    this.factions = {
      traders: 0,
      lawEnforcement: 0,
      criminals: 0
    };
  }

  // Public API
  joinFaction(faction, reputationCost) {
    if (this.factions[faction] === 0) {
      this.factions[faction] = reputationCost;
      return true;
    }
    return false;
  }

  leaveFaction(faction) {
    this.factions[faction] = 0;
  }

  getFactions() {
    return this.factions;
  }
}

class Coordinator {
  constructor() {
    this.tradeSystem = new TradeSystem();
    this.reputationSystem = new ReputationSystem();
    this.factionSystem = new FactionSystem();
  }

  // Public API
  trade(price) {
    if (this.tradeSystem.buy(price)) {
      this.reputationSystem.gainReputation(1);
      console.log(`Trade successful. New balance: ${this.tradeSystem.getBalance()}. Reputation: ${this.reputationSystem.getReputation()}`);
    } else {
      console.log('Trade failed. Insufficient funds.');
    }
  }

  joinFaction(faction, reputationCost) {
    if (this.reputationSystem.getReputation() >= reputationCost) {
      if (this.factionSystem.joinFaction(faction, reputationCost)) {
        this.reputationSystem.loseReputation(reputationCost);
        console.log(`Joined ${faction}. Reputation: ${this.reputationSystem.getReputation()}. Factions:`, this.factionSystem.getFactions());
      } else {
        console.log(`Already in faction ${faction}.`);
      }
    } else {
      console.log('Insufficient reputation to join faction.');
    }
  }

  leaveFaction(faction) {
    this.factionSystem.leaveFaction(faction);
    console.log(`Left ${faction}. Factions:`, this.factionSystem.getFactions());
  }
}

