  }

  placeOrder(items) {
    const orderId = Date.now();
    this.orders.push({ id: orderId, items, status: 'received' });
    console.log(`Order ${orderId} placed with items: ${items.join(', ')}`);
    return orderId;
  }

  updateOrderStatus(orderId, status) {
    const order = this.orders.find(o => o.id === orderId);
    if (order) {
      order.status = status;
      console.log(`Order ${orderId} status updated to ${status}`);
    } else {
      console.log(`Order ${orderId} not found`);
    }
  }

  getOrderStatus(orderId) {
    const order = this.orders.find(o => o.id === orderId);
    return order ? order.status : 'not found';
  }
}

class KitchenSystem {
  constructor(orderSystem) {
    this.orderSystem = orderSystem;
  }

  prepareOrder(orderId) {
    const status = this.orderSystem.getOrderStatus(orderId);
    if (status === 'received') {
      console.log(`Preparing order ${orderId}`);
      setTimeout(() => {
        this.orderSystem.updateOrderStatus(orderId, 'prepared');
        this.notifyCustomer(orderId);
      }, 2000); // Simulate preparation time
    } else {
      console.log(`Order ${orderId} cannot be prepared, status: ${status}`);
    }
  }

  notifyCustomer(orderId) {
