class EventBus {
  constructor() {
    this.events = {};
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(listener => listener(data));
    }
  }

  subscribe(eventName, listener) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(listener);
  }
}

class Recipe {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = {
      woodPickaxe: { ingredients: { wood: 5 } },
      stonePickaxe: { ingredients: { wood: 3, stone: 2 } }
    };

    this.eventBus.subscribe('craft', this.handleCraftRequest.bind(this));
  }

  handleCraftRequest(request) {
    const { item, inventory } = request;
    const recipe = this.recipes[item];

    if (recipe && this.canCraft(recipe.ingredients, inventory)) {
      this.consumeIngredients(recipe.ingredients, inventory);
      this.eventBus.emit('craftSuccess', { item, inventory });
      console.log(`Crafted ${item}`);
    } else {
      this.eventBus.emit('craftFailure', { item, inventory });
      console.log(`Failed to craft ${item}`);
    }
  }

  canCraft(ingredients, inventory) {
    for (const [resource, amount] of Object.entries(ingredients)) {
      if (inventory[resource] < amount) {
        return false;
      }
    }
    return true;
  }

  consumeIngredients(ingredients, inventory) {
    for (const [resource, amount] of Object.entries(ingredients)) {
      inventory[resource] -= amount;
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = { wood: 10, stone: 5 };

    this.eventBus.subscribe('craftSuccess', this.onCraftSuccess.bind(this));
    this.eventBus.subscribe('craftFailure', this.onCraftFailure.bind(this));
  }

  craft(item) {
    this.eventBus.emit('craft', { item, inventory: this.items });
  }

  onCraftSuccess({ item, inventory }) {
    console.log(`Inventory after crafting ${item}:`, inventory);
  }

  onCraftFailure({ item, inventory }) {
    console.log(`Inventory after failed craft attempt of ${item}:`, inventory);
  }
}

class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipe = new Recipe(eventBus);
    this.inventory = new Inventory(eventBus);
  }

  start() {
    this.inventory.craft('woodPickaxe');
    this.inventory.craft('stonePickaxe');
    this.inventory.craft('ironPickaxe'); // Non-existent recipe
  }
}

