class Pricing {
    constructor(basePrice, priceIncrease) {
        this.basePrice = basePrice;
        this.priceIncrease = priceIncrease;
    }

    calculatePrice(quantity) {
        return this.basePrice + (quantity * this.priceIncrease);
    }
}

class Demand {
    constructor(baseDemand, demandDecrease) {
        this.baseDemand = baseDemand;
        this.demandDecrease = demandDecrease;
    }

    calculateDemand(price) {
        return Math.max(0, this.baseDemand - (price * this.demandDecrease));
    }
}

class Store {
    constructor(pricing, demand) {
        this.pricing = pricing;
        this.demand = demand;
    }

    sell(quantity) {
        const price = this.pricing.calculatePrice(quantity);
        const demand = this.demand.calculateDemand(price);
        const actualQuantitySold = Math.min(quantity, demand);
        return { price, actualQuantitySold };
    }
}

// Demo
