  constructor() {
    this.inventory = [];
  }

  buyCrop(crop) {
    this.inventory.push(crop);
    console.log(`Bought ${crop.name} for ${crop.price}`);
  }

  sellCrop(crop) {
    const index = this.inventory.findIndex(c => c === crop);
    if (index === -1) {
      console.log(`${crop.name} is not in inventory.`);
      return 0;
