class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  hasItem(item, quantity = 1) {
    return this.items[item] && this.items[item] >= quantity;
  }

  getItems() {
    return { ...this.items };
  }
}

class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { item: quantity }
  }

  canCraft(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      if (!inventory.hasItem(item, quantity)) {
        return false;
      }
    }
    return true;
  }

  craft(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      inventory.removeItem(item, quantity);
    }
    return true;
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes; // { name: Recipe }
  }

  addRecipe(recipe) {
    this.recipes[recipe.name] = recipe;
  }

  craftRecipe(recipeName) {
    const recipe = this.recipes[recipeName];
    if (recipe && recipe.canCraft(this.inventory)) {
      recipe.craft(this.inventory);
      return true;
    }
    return false;
  }

  getRecipes() {
    return Object.keys(this.recipes);
  }
}

