class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  calculatePrice(unitsSold) {
    return this.basePrice * (1 + 0.1 * unitsSold);
  }
}

class Demand {
  constructor(initialDemand, decreaseRate) {
    this.currentDemand = initialDemand;
    this.decreaseRate = decreaseRate;
  }

  updateDemand(unitsSold) {
    this.currentDemand -= unitsSold * this.decreaseRate;
    if (this.currentDemand < 0) this.currentDemand = 0;
  }

  getCurrentDemand() {
    return this.currentDemand;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.unitsSold = 0;
  }

  sellUnits(unitsToSell) {
    const availableUnits = this.demand.getCurrentDemand();
    const unitsSold = Math.min(unitsToSell, availableUnits);
    this.unitsSold += unitsSold;
    this.demand.updateDemand(unitsSold);
    const price = this.pricing.calculatePrice(this.unitsSold);
    return { unitsSold, price };
  }

  getInventoryStatus() {
    return `Units Sold: ${this.unitsSold}, Remaining Demand: ${this.demand.getCurrentDemand()}`;
  }
}

