class Resource {
  constructor() {
    this.resources = { wood: 100, stone: 100, gold: 100 };
  }

  checkResources(cost) {
    for (const [resource, amount] of Object.entries(cost)) {
      if (this.resources[resource] < amount) {
        return false;
      }
    }
    return true;
  }

  consumeResources(cost) {
    for (const [resource, amount] of Object.entries(cost)) {
      this.resources[resource] -= amount;
    }
  }

  getResources() {
    return { ...this.resources };
  }
}

class Economy {
  constructor(resourceSystem, buildingSystem) {
    this.resourceSystem = resourceSystem;
    this.buildingSystem = buildingSystem;
  }

  buildBuilding(name, type, cost) {
    if (this.resourceSystem.checkResources(cost)) {
      this.resourceSystem.consumeResources(cost);
      this.buildingSystem.build(name, type, cost);
      return true;
    }
    return false;
  }

  getEconomyStatus() {
    return {
      resources: this.resourceSystem.getResources(),
      buildings: this.buildingSystem.buildings
    };
  }
}

