    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}, new balance is ${this.balance}`);
      this.eventBus.emit('balanceUpdated', { balance: this.balance });
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}, new balance is ${this.balance}`);
      this.eventBus.emit('balanceUpdated', { balance: this.balance });
    }
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.prices = { item1: 10, item2: 20 };
    this.eventBus.subscribe('buy', this.buy.bind(this));
  }

  buy(item, quantity) {
    if (this.prices[item] !== undefined && quantity > 0) {
      const totalCost = this.prices[item] * quantity;
      console.log(`Attempting to buy ${quantity} of ${item} for ${totalCost}`);
      this.eventBus.emit('withdraw', { amount: totalCost });
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = { item1: 0, item2: 0 };
    this.eventBus.subscribe('balanceUpdated', this.checkPurchase.bind(this));
    this.eventBus.subscribe('sell', this.sell.bind(this));
  }

  checkPurchase({ balance }) {
    if (balance >= 0) {
      console.log('Balance is sufficient for purchase.');
    } else {
      console.log('Insufficient balance for purchase.');
    }
  }

  sell(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      console.log(`Sold ${quantity} of ${item}, remaining stock is ${this.items[item]}`);
    }
  }
}

// Demo
const eventBus = new EventBus();
const bank = new Bank(eventBus);
const market = new Market(eventBus);
const inventory = new Inventory(eventBus);

// Deposit money
bank.deposit(100);

// Buy items
market.buy('item1', 2);
market.buy('item2', 1);

// Sell items
inventory.sell('item1', 1);
