class Quest {
  constructor() {
    this.activeQuests = [];
  }

  startQuest(questName) {
    this.activeQuests.push(questName);
    console.log(`Started quest: ${questName}`);
  }

  completeQuest(questName) {
    const index = this.activeQuests.indexOf(questName);
    if (index !== -1) {
      this.activeQuests.splice(index, 1);
      console.log(`Completed quest: ${questName}`);
      return true;
    }
    console.log(`Quest not found: ${questName}`);
    return false;
  }

  getActiveQuests() {
    return [...this.activeQuests];
  }
}

class Reward {
  constructor() {
    this.rewards = {};
  }

  addReward(questName, reward) {
    this.rewards[questName] = reward;
    console.log(`Added reward for quest ${questName}: ${reward}`);
  }

  getReward(questName) {
    if (this.rewards[questName]) {
      console.log(`Reward for quest ${questName}: ${this.rewards[questName]}`);
      return this.rewards[questName];
    }
    console.log(`No reward for quest ${questName}`);
    return null;
  }
}

