// Event Bus Implementation
class EventBus {
    constructor() {
        this.events = {};
    }

    emit(eventName, data) {
        if (this.events[eventName]) {
            this.events[eventName].forEach(handler => handler(data));
        }
    }

    subscribe(eventName, handler) {
        if (!this.events[eventName]) {
            this.events[eventName] = [];
        }
        this.events[eventName].push(handler);
    }
}

// Dialogue System
class Dialogue {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('questCompleted', this.handleQuestCompleted.bind(this));
    }

    startDialogue(character) {
        console.log(`Starting dialogue with ${character}`);
        // Example dialogue logic
        this.eventBus.emit('dialogueFinished', { character, outcome: 'neutral' });
    }

    handleQuestCompleted(data) {
        console.log(`Quest completed for ${data.character}. Updating dialogue...`);
        this.eventBus.emit('dialogueFinished', { character: data.character, outcome: 'positive' });
    }
}

// Flags System
class Flags {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('dialogueFinished', this.handleDialogueFinished.bind(this));
        this.flags = {};
    }

    setFlag(flag, value) {
        this.flags[flag] = value;
        console.log(`Flag ${flag} set to ${value}`);
    }

    getFlag(flag) {
        return this.flags[flag];
    }

    handleDialogueFinished(data) {
        if (data.outcome === 'positive') {
            this.setFlag(`${data.character}_questSuccess`, true);
        } else {
            this.setFlag(`${data.character}_questSuccess`, false);
        }
    }
}

// Quest System
class Quest {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('flagsUpdated', this.handleFlagsUpdated.bind(this));
        this.activeQuests = {};
    }

    startQuest(character) {
        this.activeQuests[character] = 'active';
        console.log(`Quest started for ${character}`);
        this.eventBus.emit('questStarted', { character });
    }

    completeQuest(character) {
        if (this.activeQuests[character] === 'active') {
            this.activeQuests[character] = 'completed';
            console.log(`Quest completed for ${character}`);
            this.eventBus.emit('questCompleted', { character });
        }
    }

    handleFlagsUpdated(data) {
        console.log(`Flags updated: ${JSON.stringify(data)}`);
    }
