class Order {
    constructor() {
        this.orders = [];
    }

    takeOrder(customer, items) {
        const orderId = this.orders.length + 1;
        this.orders.push({ orderId, customer, items, status: 'pending' });
        console.log(`Order ${orderId} taken for ${customer}:`, items);
        return orderId;
    }

    getOrderStatus(orderId) {
        const order = this.orders.find(o => o.orderId === orderId);
        if (order) {
            return order.status;
        }
        console.log(`Order ${orderId} not found.`);
        return null;
    }

    updateOrderStatus(orderId, status) {
        const order = this.orders.find(o => o.orderId === orderId);
        if (order) {
            order.status = status;
            console.log(`Order ${orderId} status updated to ${status}.`);
        } else {
            console.log(`Order ${orderId} not found.`);
        }
    }
}

class Kitchen {
    constructor(orderSystem) {
        this.orderSystem = orderSystem;
    }

    prepareOrder(orderId) {
        const status = this.orderSystem.getOrderStatus(orderId);
        if (status === 'pending') {
            this.orderSystem.updateOrderStatus(orderId, 'cooking');
            console.log(`Preparing order ${orderId}...`);
            setTimeout(() => {
                this.orderSystem.updateOrderStatus(orderId, 'ready');
                console.log(`Order ${orderId} is ready.`);
            }, 3000); // Simulate cooking time
        } else {
            console.log(`Order ${orderId} is not pending.`);
        }
    }

    checkOrderStatus(orderId) {
        return this.orderSystem.getOrderStatus(orderId);
    }
}

class Customer {
    constructor(orderSystem, kitchenSystem) {
        this.orderSystem = orderSystem;
        this.kitchenSystem = kitchenSystem;
    }

    placeOrder(items) {
        const orderId = this.orderSystem.takeOrder('Customer', items);
        this.kitchenSystem.prepareOrder(orderId);
        return orderId;
    }

    checkOrder(orderId) {
        return this.kitchenSystem.checkOrderStatus(orderId);
    }
}

// Demo
