const kitchenSystem = new Kitchen(orderSystem);
const customer = new Customer(orderSystem, kitchenSystem);

const orderId = customer.placeOrder(['burger', 'fries']);
setTimeout(() => {
    console.log(`Customer checks order ${orderId}:`, customer.checkOrder(orderId));
}, 4000); // Check status after order is ready
