class Hunger {
  constructor() {
    this.level = 100;
  }

  eat(amount) {
    this.level = Math.min(100, this.level + amount);
    console.log(`Ate ${amount}. Hunger level is now ${this.level}.`);
  }

  consume(amount) {
    this.level = Math.max(0, this.level - amount);
    console.log(`Consumed ${amount}. Hunger level is now ${this.level}.`);
  }

  getLevel() {
    return this.level;
  }
}

class Energy {
  constructor() {
    this.level = 100;
  }

  rest(amount) {
    this.level = Math.min(100, this.level + amount);
    console.log(`Rested ${amount}. Energy level is now ${this.level}.`);
  }

  expend(amount) {
    this.level = Math.max(0, this.level - amount);
    console.log(`Expend ${amount}. Energy level is now ${this.level}.`);
  }

  getLevel() {
    return this.level;
  }
}

class Clock {
  constructor() {
    this.time = 0;
  }

  tick() {
    this.time++;
    console.log(`Time is now ${this.time}.`);
    return this.time;
  }

  getTime() {
    return this.time;
  }
}

class GameCoordinator {
  constructor() {
    this.hunger = new Hunger();
    this.energy = new Energy();
    this.clock = new Clock();
  }

  simulateDay() {
    console.log("Simulating a day...");

    // Morning
    this.clock.tick();
    this.hunger.consume(20);
    this.energy.expend(10);

    // Midday
    this.clock.tick();
    this.hunger.eat(30);
    this.energy.rest(5);

    // Evening
    this.clock.tick();
    this.hunger.consume(15);
    this.energy.expend(20);

    // Night
    this.clock.tick();
    this.hunger.eat(20);
    this.energy.rest(30);

    console.log("Day simulation complete.");
  }
}

