class RarityTable {
  constructor() {
    this.rarities = {
      common: 0.7,
      uncommon: 0.2,
      rare: 0.08,
      epic: 0.02
    };
  }

  rollRarity() {
    const roll = Math.random();
    let total = 0;
    for (const rarity in this.rarities) {
      total += this.rarities[rarity];
      if (roll < total) {
        return rarity;
      }
    }
    return "common"; // Default to common if no match
  }
}

