    const loot = this.lootSystem.generateLoot();
    const rarity = this.raritySystem.rollRarity();
    loot.rarity = rarity;
    this.items.push(loot);
  }

  displayInventory() {
    console.log("Inventory:");
    this.items.forEach((item, index) => {
      console.log(`${index + 1}. ${item.name} (x${item.quantity}) - ${item.rarity}`);
    });
  }
}

