class Economy {
  constructor() {
    this.balances = new Map();
  }

  getBalance(player) {
    return this.balances.get(player) || 0;
  }

  debit(player, amount) {
    const currentBalance = this.getBalance(player);
    if (currentBalance >= amount) {
      this.balances.set(player, currentBalance - amount);
      return true;
    }
    return false;
  }

  credit(player, amount) {
    const currentBalance = this.getBalance(player);
    this.balances.set(player, currentBalance + amount);
  }
}

class RarityTable {
  constructor() {
    this.rarityLevels = {
      COMMON: 0.6,
      UNCOMMON: 0.3,
      RARE: 0.09,
      EPIC: 0.01
    };
  }

  getRandomItem() {
    const random = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.rarityLevels)) {
      cumulativeProbability += probability;
      if (random <= cumulativeProbability) {
        return rarity;
      }
    }

    return 'COMMON'; // Fallback to common if something goes wrong
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  addItem(player, item) {
    if (!this.items.has(player)) {
      this.items.set(player, []);
    }
    this.items.get(player).push(item);
  }

  getInventory(player) {
    return this.items.get(player) || [];
  }
}

class Store {
  constructor(economy, rarityTable, inventory) {
    this.economy = economy;
    this.rarityTable = rarityTable;
    this.inventory = inventory;
    this.prices = {
      COMMON: 10,
      UNCOMMON: 20,
      RARE: 50,
      EPIC: 100
    };
  }

  getItemPrice(item) {
    return this.prices[item] || 0;
  }

  purchaseItem(player) {
    const item = this.rarityTable.getRandomItem();
    const price = this.getItemPrice(item);

    if (this.economy.debit(player, price)) {
      this.inventory.addItem(player, item);
      console.log(`${player} purchased a ${item} item for ${price} credits.`);
    } else {
      console.log(`${player} does not have enough credits to purchase a ${item} item.`);
    }
  }
}

