        this.name = name;
        this.ingredients = ingredients; // { ingredientName: quantity }
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    hasIngredients(recipe) {
        for (let [ingredient, requiredQuantity] of Object.entries(recipe.ingredients)) {
            if (!this.items[ingredient] || this.items[ingredient] < requiredQuantity) {
                return false;
            }
        }
        return true;
    }

    listItems() {
        return this.items;
    }
}

class Crafting {
    constructor(inventory, recipes) {
        this.inventory = inventory;
        this.recipes = recipes; // { recipeName: Recipe }
    }

    craft(recipeName) {
        const recipe = this.recipes[recipeName];
        if (!recipe) {
            console.log(`Recipe ${recipeName} not found.`);
            return false;
        }

        if (!this.inventory.hasIngredients(recipe)) {
            console.log(`Not enough ingredients to craft ${recipeName}.`);
            return false;
        }

        for (let [ingredient, requiredQuantity] of Object.entries(recipe.ingredients)) {
            this.inventory.removeItem(ingredient, requiredQuantity);
        }

        this.inventory.addItem(recipeName, 1);
        console.log(`Crafted ${recipeName}.`);
        return true;
    }
}

class Economy {
    constructor() {
        this.prices = {};
    }

    setPrice(item, price) {
        this.prices[item] = price;
    }

    getPrice(item) {
        return this.prices[item] || 0;
    }

    debit(amount) {
        if (amount > this.balance) {
            console.log(`Insufficient funds. Current balance: ${this.balance}.`);
            return false;
        }
        this.balance -= amount;
        console.log(`Debited ${amount}. New balance: ${this.balance}.`);
        return true;
    }

    credit(amount) {
        this.balance += amount;
        console.log(`Credited ${amount}. New balance: ${this.balance}.`);
    }

    getBalance() {
        return this.balance;
    }
}

class Store {
    constructor(inventory, economy) {
        this.inventory = inventory;
        this.economy = economy;
    }

    purchase(item, quantity) {
        const price = this.economy.getPrice(item);
        const totalCost = price * quantity;

        if (!this.economy.debit(totalCost)) {
            return false;
        }

        this.inventory.addItem(item, quantity);
        console.log(`Purchased ${quantity} of ${item}.`);
        return true;
    }
}

