class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients;
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return this.ingredients;
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  addItem(item, quantity) {
    if (this.items.has(item)) {
      this.items.set(item, this.items.get(item) + quantity);
    } else {
      this.items.set(item, quantity);
    }
  }

  removeItem(item, quantity) {
    if (this.items.has(item) && this.items.get(item) >= quantity) {
      this.items.set(item, this.items.get(item) - quantity);
      if (this.items.get(item) === 0) {
        this.items.delete(item);
      }
      return true;
    }
    return false;
  }

  hasItems(ingredients) {
    for (const [item, quantity] of ingredients) {
      if (!this.items.has(item) || this.items.get(item) < quantity) {
        return false;
      }
    }
    return true;
  }

  listItems() {
    return Object.fromEntries(this.items);
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes;
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe) {
      console.log(`Recipe "${recipeName}" not found.`);
      return false;
    }

    const ingredients = recipe.getIngredients();
    if (!this.inventory.hasItems(ingredients)) {
      console.log(`Insufficient ingredients for "${recipeName}".`);
      return false;
    }

    ingredients.forEach(([item, quantity]) => {
      this.inventory.removeItem(item, quantity);
    });

    console.log(`Crafted "${recipeName}".`);
    return true;
  }

  listRecipes() {
    return this.recipes.map(recipe => recipe.getName());
  }
}

