// RarityTable System
class RarityTable {
  constructor() {
    this.rarityMap = {
      common: 0.6,
      uncommon: 0.3,
      rare: 0.08,
      epic: 0.02
    };
  }

  getRandomRarity() {
    const random = Math.random();
    let cumulativeProbability = 0;

    for (const rarity in this.rarityMap) {
      cumulativeProbability += this.rarityMap[rarity];
      if (random <= cumulativeProbability) {
        return rarity;
      }
    }

    return 'common'; // Default to common if something goes wrong
  }
}

