// Recipe System
class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients;
    this.result = result;
  }

  canCraft(inventory) {
    for (const [item, count] of Object.entries(this.ingredients)) {
      if (!inventory.hasItem(item, count)) {
        return false;
      }
    }
    return true;
  }

  craft(inventory) {
    for (const [item, count] of Object.entries(this.ingredients)) {
      inventory.removeItem(item, count);
    }
    inventory.addItem(this.result, 1);
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  hasItem(item, count) {
    return (this.items[item] || 0) >= count;
  }

  addItem(item, count) {
    this.items[item] = (this.items[item] || 0) + count;
  }

  removeItem(item, count) {
    if (this.hasItem(item, count)) {
      this.items[item] -= count;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

// Crafting System
class Crafting {
  constructor() {
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) return false;
    return recipe.canCraft(inventory);
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe && recipe.canCraft(inventory)) {
      recipe.craft(inventory);
    }
  }
}

// Top-level coordinator
class GameCoordinator {
  constructor() {
    this.inventory = new Inventory();
    this.crafting = new Crafting();
  }

  addRecipe(name, ingredients, result) {
    const recipe = new Recipe(name, ingredients, result);
    this.crafting.addRecipe(recipe);
  }

  addItemToInventory(item, count) {
    this.inventory.addItem(item, count);
  }

  canCraft(recipeName) {
    return this.crafting.canCraft(recipeName, this.inventory);
  }

  craft(recipeName) {
    this.crafting.craft(recipeName, this.inventory);
  }

  getInventoryItem(item) {
    return this.inventory.getItemCount(item);
  }
}

