class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices = {}) {
    this.prices = prices;
  }

  getItemPrice(item) {
    return this.prices[item] || 0;
  }

  setItemPrice(item, price) {
    if (price >= 0) {
      this.prices[item] = price;
    }
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return this.items;
  }
}

class Store {
  constructor(bank, market, inventory) {
    this.bank = bank;
    this.market = market;
    this.inventory = inventory;
  }

  purchaseItem(item) {
    const price = this.market.getItemPrice(item);
    if (price > 0 && this.bank.withdraw(price)) {
      this.inventory.addItem(item);
      console.log(`Purchased ${item} for ${price}. New balance: ${this.bank.getBalance()}`);
      return true;
    }
    console.log(`Failed to purchase ${item}.`);
    return false;
  }
}

