class Store {
    constructor(pricing, demand) {
        this.pricing = pricing;
        this.demand = demand;
    }

    sell(quantity) {
        if (quantity > this.demand.getCurrentDemand()) {
            console.log("Not enough demand to sell that quantity.");
            return 0;
        }
        this.demand.updateDemand(-quantity);
        const totalRevenue = this.pricing.calculatePrice(quantity);
        console.log(`Sold ${quantity} items for a total of $${totalRevenue}.`);
        return totalRevenue;
    }

    checkDemand() {
        return this.demand.getCurrentDemand();
    }
}

