class Building {
  constructor(resourceSystem, economySystem) {
    this.resourceSystem = resourceSystem;
    this.economySystem = economySystem;
  }

  build(type, cost) {
    if (this.resourceSystem.hasResources(cost)) {
      this.resourceSystem.consumeResources(cost);
      this.economySystem.addBuilding(type);
      console.log(`Built ${type} successfully.`);
    } else {
      console.log(`Not enough resources to build ${type}.`);
    }
  }
}

class Resource {
  constructor(initialResources = {}) {
    this.resources = initialResources;
  }

  hasResources(cost) {
    for (const [resource, amount] of Object.entries(cost)) {
      if (this.resources[resource] === undefined || this.resources[resource] < amount) {
        return false;
      }
    }
    return true;
  }

  consumeResources(cost) {
    for (const [resource, amount] of Object.entries(cost)) {
      this.resources[resource] -= amount;
    }
  }

  addResources(amounts) {
    for (const [resource, amount] of Object.entries(amounts)) {
      this.resources[resource] = (this.resources[resource] || 0) + amount;
    }
  }
}

class Economy {
  constructor() {
    this.buildings = {};
  }

  addBuilding(type) {
    this.buildings[type] = (this.buildings[type] || 0) + 1;
  }

  getBuildingCount(type) {
    return this.buildings[type] || 0;
  }
}

