class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices; // { item: price }
  }

  getPrice(item) {
    return this.prices[item] || null;
  }

  sell(item, price) {
    if (price > 0) {
      this.prices[item] = price;
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { item: quantity }
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Coordinator {
  constructor() {
    this.bank = new Bank();
    this.market = new Market({ apple: 1, banana: 2 });
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    const price = this.market.getPrice(item);
    if (price !== null && this.bank.withdraw(price * quantity)) {
      this.inventory.addItem(item, quantity);
      return true;
    }
    return false;
  }

  sellItem(item, quantity) {
    if (this.inventory.removeItem(item, quantity)) {
      const price = this.market.getPrice(item);
      if (price !== null) {
        this.bank.deposit(price * quantity);
        return true;
      }
    }
    return false;
  }

  checkBalance() {
    return this.bank.getBalance();
  }

  checkInventory() {
    return this.inventory.getInventory();
  }
}

// Runnable demo
