class Loot {
  constructor() {
    this.lootPool = ['Potion', 'Sword', 'Shield'];
  }

  dropLoot() {
    const loot = this.lootPool[Math.floor(Math.random() * this.lootPool.length)];
    console.log(`Loot dropped: ${loot}`);
    return loot;
  }
}

// Coordinator
class Coordinator {
  constructor() {
    this.combat = new Combat();
    this.loot = new Loot();
  }

  startBattle(attacker, defender) {
    attacker.setCoordinator(this);
    defender.setCoordinator(this);
    this.combat.startCombat(attacker, defender);
  }

  onDefeat(defeated) {
    this.combat.endCombat();
    const loot = this.loot.dropLoot();
    console.log(`${defeated.name} drops ${loot}.`);
  }
}

