class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }

  matchesInventory(inventory) {
    for (const [ingredient, quantity] of Object.entries(this.ingredients)) {
      if (inventory[ingredient] === undefined || inventory[ingredient] < quantity) {
        return false;
      }
    }
    return true;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { itemName: quantity }
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItems(items) {
    for (const [item, quantity] of Object.entries(items)) {
      if (this.items[item] && this.items[item] >= quantity) {
        this.items[item] -= quantity;
      } else {
        throw new Error(`Not enough ${item} in inventory.`);
      }
    }
  }

  getInventory() {
    return { ...this.items };
  }
}

class Crafting {
  constructor() {
    this.recipes = [];
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) {
      throw new Error(`Recipe ${recipeName} not found.`);
    }
    return recipe.matchesInventory(inventory);
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (!recipe) {
      throw new Error(`Recipe ${recipeName} not found.`);
    }
    if (!recipe.matchesInventory(inventory)) {
      throw new Error(`Not enough ingredients to craft ${recipeName}.`);
    }
    inventory.removeItems(recipe.ingredients);
    return `Crafted ${recipeName}`;
  }
}

