class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients; // { item1: amount1, item2: amount2, ... }
    this.result = result; // { item: amount }
  }

  canCraft(inventory) {
    for (const [item, amount] of Object.entries(this.ingredients)) {
      if (inventory.getItemAmount(item) < amount) {
        return false;
      }
    }
    return true;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, amount) {
    if (this.items[item]) {
      this.items[item] += amount;
    } else {
      this.items[item] = amount;
    }
  }

  removeItem(item, amount) {
    if (this.items[item] >= amount) {
      this.items[item] -= amount;
    } else {
      throw new Error(`Not enough ${item} in inventory.`);
    }
  }

  getItemAmount(item) {
    return this.items[item] || 0;
  }
}

class Crafting {
  constructor(recipeBook, inventory) {
    this.recipeBook = recipeBook; // Array of Recipe instances
    this.inventory = inventory;
  }

  craft(recipeName) {
    const recipe = this.recipeBook.find(r => r.name === recipeName);
    if (!recipe) {
      throw new Error(`Recipe ${recipeName} not found.`);
    }

    if (!recipe.canCraft(this.inventory)) {
      throw new Error(`Cannot craft ${recipeName}: insufficient ingredients.`);
    }

    for (const [item, amount] of Object.entries(recipe.ingredients)) {
      this.inventory.removeItem(item, amount);
    }

    for (const [resultItem, resultAmount] of Object.entries(recipe.result)) {
      this.inventory.addItem(resultItem, resultAmount);
    }

    console.log(`Crafted ${recipeName}. Inventory updated.`);
  }
}

