            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    removeItem(item, quantity = 1) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    hasItems(items) {
        for (const [item, quantity] of Object.entries(items)) {
            if (!this.items[item] || this.items[item] < quantity) {
                return false;
            }
        }
        return true;
    }

    getItems() {
        return { ...this.items };
    }
}

class Crafting {
    constructor(recipeBook, inventory) {
        this.recipeBook = recipeBook;
        this.inventory = inventory;
    }

    craft(recipeId) {
        const recipe = this.recipeBook.find(r => r.id === recipeId);
        if (!recipe) {
            console.log(`Recipe with ID ${recipeId} not found.`);
            return false;
        }

        if (!this.inventory.hasItems(recipe.inputs)) {
            console.log(`Insufficient resources to craft ${recipeId}.`);
            return false;
        }

        for (const [item, quantity] of Object.entries(recipe.inputs)) {
            this.inventory.removeItem(item, quantity);
        }

        this.inventory.addItem(recipe.output);
        console.log(`Crafted ${recipe.output}.`);
        return true;
    }

    getRecipeBook() {
        return this.recipeBook.map(recipe => ({ id: recipe.id, inputs: recipe.inputs, output: recipe.output }));
    }
