class Loot {
  constructor(itemName, rarity, value) {
    this.itemName = itemName;
    this.rarity = rarity;
    this.value = value;
  }

  getDescription() {
    return `${this.itemName} (Rarity: ${this.rarity}, Value: ${this.value})`;
  }
