class RarityTable {
  constructor() {
    this.rarityLevels = {
      COMMON: { chance: 0.6 },
      UNCOMMON: { chance: 0.3 },
      RARE: { chance: 0.09 },
      EPIC: { chance: 0.01 }
    };
  }

  generateLoot() {
    const totalChance = 1.0;
    let random = Math.random();
    let cumulativeChance = 0;

    for (const [rarity, { chance }] of Object.entries(this.rarityLevels)) {
      cumulativeChance += chance;
      if (random <= cumulativeChance) {
        return new Loot(this.getRandomItemName(rarity), rarity, this.getValueForRarity(rarity));
      }
    }

    throw new Error("Failed to generate loot");
  }

  getRandomItemName(rarity) {
    const items = {
      COMMON: ["Potion", "Scroll", "Coin"],
      UNCOMMON: ["Ring", "Amulet", "Wand"],
      RARE: ["Sword", "Shield", "Armor"],
      EPIC: ["Staff", "Helmet", "Gloves"]
    };

    return items[rarity][Math.floor(Math.random() * items[rarity].length)];
  }

  getValueForRarity(rarity) {
    const values = {
      COMMON: 10,
      UNCOMMON: 50,
      RARE: 100,
      EPIC: 500
    };

    return values[rarity];
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(loot) {
    this.items.push(loot);
