    constructor(eventBus) {
        this.eventBus = eventBus;
        this.eventBus.subscribe('updateDemand', this.updateDemand.bind(this));
    }

    updateDemand(item) {
        if (Math.random() > 0.5) {
            item.demand += Math.floor(Math.random() * 20); // Randomly increase demand
        } else {
            item.demand -= Math.floor(Math.random() * 10); // Randomly decrease demand
        }
