class Crop {
    constructor(name, growTime, sellPrice) {
        this.name = name;
        this.growTime = growTime;
        this.sellPrice = sellPrice;
        this.isReady = false;
        this.daysGrown = 0;
    }

    grow() {
        this.daysGrown++;
        if (this.daysGrown >= this.growTime) {
            this.isReady = true;
        }
    }

    isMature() {
        return this.isReady;
    }

    sell() {
        if (this.isReady) {
            const price = this.sellPrice;
            this.isReady = false;
            this.daysGrown = 0;
            return price;
        }
        return 0;
    }
}

class Market {
    constructor() {
        this.inventory = {};
    }

    buyCrop(crop, quantity) {
        if (this.inventory[crop.name]) {
            this.inventory[crop.name] -= quantity;
            return true;
        }
        return false;
    }

    sellCrop(crop, quantity) {
        if (this.inventory[crop.name]) {
            this.inventory[crop.name] += quantity;
        } else {
            this.inventory[crop.name] = quantity;
        }
        return true;
    }

    getInventory() {
        return this.inventory;
    }
}

class Farm {
    constructor(market) {
        this.market = market;
        this.crops = [];
    }

    plantCrop(crop) {
        this.crops.push(crop);
    }

    growCrops() {
        this.crops.forEach(crop => crop.grow());
    }

    harvestCrops() {
        let totalEarnings = 0;
        this.crops = this.crops.filter(crop => {
            if (crop.isMature()) {
                totalEarnings += crop.sell();
                this.market.sellCrop(crop, 1);
            }
            return !crop.isMature();
        });
        return totalEarnings;
    }

    getMarketInventory() {
        return this.market.getInventory();
    }
}

// Demo
