class Bank {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}, new balance is ${this.balance}`);
    } else {
      console.log("Deposit amount must be positive");
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}, new balance is ${this.balance}`);
    } else {
      console.log("Invalid withdrawal amount");
    }
  }

  getBalance() {
    return this.balance;
  }
}

// Market system
class Market {
  constructor(prices = {}) {
    this.prices = prices;
  }

  buy(item, quantity, bank) {
    const price = this.prices[item];
    if (price) {
      const totalCost = price * quantity;
      if (bank.getBalance() >= totalCost) {
        bank.withdraw(totalCost);
        console.log(`Bought ${quantity} of ${item} for ${totalCost}`);
        return true;
      } else {
        console.log(`Insufficient funds to buy ${quantity} of ${item}`);
        return false;
      }
    } else {
      console.log(`Item ${item} is not available in the market`);
      return false;
    }
  }

  sell(item, quantity, bank) {
    const price = this.prices[item];
    if (price) {
      const totalEarnings = price * quantity;
      bank.deposit(totalEarnings);
      console.log(`Sold ${quantity} of ${item} for ${totalEarnings}`);
      return true;
    } else {
      console.log(`Item ${item} is not available in the market`);
      return false;
    }
  }
}

