    this.crops.push(crop);
  }

  growCrops() {
    this.crops.forEach(crop => crop.grow());
  }

  harvestCrops() {
    const harvested = this.crops.filter(crop => crop.isMature()).map(crop => crop.sell());
    this.crops = this.crops.filter(crop => !crop.isMature());
    return harvested;
  }
