class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  addMoney(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  subtractMoney(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Shop {
  constructor(prices) {
    this.prices = prices; // { item1: price, item2: price, ... }
  }

  getPrice(item) {
    return this.prices[item] || null;
  }

  purchase(wallet, item) {
    const price = this.getPrice(item);
    if (price !== null && wallet.subtractMoney(price)) {
      return true;
    }
    return false;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

