class Pricing {
  constructor(basePrice) {
    this.basePrice = basePrice;
  }

  calculatePrice(product, quantity) {
    // Simple pricing model: base price + 10% of base price per unit
    return this.basePrice + (this.basePrice * 0.1 * quantity);
  }
}

class Demand {
  constructor(initialDemand) {
    this.demand = initialDemand;
  }

  adjustDemand(change) {
    // Adjust demand by a given change value
    this.demand += change;
    // Ensure demand does not go below zero
    this.demand = Math.max(0, this.demand);
  }

  getCurrentDemand() {
    return this.demand;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sellProduct(product, quantity) {
    if (this.demand.getCurrentDemand() >= quantity) {
      const totalCost = this.pricing.calculatePrice(product, quantity);
      this.demand.adjustDemand(-quantity);
      console.log(`Sold ${quantity} ${product}(s) for $${totalCost.toFixed(2)}. Remaining demand: ${this.demand.getCurrentDemand()}`);
      return true;
    } else {
      console.log(`Not enough demand to sell ${quantity} ${product}(s). Current demand: ${this.demand.getCurrentDemand()}`);
      return false;
    }
  }
}

