        if (crop) {
            if (!this.inventory[crop.name]) {
                this.inventory[crop.name] = 0;
            }
            this.inventory[crop.name] += 1;
            return true;
        }
        return false;
    }

    sellCrop(cropName) {
        if (this.inventory[cropName] && this.inventory[cropName] > 0) {
            this.inventory[cropName] -= 1;
