// Crafting System
class Crafting {
    constructor(inventory, recipeBook) {
        this.inventory = inventory;
        this.recipeBook = recipeBook;
    }

    canCraft(recipeName) {
        const recipe = this.recipeBook.getRecipe(recipeName);
        if (!recipe) return false;

        for (const [item, amount] of Object.entries(recipe.ingredients)) {
            if (this.inventory.get(item) < amount) return false;
        }
        return true;
    }

    craft(recipeName) {
        if (!this.canCraft(recipeName)) return false;

        const recipe = this.recipeBook.getRecipe(recipeName);
        for (const [item, amount] of Object.entries(recipe.ingredients)) {
            this.inventory.use(item, amount);
        }
        this.inventory.add(recipe.result, 1);
        return true;
    }
}

// Recipe System
class RecipeBook {
    constructor() {
        this.recipes = {};
    }

    addRecipe(name, ingredients, result) {
        this.recipes[name] = { ingredients, result };
    }

    getRecipe(name) {
        return this.recipes[name];
    }
}

