class Inventory {
    constructor() {
        this.items = {};
    }

    add(item, amount) {
        this.items[item] = (this.items[item] || 0) + amount;
    }

    use(item, amount) {
        if (this.items[item] >= amount) {
            this.items[item] -= amount;
        } else {
            console.log(`Not enough ${item} in inventory.`);
        }
    }

    get(item) {
        return this.items[item] || 0;
    }
}

