class Crop {
  constructor(name, growthRate) {
    this.name = name;
    this.growthRate = growthRate;
    this.growthStage = 0;
  }

  grow() {
    this.growthStage += this.growthRate;
    return this.growthStage;
  }

  isReadyToHarvest() {
    return this.growthStage >= 10;
  }

  harvest() {
    if (this.isReadyToHarvest()) {
      const yieldAmount = this.growthStage;
      this.growthStage = 0;
      return yieldAmount;
    }
    return 0;
  }
}

class Farm {
  constructor() {
    this.crops = [];
  }

  plantCrop(crop) {
    this.crops.push(crop);
  }

  growAllCrops() {
    this.crops.forEach(crop => crop.grow());
  }

  harvestCrops() {
    return this.crops.reduce((total, crop) => {
      const yieldAmount = crop.harvest();
      if (yieldAmount > 0) {
        total[crop.name] = (total[crop.name] || 0) + yieldAmount;
      }
      return total;
    }, {});
  }
}

class Market {
  constructor() {
    this.prices = { Wheat: 2, Carrot: 3 };
  }

  sellCrops(cropYields) {
    return Object.entries(cropYields).reduce((total, [cropName, amount]) => {
      const price = this.prices[cropName] || 0;
      total += amount * price;
      return total;
    }, 0);
  }
}

class Coordinator {
  constructor() {
    this.farm = new Farm();
    this.market = new Market();
  }

  plantCrop(name, growthRate) {
    const crop = new Crop(name, growthRate);
    this.farm.plantCrop(crop);
  }

  simulateDay() {
    this.farm.growAllCrops();
    const cropYields = this.farm.harvestCrops();
    const earnings = this.market.sellCrops(cropYields);
    return earnings;
  }
}

// Runnable demo
const coordinator = new Coordinator();
coordinator.plantCrop('Wheat', 2);
coordinator.plantCrop('Carrot', 1);

console.log('Day 1 Earnings:', coordinator.simulateDay()); // Day 1 Earnings: 0
console.log('Day 2 Earnings:', coordinator.simulateDay()); // Day 2 Earnings: 30
console.log('Day 3 Earnings:', coordinator.simulateDay()); // Day 3 Earnings: 30
