class Economy {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Store {
  constructor(items = {}, economy) {
    this.items = items; // { itemName: price }
    this.economy = economy;
  }

  buyItem(itemName) {
    const price = this.items[itemName];
    if (price !== undefined && this.economy.withdraw(price)) {
      return true;
    }
    return false;
  }

  sellItem(itemName, price) {
    if (price > 0) {
      this.items[itemName] = price;
      return true;
    }
    return false;
  }

  getItemPrice(itemName) {
    return this.items[itemName];
  }
}

class Inventory {
  constructor(items = {}, store) {
    this.items = items; // { itemName: quantity }
    this.store = store;
  }

  addItem(itemName, quantity) {
    if (quantity > 0) {
      if (this.items[itemName] === undefined) {
        this.items[itemName] = 0;
      }
      this.items[itemName] += quantity;
      return true;
    }
    return false;
  }

  removeItem(itemName, quantity) {
    if (quantity > 0 && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
      return true;
    }
    return false;
  }

  getItemQuantity(itemName) {
    return this.items[itemName] || 0;
  }

  purchaseItem(itemName, quantity) {
    const pricePerItem = this.store.getItemPrice(itemName);
    if (pricePerItem !== undefined && this.store.buyItem(itemName)) {
      this.addItem(itemName, quantity);
      return true;
    }
    return false;
  }

  sellItem(itemName, quantity) {
    if (this.removeItem(itemName, quantity)) {
      const pricePerItem = this.store.getItemPrice(itemName);
      if (pricePerItem !== undefined) {
        this.store.economy.deposit(pricePerItem * quantity);
        return true;
      }
    }
    return false;
  }
}

