class Hunger {
  constructor(initialLevel = 100) {
    this.level = initialLevel;
  }

  eat(amount = 20) {
    this.level = Math.min(100, this.level + amount);
    return this.level;
  }

  consume(amount = 10) {
    this.level = Math.max(0, this.level - amount);
    return this.level;
  }

  getLevel() {
    return this.level;
  }
}

class Energy {
  constructor(initialLevel = 100) {
    this.level = initialLevel;
  }

  rest(amount = 20) {
    this.level = Math.min(100, this.level + amount);
    return this.level;
  }

  expend(amount = 10) {
    this.level = Math.max(0, this.level - amount);
    return this.level;
  }

  getLevel() {
    return this.level;
  }
}

class Clock {
  constructor() {
    this.time = 0;
  }

  tick(interval = 1) {
    this.time += interval;
    return this.time;
  }

  getTime() {
    return this.time;
  }
}

