class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

class Skill {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.skills = {};
    this.eventBus.subscribe('levelUp', this.onLevelUp.bind(this));
  }

  learn(skillName, cost) {
    if (this.skills[skillName]) {
      console.log(`Already know ${skillName}`);
      return;
    }
    this.skills[skillName] = { cost };
    console.log(`Learned ${skillName} with cost ${cost}`);
  }

  use(skillName) {
    if (!this.skills[skillName]) {
      console.log(`Don't know ${skillName}`);
      return;
    }
    console.log(`Used ${skillName}`);
    this.eventBus.emit('skillUsed', { skillName, cost: this.skills[skillName].cost });
  }

  onLevelUp(data) {
    console.log(`Level up! Learning new skills...`);
    this.learn('Advanced Technique', 10);
  }
}

class Experience {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.experiencePoints = 0;
    this.eventBus.subscribe('skillUsed', this.onSkillUsed.bind(this));
  }

  earn(points) {
    this.experiencePoints += points;
    console.log(`Earned ${points} experience points. Total: ${this.experiencePoints}`);
    this.checkLevelUp();
  }

  onSkillUsed(data) {
    this.earn(data.cost);
  }

  checkLevelUp() {
    const nextLevelThreshold = (this.level + 1) * 10;
    if (this.experiencePoints >= nextLevelThreshold) {
      this.levelUp();
    }
  }

  levelUp() {
    this.level++;
    console.log(`Leveled up to level ${this.level}`);
    this.eventBus.emit('levelUp', { level: this.level });
  }
}

