class Recipe {
    constructor(name, ingredients, result) {
        this.name = name;
        this.ingredients = ingredients; // { ingredient1: amount1, ingredient2: amount2, ... }
        this.result = result; // { item: amount }
    }
}

class Inventory {
    constructor() {
        this.items = {}; // { item1: amount1, item2: amount2, ... }
    }

    addItem(item, amount) {
        if (this.items[item]) {
            this.items[item] += amount;
        } else {
            this.items[item] = amount;
        }
    }

    removeItem(item, amount) {
        if (this.items[item] && this.items[item] >= amount) {
            this.items[item] -= amount;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    hasIngredients(ingredients) {
        for (const [item, amount] of Object.entries(ingredients)) {
            if (!this.items[item] || this.items[item] < amount) {
                return false;
            }
        }
        return true;
    }

    getItems() {
        return { ...this.items };
    }
}

class Crafting {
    constructor(inventory, recipes) {
        this.inventory = inventory;
        this.recipes = recipes; // Array of Recipe instances
    }

    craft(recipeName) {
        const recipe = this.recipes.find(r => r.name === recipeName);
        if (!recipe) {
            console.log(`Recipe ${recipeName} not found.`);
            return false;
        }

        if (!this.inventory.hasIngredients(recipe.ingredients)) {
            console.log(`Missing ingredients for ${recipeName}.`);
            return false;
        }

        for (const [item, amount] of Object.entries(recipe.ingredients)) {
            this.inventory.removeItem(item, amount);
        }

        for (const [resultItem, resultAmount] of Object.entries(recipe.result)) {
            this.inventory.addItem(resultItem, resultAmount);
        }

        console.log(`Crafted ${recipeName}.`);
        return true;
    }
}

