        this.bank.deposit(totalEarnings);
        console.log(`Sold ${quantity} of ${item} for ${totalEarnings}`);
      } else {
        console.log('Insufficient quantity in inventory');
      }
    } else {
      console.log(`Price for ${item} not set`);
    }
  }
}

