  }
}

class Resource {
  constructor(name, initialAmount = 0) {
    this.name = name;
    this.amount = initialAmount;
  }

  consume(amount) {
    if (this.amount >= amount) {
      this.amount -= amount;
      return true;
    }
    return false;
  }

  produce(amount) {
    this.amount += amount;
  }

  getAmount() {
    return this.amount;
  }

  getName() {
    return this.name;
  }
}

class Economy {
  constructor(building, resource) {
    this.building = building;
    this.resource = resource;
  }

  tradeBuildingResourceForEconomyResource(buildingResourceName, economyResourceName, amount) {
    const buildingResourceAmount = this.building.getResource(buildingResourceName);
    if (buildingResourceAmount >= amount) {
      this.building.addResource(buildingResourceName, -amount);
      this.resource.produce(amount);
      return true;
    }
    return false;
  }

  tradeEconomyResourceForBuildingResource(economyResourceName, buildingResourceName, amount) {
    const economyResourceAmount = this.resource.getAmount();
    if (economyResourceAmount >= amount) {
      this.resource.consume(amount);
      this.building.addResource(buildingResourceName, amount);
      return true;
    }
    return false;
  }
}

