  }

  getItemStock(itemName) {
    return this.items[itemName]?.stock || 0;
  }

  sellItem(itemName, quantity) {
    if (this.items[itemName] && this.items[itemName].stock >= quantity) {
      this.items[itemName].stock -= quantity;
      return true;
    }
    return false;
  }
