    if (this.lootPool.length === 0) return null;
    const randomIndex = Math.floor(Math.random() * this.lootPool.length);
    return this.lootPool.splice(randomIndex, 1)[0];
  }
}

class RarityTable {
  constructor() {
    this.rarityMap = {
      common: 0.7,
      uncommon: 0.2,
      rare: 0.08,
      epic: 0.01,
      legendary: 0.01
    };
  }

  generateRarity() {
    const rand = Math.random();
    let cumulativeProbability = 0;
    for (const rarity in this.rarityMap) {
      cumulativeProbability += this.rarityMap[rarity];
      if (rand <= cumulativeProbability) return rarity;
    }
    return 'common'; // Default to common if something goes wrong
  }
}

