        }

        this.balance -= totalCost;
        this.inventory[item] += quantity;
        console.log(`Purchased ${quantity} ${item}(s) for ${totalCost}. Balance: ${this.balance}`);
    }

    getInventory() {
        return this.inventory;
    }

