class EventBus {
    constructor() {
        this.listeners = {};
    }

    emit(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(listener => listener(data));
        }
    }

    subscribe(event, listener) {
        if (!this.listeners[event]) {
            this.listeners[event] = [];
        }
        this.listeners[event].push(listener);
    }
}

class Economy {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.balance = 0;

        this.eventBus.subscribe('buyItem', ({ cost }) => {
            if (this.balance >= cost) {
                this.balance -= cost;
                this.eventBus.emit('transactionSuccessful', { amount: cost });
            } else {
                this.eventBus.emit('transactionFailed', { message: 'Insufficient funds' });
            }
        });

        this.eventBus.subscribe('deposit', ({ amount }) => {
            this.balance += amount;
            this.eventBus.emit('depositSuccessful', { amount });
        });
    }

    getBalance() {
        return this.balance;
    }
}

class Store {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = [
            { name: 'Potion', cost: 10 },
            { name: 'Sword', cost: 50 }
        ];

        this.eventBus.subscribe('listItems', () => {
            this.eventBus.emit('itemsListed', { items: this.items });
        });

        this.eventBus.subscribe('purchaseItem', ({ item }) => {
            const selectedItem = this.items.find(i => i.name === item);
            if (selectedItem) {
                this.eventBus.emit('buyItem', { cost: selectedItem.cost });
            } else {
                this.eventBus.emit('transactionFailed', { message: 'Item not found' });
            }
        });
    }
}

class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = [];

        this.eventBus.subscribe('transactionSuccessful', ({ amount }) => {
            console.log(`Transaction successful, spent ${amount} gold.`);
        });

        this.eventBus.subscribe('transactionFailed', ({ message }) => {
            console.log(`Transaction failed: ${message}`);
        });

        this.eventBus.subscribe('depositSuccessful', ({ amount }) => {
            console.log(`Deposited ${amount} gold.`);
        });

        this.eventBus.subscribe('itemsListed', ({ items }) => {
            console.log('Available items:');
            items.forEach(item => console.log(`- ${item.name} (${item.cost} gold)`));
        });
    }

    addItem(item) {
        this.items.push(item);
        this.eventBus.emit('itemAdded', { item });
    }
}

