// RarityTable.js
class RarityTable {
    constructor() {
        this.table = [
            { rarity: 'common', probability: 0.5 },
            { rarity: 'uncommon', probability: 0.3 },
            { rarity: 'rare', probability: 0.1 },
            { rarity: 'epic', probability: 0.05 },
            { rarity: 'legendary', probability: 0.05 }
        ];
    }

    rollRarity() {
        const roll = Math.random();
        let cumulativeProbability = 0;

        for (const entry of this.table) {
            cumulativeProbability += entry.probability;
            if (roll < cumulativeProbability) {
                return entry.rarity;
            }
        }

        return 'common'; // Default to common if something goes wrong
    }
}

// Inventory.js
class Inventory {
    constructor() {
        this.items = [];
    }

    addItem(item) {
        this.items.push(item);
    }

    getItems() {
        return this.items;
    }

    getTotalValue() {
        return this.items.reduce((total, item) => total + item.getValue(), 0);
    }
}

