class Pricing {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('item-sold', this.updatePrice.bind(this));
    this.prices = {};
  }

  setInitialPrice(item, price) {
    this.prices[item] = price;
  }

  updatePrice(item) {
    if (this.prices[item]) {
      this.prices[item] *= 0.95; // Reduce price by 5%
      this.eventBus.emit('price-updated', { item, newPrice: this.prices[item] });
    }
  }
}

class Demand {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('price-updated', this.updateDemand.bind(this));
    this.demand = {};
  }

  setInitialDemand(item, demand) {
    this.demand[item] = demand;
  }

  updateDemand({ item, newPrice }) {
    if (this.demand[item]) {
      this.demand[item] += newPrice < 10 ? 5 : -3; // Increase demand if price is low
      this.eventBus.emit('demand-updated', { item, newDemand: this.demand[item] });
    }
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('demand-updated', this.stockItems.bind(this));
    this.inventory = {};
  }

  addItem(item, quantity) {
    this.inventory[item] = quantity;
  }

  sellItem(item) {
    if (this.inventory[item] > 0) {
      this.inventory[item]--;
      this.eventBus.emit('item-sold', item);
      console.log(`Sold ${item}. Remaining stock: ${this.inventory[item]}`);
    } else {
      console.log(`Out of stock for ${item}`);
    }
  }

  stockItems({ item, newDemand }) {
    if (newDemand > 10) {
      this.inventory[item] += 10; // Restock if demand is high
      console.log(`Restocked ${item}. New stock: ${this.inventory[item]}`);
    }
  }
}

