class Recipe {
    constructor(name, ingredients, result) {
        this.name = name;
        this.ingredients = ingredients; // { ingredientName: amount }
        this.result = result; // { itemName: amount }
    }
}

class Crafting {
    constructor(recipes) {
        this.recipes = new Map(recipes.map(recipe => [recipe.name, recipe]));
    }

    canCraft(recipeName, inventory) {
        const recipe = this.recipes.get(recipeName);
        if (!recipe) return false;
        for (const [ingredient, amount] of Object.entries(recipe.ingredients)) {
            if ((inventory[ingredient] || 0) < amount) {
                return false;
            }
        }
        return true;
    }

    craft(recipeName, inventory) {
        const recipe = this.recipes.get(recipeName);
        if (!this.canCraft(recipeName, inventory)) return false;
        for (const [ingredient, amount] of Object.entries(recipe.ingredients)) {
            inventory[ingredient] -= amount;
        }
        for (const [item, amount] of Object.entries(recipe.result)) {
            inventory[item] = (inventory[item] || 0) + amount;
        }
        return true;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, amount) {
        this.items[item] = (this.items[item] || 0) + amount;
    }

    removeItem(item, amount) {
        if ((this.items[item] || 0) < amount) return false;
        this.items[item] -= amount;
        return true;
    }

    getInventory() {
        return { ...this.items };
    }
}

class Economy {
    constructor(prices) {
        this.prices = prices; // { itemName: price }
    }

    getPrice(item) {
        return this.prices[item] || 0;
    }

    debit(account, amount) {
        if (account.balance < amount) return false;
        account.balance -= amount;
        return true;
    }

    credit(account, amount) {
        account.balance += amount;
    }
}

class Store {
    constructor(economy, inventory) {
        this.economy = economy;
        this.inventory = inventory;
    }

    purchase(item, quantity, account) {
        const pricePerItem = this.economy.getPrice(item);
        const totalCost = pricePerItem * quantity;
        if (!this.economy.debit(account, totalCost)) return false;
        this.inventory.addItem(item, quantity);
        return true;
    }
}

