class Demand {
  constructor(initialDemand, demandModifier) {
    this.currentDemand = initialDemand;
    this.demandModifier = demandModifier;
  }

  updateDemand(supply, price) {
    this.currentDemand += this.demandModifier * (supply - this.currentDemand) - price;
    return this.currentDemand;
  }
}

class Store {
