    const price = this.pricing.calculatePrice(product);
    const updatedDemand = this.demand.updateDemand(this.inventory, price);
    const actualQuantitySold = Math.min(quantity, updatedDemand, this.inventory);

    this.inventory -= actualQuantitySold;
    console.log(`Sold ${actualQuantitySold} units at ${price.toFixed(2)}`);
    console.log(`Remaining inventory: ${this.inventory}`);
    console.log(`Current demand: ${updatedDemand.toFixed(2)}`);
  }
