        this.eventBus = eventBus;
        this.eventBus.subscribe('questRewarded', this.onQuestRewarded.bind(this));
    }

    onQuestRewarded(questId) {
        console.log(`Rewarding for quest ${questId}.`);
        const reward = { gold: 100, experience: 50 };
        this.eventBus.emit('rewardGranted', reward);
    }
}

