        this.buildingData = buildingData;
    }

    getBuilding(name) {
        return this.buildingData[name] || null;
    }
}

class Resource {
    constructor() {
        this.resources = {
            wood: 100,
            stone: 100,
            gold: 50
        };
    }

    getResources() {
        return this.resources;
    }

    addResource(resource, amount) {
        if (this.resources[resource] !== undefined) {
            this.resources[resource] += amount;
        }
    }

    removeResource(resource, amount) {
        if (this.resources[resource] !== undefined && this.resources[resource] >= amount) {
            this.resources[resource] -= amount;
            return true;
        }
        return false;
    }
}

class Economy {
    constructor(buildingSystem, resourceSystem) {
        this.buildingSystem = buildingSystem;
        this.resourceSystem = resourceSystem;
    }

    buildBuilding(buildingName, cost) {
        const building = this.buildingSystem.getBuilding(buildingName);
        if (building) {
            const resources = this.resourceSystem.getResources();
            let canBuild = true;
            for (const resource in cost) {
                if (resources[resource] < cost[resource]) {
                    canBuild = false;
                    break;
                }
            }
            if (canBuild) {
                for (const resource in cost) {
                    this.resourceSystem.removeResource(resource, cost[resource]);
                }
                console.log(`Built ${buildingName}`);
                return true;
            } else {
                console.log(`Not enough resources to build ${buildingName}`);
                return false;
            }
        } else {
            console.log(`Building ${buildingName} does not exist`);
            return false;
        }
    }

    collectResources(buildingName) {
        const building = this.buildingSystem.getBuilding(buildingName);
        if (building && building.production) {
            for (const resource in building.production) {
                this.resourceSystem.addResource(resource, building.production[resource]);
            }
            console.log(`Collected resources from ${buildingName}`);
        } else {
            console.log(`Building ${buildingName} does not exist or does not produce resources`);
        }
    }
}

