// Event Bus Implementation
class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Recipe System
class Recipe {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = {};

    this.eventBus.subscribe('craft', this.handleCraft.bind(this));
  }

  addRecipe(item, ingredients) {
    this.recipes[item] = ingredients;
  }

  handleCraft(item) {
    const ingredients = this.recipes[item];
    if (ingredients) {
      this.eventBus.emit('checkIngredients', { item, ingredients });
    } else {
      console.log(`No recipe found for ${item}`);
    }
  }
}

// Inventory System
class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};

    this.eventBus.subscribe('checkIngredients', this.checkIngredients.bind(this));
    this.eventBus.subscribe('removeIngredients', this.removeIngredients.bind(this));
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  checkIngredients({ item, ingredients }) {
    let canCraft = true;
    for (const [ingredient, requiredQuantity] of Object.entries(ingredients)) {
      if (!this.items[ingredient] || this.items[ingredient] < requiredQuantity) {
        canCraft = false;
        break;
      }
    }
    if (canCraft) {
      this.eventBus.emit('removeIngredients', { item, ingredients });
      console.log(`${item} crafted successfully!`);
    } else {
      console.log(`Not enough ingredients to craft ${item}`);
    }
  }

  removeIngredients({ ingredients }) {
    for (const [ingredient, requiredQuantity] of Object.entries(ingredients)) {
      this.items[ingredient] -= requiredQuantity;
    }
  }
}

// Crafting System
class Crafting {
  constructor(eventBus) {
    this.eventBus = eventBus;
  }

  craft(item) {
    this.eventBus.emit('craft', item);
  }
}

