class Trade {
  constructor() {
    this.resources = { gold: 0, wood: 0, stone: 0 };
  }

  buy(resource, amount, price) {
    if (this.resources.gold >= price) {
      this.resources.gold -= price;
      this.resources[resource] = (this.resources[resource] || 0) + amount;
      return true;
    }
    return false;
  }

  sell(resource, amount, price) {
    if (this.resources[resource] >= amount) {
      this.resources[resource] -= amount;
      this.resources.gold += price;
      return true;
    }
    return false;
  }

  getResources() {
    return { ...this.resources };
  }
}

class Reputation {
  constructor() {
    this.standing = 0;
  }

  increase(amount) {
    this.standing += amount;
  }

  decrease(amount) {
    this.standing -= amount;
  }

  getStanding() {
    return this.standing;
  }
}

class Faction {
  constructor(tradeSystem, reputationSystem) {
    this.tradeSystem = tradeSystem;
    this.reputationSystem = reputationSystem;
  }

  tradeWithFaction(resource, amount, price) {
    if (this.tradeSystem.buy(resource, amount, price)) {
      this.reputationSystem.increase(1);
      console.log(`Traded ${amount} ${resource} for ${price} gold. Reputation increased.`);
    } else {
      this.reputationSystem.decrease(1);
      console.log(`Failed to trade ${amount} ${resource} for ${price} gold. Reputation decreased.`);
    }
  }

  sellToFaction(resource, amount, price) {
    if (this.tradeSystem.sell(resource, amount, price)) {
      this.reputationSystem.increase(1);
      console.log(`Sold ${amount} ${resource} for ${price} gold. Reputation increased.`);
    } else {
      this.reputationSystem.decrease(1);
      console.log(`Failed to sell ${amount} ${resource} for ${price} gold. Reputation decreased.`);
    }
  }

  getStatus() {
    return {
      resources: this.tradeSystem.getResources(),
      reputation: this.reputationSystem.getStanding()
    };
  }
}

