// Recipe System
class Recipe {
  constructor() {
    this.recipes = {
      sword: { ingredients: ['iron', 'wood'] },
      shield: { ingredients: ['leather', 'wood'] }
    };
  }

  getRecipe(itemName) {
    return this.recipes[itemName];
  }

  addRecipe(itemName, ingredients) {
    this.recipes[itemName] = { ingredients };
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {
      iron: 10,
      wood: 15,
      leather: 5
    };
  }

  hasItems(ingredients) {
    return ingredients.every(ingredient => this.items[ingredient] > 0);
  }

  consumeItems(ingredients) {
    ingredients.forEach(ingredient => {
      if (this.items[ingredient] > 0) {
        this.items[ingredient]--;
      }
    });
  }
}

// Coordinator
class GameCoordinator {
  constructor() {
    this.recipeSystem = new Recipe();
    this.inventorySystem = new Inventory();
    this.craftingSystem = new Crafting(this.recipeSystem);
  }

  craftItem(itemName) {
    const recipe = this.recipeSystem.getRecipe(itemName);
    if (recipe && this.inventorySystem.hasItems(recipe.ingredients)) {
      this.inventorySystem.consumeItems(recipe.ingredients);
      return this.craftingSystem.craft(itemName);
    } else {
      return `Insufficient ingredients to craft ${itemName}`;
    }
  }

  addRecipe(itemName, ingredients) {
    this.recipeSystem.addRecipe(itemName, ingredients);
  }
}

