class Wallet {
    constructor(initialBalance = 0) {
        this.balance = initialBalance;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            return true;
        }
        return false;
    }

    withdraw(amount) {
        if (amount > 0 && amount <= this.balance) {
            this.balance -= amount;
            return true;
        }
        return false;
    }

    getBalance() {
        return this.balance;
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (quantity > 0) {
            if (this.items[item]) {
                this.items[item] += quantity;
            } else {
                this.items[item] = quantity;
            }
            return true;
        }
        return false;
    }

    removeItem(item, quantity = 1) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    getItemQuantity(item) {
        return this.items[item] || 0;
    }

    getInventory() {
        return { ...this.items };
    }
}

class Shop {
    constructor(prices, wallet, inventory) {
        this.prices = prices;
        this.wallet = wallet;
        this.inventory = inventory;
    }

    buyItem(item) {
        const price = this.prices[item];
        if (price && this.wallet.withdraw(price)) {
            this.inventory.addItem(item);
            return true;
        }
        return false;
    }

    sellItem(item) {
        const price = this.prices[item];
        if (price && this.inventory.removeItem(item)) {
            this.wallet.deposit(price);
            return true;
        }
        return false;
    }

    getItemPrice(item) {
        return this.prices[item] || null;
    }
}

