class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
    this.balance = 0;
  }

  purchase(item) {
    const price = this.pricing.getPrice(item);
    const demand = this.demand.getDemand(item);

    if (this.balance >= price && demand > 0) {
      this.balance -= price;
      this.demand.setDemand(item, demand - 1);
      if (this.inventory[item]) {
        this.inventory[item]++;
      } else {
        this.inventory[item] = 1;
      }
      console.log(`Purchased ${item} for $${price}. Remaining balance: $${this.balance}`);
    } else {
      console.log(`Insufficient funds or demand for ${item}`);
    }
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited $${amount}. New balance: $${this.balance}`);
  }

  getInventory() {
    return this.inventory;
  }
}

