class TradeSystem {
    constructor() {
        this.trades = {};
    }

    recordTrade(factionA, factionB, resource, amount) {
        if (!this.trades[factionA]) this.trades[factionA] = {};
        if (!this.trades[factionB]) this.trades[factionB] = {};
        this.trades[factionA][factionB] = (this.trades[factionA][factionB] || 0) + amount;
        this.trades[factionB][factionA] = (this.trades[factionB][factionA] || 0) - amount;
    }

    getTradeHistory(faction) {
        return this.trades[faction] || {};
    }
}

class ReputationSystem {
    constructor() {
        this.reputations = {};
    }

    updateReputation(factionA, factionB, change) {
        if (!this.reputations[factionA]) this.reputations[factionA] = {};
        this.reputations[factionA][factionB] = (this.reputations[factionA][factionB] || 0) + change;
    }

    getReputation(factionA, factionB) {
        return this.reputations[factionA]?.[factionB] || 0;
    }
}

class FactionSystem {
    constructor(tradeSystem, reputationSystem) {
        this.tradeSystem = tradeSystem;
        this.reputationSystem = reputationSystem;
    }

    tradeResources(factionA, factionB, resource, amount) {
        this.tradeSystem.recordTrade(factionA, factionB, resource, amount);
        const reputationChange = amount > 0 ? 1 : -1;
        this.reputationSystem.updateReputation(factionA, factionB, reputationChange);
        this.reputationSystem.updateReputation(factionB, factionA, -reputationChange);
    }

    getTradeHistory(faction) {
        return this.tradeSystem.getTradeHistory(faction);
    }

    getReputation(factionA, factionB) {
        return this.reputationSystem.getReputation(factionA, factionB);
    }
}

