class FactionSystem {
  constructor() {
    this.factions = {};
  }

  addFaction(name, startingReputation = 0) {
    this.factions[name] = startingReputation;
    console.log(`Added faction ${name} with reputation ${startingReputation}`);
  }

  updateFactionReputation(faction, amount) {
    if (this.factions[faction] !== undefined) {
      this.factions[faction] += amount;
      console.log(`Updated ${faction} reputation by ${amount}`);
    } else {
      console.log(`Faction ${faction} does not exist`);
    }
  }

  getFactionReputation(faction) {
