class GameCoordinator {
  constructor() {
    this.tradeSystem = new TradeSystem();
    this.reputationSystem = new ReputationSystem();
    this.factionSystem = new FactionSystem();
  }

  performTrade(item, quantity, price, faction) {
    const transaction = this.tradeSystem.trade(item, quantity, price, faction);
    this.factionSystem.updateFactionReputation(faction, price);
  }

  updateReputation(amount) {
    if (amount > 0) {
      this.reputationSystem.gainReputation(amount);
    } else {
      this.reputationSystem.loseReputation(Math.abs(amount));
    }
  }

  addFaction(name, startingReputation) {
    this.factionSystem.addFaction(name, startingReputation);
  }

  getTransactionHistory() {
    return this.tradeSystem.getTransactionHistory();
  }

  getReputation() {
    return this.reputationSystem.getReputation();
  }

  getFactionReputation(faction) {
    return this.factionSystem.getFactionReputation(faction);
  }
}

