class Crafting {
    constructor(recipes) {
        this.recipes = new Map();
        recipes.forEach(recipe => {
            this.recipes.set(recipe.getItem(), recipe);
        });
    }

    canCraft(item, inventory) {
        const recipe = this.recipes.get(item);
        if (!recipe) return false;
        const ingredients = recipe.getIngredients();
        for (let [ingredient, amount] of Object.entries(ingredients)) {
            if (inventory.getAmount(ingredient) < amount) {
                return false;
            }
        }
        return true;
    }

    craft(item, inventory) {
        const recipe = this.recipes.get(item);
        if (!recipe) throw new Error("Item cannot be crafted.");
        const ingredients = recipe.getIngredients();
        for (let [ingredient, amount] of Object.entries(ingredients)) {
            inventory.decreaseAmount(ingredient, amount);
        }
        inventory.addItem(item, 1);
    }
}

