        this.items = new Map();
    }

    addItem(item, amount) {
        this.items.set(item, (this.items.get(item) || 0) + amount);
    }

    removeItem(item, amount) {
        if (this.items.get(item) < amount) {
            throw new Error("Not enough items to remove.");
        }
        this.items.set(item, this.items.get(item) - amount);
    }

    getAmount(item) {
        return this.items.get(item) || 0;
    }

    decreaseAmount(item, amount) {
        this.removeItem(item, amount);
    }
}

