class EventBus {
    constructor() {
        this.listeners = {};
    }

    subscribe(event, listener) {
        if (!this.listeners[event]) {
            this.listeners[event] = [];
        }
        this.listeners[event].push(listener);
    }

    emit(event, data) {
        if (this.listeners[event]) {
            this.listeners[event].forEach(listener => listener(data));
        }
    }
}

class Bank {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.balance = 0;
        this.eventBus.subscribe('deposit', this.deposit.bind(this));
        this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            console.log(`Deposited: ${amount}, New Balance: ${this.balance}`);
        }
    }

    withdraw(amount) {
        if (amount > 0 && amount <= this.balance) {
            this.balance -= amount;
            console.log(`Withdrew: ${amount}, New Balance: ${this.balance}`);
        }
    }
}

class Market {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.prices = {
            apple: 1,
            banana: 2,
            carrot: 3
        };
        this.eventBus.subscribe('buy', this.buy.bind(this));
    }

    buy(item, quantity) {
        if (this.prices[item] !== undefined && quantity > 0) {
            const totalCost = this.prices[item] * quantity;
            this.eventBus.emit('withdraw', totalCost);
            this.eventBus.emit('addToInventory', { item, quantity });
            console.log(`Bought ${quantity} ${item}(s) for ${totalCost}`);
        }
    }
}

class Inventory {
    constructor(eventBus) {
        this.eventBus = eventBus;
        this.items = {};
        this.eventBus.subscribe('addToInventory', this.addToInventory.bind(this));
    }

    addToInventory({ item, quantity }) {
        if (quantity > 0) {
            if (this.items[item]) {
                this.items[item] += quantity;
            } else {
                this.items[item] = quantity;
            }
            console.log(`Added ${quantity} ${item}(s) to inventory`);
        }
    }
}

