class Building {
  constructor(resourceSystem) {
    this.resourceSystem = resourceSystem;
    this.buildings = {};
  }

  build(buildingType, cost) {
    if (this.resourceSystem.canAfford(cost)) {
      this.resourceSystem.spend(cost);
      if (this.buildings[buildingType]) {
        this.buildings[buildingType]++;
      } else {
        this.buildings[buildingType] = 1;
      }
      console.log(`Built 1 ${buildingType}. Total: ${this.buildings[buildingType]}`);
      return true;
    } else {
      console.log(`Not enough resources to build ${buildingType}.`);
      return false;
    }
  }

  getBuildingCount(buildingType) {
    return this.buildings[buildingType] || 0;
  }
}

class Resource {
  constructor(initialResources = {}) {
    this.resources = initialResources;
  }

  canAfford(cost) {
    for (const resource in cost) {
      if (!this.resources[resource] || this.resources[resource] < cost[resource]) {
        return false;
      }
    }
    return true;
  }

  spend(cost) {
    for (const resource in cost) {
      this.resources[resource] -= cost[resource];
    }
  }

  getResources() {
    return { ...this.resources };
  }
}

class Economy {
  constructor(resourceSystem) {
    this.resourceSystem = resourceSystem;
  }

  generateIncome(income) {
    for (const resource in income) {
      if (this.resourceSystem.resources[resource]) {
        this.resourceSystem.resources[resource] += income[resource];
      } else {
        this.resourceSystem.resources[resource] = income[resource];
      }
    }
    console.log(`Income generated:`, this.resourceSystem.getResources());
  }
}

