class Building {
    constructor(resources) {
        this.resources = resources;
    }

    build(type, cost) {
        if (this.resources.hasEnough(cost)) {
            this.resources.spend(cost);
            console.log(`Building ${type} completed.`);
            return true;
        } else {
            console.log(`Not enough resources to build ${type}.`);
            return false;
        }
    }
}

class Resource {
    constructor(initialResources) {
        this.resources = initialResources;
    }

    hasEnough(cost) {
        for (let [resource, amount] of Object.entries(cost)) {
            if (!this.resources[resource] || this.resources[resource] < amount) {
                return false;
            }
        }
        return true;
    }

    spend(cost) {
        for (let [resource, amount] of Object.entries(cost)) {
            this.resources[resource] -= amount;
        }
    }

    getAvailableResources() {
        return { ...this.resources };
    }
}

class Economy {
    constructor(building, initialPrices) {
        this.building = building;
        this.prices = initialPrices;
    }

    buyBuilding(type) {
        if (this.prices[type]) {
            const cost = this.prices[type];
            return this.building.build(type, cost);
        } else {
            console.log(`Building type ${type} not available.`);
            return false;
        }
    }

    updatePrices(newPrices) {
        this.prices = { ...this.prices, ...newPrices };
    }
}

