    this.quantity = quantity;
  }

  consume(amount) {
    if (this.quantity >= amount) {
      this.quantity -= amount;
      console.log(`Consumed ${amount} ${this.name}, remaining: ${this.quantity}`);
      return true;
    } else {
      console.log(`Not enough ${this.name} to consume ${amount}`);
