class Economy {
  constructor(resources = {}) {
    this.resources = resources;
  }

  canAfford(building) {
    for (const [resourceName, amount] of Object.entries(building.resourceCosts)) {
      if (!this.resources[resourceName] || this.resources[resourceName].quantity < amount) {
        console.log(`Cannot afford to build ${building.name}: not enough ${resourceName}`);
        return false;
      }
    }
    return true;
  }

  buildBuilding(building) {
    if (this.canAfford(building)) {
      for (const [resourceName, amount] of Object.entries(building.resourceCosts)) {
        this.resources[resourceName].consume(amount);
      }
      console.log(`Successfully built ${building.name}`);
    }
  }

  addResource(resource) {
    this.resources[resource.name] = resource;
    console.log(`Added resource ${resource.name} with quantity ${resource.quantity}`);
  }
}

