  constructor(crop) {
    this.crop = crop;
    this.crops = [];
  }

  plant() {
    this.crops.push(new Crop(this.crop.name, this.crop.price, this.crop.growthRate));
  }

  growAll() {
    this.crops.forEach(crop => crop.grow());
  }

  harvestAll() {
    const totalValue = this.crops.reduce((total, crop) => total + crop.getHarvestValue(), 0);
    this.crops = [];
    return totalValue;
  }
}

class Market {
  constructor() {
    this.inventory = {};
  }

  sellCrop(crop, quantity, pricePerUnit) {
    if (this.inventory[crop.name]) {
      this.inventory[crop.name].quantity += quantity;
      this.inventory[crop.name].totalValue += quantity * pricePerUnit;
    } else {
      this.inventory[crop.name] = { quantity, totalValue: quantity * pricePerUnit };
    }
  }

  getInventoryValue() {
    return Object.values(this.inventory).reduce((total, item) => total + item.totalValue, 0);
  }
}

