class Economy {
  constructor(initialBalance) {
    this.balance = initialBalance;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
  }

  credit(amount) {
    this.balance += amount;
  }

  getBalance() {
    return this.balance;
  }
}

class Store {
  constructor(economy, rarityTable) {
    this.economy = economy;
    this.rarityTable = rarityTable;
  }

  purchaseItem() {
    const loot = this.rarityTable.generateLoot();
    const price = loot.getValue();
    this.economy.debit(price);
    return loot;
  }
}

