class Recipe {
    constructor(name, ingredients) {
        this.name = name;
        this.ingredients = ingredients;
    }
}

class Inventory {
    constructor() {
        this.items = new Map();
    }

    addItem(item, quantity = 1) {
        this.items.set(item, (this.items.get(item) || 0) + quantity);
    }

    removeItem(item, quantity = 1) {
        if (this.items.has(item)) {
            const currentQuantity = this.items.get(item);
            if (currentQuantity >= quantity) {
                this.items.set(item, currentQuantity - quantity);
                if (this.items.get(item) === 0) {
                    this.items.delete(item);
                }
                return true;
            }
        }
        return false;
    }

    hasIngredients(recipe) {
        return recipe.ingredients.every(([item, quantity]) => this.items.get(item) >= quantity);
    }

    getInventory() {
        return new Map(this.items);
    }
}

class Crafting {
    constructor(inventory) {
        this.inventory = inventory;
        this.recipes = new Map();
    }

    addRecipe(recipe) {
        this.recipes.set(recipe.name, recipe);
    }

    canCraft(recipeName) {
        const recipe = this.recipes.get(recipeName);
        if (recipe) {
            return this.inventory.hasIngredients(recipe);
        }
        return false;
    }

    craft(recipeName) {
        const recipe = this.recipes.get(recipeName);
        if (recipe && this.inventory.hasIngredients(recipe)) {
            recipe.ingredients.forEach(([item, quantity]) => {
                this.inventory.removeItem(item, quantity);
            });
            console.log(`Crafted: ${recipeName}`);
            return true;
        }
        console.log(`Cannot craft: ${recipeName}`);
        return false;
    }
}

