class Crop {
    constructor(name, growthRate) {
        this.name = name;
        this.growthRate = growthRate; // growth in units per day
        this.currentGrowth = 0;
    }

    grow(days) {
        this.currentGrowth += this.growthRate * days;
    }

    getHarvestable() {
        return this.currentGrowth >= 100; // Assume 100 units are needed for harvest
    }

    harvest() {
        if (this.getHarvestable()) {
            const harvestAmount = this.currentGrowth;
            this.currentGrowth = 0;
            return harvestAmount;
        }
        return 0;
    }
}

// Farm class
class Farm {
    constructor(market) {
        this.market = market;
        this.crops = [];
    }

    plantCrop(name, growthRate) {
        this.crops.push(new Crop(name, growthRate));
    }

    growCrops(days) {
        this.crops.forEach(crop => crop.grow(days));
    }

    sellHarvest() {
        let totalSold = 0;
        this.crops.forEach(crop => {
            if (crop.getHarvestable()) {
                const harvestAmount = crop.harvest();
                totalSold += this.market.sellCrop(crop.name, harvestAmount);
            }
        });
        return totalSold;
    }
}

// Market class
class Market {
    constructor() {
        this.prices = {
            wheat: 1.5,
            corn: 2.0
        };
    }

    sellCrop(name, amount) {
        if (this.prices[name]) {
            const price = this.prices[name];
            const earnings = amount * price;
            console.log(`Sold ${amount} units of ${name} for ${earnings} gold.`);
            return earnings;
        }
        console.log(`No price for ${name}.`);
        return 0;
    }
}

