class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

class Shop {
  constructor(items = {}) {
    this.items = items; // { itemName: price }
  }

  getItemPrice(itemName) {
    return this.items[itemName] || null;
  }

  listItems() {
    return Object.keys(this.items);
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(itemName, quantity = 1) {
    if (quantity > 0) {
      this.items[itemName] = (this.items[itemName] || 0) + quantity;
    }
  }

  removeItem(itemName, quantity = 1) {
    if (this.items[itemName] && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return { ...this.items };
  }
}

class Coordinator {
  constructor(wallet, shop, inventory) {
    this.wallet = wallet;
    this.shop = shop;
    this.inventory = inventory;
  }

  buyItem(itemName) {
    const price = this.shop.getItemPrice(itemName);
    if (price !== null && this.wallet.withdraw(price)) {
      this.inventory.addItem(itemName);
      console.log(`Bought ${itemName} for ${price}.`);
