class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
  }

  credit(amount) {
    this.balance += amount;
  }
}

class Shop {
  constructor(prices) {
    this.prices = prices;
  }

  getPrice(item) {
    return this.prices[item] || null;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Economy {
  constructor(prices) {
    this.prices = prices;
    this.wallet = new Wallet();
  }

  setInitialBalance(amount) {
    this.wallet.credit(amount);
  }

  buyItem(item, shop) {
    const price = shop.getPrice(item);
    if (!price) {
      throw new Error("Item not available");
    }
    this.wallet.debit(price);
    return { price, item };
  }
}

