class Recipe {
    constructor(name, ingredients, result) {
        this.name = name;
        this.ingredients = ingredients; // { ingredient1: quantity, ingredient2: quantity, ... }
        this.result = result; // { item: quantity }
    }

    canCraft(inventory) {
        for (const [ingredient, quantity] of Object.entries(this.ingredients)) {
            if ((inventory.get(ingredient) || 0) < quantity) {
                return false;
            }
        }
        return true;
    }

    craft(inventory) {
        for (const [ingredient, quantity] of Object.entries(this.ingredients)) {
            inventory.set(ingredient, (inventory.get(ingredient) || 0) - quantity);
        }
        for (const [item, quantity] of Object.entries(this.result)) {
            inventory.set(item, (inventory.get(item) || 0) + quantity);
        }
    }
}

class Inventory {
    constructor() {
        this.items = new Map();
    }

    get(item) {
        return this.items.get(item) || 0;
    }

    set(item, quantity) {
        this.items.set(item, quantity);
    }

    display() {
        const inventoryList = Array.from(this.items.entries())
            .map(([item, quantity]) => `${item}: ${quantity}`)
            .join(', ');
        return `Inventory: ${inventoryList}`;
    }
}

class Crafting {
    constructor() {
        this.recipes = [];
    }

    addRecipe(recipe) {
        this.recipes.push(recipe);
    }

    craftRecipe(name, inventory) {
        const recipe = this.recipes.find(r => r.name === name);
        if (recipe && recipe.canCraft(inventory)) {
            recipe.craft(inventory);
            return true;
        }
        return false;
    }

    listRecipes() {
        return this.recipes.map(recipe => recipe.name).join(', ') || 'No recipes available';
    }
}

class GameCoordinator {
    constructor() {
        this.inventory = new Inventory();
        this.crafting = new Crafting();
    }

    initialize() {
        // Add initial items to inventory
        this.inventory.set('wood', 10);
        this.inventory.set('stone', 5);

        // Define and add recipes
        const woodPickaxeRecipe = new Recipe('Wood Pickaxe', { wood: 5 }, { 'pickaxe': 1 });
        const stonePickaxeRecipe = new Recipe('Stone Pickaxe', { stone: 5 }, { 'pickaxe': 1 });
        this.crafting.addRecipe(woodPickaxeRecipe);
        this.crafting.addRecipe(stonePickaxeRecipe);
    }

    craft(itemName) {
        if (this.crafting.craftRecipe(itemName, this.inventory)) {
            console.log(`Crafted ${itemName} successfully!`);
        } else {
            console.log(`Failed to craft ${itemName}.`);
        }
        console.log(this.inventory.display());
    }

    listRecipes() {
        console.log(`Available recipes: ${this.crafting.listRecipes()}`);
    }
}

// Demo
const coordinator = new GameCoordinator();
coordinator.initialize();
coordinator.listRecipes();
coordinator.craft('Wood Pickaxe');
coordinator.craft('Stone Pickaxe');
coordinator.craft('Wood Pickaxe');
