class EventBus {
  constructor() {
    this.listeners = {};
  }

  subscribe(event, listener) {
    if (!this.listeners[event]) {
      this.listeners[event] = [];
    }
    this.listeners[event].push(listener);
  }

  emit(event, data) {
    if (this.listeners[event]) {
      this.listeners[event].forEach(listener => listener(data));
    }
  }
}

class Trade {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemTraded', this.onItemTraded.bind(this));
  }

  tradeItem(item, buyer, seller) {
    console.log(`${buyer} traded ${item} with ${seller}`);
    this.eventBus.emit('itemTraded', { item, buyer, seller });
  }

  onItemTraded(data) {
    console.log(`Trade system received item traded event: ${data.buyer} traded ${data.item} with ${data.seller}`);
  }
}

class Reputation {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.reputations = {};
    this.eventBus.subscribe('itemTraded', this.onItemTraded.bind(this));
  }

  updateReputation(person, change) {
    this.reputations[person] = (this.reputations[person] || 0) + change;
    console.log(`${person}'s reputation is now ${this.reputations[person]}`);
  }

  onItemTraded(data) {
    console.log(`Reputation system received item traded event: ${data.buyer} traded ${data.item} with ${data.seller}`);
    this.updateReputation(data.buyer, 1);
    this.updateReputation(data.seller, 1);
  }
}

class Faction {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.factions = { 'Trader': new Set(), 'Merchant': new Set() };
    this.eventBus.subscribe('itemTraded', this.onItemTraded.bind(this));
  }

  joinFaction(person, faction) {
    if (!this.factions[faction]) {
      this.factions[faction] = new Set();
    }
    this.factions[faction].add(person);
    console.log(`${person} joined faction ${faction}`);
  }

  onItemTraded(data) {
    console.log(`Faction system received item traded event: ${data.buyer} traded ${data.item} with ${data.seller}`);
    this.joinFaction(data.buyer, 'Trader');
    this.joinFaction(data.seller, 'Merchant');
  }
}

