class RarityTable {
  constructor() {
    this.rarityDistribution = {
      common: 0.6,
      uncommon: 0.3,
      rare: 0.1
    };
  }

  getRandomLoot() {
    const rarity = this._determineRarity();
    const itemName = this._generateItemName(rarity);
    return new Loot(itemName, rarity);
  }

  _determineRarity() {
    const random = Math.random();
    if (random < this.rarityDistribution.common) {
      return 'common';
    } else if (random < this.rarityDistribution.common + this.rarityDistribution.uncommon) {
      return 'uncommon';
    } else {
      return 'rare';
    }
  }

  _generateItemName(rarity) {
    const itemTemplates = {
      common: ['Potion', 'Stick', 'Rock'],
      uncommon: ['Sword', 'Shield', 'Map'],
      rare: ['Golden Coin', 'Ancient Amulet', 'Enchanted Blade']
    };
    const items = itemTemplates[rarity];
    return items[Math.floor(Math.random() * items.length)];
  }
}

