    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('itemAdded', this.onItemAdded.bind(this));
    this.eventBus.subscribe('itemUsed', this.onItemUsed.bind(this));
  }

  addItem(item, quantity) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
    this.eventBus.emit('itemAdded', { item, quantity });
  }

  useItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      this.eventBus.emit('itemUsed', { item, quantity });
    } else {
      console.log(`Not enough ${item} in inventory.`);
    }
  }

  getInventory() {
    return this.items;
  }

  onItemAdded({ item, quantity }) {
    console.log(`Added ${quantity} ${item}(s). Current inventory:`, this.getInventory());
  }

  onItemUsed({ item, quantity }) {
    console.log(`Used ${quantity} ${item}(s). Current inventory:`, this.getInventory());
  }
}

class Recipe {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = {};
    this.eventBus.subscribe('craftItem', this.onCraftItem.bind(this));
  }

  addRecipe(name, ingredients) {
    this.recipes[name] = ingredients;
  }

  craft(name) {
    if (this.recipes[name]) {
      const ingredients = this.recipes[name];
      this.eventBus.emit('craftItem', { name, ingredients });
    } else {
      console.log(`No recipe found for ${name}.`);
    }
  }

  onCraftItem({ name, ingredients }) {
    const canCraft = Object.keys(ingredients).every(ingredient => {
      return ingredients[ingredient] <= this.eventBus.emit('getIngredientCount', ingredient);
    });

    if (canCraft) {
      Object.keys(ingredients).forEach(ingredient => {
        this.eventBus.emit('useItem', { item: ingredient, quantity: ingredients[ingredient] });
      });
      console.log(`${name} crafted successfully.`);
    } else {
      console.log(`Missing ingredients to craft ${name}.`);
    }
  }
}

