class Hunger {
  constructor() {
    this.level = 100;
  }

  eat(amount) {
    this.level = Math.min(100, this.level + amount);
  }

  getLevel() {
    return this.level;
  }

  consume(amount) {
    this.level = Math.max(0, this.level - amount);
    return this.level <= 0;
  }
}

class Energy {
  constructor() {
    this.level = 100;
  }

  rest(amount) {
    this.level = Math.min(100, this.level + amount);
  }

  getLevel() {
    return this.level;
  }

  expend(amount) {
    this.level = Math.max(0, this.level - amount);
    return this.level <= 0;
  }
}

class Clock {
  constructor() {
    this.time = 0;
  }

