class Loot {
    constructor() {
        this.lootTable = {
            common: ['Potion', 'Coin', 'Stick'],
            rare: ['Sword', 'Shield', 'Ring'],
            epic: ['Magic Sword', 'Elixir', 'Dragon Scale']
        };
    }

    getRandomLoot(rarity) {
        const lootList = this.lootTable[rarity] || [];
        const randomIndex = Math.floor(Math.random() * lootList.length);
        return lootList[randomIndex];
    }
}

class RarityTable {
    constructor() {
        this.rarityWeights = {
            common: 0.7,
            rare: 0.2,
            epic: 0.1
        };
    }

    getRandomRarity() {
        const roll = Math.random();
        let cumulativeProbability = 0;

        for (const [rarity, weight] of Object.entries(this.rarityWeights)) {
            cumulativeProbability += weight;
            if (roll <= cumulativeProbability) {
                return rarity;
            }
        }

        return 'common'; // Default to common if something goes wrong
    }
}

