  }

  debit(amount) {
    if (this.currency >= amount) {
      this.currency -= amount;
      console.log(`Debited ${amount} currency. Remaining: ${this.currency}`);
    } else {
      console.log('Insufficient currency for transaction.');
    }
  }

  credit(amount) {
    this.currency = (this.currency || 0) + amount;
    console.log(`Credited ${amount} currency. Total: ${this.currency}`);
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }
