    this.items = {};
  }

  addItem(item, quantity) {
    this.items[item] = (this.items[item] || 0) + quantity;
    console.log(`Added ${quantity} ${item}(s) to inventory. Total: ${this.items[item]}`);
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Store {
  constructor(economy, inventory) {
    this.economy = economy;
    this.inventory = inventory;
  }

  purchaseItem(item) {
    const price = this.economy.getPrice(item);
    if (price > 0) {
      this.economy.debit(price);
      this.inventory.addItem(item, 1);
    } else {
      console.log(`Item ${item} not available or no price set.`);
    }
  }
}

class Crafting {
  constructor(recipes, inventory) {
    this.recipes = recipes;
    this.inventory = inventory;
  }

  craftItem(item) {
    const recipe = this.recipes[item];
    if (recipe) {
      const canCraft = Object.keys(recipe).every(ingredient => 
        this.inventory.getItemCount(ingredient) >= recipe[ingredient]
      );
      if (canCraft) {
        Object.keys(recipe).forEach(ingredient => 
          this.inventory.addItem(ingredient, -recipe[ingredient])
        );
        this.inventory.addItem(item, 1);
        console.log(`Crafted ${item}.`);
      } else {
        console.log(`Insufficient ingredients to craft ${item}.`);
      }
    } else {
      console.log(`Recipe for ${item} not found.`);
    }
  }
}

