class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    this.balance += amount;
  }

  withdraw(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(bank) {
    this.bank = bank;
    this.prices = {
      apple: 1,
      banana: 2,
      orange: 3
    };
  }

  buy(item, quantity) {
    const price = this.prices[item] * quantity;
    if (this.bank.withdraw(price)) {
      console.log(`Bought ${quantity} ${item}(s) for ${price}`);
      return true;
    }
    console.log(`Insufficient funds to buy ${quantity} ${item}(s)`);
    return false;
  }

  sell(item, quantity) {
    const price = this.prices[item] * quantity;
    this.bank.deposit(price);
    console.log(`Sold ${quantity} ${item}(s) for ${price}`);
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getInventory() {
    return this.items;
  }
}

