    constructor(prices = {}) {
        this.prices = prices; // prices is an object where key is item name and value is price
    }

    getItemPrice(item) {
        return this.prices[item] || null;
    }

    setItemPrice(item, price) {
        if (price >= 0) {
            this.prices[item] = price;
            return true;
        }
        return false;
    }
}

// Inventory System
class Inventory {
    constructor() {
        this.items = {}; // items is an object where key is item name and value is quantity
    }

    addItem(item, quantity) {
        if (quantity > 0) {
            this.items[item] = (this.items[item] || 0) + quantity;
            return true;
        }
        return false;
    }

    removeItem(item, quantity) {
        if (quantity > 0 && this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            return true;
        }
        return false;
    }

    getItemCount(item) {
        return this.items[item] || 0;
    }
}

