// Wallet System
class Wallet {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('purchaseMade', this.handlePurchase.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Deposited: $${amount}, New Balance: $${this.balance}`);
  }

  withdraw(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew: $${amount}, New Balance: $${this.balance}`);
    } else {
      console.log('Insufficient funds');
    }
  }

  handlePurchase(data) {
    if (data.price <= this.balance) {
      this.withdraw(data.price);
