class RarityTable {
    constructor(rarityLevels) {
        this.rarityLevels = rarityLevels;
    }

    rollRarity() {
        const totalWeight = Object.values(this.rarityLevels).reduce((sum, weight) => sum + weight, 0);
        const randomWeight = Math.random() * totalWeight;
        let cumulativeWeight = 0;

        for (const [rarity, weight] of Object.entries(this.rarityLevels)) {
            cumulativeWeight += weight;
            if (randomWeight < cumulativeWeight) {
                return rarity;
            }
        }

        throw new Error("Failed to roll rarity");
    }
}

