class Building {
  constructor(name, resources) {
    this.name = name;
    this.resources = resources; // { type: amount }
  }

  getName() {
    return this.name;
  }

  getResources() {
    return this.resources;
  }

  consumeResource(type, amount) {
    if (this.resources[type] >= amount) {
      this.resources[type] -= amount;
      return true;
    }
    return false;
  }

  produceResource(type, amount) {
    if (this.resources[type] === undefined) {
      this.resources[type] = 0;
    }
    this.resources[type] += amount;
  }
}

class Resource {
  constructor(type, initialAmount) {
    this.type = type;
    this.amount = initialAmount;
  }

  getType() {
    return this.type;
  }

  getAmount() {
    return this.amount;
  }

  consume(amount) {
    if (this.amount >= amount) {
      this.amount -= amount;
      return true;
    }
    return false;
  }

  produce(amount) {
    this.amount += amount;
  }
}

class Economy {
  constructor(building, resource) {
    this.building = building;
    this.resource = resource;
  }

  tradeResource(buildingType, resourceType, amount) {
    if (this.building.getName() === buildingType && this.resource.getType() === resourceType) {
      if (this.resource.consume(amount)) {
        this.building.produceResource(resourceType, amount);
        return true;
      }
    }
    return false;
  }

  checkResourceAmount() {
    return this.resource.getAmount();
  }

  checkBuildingResources() {
    return this.building.getResources();
  }
}

// Demo
