class Economy {
  constructor() {
    this.balance = 0;
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    this.balance += amount;
  }

  withdraw(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
  }
}

class Store {
  constructor() {
    this.items = {
      bread: { price: 2, stock: 10 },
      milk: { price: 3, stock: 5 },
      cheese: { price: 5, stock: 8 }
    };
  }

  getItemPrice(item) {
    return this.items[item]?.price || 0;
  }

  getItemStock(item) {
    return this.items[item]?.stock || 0;
  }

  purchase(item, quantity) {
    const price = this.getItemPrice(item);
    const stock = this.getItemStock(item);

    if (quantity > stock) {
      throw new Error("Insufficient stock");
    }

    return price * quantity;
  }
}

class Inventory {
  constructor() {
    this.contents = {};
  }

  addItem(item, quantity) {
    if (this.contents[item]) {
      this.contents[item] += quantity;
    } else {
      this.contents[item] = quantity;
    }
  }

  getItemCount(item) {
    return this.contents[item] || 0;
  }
}

class GameCoordinator {
  constructor() {
    this.economy = new Economy();
    this.store = new Store();
    this.inventory = new Inventory();
  }

  buyItem(item, quantity) {
    try {
      const cost = this.store.purchase(item, quantity);
      this.economy.withdraw(cost);
      this.inventory.addItem(item, quantity);
      console.log(`Purchased ${quantity} ${item}(s) for $${cost}. Balance: $${this.economy.getBalance()}`);
    } catch (error) {
      console.error(error.message);
    }
  }

  checkInventory() {
    console.log("Inventory:");
    for (const [item, quantity] of Object.entries(this.inventory.contents)) {
      console.log(`${item}: ${quantity}`);
    }
  }
}

