class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: quantity }
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return this.ingredients;
  }
}

class Inventory {
  constructor() {
    this.items = {}; // { itemName: quantity }
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  getItems() {
    return this.items;
  }
}

class Crafting {
  constructor(inventory, recipes) {
    this.inventory = inventory;
    this.recipes = recipes; // Array of Recipe instances
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe) return false;

    const ingredients = recipe.getIngredients();
    for (const [ingredient, quantity] of Object.entries(ingredients)) {
      if (this.inventory.getItems()[ingredient] < quantity) {
        return false;
      }
    }
    return true;
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.getName() === recipeName);
    if (!recipe) return false;

    const ingredients = recipe.getIngredients();
    for (const [ingredient, quantity] of Object.entries(ingredients)) {
      if (!this.inventory.removeItem(ingredient, quantity)) {
        return false;
      }
    }

    // Assuming crafting the recipe results in an item named after the recipe
    this.inventory.addItem(recipeName, 1);
    return true;
  }
}

