class Bank {
    constructor() {
        this.balance = 0;
    }

    deposit(amount) {
        if (amount > 0) {
            this.balance += amount;
            console.log(`Deposited ${amount}. New balance: ${this.balance}`);
        } else {
            console.log('Deposit amount must be positive.');
        }
    }

    withdraw(amount) {
        if (amount > 0 && amount <= this.balance) {
            this.balance -= amount;
            console.log(`Withdrew ${amount}. New balance: ${this.balance}`);
        } else {
            console.log('Insufficient funds or invalid amount.');
        }
    }

    getBalance() {
        return this.balance;
    }
}

class Market {
    constructor(prices) {
        this.prices = prices;
    }

    getPrices() {
        return this.prices;
    }

    buy(item, quantity, bank) {
        const price = this.prices[item];
        if (price !== undefined && quantity > 0) {
            const totalCost = price * quantity;
            if (bank.getBalance() >= totalCost) {
                bank.withdraw(totalCost);
                console.log(`Bought ${quantity} ${item}(s) for ${totalCost}.`);
                return true;
            } else {
                console.log('Insufficient funds to buy item(s).');
                return false;
            }
        } else {
            console.log('Invalid item or quantity.');
            return false;
        }
    }
}

class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity) {
        if (quantity > 0) {
            if (this.items[item]) {
                this.items[item] += quantity;
            } else {
                this.items[item] = quantity;
            }
            console.log(`Added ${quantity} ${item}(s) to inventory.`);
        } else {
            console.log('Quantity must be positive.');
        }
    }

    removeItem(item, quantity) {
        if (this.items[item] && this.items[item] >= quantity) {
            this.items[item] -= quantity;
            if (this.items[item] === 0) {
                delete this.items[item];
            }
            console.log(`Removed ${quantity} ${item}(s) from inventory.`);
        } else {
            console.log('Insufficient inventory to remove item(s).');
        }
    }

    getInventory() {
        return this.items;
    }
}

class Coordinator {
    constructor() {
        this.bank = new Bank();
        this.market = new Market({ apple: 10, banana: 5, carrot: 2 });
        this.inventory = new Inventory();
    }

    performTransaction(item, quantity) {
        const success = this.market.buy(item, quantity, this.bank);
        if (success) {
            this.inventory.addItem(item, quantity);
        }
    }

    displayStatus() {
        console.log('Bank Balance:', this.bank.getBalance());
        console.log('Market Prices:', this.market.getPrices());
        console.log('Inventory:', this.inventory.getInventory());
    }
}

