class Farm {
  constructor() {
    this.crops = [];
  }

  plantCrop(crop) {
    this.crops.push(crop);
  }

  harvest() {
    let totalYield = 0;
    for (const crop of this.crops) {
      totalYield += crop.getYieldPerDay();
    }
    return totalYield;
  }
}

class Market {
  constructor() {
    this.prices = {};
  }

  setPrice(cropName, price) {
    this.prices[cropName] = price;
  }

  getPrice(cropName) {
    return this.prices[cropName] || 0;
  }

  sellCrop(farm, cropName) {
    const crop = farm.crops.find(c => c.getName() === cropName);
    if (crop) {
      const price = this.getPrice(cropName);
      const yieldPerDay = crop.getYieldPerDay();
      const revenue = yieldPerDay * price;
      farm.crops = farm.crops.filter(c => c !== crop);
      return revenue;
    }
    return 0;
  }
}

