        console.log(`Order placed by customer ${customerId}:`, items);
        this.eventBus.emit('orderPlaced', { customerId, items });
    }

    onCustomerOrderReceived(data) {
        const { customerId, items } = data;
        this.placeOrder(customerId, items);
    }
}

class Kitchen {
