class GameCoordinator {
  constructor() {
    this.hunger = new Hunger();
    this.energy = new Energy();
    this.clock = new Clock();
  }

  update() {
    this.clock.tick();
    if (this.clock.getTime() % 4 === 0) {
      this.hunger.consume();
    }
    if (this.clock.getTime() % 6 === 0) {
      this.energy.spend();
    }
  }

