        this.enemies.push({ id: enemyId, health: 100 });
        console.log(`Enemy ${enemyId} added to pool`);
        return enemyId;
    }

    removeEnemy(enemyId) {
        this.enemies = this.enemies.filter(enemy => enemy.id !== enemyId);
        console.log(`Enemy ${enemyId} removed from pool`);
    }

    getEnemyHealth(enemyId) {
