        if (enemy) {
            return enemy.health;
        }
        console.log("Enemy not found");
        return null;
    }

    damageEnemy(enemyId, amount) {
        const enemy = this.enemies.find(enemy => enemy.id === enemyId);
        if (enemy) {
            enemy.health -= amount;
            console.log(`Enemy ${enemyId} damaged, health: ${enemy.health}`);
