      uncommon: { chance: 0.2, value: 50 },
      rare: { chance: 0.09, value: 200 },
      epic: { chance: 0.01, value: 1000 }
    };
  }

  generateLoot() {
    const roll = Math.random();
    let cumulativeChance = 0;

    for (const rarity in this.rarityMap) {
      cumulativeChance += this.rarityMap[rarity].chance;
      if (roll <= cumulativeChance) {
        const { value } = this.rarityMap[rarity];
        return new Loot(`Loot-${rarity}`, value);
      }
    }

    throw new Error("Failed to generate loot");
  }
}

