class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // ingredients is an object where keys are item names and values are required amounts
  }
}

class Inventory {
  constructor() {
    this.items = {}; // items is an object where keys are item names and values are available amounts
  }

  addItem(item, amount) {
    if (this.items[item]) {
      this.items[item] += amount;
    } else {
      this.items[item] = amount;
    }
  }

  removeItem(item, amount) {
    if (this.items[item] && this.items[item] >= amount) {
      this.items[item] -= amount;
      return true;
    }
    return false;
  }

  hasIngredients(recipe) {
    for (let [item, amount] of Object.entries(recipe.ingredients)) {
      if (!this.items[item] || this.items[item] < amount) {
        return false;
      }
    }
    return true;
  }
}

class Crafting {
  constructor(inventory) {
    this.inventory = inventory;
    this.recipes = []; // recipes is an array of Recipe instances
  }

  addRecipe(recipe) {
    this.recipes.push(recipe);
  }

  canCraft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe) {
      return this.inventory.hasIngredients(recipe);
    }
    return false;
  }

  craft(recipeName) {
    const recipe = this.recipes.find(r => r.name === recipeName);
    if (recipe && this.inventory.hasIngredients(recipe)) {
      for (let [item, amount] of Object.entries(recipe.ingredients)) {
        this.inventory.removeItem(item, amount);
      }
      console.log(`Crafted: ${recipeName}`);
      return true;
    }
    console.log(`Cannot craft: ${recipeName}`);
    return false;
  }
}

