class Recipe {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.recipes = {
      "wooden_sword": { "wood": 2, "stone": 1 },
      "leather_boots": { "leather": 2 }
    };
    this.eventBus.subscribe('craft', this.handleCraft.bind(this));
  }

  handleCraft(data) {
    const { item } = data;
    const recipe = this.recipes[item];
    if (recipe) {
      this.eventBus.emit('craftRecipe', { item, recipe });
    } else {
      console.log(`Recipe for ${item} not found.`);
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {
      "wood": 10,
      "stone": 5,
      "leather": 8
    };
    this.eventBus.subscribe('craftRecipe', this.handleCraftRecipe.bind(this));
  }

  handleCraftRecipe(data) {
    const { item, recipe } = data;
    const canCraft = Object.keys(recipe).every(ingredient => {
      return this.items[ingredient] >= recipe[ingredient];
    });

    if (canCraft) {
      Object.keys(recipe).forEach(ingredient => {
        this.items[ingredient] -= recipe[ingredient];
      });
      this.eventBus.emit('itemCrafted', { item });
    } else {
      console.log(`Insufficient materials to craft ${item}.`);
    }
  }
}

class Crafting {
