        if (this.inventory[crop.name]) {
            this.inventory[crop.name].quantity += 1;
        } else {
            this.inventory[crop.name] = { crop, quantity: 1, price };
        }
    }

    sellCrop(cropName) {
        if (this.inventory[cropName] && this.inventory[cropName].quantity > 0) {
            this.inventory[cropName].quantity -= 1;
            return this.inventory[cropName].price;
        }
        return null;
    }

    getInventory() {
        return this.inventory;
    }
}

