class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      return true;
    }
    return false;
  }

  hasItems(items) {
    for (const [item, quantity] of Object.entries(items)) {
      if (!this.items[item] || this.items[item] < quantity) {
        return false;
      }
    }
    return true;
  }

  getItems() {
    return this.items;
  }
}

class Crafting {
  constructor() {
    this.recipes = {};
  }

  addRecipe(recipe) {
    this.recipes[recipe.getName()] = recipe;
  }

  canCraft(recipeName) {
    const recipe = this.recipes[recipeName];
    if (!recipe) return false;
    return this.inventory.hasItems(recipe.getIngredients());
  }

  craft(recipeName) {
    const recipe = this.recipes[recipeName];
    if (!recipe) return false;
    if (!this.canCraft(recipeName)) return false;

    for (const [item, quantity] of Object.entries(recipe.getIngredients())) {
      this.inventory.removeItem(item, quantity);
    }

    this.inventory.addItem(recipe.getName());
    return true;
  }

  setInventory(inventory) {
    this.inventory = inventory;
  }
}

