class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
    this.inventory = {};
    this.balance = 1000; // Initial balance for the store
  }

  purchase(item, quantity) {
    const price = this.pricing.getPrice(item);
    const demand = this.demand.getDemand(item);

    if (quantity <= 0 || price <= 0 || demand <= 0) {
      console.log(`Purchase failed for ${item}: Invalid quantity, price, or demand.`);
      return;
    }

    const totalCost = price * quantity;

    if (totalCost > this.balance) {
      console.log(`Purchase failed for ${item}: Insufficient balance.`);
      return;
    }

    if (this.demand.getDemand(item) < quantity) {
      console.log(`Purchase failed for ${item}: Insufficient demand.`);
      return;
    }

    this.balance -= totalCost;
    this.demand.setDemand(item, demand - quantity);
    this.inventory[item] = (this.inventory[item] || 0) + quantity;

    console.log(`Purchased ${quantity} of ${item} for ${totalCost}. Balance: ${this.balance}`);
  }

  getInventory() {
    return this.inventory;
  }

  getBalance() {
    return this.balance;
  }
}

