    this.eventBus = eventBus;
    this.balance = 0;

    this.eventBus.subscribe('sellItem', ({ itemPrice }) => {
      this.balance += itemPrice;
      console.log(`Sold item for ${itemPrice}, new balance: ${this.balance}`);
    });

    this.eventBus.subscribe('buyItem', ({ itemPrice }) => {
      if (this.balance >= itemPrice) {
        this.balance -= itemPrice;
        console.log(`Bought item for ${itemPrice}, new balance: ${this.balance}`);
      } else {
        console.log(`Insufficient balance to buy item for ${itemPrice}`);
      }
    });
  }

  getBalance() {
    return this.balance;
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = [
      { name: 'Sword', price: 50 },
      { name: 'Shield', price: 30 },
      { name: 'Potion', price: 10 }
    ];

    this.eventBus.subscribe('listItems', () => {
      console.log('Available items in store:');
      this.items.forEach(item => console.log(`- ${item.name}: ${item.price}`));
    });
  }

  sellItem(itemName) {
    const item = this.items.find(i => i.name === itemName);
    if (item) {
      this.eventBus.emit('sellItem', { itemPrice: item.price });
    } else {
      console.log(`Item ${itemName} not found in store.`);
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = [];

    this.eventBus.subscribe('buyItem', ({ itemPrice, itemName }) => {
      this.items.push({ name: itemName, price: itemPrice });
      console.log(`Added ${itemName} to inventory.`);
    });
  }

  listInventory() {
    console.log('Inventory:');
    this.items.forEach(item => console.log(`- ${item.name}: ${item.price}`));
  }
}

