class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients; // { ingredientName: amount }
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, amount = 1) {
    if (this.items[item]) {
      this.items[item] += amount;
    } else {
      this.items[item] = amount;
    }
  }

  hasIngredients(recipe) {
    for (const [ingredient, amount] of Object.entries(recipe.ingredients)) {
      if (!this.items[ingredient] || this.items[ingredient] < amount) {
        return false;
      }
    }
    return true;
  }

  consumeIngredients(recipe) {
    for (const [ingredient, amount] of Object.entries(recipe.ingredients)) {
      this.items[ingredient] -= amount;
    }
  }

  getItemAmount(item) {
    return this.items[item] || 0;
  }
}

class Crafting {
  constructor(recipes) {
    this.recipes = recipes; // { recipeName: Recipe }
  }

  canCraft(recipeName) {
    return this.recipes[recipeName] ? true : false;
  }

  craft(recipeName, inventory) {
    const recipe = this.recipes[recipeName];
    if (!recipe) {
      throw new Error(`Recipe ${recipeName} does not exist.`);
    }
    if (!inventory.hasIngredients(recipe)) {
      throw new Error(`Not enough ingredients for ${recipeName}.`);
    }
    inventory.consumeIngredients(recipe);
    inventory.addItem(recipe.name);
    return recipe.name;
  }
}

class Economy {
  constructor(prices) {
    this.prices = prices; // { itemName: price }
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }

  debit(account, amount) {
    if (account.balance < amount) {
      throw new Error(`Insufficient funds: ${account.balance} < ${amount}`);
    }
    account.balance -= amount;
  }
}

class Store {
  constructor(inventory, economy) {
    this.inventory = inventory;
    this.economy = economy;
  }

  purchaseItem(itemName, account) {
    const price = this.economy.getPrice(itemName);
    if (price === 0) {
      throw new Error(`Item ${itemName} is not for sale.`);
    }
    this.economy.debit(account, price);
    this.inventory.addItem(itemName);
    console.log(`Purchased ${itemName} for ${price}. Balance: ${account.balance}`);
  }
}

