class RarityTable {
    constructor() {
        this.table = [
            { rarity: 'common', weight: 50 },
            { rarity: 'uncommon', weight: 30 },
            { rarity: 'rare', weight: 15 },
            { rarity: 'epic', weight: 5 }
        ];
    }

    roll() {
        const totalWeight = this.table.reduce((sum, entry) => sum + entry.weight, 0);
        const rand = Math.random() * totalWeight;
        let cumulativeWeight = 0;

        for (const entry of this.table) {
            cumulativeWeight += entry.weight;
            if (rand < cumulativeWeight) {
                return entry.rarity;
            }
        }

        return 'common'; // Fallback to common if something goes wrong
    }
}

class Inventory {
    constructor() {
        this.items = [];
    }

    addItem(item) {
        this.items.push(item);
    }

    getItems() {
        return this.items;
    }
}

class Store {
    constructor(economy, rarityTable, inventory) {
        this.economy = economy;
        this.rarityTable = rarityTable;
        this.inventory = inventory;
    }

    purchaseItem() {
        const rarity = this.rarityTable.roll();
        const cost = this.economy.getCost(rarity);

        if (this.economy.debit(cost)) {
            this.inventory.addItem({ rarity, cost });
            console.log(`Purchased ${rarity} item for ${cost}. New balance: ${this.economy.getBalance()}`);
            return true;
        } else {
            console.log('Insufficient funds for purchase.');
            return false;
        }
    }
}

