class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }
}

class Economy {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('transaction', this.handleTransaction.bind(this));
  }

  getBalance() {
    return this.balance;
  }

  deposit(amount) {
    this.balance += amount;
    this.eventBus.emit('balanceChanged', { balance: this.balance });
  }

  withdraw(amount) {
    if (amount <= this.balance) {
      this.balance -= amount;
      this.eventBus.emit('balanceChanged', { balance: this.balance });
      return true;
    }
    return false;
  }

  handleTransaction(transaction) {
    if (transaction.type === 'purchase') {
      if (this.withdraw(transaction.amount)) {
        this.eventBus.emit('transactionSuccess', transaction);
      } else {
        this.eventBus.emit('transactionFailure', transaction);
      }
    }
  }
}

class Store {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.inventory = {
      'apple': { price: 10 },
      'banana': { price: 5 }
    };
    this.eventBus.subscribe('buyItem', this.handleBuyItem.bind(this));
  }

  getItemPrice(item) {
    return this.inventory[item] ? this.inventory[item].price : null;
  }

  handleBuyItem(item) {
    const price = this.getItemPrice(item);
    if (price !== null) {
      this.eventBus.emit('transaction', { type: 'purchase', amount: price, item });
    } else {
      console.log(`Item ${item} not found in store.`);
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('transactionSuccess', this.handleTransactionSuccess.bind(this));
  }

  addItem(item, quantity) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
  }

  getInventory() {
    return this.items;
  }

  handleTransactionSuccess(transaction) {
    if (transaction.type === 'purchase') {
      this.addItem(transaction.item, 1);
      console.log(`Purchased ${transaction.item}. Inventory updated:`, this.getInventory());
    }
  }
}

