class Market {
    constructor() {
        this.prices = {};
    }

    setPrice(item, price) {
        if (price >= 0) {
            this.prices[item] = price;
            return true;
        }
        return false;
    }

    getPrice(item) {
        return this.prices[item] !== undefined ? this.prices[item] : null;
    }
}

