    }
}

// Coordinator System
class Coordinator {
    constructor() {
        this.bank = new Bank(100); // Starting with $100
        this.market = new Market();
        this.inventory = new Inventory();
    }

    buyItem(item, quantity) {
        const price = this.market.getPrice(item);
        if (price !== null) {
            const totalCost = price * quantity;
            if (this.bank.withdraw(totalCost)) {
                this.inventory.addItem(item, quantity);
                console.log(`Bought ${quantity} ${item}(s) for $${totalCost}.`);
                return true;
            } else {
                console.log(`Insufficient funds to buy ${quantity} ${item}(s).`);
            }
        } else {
            console.log(`Item ${item} is not available in the market.`);
        }
        return false;
    }

    sellItem(item, quantity) {
        const price = this.market.getPrice(item);
        if (price !== null) {
            const totalRevenue = price * quantity;
            if (this.inventory.removeItem(item, quantity)) {
                this.bank.deposit(totalRevenue);
                console.log(`Sold ${quantity} ${item}(s) for $${totalRevenue}.`);
                return true;
            } else {
                console.log(`Insufficient ${item}(s) in inventory to sell.`);
            }
        } else {
            console.log(`Item ${item} is not available in the market.`);
        }
        return false;
    }

    checkBalance() {
        return this.bank.getBalance();
    }

    checkInventory() {
        return this.inventory.items;
    }

    checkMarket() {
        return this.market.prices;
    }
}

