// Event Bus
class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, listener) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(listener);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(listener => listener(data));
    }
  }
}

// Inventory System
class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemAdded', this.handleItemAdded.bind(this));
    this.eventBus.subscribe('itemUsed', this.handleItemUsed.bind(this));
  }

  addItem(item, quantity) {
    if (!this.items[item]) {
      this.items[item] = 0;
    }
    this.items[item] += quantity;
    this.eventBus.emit('itemAdded', { item, quantity });
  }

  useItem(item, quantity) {
    if (this.items[item] >= quantity) {
      this.items[item] -= quantity;
      this.eventBus.emit('itemUsed', { item, quantity });
    } else {
      console.log(`Not enough ${item} in inventory.`);
    }
  }

  handleItemAdded(data) {
    console.log(`Added ${data.quantity} ${data.item}(s) to inventory.`);
  }

  handleItemUsed(data) {
    console.log(`Used ${data.quantity} ${data.item}(s) from inventory.`);
  }
}

// Crafting System
class Crafting {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemUsed', this.handleItemUsed.bind(this));
  }

  addRecipe(recipeName, ingredients) {
    this.recipes[recipeName] = ingredients;
  }

  craft(recipeName) {
    const ingredients = this.recipes[recipeName];
    if (ingredients) {
      let canCraft = true;
      Object.keys(ingredients).forEach(item => {
        if (this.eventBus.emit('checkItemQuantity', { item }) < ingredients[item]) {
          canCraft = false;
          console.log(`Not enough ${item}(s) to craft ${recipeName}.`);
        }
      });
      if (canCraft) {
        Object.keys(ingredients).forEach(item => {
          this.eventBus.emit('useItem', { item, quantity: ingredients[item] });
        });
        console.log(`${recipeName} crafted successfully.`);
      }
    } else {
      console.log(`No recipe found for ${recipeName}.`);
    }
  }

  handleItemUsed(data) {
    console.log(`Used ${data.quantity} ${data.item}(s) in crafting.`);
  }
}

// Recipe System
class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;
    this.eventBus.subscribe('itemUsed', this.handleItemUsed.bind(this));
  }

  addRecipe(recipeName, ingredients) {
    this.recipes[recipeName] = ingredients;
  }

  getRecipe(recipeName) {
    return this.recipes[recipeName];
  }

  handleItemUsed(data) {
    console.log(`Used ${data.quantity} ${data.item}(s) in recipe.`);
  }
}

