class Building {
  constructor(name, resourceCosts) {
    this.name = name;
    this.resourceCosts = resourceCosts;
  }

  build(economy) {
    if (economy.canAfford(this.resourceCosts)) {
      economy.deductResources(this.resourceCosts);
      console.log(`Built ${this.name}`);
      return true;
    } else {
      console.log(`Cannot build ${this.name}: insufficient resources`);
      return false;
    }
  }
}

class Resource {
  constructor(name, amount) {
    this.name = name;
    this.amount = amount;
  }

  deduct(amount) {
    this.amount -= amount;
    console.log(`Deducted ${amount} ${this.name}, remaining: ${this.amount}`);
  }
}

class Economy {
  constructor(resources) {
    this.resources = new Map();
    resources.forEach(resource => this.resources.set(resource.name, resource));
  }

  canAfford(costs) {
    for (const [resourceName, amount] of Object.entries(costs)) {
      if (this.resources.get(resourceName).amount < amount) {
        return false;
      }
    }
    return true;
  }

  deductResources(costs) {
    for (const [resourceName, amount] of Object.entries(costs)) {
      this.resources.get(resourceName).deduct(amount);
    }
  }
}

