    this.reputations = {};
  }

  updateReputation(partner, points) {
    if (!this.reputations[partner]) {
      this.reputations[partner] = 0;
    }
    this.reputations[partner] += points;
    console.log(`Reputation updated for ${partner}: ${this.reputations[partner]} points`);
