    this.factions = {};
  }

  joinFaction(partner, factionName) {
    if (!this.factions[factionName]) {
      this.factions[factionName] = [];
    }
    this.factions[factionName].push(partner);
    console.log(`${partner} joined faction ${factionName}`);
  }

  getFactionMembers(factionName) {
    return this.factions[factionName] || [];
  }
}

