// Event Bus Implementation
class EventBus {
  constructor() {
    this.events = {};
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(callback => callback(data));
    }
  }

  subscribe(eventName, callback) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(callback);
  }
}

// Combat System
class CombatSystem {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('playerAttack', this.handlePlayerAttack.bind(this));
  }

  handlePlayerAttack(data) {
    console.log(`CombatSystem: Player attacks ${data.target} with ${data.damage} damage.`);
    this.eventBus.emit('damageReceived', { target: data.target, damage: data.damage });
  }

  attack(target, damage) {
    this.eventBus.emit('playerAttack', { target, damage });
  }
}

// Health System
class HealthSystem {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('damageReceived', this.handleDamageReceived.bind(this));
  }

  handleDamageReceived(data) {
    console.log(`HealthSystem: ${data.target} received ${data.damage} damage.`);
    // For simplicity, let's assume the target always has 100 health initially
    const newHealth = 100 - data.damage;
    console.log(`HealthSystem: ${data.target} now has ${newHealth} health.`);
    if (newHealth <= 0) {
      console.log(`HealthSystem: ${data.target} has been defeated.`);
      this.eventBus.emit('entityDefeated', { target: data.target });
    }
  }
}

// Loot System
class LootSystem {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('entityDefeated', this.handleEntityDefeated.bind(this));
  }

