    console.log(`LootSystem: ${data.target} has been defeated. Dropping loot.`);
    const loot = this.generateLoot();
    console.log(`LootSystem: ${data.target} dropped ${loot}`);
  }

  generateLoot() {
    const lootItems = ['Potion', 'Sword', 'Shield', 'Gold'];
    return lootItems[Math.floor(Math.random() * lootItems.length)];
  }
}

