class RarityTable {
  constructor() {
    this.table = {
      common: 0.75,
      uncommon: 0.2,
      rare: 0.04,
      epic: 0.01
    };
  }

  roll() {
    const roll = Math.random();
    let cumulativeProbability = 0;

    for (const [rarity, probability] of Object.entries(this.table)) {
      cumulativeProbability += probability;
      if (roll < cumulativeProbability) {
        return rarity;
      }
    }

    return 'common'; // Default to common if something goes wrong
  }

  getItem() {
    const rarity = this.roll();
    let value;
    switch (rarity) {
      case 'common':
        value = Math.floor(Math.random() * 10) + 1;
        break;
      case 'uncommon':
        value = Math.floor(Math.random() * 20) + 10;
        break;
      case 'rare':
        value = Math.floor(Math.random() * 50) + 20;
        break;
      case 'epic':
        value = Math.floor(Math.random() * 100) + 50;
        break;
      default:
        value = 1;
    }

    return new Loot(`Item-${rarity[0].toUpperCase() + rarity.slice(1)}`, value);
  }
}

