class Combat {
  constructor() {
    this.attacker = null;
    this.defender = null;
  }

  startCombat(attacker, defender) {
    this.attacker = attacker;
    this.defender = defender;
    console.log(`${this.attacker.name} attacks ${this.defender.name}`);
  }

  attack() {
    if (this.attacker && this.defender) {
      const damage = Math.floor(Math.random() * 10) + 1;
      console.log(`${this.attacker.name} deals ${damage} damage to ${this.defender.name}`);
      return damage;
    }
    return 0;
  }
}

class Health {
  constructor(entity) {
    this.entity = entity;
    this.currentHealth = 100;
  }

  takeDamage(damage) {
    this.currentHealth -= damage;
    if (this.currentHealth < 0) {
      this.currentHealth = 0;
    }
    console.log(`${this.entity.name} has ${this.currentHealth} health remaining`);
    if (this.currentHealth === 0) {
      console.log(`${this.entity.name} has been defeated!`);
    }
  }

  isAlive() {
    return this.currentHealth > 0;
  }
}

class Loot {
  constructor() {
    this.lootTable = ['Potion', 'Sword', 'Shield', 'Gold'];
  }

  getRandomLoot() {
    const loot = this.lootTable[Math.floor(Math.random() * this.lootTable.length)];
    console.log(`Looted: ${loot}`);
    return loot;
  }
}

class GameCoordinator {
  constructor() {
    this.combat = new Combat();
    this.loot = new Loot();
  }

  startBattle(attacker, defender) {
    this.combat.startCombat(attacker, defender);
    const attackerHealth = new Health(attacker);
    const defenderHealth = new Health(defender);

    while (attackerHealth.isAlive() && defenderHealth.isAlive()) {
      const damage = this.combat.attack();
      defenderHealth.takeDamage(damage);

      if (defenderHealth.isAlive()) {
        // Defender retaliates
        const returnDamage = this.combat.attack();
        attackerHealth.takeDamage(returnDamage);
      }
    }

    if (!attackerHealth.isAlive()) {
      console.log(`${defender.name} wins!`);
    } else {
      console.log(`${attacker.name} wins!`);
    }

    const winner = attackerHealth.isAlive() ? attacker : defender;
    const loot = this.loot.getRandomLoot();
    console.log(`${winner.name} receives ${loot}`);
  }
}

