class QuestSystem {
    constructor(flagsSystem) {
        this.flagsSystem = flagsSystem;
        this.quests = {};
    }

    addQuest(key, requirements, completionMessage) {
        this.quests[key] = { requirements, completionMessage };
    }

    canCompleteQuest(questKey) {
        const quest = this.quests[questKey];
        if (!quest) return false;
        return quest.requirements.every(flagKey => this.flagsSystem.getFlag(flagKey));
    }

    completeQuest(questKey) {
        if (this.canCompleteQuest(questKey)) {
            const quest = this.quests[questKey];
            console.log(quest.completionMessage);
            return true;
        }
        return false;
    }
}

