// Recipe System
class Recipe {
    constructor(id, ingredients, result) {
        this.id = id;
        this.ingredients = ingredients; // { ingredientId: quantity }
        this.result = result; // { itemId: quantity }
    }

    getId() {
        return this.id;
    }

    getIngredients() {
        return this.ingredients;
    }

    getResult() {
        return this.result;
    }
}

// Inventory System
class Inventory {
    constructor() {
        this.items = {}; // { itemId: quantity }
    }

    addItem(itemId, quantity) {
        if (this.items[itemId]) {
            this.items[itemId] += quantity;
        } else {
            this.items[itemId] = quantity;
        }
    }

    removeItem(itemId, quantity) {
        if (this.items[itemId] && this.items[itemId] >= quantity) {
            this.items[itemId] -= quantity;
            if (this.items[itemId] === 0) {
                delete this.items[itemId];
            }
            return true;
        }
        return false;
    }

    hasItems(neededItems) {
        for (const [itemId, quantity] of Object.entries(neededItems)) {
            if (!this.items[itemId] || this.items[itemId] < quantity) {
                return false;
            }
        }
        return true;
    }

    getItems() {
        return { ...this.items };
    }
}

// Crafting System
class Crafting {
    constructor(inventory, recipes) {
        this.inventory = inventory;
        this.recipes = recipes; // { recipeId: Recipe }
    }

    canCraft(recipeId) {
        const recipe = this.recipes[recipeId];
        if (!recipe) return false;
        return this.inventory.hasItems(recipe.getIngredients());
    }

    craft(recipeId) {
        const recipe = this.recipes[recipeId];
        if (!recipe || !this.canCraft(recipeId)) return false;

        // Remove ingredients
        for (const [itemId, quantity] of Object.entries(recipe.getIngredients())) {
            this.inventory.removeItem(itemId, quantity);
        }

        // Add result
        for (const [itemId, quantity] of Object.entries(recipe.getResult())) {
            this.inventory.addItem(itemId, quantity);
        }

        return true;
    }

    getCraftableRecipes() {
        return Object.keys(this.recipes).filter(recipeId => this.canCraft(recipeId));
    }
}

// Demo
