    'craft_table': new Recipe('craft_table', { wood: 4 }, { table: 1 }),
    'stone_pickaxe': new Recipe('stone_pickaxe', { stone: 3 }, { pickaxe: 1 })
};

const crafting = new Crafting(inventory, recipes);

