    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    this.balance += amount;
    console.log(`Bank: Deposited ${amount}, new balance is ${this.balance}`);
    this.eventBus.emit('balanceChanged', { balance: this.balance });
  }

  withdraw(amount) {
    if (amount > this.balance) {
      console.log('Bank: Insufficient funds');
      return;
    }
    this.balance -= amount;
    console.log(`Bank: Withdrew ${amount}, new balance is ${this.balance}`);
    this.eventBus.emit('balanceChanged', { balance: this.balance });
  }
}

// Market System
