  rest(amount) {
    this.currentEnergy = Math.min(this.maxEnergy, this.currentEnergy + amount);
    console.log(`Restored ${amount} energy, Energy: ${this.currentEnergy}`);
  }

  spend(amount) {
    this.currentEnergy = Math.max(0, this.currentEnergy - amount);
    console.log(`Spent ${amount} energy, Energy: ${this.currentEnergy}`);
