class Inventory {
  constructor(eventBus) {
    this.items = {};
    this.eventBus = eventBus;

    this.eventBus.subscribe('itemAdded', this.addItem.bind(this));
    this.eventBus.subscribe('itemRemoved', this.removeItem.bind(this));
  }

  addItem(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
    console.log(`Inventory: Added ${quantity} ${item}`);
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      if (this.items[item] === 0) {
        delete this.items[item];
      }
      console.log(`Inventory: Removed ${quantity} ${item}`);
    } else {
      console.log(`Inventory: Not enough ${item} to remove`);
    }
  }

  hasItem(item, quantity) {
    return this.items[item] && this.items[item] >= quantity;
  }
}

class Recipe {
  constructor(eventBus) {
    this.recipes = {};
    this.eventBus = eventBus;

    this.eventBus.subscribe('craftRequest', this.craft.bind(this));
  }

  addRecipe(name, ingredients) {
    this.recipes[name] = ingredients;
    console.log(`Recipe added: ${name}`);
  }

  craft(name) {
    const recipe = this.recipes[name];
    if (recipe) {
      const canCraft = Object.keys(recipe).every(item => {
        return this.eventBus.emit('checkInventory', { item, quantity: recipe[item] });
      });

      if (canCraft) {
        Object.keys(recipe).forEach(item => {
          this.eventBus.emit('removeItem', { item, quantity: recipe[item] });
        });
        console.log(`Crafted: ${name}`);
        this.eventBus.emit('itemAdded', { item: name, quantity: 1 });
      } else {
        console.log(`Cannot craft: ${name}`);
      }
    } else {
      console.log(`Recipe not found: ${name}`);
    }
  }
}

