class CraftingSystem {
  constructor(recipeSystem, inventorySystem) {
    this.recipeSystem = recipeSystem;
    this.inventorySystem = inventorySystem;
  }

  craft(itemName) {
    const recipe = this.recipeSystem.getRecipe(itemName);
    if (!recipe) {
      console.log(`No recipe found for ${itemName}`);
      return false;
    }

    const canCraft = recipe.ingredients.every(ingredient => 
      this.inventorySystem.hasItem(ingredient, recipe.quantity)
    );

    if (canCraft) {
      recipe.ingredients.forEach(ingredient => 
        this.inventorySystem.removeItem(ingredient, recipe.quantity)
      );
      this.inventorySystem.addItem(itemName, 1);
      console.log(`Crafted ${itemName}`);
      return true;
    } else {
      console.log(`Insufficient ingredients to craft ${itemName}`);
      return false;
    }
  }
}

