class RarityTable {
  constructor() {
    this.table = {
      common: 60,
      uncommon: 30,
      rare: 8,
      epic: 2
    };
  }

  roll() {
    const rand = Math.random() * 100;
    let cumulativeProbability = 0;

    for (const rarity in this.table) {
      cumulativeProbability += this.table[rarity];
      if (rand <= cumulativeProbability) {
        return rarity;
      }
    }

    return 'common'; // Default to common if something goes wrong
  }
}

