class Store {
    constructor() {
        this.items = new Map([
            ['apple', { price: 10, stock: 5 }],
            ['banana', { price: 5, stock: 10 }],
            ['orange', { price: 8, stock: 7 }]
        ]);
    }

    getItemPrice(item) {
        const itemInfo = this.items.get(item);
        return itemInfo ? itemInfo.price : null;
    }

    getItemStock(item) {
        const itemInfo = this.items.get(item);
        return itemInfo ? itemInfo.stock : 0;
    }

    purchaseItem(item, quantity) {
        const itemInfo = this.items.get(item);
        if (itemInfo && itemInfo.stock >= quantity) {
            itemInfo.stock -= quantity;
            return true;
        }
        return false;
    }
}

class Inventory {
    constructor() {
        this.items = new Map();
    }

    addItem(item, quantity) {
        if (quantity > 0) {
            this.items.set(item, (this.items.get(item) || 0) + quantity);
            return true;
        }
        return false;
    }

    getItemCount(item) {
        return this.items.get(item) || 0;
    }

    removeItem(item, quantity) {
        if (this.items.has(item) && this.items.get(item) >= quantity) {
            this.items.set(item, this.items.get(item) - quantity);
            if (this.items.get(item) === 0) {
                this.items.delete(item);
            }
            return true;
        }
        return false;
    }
}

class GameCoordinator {
