        this.store = new Store();
        this.inventory = new Inventory();
    }

    buyItemFromStore(item, quantity) {
        const price = this.store.getItemPrice(item);
        const stock = this.store.getItemStock(item);

        if (price && stock >= quantity) {
            const totalCost = price * quantity;
            if (this.economy.subtractFunds(totalCost)) {
                if (this.store.purchaseItem(item, quantity)) {
                    this.inventory.addItem(item, quantity);
                    console.log(`Bought ${quantity} ${item}(s) for ${totalCost}.`);
                    return true;
                }
            }
        }
        console.log(`Failed to buy ${quantity} ${item}(s).`);
        return false;
    }

    sellItemToStore(item, quantity) {
        const inventoryCount = this.inventory.getItemCount(item);

        if (inventoryCount >= quantity) {
            const price = this.store.getItemPrice(item);
            if (price) {
                const totalEarnings = price * quantity;
                this.economy.addFunds(totalEarnings);
                this.inventory.removeItem(item, quantity);
                console.log(`Sold ${quantity} ${item}(s) for ${totalEarnings}.`);
                return true;
            }
        }
        console.log(`Failed to sell ${quantity} ${item}(s).`);
        return false;
    }

    checkBalance() {
        console.log(`Current balance: ${this.economy.getBalance()}.`);
    }

    checkInventory() {
        console.log('Inventory:');
        this.inventory.items.forEach((quantity, item) => {
            console.log(`- ${item}: ${quantity}`);
        });
    }
}

