// Loot System
class Loot {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  getItem() {
    if (this.items.length === 0) return null;
    return this.items[Math.floor(Math.random() * this.items.length)];
  }
}

// RarityTable System
class RarityTable {
  constructor() {
    this.table = {
      common: 0.6,
      uncommon: 0.3,
      rare: 0.1
    };
  }

  generateRarity() {
    const roll = Math.random();
    let cumulativeProbability = 0;
    for (const [rarity, probability] of Object.entries(this.table)) {
      cumulativeProbability += probability;
      if (roll < cumulativeProbability) {
        return rarity;
      }
    }
    return 'common'; // Default to common if something goes wrong
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }

  listItems() {
    return Object.entries(this.items).map(([item, quantity]) => `${item}: ${quantity}`);
  }
}

// Top-level Coordinator
class GameCoordinator {
  constructor() {
    this.loot = new Loot();
    this.rarityTable = new RarityTable();
    this.inventory = new Inventory();
  }

  initializeLoot() {
    this.loot.addItem('Sword');
    this.loot.addItem('Shield');
    this.loot.addItem('Potion');
  }

  generateLoot() {
    const item = this.loot.getItem();
    if (!item) return null;
    const rarity = this.rarityTable.generateRarity();
    const lootDescription = `${rarity.charAt(0).toUpperCase() + rarity.slice(1)} ${item}`;
    this.inventory.addItem(lootDescription);
    return lootDescription;
  }

  displayInventory() {
    console.log('Inventory:');
    this.inventory.listItems().forEach(item => console.log(item));
  }
}

