class FlagsSystem {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.flags = {};
  }

  setFlag(flagName, value) {
    this.flags[flagName] = value;
    this.eventBus.emit('flagUpdated', { flagName, value });
  }

  getFlag(flagName) {
    return this.flags[flagName];
  }
}

class QuestSystem {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.eventBus.subscribe('flagUpdated', this.onFlagUpdated.bind(this));
    this.quests = {};
  }

  addQuest(questName, requirements) {
    this.quests[questName] = { requirements, completed: false };
  }

  completeQuest(questName) {
    if (this.quests[questName] && this.checkRequirements(questName)) {
      this.quests[questName].completed = true;
      console.log(`Quest "${questName}" completed!`);
      this.eventBus.emit('questCompleted', questName);
    }
  }

  onFlagUpdated({ flagName, value }) {
    this.quests = Object.fromEntries(
      Object.entries(this.quests).map(([questName, quest]) => {
        if (quest.requirements.includes(flagName)) {
          quest.completed = quest.completed || value;
        }
        return [questName, quest];
      })
    );
  }

  checkRequirements(questName) {
    const requirements = this.quests[questName].requirements;
    return requirements.every(flagName => this.eventBus.flagsSystem.getFlag(flagName));
  }
}

