    this.availableEnemies = [...Array(maxEnemies).keys()];
  }

  acquireEnemy() {
    if (this.availableEnemies.length === 0) {
      throw new Error("No available enemies");
    }
    return this.availableEnemies.pop();
  }

  releaseEnemy(enemyId) {
    this.availableEnemies.push(enemyId);
    console.log(`Enemy released with ID: ${enemyId}`);
  }
