class Economy {
  constructor(initialBalance = 1000) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  debit(amount) {
    if (amount > this.balance) {
      throw new Error("Insufficient funds");
    }
    this.balance -= amount;
    return true;
  }

  credit(amount) {
    this.balance += amount;
  }
}

class RarityTable {
  constructor() {
    this.rarityWeights = {
      common: 70,
      uncommon: 20,
      rare: 5,
      epic: 3,
      legendary: 1
    };
  }

  getRandomItem() {
    const totalWeight = Object.values(this.rarityWeights).reduce((acc, weight) => acc + weight, 0);
    let random = Math.random() * totalWeight;
    for (const [rarity, weight] of Object.entries(this.rarityWeights)) {
      random -= weight;
      if (random < 0) {
        return rarity;
      }
    }
    throw new Error("Failed to generate item");
  }
}

class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
  }

  getItems() {
    return this.items;
  }
}

