class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
    }
  }

  withdraw(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(prices) {
    this.prices = prices; // { item: price }
  }

  getPrice(item) {
    return this.prices[item] || 0;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item) {
    if (this.items[item]) {
      this.items[item]++;
    } else {
      this.items[item] = 1;
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

class Store {
  constructor(bank, market, inventory) {
    this.bank = bank;
    this.market = market;
    this.inventory = inventory;
  }

  purchase(item) {
    const price = this.market.getPrice(item);
    if (price > 0 && this.bank.withdraw(price)) {
      this.inventory.addItem(item);
      return true;
    }
    return false;
  }
}

