        this.table = {
            "Common": { min: 1, max: 5 },
            "Uncommon": { min: 6, max: 10 },
            "Rare": { min: 11, max: 15 },
            "Epic": { min: 16, max: 20 },
            "Legendary": { min: 21, max: 25 }
        };
    }

    getRandomLoot() {
        const rarities = Object.keys(this.table);
        const randomRarity = rarities[Math.floor(Math.random() * rarities.length)];
        const valueRange = this.table[randomRarity];
        const value = Math.floor(Math.random() * (valueRange.max - valueRange.min + 1)) + valueRange.min;
        return new Loot(`Item-${value}`, randomRarity, value);
    }
