    for (const [resource, amount] of Object.entries(cost)) {
      if (!this.resources[resource] || this.resources[resource] < amount) {
        return false;
      }
    }
    return true;
  }

  removeResources(cost) {
    for (const [resource, amount] of Object.entries(cost)) {
      this.resources[resource] -= amount;
    }
  }

  getResources() {
    return { ...this.resources };
  }
}

