class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(event, callback) {
    if (!this.events[event]) {
      this.events[event] = [];
    }
    this.events[event].push(callback);
  }

  emit(event, data) {
    if (this.events[event]) {
      this.events[event].forEach(callback => callback(data));
    }
  }
}

class Recipe {
  constructor(name, ingredients, result) {
    this.name = name;
    this.ingredients = ingredients;
    this.result = result;
  }

  canCraft(inventory) {
    for (const [item, quantity] of Object.entries(this.ingredients)) {
      if (!inventory[item] || inventory[item] < quantity) {
        return false;
      }
    }
    return true;
  }
}

class Inventory {
