class Wallet {
  constructor(initialAmount = 0) {
    this.balance = initialAmount;
  }

  deposit(amount) {
    this.balance += amount;
  }

  withdraw(amount) {
    if (amount > this.balance) {
      throw new Error('Insufficient funds');
    }
    this.balance -= amount;
  }

  getBalance() {
    return this.balance;
  }
}

class Inventory {
  constructor() {
    this.items = {};
  }

  addItem(item, quantity = 1) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  removeItem(item, quantity = 1) {
    if (!this.items[item] || this.items[item] < quantity) {
      throw new Error('Insufficient item quantity');
    }
    this.items[item] -= quantity;
    if (this.items[item] === 0) {
      delete this.items[item];
    }
  }

  getInventory() {
    return { ...this.items };
  }
}

class Shop {
  constructor(wallet, inventory, prices) {
    this.wallet = wallet;
    this.inventory = inventory;
    this.prices = prices;
  }

  buyItem(item, quantity = 1) {
    const price = this.prices[item];
    if (!price) {
      throw new Error('Item not for sale');
    }
    const totalCost = price * quantity;
    if (this.wallet.getBalance() < totalCost) {
      throw new Error('Insufficient funds');
    }
    this.wallet.withdraw(totalCost);
    this.inventory.addItem(item, quantity);
  }

  sellItem(item, quantity = 1) {
    if (!this.inventory.items[item] || this.inventory.items[item] < quantity) {
      throw new Error('Insufficient item quantity');
    }
    const price = this.prices[item];
    if (!price) {
      throw new Error('Item not for sale');
    }
    const totalRevenue = price * quantity;
    this.wallet.deposit(totalRevenue);
    this.inventory.removeItem(item, quantity);
  }
}

