class Pricing {
  constructor(pricingRules) {
    this.pricingRules = pricingRules;
  }

  calculatePrice(item, quantity) {
    const rule = this.pricingRules[item];
    if (rule && rule.type === 'discount') {
      return quantity * rule.price * (1 - rule.discount / 100);
    }
    return quantity * (rule?.price || 0);
  }
}

class Demand {
  constructor(demandData) {
    this.demandData = demandData;
  }

  getDemand(item) {
    return this.demandData[item] || 0;
  }
}

class Store {
  constructor(pricing, demand) {
    this.pricing = pricing;
    this.demand = demand;
  }

  sellItem(item, quantity) {
    const demand = this.demand.getDemand(item);
    if (quantity > demand) {
      return `Cannot sell ${quantity} ${item}(s). Only ${demand} available.`;
    }
    const price = this.pricing.calculatePrice(item, quantity);
    return `Sold ${quantity} ${item}(s) for $${price.toFixed(2)}.`;
  }
}

