class RarityTable {
  constructor() {
    this.table = {
      common: 0.6,
      rare: 0.3,
      epic: 0.1
    };
  }

  getRandomRarity() {
    const roll = Math.random();
    let cumulativeProbability = 0;

    for (const rarity in this.table) {
      cumulativeProbability += this.table[rarity];
      if (roll <= cumulativeProbability) {
        return rarity;
      }
    }

    return 'common'; // Fallback to common if all else fails
  }
}

