class Bank {
  constructor() {
    this.balance = 0;
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Deposited ${amount}, new balance: ${this.balance}`);
    } else {
      console.log('Deposit amount must be positive');
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Withdrew ${amount}, new balance: ${this.balance}`);
    } else {
      console.log('Invalid withdrawal amount');
    }
  }

  getBalance() {
    return this.balance;
  }
}

class Market {
  constructor(priceList) {
    this.priceList = priceList;
  }

  getPrice(item) {
    return this.priceList[item] || null;
  }

  buy(item, bank) {
    const price = this.getPrice(item);
    if (price) {
      if (bank.getBalance() >= price) {
        bank.withdraw(price);
        console.log(`Bought ${item} for ${price}`);
        return true;
      } else {
        console.log('Insufficient funds');
      }
    } else {
      console.log('Item not available in market');
    }
    return false;
  }
}

class Inventory {
