    this.items = {};
  }

  addItem(item, quantity) {
    if (quantity > 0) {
      this.items[item] = (this.items[item] || 0) + quantity;
      console.log(`Added ${quantity} of ${item}, total: ${this.items[item]}`);
    } else {
      console.log('Quantity must be positive');
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      console.log(`Removed ${quantity} of ${item}, remaining: ${this.items[item]}`);
    } else {
      console.log('Insufficient inventory');
    }
  }

  getItemCount(item) {
    return this.items[item] || 0;
  }
}

