class Economy {
    constructor(buildings, resources) {
        this.buildings = buildings;
        this.resources = resources;
    }

    update() {
        this.buildings.forEach(building => {
            const produced = building.produce();
            produced.forEach(resource => {
                this.resources[resource.name].add(resource.amount);
            });
        });
    }

    consumeResource(resourceName, amount) {
        const resource = this.resources[resourceName];
        if (resource) {
            resource.consume(amount);
        } else {
            console.log(`Resource ${resourceName} not found in economy.`);
        }
    }
}

