class Wallet {
  constructor(initialBalance = 0) {
    this.balance = initialBalance;
  }

  getBalance() {
    return this.balance;
  }

  addFunds(amount) {
    if (amount > 0) {
      this.balance += amount;
      return true;
    }
    return false;
  }

  subtractFunds(amount) {
    if (amount > 0 && this.balance >= amount) {
      this.balance -= amount;
      return true;
    }
    return false;
  }
}

// Shop System
class Shop {
  constructor() {
    this.items = {
      "Sword": 50,
      "Potion": 20,
      "Shield": 30
    };
  }

  getItems() {
    return { ...this.items };
  }

  getItemPrice(itemName) {
    return this.items[itemName] || 0;
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = {};
  }

  getInventory() {
    return { ...this.items };
  }

  addItem(itemName, quantity = 1) {
    if (quantity > 0) {
      this.items[itemName] = (this.items[itemName] || 0) + quantity;
      return true;
    }
    return false;
  }

  removeItem(itemName, quantity = 1) {
    if (quantity > 0 && this.items[itemName] >= quantity) {
      this.items[itemName] -= quantity;
      if (this.items[itemName] === 0) {
        delete this.items[itemName];
      }
      return true;
    }
    return false;
  }
}

// Coordinator to wire the systems together
class GameCoordinator {
  constructor() {
    this.wallet = new Wallet(100);
    this.shop = new Shop();
    this.inventory = new Inventory();
  }

  buyItem(itemName) {
    const price = this.shop.getItemPrice(itemName);
    if (price > 0 && this.wallet.subtractFunds(price)) {
      this.inventory.addItem(itemName);
      console.log(`Bought ${itemName} for ${price} gold. New balance: ${this.wallet.getBalance()} gold.`);
      return true;
    }
    console.log(`Failed to buy ${itemName}. Not enough gold or item does not exist.`);
    return false;
  }

  sellItem(itemName) {
    const price = this.shop.getItemPrice(itemName);
    if (price > 0 && this.inventory.removeItem(itemName)) {
      this.wallet.addFunds(price);
      console.log(`Sold ${itemName} for ${price} gold. New balance: ${this.wallet.getBalance()} gold.`);
      return true;
    }
    console.log(`Failed to sell ${itemName}. Item not in inventory or does not exist.`);
    return false;
  }

  displayStatus() {
    console.log("Wallet Balance:", this.wallet.getBalance(), "gold");
    console.log("Inventory:", this.inventory.getInventory());
  }
}

