// Crafting System
class Crafting {
    constructor() {
        this.recipes = [];
    }

    addRecipe(recipe) {
        this.recipes.push(recipe);
    }

    canCraft(recipeName) {
        return this.recipes.some(recipe => recipe.name === recipeName);
    }

    craft(recipeName) {
        const recipe = this.recipes.find(recipe => recipe.name === recipeName);
        if (recipe) {
            return recipe.items;
        }
        return null;
    }
}

// Recipe System
class Recipe {
    constructor(name, ingredients, items) {
        this.name = name;
        this.ingredients = ingredients;
        this.items = items;
    }
}

// Inventory System
class Inventory {
    constructor() {
        this.items = {};
    }

    addItem(item, quantity = 1) {
        if (this.items[item]) {
            this.items[item] += quantity;
        } else {
            this.items[item] = quantity;
        }
    }

    hasItems(ingredients) {
        for (const [item, quantity] of Object.entries(ingredients)) {
            if (!this.items[item] || this.items[item] < quantity) {
                return false;
            }
        }
        return true;
    }

    consumeItems(ingredients) {
        for (const [item, quantity] of Object.entries(ingredients)) {
            this.items[item] -= quantity;
        }
    }

    getItems() {
        return this.items;
    }
}

// Top-level Coordinator
class GameCoordinator {
    constructor() {
        this.crafting = new Crafting();
        this.inventory = new Inventory();
    }

    addRecipe(recipe) {
        this.crafting.addRecipe(recipe);
    }

    craftItem(recipeName) {
        if (this.crafting.canCraft(recipeName)) {
            const recipe = this.crafting.recipes.find(recipe => recipe.name === recipeName);
            if (this.inventory.hasItems(recipe.ingredients)) {
                this.inventory.consumeItems(recipe.ingredients);
                this.inventory.addItem(recipe.items[0], recipe.items[1]);
                console.log(`Crafted ${recipeName}: ${recipe.items[0]} x ${recipe.items[1]}`);
                return true;
            } else {
                console.log(`Not enough ingredients for ${recipeName}`);
                return false;
            }
        } else {
            console.log(`${recipeName} is not a known recipe`);
            return false;
        }
    }

    showInventory() {
        console.log("Inventory:", this.inventory.getItems());
    }
}

