    this.drainRate = drainRate;
    this.replenishRate = replenishRate;
    this.energyLevel = 100; // Full state
  }

  drain() {
    this.energyLevel -= this.drainRate;
    if (this.energyLevel < 0) this.energyLevel = 0; // Don't go below zero
  }

  replenish() {
    this.energyLevel += this.replenishRate;
    if (this.energyLevel > 100) this.energyLevel = 100; // Don't go above full
  }

  getCurrentLevel() {
    return this.energyLevel;
  }
}

