class EventBus {
  constructor() {
    this.events = {};
  }

  subscribe(eventName, callback) {
    if (!this.events[eventName]) {
      this.events[eventName] = [];
    }
    this.events[eventName].push(callback);
  }

  emit(eventName, data) {
    if (this.events[eventName]) {
      this.events[eventName].forEach(callback => callback(data));
    }
  }
}

class Bank {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.balance = 0;
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
    this.eventBus.subscribe('withdraw', this.withdraw.bind(this));
  }

  deposit(amount) {
    if (amount > 0) {
      this.balance += amount;
      console.log(`Bank: Deposited ${amount}, new balance is ${this.balance}`);
      this.eventBus.emit('balanceChanged', this.balance);
    } else {
      console.log('Bank: Deposit amount must be positive');
    }
  }

  withdraw(amount) {
    if (amount > 0 && amount <= this.balance) {
      this.balance -= amount;
      console.log(`Bank: Withdrew ${amount}, new balance is ${this.balance}`);
      this.eventBus.emit('balanceChanged', this.balance);
    } else {
      console.log('Bank: Insufficient funds or invalid amount');
    }
  }
}

class Market {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.prices = {
      apple: 1,
      banana: 2,
      orange: 3
    };
    this.eventBus.subscribe('buy', this.buy.bind(this));
  }

  buy(item, quantity) {
    const price = this.prices[item];
    if (price && quantity > 0) {
      const totalCost = price * quantity;
      console.log(`Market: Buying ${quantity} ${item}(s) at ${price} each, total cost is ${totalCost}`);
      this.eventBus.emit('buyRequest', { item, quantity, totalCost });
    } else {
      console.log('Market: Invalid item or quantity');
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.eventBus = eventBus;
    this.items = {};
    this.eventBus.subscribe('buyRequest', this.buyRequest.bind(this));
    this.eventBus.subscribe('deposit', this.deposit.bind(this));
  }

  buyRequest(data) {
    this.eventBus.emit('withdraw', data.totalCost);
  }

  deposit(item, quantity) {
    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
    console.log(`Inventory: Deposited ${quantity} ${item}(s), new inventory is`, this.items);
  }
}

