class Trade {
  constructor(prices) {
    this.prices = prices;
  }

  getTradePrice(item) {
    return this.prices[item] || null;
  }

  executeTrade(item, quantity, buyer, seller) {
    if (!this.prices[item]) {
      console.log(`Item ${item} is not tradable.`);
      return false;
    }
    const price = this.prices[item] * quantity;
    if (buyer.balance >= price) {
      buyer.balance -= price;
      seller.balance += price;
      console.log(`${buyer.name} bought ${quantity} ${item} from ${seller.name} for ${price}.`);
