class Reputation {
  constructor() {
    this.reputations = {};
  }

  getReputation(character) {
    return this.reputations[character.name] || 0;
  }

  changeReputation(character, amount) {
    if (!this.reputations[character.name]) {
      this.reputations[character.name] = 0;
    }
    this.reputations[character.name] += amount;
    console.log(`${character.name}'s reputation changed by ${amount}, new reputation: ${this.reputations[character.name]}.`);
