    if (!this.factions[factionName]) {
      this.factions[factionName] = [];
    }
    this.factions[factionName].push(character);
    console.log(`${character.name} joined faction ${factionName}.`);
  }

  getFactionMembers(factionName) {
    return this.factions[factionName] || [];
  }

  factionReputationChange(factionName, amount) {
    const members = this.getFactionMembers(factionName);
    members.forEach(member => {
      this.reputationSystem.changeReputation(member, amount);
    });
  }
