class LevelUp {
  constructor(skillSystem, experienceSystem) {
    this.skillSystem = skillSystem;
    this.experienceSystem = experienceSystem;
    this.level = 1;
  }

  checkForLevelUp() {
    const requiredExperience = this.level * 1000; // Arbitrary rule: level * 1000 experience needed
    if (this.experienceSystem.getExperiencePoints() >= requiredExperience) {
      this.levelUp();
    }
  }

  levelUp() {
    this.level++;
    console.log(`Level up! New level: ${this.level}`);
    // Example: Automatically learn a new skill or increase an existing one
    const newSkill = `Skill${this.level}`;
    this.skillSystem.learn(newSkill, this.level);
  }
}

