    this.skillSystem = new Skill();
    this.experienceSystem = new Experience();
    this.levelUpSystem = new LevelUp(this.skillSystem, this.experienceSystem);
  }

  gainSkill(skillName, level) {
    this.skillSystem.learn(skillName, level);
  }

  addExperience(points) {
    this.experienceSystem.gainExperience(points);
    this.levelUpSystem.checkForLevelUp();
  }
