class Market {
  constructor(eventBus) {
    this.items = { apple: 1, banana: 2, orange: 3 };
    this.eventBus = eventBus;

    this.eventBus.subscribe('buy', this.buy.bind(this));
    this.eventBus.subscribe('sell', this.sell.bind(this));
  }

  buy(item, quantity) {
    if (this.items[item] !== undefined && quantity > 0) {
      const totalCost = this.items[item] * quantity;
      this.eventBus.emit('withdraw', totalCost);
      this.eventBus.subscribe('balanceUpdated', (balance) => {
        if (balance >= 0) {
          console.log(`Bought ${quantity} ${item}(s) for ${totalCost}`);
        } else {
          console.log('Transaction failed: insufficient funds');
          this.eventBus.emit('deposit', totalCost); // Refund the money
        }
      }, { once: true });
    } else {
      console.log('Item not available or invalid quantity');
    }
  }

  sell(item, quantity) {
    if (this.items[item] !== undefined && quantity > 0) {
      const totalRevenue = this.items[item] * quantity;
      this.eventBus.emit('deposit', totalRevenue);
      console.log(`Sold ${quantity} ${item}(s) for ${totalRevenue}`);
    } else {
      console.log('Item not available or invalid quantity');
    }
  }
}

class Inventory {
  constructor(eventBus) {
    this.items = { apple: 0, banana: 0, orange: 0 };
    this.eventBus = eventBus;

    this.eventBus.subscribe('buy', this.addItem.bind(this));
    this.eventBus.subscribe('sell', this.removeItem.bind(this));
  }

  addItem(item, quantity) {
    if (this.items[item] !== undefined && quantity > 0) {
      this.items[item] += quantity;
      console.log(`Added ${quantity} ${item}(s) to inventory`);
    } else {
      console.log('Item not available or invalid quantity');
    }
  }

  removeItem(item, quantity) {
    if (this.items[item] !== undefined && quantity > 0 && this.items[item] >= quantity) {
      this.items[item] -= quantity;
      console.log(`Removed ${quantity} ${item}(s) from inventory`);
    } else {
      console.log('Item not available or invalid quantity');
    }
  }
}

