class Recipe {
  constructor(name, ingredients) {
    this.name = name;
    this.ingredients = ingredients;
  }

  getName() {
    return this.name;
  }

  getIngredients() {
    return this.ingredients;
  }
}

class Inventory {
  constructor() {
    this.items = new Map();
  }

  addItem(item, quantity = 1) {
    if (this.items.has(item)) {
      this.items.set(item, this.items.get(item) + quantity);
    } else {
      this.items.set(item, quantity);
    }
  }

  removeItem(item, quantity = 1) {
    if (this.items.has(item)) {
      const currentQuantity = this.items.get(item);
      if (currentQuantity > quantity) {
        this.items.set(item, currentQuantity - quantity);
      } else if (currentQuantity === quantity) {
        this.items.delete(item);
      } else {
        throw new Error(`Not enough ${item} in inventory.`);
      }
    } else {
      throw new Error(`${item} not found in inventory.`);
    }
  }

  hasItems(ingredients) {
    for (const [item, quantity] of Object.entries(ingredients)) {
      if (!this.items.has(item) || this.items.get(item) < quantity) {
        return false;
      }
    }
    return true;
  }

  getItems() {
    return this.items;
  }
}

class Crafting {
  constructor(inventory) {
    this.inventory = inventory;
    this.recipes = new Map();
  }

  addRecipe(recipe) {
    this.recipes.set(recipe.getName(), recipe);
  }

  craft(recipeName) {
    if (this.recipes.has(recipeName)) {
      const recipe = this.recipes.get(recipeName);
      if (this.inventory.hasItems(recipe.getIngredients())) {
        for (const [item, quantity] of Object.entries(recipe.getIngredients())) {
          this.inventory.removeItem(item, quantity);
        }
        console.log(`Crafted ${recipeName}`);
        return true;
      } else {
        console.log(`Missing ingredients for ${recipeName}`);
        return false;
      }
    } else {
      console.log(`Recipe ${recipeName} not found`);
      return false;
    }
  }
}

