class Hunger {
  constructor(maxHunger) {
    this.maxHunger = maxHunger;
    this.currentHunger = 0;
  }

  eat(amount) {
    this.currentHunger = Math.max(0, this.currentHunger - amount);
    console.log(`Ate ${amount}. Hunger is now ${this.currentHunger}.`);
  }

  update() {
    this.currentHunger = Math.min(this.maxHunger, this.currentHunger + 1);
    console.log(`Hunger increased by 1. Hunger is now ${this.currentHunger}.`);
  }
}

class Energy {
  constructor(maxEnergy) {
    this.maxEnergy = maxEnergy;
    this.currentEnergy = maxEnergy;
  }

  rest(amount) {
    this.currentEnergy = Math.min(this.maxEnergy, this.currentEnergy + amount);
    console.log(`Rested ${amount}. Energy is now ${this.currentEnergy}.`);
  }

  use(amount) {
    this.currentEnergy = Math.max(0, this.currentEnergy - amount);
    console.log(`Used ${amount} energy. Energy is now ${this.currentEnergy}.`);
  }

  update() {
    this.currentEnergy = Math.max(0, this.currentEnergy - 1);
    console.log(`Energy decreased by 1. Energy is now ${this.currentEnergy}.`);
  }
}

class Clock {
  constructor(onTick) {
    this.onTick = onTick;
    this.time = 0;
  }

  tick() {
    this.time++;
    console.log(`Time is now ${this.time}.`);
    this.onTick();
  }
}

