    if (this.items[item]) {
      this.items[item] += quantity;
    } else {
      this.items[item] = quantity;
    }
  }

  getInventory() {
    return { ...this.items };
  }
}

class Store {
  constructor(economy, inventory, prices) {
    this.economy = economy;
    this.inventory = inventory;
    this.prices = prices;
  }

  purchase(item, quantity) {
    const pricePerUnit = this.prices[item];
    const totalCost = pricePerUnit * quantity;

    if (this.economy.debit(totalCost)) {
      this.inventory.addItem(item, quantity);
      return true;
    }
    return false;
  }
}

class Clock {
  constructor() {
    this.time = 0;
  }

