      this.hungerLevel -= quantity * 10; // Eating reduces hunger by 10 units per unit of food
      if (this.hungerLevel < 0) {
        this.hungerLevel = 0;
      }
    }
  }

  getHungerLevel() {
    return this.hungerLevel;
  }
