const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * dpr;
canvas.height = window.innerHeight * dpr;
ctx.scale(dpr, dpr);

const gridSize = 20;
const snake = [{x: 10, y: 10}];
let direction = {x: 0, y: 0};
let food = {x: 15, y: 15};
let score = 0;

function getRandomFood() {
    return {
        x: Math.floor(Math.random() * (canvas.width / gridSize)),
        y: Math.floor(Math.random() * (canvas.height / gridSize))
    };
}

function drawRect(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x * gridSize, y * gridSize, gridSize, gridSize);
}

function drawSnake() {
    snake.forEach(segment => drawRect(segment.x, segment.y, 'green'));
}

function drawFood() {
    drawRect(food.x, food.y, 'red');
}

function moveSnake() {
    const head = {x: snake[0].x + direction.x, y: snake[0].y + direction.y};
    snake.unshift(head);
    if (head.x === food.x && head.y === food.y) {
        score++;
        food = getRandomFood();
    } else {
        snake.pop();
    }
}

function checkCollision() {
    const head = snake[0];
    if (head.x < 0 || head.x >= canvas.width / gridSize || head.y < 0 || head.y >= canvas.height / gridSize || snake.slice(1).some(segment => segment.x === head.x && segment.y === head.y)) {
        alert(`Game Over! Your score: ${score}`);
        document.location.reload();
    }
}

function aiMove() {
    const head = snake[0];
    const directions = [
        {x: 1, y: 0},  // Right
        {x: -1, y: 0}, // Left
        {x: 0, y: 1},  // Down
        {x: 0, y: -1}  // Up
    ];

    directions.sort((a, b) => {
        const distanceToFoodA = Math.abs(food.x - (head.x + a.x)) + Math.abs(food.y - (head.y + a.y));
        const distanceToFoodB = Math.abs(food.x - (head.x + b.x)) + Math.abs(food.y - (head.y + b.y));
        return distanceToFoodA - distanceToFoodB;
    });

    direction = directions[0];
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    aiMove();
    moveSnake();
    checkCollision();
    drawSnake();
    drawFood();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowUp':
            if (direction.y === 0) direction = {x: 0, y: -1};
            break;
        case 'ArrowDown':
            if (direction.y === 0) direction = {x: 0, y: 1};
            break;
        case 'ArrowLeft':
            if (direction.x === 0) direction = {x: -1, y: 0};
            break;
        case 'ArrowRight':
            if (direction.x === 0) direction = {x: 1, y: 0};
            break;
    }
});

gameLoop();
