    canvas.width = CANVAS_WIDTH;
    canvas.height = CANVAS_HEIGHT;
    document.body.appendChild(canvas);
    ctx = canvas.getContext('2d');
}

// Update game state
function update() {
    if (!gameRunning) return;

    // Move player
    player.vy += GRAVITY;
    player.y += player.vy;

    // Jump on spacebar press
    if (keys[' ']) {
        player.vy = JUMP_STRENGTH;
        keys[' '] = false;
    }

