const BLOCK_SIZE = 30;
const COLS = Math.floor(canvas.width / BLOCK_SIZE);
const ROWS = Math.floor(canvas.height / BLOCK_SIZE);
let blocks = [];
let currentBlock = null;
let currentBlockX = 0;
let currentBlockY = 0;
let gameInterval;

function createBlock() {
  return {
    shape: [
      [1, 1, 1, 1]
    ],
    color: `rgb(${Math.random() * 255}, ${Math.random() * 255}, ${Math.random() * 255})`
  };
}

function drawBlock(x, y, block) {
  block.shape.forEach((row, i) => {
    row.forEach((cell, j) => {
      if (cell) {
        ctx.fillStyle = block.color;
        ctx.fillRect((x + j) * BLOCK_SIZE, (y + i) * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
      }
    });
  });
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  blocks.forEach(block => drawBlock(block.x, block.y, block));
  if (currentBlock) {
    drawBlock(currentBlockX, currentBlockY, currentBlock);
  }
}

function moveBlock(dx, dy) {
  if (!currentBlock) return;
  const newX = currentBlockX + dx;
  const newY = currentBlockY + dy;
  if (newX >= 0 && newX + currentBlock.shape[0].length <= COLS && newY + currentBlock.shape.length <= ROWS) {
    currentBlockX = newX;
    currentBlockY = newY;
  }
}

function dropBlock() {
  if (!currentBlock) return;
  if (currentBlockY + currentBlock.shape.length < ROWS) {
    currentBlockY++;
  } else {
    blocks.push({ ...currentBlock, x: currentBlockX, y: currentBlockY });
    currentBlock = null;
    currentBlockX = 0;
    currentBlockY = 0;
  }
}

function gameLoop() {
  dropBlock();
  draw();
  if (!currentBlock) {
    currentBlock = createBlock();
  }
}

function resizeCanvas() {
  dpr = window.devicePixelRatio;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}

