  growRate: 0.1,
  maxGrowth: 100,
  seed: null,
  plant: null,
  timer: null,
  startTime: null,
  duration: 10000 // 10 seconds
};

function plantSeed(seedName) {
  farmingPlot.seed = seedName;
  farmingPlot.plant = null;
  farmingPlot.growth = 0;
  farmingPlot.startTime = Date.now();
  farmingPlot.timer = setInterval(updateGrowth, 100);
}

function updateGrowth() {
  if (farmingPlot.startTime) {
    let elapsed = Date.now() - farmingPlot.startTime;
    if (elapsed >= farmingPlot.duration) {
      clearInterval(farmingPlot.timer);
      farmingPlot.plant = farmingPlot.seed;
      farmingPlot.seed = null;
      farmingPlot.growth = farmingPlot.maxGrowth;
    } else {
      farmingPlot.growth = Math.min(farmingPlot.maxGrowth, (elapsed / farmingPlot.duration) * farmingPlot.maxGrowth);
    }
  }
}

function drawFarmingPlot() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = '#7A593B';
  ctx.fillRect(farmingPlot.x, farmingPlot.y, farmingPlot.width, farmingPlot.height);

