    const y = Math.random() * (canvas.height - 20) + 10;
    enemies.push({ x, y, speed: 2, size: 10, hitPoints: 5 });
}

function update(dt) {
    if (gameOver) return;

    // Enemy movement
    enemies.forEach(enemy => {
        enemy.x -= enemy.speed * dt;
        if (enemy.x < 0) {
            lives--;
            enemies.splice(enemies.indexOf(enemy), 1);
            if (lives <= 0) {
                gameOver = true;
            }
        }
    });

