            if (target) {
                bullets.push({ x: tower.x, y: tower.y, target, speed: 5 });
            }
        }
    });

    // Bullet movement and collision detection
    bullets.forEach(bullet => {
        const dx = bullet.target.x - bullet.x;
        const dy = bullet.target.y - bullet.y;
        const distance = Math.hypot(dx, dy);
        const moveX = dx / distance * bullet.speed;
        const moveY = dy / distance * bullet.speed;
        bullet.x += moveX;
        bullet.y += moveY;

        if (Math.hypot(bullet.x - bullet.target.x, bullet.y - bullet.target.y) < bullet.target.size) {
            bullet.target.hitPoints--;
            if (bullet.target.hitPoints <= 0) {
                enemies.splice(enemies.indexOf(bullet.target), 1);
                score += 100;
            }
            bullets.splice(bullets.indexOf(bullet), 1);
        }
    });
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw towers
    towers.forEach(tower => {
        ctx.fillStyle = 'blue';
        ctx.fillRect(tower.x, tower.y, 10, 10);
    });

    // Draw enemies
    enemies.forEach(enemy => {
        ctx.fillStyle = 'red';
        ctx.fillRect(enemy.x, enemy.y, enemy.size, enemy.size);
    });

    // Draw bullets
    bullets.forEach(bullet => {
        ctx.fillStyle = 'green';
        ctx.fillRect(bullet.x, bullet.y, 3, 3);
    });

    // Draw score and lives
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`Lives: ${lives}`, 10, 60);

    if (gameOver) {
        ctx.fillStyle = 'red';
        ctx.font = '40px Arial';
        ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
    }
}

function gameLoop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    accumulator += dt;

    while (accumulator >= FIXED_TIMESTEP) {
        update(FIXED_TIMESTEP);
        accumulator -= FIXED_TIMESTEP;
    }

    draw();

    requestAnimationFrame(gameLoop);
}

createTower(100, 100);
let lastTime = performance.now();
requestAnimationFrame(gameLoop);

setInterval(createEnemy, 2000);
