canvas.width = 800;
canvas.height = 600;

const cardWidth = 100;
const cardHeight = 150;
const cardSpacing = 20;
const cols = 4;
const rows = 3;
const totalCards = cols * rows;
const cardPairs = totalCards / 2;

const cards = [];
const flippedCards = [];
let firstCard, secondCard;
let aiTurn = false;
let aiTimer;

function getRandomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
        const j = getRandomInt(0, i);
        [array[i], array[j]] = [array[j], array[i]];
    }
}

function createCards() {
    for (let i = 0; i < cardPairs; i++) {
        cards.push({ value: i, flipped: false, matched: false });
        cards.push({ value: i, flipped: false, matched: false });
    }
    shuffle(cards);
}

function drawCard(card, x, y) {
    ctx.fillStyle = card.flipped || card.matched ? 'lightblue' : 'lightgray';
    ctx.fillRect(x, y, cardWidth, cardHeight);
    if (card.flipped || card.matched) {
        ctx.fillStyle = 'black';
        ctx.font = '20px Arial';
        ctx.fillText(card.value.toString(), x + cardWidth / 2 - 5, y + cardHeight / 2 + 5);
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < totalCards; i++) {
        const x = (cardWidth + cardSpacing) * (i % cols);
        const y = (cardHeight + cardSpacing) * Math.floor(i / cols);
        drawCard(cards[i], x, y);
    }
}

function checkMatch() {
    if (firstCard.value === secondCard.value) {
        firstCard.matched = true;
        secondCard.matched = true;
    } else {
        setTimeout(() => {
            firstCard.flipped = false;
            secondCard.flipped = false;
        }, 1000);
    }
    firstCard = secondCard = null;
}

function flipCard(card, index) {
    if (!card.flipped && !card.matched) {
        card.flipped = true;
        if (firstCard) {
            secondCard = card;
            checkMatch();
            if (flippedCards.length === 2) {
                aiTurn = true;
                aiTimer = setTimeout(aiFlip, 1000);
            }
        } else {
            firstCard = card;
        }
        flippedCards.push(index);
    }
}

function aiFlip() {
    aiTurn = false;
    let availableCards = cards.filter(card => !card.flipped && !card.matched);
    if (availableCards.length === 0) return;
    let randomIndex = getRandomInt(0, availableCards.length - 1);
    let randomCard = availableCards[randomIndex];
    let cardIndex = cards.indexOf(randomCard);
    flipCard(randomCard, cardIndex);
}

function gameLoop() {
    drawBoard();
    requestAnimationFrame(gameLoop);
}

createCards();
gameLoop();

canvas.addEventListener('click', (event) => {
    if (aiTurn) return;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    for (let i = 0; i < totalCards; i++) {
        const cardX = (cardWidth + cardSpacing) * (i % cols);
        const cardY = (cardHeight + cardSpacing) * Math.floor(i / cols);
        if (x > cardX && x < cardX + cardWidth && y > cardY && y < cardY + cardHeight) {
            flipCard(cards[i], i);
            break;
        }
    }
});
