```js
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

const SHIP_SIZE = 20;
const SHIP_THRUST = 5;
const SHIP_TURN_SPEED = 360;
const ASTEROID_SIZES = [50, 30, 15];
const ASTEROID_SPEED = 150;
const ASTEROID_VARIATION = 100;
const BULLET_SPEED = 500;
const BULLET_LIFETIME = 1;
const WAVES = 5;

let ship = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  angle: 90,
  thrusting: false,
  thrust: { x: 0, y: 0 },
  r: SHIP_SIZE
};

let bullets = [];
let asteroids = [];
let wave = 1;
let score = 0;
let lives = 3;
let lastTime = 0;
let fixedTimeStep = 1000 / 60;
let accumulator = 0;

function resetShip() {
  ship = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    angle: 90,
    thrusting: false,
    thrust: { x: 0, y: 0 },
    r: SHIP_SIZE
  };
}

function resetGame() {
  wave = 1;
  score = 0;
  lives = 3;
  asteroids = [];
  bullets = [];
  resetShip();
  spawnAsteroids(wave);
}

function spawnAsteroids(count) {
  for (let i = 0; i < count; i++) {
    const size = ASTEROID_SIZES[Math.floor(Math.random() * ASTEROID_SIZES.length)];
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height;
    const dx = (Math.random() - 0.5) * ASTEROID_SPEED;
    const dy = (Math.random() - 0.5) * ASTEROID_SPEED;
    asteroids.push({ x, y, dx, dy, size, r: size / 2 });
  }
}

function shootBullet() {
  const angleRad = degToRad(ship.angle);
  const velX = Math.cos(angleRad) * BULLET_SPEED;
  const velY = Math.sin(angleRad) * BULLET_SPEED;
  bullets.push({
    x: ship.x + Math.cos(angleRad) * SHIP_SIZE,
    y: ship.y + Math.sin(angleRad) * SHIP_SIZE,
    dx: velX,
    dy: velY,
    r: 3,
    time: 0
  });
}

function degToRad(degrees) {
  return degrees * Math.PI / 180;
}

function radToDeg(radians) {
  return radians * 180 / Math.PI;
}

function update(dt) {
  if (lives <= 0) {
    resetGame();
    return;
  }

  if (ship.thrusting) {
    const angleRad = degToRad(ship.angle);
    ship.thrust.x += Math.cos(angleRad) * SHIP_THRUST * dt;
    ship.thrust.y += Math.sin(angleRad) * SHIP_THRUST * dt;
  } else {
    ship.thrust.x = 0;
    ship.thrust.y = 0;
  }

  ship.x += ship.thrust.x * dt;
  ship.y += ship.thrust.y * dt;

  if (ship.x < 0) ship.x = canvas.width;
  if (ship.x > canvas.width) ship.x = 0;
  if (ship.y < 0) ship.y = canvas.height;
  if (ship.y > canvas.height) ship.y = 0;

  bullets.forEach(bullet => {
    bullet.x += bullet.dx * dt;
    bullet.y += bullet.dy * dt;
    bullet.time += dt;
  });

  bullets = bullets.filter(bullet => bullet.time < BULLET_LIFETIME);

  asteroids.forEach(asteroid => {
    asteroid.x += asteroid.dx * dt;
    asteroid.y += asteroid.dy * dt;

    if (asteroid.x < 0) asteroid.x = canvas.width;
    if (asteroid.x > canvas.width) asteroid.x = 0;
    if (asteroid.y < 0) asteroid.y = canvas.height;
    if (asteroid.y > canvas.height) asteroid.y = 0;
  });

  asteroids.forEach((asteroid, i) => {
    bullets.forEach((bullet, j) => {
      if (dist(asteroid.x, asteroid.y, bullet.x, bullet.y) < asteroid.r + bullet.r) {
        bullets.splice(j, 1);
        score += 10;
        if (asteroid.size > ASTEROID_SIZES[ASTEROID_SIZES.length - 1]) {
          splitAsteroid(asteroid);
        }
        asteroids.splice(i, 1);
      }
    });
  });

  asteroids.forEach(asteroid => {
    if (dist(asteroid.x, asteroid.y, ship.x, ship.y) < asteroid.r + ship.r) {
      lives--;
      resetShip();
      asteroids = [];
      spawnAsteroids(wave);
    }
  });

  if (asteroids.length === 0 && wave < WAVES) {
    wave++;
    spawnAsteroids(wave);
  }
}

function splitAsteroid(asteroid) {
  const newSize = ASTEROID_SIZES.indexOf(asteroid.size) + 1;
  if (newSize >= ASTEROID_SIZES.length) return;

  const angle = degToRad(Math.random() * 360);
  const newSpeed = ASTEROID_SPEED + Math.random() * ASTEROID_VARIATION - ASTEROID_VARIATION / 2;

  const newAsteroids = [
    {
      x: asteroid.x,
      y: asteroid.y,
      dx: Math.cos(angle - Math.PI / 2) * newSpeed,
      dy: Math.sin(angle - Math.PI / 2) * newSpeed,
      size: ASTEROID_SIZES[newSize],
      r: ASTEROID_SIZES[newSize] / 2
    },
    {
      x: asteroid.x,
      y: asteroid.y,
      dx: Math.cos(angle + Math.PI / 2) * newSpeed,
      dy: Math.sin(angle + Math.PI / 2) * newSpeed,
      size: ASTEROID_SIZES[newSize],
      r: ASTEROID_SIZES[newSize] / 2
    }
  ];

  asteroids = asteroids.concat(newAsteroids);
}

function dist(x1, y1, x2, y2) {
  return Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
}

function render() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(degToRad(ship.angle));
  ctx.strokeStyle = 'green';
  ctx.beginPath();
  ctx.moveTo(0, -SHIP_SIZE);
  ctx.lineTo(-SHIP_SIZE / 2, SHIP_SIZE / 2);
  ctx.lineTo(SHIP_SIZE / 2, SHIP_SIZE / 2);
  ctx.closePath();
  ctx.stroke();
  ctx.restore();

  ctx.fillStyle = 'red';
  bullets.forEach(bullet => {
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, bullet.r, 0, Math.PI * 2);
    ctx.fill();
  });

  ctx.fillStyle = 'gray';
  asteroids.forEach(asteroid => {
    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.r, 0, Math.PI * 2);
    ctx.fill();
  });

  ctx.fillStyle = 'white';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Lives: ${lives}`, 10, 60);
  ctx.fillText(`Wave: ${wave}`, 10, 90);
}

function gameLoop(timestamp) {
  const dt = timestamp - lastTime;
  lastTime = timestamp;
  accumulator += dt;

  while (accumulator >= fixedTimeStep) {
    update(fixedTimeStep / 1000);
    accumulator -= fixedTimeStep;
  }

  render();
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', event => {
  if (event.key === 'ArrowLeft') {
    ship.angle -= SHIP_TURN_SPEED;
  } else if (event.key === 'ArrowRight') {
    ship.angle += SHIP_TURN_SPEED;
