    switch (currentState) {
        case states.menu:
            startGame();
            break;
        case states.playing:
            towers.push({ x, y });
            break;
        case states.paused:
            currentState = states.playing;
            break;
        case states.gameover:
            startGame();
            break;
    }
}

canvas.addEventListener('click', handleMouseClick);

update();
