    }

    window.addEventListener('resize', resizeCanvas);
    resizeCanvas();

    const cardWidth = 100;
    const cardHeight = 150;
    const padding = 10;
    const cardsPerRow = Math.floor(canvas.width / (cardWidth + padding));
    const rows = Math.ceil(16 / cardsPerRow);
    const cardImages = [];
    for (let i = 0; i < 8; i++) {
        cardImages.push(`image${i}.png`);
        cardImages.push(`image${i}.png`);
    }

    function shuffle(array) {
        for (let i = array.length - 1; i > 0; i--) {
            const j = Math.floor(Math.random() * (i + 1));
            [array[i], array[j]] = [array[j], array[i]];
        }
    }

    shuffle(cardImages);

    const cards = [];
    for (let i = 0; i < 16; i++) {
        const row = Math.floor(i / cardsPerRow);
        const col = i % cardsPerRow;
        cards.push({
            x: col * (cardWidth + padding),
            y: row * (cardHeight + padding),
            width: cardWidth,
            height: cardHeight,
            image: cardImages[i],
            flipped: false,
            matched: false
        });
    }

    let selectedCard = null;

    function drawCard(card) {
        if (!card.flipped || card.matched) {
            ctx.fillStyle = 'lightgray';
            ctx.fillRect(card.x, card.y, card.width, card.height);
            ctx.strokeRect(card.x, card.y, card.width, card.height);
        } else {
            const img = new Image();
            img.src = card.image;
            img.onload = () => {
                ctx.drawImage(img, card.x, card.y, card.width, card.height);
            };
        }
    }

    function draw() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        cards.forEach(drawCard);
    }

    canvas.addEventListener('click', (event) => {
        const rect = canvas.getBoundingClientRect();
        const x = (event.clientX - rect.left) / devicePixelRatio;
        const y = (event.clientY - rect.top) / devicePixelRatio;
        const card = cards.find(c => 
            x > c.x && x < c.x + c.width && 
            y > c.y && y < c.y + c.height
        );
        if (card && !card.flipped && !card.matched) {
            if (selectedCard) {
                selectedCard.flipped = true;
                draw();
                setTimeout(() => {
                    if (selectedCard.image === card.image) {
                        selectedCard.matched = true;
                        card.matched = true;
                    } else {
                        selectedCard.flipped = false;
                        card.flipped = false;
                    }
                    selectedCard = null;
                    draw();
                }, 1000);
            } else {
                selectedCard = card;
                card.flipped = true;
                draw();
            }
        }
    });

    document.addEventListener('keydown', (event) => {
        if (event.key === 'ArrowLeft' || event.key === 'ArrowRight' || event.key === 'ArrowUp' || event.key === 'ArrowDown') {
            let index = cards.findIndex(c => c.flipped && !c.matched);
            if (index === -1) index = 0;

            let newIndex = index;
            if (event.key === 'ArrowLeft') newIndex = Math.max(0, index - 1);
            if (event.key === 'ArrowRight') newIndex = Math.min(cards.length - 1, index + 1);
            if (event.key === 'ArrowUp') newIndex = Math.max(0, index - cardsPerRow);
            if (event.key === 'ArrowDown') newIndex = Math.min(cards.length - 1, index + cardsPerRow);

            if (newIndex !== index) {
                cards[index].flipped = false;
                cards[newIndex].flipped = true;
                selectedCard = cards[newIndex];
                draw();
            }
        }
    });

    draw();
});
