  inputText = '';
  score = 0;
  gameStarted = true;
  gameOver = false;
  startTime = Date.now();
}

// Update game logic
function update() {
  if (gameOver) return;

  // Calculate score
  score = calculateScore(inputText);
  if (inputText === TEXT_TO_TYPE) {
    gameOver = true;
  }
}

// Render the game
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = BACKGROUND_COLOR;
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  // Render text to type
  ctx.fillStyle = TEXT_COLOR;
  ctx.font = `${FONT_SIZE}px Arial`;
  ctx.fillText(TEXT_TO_TYPE, TEXT_PADDING, TEXT_PADDING + FONT_SIZE);

  // Render input text
  ctx.fillText(inputText, TEXT_PADDING, TEXT_PADDING + 3 * FONT_SIZE);

  // Render score
  ctx.fillText(`Score: ${score}`, TEXT_PADDING, TEXT_PADDING + 5 * FONT_SIZE);

  // Render game over message if applicable
  if (gameOver) {
    ctx.fillStyle = TEXT_COLOR;
    ctx.font = `${FONT_SIZE * 2}px Arial`;
    ctx.fillText(GAME_OVER_TEXT, (canvas.width / 2) - (ctx.measureText(GAME_OVER_TEXT).width / 2), canvas.height / 2);
  }
}

// Calculate score based on input
function calculateScore(input) {
  let typedCorrectly = 0;
  for (let i = 0; i < input.length && i < TEXT_TO_TYPE.length; i++) {
    if (input[i] === TEXT_TO_TYPE[i]) {
      typedCorrectly++;
    }
  }
  return (typedCorrectly / TEXT_TO_TYPE.length) * 100;
}

// Event listeners
function setupEventListeners() {
  document.addEventListener('keydown', (e) => {
    if (!gameStarted) return;
    if (e.key === 'Backspace') {
      inputText = inputText.slice(0, -1);
    } else if (e.key.length === 1) {
      inputText += e.key;
    }
  });

  document.addEventListener('click', () => {
    if (gameOver) {
      resetGame();
    }
  });

  window.addEventListener('resize', () => {
    initCanvas();
  });
}

// Main game loop
function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

// Initialize game
function initGame() {
  initCanvas();
  setupEventListeners();
  resetGame();
  gameLoop();
}

// Start the game
initGame();
