class Plant {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.color = color;
    this.growth = 0;
  }

  grow() {
    this.growth += 0.01;
    if (this.growth > 1) this.growth = 1;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, 10 + 20 * this.growth, 0, Math.PI * 2);
    ctx.fillStyle = this.color;
    ctx.fill();
  }
}

class Enemy {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.color = color;
    this.speed = 1 + Math.random();
  }

  move() {
    this.x -= this.speed;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, 10, 0, Math.PI * 2);
    ctx.fillStyle = this.color;
    ctx.fill();
  }
}

class FarmPlot {
  constructor() {
    this.plants = [];
    this.enemies = [];
    this.level = 1;
    this.score = 0;
    this.waveTimer = 0;
    this.waveInterval = 3000;
  }

  spawnPlant(x, y) {
    this.plants.push(new Plant(x, y, 'green'));
  }

  spawnEnemy() {
    const y = Math.random() * canvas.height;
    this.enemies.push(new Enemy(canvas.width, y, 'red'));
  }

  update() {
    this.waveTimer++;
    if (this.waveTimer >= this.waveInterval) {
      this.waveTimer = 0;
      for (let i = 0; i < this.level; i++) {
        this.spawnEnemy();
      }
      this.level++;
      this.waveInterval *= 0.9; // Increase difficulty by reducing wave interval
    }

    this.plants.forEach(plant => plant.grow());
    this.enemies.forEach(enemy => enemy.move());

    // Collision detection
    this.plants.forEach(plant => {
      this.enemies.forEach((enemy, index) => {
        const dx = plant.x - enemy.x;
        const dy = plant.y - enemy.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance < 30) {
          this.enemies.splice(index, 1);
          this.score++;
        }
      });
    });

    // Remove enemies that go off screen
    this.enemies = this.enemies.filter(enemy => enemy.x > 0);
  }

  draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    this.plants.forEach(plant => plant.draw());
    this.enemies.forEach(enemy => enemy.draw());

    // Draw score and level
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${this.score}`, 10, 30);
    ctx.fillText(`Level: ${this.level}`, 10, 60);
  }
}

const farmPlot = new FarmPlot();

function gameLoop() {
  farmPlot.update();
  farmPlot.draw();
  requestAnimationFrame(gameLoop);
}

