  x: (i % 4) * (cardWidth + margin) + margin,
  y: Math.floor(i / 4) * (cardHeight + margin) + margin,
  value: Math.floor(i / 2) + 1,
  revealed: false,
  matched: false
}));

let selectedCard = null;
let combo = 1;
let score = 0;

function drawCard(card, revealed) {
  ctx.fillStyle = '#fff';
  ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
  ctx.strokeStyle = '#000';
  ctx.strokeRect(card.x, card.y, cardWidth, cardHeight);
  if (revealed) {
    ctx.font = '24px Arial';
    ctx.fillStyle = '#000';
    ctx.fillText(card.value, card.x + cardWidth / 2 - 10, card.y + cardHeight / 2 + 10);
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  cards.forEach(card => drawCard(card, card.revealed));
  ctx.fillStyle = '#000';
  ctx.font = '18px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Combo: x${combo}`, 10, 50);
  requestAnimationFrame(draw);
}

canvas.addEventListener('click', (event) => {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;

  const card = cards.find(c => x > c.x && x < c.x + cardWidth && y > c.y && y < c.y + cardHeight);

  if (card && !card.revealed && !card.matched) {
    card.revealed = true;
    if (selectedCard) {
      if (card.value === selectedCard.value) {
        card.matched = true;
        selectedCard.matched = true;
        score += card.value * combo;
        combo++;
      } else {
        combo = 1;
      }
      selectedCard = null;
    } else {
      selectedCard = card;
    }
  }
});

