const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const jumpForce = -10;
const groundY = canvas.height - 50;
const enemySpawnInterval = 2000; // milliseconds
const difficultyIncreaseInterval = 10000; // milliseconds
const maxEnemySpeed = 5;

let player = {
    x: 50,
    y: groundY,
    width: 50,
    height: 50,
    velocityY: 0,
    isJumping: false
};

let enemies = [];
let score = 0;
let lastEnemySpawnTime = 0;
let lastDifficultyIncreaseTime = 0;
let enemySpeed = 2;
let gameRunning = true;
let lastFrameTime = 0;

function update(deltaTime) {
    if (!gameRunning) return;

    player.velocityY += gravity;
    player.y += player.velocityY;

    if (player.y > groundY) {
        player.y = groundY;
        player.velocityY = 0;
        player.isJumping = false;
    }

    score += deltaTime * 0.01;

    if (Date.now() - lastEnemySpawnTime > enemySpawnInterval) {
        spawnEnemy();
        lastEnemySpawnTime = Date.now();
    }

    enemies.forEach(enemy => {
        enemy.x -= enemySpeed;
        if (enemy.x + enemy.width < 0) {
            enemies.shift();
        }
    });

    if (Date.now() - lastDifficultyIncreaseTime > difficultyIncreaseInterval) {
        increaseDifficulty();
        lastDifficultyIncreaseTime = Date.now();
    }

    checkCollisions();
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'green';
    ctx.fillRect(0, groundY, canvas.width, canvas.height - groundY);

    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    ctx.fillStyle = 'red';
    enemies.forEach(enemy => {
        ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
    });

    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score.toFixed(2)}`, 10, 30);
}

function spawnEnemy() {
    const enemy = {
        x: canvas.width,
        y: groundY - 50,
        width: 30,
        height: 50
    };
    enemies.push(enemy);
}

function increaseDifficulty() {
    if (enemySpeed < maxEnemySpeed) {
        enemySpeed += 0.5;
    }
}

function checkCollisions() {
    enemies.forEach(enemy => {
        if (player.x < enemy.x + enemy.width &&
            player.x + player.width > enemy.x &&
            player.y < enemy.y + enemy.height &&
            player.y + player.height > enemy.y) {
            gameRunning = false;
        }
    });
}

function mainLoop(timestamp) {
    const deltaTime = timestamp - lastFrameTime;
    lastFrameTime = timestamp;

    update(deltaTime);
    draw();

    if (gameRunning) {
        requestAnimationFrame(mainLoop);
    }
}

canvas.addEventListener('click', () => {
    if (!player.isJumping) {
        player.velocityY = jumpForce;
        player.isJumping = true;
    }
});

requestAnimationFrame(mainLoop);
