(function() {
    const canvas = document.createElement('canvas');
    document.body.appendChild(canvas);
    const ctx = canvas.getContext('2d');

    const scale = window.devicePixelRatio;
    let boardSize = 4;
    let board = Array(boardSize).fill().map(() => Array(boardSize).fill(0));
    let score = 0;

    function setCanvasSize() {
        const width = window.innerWidth;
        const height = window.innerHeight;
        canvas.width = width * scale;
        canvas.height = height * scale;
        ctx.scale(scale, scale);
        ctx.font = 'bold 24px Arial';
    }

    function getRandomInt(min, max) {
        return Math.floor(Math.random() * (max - min)) + min;
    }

    function addRandomTile() {
        let emptyTiles = [];
        for (let i = 0; i < boardSize; i++) {
            for (let j = 0; j < boardSize; j++) {
                if (board[i][j] === 0) {
                    emptyTiles.push([i, j]);
                }
            }
        }
        if (emptyTiles.length > 0) {
            const [x, y] = emptyTiles[getRandomInt(0, emptyTiles.length)];
            board[x][y] = Math.random() < 0.9 ? 2 : 4;
        }
    }

    function slide(direction) {
        let moved = false;
        switch (direction) {
            case 'up':
                for (let j = 0; j < boardSize; j++) {
                    let newRow = [];
                    for (let i = 0; i < boardSize; i++) {
                        if (board[i][j] !== 0) {
                            newRow.push(board[i][j]);
                        }
                    }
                    for (let i = 0; i < boardSize; i++) {
                        if (i < newRow.length - 1 && newRow[i] === newRow[i + 1]) {
                            newRow[i] *= 2;
                            score += newRow[i];
                            newRow.splice(i + 1, 1);
                        }
                        if (board[i][j] !== newRow[i]) {
                            board[i][j] = newRow[i] || 0;
                            moved = true;
                        }
                    }
                }
                break;
            case 'down':
                for (let j = 0; j < boardSize; j++) {
                    let newRow = [];
                    for (let i = boardSize - 1; i >= 0; i--) {
                        if (board[i][j] !== 0) {
                            newRow.push(board[i][j]);
                        }
                    }
                    for (let i = boardSize - 1; i >= 0; i--) {
                        if (i > 0 && newRow[i] === newRow[i - 1]) {
                            newRow[i] *= 2;
                            score += newRow[i];
                            newRow.splice(i - 1, 1);
                        }
                        if (board[i][j] !== newRow[boardSize - 1 - i]) {
                            board[i][j] = newRow[boardSize - 1 - i] || 0;
                            moved = true;
                        }
                    }
                }
                break;
            case 'left':
                for (let i = 0; i < boardSize; i++) {
                    let newRow = [];
                    for (let j = 0; j < boardSize; j++) {
                        if (board[i][j] !== 0) {
                            newRow.push(board[i][j]);
                        }
                    }
                    for (let j = 0; j < boardSize; j++) {
                        if (j < newRow.length - 1 && newRow[j] === newRow[j + 1]) {
                            newRow[j] *= 2;
                            score += newRow[j];
                            newRow.splice(j + 1, 1);
                        }
                        if (board[i][j] !== newRow[j]) {
                            board[i][j] = newRow[j] || 0;
                            moved = true;
                        }
                    }
                }
                break;
            case 'right':
                for (let i = 0; i < boardSize; i++) {
                    let newRow = [];
                    for (let j = boardSize - 1; j >= 0; j--) {
                        if (board[i][j] !== 0) {
                            newRow.push(board[i][j]);
                        }
                    }
                    for (let j = boardSize - 1; j >= 0; j--) {
                        if (j > 0 && newRow[j] === newRow[j - 1]) {
                            newRow[j] *= 2;
                            score += newRow[j];
                            newRow.splice(j - 1, 1);
                        }
                        if (board[i][j] !== newRow[boardSize - 1 - j]) {
                            board[i][j] = newRow[boardSize - 1 - j] || 0;
                            moved = true;
                        }
                    }
                }
                break;
        }
        if (moved) {
            addRandomTile();
        }
    }

    function drawBoard() {
        ctx.clearRect(0, 0, canvas.width, canvas.height);
        for (let i = 0; i < boardSize; i++) {
            for (let j = 0; j < boardSize; j++) {
                ctx.fillStyle = board[i][j] === 0 ? '#ccc' : '#fff';
                ctx.fillRect(i * 100, j * 100, 100, 100);
                if (board[i][j] !== 0) {
                    ctx.fillStyle = '#000';
                    ctx.fillText(board[i][j], i * 100 + 45, j * 100 + 60);
                }
            }
        }
        ctx.fillStyle = '#000';
        ctx.fillText('Score: ' + score, 10, 30);
    }

    function checkGameOver() {
        for (let i = 0; i < boardSize; i++) {
            for (let j = 0; j < boardSize; j++) {
                if (board[i][j] === 0) {
                    return false;
                }
                if ((i < boardSize - 1 && board[i][j] === board[i + 1][j]) ||
                    (j < boardSize - 1 && board[i][j] === board[i][j + 1])) {
                    return false;
                }
            }
        }
        return true;
    }

    function gameLoop() {
        if (checkGameOver()) {
            ctx.fillStyle = '#000';
            ctx.fillText('Game Over!', 10, 60);
            return;
        }
        drawBoard();
        requestAnimationFrame(gameLoop);
    }

    function handleKeyDown(event) {
        switch (event.key) {
            case 'ArrowUp':
                slide('up');
                break;
            case 'ArrowDown':
                slide('down');
                break;
            case 'ArrowLeft':
                slide('left');
                break;
            case 'ArrowRight':
                slide('right');
                break;
        }
    }

    window.addEventListener('resize', setCanvasSize);
    window.addEventListener('keydown', handleKeyDown);
    setCanvasSize();
    addRandomTile();
    addRandomTile();
    gameLoop();
})();
