function drawHealthBar() {
  ctx.fillStyle = '#f00';
  ctx.fillRect(10, 10, playerHealth, 20);
  ctx.fillStyle = '#000';
  ctx.strokeRect(10, 10, 100, 20);
}

function spawnEnemy() {
  enemies.push({
    x: 0,
    y: Math.random() * canvas.height
  });
}

function updateEnemies() {
  enemies.forEach((enemy, index) => {
    enemy.x += enemySpeed;
    if (enemy.x > canvas.width) {
      enemies.splice(index, 1);
      playerHealth -= 10;
    }
  });
}

function drawEnemies() {
  ctx.fillStyle = '#0f0';
  enemies.forEach(enemy => {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, 10, 0, Math.PI * 2);
    ctx.fill();
  });
}

function updateTowers() {
  towers.forEach(tower => {
    let closestEnemy = null;
    enemies.forEach(enemy => {
      const distance = Math.sqrt(Math.pow(tower.x - enemy.x, 2) + Math.pow(tower.y - enemy.y, 2));
      if (distance < towerRange) {
        if (!closestEnemy || distance < closestEnemy.distance) {
          closestEnemy = { enemy, distance };
        }
      }
    });
    if (closestEnemy) {
      closestEnemy.enemy.y -= towerDamage;
      if (closestEnemy.enemy.y <= 0) {
        enemies.splice(enemies.indexOf(closestEnemy.enemy), 1);
      }
    }
  });
}

