    if (newState === 'playing') {
        birdY = canvas.height / 2;
        birdVelocity = 0;
        pipes = [];
        score = 0;
    }
}

function drawRect(x, y, width, height, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x, y, width, height);
}

function drawText(text, x, y, color) {
    ctx.fillStyle = color;
    ctx.font = '20px Arial';
    ctx.fillText(text, x, y);
}

function update() {
    if (state === 'playing') {
        birdVelocity += gravity;
        birdY += birdVelocity;

        if (birdY + birdSize > canvas.height || birdY < 0) {
            setState('gameover');
        }

        pipes.forEach(pipe => {
            pipe.x -= pipeSpeed;
            if (pipe.x < -pipeWidth) {
                pipes.shift();
                score++;
            }
            if (birdY < pipe.y + pipeWidth || birdY + birdSize > pipe.y + pipeWidth + gapSize) {
                if (birdX + birdSize > pipe.x && birdX < pipe.x + pipeWidth) {
                    setState('gameover');
                }
            }
        });

        if (Math.random() < 0.02) {
            pipes.push({
                x: canvas.width,
                y: Math.random() * (canvas.height - gapSize - pipeWidth)
            });
        }
    }
