```js
// Constants
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const BALL_RADIUS = 10;
const PADDLE_WIDTH = 100;
const PADDLE_HEIGHT = 20;
const BRICK_WIDTH = 75;
const BRICK_HEIGHT = 20;
const BRICK_PADDING = 10;
const BRICK_OFFSET_TOP = 30;
const BRICK_OFFSET_LEFT = 30;
const PARTICLE_COUNT = 10;
const GRAVITY = 0.05;
const PARTICLE_SPEED = 1;
const FIXED_TIME_STEP = 1000 / 60;
const MAX_UPDATE_STEPS = 10;

// Colors
const BALL_COLOR = 'red';
const PADDLE_COLOR = 'blue';
const BRICK_COLOR = 'green';
const PARTICLE_COLOR = 'yellow';

// Game state
let lastTime = 0;
let paddle = { x: CANVAS_WIDTH / 2 - PADDLE_WIDTH / 2, y: CANVAS_HEIGHT - PADDLE_HEIGHT - 10, dx: 5 };
let ball = { x: CANVAS_WIDTH / 2, y: CANVAS_HEIGHT / 2, dx: 2, dy: -2, radius: BALL_RADIUS };
let bricks = [];
let particles = [];

// Initialize bricks
for (let row = 0; row < 5; row++) {
    for (let col = 0; col < 10; col++) {
        bricks.push({
            x: col * (BRICK_WIDTH + BRICK_PADDING) + BRICK_OFFSET_LEFT,
            y: row * (BRICK_HEIGHT + BRICK_PADDING) + BRICK_OFFSET_TOP,
            width: BRICK_WIDTH,
            height: BRICK_HEIGHT,
            alive: true
        });
    }
}

// Initialize canvas
const canvas = document.createElement('canvas');
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Particle system
function createParticle(x, y) {
    return {
        x: x,
        y: y,
        dx: (Math.random() - 0.5) * PARTICLE_SPEED,
        dy: (Math.random() - 0.5) * PARTICLE_SPEED,
        color: PARTICLE_COLOR,
        ttl: 20
    };
}

function updateParticles() {
    particles = particles.filter(particle => particle.ttl > 0);
    particles.forEach(particle => {
        particle.x += particle.dx;
        particle.y += particle.dy;
        particle.dy += GRAVITY;
        particle.ttl--;
    });
}

function drawParticles() {
    particles.forEach(particle => {
        ctx.fillStyle = particle.color;
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, 2, 0, Math.PI * 2);
        ctx.fill();
    });
}

// Collision detection
function detectCollisions() {
    // Ball with walls
    if (ball.x + ball.dx > CANVAS_WIDTH - ball.radius || ball.x + ball.dx < ball.radius) {
        ball.dx = -ball.dx;
    }
    if (ball.y + ball.dy > CANVAS_HEIGHT - ball.radius) {
        ball.dy = -ball.dy;
    }
    if (ball.y + ball.dy < ball.radius) {
        ball.dy = -ball.dy;
    }

    // Ball with paddle
    if (ball.y + ball.dy > CANVAS_HEIGHT - PADDLE_HEIGHT - ball.radius && 
        ball.x > paddle.x && ball.x < paddle.x + PADDLE_WIDTH) {
        ball.dy = -ball.dy;
    }

    // Ball with bricks
    bricks.forEach(brick => {
        if (brick.alive && ball.x + ball.radius > brick.x && 
            ball.x - ball.radius < brick.x + brick.width && 
            ball.y + ball.radius > brick.y && 
            ball.y - ball.radius < brick.y + brick.height) {
            ball.dy = -ball.dy;
            brick.alive = false;
            for (let i = 0; i < PARTICLE_COUNT; i++) {
                particles.push(createParticle(brick.x + brick.width / 2, brick.y + brick.height / 2));
            }
        }
    });
}

// Game loop
function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;

    let updateSteps = 0;
    while (deltaTime > FIXED_TIME_STEP && updateSteps < MAX_UPDATE_STEPS) {
        updateParticles();
        detectCollisions();
        ball.x += ball.dx;
        ball.y += ball.dy;
        paddle.x += paddle.dx;
        paddle.x = Math.max(0, Math.min(CANVAS_WIDTH - PADDLE_WIDTH, paddle.x));
        updateSteps++;
    }

    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw paddle
    ctx.fillStyle = PADDLE_COLOR;
    ctx.fillRect(paddle.x, paddle.y, PADDLE_WIDTH, PADDLE_HEIGHT);

    // Draw ball
    ctx.fillStyle = BALL_COLOR;
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
    ctx.fill();

    // Draw bricks
    bricks.forEach(brick => {
        if (brick.alive) {
            ctx.fillStyle = BRICK_COLOR;
            ctx.fillRect(brick.x, brick.y, brick.width, brick.height);
        }
    });

    // Draw particles
    drawParticles();

    requestAnimationFrame(gameLoop);
}

// Input handling
document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') {
        paddle.dx = -5;
    } else if (e.key === 'ArrowRight') {
        paddle.dx = 5;
    }
});

document.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
        paddle.dx = 0;
    }
});

// Start game loop
requestAnimationFrame(gameLoop);
