const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const ASTEROID_COUNT = 5;
const ASTEROID_SIZE = 30;
const ASTEROID_SPEED = 1;
const SHIP_SIZE = 20;
const SHIP_SPEED = 4;
const BULLET_SPEED = 8;
const COMBO_THRESHOLD = 5;
const COMBO_MULTIPLIER = 2;

let asteroids = [];
let ship = { x: canvas.width / 2, y: canvas.height / 2, angle: 0, dx: 0, dy: 0 };
let bullets = [];
let score = 0;
let combo = 0;
let lastTime = 0;

function getRandom(min, max) {
  return Math.random() * (max - min) + min;
}

function createAsteroid() {
  return {
    x: getRandom(0, canvas.width),
    y: getRandom(0, canvas.height),
    size: ASTEROID_SIZE,
    angle: getRandom(0, Math.PI * 2),
    speed: ASTEROID_SPEED
  };
}

function initializeAsteroids() {
  for (let i = 0; i < ASTEROID_COUNT; i++) {
    asteroids.push(createAsteroid());
  }
}

function updateAsteroids(deltaTime) {
  asteroids.forEach(asteroid => {
    asteroid.x += asteroid.speed * Math.cos(asteroid.angle) * deltaTime;
    asteroid.y += asteroid.speed * Math.sin(asteroid.angle) * deltaTime;
    if (asteroid.x < 0 || asteroid.x > canvas.width) asteroid.angle = Math.PI - asteroid.angle;
    if (asteroid.y < 0 || asteroid.y > canvas.height) asteroid.angle = -asteroid.angle;
  });
}

function drawAsteroids() {
  ctx.fillStyle = 'gray';
  asteroids.forEach(asteroid => {
    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.size, 0, Math.PI * 2);
    ctx.fill();
  });
}

function updateShip(deltaTime) {
  ship.x += ship.dx * deltaTime;
  ship.y += ship.dy * deltaTime;
  if (ship.x < 0) ship.x = 0;
  if (ship.x > canvas.width) ship.x = canvas.width;
  if (ship.y < 0) ship.y = 0;
  if (ship.y > canvas.height) ship.y = canvas.height;
}

function drawShip() {
  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);
  ctx.beginPath();
  ctx.moveTo(SHIP_SIZE, 0);
  ctx.lineTo(-SHIP_SIZE, SHIP_SIZE);
  ctx.lineTo(-SHIP_SIZE, -SHIP_SIZE);
  ctx.closePath();
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.restore();
}

function updateBullets(deltaTime) {
  bullets.forEach(bullet => {
    bullet.x += BULLET_SPEED * Math.cos(bullet.angle) * deltaTime;
    bullet.y += BULLET_SPEED * Math.sin(bullet.angle) * deltaTime;
  });
  bullets = bullets.filter(bullet => bullet.x > 0 && bullet.x < canvas.width && bullet.y > 0 && bullet.y < canvas.height);
}

function drawBullets() {
  ctx.fillStyle = 'yellow';
  bullets.forEach(bullet => {
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, 2, 0, Math.PI * 2);
    ctx.fill();
  });
}

function checkCollisions() {
  let newAsteroids = [];
  asteroids.forEach(asteroid => {
    let hit = false;
    bullets = bullets.filter(bullet => {
      if (Math.hypot(asteroid.x - bullet.x, asteroid.y - bullet.y) < asteroid.size) {
        score += Math.pow(2, ASTEROID_SIZE - asteroid.size) * (combo >= COMBO_THRESHOLD ? COMBO_MULTIPLIER : 1);
        combo++;
        hit = true;
        return false;
      }
      return true;
    });
    if (!hit) newAsteroids.push(asteroid);
  });
  asteroids = newAsteroids;
}

function drawScore() {
  ctx.fillStyle = 'white';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Combo: ${combo >= COMBO_THRESHOLD ? combo + 'x' : combo}`, 10, 50);
}

function gameLoop(timestamp) {
  let deltaTime = timestamp - lastTime;
  if (deltaTime > 1000 / 60) {
    lastTime = timestamp;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    updateAsteroids(deltaTime);
    updateShip(deltaTime);
    updateBullets(deltaTime);
    checkCollisions();
    drawAsteroids();
    drawShip();
    drawBullets();
    drawScore();
  }
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', event => {
  switch (event.key) {
    case 'ArrowLeft':
      ship.angle -= Math.PI / 36;
      break;
    case 'ArrowRight':
      ship.angle += Math.PI / 36;
      break;
    case 'ArrowUp':
      ship.dx += SHIP_SPEED * Math.cos(ship.angle);
      ship.dy += SHIP_SPEED * Math.sin(ship.angle);
      break;
    case 'ArrowDown':
      ship.dx -= SHIP_SPEED * Math.cos(ship.angle);
      ship.dy -= SHIP_SPEED * Math.sin(ship.angle);
      break;
    case ' ':
      bullets.push({ x: ship.x, y: ship.y, angle: ship.angle });
      combo = 0;
      break;
  }
});

document.addEventListener('keyup', event => {
  switch (event.key) {
    case 'ArrowUp':
    case 'ArrowDown':
      ship.dx = 0;
      ship.dy = 0;
      break;
  }
});

initializeAsteroids();
requestAnimationFrame(gameLoop);
