// BallDropGame.js

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const damping = 0.7;
const fixedTimestep = 1000 / 60; // 60 FPS
let lastTime = 0;
let countdown = 3;
let ball = { x: canvas.width / 2, y: 50, velocity: 0, radius: 10 };
let gameStarted = false;
let gameOver = false;

function startGame() {
    gameStarted = true;
    lastTime = performance.now();
    requestAnimationFrame(mainLoop);
}

function mainLoop(time) {
    if (!gameStarted) return;

    const dt = time - lastTime;
    if (dt < fixedTimestep) {
        requestAnimationFrame(mainLoop);
        return;
    }

    update(dt);
    render();
    lastTime = time;

    if (!gameOver) {
        requestAnimationFrame(mainLoop);
    }
}

function update(dt) {
    if (countdown > 0) {
        countdown -= dt / 1000;
        if (countdown < 0) countdown = 0;
        return;
    }

    if (!gameOver) {
        ball.velocity += gravity * fixedTimestep / 1000;
        ball.y += ball.velocity * fixedTimestep / 1000;

        if (ball.y + ball.radius >= canvas.height) {
            ball.y = canvas.height - ball.radius;
            ball.velocity *= -damping;
            if (Math.abs(ball.velocity) < 0.1) {
                gameOver = true;
            }
        }
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (countdown > 0) {
        ctx.font = '48px Arial';
        ctx.fillStyle = 'black';
        ctx.textAlign = 'center';
        ctx.fillText(countdown.toFixed(1), canvas.width / 2, canvas.height / 2);
    } else {
        ctx.beginPath();
        ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'red';
        ctx.fill();
    }

    if (gameOver) {
        ctx.font = '24px Arial';
        ctx.fillStyle = 'black';
        ctx.textAlign = 'center';
        ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 + 50);
    }
}

canvas.addEventListener('click', startGame);
