  if (ball.y + ball.radius > canvas.height) {
    currentState = states.GAMEOVER;
  }

  if (ball.y - ball.radius < 0) {
    score++;
    ball.dy *= 1.1; // Increase speed
    ball.y = ball.radius;
  }
}

function handleInput(event) {
  if (currentState === states.MENU) {
    if (event.code === 'Space') {
