    for (let i = 0; i < 4; i++) {
        let row = boardCopy[direction === 'up' || direction === 'down' ? i : 0];
        let newRow = [];
        for (let j = 0; j < 4; j++) {
            if (row[j] !== 0) newRow.push(row[j]);
        }
        for (let j = 0; j < newRow.length - 1; j++) {
            if (newRow[j] === newRow[j + 1]) {
                newRow[j] *= 2;
                newRow[j + 1] = 0;
