let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore'), 10) : 0;

function getRandomEmptyCell() {
  const emptyCells = [];
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      if (board[i][j] === 0) {
        emptyCells.push([i, j]);
      }
    }
  }
  return emptyCells[Math.floor(Math.random() * emptyCells.length)] || [0, 0];
}

function addNewTile() {
  const [i, j] = getRandomEmptyCell();
  board[i][j] = Math.random() > 0.9 ? 4 : 2;
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.strokeStyle = '#aaa';
  for (let i = 0; i <= gridSize; i++) {
    ctx.beginPath();
    ctx.moveTo(i * cellSize, 0);
    ctx.lineTo(i * cellSize, canvas.height);
    ctx.stroke();
    ctx.beginPath();
    ctx.moveTo(0, i * cellSize);
    ctx.lineTo(canvas.width, i * cellSize);
    ctx.stroke();
  }
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      const value = board[i][j];
      if (value !== 0) {
        ctx.fillStyle = colors[value] || colors.default;
        ctx.fillRect(j * cellSize + padding, i * cellSize + padding, cellSize - padding * 2, cellSize - padding * 2);
        ctx.font = 'bold 24px Arial';
        ctx.fillStyle = '#776e65';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(value, j * cellSize + cellSize / 2, i * cellSize + cellSize / 2);
      }
    }
  }
}

function move(direction) {
  let moved = false;
  let newBoard = Array.from({ length: gridSize }, () => Array(gridSize).fill(0));
  for (let i = 0; i < gridSize; i++) {
    let row = [];
    for (let j = 0; j < gridSize; j++) {
      const value = direction === 'up' ? board[j][i] : direction === 'down' ? board[gridSize - 1 - j][i] : direction === 'left' ? board[i][j] : board[i][gridSize - 1 - j];
      if (value !== 0) {
        row.push(value);
      }
    }
    row = merge(row);
    for (let j = 0; j < gridSize; j++) {
      const value = direction === 'up' ? row[j] : direction === 'down' ? row[gridSize - 1 - j] : direction === 'left' ? row[j] : row[gridSize - 1 - j];
      if (value !== (direction === 'up' ? board[j][i] : direction === 'down' ? board[gridSize - 1 - j][i] : direction === 'left' ? board[i][j] : board[i][gridSize - 1 - j])) {
        moved = true;
      }
      newBoard[i][j] = value;
    }
  }
  if (moved) {
    board = newBoard;
    addNewTile();
    if (checkGameOver()) {
      alert('Game Over! Your score: ' + score);
      resetGame();
    }
  }
}

function merge(row) {
  for (let i = 0; i < row.length - 1; i++) {
    if (row[i] !== 0 && row[i] === row[i + 1]) {
      row[i] *= 2;
      row[i + 1] = 0;
      score += row[i];
    }
  }
  return row.filter(x => x !== 0);
}

function checkGameOver() {
