  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.size, player.size);
}

function drawMaze() {
  ctx.fillStyle = 'black';
  maze.walls.forEach(wall => {
    ctx.fillRect(wall.x, wall.y, maze.cellSize, maze.cellSize);
  });
}

function drawGoal() {
  ctx.fillStyle = 'green';
  ctx.fillRect(goal.x, goal.y, goal.size, goal.size);
}

function drawComboMultiplier() {
  ctx.fillStyle = 'white';
  ctx.fillText(`Combo x${comboMultiplier.multiplier}`, 10, 20);
}

function checkCollision() {
  if (player.x < goal.x + goal.size &&
      player.x + player.size > goal.x &&
      player.y < goal.y + goal.size &&
      player.y + player.size > goal.y) {
    comboMultiplier.count++;
    comboMultiplier.multiplier = Math.min(comboMultiplier.count + 1, 10);
    player.x = 50;
    player.y = 50;
  }
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawPlayer();
  drawMaze();
  drawGoal();
  drawComboMultiplier();

  checkCollision();

  requestAnimationFrame(update);
}

function generateMaze() {
  for (let i = 0; i < maze.width; i += maze.cellSize) {
    for (let j = 0; j < maze.height; j += maze.cellSize) {
      if (Math.random() > 0.7) {
        maze.walls.push({ x: i, y: j });
      }
    }
  }
}

function movePlayer(event) {
  const key = event.key;
  const step = player.speed;

  if (key === 'ArrowRight') {
    player.direction = 'right';
    player.x += step;
  } else if (key === 'ArrowLeft') {
    player.direction = 'left';
    player.x -= step;
  } else if (key === 'ArrowUp') {
    player.direction = 'up';
    player.y -= step;
  } else if (key === 'ArrowDown') {
    player.direction = 'down';
    player.y += step;
  }

  // Simple collision detection with walls
  maze.walls.forEach(wall => {
    if (player.x < wall.x + maze.cellSize &&
        player.x + player.size > wall.x &&
        player.y < wall.y + maze.cellSize &&
        player.y + player.size > wall.y) {
      switch (player.direction) {
        case 'right': player.x -= step; break;
        case 'left': player.x += step; break;
        case 'up': player.y += step; break;
        case 'down': player.y -= step; break;
      }
    }
  });
}

document.addEventListener('keydown', movePlayer);
generateMaze();
update();
