const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const gridSize = 4;
const cellSize = 100;
const margin = 10;
const colors = {
  0: '#f0f0f0',
  2: '#eee4da',
  4: '#ede0c8',
  8: '#f2b179',
  16: '#f59563',
  32: '#f67c5f',
  64: '#f65e3b',
  128: '#edcf72',
  256: '#edcc61',
  512: '#edc850',
  1024: '#edc53f',
  2048: '#edc22e'
};

let grid = Array(gridSize).fill().map(() => Array(gridSize).fill(0));
let score = 0;
let combo = 0;
let lastTime = 0;
let gameOver = false;

function init() {
  addRandomTile();
  addRandomTile();
  requestAnimationFrame(mainLoop);
}

function addRandomTile() {
  const emptyCells = [];
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      if (grid[i][j] === 0) {
        emptyCells.push([i, j]);
      }
    }
  }
  if (emptyCells.length > 0) {
    const [x, y] = emptyCells[Math.floor(Math.random() * emptyCells.length)];
    grid[x][y] = Math.random() < 0.9 ? 2 : 4;
  }
}

function slide(row) {
  const filtered = row.filter(num => num !== 0);
  for (let i = 0; i < filtered.length - 1; i++) {
    if (filtered[i] === filtered[i + 1]) {
      filtered[i] *= 2;
      score += filtered[i];
      combo++;
      filtered.splice(i + 1, 1);
    }
  }
  while (filtered.length < gridSize) {
    filtered.push(0);
  }
  return filtered;
}

function move(direction) {
  let changed = false;
  if (direction === 'up' || direction === 'down') {
    for (let i = 0; i < gridSize; i++) {
      const column = [];
      for (let j = 0; j < gridSize; j++) {
        column.push(grid[direction === 'up' ? j : gridSize - 1 - j][i]);
      }
      const newColumn = slide(column);
      for (let j = 0; j < gridSize; j++) {
        if (grid[direction === 'up' ? j : gridSize - 1 - j][i] !== newColumn[j]) {
          changed = true;
        }
        grid[direction === 'up' ? j : gridSize - 1 - j][i] = newColumn[j];
      }
    }
  } else if (direction === 'left' || direction === 'right') {
    for (let i = 0; i < gridSize; i++) {
      const row = [...grid[i]];
      const newRow = slide(row);
      if (JSON.stringify(row) !== JSON.stringify(newRow)) {
        changed = true;
      }
      grid[i] = newRow;
    }
  }
  if (changed) {
    addRandomTile();
    combo = 0;
    checkGameOver();
  }
}

function checkGameOver() {
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      if (grid[i][j] === 0) {
        return;
      }
      if ((i < gridSize - 1 && grid[i][j] === grid[i + 1][j]) ||
          (j < gridSize - 1 && grid[i][j] === grid[i][j + 1])) {
        return;
      }
    }
  }
  gameOver = true;
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < gridSize; i++) {
    for (let j = 0; j < gridSize; j++) {
      const value = grid[i][j];
      const x = j * cellSize + margin;
      const y = i * cellSize + margin;
      ctx.fillStyle = colors[value];
      ctx.fillRect(x, y, cellSize - 2 * margin, cellSize - 2 * margin);
      if (value !== 0) {
        ctx.font = 'bold 48px Arial';
        ctx.fillStyle = '#776e65';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(value, x + cellSize / 2, y + cellSize / 2);
      }
    }
  }
  ctx.font = 'bold 24px Arial';
  ctx.fillStyle = '#776e65';
  ctx.textAlign = 'left';
  ctx.textBaseline = 'top';
  ctx.fillText(`Score: ${score}`, 10, 10);
  ctx.fillText(`Combo: ${combo}`, 10, 40);
  if (gameOver) {
    ctx.font = 'bold 48px Arial';
    ctx.fillStyle = '#776e65';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

function mainLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  if (!gameOver && deltaTime >= 100) {
    draw();
    lastTime = timestamp;
  }
  requestAnimationFrame(mainLoop);
}

document.addEventListener('keydown', (e) => {
  if (!gameOver) {
    switch (e.key) {
      case 'ArrowUp':
        move('up');
        break;
      case 'ArrowDown':
        move('down');
        break;
      case 'ArrowLeft':
        move('left');
        break;
      case 'ArrowRight':
        move('right');
        break;
    }
    requestAnimationFrame(mainLoop);
  }
});

init();
