        player.comboMultiplier += 0.1;
        if (enemy.health <= 0) {
            enemy.health = 0;
            console.log('Player wins!');
        }
        turn = 'enemy';
    } else {
        const damage = Math.max(enemy.attack - player.defense, 0);
        player.health -= damage;
        player.combo = 0;
        player.comboMultiplier = 1;
        if (player.health <= 0) {
            player.health = 0;
            console.log('Enemy wins!');
        }
        turn = 'player';
    }
}

// Game loop
