const BALL_SIZE = 10;
const PADDLE_WIDTH = 100;
const PADDLE_HEIGHT = 10;
const BRICK_WIDTH = 60;
const BRICK_HEIGHT = 20;
const BRICK_GAP = 10;
const ENEMY_SPAWN_INTERVAL = 5000; // milliseconds
const ENEMY_SPEED = 2;

let ball = { x: canvas.width / 2, y: canvas.height - PADDLE_HEIGHT - BALL_SIZE, vx: 4, vy: -4 };
let paddle = { x: canvas.width / 2 - PADDLE_WIDTH / 2, y: canvas.height - PADDLE_HEIGHT, width: PADDLE_WIDTH, height: PADDLE_HEIGHT, vx: 0 };
let bricks = [];
let enemies = [];
let lastTime = performance.now();
let spawnInterval = ENEMY_SPAWN_INTERVAL;

function createBricks() {
    bricks = [];
    for (let row = 0; row < 5; row++) {
        for (let col = 0; col < canvas.width / (BRICK_WIDTH + BRICK_GAP); col++) {
            bricks.push({ x: col * (BRICK_WIDTH + BRICK_GAP), y: row * (BRICK_HEIGHT + BRICK_GAP), width: BRICK_WIDTH, height: BRICK_HEIGHT });
        }
    }
}

function spawnEnemy() {
    enemies.push({ x: Math.random() * (canvas.width - 20), y: 0, vx: ENEMY_SPEED });
}

function update(delta) {
    // Update ball position
    ball.x += ball.vx * delta;
    ball.y += ball.vy * delta;

    // Ball collision with walls
    if (ball.x - BALL_SIZE / 2 < 0 || ball.x + BALL_SIZE / 2 > canvas.width) {
        ball.vx = -ball.vx;
    }
    if (ball.y - BALL_SIZE / 2 < 0) {
        ball.vy = -ball.vy;
    }
    if (ball.y + BALL_SIZE / 2 > canvas.height) {
        // Reset ball position
        ball.x = canvas.width / 2;
        ball.y = canvas.height - PADDLE_HEIGHT - BALL_SIZE;
    }

    // Ball collision with paddle
    if (ball.x > paddle.x && ball.x < paddle.x + paddle.width && ball.y + BALL_SIZE / 2 > paddle.y) {
        ball.vy = -ball.vy;
    }

    // Ball collision with bricks
    for (let i = bricks.length - 1; i >= 0; i--) {
        const brick = bricks[i];
        if (ball.x > brick.x && ball.x < brick.x + brick.width && ball.y > brick.y && ball.y < brick.y + brick.height) {
            bricks.splice(i, 1);
            ball.vy = -ball.vy;
            break;
        }
    }

    // Update paddle position
    paddle.x += paddle.vx * delta;

    // Paddle collision with walls
    if (paddle.x < 0) {
        paddle.x = 0;
    }
    if (paddle.x + paddle.width > canvas.width) {
        paddle.x = canvas.width - paddle.width;
    }

    // Update enemies
    for (let i = enemies.length - 1; i >= 0; i--) {
        const enemy = enemies[i];
        enemy.y += enemy.vx * delta;

        // Enemy collision with paddle
        if (enemy.x > paddle.x && enemy.x < paddle.x + paddle.width && enemy.y + 20 > paddle.y) {
            // Reset ball position
            ball.x = canvas.width / 2;
            ball.y = canvas.height - PADDLE_HEIGHT - BALL_SIZE;
            enemies.splice(i, 1);
            break;
        }

        // Enemy collision with walls
        if (enemy.y + 20 > canvas.height) {
            enemies.splice(i, 1);
            break;
        }
    }

    // Spawn enemy if interval has passed
    if (performance.now() - lastTime > spawnInterval) {
        spawnEnemy();
        lastTime = performance.now();
        spawnInterval *= 0.98; // Reduce spawn interval to increase difficulty
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw ball
    ctx.beginPath();
    ctx.arc(ball.x, ball.y, BALL_SIZE, 0, Math.PI * 2);
    ctx.fillStyle = '#000';
    ctx.fill();

    // Draw paddle
    ctx.fillStyle = '#000';
    ctx.fillRect(paddle.x, paddle.y, paddle.width, paddle.height);

    // Draw bricks
    ctx.fillStyle = '#333';
    bricks.forEach(brick => {
        ctx.fillRect(brick.x, brick.y, brick.width, brick.height);
    });

    // Draw enemies
    ctx.fillStyle = 'red';
    enemies.forEach(enemy => {
        ctx.fillRect(enemy.x, enemy.y, 20, 20);
    });
}

function gameLoop(timestamp) {
    const delta = timestamp - lastTime;
    lastTime = timestamp;

    update(delta);
    render();

    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    if (e.key === 'ArrowLeft') {
        paddle.vx = -5;
    } else if (e.key === 'ArrowRight') {
        paddle.vx = 5;
    }
});

document.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowLeft' || e.key === 'ArrowRight') {
        paddle.vx = 0;
    }
});

createBricks();
requestAnimationFrame(gameLoop);
