// HTML5 Canvas Top-Down Arena Shooter
// Features: High-score saved to localStorage, rendered with requestAnimationFrame

// Canvas setup
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game constants
const playerSize = 30;
const enemySize = 20;
const bulletSize = 10;
const enemySpeed = 2;
const bulletSpeed = 5;
const spawnInterval = 2000; // milliseconds
const maxEnemies = 10;

// Game state
let score = 0;
let highScore = localStorage.getItem('highScore') || 0;
let player = { x: canvas.width / 2, y: canvas.height / 2, angle: 0 };
let bullets = [];
let enemies = [];
let lastSpawnTime = 0;

// Load high score from localStorage
if (highScore) {
  highScore = parseInt(highScore, 10);
}

// Event listeners
canvas.addEventListener('mousemove', (e) => {
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  player.angle = Math.atan2(y - player.y, x - player.x);
});

canvas.addEventListener('click', () => {
  bullets.push({
    x: player.x + playerSize * Math.cos(player.angle),
    y: player.y + playerSize * Math.sin(player.angle),
    angle: player.angle
  });
});

// Game loop
function gameLoop() {
  requestAnimationFrame(gameLoop);

  // Update player
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.save();
  ctx.translate(player.x, player.y);
  ctx.rotate(player.angle);
  ctx.fillStyle = 'blue';
  ctx.fillRect(-playerSize / 2, -playerSize / 2, playerSize, playerSize);
  ctx.restore();

  // Update bullets
  for (let i = bullets.length - 1; i >= 0; i--) {
    const bullet = bullets[i];
    bullet.x += bulletSpeed * Math.cos(bullet.angle);
    bullet.y += bulletSpeed * Math.sin(bullet.angle);

    // Draw bullet
    ctx.fillStyle = 'red';
    ctx.fillRect(bullet.x - bulletSize / 2, bullet.y - bulletSize / 2, bulletSize, bulletSize);

    // Check for collisions with enemies
    for (let j = enemies.length - 1; j >= 0; j--) {
      const enemy = enemies[j];
      if (collides(bullet, enemy)) {
        enemies.splice(j, 1);
        bullets.splice(i, 1);
        score += 10;
        break;
      }
    }
  }

  // Spawn enemies
  if (Date.now() - lastSpawnTime > spawnInterval && enemies.length < maxEnemies) {
    spawnEnemy();
    lastSpawnTime = Date.now();
  }

  // Update enemies
  for (let i = enemies.length - 1; i >= 0; i--) {
    const enemy = enemies[i];
    enemy.x += enemySpeed * Math.cos(enemy.angle);
    enemy.y += enemySpeed * Math.sin(enemy.angle);

    // Wrap enemies around the screen
    if (enemy.x < 0) enemy.x = canvas.width;
    if (enemy.x > canvas.width) enemy.x = 0;
    if (enemy.y < 0) enemy.y = canvas.height;
    if (enemy.y > canvas.height) enemy.y = 0;

    // Draw enemy
    ctx.fillStyle = 'green';
    ctx.fillRect(enemy.x - enemySize / 2, enemy.y - enemySize / 2, enemySize, enemySize);

    // Check for collisions with player
    if (collides(player, enemy)) {
      gameOver();
    }
  }

  // Draw score and high score
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

// Spawn an enemy
function spawnEnemy() {
  const angle = Math.random() * Math.PI * 2;
  enemies.push({
    x: Math.random() * canvas.width,
    y: Math.random() * canvas.height,
    angle: angle
  });
}

// Check for collisions
function collides(a, b) {
  const distX = a.x - b.x;
  const distY = a.y - b.y;
  const dist = Math.sqrt(distX * distX + distY * distY);
  return dist < (a.size || playerSize) + (b.size || enemySize);
}

// Game over
function gameOver() {
  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }
  alert(`Game Over! Your score: ${score}. High Score: ${highScore}`);
  location.reload();
}

// Start the game
gameLoop();
