const noteSpeed = 2.5;
const noteSize = 20;
const tapRadius = 30;
let score = 0;
let level = 1;
let notes = [];
let lastNoteTime = 0;
let noteInterval = 1000; // milliseconds between notes

function random(min, max) {
  return Math.random() * (max - min) + min;
}

function createNote() {
  const x = random(0, w);
  notes.push({ x, y: -noteSize, size: noteSize, hit: false });
}

function updateNotes(delta) {
  notes.forEach(note => {
    note.y += noteSpeed * delta;
    if (note.y > h) {
      note.hit = true; // missed note
    }
  });
}

function drawNotes() {
  ctx.fillStyle = 'red';
  notes.forEach(note => {
    ctx.beginPath();
    ctx.arc(note.x, note.y, note.size, 0, Math.PI * 2);
    ctx.fill();
  });
}

function checkTaps(event) {
  const { clientX, clientY } = event;
  const localX = clientX * devicePixelRatio;
  const localY = clientY * devicePixelRatio;

  notes.forEach(note => {
    if (!note.hit && Math.hypot(localX - note.x, localY - note.y) < tapRadius) {
      note.hit = true;
      score++;
    }
  });
}

function clearMissedNotes() {
  notes = notes.filter(note => !note.hit);
}

function updateLevel() {
  if (notes.length === 0 && Date.now() - lastNoteTime > 2000) {
    level++;
    noteInterval = Math.max(500, noteInterval - 100);
  }
}

function update(delta) {
  updateNotes(delta);
  clearMissedNotes();
  updateLevel();
  createNote();
  lastNoteTime = Date.now();
}

function draw() {
  ctx.clearRect(0, 0, w, h);
  drawNotes();
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Level: ${level}`, 10, 50);
}

let lastTime = 0;
function gameLoop(timestamp) {
  const delta = timestamp - lastTime;
  lastTime = timestamp;

  update(delta);
  draw();

  requestAnimationFrame(gameLoop);
}

window.addEventListener('resize', () => {
  w = window.innerWidth;
  h = window.innerHeight;
  canvas.width = w * devicePixelRatio;
  canvas.height = h * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
});

