    fish.push({
      x: getRandom(FISH_SIZE, canvas.width - FISH_SIZE),
      y: getRandom(FISH_SIZE, canvas.height / 2),
      dx: getRandom(1, 3),
      dy: getRandom(1, 3)
    });
