      player.y + player.dy >= 0 && player.y + player.dy + player.size <= canvas.height &&
      maze[Math.floor((player.y + player.dy) / 40)][Math.floor((player.x + player.dx) / 40)] !== 1) {
    player.x += player.dx;
    player.y += player.dy;
  }
}

function updateAI() {
  const dx = player.x - ai.x;
  const dy = player.y - ai.y;
  const dist = Math.sqrt(dx * dx + dy * dy);

  if (dist > 0) {
    ai.dx = (dx / dist) * ai.speed;
    ai.dy = (dy / dist) * ai.speed;

    if (ai.x + ai.dx >= 0 && ai.x + ai.dx + ai.size <= canvas.width &&
        ai.y + ai.dy >= 0 && ai.y + ai.dy + ai.size <= canvas.height &&
        maze[Math.floor((ai.y + ai.dy) / 40)][Math.floor((ai.x + ai.dx) / 40)] !== 1) {
      ai.x += ai.dx;
      ai.y += ai.dy;
    }
  }
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawMaze();
  updatePlayer();
  updateAI();
  drawPlayer();
  drawAI();
