const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const tileSize = 32;
const gridWidth = canvas.width / tileSize;
const gridHeight = canvas.height / tileSize;

let lastTime = performance.now();
const fixedTimeStep = 1000 / 60; // 60 FPS

class Plot {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.isPlowed = false;
    this.isPlanted = false;
    this.plantGrowth = 0;
  }

  update(deltaTime) {
    if (this.isPlanted && this.plantGrowth < 1) {
      this.plantGrowth += deltaTime / 1000;
      if (this.plantGrowth > 1) this.plantGrowth = 1;
    }
  }

  draw() {
    ctx.fillStyle = this.isPlowed ? '#557f55' : '#a3c1a3';
    ctx.fillRect(this.x * tileSize, this.y * tileSize, tileSize, tileSize);
    if (this.isPlanted) {
      ctx.fillStyle = `rgb(0, 255, 0, ${this.plantGrowth})`;
      ctx.fillRect(this.x * tileSize + 4, this.y * tileSize + 4, tileSize - 8, tileSize - 8);
    }
  }

  plow() {
    this.isPlowed = !this.isPlowed;
  }

  plant() {
    if (this.isPlowed && !this.isPlanted) {
      this.isPlanted = true;
      this.plantGrowth = 0;
    }
  }
}

const plots = [];
for (let y = 0; y < gridHeight; y++) {
  for (let x = 0; x < gridWidth; x++) {
    plots.push(new Plot(x, y));
  }
}

function getPlotAt(x, y) {
  const gridX = Math.floor(x / tileSize);
  const gridY = Math.floor(y / tileSize);
  return plots[gridY * gridWidth + gridX];
}

canvas.addEventListener('click', (event) => {
  const rect = canvas.getBoundingClientRect();
  const plot = getPlotAt(event.clientX - rect.left, event.clientY - rect.top);
  if (plot) {
    if (event.shiftKey) {
      plot.plant();
    } else {
      plot.plow();
    }
  }
});

const keyActions = {
  'KeyP': (plot) => plot.plant(),
  'KeyT': (plot) => plot.plow(),
};

document.addEventListener('keydown', (event) => {
  const rect = canvas.getBoundingClientRect();
  const plot = getPlotAt(rect.left + canvas.width / 2, rect.top + canvas.height / 2);
  if (plot && keyActions[event.code]) {
    keyActions[event.code](plot);
  }
});

function update(deltaTime) {
  plots.forEach(plot => plot.update(deltaTime));
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  plots.forEach(plot => plot.draw());
}

