    if (!startTime) startTime = timestamp;
    const elapsed = timestamp - startTime;
    const minutesElapsed = elapsed / (1000 * 60);
    const expectedCharsTyped = minutesElapsed * targetSpeed;
    const accuracy = (score / expectedCharsTyped) || 0;

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.font = '24px Arial';
    ctx.fillText(text.substring(0, textIndex), 10, 50);
    ctx.fillText(`Score: ${score}`, 10, 80);
    ctx.fillText(`Accuracy: ${(accuracy * 100).toFixed(2)}%`, 10, 110);

    if (pointerDown) {
        const charIndex = Math.floor(pointerPosition.x / 25); // Assuming each char is 25px wide
        if (text[charIndex] === text[textIndex]) {
