const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let scale = window.devicePixelRatio;
let width = window.innerWidth;
let height = window.innerHeight;
canvas.width = width * scale;
canvas.height = height * scale;
ctx.scale(scale, scale);
canvas.style.width = width + 'px';
canvas.style.height = height + 'px';

const COLS = 8;
const ROWS = 8;
const GRID_SIZE = 40;
const COLORS = ['red', 'green', 'blue', 'yellow', 'purple', 'orange'];
let board = Array.from({ length: ROWS }, () =>
  Array.from({ length: COLS }, () => Math.floor(Math.random() * COLORS.length))
);

let score = 0;
let gameOver = false;

function drawBoard() {
  ctx.clearRect(0, 0, width, height);
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      ctx.fillStyle = COLORS[board[y][x]];
      ctx.fillRect(x * GRID_SIZE, y * GRID_SIZE, GRID_SIZE, GRID_SIZE);
      ctx.strokeRect(x * GRID_SIZE, y * GRID_SIZE, GRID_SIZE, GRID_SIZE);
    }
  }
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 30);
  if (gameOver) {
    ctx.font = '48px Arial';
    ctx.fillText('Game Over!', width / 2 - 100, height / 2);
  }
}

function checkMatches() {
  let matches = [];
  for (let y = 0; y < ROWS; y++) {
    for (let x = 0; x < COLS; x++) {
      let color = board[y][x];
      if (y < ROWS - 2 && board[y + 1][x] === color && board[y + 2][x] === color) {
        matches.push([[x, y], [x, y + 1], [x, y + 2]]);
      }
      if (x < COLS - 2 && board[y][x + 1] === color && board[y][x + 2] === color) {
        matches.push([[x, y], [x + 1, y], [x + 2, y]]);
      }
    }
  }
  return matches;
}

function clearMatches(matches) {
  let cleared = new Set();
  matches.forEach(match => {
    match.forEach(([x, y]) => cleared.add(`${x},${y}`));
  });
  matches.forEach(match => {
    match.forEach(([x, y]) => {
      board[y][x] = -1;
      score += 10;
    });
  });
  return cleared;
}

function dropPieces(cleared) {
  for (let x = 0; x < COLS; x++) {
    let drop = 0;
    for (let y = ROWS - 1; y >= 0; y--) {
      if (cleared.has(`${x},${y}`)) {
        drop++;
      } else if (drop > 0) {
        board[y + drop][x] = board[y][x];
        board[y][x] = -1;
      }
    }
  }
}

function fillBoard() {
  for (let x = 0; x < COLS; x++) {
    for (let y = ROWS - 1; y >= 0; y--) {
      if (board[y][x] === -1) {
        board[y][x] = Math.floor(Math.random() * COLORS.length);
      }
    }
  }
}

function gameLoop() {
  if (gameOver) return;
  let matches = checkMatches();
  if (matches.length > 0) {
    let cleared = clearMatches(matches);
    dropPieces(cleared);
    fillBoard();
  } else {
    gameOver = true;
  }
  drawBoard();
  requestAnimationFrame(gameLoop);
}

gameLoop();

