const BLOCK_SIZE = 20;
const COLORS = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];
const PARTICLE_COUNT = 20;

class Block {
    constructor(x, y, color) {
        this.x = x;
        this.y = y;
        this.color = color;
        this.falling = true;
    }

    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x * BLOCK_SIZE, this.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
    }

    update() {
        if (this.falling) {
            this.y++;
            this.falling = this.y * BLOCK_SIZE < canvas.height - BLOCK_SIZE;
        }
    }
}

class Particle {
    constructor(x, y, color) {
        this.x = x;
        this.y = y;
        this.color = color;
        this.life = 10;
    }

    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x * BLOCK_SIZE, this.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
    }

    update() {
        this.life--;
        this.y -= 0.1;
    }
}

let blocks = [];
let particles = [];

function createBlock() {
    const x = Math.floor(Math.random() * (canvas.width / BLOCK_SIZE));
    const color = COLORS[Math.floor(Math.random() * COLORS.length)];
    blocks.push(new Block(x, 0, color));
}

function createParticles(x, y, color) {
    for (let i = 0; i < PARTICLE_COUNT; i++) {
        particles.push(new Particle(x, y, color));
    }
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    blocks.forEach(block => {
        block.update();
        block.draw();
    });

    particles = particles.filter(particle => particle.life > 0);
    particles.forEach(particle => {
        particle.update();
        particle.draw();
    });

    if (blocks.some(block => block.y * BLOCK_SIZE >= canvas.height - BLOCK_SIZE)) {
        blocks = blocks.filter(block => block.y * BLOCK_SIZE < canvas.height - BLOCK_SIZE);
        createParticles(Math.random() * (canvas.width / BLOCK_SIZE), canvas.height / BLOCK_SIZE, COLORS[Math.floor(Math.random() * COLORS.length)]);
    }

    requestAnimationFrame(update);
}

setInterval(createBlock, 1000);
