const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const cardWidth = 100;
const cardHeight = 150;
const margin = 10;
const cols = Math.floor(canvas.width / (cardWidth + margin));
const rows = Math.floor(canvas.height / (cardHeight + margin));
const totalCards = cols * rows;
const cardPairs = Math.floor(totalCards / 2);

let cards = [];
let flippedCards = [];
let powerUps = [];
let powerUpTimer = 0;
let score = 0;
let lives = 3;
let gameover = false;

const powerUpTypes = {
  life: { color: 'green', effect: () => { lives++; } },
  score: { color: 'blue', effect: () => { score += 5; } },
  time: { color: 'red', effect: () => { powerUpTimer += 10; } }
};

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}

function createCards() {
  const cardImages = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H', 'I', 'J'];
  let images = [];
  for (let i = 0; i < cardPairs; i++) {
    images.push(cardImages[i % cardImages.length], cardImages[i % cardImages.length]);
  }
  shuffle(images);
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      cards.push({
        x: j * (cardWidth + margin),
        y: i * (cardHeight + margin),
        image: images[i * cols + j],
        flipped: false
      });
    }
  }
}

function createPowerUps() {
  const types = Object.keys(powerUpTypes);
  for (let i = 0; i < 5; i++) {
    powerUps.push({
      x: Math.random() * (canvas.width - 20),
      y: Math.random() * (canvas.height - 20),
      type: types[Math.floor(Math.random() * types.length)]
    });
  }
}

function drawCard(card) {
  ctx.strokeStyle = 'black';
  ctx.strokeRect(card.x, card.y, cardWidth, cardHeight);
  if (card.flipped) {
    ctx.fillStyle = 'lightblue';
    ctx.fillRect(card.x + 2, card.y + 2, cardWidth - 4, cardHeight - 4);
    ctx.font = '30px Arial';
    ctx.fillStyle = 'black';
    ctx.fillText(card.image, card.x + 30, card.y + 70);
  }
}

function drawPowerUp(powerUp) {
  ctx.fillStyle = powerUpTypes[powerUp.type].color;
  ctx.beginPath();
  ctx.arc(powerUp.x, powerUp.y, 10, 0, Math.PI * 2);
  ctx.fill();
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  cards.forEach(drawCard);
  powerUps.forEach(drawPowerUp);
  ctx.font = '20px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 20);
  ctx.fillText(`Lives: ${lives}`, 10, 40);
  if (gameover) {
    ctx.fillStyle = 'red';
    ctx.fillText('Game Over', canvas.width / 2 - 40, canvas.height / 2);
  }
  requestAnimationFrame(draw);
}

function flipCard(x, y) {
  if (gameover) return;
  const card = cards.find(c => x > c.x && x < c.x + cardWidth && y > c.y && y < c.y + cardHeight);
  if (card && !card.flipped) {
    card.flipped = true;
    flippedCards.push(card);
    if (flippedCards.length === 2) {
      setTimeout(() => {
        if (flippedCards[0].image !== flippedCards[1].image) {
          flippedCards.forEach(c => c.flipped = false);
          lives--;
        }
        flippedCards = [];
        if (lives === 0 || cards.every(c => c.flipped)) {
          gameover = true;
        }
      }, 1000);
    }
  }
}

function collectPowerUp(x, y) {
  powerUps = powerUps.filter(p => {
    const distance = Math.sqrt((p.x - x) ** 2 + (p.y - y) ** 2);
    if (distance < 10) {
      powerUpTypes[p.type].effect();
      return false;
    }
    return true;
  });
}

canvas.addEventListener('click', (event) => {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;
  flipCard(x, y);
  collectPowerUp(x, y);
});

createCards();
createPowerUps();
draw();
