const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let width, height;

function resizeCanvas() {
    width = window.innerWidth;
    height = window.innerHeight;
    canvas.width = width * devicePixelRatio;
    canvas.height = height * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);
    canvas.style.width = width + 'px';
    canvas.style.height = height + 'px';
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

const plotSize = 100;
let score = 0;
let gameOver = false;
let plantedPlots = [];
const plants = [
    { name: 'Tomato', value: 10, growthTime: 5000 },
    { name: 'Carrot', value: 5, growthTime: 3000 },
    { name: 'Potato', value: 8, growthTime: 4000 }
];

function Plant(x, y, plantType) {
    this.x = x;
    this.y = y;
    this.plantType = plantType;
    this.growthTimer = plantType.growthTime;
    this.grown = false;
}

Plant.prototype.update = function(dt) {
    if (!this.grown) {
        this.growthTimer -= dt;
        if (this.growthTimer <= 0) {
            this.grown = true;
            score += this.plantType.value;
        }
    }
};

Plant.prototype.draw = function() {
    ctx.fillStyle = this.grown ? 'green' : 'brown';
    ctx.fillRect(this.x, this.y, plotSize, plotSize);
    ctx.fillStyle = 'black';
    ctx.fillText(this.plantType.name, this.x + 5, this.y + 20);
};

function plantSeed(event) {
    if (gameOver) return;
    const x = Math.floor((event.clientX - canvas.offsetLeft) / plotSize) * plotSize;
    const y = Math.floor((event.clientY - canvas.offsetTop) / plotSize) * plotSize;
    if (plantedPlots.find(plant => plant.x === x && plant.y === y)) return;
    const plantType = plants[Math.floor(Math.random() * plants.length)];
    plantedPlots.push(new Plant(x, y, plantType));
}

canvas.addEventListener('click', plantSeed);

function update(dt) {
    plantedPlots.forEach(plant => plant.update(dt));
}

function draw() {
    ctx.clearRect(0, 0, width, height);
    plantedPlots.forEach(plant => plant.draw());
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 20);
    if (gameOver) {
        ctx.font = '48px Arial';
        ctx.fillText('Game Over!', width / 2 - 100, height / 2);
    }
}

function gameLoop(timestamp) {
    const dt = timestamp - lastTime;
    lastTime = timestamp;
    if (!gameOver) update(dt);
    draw();
    requestAnimationFrame(gameLoop);
}

let lastTime = performance.now();
requestAnimationFrame(gameLoop);

// Game Over condition
setTimeout(() => {
    gameOver = true;
}, 60000); // Game ends after 1 minute
