const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const gravity = 980; // pixels per second squared
const fixedTimeStep = 1 / 60; // 60 frames per second

const player = {
    x: 100,
    y: 100,
    width: 50,
    height: 50,
    velocityX: 0,
    velocityY: 0,
    jumpPower: -600,
    onGround: false,
    color: 'blue'
};

const platforms = [
    { x: 0, y: 550, width: 800, height: 50, color: 'green' },
    { x: 200, y: 400, width: 100, height: 20, color: 'green' },
    { x: 500, y: 300, width: 150, height: 20, color: 'green' }
];

const powerUps = [
    { x: 300, y: 500, width: 20, height: 20, color: 'red', collected: false },
    { x: 600, y: 400, width: 20, height: 20, color: 'red', collected: false }
];

let lastTime = performance.now();
let accumulatedTime = 0;

function update(dt) {
    player.velocityY += gravity * dt;
    player.x += player.velocityX * dt;
    player.y += player.velocityY * dt;

    // Collision with platforms
    for (let platform of platforms) {
        if (player.x < platform.x + platform.width &&
            player.x + player.width > platform.x &&
            player.y < platform.y + platform.height &&
            player.y + player.height > platform.y) {
            if (player.velocityY > 0) {
                player.y = platform.y - player.height;
                player.velocityY = 0;
                player.onGround = true;
            }
        }
    }

    // Collect power-ups
    for (let powerUp of powerUps) {
        if (!powerUp.collected &&
            player.x < powerUp.x + powerUp.width &&
            player.x + player.width > powerUp.x &&
            player.y < powerUp.y + powerUp.height &&
            player.y + player.height > powerUp.y) {
            powerUp.collected = true;
        }
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw player
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Draw platforms
    for (let platform of platforms) {
        ctx.fillStyle = platform.color;
        ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
    }

    // Draw power-ups
    for (let powerUp of powerUps) {
        if (!powerUp.collected) {
            ctx.fillStyle = powerUp.color;
            ctx.fillRect(powerUp.x, powerUp.y, powerUp.width, powerUp.height);
        }
    }
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;
    accumulatedTime += deltaTime;

    while (accumulatedTime >= fixedTimeStep) {
        update(fixedTimeStep);
        accumulatedTime -= fixedTimeStep;
    }

    render();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (event) => {
    switch (event.key) {
        case 'ArrowLeft':
            player.velocityX = -400;
            break;
        case 'ArrowRight':
            player.velocityX = 400;
            break;
        case 'Space':
            if (player.onGround) {
                player.velocityY = player.jumpPower;
                player.onGround = false;
            }
            break;
    }
});

document.addEventListener('keyup', (event) => {
    switch (event.key) {
        case 'ArrowLeft':
        case 'ArrowRight':
            player.velocityX = 0;
            break;
    }
});

requestAnimationFrame(gameLoop);
