const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TILE_SIZE = 100;
const GRID_SIZE = 4;
const FPS = 60;
const TIME_LIMIT = 30; // seconds

let grid = Array.from({ length: GRID_SIZE }, () => Array(GRID_SIZE).fill(0));
let score = 0;
let gameOver = false;
let timeLeft = TIME_LIMIT;
let lastTime = 0;

function getRandomTile() {
  const emptyTiles = [];
  for (let i = 0; i < GRID_SIZE; i++) {
    for (let j = 0; j < GRID_SIZE; j++) {
      if (grid[i][j] === 0) {
        emptyTiles.push([i, j]);
      }
    }
  }
  if (emptyTiles.length === 0) return null;
  const [x, y] = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
  grid[x][y] = Math.random() < 0.9 ? 2 : 4;
}

function drawTile(x, y, value) {
  ctx.fillStyle = `rgb(${255 - value * 10}, ${255 - value * 10}, ${255 - value * 10})`;
  ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
  ctx.fillStyle = 'white';
  ctx.font = 'bold 20px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText(value, x * TILE_SIZE + TILE_SIZE / 2, y * TILE_SIZE + TILE_SIZE / 2);
}

function drawGrid() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < GRID_SIZE; i++) {
    for (let j = 0; j < GRID_SIZE; j++) {
      drawTile(i, j, grid[i][j]);
    }
  }
}

function update() {
  if (gameOver) return;

  timeLeft -= 1 / FPS;
  if (timeLeft <= 0) {
    gameOver = true;
  }

  getRandomTile();
}

function mainLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  lastTime = timestamp;

  update();

  drawGrid();

  if (gameOver) {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'white';
    ctx.font = 'bold 30px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(`Game Over! Score: ${score}`, canvas.width / 2, canvas.height / 2);
  } else {
    requestAnimationFrame(mainLoop);
  }
}

document.addEventListener('keydown', (e) => {
  if (gameOver) return;

  let moved = false;

  switch (e.key) {
    case 'ArrowUp':
      for (let j = 0; j < GRID_SIZE; j++) {
        for (let i = 1; i < GRID_SIZE; i++) {
          if (grid[i][j] !== 0) {
            let k = i;
            while (k > 0 && grid[k - 1][j] === 0) {
              grid[k - 1][j] = grid[k][j];
              grid[k][j] = 0;
              k--;
              moved = true;
            }
            if (k > 0 && grid[k - 1][j] === grid[k][j]) {
              grid[k - 1][j] *= 2;
              score += grid[k - 1][j];
              grid[k][j] = 0;
              moved = true;
            }
          }
        }
      }
      break;
    case 'ArrowDown':
      for (let j = 0; j < GRID_SIZE; j++) {
        for (let i = GRID_SIZE - 2; i >= 0; i--) {
          if (grid[i][j] !== 0) {
            let k = i;
            while (k < GRID_SIZE - 1 && grid[k + 1][j] === 0) {
              grid[k + 1][j] = grid[k][j];
              grid[k][j] = 0;
              k++;
              moved = true;
            }
            if (k < GRID_SIZE - 1 && grid[k + 1][j] === grid[k][j]) {
              grid[k + 1][j] *= 2;
              score += grid[k + 1][j];
              grid[k][j] = 0;
              moved = true;
            }
          }
        }
      }
      break;
    case 'ArrowLeft':
      for (let i = 0; i < GRID_SIZE; i++) {
        for (let j = 1; j < GRID_SIZE; j++) {
          if (grid[i][j] !== 0) {
            let k = j;
            while (k > 0 && grid[i][k - 1] === 0) {
              grid[i][k - 1] = grid[i][k];
              grid[i][k] = 0;
              k--;
              moved = true;
            }
            if (k > 0 && grid[i][k - 1] === grid[i][k]) {
              grid[i][k - 1] *= 2;
              score += grid[i][k - 1];
              grid[i][k] = 0;
              moved = true;
            }
          }
        }
      }
      break;
    case 'ArrowRight':
      for (let i = 0; i < GRID_SIZE; i++) {
        for (let j = GRID_SIZE - 2; j >= 0; j--) {
          if (grid[i][j] !== 0) {
            let k = j;
            while (k < GRID_SIZE - 1 && grid[i][k + 1] === 0) {
              grid[i][k + 1] = grid[i][k];
              grid[i][k] = 0;
              k++;
              moved = true;
            }
            if (k < GRID_SIZE - 1 && grid[i][k + 1] === grid[i][k]) {
              grid[i][k + 1] *= 2;
              score += grid[i][k + 1];
              grid[i][k] = 0;
              moved = true;
            }
          }
        }
      }
      break;
  }

  if (moved) {
    getRandomTile();
  }
});

