const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const gridSize = 20;
const tileCount = canvas.width / gridSize;

const snake = [{ x: 10, y: 10 }];
let direction = { x: 0, y: 0 };
let food = { x: 15, y: 15 };
let powerUp = { x: 20, y: 20 };
let powerUpActive = false;
let powerUpTimer = 0;
let score = 0;
let gameOver = false;

const powerUpDuration = 10; // in seconds

function getRandomTile() {
    return Math.floor(Math.random() * tileCount);
}

function update() {
    if (gameOver) return;

    // Move snake
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };
    snake.unshift(head);

    // Check for collision with food
    if (head.x === food.x && head.y === food.y) {
        score++;
        food = { x: getRandomTile(), y: getRandomTile() };
        powerUp = { x: getRandomTile(), y: getRandomTile() };
        powerUpActive = true;
        powerUpTimer = powerUpDuration;
    } else {
        snake.pop();
    }

    // Check for collision with power-up
    if (head.x === powerUp.x && head.y === powerUp.y && powerUpActive) {
        score += 5;
        powerUpActive = false;
        powerUpTimer = 0;
    }

    // Check for collision with walls or self
    if (head.x < 0 || head.x >= tileCount || head.y < 0 || head.y >= tileCount || snake.some((segment, index) => index > 0 && segment.x === head.x && segment.y === head.y)) {
        gameOver = true;
    }

    // Update power-up timer
    if (powerUpActive) {
        powerUpTimer -= 1 / 60; // assuming 60fps
        if (powerUpTimer <= 0) {
            powerUpActive = false;
        }
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw snake
    ctx.fillStyle = 'green';
    snake.forEach(segment => {
        ctx.fillRect(segment.x * gridSize, segment.y * gridSize, gridSize, gridSize);
    });

    // Draw food
    ctx.fillStyle = 'red';
    ctx.fillRect(food.x * gridSize, food.y * gridSize, gridSize, gridSize);

    // Draw power-up
    if (powerUpActive) {
        ctx.fillStyle = 'blue';
        ctx.fillRect(powerUp.x * gridSize, powerUp.y * gridSize, gridSize, gridSize);
    }

    // Draw score
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 20);

    // Draw game over
    if (gameOver) {
        ctx.font = '48px Arial';
        ctx.fillStyle = 'red';
        ctx.fillText('Game Over', canvas.width / 4, canvas.height / 2);
    }
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTimestamp;
    if (deltaTime >= 1000 / 60) { // 60fps
        update();
        draw();
        lastTimestamp = timestamp;
    }
    requestAnimationFrame(gameLoop);
}

let lastTimestamp = 0;
requestAnimationFrame(gameLoop);

document.addEventListener('keydown', event => {
    switch (event.key) {
        case 'ArrowUp':
            if (direction.y === 0) direction = { x: 0, y: -1 };
            break;
        case 'ArrowDown':
            if (direction.y === 0) direction = { x: 0, y: 1 };
            break;
        case 'ArrowLeft':
            if (direction.x === 0) direction = { x: -1, y: 0 };
            break;
        case 'ArrowRight':
            if (direction.x === 0) direction = { x: 1, y: 0 };
            break;
    }
});
