// Falling Block Puzzle with Countdown Timer

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
let ctx = canvas.getContext('2d');

const BLOCK_SIZE = 30;
const BOARD_WIDTH = 10;
const BOARD_HEIGHT = 20;
let blocks = [];
let gameOver = false;
let countdown = 60;
let lastTime = 0;

function resizeCanvas() {
  const dpr = window.devicePixelRatio || 1;
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

function createBlock() {
  blocks.push({
    x: Math.floor(Math.random() * BOARD_WIDTH),
    y: -1,
    color: `rgb(${Math.random() * 255}, ${Math.random() * 255}, ${Math.random() * 255})`
  });
}

function moveBlocks() {
  blocks.forEach(block => block.y++);
}

function drawBlock(block) {
  ctx.fillStyle = block.color;
  ctx.fillRect(block.x * BLOCK_SIZE, block.y * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  blocks.forEach(drawBlock);
  ctx.fillStyle = 'black';
  ctx.fillText(`Time: ${countdown}`, 10, 20);
}

function checkCollision() {
  blocks.forEach(block => {
    if (block.y >= BOARD_HEIGHT || blocks.some(b => b.x === block.x && b.y === block.y + 1)) {
      gameOver = true;
    }
  });
}

function update() {
  if (gameOver) return;
  moveBlocks();
  checkCollision();
  if (blocks.some(block => block.y < 0)) gameOver = true;
  if (blocks.length === 0 || blocks[blocks.length - 1].y > 0) createBlock();
  countdown = Math.max(0, countdown - (Date.now() - lastTime) / 1000);
  lastTime = Date.now();
  if (countdown <= 0) gameOver = true;
}

function gameLoop() {
  update();
  drawBoard();
  if (!gameOver) requestAnimationFrame(gameLoop);
  else ctx.fillText('Game Over!', canvas.width / 2 - 50, canvas.height / 2);
}

gameLoop();
