// Memory Card Game with Health Bar and Respawn

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const cardWidth = 100;
const cardHeight = 150;
const margin = 10;
const columns = 4;
const rows = 4;
const totalCards = columns * rows;
const cardPairs = totalCards / 2;

let cards = [];
let flippedCards = [];
let playerHealth = 5;
let gameRunning = true;

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}

function createCard(x, y, pair) {
  return { x, y, pair, flipped: false, matched: false };
}

function createBoard() {
  let pairs = [];
  for (let i = 0; i < cardPairs; i++) {
    pairs.push(i + 1, i + 1);
  }
  shuffle(pairs);
  cards = [];
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < columns; j++) {
      cards.push(createCard(j * (cardWidth + margin), i * (cardHeight + margin), pairs[i * columns + j]));
    }
  }
}

function drawCard(card) {
  if (card.flipped) {
    ctx.fillStyle = '#fff';
    ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
    ctx.fillStyle = '#000';
    ctx.font = '30px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(card.pair, card.x + cardWidth / 2, card.y + cardHeight / 2);
  } else {
    ctx.fillStyle = '#ccc';
    ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
  }
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  cards.forEach(drawCard);
  ctx.fillStyle = 'red';
  ctx.fillRect(0, canvas.height - 30, playerHealth * 100, 30);
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Health: ${playerHealth}`, 10, canvas.height - 10);
}

function checkForMatch() {
  if (flippedCards.length === 2) {
    if (flippedCards[0].pair === flippedCards[1].pair) {
      flippedCards[0].matched = true;
      flippedCards[1].matched = true;
    } else {
      playerHealth--;
      if (playerHealth <= 0) {
        gameRunning = false;
      }
    }
    flippedCards = [];
  }
}

function handleClick(event) {
  if (!gameRunning) return;
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;
  cards.forEach(card => {
    if (!card.flipped && !card.matched && x > card.x && x < card.x + cardWidth && y > card.y && y < card.y + cardHeight) {
      card.flipped = true;
      flippedCards.push(card);
      checkForMatch();
    }
  });
}

canvas.addEventListener('click', handleClick);

function gameLoop() {
  drawBoard();
  if (gameRunning) {
    requestAnimationFrame(gameLoop);
  } else {
    ctx.fillStyle = 'black';
    ctx.font = '40px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
  }
}

createBoard();
gameLoop();
