const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let isRunning = true;
let playerX = 50;
let playerY = 50;
let playerSpeed = 5;
let playerHealth = 100;
let healthBarWidth = 200;
let healthBarHeight = 20;
let obstacleSpeed = 2;
let obstacles = [];
let score = 0;
let spawnInterval = 1000; // milliseconds
let lastSpawnTime = 0;

canvas.width = window.innerWidth;
canvas.height = window.innerHeight;

function handleResize() {
    canvas.width = window.innerWidth;
    canvas.height = window.innerHeight;
}

window.addEventListener('resize', handleResize);

function spawnObstacle() {
    obstacles.push({
        x: canvas.width,
        y: Math.random() * (canvas.height - 50) + 25,
        width: 30,
        height: 30
    });
}

function update() {
    if (!isRunning) return;

    const now = Date.now();
    if (now - lastSpawnTime > spawnInterval) {
        spawnObstacle();
        lastSpawnTime = now;
    }

    playerX += playerSpeed;
    if (playerX > canvas.width) {
        playerX = 0;
    }

    obstacles.forEach(obstacle => {
        obstacle.x -= obstacleSpeed;
        if (playerX < obstacle.x + obstacle.width &&
            playerX + 50 > obstacle.x &&
            playerY < obstacle.y + obstacle.height &&
            playerY + 50 > obstacle.y) {
            playerHealth -= 10;
            if (playerHealth <= 0) {
                resetGame();
            }
        }
    });

    obstacles = obstacles.filter(obstacle => obstacle.x + obstacle.width > 0);

    requestAnimationFrame(update);
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw player
    ctx.fillStyle = 'blue';
    ctx.fillRect(playerX, playerY, 50, 50);

    // Draw obstacles
    ctx.fillStyle = 'red';
    obstacles.forEach(obstacle => {
        ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
    });

    // Draw health bar
    ctx.fillStyle = 'green';
    ctx.fillRect(10, 10, (playerHealth / 100) * healthBarWidth, healthBarHeight);
    ctx.strokeStyle = 'black';
    ctx.strokeRect(10, 10, healthBarWidth, healthBarHeight);

    requestAnimationFrame(draw);
}

function resetGame() {
    isRunning = false;
    playerX = 50;
    playerY = 50;
    playerHealth = 100;
    obstacles = [];
    score = 0;
    lastSpawnTime = 0;
    setTimeout(() => {
        isRunning = true;
    }, 1000); // Wait 1 second before restarting
}

function startGame() {
    update();
    draw();
}

document.addEventListener('keydown', (event) => {
    if (event.key === ' ' && !isRunning) {
        startGame();
    }
});

startGame();
