const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const GRAVITY = 0.5;
const ENEMY_SPAWN_INTERVAL = 2000; // milliseconds
const BALL_RADIUS = 10;
const ENEMY_RADIUS = 15;
const BALL_COLOR = '#00FF00';
const ENEMY_COLOR = '#FF0000';
const BACKGROUND_COLOR = '#000000';

let lastTimestamp = 0;
let enemies = [];
let spawnInterval = ENEMY_SPAWN_INTERVAL;
let spawnTimer = spawnInterval;

class Ball {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.velocityY = 0;
  }

  update(deltaTime) {
    this.velocityY += GRAVITY * deltaTime;
    this.y += this.velocityY * deltaTime;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, BALL_RADIUS, 0, Math.PI * 2);
    ctx.fillStyle = BALL_COLOR;
    ctx.fill();
    ctx.closePath();
  }

  reset() {
    this.y = 50;
  }
}

class Enemy {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.velocityY = 0;
  }

  update(deltaTime) {
    this.velocityY += GRAVITY * deltaTime;
    this.y += this.velocityY * deltaTime;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, ENEMY_RADIUS, 0, Math.PI * 2);
    ctx.fillStyle = ENEMY_COLOR;
    ctx.fill();
    ctx.closePath();
  }

  isCollidingWith(ball) {
    return Math.hypot(this.x - ball.x, this.y - ball.y) < BALL_RADIUS + ENEMY_RADIUS;
  }
}

const ball = new Ball(canvas.width / 2, 50);

function spawnEnemy() {
  const x = Math.random() * canvas.width;
  const y = -ENEMY_RADIUS;
  enemies.push(new Enemy(x, y));
  spawnTimer = spawnInterval;
}

function update(deltaTime) {
  ball.update(deltaTime);
  enemies.forEach(enemy => enemy.update(deltaTime));
  enemies = enemies.filter(enemy => enemy.y < canvas.height + ENEMY_RADIUS);

  if (spawnTimer <= 0) {
    spawnEnemy();
    spawnInterval *= 0.95; // Increase difficulty
  } else {
    spawnTimer -= deltaTime;
  }
}

function draw() {
  ctx.fillStyle = BACKGROUND_COLOR;
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ball.draw();
  enemies.forEach(enemy => enemy.draw());
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTimestamp;
  lastTimestamp = timestamp;

  update(deltaTime);
  draw();

  requestAnimationFrame(gameLoop);
}

function handleKeyDown(event) {
  if (event.key === 'ArrowDown') {
    ball.reset();
  }
}

document.addEventListener('keydown', handleKeyDown);

requestAnimationFrame(gameLoop);
