  if (gameRunning) {
    if (e.key === textToType[currentTypedIndex]) {
      currentTypedIndex++;
      currentScore++;
      if (currentTypedIndex === textToType.length) {
        endGame();
      }
    }
  } else {
    startGame();
  }
});

function startGame() {
