  gameRunning = false;
}

function gameLoop(currentTime) {
  const deltaTime = currentTime - lastTime;
  if (deltaTime >= timestep) {
    update(deltaTime);
    render();
    lastTime = currentTime - (deltaTime % timestep);
  }
  requestAnimationFrame(gameLoop);
}

