const TILE_SIZE = 32;
const ROOM_WIDTH = 16;
const ROOM_HEIGHT = 12;
const ENEMY_SPEED = 1;
const PLAYER_SPEED = 2;

let level = 1;
let player = { x: ROOM_WIDTH / 2, y: ROOM_HEIGHT / 2, width: TILE_SIZE, height: TILE_SIZE };
let enemies = [];
let gameOver = false;

function generateRoom() {
    enemies = [];
    for (let i = 0; i < level * 3; i++) {
        enemies.push({
            x: Math.floor(Math.random() * ROOM_WIDTH) + 1,
            y: Math.floor(Math.random() * ROOM_HEIGHT) + 1,
            width: TILE_SIZE,
            height: TILE_SIZE
        });
    }
}

function movePlayer(dx, dy) {
    player.x += dx;
    player.y += dy;
    if (player.x < 0) player.x = 0;
    if (player.x > ROOM_WIDTH - 1) player.x = ROOM_WIDTH - 1;
    if (player.y < 0) player.y = 0;
    if (player.y > ROOM_HEIGHT - 1) player.y = ROOM_HEIGHT - 1;
}

function moveEnemies() {
    enemies.forEach(enemy => {
        const dx = player.x - enemy.x;
        const dy = player.y - enemy.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance > 0) {
            enemy.x += (dx / distance) * ENEMY_SPEED;
            enemy.y += (dy / distance) * ENEMY_SPEED;
        }
    });
}

function checkCollisions() {
    enemies.forEach(enemy => {
        if (player.x < enemy.x + enemy.width &&
            player.x + player.width > enemy.x &&
            player.y < enemy.y + enemy.height &&
            player.y + player.height > enemy.y) {
            gameOver = true;
        }
    });
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'black';
    ctx.fillRect(player.x * TILE_SIZE, player.y * TILE_SIZE, player.width, player.height);
    enemies.forEach(enemy => {
        ctx.fillStyle = 'red';
        ctx.fillRect(enemy.x * TILE_SIZE, enemy.y * TILE_SIZE, enemy.width, enemy.height);
    });
    if (gameOver) {
        ctx.fillStyle = 'white';
        ctx.font = '48px Arial';
        ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
    }
}

function update() {
    moveEnemies();
    checkCollisions();
    if (enemies.length === 0) {
        level++;
        generateRoom();
    }
}

function gameLoop() {
    if (!gameOver) {
        update();
    }
    render();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    if (gameOver) return;
    switch (e.key) {
        case 'ArrowUp':
            movePlayer(0, -1);
