class Entity {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }

  draw(ctx) {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, 20, 20);
  }
}

class Player extends Entity {
  constructor(x, y) {
    super(x, y);
    this.velocity = 5;
  }

  update(input) {
    if (input.left) this.x -= this.velocity;
    if (input.right) this.x += this.velocity;
    if (input.up) this.y -= this.velocity;
    if (input.down) this.y += this.velocity;
  }
}

class Enemy extends Entity {
  constructor(x, y) {
    super(x, y);
    this.velocity = 2;
  }

  update(player) {
    const dx = player.x - this.x;
    const dy = player.y - this.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance > 0) {
      this.x += (dx / distance) * this.velocity;
      this.y += (dy / distance) * this.velocity;
    }
  }
}

const player = new Player(canvas.width / 2, canvas.height / 2);
const enemies = [];
let spawnRate = 1000; // milliseconds
let nextSpawn = Date.now() + spawnRate;

function spawnEnemy() {
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  enemies.push(new Enemy(x, y));
  spawnRate *= 0.99; // Increase difficulty by decreasing spawn rate
  nextSpawn = Date.now() + spawnRate;
}

function update(input) {
  player.update(input);
  enemies.forEach(enemy => enemy.update(player));
  if (Date.now() > nextSpawn) {
    spawnEnemy();
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  player.draw(ctx);
  enemies.forEach(enemy => enemy.draw(ctx));
}

function gameLoop(timestamp) {
  const delta = timestamp - lastTime;
  lastTime = timestamp;
  lag += delta;

  while (lag >= MS_PER_UPDATE) {
    update(input);
    lag -= MS_PER_UPDATE;
  }

  render();
  requestAnimationFrame(gameLoop);
}

