const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const cardWidth = 100;
const cardHeight = 100;
const margin = 10;
const numPairs = 16;
const cards = [];
let flippedCards = [];
let lockBoard = false;
let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;

function createBoard() {
    const colors = ['#FF6347', '#4682B4', '#FFD700', '#32CD32', '#FF4500', '#00FFFF', '#FF1493', '#1E90FF'];
    const colorPairs = [...colors, ...colors].sort(() => 0.5 - Math.random());

    for (let i = 0; i < numPairs * 2; i++) {
        const x = (i % 8) * (cardWidth + margin);
        const y = Math.floor(i / 8) * (cardHeight + margin);
        cards.push({ x, y, color: colorPairs[i], flipped: false, matched: false });
    }
}

function drawCard(card) {
    ctx.fillStyle = card.flipped || card.matched ? card.color : '#FFFFFF';
    ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(card.x, card.y, cardWidth, cardHeight);
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    cards.forEach(card => drawCard(card));
    ctx.fillStyle = '#000';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function flipCard(card) {
    if (lockBoard) return;
    if (flippedCards.length === 2) return;
    if (card.flipped || card.matched) return;

    card.flipped = true;
    flippedCards.push(card);

    if (flippedCards.length === 2) {
        setTimeout(checkForMatch, 500);
    }
}

function checkForMatch() {
    const [card1, card2] = flippedCards;
    if (card1.color === card2.color) {
        card1.matched = true;
        card2.matched = true;
        score += 2;
    } else {
        card1.flipped = false;
        card2.flipped = false;
    }
    flippedCards = [];
    lockBoard = false;
    checkForWin();
}

function checkForWin() {
    if (cards.every(card => card.matched)) {
        if (score > highScore) {
            highScore = score;
            localStorage.setItem('highScore', highScore);
        }
        alert(`You win! High Score: ${highScore}`);
        score = 0;
        createBoard();
    }
}

canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;

    const clickedCard = cards.find(card => x > card.x && x < card.x + cardWidth && y > card.y && y < card.y + cardHeight);
    if (clickedCard) {
        flipCard(clickedCard);
    }
});

createBoard();

function gameLoop() {
    drawBoard();
    requestAnimationFrame(gameLoop);
}

gameLoop();
