const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const devicePixelRatio = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * devicePixelRatio;
canvas.height = window.innerHeight * devicePixelRatio;
ctx.scale(devicePixelRatio, devicePixelRatio);

const BOARD_SIZE = 8;
const TILE_SIZE = 50;
const COLORS = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];

class Tile {
  constructor(x, y, color) {
    this.x = x;
    this.y = y;
    this.color = color;
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x * TILE_SIZE, this.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(this.x * TILE_SIZE, this.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
  }
}

class Board {
  constructor() {
    this.grid = Array.from({ length: BOARD_SIZE }, () =>
      Array.from({ length: BOARD_SIZE }, () => new Tile(Math.floor(Math.random() * BOARD_SIZE), Math.floor(Math.random() * BOARD_SIZE), COLORS[Math.floor(Math.random() * COLORS.length)]))
    );
  }

  draw() {
    this.grid.forEach(row => row.forEach(tile => tile.draw()));
  }

  findMatches() {
    const matches = [];
    for (let y = 0; y < BOARD_SIZE; y++) {
      for (let x = 0; x < BOARD_SIZE - 2; x++) {
        if (this.grid[y][x].color === this.grid[y][x + 1].color && this.grid[y][x].color === this.grid[y][x + 2].color) {
          matches.push([this.grid[y][x], this.grid[y][x + 1], this.grid[y][x + 2]]);
        }
      }
    }
    for (let x = 0; x < BOARD_SIZE; x++) {
      for (let y = 0; y < BOARD_SIZE - 2; y++) {
        if (this.grid[y][x].color === this.grid[y + 1][x].color && this.grid[y][x].color === this.grid[y + 2][x].color) {
          matches.push([this.grid[y][x], this.grid[y + 1][x], this.grid[y + 2][x]]);
        }
      }
    }
    return matches;
  }

  clearMatches(matches) {
    matches.forEach(match => match.forEach(tile => {
      tile.color = 'transparent';
    }));
  }

  dropTiles() {
    for (let x = 0; x < BOARD_SIZE; x++) {
      let emptyY = BOARD_SIZE - 1;
      for (let y = BOARD_SIZE - 1; y >= 0; y--) {
        if (this.grid[y][x].color !== 'transparent') {
          if (y !== emptyY) {
            this.grid[emptyY][x].color = this.grid[y][x].color;
            this.grid[y][x].color = 'transparent';
          }
          emptyY--;
        }
      }
    }
  }

  refillBoard() {
    for (let x = 0; x < BOARD_SIZE; x++) {
      for (let y = 0; y < BOARD_SIZE; y++) {
        if (this.grid[y][x].color === 'transparent') {
          this.grid[y][x].color = COLORS[Math.floor(Math.random() * COLORS.length)];
        }
      }
    }
  }

  update() {
    const matches = this.findMatches();
    if (matches.length > 0) {
      this.clearMatches(matches);
      this.dropTiles();
      this.refillBoard();
    }
  }
}

class AI {
  constructor(board) {
    this.board = board;
  }

  makeMove() {
    const matches = this.board.findMatches();
    if (matches.length > 0) {
      const match = matches[Math.floor(Math.random() * matches.length)];
      match.forEach(tile => {
        tile.color = COLORS[Math.floor(Math.random() * COLORS.length)];
      });
    }
  }
}

const board = new Board();
const ai = new AI(board);

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  board.draw();
  ai.makeMove();
  board.update();
  requestAnimationFrame(gameLoop);
}

gameLoop();

window.addEventListener('resize', () => {
  canvas.width = window.innerWidth * devicePixelRatio;
  canvas.height = window.innerHeight * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
});
