const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const jumpVelocity = -10;
const moveSpeed = 5;
const fixedTimestep = 1 / 60; // 60 FPS

let lastTime = performance.now();
let accumulator = 0;

class Player {
    constructor(x, y, width, height) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.velocityY = 0;
        this.isJumping = false;
    }

    update(delta) {
        if (keys.left) this.x -= moveSpeed * delta;
        if (keys.right) this.x += moveSpeed * delta;

        if (this.isJumping) {
            this.velocityY += gravity;
            this.y += this.velocityY * delta;
            if (this.y > canvas.height - this.height) {
                this.y = canvas.height - this.height;
                this.isJumping = false;
                this.velocityY = 0;
            }
        }
    }

    draw() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }
}

const player = new Player(100, canvas.height - 50, 50, 50);

const keys = {
    left: false,
    right: false,
    space: false
};

document.addEventListener('keydown', (e) => {
    if (e.code === 'ArrowLeft') keys.left = true;
    if (e.code === 'ArrowRight') keys.right = true;
    if (e.code === 'Space' && !player.isJumping) {
        player.isJumping = true;
        player.velocityY = jumpVelocity;
    }
});

document.addEventListener('keyup', (e) => {
    if (e.code === 'ArrowLeft') keys.left = false;
    if (e.code === 'ArrowRight') keys.right = false;
});

canvas.addEventListener('mousedown', (e) => {
    if (e.clientX > player.x && e.clientX < player.x + player.width &&
        e.clientY > player.y && e.clientY < player.y + player.height) {
        if (!player.isJumping) {
            player.isJumping = true;
            player.velocityY = jumpVelocity;
        }
    }
});

function mainLoop(currentTime) {
    const delta = (currentTime - lastTime) / 1000;
    lastTime = currentTime;
    accumulator += delta;

    while (accumulator >= fixedTimestep) {
        player.update(fixedTimestep);
        accumulator -= fixedTimestep;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);
    player.draw();

    requestAnimationFrame(mainLoop);
}

requestAnimationFrame(mainLoop);
