  x: width / 2,
  y: height / 2,
  radius: 10,
  speed: 4,
  rotation: 0,
  health: 3
};

const keys = {
  up: false,
  left: false,
  right: false,
  space: false
};

document.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowUp': keys.up = true; break;
    case 'ArrowLeft': keys.left = true; break;
    case 'ArrowRight': keys.right = true; break;
    case ' ': keys.space = true; break;
  }
});

document.addEventListener('keyup', (e) => {
  switch (e.key) {
    case 'ArrowUp': keys.up = false; break;
    case 'ArrowLeft': keys.left = false; break;
    case 'ArrowRight': keys.right = false; break;
    case ' ': keys.space = false; break;
  }
});

function drawPlayer() {
  ctx.save();
  ctx.translate(player.x, player.y);
  ctx.rotate(player.rotation);
  ctx.beginPath();
  ctx.moveTo(0, -player.radius);
  ctx.lineTo(player.radius, player.radius);
  ctx.lineTo(-player.radius, player.radius);
  ctx.closePath();
  ctx.fillStyle = 'green';
  ctx.fill();
  ctx.restore();
}

function updatePlayer() {
  if (keys.left) player.rotation -= 0.05;
  if (keys.right) player.rotation += 0.05;
  if (keys.up) {
    player.x += player.speed * Math.cos(player.rotation);
    player.y += player.speed * Math.sin(player.rotation);
  }
  player.x = (player.x + width) % width;
  player.y = (player.y + height) % height;
}

function drawHealthBar() {
  ctx.fillStyle = 'red';
  ctx.fillRect(10, 10, 100, 10);
  ctx.fillStyle = 'green';
  ctx.fillRect(10, 10, (player.health / 3) * 100, 10);
}

function gameLoop() {
  ctx.clearRect(0, 0, width, height);
  updatePlayer();
  drawPlayer();
  drawHealthBar();
  requestAnimationFrame(gameLoop);
}

gameLoop();
