// Ball-drop game with basic AI opponent

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const DPR = window.devicePixelRatio;
canvas.width = window.innerWidth * DPR;
canvas.height = window.innerHeight * DPR;
ctx.scale(DPR, DPR);

const gravity = 0.5;
const bounce = -0.7;
const ballRadius = 10;
const paddleWidth = 100;
const paddleHeight = 10;
const paddleSpeed = 5;
const aiPaddleSpeed = 3;

let ball = {
  x: canvas.width / 2,
  y: canvas.height / 2,
  dx: 2,
  dy: -2
};

let playerPaddle = {
  x: (canvas.width - paddleWidth) / 2,
  y: canvas.height - paddleHeight - 10,
  width: paddleWidth,
  height: paddleHeight
};

let aiPaddle = {
  x: (canvas.width - paddleWidth) / 2,
  y: 10,
  width: paddleWidth,
  height: paddleHeight
};

let leftPressed = false;
let rightPressed = false;

function drawBall() {
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ballRadius, 0, Math.PI * 2);
  ctx.fillStyle = '#0095DD';
  ctx.fill();
  ctx.closePath();
}

function drawPaddle(paddle) {
  ctx.beginPath();
  ctx.rect(paddle.x, paddle.y, paddle.width, paddle.height);
  ctx.fillStyle = '#0095DD';
  ctx.fill();
  ctx.closePath();
}

function movePaddle(paddle, left, right) {
  if (left && paddle.x > 0) {
    paddle.x -= paddleSpeed;
  }
  if (right && paddle.x < canvas.width - paddle.width) {
    paddle.x += paddleSpeed;
  }
}

function moveAIPaddle() {
  if (ball.x < aiPaddle.x + aiPaddle.width / 2) {
    aiPaddle.x -= aiPaddleSpeed;
  } else if (ball.x > aiPaddle.x + aiPaddle.width / 2) {
    aiPaddle.x += aiPaddleSpeed;
  }
}

function updateGame() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Move player paddle
  movePaddle(playerPaddle, leftPressed, rightPressed);

  // Move AI paddle
  moveAIPaddle();

  // Update ball position
  ball.x += ball.dx;
  ball.y += ball.dy;

  // Collision with walls
  if (ball.x + ball.dx > canvas.width - ballRadius || ball.x + ball.dx < ballRadius) {
    ball.dx = -ball.dx;
  }
  if (ball.y + ball.dy < ballRadius) {
    ball.dy = -ball.dy;
  } else if (ball.y + ball.dy > canvas.height - ballRadius) {
    if (ball.x > playerPaddle.x && ball.x < playerPaddle.x + playerPaddle.width) {
      ball.dy = bounce * Math.abs(ball.dy);
      ball.dx = (ball.x - (playerPaddle.x + playerPaddle.width / 2)) / playerPaddle.width * 6;
    } else if (ball.y + ball.dy > canvas.height) {
      // Reset ball
      ball.x = canvas.width / 2;
      ball.y = canvas.height / 2;
      ball.dx = 2;
      ball.dy = -2;
    }
  }

  // Collision with AI paddle
  if (ball.y + ball.dy < ballRadius) {
    if (ball.x > aiPaddle.x && ball.x < aiPaddle.x + aiPaddle.width) {
      ball.dy = -bounce * Math.abs(ball.dy);
      ball.dx = (ball.x - (aiPaddle.x + aiPaddle.width / 2)) / aiPaddle.width * 6;
    }
  }

  // Draw everything
  drawBall();
  drawPaddle(playerPaddle);
  drawPaddle(aiPaddle);

  requestAnimationFrame(updateGame);
}

document.addEventListener('keydown', keyDownHandler, false);
document.addEventListener('keyup', keyUpHandler, false);

function keyDownHandler(e) {
  if (e.key === 'Left' || e.key === 'ArrowLeft') {
    leftPressed = true;
  } else if (e.key === 'Right' || e.key === 'ArrowRight') {
    rightPressed = true;
  }
}

function keyUpHandler(e) {
  if (e.key === 'Left' || e.key === 'ArrowLeft') {
    leftPressed = false;
  } else if (e.key === 'Right' || e.key === 'ArrowRight') {
    rightPressed = false;
  }
}

updateGame();
