  ctx.fillStyle = 'gray';
  for (let y = 0; y < maze.length; y++) {
    for (let x = 0; x < maze[y].length; x++) {
      if (maze[y][x] === 1) {
        ctx.fillRect(x * wallSize, y * wallSize, wallSize, wallSize);
      }
    }
  }
