  const speed = player.speed;
  if (keys['ArrowUp'] && player.y > 0) player.y -= speed;
  if (keys['ArrowDown'] && player.y < canvas.height - player.size) player.y += speed;
  if (keys['ArrowLeft'] && player.x > 0) player.x -= speed;
  if (keys['ArrowRight'] && player.x < canvas.width - player.size) player.x += speed;
}

function updateEnemies() {
  enemies.forEach(enemy => {
    const dx = player.x - enemy.x;
    const dy = player.y - enemy.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    if (distance > 0) {
      enemy.x += (dx / distance) * enemy.speed;
      enemy.y += (dy / distance) * enemy.speed;
    }
  });
}

function checkCollision() {
  enemies.forEach(enemy => {
    if (Math.abs(player.x - enemy.x) < player.size + enemy.size &&
        Math.abs(player.y - enemy.y) < player.size + enemy.size) {
      gameOver = true;
    }
  });
}

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function drawGameOver() {
  ctx.fillStyle = 'black';
  ctx.font = '40px Arial';
  ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
}

function gameLoop(timestamp) {
