    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawMaze();
    drawEnemies();
    drawPlayer();
    drawGameOver();
    return;
  }

  updatePlayer();
  updateEnemies();
  checkCollision();

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawMaze();
  drawEnemies();
  drawPlayer();
  drawScore();

  score++;
  requestAnimationFrame(gameLoop);
}

