  x: canvas.width / 2,
  y: canvas.height / 2,
  size: 10,
  speed: 5,
  combo: 0,
  maxCombo: 5
};

const enemies = [];
const bullets = [];

const enemySpeed = 2;
const enemySize = 15;
const spawnInterval = 1000; // milliseconds
let lastSpawnTime = Date.now();

function spawnEnemy() {
  const x = Math.random() * canvas.width;
  const y = Math.random() * canvas.height;
  enemies.push({ x, y, size: enemySize });
}

function update() {
  const now = Date.now();
  if (now - lastSpawnTime > spawnInterval) {
    spawnEnemy();
    lastSpawnTime = now;
  }

  // Player movement
  if (keys['ArrowUp'] && player.y > 0) player.y -= player.speed;
  if (keys['ArrowDown'] && player.y < canvas.height - player.size) player.y += player.speed;
  if (keys['ArrowLeft'] && player.x > 0) player.x -= player.speed;
  if (keys['ArrowRight'] && player.x < canvas.width - player.size) player.x += player.speed;

  // Bullet movement
  bullets.forEach((bullet, index) => {
    bullet.y -= 5;
    if (bullet.y < 0) {
      bullets.splice(index, 1);
    }
  });

  // Collision detection
  bullets.forEach((bullet, bulletIndex) => {
    enemies.forEach((enemy, enemyIndex) => {
      if (
        bullet.x < enemy.x + enemy.size &&
        bullet.x + player.size > enemy.x &&
        bullet.y < enemy.y + enemy.size &&
        bullet.size + bullet.y > enemy.y
      ) {
        enemies.splice(enemyIndex, 1);
        bullets.splice(bulletIndex, 1);
        player.combo++;
        if (player.combo > player.maxCombo) player.maxCombo++;
      }
    });
  });

  // Enemy movement
  enemies.forEach(enemy => {
    enemy.y += enemySpeed;
    if (enemy.y > canvas.height) {
      enemies.shift();
      player.combo = 0;
    }
  });
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.size, player.size);

  // Draw enemies
  ctx.fillStyle = 'red';
  enemies.forEach(enemy => {
    ctx.fillRect(enemy.x, enemy.y, enemy.size, enemy.size);
  });

  // Draw bullets
  ctx.fillStyle = 'yellow';
  bullets.forEach(bullet => {
    ctx.fillRect(bullet.x, bullet.y, player.size / 2, player.size / 2);
  });

  // Draw combo
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Combo: ${player.combo}`, 10, 30);
}

function shoot() {
  bullets.push({ x: player.x + player.size / 2, y: player.y });
}

