  keys[e.key] = true;
  if (e.key === ' ') shoot();
});

window.addEventListener('keyup', e => {
  keys[e.key] = false;
});

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

gameLoop();
