const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const boardSize = 8;
const cellSize = canvas.width / boardSize;
const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];
let board = [];
let score = 0;
let level = 1;
let selected = null;

function initBoard() {
  for (let i = 0; i < boardSize; i++) {
    board[i] = [];
    for (let j = 0; j < boardSize; j++) {
      board[i][j] = Math.floor(Math.random() * colors.length);
    }
  }
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < boardSize; i++) {
    for (let j = 0; j < boardSize; j++) {
      ctx.fillStyle = colors[board[i][j]];
      ctx.fillRect(i * cellSize, j * cellSize, cellSize, cellSize);
      ctx.strokeStyle = '#000';
      ctx.strokeRect(i * cellSize, j * cellSize, cellSize, cellSize);
    }
  }
}

function checkMatches() {
  let matches = [];
  for (let i = 0; i < boardSize; i++) {
    for (let j = 0; j < boardSize - 2; j++) {
      if (board[i][j] === board[i][j + 1] && board[i][j] === board[i][j + 2]) {
        matches.push([i, j], [i, j + 1], [i, j + 2]);
      }
    }
  }
  for (let j = 0; j < boardSize; j++) {
    for (let i = 0; i < boardSize - 2; i++) {
      if (board[i][j] === board[i + 1][j] && board[i][j] === board[i + 2][j]) {
        matches.push([i, j], [i + 1, j], [i + 2, j]);
      }
    }
  }
  return matches;
}

function clearMatches(matches) {
  matches.forEach(([i, j]) => {
    board[i][j] = null;
  });
}

function dropTiles() {
  for (let i = 0; i < boardSize; i++) {
    let empty = [];
    for (let j = 0; j < boardSize; j++) {
      if (board[i][j] === null) {
        empty.push(j);
      } else if (empty.length > 0) {
        board[i][empty.shift()] = board[i][j];
        board[i][j] = null;
      }
    }
  }
}

function fillGaps() {
  for (let i = 0; i < boardSize; i++) {
    for (let j = boardSize - 1; j >= 0; j--) {
      if (board[i][j] === null) {
        board[i][j] = Math.floor(Math.random() * colors.length);
      }
    }
  }
}

function handleSwap(x1, y1, x2, y2) {
  [board[x1][y1], board[x2][y2]] = [board[x2][y2], board[x1][y1]];
  const matches = checkMatches();
  if (matches.length > 0) {
    clearMatches(matches);
    dropTiles();
    fillGaps();
    score += matches.length;
  } else {
    [board[x1][y1], board[x2][y2]] = [board[x2][y2], board[x1][y1]];
  }
  selected = null;
}

canvas.addEventListener('click', (e) => {
  const x = Math.floor(e.offsetX / cellSize);
  const y = Math.floor(e.offsetY / cellSize);
  if (selected) {
    handleSwap(selected[0], selected[1], x, y);
  } else {
    selected = [x, y];
  }
});

function update() {
  drawBoard();
  requestAnimationFrame(update);
}

function nextLevel() {
  level++;
  initBoard();
  score = 0;
}

function checkLevelProgression() {
  // Example: increase level when score reaches a multiple of 100
  if (score >= level * 100) {
    nextLevel();
  }
}

function gameLoop() {
  checkLevelProgression();
  update();
}

initBoard();
gameLoop();
