// Tower Defense Skirmish with Countdown Timer

// Canvas setup
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game settings
const ENEMY_SPEED = 2;
const TOWER_RANGE = 100;
const TOWER_DAMAGE = 10;
const TOWER_COST = 50;
const ENEMY_HEALTH = 20;
const ENEMY_COUNTDOWN = 2000; // milliseconds
const GAME_DURATION = 60000; // milliseconds

// Game state
let enemies = [];
let towers = [];
let gold = 200;
let countdown = GAME_DURATION;
let gameOver = false;

// Enemy class
class Enemy {
    constructor() {
        this.x = 0;
        this.y = Math.random() * (canvas.height - 20);
        this.health = ENEMY_HEALTH;
    }

    update() {
        this.x += ENEMY_SPEED;
        if (this.x > canvas.width) {
            gameOver = true;
        }
    }

    draw() {
        ctx.fillStyle = 'red';
        ctx.fillRect(this.x, this.y, 20, 20);
    }

    isDead() {
        return this.health <= 0;
    }

    damage(amount) {
        this.health -= amount;
    }
}

// Tower class
class Tower {
    constructor(x, y) {
        this.x = x;
        this.y = y;
    }

    update() {
        for (let i = enemies.length - 1; i >= 0; i--) {
            const enemy = enemies[i];
            const distance = Math.sqrt((this.x - enemy.x) ** 2 + (this.y - enemy.y) ** 2);
            if (distance < TOWER_RANGE) {
                enemy.damage(TOWER_DAMAGE);
                if (enemy.isDead()) {
                    enemies.splice(i, 1);
                }
                break;
            }
        }
    }

    draw() {
        ctx.fillStyle = 'green';
        ctx.fillRect(this.x - 5, this.y - 5, 10, 10);
    }
}

// Place tower
function placeTower(x, y) {
    if (gold >= TOWER_COST) {
        towers.push(new Tower(x, y));
        gold -= TOWER_COST;
    }
}

// Game loop
function gameLoop(timestamp) {
    if (gameOver) {
        ctx.fillStyle = 'black';
        ctx.fillRect(0, 0, canvas.width, canvas.height);
        ctx.fillStyle = 'white';
        ctx.font = '30px Arial';
        ctx.fillText('Game Over!', canvas.width / 2 - 80, canvas.height / 2);
        return;
    }

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Update countdown
    countdown = Math.max(0, countdown - timestamp);
    if (countdown <= 0) {
        gameOver = true;
    }

    // Spawn enemies
    if (timestamp % ENEMY_COUNTDOWN === 0) {
        enemies.push(new Enemy());
    }

    // Update and draw enemies
    enemies.forEach(enemy => {
        enemy.update();
        enemy.draw();
    });

    // Update and draw towers
    towers.forEach(tower => {
        tower.update();
        tower.draw();
    });

    // Draw UI
    ctx.fillStyle = 'black';
    ctx.fillRect(0, 0, 800, 30);
    ctx.fillStyle = 'white';
    ctx.font = '15px Arial';
    ctx.fillText(`Gold: ${gold}`, 10, 20);
    ctx.fillText(`Time: ${Math.floor(countdown / 1000)}s`, 700, 20);

    requestAnimationFrame(gameLoop);
}

// Start game loop
requestAnimationFrame(gameLoop);

// Event listener for placing towers
canvas.addEventListener('click', (event) => {
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;
    placeTower(x, y);
});
