    ctx.scale(dpr, dpr);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);

const roomWidth = 50;
const roomHeight = 30;
const tileWidth = 16;
const tileHeight = 16;
const particles = [];

function drawRoom() {
    ctx.fillStyle = '#000';
    ctx.fillRect(0, 0, roomWidth * tileWidth, roomHeight * tileHeight);

    for (let y = 0; y < roomHeight; y++) {
        for (let x = 0; x < roomWidth; x++) {
            ctx.fillStyle = '#111';
            ctx.fillRect(x * tileWidth, y * tileHeight, tileWidth, tileHeight);
        }
    }
}

function createParticle(x, y) {
    particles.push({
        x: x * tileWidth + tileWidth / 2,
        y: y * tileHeight + tileHeight / 2,
        radius: Math.random() * 2 + 1,
        color: `hsl(${Math.random() * 360}, 100%, 50%)`,
        vx: (Math.random() - 0.5) * 2,
        vy: (Math.random() - 0.5) * 2,
        life: 100
    });
}

function updateParticles() {
    particles.forEach((particle, index) => {
        particle.x += particle.vx;
        particle.y += particle.vy;
        particle.life--;

        if (particle.life <= 0) {
            particles.splice(index, 1);
        }
    });
}

function drawParticles() {
    ctx.save();
    ctx.globalCompositeOperation = 'lighter';
    particles.forEach(particle => {
        ctx.beginPath();
        ctx.arc(particle.x, particle.y, particle.radius, 0, Math.PI * 2);
        ctx.fillStyle = particle.color;
        ctx.fill();
    });
    ctx.restore();
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawRoom();
    updateParticles();
    drawParticles();
    requestAnimationFrame(render);
}

render();

document.addEventListener('keydown', e => {
    const key = e.key;
    if (key === 'ArrowUp' || key === 'ArrowDown' || key === 'ArrowLeft' || key === 'ArrowRight') {
        const playerX = Math.floor(roomWidth / 2);
        const playerY = Math.floor(roomHeight / 2);
        createParticle(playerX, playerY);
    }
});
