let wave = 1;
let score = 0;
let lastTime = performance.now();
const fixedTimeStep = 1000 / 60; // 60 FPS

// Obstacle class
class Obstacle {
    constructor(x, y, width, height, speed) {
        this.x = x;
        this.y = y;
        this.width = width;
        this.height = height;
        this.speed = speed;
    }

    update() {
        this.x -= this.speed;
    }

    draw() {
        ctx.fillStyle = 'red';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }
}

// Button to jump
