const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const ASTEROID_SPEED = 100;
const ASTEROID_SIZE = 30;
const PLAYER_SPEED = 200;
const PLAYER_SIZE = 10;
const BULLET_SPEED = 300;
const BULLET_SIZE = 5;
const POWERUP_SPEED = 75;
const POWERUP_SIZE = 10;
const POWERUP_TYPES = ['speed', 'shield'];
const POWERUP_PROBABILITY = 0.01;
const MAX_BULLETS = 10;
const GAME_STATE = { playing: true, score: 0, lives: 3 };
const FIXED_TIME_STEP = 1000 / 60;
let accumulator = 0;
let lastTime = performance.now();

class Entity {
    constructor(x, y, size) {
        this.x = x;
        this.y = y;
        this.size = size;
    }

    update(deltaTime) {
        // Override in subclass
    }

    draw() {
        // Override in subclass
    }

    collidesWith(other) {
        const distance = Math.sqrt(
            Math.pow(this.x - other.x, 2) +
            Math.pow(this.y - other.y, 2)
        );
        return distance < (this.size + other.size);
    }
}

class Asteroid extends Entity {
    constructor(x, y) {
        super(x, y, ASTEROID_SIZE);
        this.angle = Math.random() * Math.PI * 2;
        this.velocity = {
            x: Math.cos(this.angle) * ASTEROID_SPEED,
            y: Math.sin(this.angle) * ASTEROID_SPEED
        };
    }

    update(deltaTime) {
        this.x += this.velocity.x * deltaTime;
        this.y += this.velocity.y * deltaTime;
        if (this.x < -this.size || this.x > canvas.width + this.size ||
            this.y < -this.size || this.y > canvas.height + this.size) {
            this.respawn();
        }
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fillStyle = 'gray';
        ctx.fill();
    }

    respawn() {
        this.x = Math.random() * canvas.width;
        this.y = Math.random() * canvas.height;
        this.angle = Math.random() * Math.PI * 2;
        this.velocity = {
            x: Math.cos(this.angle) * ASTEROID_SPEED,
            y: Math.sin(this.angle) * ASTEROID_SPEED
        };
    }
}

class Player extends Entity {
    constructor() {
        super(canvas.width / 2, canvas.height / 2, PLAYER_SIZE);
        this.angle = 0;
        this.shield = false;
        this.bullets = [];
        this.velocity = { x: 0, y: 0 };
    }

    update(deltaTime) {
        const speed = PLAYER_SPEED * deltaTime;
        this.x += this.velocity.x;
        this.y += this.velocity.y;
        if (this.x < 0) this.x = 0;
        if (this.x > canvas.width) this.x = canvas.width;
        if (this.y < 0) this.y = 0;
        if (this.y > canvas.height) this.y = canvas.height;

        this.bullets = this.bullets.filter(bullet => {
            bullet.x += bullet.velocity.x * deltaTime;
            bullet.y += bullet.velocity.y * deltaTime;
            return bullet.x > 0 && bullet.x < canvas.width &&
                   bullet.y > 0 && bullet.y < canvas.height;
        });
    }

    draw() {
        ctx.save();
        ctx.translate(this.x, this.y);
        ctx.rotate(this.angle);
        ctx.beginPath();
        ctx.moveTo(0, -this.size);
        ctx.lineTo(this.size, this.size);
        ctx.lineTo(-this.size, this.size);
        ctx.closePath();
        ctx.fillStyle = 'blue';
        ctx.fill();
        if (this.shield) {
            ctx.beginPath();
            ctx.arc(0, 0, this.size * 2, 0, Math.PI * 2);
            ctx.strokeStyle = 'green';
            ctx.lineWidth = 3;
            ctx.stroke();
        }
        ctx.restore();

        this.bullets.forEach(bullet => {
            ctx.beginPath();
            ctx.arc(bullet.x, bullet.y, BULLET_SIZE, 0, Math.PI * 2);
            ctx.fillStyle = 'red';
            ctx.fill();
        });
    }

    shoot() {
        if (this.bullets.length < MAX_BULLETS) {
            const bullet = {
                x: this.x,
                y: this.y,
                velocity: {
                    x: Math.cos(this.angle) * BULLET_SPEED,
                    y: Math.sin(this.angle) * BULLET_SPEED
                }
            };
            this.bullets.push(bullet);
        }
    }

    collectPowerUp(powerUp) {
        if (powerUp.type === 'speed') {
            PLAYER_SPEED *= 1.2;
        } else if (powerUp.type === 'shield') {
            this.shield = true;
            setTimeout(() => { this.shield = false; }, 5000);
        }
    }
}

class PowerUp extends Entity {
    constructor(x, y) {
        super(x, y, POWERUP_SIZE);
        this.type = POWERUP_TYPES[Math.floor(Math.random() * POWERUP_TYPES.length)];
        this.angle = Math.random() * Math.PI * 2;
        this.velocity = {
            x: Math.cos(this.angle) * POWERUP_SPEED,
            y: Math.sin(this.angle) * POWERUP_SPEED
        };
    }

    update(deltaTime) {
        this.x += this.velocity.x * deltaTime;
        this.y += this.velocity.y * deltaTime;
        if (this.x < -this.size || this.x > canvas.width + this.size ||
            this.y < -this.size || this.y > canvas.height + this.size) {
            this.respawn();
        }
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.size, 0, Math.PI * 2);
        ctx.fillStyle = this.type === 'speed' ? 'yellow' : 'green';
        ctx.fill();
    }

    respawn() {
        this.x = Math.random() * canvas.width;
        this.y = Math.random() * canvas.height;
        this.angle = Math.random() * Math.PI * 2;
        this.velocity = {
            x: Math.cos(this.angle) * POWERUP_SPEED,
            y: Math.sin(this.angle) * POWERUP_SPEED
        };
    }
}

const player = new Player();
const asteroids = Array.from({ length: 5 }, () => new Asteroid(Math.random() * canvas.width, Math.random() * canvas.height));
const powerUps = [];

function handleInput() {
    const keys = {};
    document.addEventListener('keydown', (e) => {
        keys[e.key] = true;
    });
    document.addEventListener('keyup', (e) => {
        keys[e.key] = false;
    });

    if (keys['ArrowLeft']) {
        player.angle -= 0.05;
    }
    if (keys['ArrowRight']) {
        player.angle += 0.05;
    }
    if (keys['ArrowUp']) {
        player.velocity.x = Math.cos(player.angle) * PLAYER_SPEED;
        player.velocity.y = Math.sin(player.angle) * PLAYER_SPEED;
    } else {
        player.velocity.x = 0;
        player.velocity.y = 0;
    }
    if (keys[' ']) {
        player.shoot();
    }
}

function update(deltaTime) {
    player.update(deltaTime);
    asteroids.forEach(asteroid => asteroid.update(deltaTime));
    powerUps.forEach(powerUp => powerUp.update(deltaTime));

    asteroids.forEach(asteroid => {
        if (player.collidesWith(asteroid)) {
            if (player.shield) {
                asteroid.respawn();
            } else {
                GAME_STATE.lives--;
                player.respawn();
            }
        }
    });

    player.bullets.forEach(bullet => {
        asteroids.forEach(asteroid => {
            if (bullet.collidesWith(asteroid)) {
                asteroid.respawn();
                GAME_STATE.score++;
            }
        });
    });

    if (Math.random() < POWERUP_PROBABILITY) {
        powerUps.push(new PowerUp(Math.random() * canvas.width, Math.random() * canvas.height));
    }

    powerUps.forEach(powerUp => {
        if (player.collidesWith(powerUp)) {
            player.collectPowerUp(powerUp);
            powerUps = powerUps.filter(p => p !== powerUp);
        }
    });

    if (GAME_STATE.lives <= 0) {
        GAME_STATE.playing = false;
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    player.draw();
    asteroids.forEach(asteroid => asteroid.draw());
    powerUps.forEach(powerUp => powerUp.draw());

    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${GAME_STATE.score}`, 10, 30);
    ctx.fillText(`Lives: ${GAME_STATE.lives}`, 10, 60);
}

function mainLoop() {
    const now = performance.now();
    accumulator += now - lastTime;
    lastTime = now;

    while (accumulator >= FIXED_TIME_STEP) {
        update(FIXED_TIME_STEP / 1000);
        accumulator -= FIXED_TIME_STEP;
    }

    draw();

    if (GAME_STATE.playing) {
        requestAnimationFrame(mainLoop);
    } else {
        ctx.fillStyle = 'black';
        ctx.font = '48px Arial';
        ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
    }
}

handleInput();
mainLoop();
