  const y = Math.random() * (canvas.height - pipeGap) + pipeGap / 2;
  pipes.push({
    x: canvas.width,
    y: y,
    update: function() {
      this.x -= pipeSpeed;
    },
    draw: function() {
      ctx.fillStyle = 'green';
      ctx.fillRect(this.x, 0, pipeWidth, this.y - pipeGap / 2);
      ctx.fillRect(this.x, this.y + pipeGap / 2, pipeWidth, canvas.height - this.y - pipeGap / 2);
    },
    collidesWith: function(bird) {
      return (bird.x + bird.radius > this.x && bird.x - bird.radius < this.x + pipeWidth) &&
             ((bird.y - bird.radius < this.y - pipeGap / 2) || (bird.y + bird.radius > this.y + pipeGap / 2));
    }
  });
};

