// Falling Block Puzzle with Particle Burst Effect

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
let ctx = canvas.getContext('2d');

let w = window.innerWidth;
let h = window.innerHeight;
let dpr = window.devicePixelRatio;

canvas.width = w * dpr;
canvas.height = h * dpr;
ctx.scale(dpr, dpr);

let cols = Math.floor(w / 40);
let rows = Math.floor(h / 40);
let grid = [];
let particles = [];
let score = 0;

function initGrid() {
  for (let i = 0; i < rows; i++) {
    grid[i] = new Array(cols).fill(0);
  }
}

function createBlock() {
  let x = Math.floor(Math.random() * cols);
  let block = { x, y: 0, color: `hsl(${Math.random() * 360}, 100%, 50%)` };
  return block;
}

function updateBlock(block) {
  if (block.y < rows - 1 && !grid[block.y + 1][block.x]) {
    block.y++;
  } else {
    grid[block.y][block.x] = block;
    block = null;
  }
  return block;
}

function checkLines() {
  let linesCleared = 0;
  for (let i = rows - 1; i >= 0; i--) {
    if (!grid[i].some(cell => cell === 0)) {
      linesCleared++;
      grid.splice(i, 1);
      grid.unshift(new Array(cols).fill(0));
      burstParticles(i);
    }
  }
  score += linesCleared * 100;
}

function burstParticles(y) {
  for (let i = 0; i < cols; i++) {
    let color = grid[y][i].color;
    particles.push({ x: i, y, color, vx: (Math.random() - 0.5) * 2, vy: -5, size: Math.random() * 2 + 1 });
  }
}

function updateParticles() {
  particles.forEach((p, i) => {
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.1;
    if (p.y > rows) {
      particles.splice(i, 1);
    }
  });
}

function draw() {
  ctx.clearRect(0, 0, w, h);

  // Draw grid
  ctx.strokeStyle = '#333';
  for (let i = 0; i < rows; i++) {
    for (let j = 0; j < cols; j++) {
      ctx.strokeRect(j * 40, i * 40, 40, 40);
    }
  }

  // Draw blocks
  grid.forEach((row, i) => {
    row.forEach((cell, j) => {
      if (cell) {
        ctx.fillStyle = cell.color;
        ctx.fillRect(j * 40, i * 40, 40, 40);
      }
    });
  });

  // Draw particles
  ctx.fillStyle = 'white';
  particles.forEach(p => {
    ctx.beginPath();
    ctx.arc(p.x * 40 + 20, p.y * 40 + 20, p.size, 0, Math.PI * 2);
    ctx.fill();
  });

  // Draw score
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function gameLoop() {
  if (block) {
    block = updateBlock(block);
    if (!block) {
      checkLines();
      block = createBlock();
    }
  }
  updateParticles();
  draw();
  requestAnimationFrame(gameLoop);
}

// Event listeners
window.addEventListener('resize', () => {
  w = window.innerWidth;
  h = window.innerHeight;
  dpr = window.devicePixelRatio;
  canvas.width = w * dpr;
  canvas.height = h * dpr;
  ctx.scale(dpr, dpr);
  cols = Math.floor(w / 40);
  rows = Math.floor(h / 40);
  initGrid();
});

initGrid();
let block = createBlock();
gameLoop();
