        if (!isRespawning) {
            isRespawning = true;
            respawnTimer = Date.now();
        }
        if (Date.now() - respawnTimer >= respawnDuration) {
            playerHealth = maxHealth;
            isRespawning = false;
        }
    }
    if (isRespawning) {
        drawRespawnText();
    }
    drawHealthBar();
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    update();
    requestAnimationFrame(gameLoop);
}

resizeCanvas();
window.addEventListener('resize', resizeCanvas);
gameLoop();

// Simulate player taking damage
setInterval(() => {
    if (!isRespawning) {
        playerHealth -= 5;
        if (playerHealth < 0) playerHealth = 0;
    }
}, 1000);
