const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const states = {
  menu: 0,
  playing: 1,
  paused: 2,
  gameover: 3
};

let currentState = states.menu;
let score = 0;
let playerY = canvas.height / 2;
let playerVelocity = 0;
const gravity = 0.5;
const jumpForce = -10;
const fixedTimestep = 1000 / 60;
let accumulator = 0;
let lastTime = performance.now();

function update(delta) {
  if (currentState === states.playing) {
    playerVelocity += gravity * delta;
    playerY += playerVelocity * delta;

    if (playerY > canvas.height) {
      currentState = states.gameover;
    }

    if (playerY < 0) {
      playerY = 0;
      playerVelocity = 0;
    }
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (currentState === states.menu) {
    ctx.fillStyle = 'black';
    ctx.font = '30px Arial';
    ctx.fillText('Press Space to Start', canvas.width / 2 - 150, canvas.height / 2);
  } else if (currentState === states.playing) {
    ctx.fillStyle = 'blue';
    ctx.fillRect(canvas.width - 50, playerY, 50, 50);
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
  } else if (currentState === states.paused) {
    ctx.fillStyle = 'black';
    ctx.font = '30px Arial';
    ctx.fillText('Game Paused', canvas.width / 2 - 100, canvas.height / 2);
  } else if (currentState === states.gameover) {
    ctx.fillStyle = 'black';
    ctx.font = '30px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2 - 50);
    ctx.fillText(`Score: ${score}`, canvas.width / 2 - 50, canvas.height / 2);
  }
}

function handleInput() {
  if (currentState === states.menu) {
    if (keys[' ']) {
      currentState = states.playing;
      score = 0;
      playerY = canvas.height / 2;
      playerVelocity = 0;
    }
  } else if (currentState === states.playing) {
    if (keys[' ']) {
      playerVelocity = jumpForce;
    }
  } else if (currentState === states.paused) {
    if (keys[' ']) {
      currentState = states.playing;
    }
  } else if (currentState === states.gameover) {
    if (keys[' ']) {
      currentState = states.menu;
    }
  }
}

const keys = {};
document.addEventListener('keydown', (e) => {
  keys[e.code] = true;
});
document.addEventListener('keyup', (e) => {
  keys[e.code] = false;
});

function gameLoop() {
  const now = performance.now();
  const deltaTime = now - lastTime;
  lastTime = now;
  accumulator += deltaTime;

  while (accumulator >= fixedTimestep) {
    update(fixedTimestep / 1000);
    accumulator -= fixedTimestep;
  }

  handleInput();
  render();
  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
