class Entity {
  constructor(x, y, width, height, color) {
    this.x = x;
    this.y = y;
    this.width = width;
    this.height = height;
    this.color = color;
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

class Player extends Entity {
  constructor(x, y) {
    super(x, y, 32, 32, 'blue');
    this.velocityX = 0;
    this.velocityY = 0;
    this.jumpPower = -10;
    this.gravity = 0.5;
    this.onGround = false;
    this.controls = { left: false, right: false, jump: false };
  }

  update() {
    if (this.controls.left) this.velocityX = -5;
    else if (this.controls.right) this.velocityX = 5;
    else this.velocityX = 0;

    if (this.controls.jump && this.onGround) {
      this.velocityY = this.jumpPower;
      this.onGround = false;
    }

    this.velocityY += this.gravity;
    this.x += this.velocityX;
    this.y += this.velocityY;

    // Collision with ground
    if (this.y + this.height > canvas.height) {
      this.y = canvas.height - this.height;
      this.velocityY = 0;
      this.onGround = true;
    }
  }
}

class Platform extends Entity {
  constructor(x, y, width, height) {
    super(x, y, width, height, 'green');
  }
}

class PowerUp extends Entity {
  constructor(x, y) {
    super(x, y, 16, 16, 'yellow');
  }

  collect() {
    // Placeholder for power-up effect
    console.log('Power-up collected!');
  }
}

const player = new Player(100, canvas.height - 64);
const platforms = [
  new Platform(0, canvas.height - 32, canvas.width, 32),
  new Platform(100, 400, 100, 20),
  new Platform(300, 200, 150, 20)
];
const powerUps = [
  new PowerUp(200, canvas.height - 96),
  new PowerUp(400, 380)
];

function checkCollisions() {
  platforms.forEach(platform => {
    if (player.x < platform.x + platform.width &&
        player.x + player.width > platform.x &&
        player.y < platform.y + platform.height &&
        player.y + player.height > platform.y) {
      player.onGround = true;
      player.velocityY = 0;
      player.y = platform.y - player.height;
    }
  });

  powerUps.forEach((powerUp, index) => {
    if (player.x < powerUp.x + powerUp.width &&
        player.x + player.width > powerUp.x &&
        player.y < powerUp.y + powerUp.height &&
        player.y + player.height > powerUp.y) {
      powerUp.collect();
      powerUps.splice(index, 1);
    }
  });
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  player.update();
  checkCollisions();

  player.draw();
  platforms.forEach(platform => platform.draw());
  powerUps.forEach(powerUp => powerUp.draw());

  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft') player.controls.left = true;
  if (e.key === 'ArrowRight') player.controls.right = true;
  if (e.key === 'ArrowUp' || e.key === ' ') player.controls.jump = true;
});

document.addEventListener('keyup', (e) => {
  if (e.key === 'ArrowLeft') player.controls.left = false;
  if (e.key === 'ArrowRight') player.controls.right = false;
  if (e.key === 'ArrowUp' || e.key === ' ') player.controls.jump = false;
});

