// Constants
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const ASTEROID_COUNT = 5;
const ASTEROID_MIN_SIZE = 20;
const ASTEROID_MAX_SIZE = 50;
const ASTEROID_SPEED = 2;
const PLAYER_SIZE = 20;
const PLAYER_SPEED = 5;
const BULLET_SPEED = 10;
const COUNTDOWN_SECONDS = 5;
const FIXED_TIMESTEP = 1000 / 60; // 60 frames per second

// HTML5 Canvas setup
const canvas = document.createElement('canvas');
canvas.width = CANVAS_WIDTH;
canvas.height = CANVAS_HEIGHT;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game state
let asteroids = [];
let bullets = [];
let player = {
    x: CANVAS_WIDTH / 2,
    y: CANVAS_HEIGHT / 2,
    angle: 0,
    speed: 0
};
let countdown = COUNTDOWN_SECONDS;
let lastTime = performance.now();
let gameOver = false;

// Initialization
function initAsteroids() {
    for (let i = 0; i < ASTEROID_COUNT; i++) {
        asteroids.push({
            x: Math.random() * CANVAS_WIDTH,
            y: Math.random() * CANVAS_HEIGHT,
            size: Math.random() * (ASTEROID_MAX_SIZE - ASTEROID_MIN_SIZE) + ASTEROID_MIN_SIZE,
            angle: Math.random() * Math.PI * 2,
            speed: ASTEROID_SPEED
        });
    }
}

// Input handling
document.addEventListener('keydown', (e) => {
    switch (e.key) {
        case 'ArrowLeft':
            player.angle -= 0.1;
            break;
        case 'ArrowRight':
            player.angle += 0.1;
            break;
        case 'ArrowUp':
            player.speed += PLAYER_SPEED;
            break;
        case 'ArrowDown':
            player.speed -= PLAYER_SPEED;
            break;
        case ' ':
            bullets.push({
                x: player.x,
                y: player.y,
                angle: player.angle,
                speed: BULLET_SPEED
            });
            break;
    }
});

document.addEventListener('keyup', (e) => {
    if (e.key === 'ArrowUp' || e.key === 'ArrowDown') {
        player.speed = 0;
    }
});

// Game loop
function gameLoop() {
    const now = performance.now();
    const deltaTime = now - lastTime;
    lastTime = now;

    if (!gameOver) {
        update(deltaTime);
        render();
        requestAnimationFrame(gameLoop);
    }
}

// Update game state
function update(deltaTime) {
    if (countdown > 0) {
        countdown -= deltaTime / 1000;
        if (countdown <= 0) {
            countdown = 0;
            initAsteroids();
        }
    } else {
        // Update player
        player.x += Math.cos(player.angle) * player.speed * deltaTime / 1000;
        player.y += Math.sin(player.angle) * player.speed * deltaTime / 1000;

        // Wrap player around the screen
        player.x = (player.x + CANVAS_WIDTH) % CANVAS_WIDTH;
        player.y = (player.y + CANVAS_HEIGHT) % CANVAS_HEIGHT;

        // Update bullets
        bullets = bullets.filter(bullet => {
            bullet.x += Math.cos(bullet.angle) * bullet.speed * deltaTime / 1000;
            bullet.y += Math.sin(bullet.angle) * bullet.speed * deltaTime / 1000;
            return bullet.x > 0 && bullet.x < CANVAS_WIDTH && bullet.y > 0 && bullet.y < CANVAS_HEIGHT;
        });

        // Update asteroids
        for (let asteroid of asteroids) {
            asteroid.x += Math.cos(asteroid.angle) * asteroid.speed * deltaTime / 1000;
            asteroid.y += Math.sin(asteroid.angle) * asteroid.speed * deltaTime / 1000;

            // Wrap asteroids around the screen
            asteroid.x = (asteroid.x + CANVAS_WIDTH) % CANVAS_WIDTH;
            asteroid.y = (asteroid.y + CANVAS_HEIGHT) % CANVAS_HEIGHT;
        }

        // Collision detection
        bullets = bullets.filter(bullet => {
            let hit = false;
            for (let i = asteroids.length - 1; i >= 0; i--) {
                let asteroid = asteroids[i];
                if (Math.hypot(bullet.x - asteroid.x, bullet.y - asteroid.y) < asteroid.size / 2) {
                    asteroids.splice(i, 1);
                    hit = true;
                    break;
                }
            }
            return !hit;
        });

        // Check for game over
        for (let asteroid of asteroids) {
            if (Math.hypot(player.x - asteroid.x, player.y - asteroid.y) < asteroid.size / 2 + PLAYER_SIZE / 2) {
                gameOver = true;
            }
        }
    }
}

// Render the game
function render() {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Draw countdown
    if (countdown > 0) {
        ctx.font = '48px Arial';
        ctx.fillStyle = 'white';
        ctx.textAlign = 'center';
        ctx.fillText(Math.ceil(countdown), CANVAS_WIDTH / 2, CANVAS_HEIGHT / 2);
        return;
    }

    // Draw player
    ctx.save();
    ctx.translate(player.x, player.y);
    ctx.rotate(player.angle);
    ctx.fillStyle = 'blue';
    ctx.fillRect(-PLAYER_SIZE / 2, -PLAYER_SIZE / 2, PLAYER_SIZE, PLAYER_SIZE);
    ctx.restore();

    // Draw bullets
    ctx.fillStyle = 'yellow';
    for (let bullet of bullets) {
        ctx.fillRect(bullet.x - 1, bullet.y - 1, 2, 2);
    }

    // Draw asteroids
    ctx.fillStyle = 'red';
    for (let asteroid of asteroids) {
        ctx.beginPath();
        ctx.arc(asteroid.x, asteroid.y, asteroid.size / 2, 0, Math.PI * 2);
        ctx.fill();
    }
}

// Start the game
initAsteroids();
gameLoop();
