const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 500;
canvas.height = 500;
const ctx = canvas.getContext('2d');

const boardSize = 8;
const cellSize = canvas.width / boardSize;
const colors = ['#FF5733', '#33FF57', '#3357FF', '#F333FF', '#33FFF3', '#FFD333', '#33FFD3', '#D333FF'];
let board = Array.from({ length: boardSize }, () => Array(boardSize).fill(0).map(() => Math.floor(Math.random() * colors.length)));
let score = 0;
let combo = 0;

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            ctx.fillStyle = colors[board[y][x]];
            ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            ctx.strokeStyle = '#000';
            ctx.strokeRect(x * cellSize, y * cellSize, cellSize, cellSize);
        }
    }
    ctx.fillStyle = '#000';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Combo: x${combo}`, 10, 40);
}

function checkMatches() {
    let matches = [];
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            if (board[y][x] === 0) continue;
            let color = board[y][x];
            let line = [];
            for (let dx = x; dx < boardSize && board[y][dx] === color; dx++) {
                line.push([y, dx]);
            }
            if (line.length >= 3) matches.push(line);
            line = [];
            for (let dy = y; dy < boardSize && board[dy][x] === color; dy++) {
                line.push([dy, x]);
            }
            if (line.length >= 3) matches.push(line);
        }
    }
    return matches;
}

function clearMatches(matches) {
    matches.forEach(line => {
        line.forEach(([y, x]) => {
            board[y][x] = 0;
        });
    });
    combo++;
}

function dropTiles() {
    for (let x = 0; x < boardSize; x++) {
        let empty = 0;
        for (let y = boardSize - 1; y >= 0; y--) {
            if (board[y][x] === 0) {
                empty++;
            } else if (empty > 0) {
                board[y + empty][x] = board[y][x];
                board[y][x] = 0;
            }
        }
    }
    for (let x = 0; x < boardSize; x++) {
        for (let y = 0; y < empty; y++) {
            board[y][x] = Math.floor(Math.random() * colors.length);
        }
    }
}

function update() {
    let matches = checkMatches();
    if (matches.length > 0) {
        clearMatches(matches);
        score += matches.length * combo;
        dropTiles();
        combo = 0;
    }
    drawBoard();
    requestAnimationFrame(update);
}

update();
