```js
// Constants
const TILE_SIZE = 16;
const ROOM_WIDTH = 10;
const ROOM_HEIGHT = 8;
const WAVE_INTERVAL = 5000; // milliseconds

// Game state
let canvas, ctx;
let tiles = Array.from({ length: ROOM_HEIGHT }, () => Array(ROOM_WIDTH).fill('empty'));
let enemies = [];
let wave = 1;
let lastWaveTime = 0;

// Tile types
const TILE_TYPES = {
  empty: 'black',
  wall: 'grey',
  enemy: 'red'
};

// Initialize canvas
function initCanvas() {
  canvas = document.createElement('canvas');
  document.body.appendChild(canvas);
  ctx = canvas.getContext('2d');
  window.addEventListener('resize', resizeCanvas);
  resizeCanvas();
}

// Resize canvas with devicePixelRatio
function resizeCanvas() {
  const scale = window.devicePixelRatio;
  canvas.width = window.innerWidth * scale;
  canvas.height = window.innerHeight * scale;
  ctx.scale(scale, scale);
}

// Generate room
function generateRoom() {
  tiles = Array.from({ length: ROOM_HEIGHT }, () => Array(ROOM_WIDTH).fill('empty'));
  for (let y = 0; y < ROOM_HEIGHT; y++) {
    for (let x = 0; x < ROOM_WIDTH; x++) {
      if (y === 0 || y === ROOM_HEIGHT - 1 || x === 0 || x === ROOM_WIDTH - 1) {
        tiles[y][x] = 'wall';
      }
    }
  }
}

// Spawn enemies for the wave
function spawnEnemies() {
  const enemyCount = wave * 5;
  enemies = [];
  for (let i = 0; i < enemyCount; i++) {
    let x, y;
    do {
      x = Math.floor(Math.random() * ROOM_WIDTH);
      y = Math.floor(Math.random() * ROOM_HEIGHT);
    } while (tiles[y][x] !== 'empty');
    enemies.push({ x, y });
  }
}

// Update game state
function update() {
  if (Date.now() - lastWaveTime >= WAVE_INTERVAL) {
    wave++;
    lastWaveTime = Date.now();
    generateRoom();
    spawnEnemies();
  }
}

// Render game
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  tiles.forEach((row, y) => {
    row.forEach((tile, x) => {
      ctx.fillStyle = TILE_TYPES[tile];
      ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    });
  });
  enemies.forEach(enemy => {
    ctx.fillStyle = TILE_TYPES.enemy;
    ctx.fillRect(enemy.x * TILE_SIZE, enemy.y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
  });
}

// Game loop
function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

// Start the game
initCanvas();
generateRoom();
spawnEnemies();
gameLoop();
