  y: 100,
  width: 30,
  height: 50,
  velocityX: 0,
  velocityY: 0,
  onGround: false
};

const platforms = [
  { x: 0, y: 550, width: 800, height: 50 },
  { x: 200, y: 400, width: 200, height: 20 },
  { x: 500, y: 300, width: 100, height: 20 }
];

