  menu: {
    update: () => {},
    draw: () => {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
      ctx.font = '24px Arial';
      ctx.fillText('Press Enter to Start', canvas.width / 2 - 100, canvas.height / 2);
    }
  },
