  ctx.clearRect(0, 0, canvas.width, canvas.height);

  spawnEnemy();
  updateEnemies();
  enemies.forEach(drawEnemy);

  spawnTower();
  updateTowers();
  towers.forEach(drawTower);

  updateProjectiles();
  projectiles.forEach(drawProjectile);

  drawScore();

  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }

  requestAnimationFrame(update);
}

update();
