function initBoard() {
    for (let i = 0; i < ROWS; i++) {
        board[i] = [];
        for (let j = 0; j < COLS; j++) {
            board[i][j] = Math.floor(Math.random() * 3);
        }
    }
}

function drawTile(x, y, color) {
    ctx.fillStyle = `hsl(${color * 60}, 100%, 50%)`;
    ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < ROWS; i++) {
        for (let j = 0; j < COLS; j++) {
            drawTile(j, i, board[i][j]);
        }
    }
    ctx.fillStyle = '#000';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`High Score: ${localStorage.getItem('highScore') || 0}`, 10, 40);
}

function matchTiles() {
    let matches = [];

    // Check horizontal matches
    for (let i = 0; i < ROWS; i++) {
        for (let j = 0; j < COLS - 2; j++) {
            if (board[i][j] === board[i][j + 1] && board[i][j] === board[i][j + 2]) {
                matches.push([i, j], [i, j + 1], [i, j + 2]);
            }
        }
    }

    // Check vertical matches
    for (let j = 0; j < COLS; j++) {
        for (let i = 0; i < ROWS - 2; i++) {
            if (board[i][j] === board[i + 1][j] && board[i][j] === board[i + 2][j]) {
                matches.push([i, j], [i + 1, j], [i + 2, j]);
            }
        }
    }

    if (matches.length > 0) {
        score += matches.length * 10;
        localStorage.setItem('highScore', Math.max(score, localStorage.getItem('highScore') || 0));
        for (let [i, j] of matches) {
            board[i][j] = -1; // Mark for removal
        }
        return true;
    }
    return false;
}

function dropTiles() {
    for (let j = 0; j < COLS; j++) {
        let emptyCount = 0;
        for (let i = ROWS - 1; i >= 0; i--) {
            if (board[i][j] === -1) {
                emptyCount++;
            } else if (emptyCount > 0) {
                board[i + emptyCount][j] = board[i][j];
                board[i][j] = -1;
            }
        }
        for (let i = 0; i < emptyCount; i++) {
            board[i][j] = Math.floor(Math.random() * 3);
        }
    }
}

function update() {
    if (matchTiles()) {
        dropTiles();
    }
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    lastTime = timestamp;
    update();
    drawBoard();
    requestAnimationFrame(gameLoop);
}

