const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;

function resizeCanvas() {
  canvas.width = window.innerWidth * dpr;
  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}
resizeCanvas();
window.addEventListener('resize', resizeCanvas);

class Player {
  constructor() {
    this.x = 50;
    this.y = canvas.height / 2;
    this.radius = 10;
    this.velocityY = 0;
    this.gravity = 0.5;
  }

  update() {
    this.velocityY += this.gravity;
    this.y += this.velocityY;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();
    ctx.closePath();
  }

  flap() {
    this.velocityY = -10;
  }
}

class Gap {
  constructor(x) {
    this.x = x;
    this.width = 50;
    this.height = 100;
    this.gapSize = 100;
    this.speed = 2;
  }

  update() {
    this.x -= this.speed;
  }

  draw() {
    ctx.fillStyle = 'green';
    ctx.fillRect(this.x, 0, this.width, this.height);
    ctx.fillRect(this.x, this.height + this.gapSize, this.width, canvas.height);
  }

  checkCollision(player) {
    return !(player.x + player.radius < this.x || player.x - player.radius > this.x + this.width ||
             player.y - player.radius < this.height || player.y + player.radius > this.height + this.gapSize);
  }
}

let player = new Player();
let gaps = [];
let gapSpawnInterval = 1500;
let lastGapSpawn = 0;
let gameOver = false;
let score = 0;
let difficulty = 1;

function spawnGap() {
  gaps.push(new Gap(canvas.width));
}

function update() {
  if (gameOver) return;

  const now = Date.now();
  if (now - lastGapSpawn > gapSpawnInterval) {
    spawnGap();
    lastGapSpawn = now;
    gapSpawnInterval -= 100;
    if (gapSpawnInterval < 500) gapSpawnInterval = 500;
    difficulty += 0.1;
  }

  player.update();
  gaps.forEach(gap => {
    gap.update();
    if (gap.checkCollision(player)) {
      gameOver = true;
    }
    if (gap.x + gap.width < 0) {
      gaps.shift();
      score++;
    }
  });

  if (player.y > canvas.height || player.y < 0) {
    gameOver = true;
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  player.draw();
  gaps.forEach(gap => gap.draw());

  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`Difficulty: ${difficulty.toFixed(1)}`, 10, 50);

  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '40px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
  }
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

window.addEventListener('keydown', e => {
  if (e.code === 'Space' && !gameOver) {
    player.flap();
  }
  if (e.code === 'Space' && gameOver) {
    player = new Player();
    gaps = [];
    lastGapSpawn = 0;
    gameOver = false;
    score = 0;
    difficulty = 1;
    gapSpawnInterval = 1500;
  }
});

