// Match-3 Board with Enemy Spawner

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const ROWS = 10;
const COLS = 10;
const TILE_SIZE = 50;
const ENEMY_SIZE = 25;
const ENEMY_SPAWN_INTERVAL = 1000; // milliseconds
const DIFFICULTY_INCREASE_INTERVAL = 30000; // milliseconds
const INITIAL_ENEMY_SPAWN_RATE = 0.05; // 5% chance per frame

let board = [];
let enemies = [];
let lastEnemySpawn = 0;
let enemySpawnRate = INITIAL_ENEMY_SPAWN_RATE;
let lastDifficultyIncrease = 0;

function initBoard() {
    for (let row = 0; row < ROWS; row++) {
        board[row] = [];
        for (let col = 0; col < COLS; col++) {
            board[row][col] = Math.floor(Math.random() * 5);
        }
    }
}

function spawnEnemy() {
    const row = Math.floor(Math.random() * ROWS);
    const col = Math.floor(Math.random() * COLS);
    enemies.push({ row, col });
}

function updateDifficulty() {
    enemySpawnRate += 0.01; // Increase spawn rate by 1% every 30 seconds
    if (enemySpawnRate > 1) enemySpawnRate = 1; // Cap at 100%
}

function checkEnemySpawn() {
    const now = Date.now();
    if (now - lastEnemySpawn > ENEMY_SPAWN_INTERVAL) {
        if (Math.random() < enemySpawnRate) {
            spawnEnemy();
            lastEnemySpawn = now;
        }
    }
}

function updateEnemies() {
    enemies.forEach((enemy, index) => {
        const { row, col } = enemy;
        if (Math.random() < 0.05) { // 5% chance to move
            const newRow = row + (Math.random() > 0.5 ? 1 : -1);
            const newCol = col + (Math.random() > 0.5 ? 1 : -1);
            if (newRow >= 0 && newRow < ROWS && newCol >= 0 && newCol < COLS) {
                enemies[index] = { row: newRow, col: newCol };
            }
        }
    });
}

function checkDifficultyIncrease() {
    const now = Date.now();
    if (now - lastDifficultyIncrease > DIFFICULTY_INCREASE_INTERVAL) {
        updateDifficulty();
        lastDifficultyIncrease = now;
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let row = 0; row < ROWS; row++) {
        for (let col = 0; col < COLS; col++) {
            const color = `hsl(${board[row][col] * 36}, 100%, 50%)`;
            ctx.fillStyle = color;
            ctx.fillRect(col * TILE_SIZE, row * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        }
    }
}

function drawEnemies() {
    enemies.forEach(enemy => {
        const { row, col } = enemy;
        ctx.fillStyle = 'red';
        ctx.fillRect(col * TILE_SIZE + TILE_SIZE / 2 - ENEMY_SIZE / 2, row * TILE_SIZE + TILE_SIZE / 2 - ENEMY_SIZE / 2, ENEMY_SIZE, ENEMY_SIZE);
    });
}

function gameLoop() {
    checkEnemySpawn();
    updateEnemies();
    checkDifficultyIncrease();
    drawBoard();
    drawEnemies();
    requestAnimationFrame(gameLoop);
}

initBoard();
gameLoop();
