const ctx = canvas.getContext('2d');
const cardWidth = 100;
const cardHeight = 100;
const numPairs = 8;
const cards = [];
let flippedCards = [];
let score = 0;
let timer = 60;
let gameEnded = false;
let lastTime = 0;
const flipTime = 500; // milliseconds

function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
}

function createCards() {
    const cardImages = ['A', 'B', 'C', 'D', 'E', 'F', 'G', 'H'];
    const cards = [];
    for (let i = 0; i < numPairs; i++) {
        cards.push(cardImages[i], cardImages[i]);
    }
    shuffle(cards);
    return cards.map((image, index) => ({
        x: (index % 8) * (cardWidth + 10),
        y: Math.floor(index / 8) * (cardHeight + 10),
        image,
        flipped: false,
        match: false
    }));
}

function drawCard(card) {
    ctx.fillStyle = card.flipped ? `#${card.image}` : '#888';
    ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
    ctx.strokeStyle = '#000';
    ctx.strokeRect(card.x, card.y, cardWidth, cardHeight);
    if (card.flipped) {
        ctx.fillStyle = '#000';
        ctx.font = '24px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(card.image, card.x + cardWidth / 2, card.y + cardHeight / 2);
    }
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    cards.forEach(drawCard);
    ctx.fillStyle = '#000';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`Time: ${timer}`, canvas.width - 80, 30);
}

function checkForMatch() {
    if (flippedCards.length === 2) {
        const [card1, card2] = flippedCards;
        if (card1.image === card2.image) {
            card1.match = true;
            card2.match = true;
            score += 10;
        } else {
            setTimeout(() => {
                card1.flipped = false;
                card2.flipped = false;
                flippedCards = [];
            }, flipTime);
        }
        flippedCards = [];
    }
}

function checkForWin() {
    if (cards.every(card => card.match)) {
        gameEnded = true;
        alert('Congratulations! You won!');
    }
}

function flipCard(x, y) {
    if (gameEnded) return;
    const card = cards.find(c => x > c.x && x < c.x + cardWidth && y > c.y && y < c.y + cardHeight);
    if (card && !card.flipped && !card.match) {
        card.flipped = true;
        flippedCards.push(card);
        checkForMatch();
        checkForWin();
    }
}

canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = e.clientX - rect.left;
    const y = e.clientY - rect.top;
    flipCard(x, y);
});

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastTime;
    if (deltaTime >= 1000) {
        timer--;
        if (timer < 0) {
            gameEnded = true;
            alert('Time\'s up! Game over!');
        }
        lastTime = timestamp;
    }
    update();
    if (!gameEnded) {
        requestAnimationFrame(gameLoop);
    }
}

cards.push(...createCards());
requestAnimationFrame(gameLoop);
