const GRAVITY = 0.5;
const DROP_INTERVAL = 1000; // milliseconds
const ENEMY_SPAWN_INTERVAL = 2000; // milliseconds

let lastTime = 0;
let score = 0;
let level = 1;
let dropTime = 0;
let spawnTime = 0;

const blocks = [];
const enemies = [];

class Block {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = BLOCK_SIZE;
        this.height = BLOCK_SIZE;
        this.color = `rgb(${Math.random() * 255}, ${Math.random() * 255}, ${Math.random() * 255})`;
    }

    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }

    update() {
        this.y += GRAVITY;
    }
}

class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = BLOCK_SIZE;
        this.height = BLOCK_SIZE;
        this.color = 'red';
    }

    draw() {
        ctx.fillStyle = this.color;
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }

    update() {
        this.y += GRAVITY;
    }
}

function spawnBlock() {
    const x = Math.random() * (canvas.width - BLOCK_SIZE);
    const y = -BLOCK_SIZE;
    blocks.push(new Block(x, y));
}

function spawnEnemy() {
    const x = Math.random() * (canvas.width - BLOCK_SIZE);
    const y = -BLOCK_SIZE;
    enemies.push(new Enemy(x, y));
}

function update() {
    const now = Date.now();
    const dt = (now - lastTime) / 1000;
    lastTime = now;

    dropTime += dt;
    if (dropTime >= DROP_INTERVAL / (level + 1)) {
        spawnBlock();
        dropTime = 0;
    }

    spawnTime += dt;
    if (spawnTime >= ENEMY_SPAWN_INTERVAL / (level + 1)) {
        spawnEnemy();
        spawnTime = 0;
    }

    blocks.forEach(block => block.update());
    enemies.forEach(enemy => enemy.update());

    // Remove blocks that have fallen off screen
    blocks.forEach((block, index) => {
        if (block.y > canvas.height) {
            blocks.splice(index, 1);
        }
    });

    // Remove enemies that have fallen off screen
    enemies.forEach((enemy, index) => {
        if (enemy.y > canvas.height) {
            enemies.splice(index, 1);
        }
    });
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    blocks.forEach(block => block.draw());
    enemies.forEach(enemy => enemy.draw());

    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
    ctx.fillText(`Level: ${level}`, 10, 60);
}

function gameLoop(time) {
