}

function checkCatch(player, fish) {
  if (player.catchCooldown > 0) {
    player.catchCooldown--;
    return;
  }

  if (player.x < fish.x + fish.width &&
      player.x + player.width > fish.x &&
      player.y < fish.y + fish.height &&
      player.y + player.height > fish.y) {
    fish.caught = true;
    player.catchCooldown = 60; // Cooldown time
  }
}

function checkAICatch(ai, fish) {
  if (ai.catchCooldown > 0) {
    ai.catchCooldown--;
    return;
  }

  if (ai.x < fish.x + fish.width &&
      ai.x + ai.width > fish.x &&
      ai.y < fish.y + fish.height &&
      ai.y + ai.height > fish.y) {
    fish.caught = true;
    ai.catchCooldown = 60; // Cooldown time
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  drawRect(player.x, player.y, player.width, player.height, 'green');
  drawRect(ai.x, ai.y, ai.width, ai.height, 'red');
  drawFish();

  requestAnimationFrame(draw);
}

function gameLoop(keys) {
  updatePlayer(keys);
  updateAI();
  updateFish();
  checkCatch(player, fish);
  checkAICatch(ai, fish);

  draw();
}

const keys = {};
window.addEventListener('keydown', (e) => keys[e.key] = true);
window.addEventListener('keyup', (e) => keys[e.key] = false);

draw();
setInterval(() => gameLoop(keys), 16); // Roughly 60 FPS
