const canvas = document.createElement('canvas');
canvas.width = 480;
canvas.height = 320;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const ROWS = 8;
const COLS = 8;
const TILE_SIZE = 40;
const EMPTY = 0;

const colors = ['#FF0000', '#00FF00', '#0000FF', '#FFFF00', '#00FFFF', '#FF00FF'];

let board = Array.from({ length: ROWS }, () => Array(COLS).fill(EMPTY));
let score = 0;
let gameOver = false;

function randomColor() {
  return Math.floor(Math.random() * colors.length) + 1;
}

function createBoard() {
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      board[r][c] = randomColor();
    }
  }
}

function matchExists() {
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS - 2; c++) {
      if (board[r][c] !== EMPTY && board[r][c] === board[r][c + 1] && board[r][c] === board[r][c + 2]) {
        return true;
      }
    }
  }
  for (let r = 0; r < ROWS - 2; r++) {
    for (let c = 0; c < COLS; c++) {
      if (board[r][c] !== EMPTY && board[r][c] === board[r + 1][c] && board[r][c] === board[r + 2][c]) {
        return true;
      }
    }
  }
  return false;
}

function removeMatches() {
  let removed = false;
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS - 2; c++) {
      if (board[r][c] !== EMPTY && board[r][c] === board[r][c + 1] && board[r][c] === board[r][c + 2]) {
        board[r][c] = board[r][c + 1] = board[r][c + 2] = EMPTY;
        removed = true;
      }
    }
  }
  for (let r = 0; r < ROWS - 2; r++) {
    for (let c = 0; c < COLS; c++) {
      if (board[r][c] !== EMPTY && board[r][c] === board[r + 1][c] && board[r][c] === board[r + 2][c]) {
        board[r][c] = board[r + 1][c] = board[r + 2][c] = EMPTY;
        removed = true;
      }
    }
  }
  return removed;
}

function fillBoard() {
  for (let c = 0; c < COLS; c++) {
    let emptyCount = 0;
    for (let r = ROWS - 1; r >= 0; r--) {
      if (board[r][c] === EMPTY) {
        emptyCount++;
      } else if (emptyCount > 0) {
        board[r + emptyCount][c] = board[r][c];
        board[r][c] = EMPTY;
      }
    }
    for (let r = emptyCount - 1; r >= 0; r--) {
      board[r][c] = randomColor();
    }
  }
}

function swapTiles(r1, c1, r2, c2) {
  [board[r1][c1], board[r2][c2]] = [board[r2][c2], board[r1][c1]];
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let r = 0; r < ROWS; r++) {
    for (let c = 0; c < COLS; c++) {
      if (board[r][c] !== EMPTY) {
        ctx.fillStyle = colors[board[r][c] - 1];
        ctx.fillRect(c * TILE_SIZE, r * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        ctx.strokeStyle = '#000';
        ctx.strokeRect(c * TILE_SIZE, r * TILE_SIZE, TILE_SIZE, TILE_SIZE);
      }
    }
  }
  ctx.fillStyle = '#000';
  ctx.fillText(`Score: ${score}`, 10, 20);
}

function update() {
  if (!gameOver) {
    if (removeMatches()) {
      fillBoard();
      score += 10;
    } else {
      gameOver = true;
    }
  }
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  accumulator += deltaTime;

  while (accumulator >= fixedTimeStep) {
    update();
    accumulator -= fixedTimeStep;
  }

  drawBoard();

  lastTime = timestamp;
  if (!gameOver) {
    requestAnimationFrame(gameLoop);
  }
}

let lastTime = 0;
const fixedTimeStep = 1000 / 30;
let accumulator = 0;

createBoard();
requestAnimationFrame(gameLoop);

canvas.addEventListener('click', (e) => {
  if (!gameOver) {
    const rect = canvas.getBoundingClientRect();
