const jumpStrength = -10;
const gapHeight = 100;
const gapWidth = 50;
const birdSize = 20;
const birdX = 50;

let birdY = canvas.height / 2;
let birdVelocity = 0;
let score = 0;
let gameOver = false;
let pipes = [];

function createPipe() {
    const y = Math.random() * (canvas.height - gapHeight - birdSize * 2) + birdSize * 2;
    pipes.push({ x: canvas.width, y: y });
}

function update() {
    if (gameOver) return;

    birdVelocity += gravity;
    birdY += birdVelocity;

    if (birdY > canvas.height || birdY < 0) {
        gameOver = true;
    }

    if (birdVelocity > 0 && birdY + birdSize >= canvas.height) {
        birdY = canvas.height - birdSize;
        birdVelocity = 0;
    }

    if (pipes.length === 0 || pipes[pipes.length - 1].x < canvas.width - gapWidth * 2) {
        createPipe();
    }

    pipes.forEach(pipe => {
        pipe.x -= 5;

        if (birdX + birdSize > pipe.x && birdX < pipe.x + gapWidth &&
            (birdY < pipe.y || birdY + birdSize > pipe.y + gapHeight)) {
            gameOver = true;
        }

        if (pipe.x + gapWidth < birdX && !pipe.counted) {
            score++;
            pipe.counted = true;
        }
    });

    pipes = pipes.filter(pipe => pipe.x + gapWidth > 0);
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    ctx.fillStyle = 'green';
    ctx.fillRect(0, 0, canvas.width, birdY - birdSize / 2);
    ctx.fillRect(0, birdY + birdSize / 2, canvas.width, canvas.height);

    ctx.fillStyle = 'red';
    ctx.fillRect(birdX, birdY, birdSize, birdSize);

    ctx.fillStyle = 'blue';
    pipes.forEach(pipe => {
        ctx.fillRect(pipe.x, 0, gapWidth, pipe.y);
        ctx.fillRect(pipe.x, pipe.y + gapHeight, gapWidth, canvas.height);
    });

    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);

    if (gameOver) {
        ctx.font = '40px Arial';
        ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
    }
}

function gameLoop() {
    update();
    draw();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
    if (e.code === 'Space' && !gameOver) {
        birdVelocity = jumpStrength;
    } else if (e.code === 'Space' && gameOver) {
        pipes = [];
        birdY = canvas.height / 2;
        birdVelocity = 0;
        score = 0;
        gameOver = false;
