// One-button endless runner with combo multiplier
// Rendered on a canvas sized to the window with devicePixelRatio handling

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let running = false;
let combo = 0;
let score = 0;
let groundLevel = 0.8;
let player = { x: 50, y: groundLevel, width: 20, height: 20, velocity: 0 };
let gravity = 0.5;
let jumpForce = -10;
let obstacles = [];

canvas.width = window.innerWidth * devicePixelRatio;
canvas.height = window.innerHeight * devicePixelRatio;
ctx.scale(devicePixelRatio, devicePixelRatio);

function handleResize() {
    canvas.width = window.innerWidth * devicePixelRatio;
    canvas.height = window.innerHeight * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);
}

window.addEventListener('resize', handleResize);

function startGame() {
    running = true;
    combo = 0;
    score = 0;
    player.y = groundLevel;
    obstacles = [];
    requestAnimationFrame(gameLoop);
}

function gameLoop() {
    if (!running) return;

    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Player physics
    player.velocity += gravity;
    player.y += player.velocity;

    if (player.y > groundLevel) {
        player.y = groundLevel;
        player.velocity = 0;
        combo = 0;
    }

    // Obstacle generation
    if (Math.random() < 0.05) {
        obstacles.push({ x: canvas.width, y: groundLevel, width: 30, height: 30 });
    }

    // Obstacle movement and collision detection
    for (let i = obstacles.length - 1; i >= 0; i--) {
        obstacles[i].x -= 5;
        if (obstacles[i].x + obstacles[i].width < 0) {
            obstacles.splice(i, 1);
            combo = 0;
        } else if (
            player.x < obstacles[i].x + obstacles[i].width &&
            player.x + player.width > obstacles[i].x &&
            player.y < obstacles[i].y + obstacles[i].height &&
            player.y + player.height > obstacles[i].y
        ) {
            running = false;
            alert(`Game Over! Your score: ${score}`);
            return;
        }
    }

    // Increase score and combo
    score++;
    combo++;

    // Rendering
    ctx.fillStyle = 'green';
    ctx.fillRect(player.x, player.y, player.width, player.height);

    ctx.fillStyle = 'red';
    obstacles.forEach(obstacle => ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height));

    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score} Combo: ${combo}`, 10, 20);

    requestAnimationFrame(gameLoop);
}

function jump() {
    if (player.y === groundLevel) {
        player.velocity = jumpForce;
        combo++;
    }
}

canvas.addEventListener('click', jump);
document.addEventListener('keydown', (e) => {
    if (e.code === 'Space') jump();
});

startGame();
