// asteroids-style space game with basic AI opponent

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.style.position = 'absolute';
canvas.style.left = '0';
canvas.style.top = '0';
canvas.style.width = '100vw';
canvas.style.height = '100vh';
const dpr = window.devicePixelRatio || 1;
canvas.width = canvas.clientWidth * dpr;
canvas.height = canvas.clientHeight * dpr;
const ctx = canvas.getContext('2d');
ctx.scale(dpr, dpr);

class Ship {
  constructor(x, y, angle) {
    this.x = x;
    this.y = y;
    this.angle = angle;
    this.vx = 0;
    this.vy = 0;
    this.radius = 10;
    this.isAI = false;
  }

  draw() {
    ctx.save();
    ctx.translate(this.x, this.y);
    ctx.rotate(this.angle);
    ctx.beginPath();
    ctx.moveTo(10, 0);
    ctx.lineTo(-5, -5);
    ctx.lineTo(-5, 5);
    ctx.closePath();
    ctx.fillStyle = this.isAI ? 'blue' : 'red';
    ctx.fill();
    ctx.restore();
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    this.x = (this.x + canvas.width) % canvas.width;
    this.y = (this.y + canvas.height) % canvas.height;
  }

  accelerate() {
    this.vx += Math.cos(this.angle) * 0.1;
    this.vy += Math.sin(this.angle) * 0.1;
  }

  turn(dir) {
    this.angle += dir * Math.PI / 60;
  }

  shoot() {
    bullets.push(new Bullet(this.x, this.y, this.angle));
  }
}

class Bullet {
  constructor(x, y, angle) {
    this.x = x;
    this.y = y;
    this.angle = angle;
    this.vx = Math.cos(angle) * 5;
    this.vy = Math.sin(angle) * 5;
    this.radius = 3;
  }

  draw() {
    ctx.beginPath();
    ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'yellow';
    ctx.fill();
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    this.x = (this.x + canvas.width) % canvas.width;
    this.y = (this.y + canvas.height) % canvas.height;
  }
}

class Asteroid {
  constructor(x, y, size) {
    this.x = x;
    this.y = y;
    this.size = size;
    this.radius = size * 10;
    this.vx = (Math.random() - 0.5) * 2;
    this.vy = (Math.random() - 0.5) * 2;
    this.angle = Math.random() * Math.PI * 2;
    this.rotationSpeed = (Math.random() - 0.5) * 0.02;
  }

  draw() {
    ctx.save();
    ctx.translate(this.x, this.y);
    ctx.rotate(this.angle);
    ctx.beginPath();
    for (let i = 0; i < 10; i++) {
      const angle = i * Math.PI * 2 / 10;
      const dx = this.radius * Math.cos(angle);
      const dy = this.radius * Math.sin(angle);
      ctx.lineTo(dx, dy);
    }
    ctx.closePath();
    ctx.fillStyle = 'gray';
    ctx.fill();
    ctx.restore();
  }

  update() {
    this.x += this.vx;
    this.y += this.vy;
    this.angle += this.rotationSpeed;
    this.x = (this.x + canvas.width) % canvas.width;
    this.y = (this.y + canvas.height) % canvas.height;
  }

  split() {
    if (this.size > 1) {
      for (let i = 0; i < 3; i++) {
        asteroids.push(new Asteroid(this.x, this.y, this.size - 1));
      }
    }
  }
}

const player = new Ship(canvas.width / 2, canvas.height / 2, Math.PI / 2);
const ai = new Ship(canvas.width / 4, canvas.height / 4, Math.PI / 2);
ai.isAI = true;
const bullets = [];
const asteroids = [];
for (let i = 0; i < 5; i++) {
  asteroids.push(new Asteroid(Math.random() * canvas.width, Math.random() * canvas.height, 3));
}

function handleInput() {
  if (keys['ArrowUp'] || keys['w']) player.accelerate();
  if (keys['ArrowLeft'] || keys['a']) player.turn(-1);
  if (keys['ArrowRight'] || keys['d']) player.turn(1);
  if (keys[' ']) player.shoot();

  if (ai.isAI) {
    const target = player;
    const dx = target.x - ai.x;
    const dy = target.y - ai.y;
    const distance = Math.sqrt(dx * dx + dy * dy);
    ai.angle = Math.atan2(dy, dx);
    if (distance < 200) {
      ai.accelerate();
      if (Math.random() < 0.02) ai.shoot();
    }
  }
}

function update() {
  handleInput();
  player.update();
  ai.update();
  bullets.forEach(bullet => bullet.update());
  asteroids.forEach(asteroid => asteroid.update());
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  player.draw();
  ai.draw();
  bullets.forEach(bullet => bullet.draw());
  asteroids.forEach(asteroid => asteroid.draw());
}

function checkCollisions() {
  bullets.forEach(bullet => {
    asteroids.forEach(asteroid => {
      const dx = bullet.x - asteroid.x;
      const dy = bullet.y - asteroid.y;
      const distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < bullet.radius + asteroid.radius) {
        asteroids.splice(asteroids.indexOf(asteroid), 1);
        bullets.splice(bullets.indexOf(bullet), 1);
        asteroid.split();
      }
    });
  });
}

function gameLoop() {
  update();
  checkCollisions();
  draw();
  requestAnimationFrame(gameLoop);
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

gameLoop();
