// Game constants
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let width, height, dpr;

// Player settings
const player = {
  x: 0,
  y: 0,
  radius: 5,
  speed: 4,
  angle: Math.PI / 2,
  keys: {
    up: false,
    left: false,
    right: false
  }
};

// Asteroid settings
const asteroids = [];
const asteroidSettings = {
  count: 5,
  minRadius: 10,
  maxRadius: 30,
  speed: 1.5
};

// Bullet settings
const bullets = [];
const bulletSettings = {
  speed: 8,
  life: 60
};

// Game loop
function gameLoop() {
  requestAnimationFrame(gameLoop);
  resizeCanvas();
  update();
  draw();
}

// Resize canvas
function resizeCanvas() {
  width = window.innerWidth;
  height = window.innerHeight;
  dpr = window.devicePixelRatio;
  canvas.width = width * dpr;
  canvas.height = height * dpr;
  ctx.scale(dpr, dpr);
  canvas.style.width = `${width}px`;
  canvas.style.height = `${height}px`;
}

// Update game state
function update() {
  updatePlayer();
  updateAsteroids();
  updateBullets();
}

// Update player position
function updatePlayer() {
  if (player.keys.up) {
    player.x += player.speed * Math.cos(player.angle);
    player.y -= player.speed * Math.sin(player.angle);
  }
  if (player.keys.left) {
    player.angle -= 0.05;
  }
  if (player.keys.right) {
    player.angle += 0.05;
  }
  player.x = (player.x + width) % width;
  player.y = (player.y + height) % height;
}

// Update asteroids
function updateAsteroids() {
  asteroids.forEach(asteroid => {
    asteroid.x += asteroid.speed * Math.cos(asteroid.angle);
    asteroid.y -= asteroid.speed * Math.sin(asteroid.angle);
    asteroid.x = (asteroid.x + width) % width;
    asteroid.y = (asteroid.y + height) % height;
  });
}

// Update bullets
function updateBullets() {
  bullets.forEach(bullet => {
    bullet.x += bullet.speed * Math.cos(bullet.angle);
    bullet.y -= bullet.speed * Math.sin(bullet.angle);
    bullet.life--;
    if (bullet.life <= 0) {
      bullet.remove = true;
    }
  });
  bullets.forEach((bullet, index) => {
    if (bullet.remove) {
      bullets.splice(index, 1);
    }
  });
}

// Draw game state
function draw() {
  ctx.clearRect(0, 0, width, height);
  drawPlayer();
  drawAsteroids();
  drawBullets();
}

// Draw player
function drawPlayer() {
  ctx.save();
  ctx.translate(player.x, player.y);
  ctx.rotate(player.angle);
  ctx.beginPath();
  ctx.arc(0, 0, player.radius, 0, Math.PI * 2);
  ctx.fillStyle = 'white';
  ctx.fill();
  ctx.restore();
}

// Draw asteroids
function drawAsteroids() {
  asteroids.forEach(asteroid => {
    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'gray';
    ctx.fill();
  });
}

// Draw bullets
function drawBullets() {
  bullets.forEach(bullet => {
    ctx.beginPath();
    ctx.arc(bullet.x, bullet.y, 1, 0, Math.PI * 2);
    ctx.fillStyle = 'yellow';
    ctx.fill();
  });
}

// Handle keydown
function handleKeyDown(event) {
  switch (event.key) {
    case 'ArrowUp':
    case 'w':
      player.keys.up = true;
      break;
    case 'ArrowLeft':
    case 'a':
      player.keys.left = true;
      break;
    case 'ArrowRight':
    case 'd':
      player.keys.right = true;
      break;
    case ' ':
      shootBullet();
      break;
  }
}

// Handle keyup
function handleKeyUp(event) {
  switch (event.key) {
    case 'ArrowUp':
    case 'w':
      player.keys.up = false;
      break;
    case 'ArrowLeft':
    case 'a':
      player.keys.left = false;
      break;
    case 'ArrowRight':
    case 'd':
      player.keys.right = false;
      break;
  }
}

// Shoot bullet
function shootBullet() {
  bullets.push({
    x: player.x,
    y: player.y,
    angle: player.angle,
    speed: bulletSettings.speed,
    life: bulletSettings.life
  });
}

// Initialize asteroids
function initializeAsteroids() {
  for (let i = 0; i < asteroidSettings.count; i++) {
    asteroids.push({
      x: Math.random() * width,
      y: Math.random() * height,
      radius: Math.random() * (asteroidSettings.maxRadius - asteroidSettings.minRadius) + asteroidSettings.minRadius,
      angle: Math.random() * Math.PI * 2,
      speed: asteroidSettings.speed
    });
  }
}

// Event listeners
window.addEventListener('resize', resizeCanvas);
window.addEventListener('keydown', handleKeyDown);
window.addEventListener('keyup', handleKeyUp);
window.addEventListener('click', event => {
  const angle = Math.atan2(event.clientY - height / 2, event.clientX - width / 2);
  shootBullet();
});

// Start game
resizeCanvas();
initializeAsteroids();
gameLoop();
