const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 640;
canvas.height = 480;

const snake = [{ x: 10, y: 10 }];
let direction = { x: 0, y: 0 };
let food = { x: 20, y: 20 };
let enemies = [];
let enemySpawnRate = 2000; // milliseconds
let lastEnemySpawn = Date.now();
let difficulty = 1;

function getRandomPosition() {
    return {
        x: Math.floor(Math.random() * (canvas.width / 20)) * 20,
        y: Math.floor(Math.random() * (canvas.height / 20)) * 20
    };
}

function drawRect(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x, y, 20, 20);
}

function update() {
    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    // Check for collision with walls
    if (head.x < 0 || head.x >= canvas.width || head.y < 0 || head.y >= canvas.height) {
        resetGame();
        return;
    }

    // Check for collision with self
    for (let i = 0; i < snake.length; i++) {
        if (head.x === snake[i].x && head.y === snake[i].y) {
            resetGame();
            return;
        }
    }

    // Check for collision with food
    if (head.x === food.x && head.y === food.y) {
        food = getRandomPosition();
        difficulty += 0.1;
        enemySpawnRate -= 100; // Increase difficulty by decreasing enemy spawn rate
    } else {
        snake.pop();
    }

    // Check for collision with enemies
    for (let i = 0; i < enemies.length; i++) {
        if (head.x === enemies[i].x && head.y === enemies[i].y) {
            resetGame();
            return;
        }
    }

    snake.unshift(head);

    // Spawn enemies
    if (Date.now() - lastEnemySpawn > enemySpawnRate) {
        enemies.push(getRandomPosition());
        lastEnemySpawn = Date.now();
    }

    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw snake
    snake.forEach(segment => drawRect(segment.x, segment.y, 'green'));

    // Draw food
    drawRect(food.x, food.y, 'red');

    // Draw enemies
    enemies.forEach(enemy => drawRect(enemy.x, enemy.y, 'blue'));

    requestAnimationFrame(update);
}

function resetGame() {
    snake.length = 1;
    snake[0] = { x: 10, y: 10 };
    direction = { x: 0, y: 0 };
    food = getRandomPosition();
    enemies = [];
    enemySpawnRate = 2000;
    difficulty = 1;
}

document.addEventListener('keydown', e => {
    switch (e.key) {
        case 'ArrowUp':
            if (direction.y === 0) direction = { x: 0, y: -20 };
            break;
        case 'ArrowDown':
            if (direction.y === 0) direction = { x: 0, y: 20 };
            break;
        case 'ArrowLeft':
            if (direction.x === 0) direction = { x: -20, y: 0 };
            break;
        case 'ArrowRight':
            if (direction.x === 0) direction = { x: 20, y: 0 };
            break;
    }
});

update();
