// Ball Drop Game with Enemy Spawner

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let dpr = window.devicePixelRatio || 1;

function resizeCanvas() {
  const width = window.innerWidth;
  const height = window.innerHeight;
  canvas.width = width * dpr;
  canvas.height = height * dpr;
  canvas.style.width = `${width}px`;
  canvas.style.height = `${height}px`;
}

window.addEventListener('resize', resizeCanvas);
resizeCanvas();

const balls = [];
const enemies = [];
let ballRadius = 20;
let enemyRadius = 15;
let gravity = 0.5;
let spawnInterval = 1500;
let lastSpawnTime = Date.now();
let enemySpeed = 2;
let difficulty = 1;
let score = 0;

function random(min, max) {
  return Math.random() * (max - min) + min;
}

function createBall(x, y) {
  balls.push({ x, y, vy: 0, color: 'blue' });
}

function createEnemy(x, y) {
  enemies.push({ x, y, vy: enemySpeed, color: 'red' });
}

function updateBalls() {
  for (let i = balls.length - 1; i >= 0; i--) {
    let ball = balls[i];
    ball.vy += gravity;
    ball.y += ball.vy;

    if (ball.y + ballRadius > canvas.height) {
      ball.y = canvas.height - ballRadius;
      ball.vy = -ball.vy * 0.7; // bounce with energy loss
    }

    if (ball.y < 0) {
      balls.splice(i, 1); // remove if off screen
    }
  }
}

function updateEnemies() {
  for (let i = enemies.length - 1; i >= 0; i--) {
    let enemy = enemies[i];
    enemy.y += enemy.vy;

    if (enemy.y > canvas.height + enemyRadius) {
      enemies.splice(i, 1); // remove if off screen
    }
  }
}

function checkCollisions() {
  for (let i = balls.length - 1; i >= 0; i--) {
    let ball = balls[i];
    for (let j = enemies.length - 1; j >= 0; j--) {
      let enemy = enemies[j];
      let dx = ball.x - enemy.x;
      let dy = ball.y - enemy.y;
      let distance = Math.sqrt(dx * dx + dy * dy);

      if (distance < ballRadius + enemyRadius) {
        balls.splice(i, 1); // ball is hit
        enemies.splice(j, 1); // enemy is destroyed
        score++;
        difficulty += 0.1; // increase difficulty
        spawnInterval = Math.max(500, spawnInterval - 100); // decrease spawn interval
        break;
      }
    }
  }
}

function spawnEnemies() {
  if (Date.now() - lastSpawnTime > spawnInterval) {
    lastSpawnTime = Date.now();
    let x = random(0, canvas.width - enemyRadius * 2);
    let y = -enemyRadius;
    createEnemy(x, y);
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  for (let ball of balls) {
    ctx.beginPath();
    ctx.arc(ball.x * dpr, ball.y * dpr, ballRadius * dpr, 0, Math.PI * 2);
    ctx.fillStyle = ball.color;
    ctx.fill();
  }

  for (let enemy of enemies) {
    ctx.beginPath();
    ctx.arc(enemy.x * dpr, enemy.y * dpr, enemyRadius * dpr, 0, Math.PI * 2);
    ctx.fillStyle = enemy.color;
    ctx.fill();
  }

  ctx.font = `20px Arial`;
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 30);
}

function gameLoop() {
  updateBalls();
  updateEnemies();
  checkCollisions();
  spawnEnemies();
  draw();
  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', (e) => {
  let rect = canvas.getBoundingClientRect();
  let x = (e.clientX - rect.left) / dpr;
  let y = (e.clientY - rect.top) / dpr;
  createBall(x, y);
});

gameLoop();
