const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const player = {
  x: canvas.width / 2,
  y: canvas.height - 50,
  width: 30,
  height: 30,
  speed: 5,
  health: 100
};

const enemies = [];
let enemySpawnInterval = 2000; // Start with 2 seconds
let difficultyRampInterval = 15000; // Increase difficulty every 15 seconds
let lastEnemySpawnTime = 0;
let lastDifficultyRampTime = 0;

function spawnEnemy() {
  enemies.push({
    x: Math.random() * canvas.width,
    y: 0,
    width: 20,
    height: 20,
    speed: 3 + Math.random() * 2 // Vary enemy speed
  });
}

function update() {
  const now = Date.now();

  // Spawn enemies
  if (now - lastEnemySpawnTime > enemySpawnInterval) {
    spawnEnemy();
    lastEnemySpawnTime = now;
  }

  // Ramp up difficulty
  if (now - lastDifficultyRampTime > difficultyRampInterval) {
    enemySpawnInterval = Math.max(enemySpawnInterval - 500, 500); // Decrease spawn interval
    difficultyRampInterval = Math.max(difficultyRampInterval - 5000, 5000); // Decrease ramp interval
    lastDifficultyRampTime = now;
  }

  // Move player
  if (keys['ArrowLeft'] && player.x > 0) player.x -= player.speed;
  if (keys['ArrowRight'] && player.x < canvas.width - player.width) player.x += player.speed;

  // Move enemies
  enemies.forEach(enemy => {
    enemy.y += enemy.speed;
    if (enemy.y > canvas.height) {
      enemies.splice(enemies.indexOf(enemy), 1);
    }
  });

  // Check for collisions
  enemies.forEach(enemy => {
    if (player.x < enemy.x + enemy.width &&
        player.x + player.width > enemy.x &&
        player.y < enemy.y + enemy.height &&
        player.y + player.height > enemy.y) {
      player.health -= 10;
      enemies.splice(enemies.indexOf(enemy), 1);
      if (player.health <= 0) {
        alert('Game Over!');
        resetGame();
      }
    }
  });
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);

  // Draw enemies
  ctx.fillStyle = 'red';
  enemies.forEach(enemy => {
    ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
  });

  // Draw health bar
  ctx.fillStyle = 'green';
  ctx.fillRect(10, 10, (player.health / 100) * 200, 20);
  ctx.strokeStyle = 'black';
  ctx.strokeRect(10, 10, 200, 20);
}

function resetGame() {
  enemies.length = 0;
  player.health = 100;
  enemySpawnInterval = 2000;
  difficultyRampInterval = 15000;
  lastEnemySpawnTime = 0;
  lastDifficultyRampTime = 0;
}

const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

gameLoop();
