let started = false;
let gameover = false;

function startGame() {
    started = true;
    ball.y = 50;
    ball.vy = 0;
    countdown = 3;
    gameover = false;
}

function update() {
    if (!started) return;

    if (countdown > 0) {
        countdown -= 0.02;
        if (countdown <= 0) {
            countdown = 0;
            started = true;
        }
        return;
    }

    ball.vy += ball.gravity;
    ball.y += ball.vy;

    if (ball.y + ball.radius >= height) {
        ball.vy = -ball.vy * ball.damping;
        ball.y = height - ball.radius;
        if (Math.abs(ball.vy) < 1) {
            gameover = true;
            started = false;
        }
    }
}

function draw() {
    ctx.clearRect(0, 0, width, height);

    if (countdown > 0) {
        ctx.font = '48px Arial';
        ctx.fillStyle = 'black';
        ctx.textAlign = 'center';
        ctx.fillText(Math.ceil(countdown), width / 2, height / 2);
        return;
    }

    ctx.beginPath();
    ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'red';
    ctx.fill();

