        let target = enemies.find(enemy => distance(tower.x, tower.y, enemy.x, enemy.y) <= towerRange);
        if (target) {
            target.health -= towerDamage;
            if (target.health <= 0) {
                enemies.splice(enemies.indexOf(target), 1);
