// Constants
const ROWS = 8;
const COLS = 8;
const TILE_SIZE = 50;
const BOARD_PADDING = 10;
const COUNTDOWN_DURATION = 60; // in seconds

// Initialize canvas
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Device pixel ratio handling
const dpr = window.devicePixelRatio || 1;
canvas.width = (TILE_SIZE * COLS + BOARD_PADDING * 2) * dpr;
canvas.height = (TILE_SIZE * ROWS + BOARD_PADDING * 2 + 50) * dpr; // extra space for timer
canvas.style.width = `${canvas.width / dpr}px`;
canvas.style.height = `${canvas.height / dpr}px`;
ctx.scale(dpr, dpr);

// Colors
const colors = ['#FF4500', '#00FFFF', '#D2691E', '#FFD700', '#8A2BE2', '#ADFF2F', '#FF1493', '#00BFFF'];

// Board
let board = [];
let score = 0;
let countdown = COUNTDOWN_DURATION;

// Initialize board
function initBoard() {
    for (let i = 0; i < ROWS; i++) {
        board[i] = [];
        for (let j = 0; j < COLS; j++) {
            board[i][j] = Math.floor(Math.random() * colors.length);
        }
    }
}

// Draw board
function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < ROWS; i++) {
        for (let j = 0; j < COLS; j++) {
            ctx.fillStyle = colors[board[i][j]];
            ctx.fillRect(BOARD_PADDING + j * TILE_SIZE, BOARD_PADDING + i * TILE_SIZE, TILE_SIZE, TILE_SIZE);
            ctx.strokeStyle = '#000';
            ctx.strokeRect(BOARD_PADDING + j * TILE_SIZE, BOARD_PADDING + i * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        }
    }
}

// Draw countdown timer
function drawTimer() {
    ctx.font = '24px Arial';
    ctx.fillStyle = '#000';
    ctx.fillText(`Time: ${countdown}s`, BOARD_PADDING, canvas.height - 10);
}

// Check matches
function checkMatches() {
    let matches = [];
    // Check horizontal matches
    for (let i = 0; i < ROWS; i++) {
        for (let j = 0; j < COLS - 2; j++) {
            if (board[i][j] === board[i][j + 1] && board[i][j] === board[i][j + 2]) {
                matches.push([i, j], [i, j + 1], [i, j + 2]);
            }
        }
    }
    // Check vertical matches
    for (let j = 0; j < COLS; j++) {
        for (let i = 0; i < ROWS - 2; i++) {
            if (board[i][j] === board[i + 1][j] && board[i][j] === board[i + 2][j]) {
                matches.push([i, j], [i + 1, j], [i + 2, j]);
            }
        }
    }
    return matches;
}

// Remove matches and drop tiles
function removeAndDrop() {
    const matches = checkMatches();
    if (matches.length === 0) return false;

    // Remove matches
    matches.forEach(([i, j]) => board[i][j] = -1);

    // Drop tiles
    for (let j = 0; j < COLS; j++) {
        let emptyIndex = -1;
        for (let i = ROWS - 1; i >= 0; i--) {
            if (board[i][j] === -1) {
                if (emptyIndex === -1) emptyIndex = i;
            } else if (emptyIndex !== -1) {
                board[emptyIndex][j] = board[i][j];
                board[i][j] = -1;
                emptyIndex--;
            }
        }
        // Fill empty spots with new tiles
        for (let i = emptyIndex; i >= 0; i--) {
            board[i][j] = Math.floor(Math.random() * colors.length);
        }
    }
    return true;
}

// Main game loop
function gameLoop() {
    drawBoard();
    drawTimer();
    if (removeAndDrop()) {
        score += 100;
    } else {
        countdown--;
        if (countdown <= 0) {
            alert(`Game Over! Your score: ${score}`);
            initBoard();
            countdown = COUNTDOWN_DURATION;
            score = 0;
        }
    }
    requestAnimationFrame(gameLoop);
}

// Start the game
initBoard();
gameLoop();
