```js
const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const COLS = 8;
const ROWS = 8;
const TILE_SIZE = 50;
const EMPTY = 0;

const colors = ['red', 'blue', 'green', 'yellow', 'purple', 'orange'];

let board = Array.from({ length: ROWS }, () =>
  Array.from({ length: COLS }, () => Math.floor(Math.random() * colors.length) + 1)
);

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      const tile = board[row][col];
      if (tile !== EMPTY) {
        ctx.fillStyle = colors[tile - 1];
        ctx.fillRect(col * TILE_SIZE, row * TILE_SIZE, TILE_SIZE, TILE_SIZE);
        ctx.strokeStyle = 'black';
        ctx.strokeRect(col * TILE_SIZE, row * TILE_SIZE, TILE_SIZE, TILE_SIZE);
      }
    }
  }
}

function matches(row, col) {
  const tile = board[row][col];
  if (tile === EMPTY) return [];

  const matches = [];
  let count = 1;

  // Check horizontal
  for (let c = col + 1; c < COLS && board[row][c] === tile; c++) {
    count++;
  }
  for (let c = col - 1; c >= 0 && board[row][c] === tile; c--) {
    count++;
  }
  if (count >= 3) {
    for (let c = col; c < COLS && board[row][c] === tile; c++) {
      matches.push([row, c]);
    }
    for (let c = col - 1; c >= 0 && board[row][c] === tile; c--) {
      matches.push([row, c]);
    }
  }

  count = 1;

  // Check vertical
  for (let r = row + 1; r < ROWS && board[r][col] === tile; r++) {
    count++;
  }
  for (let r = row - 1; r >= 0 && board[r][col] === tile; r--) {
    count++;
  }
  if (count >= 3) {
    for (let r = row; r < ROWS && board[r][col] === tile; r++) {
      matches.push([r, col]);
    }
    for (let r = row - 1; r >= 0 && board[r][col] === tile; r--) {
      matches.push([r, col]);
    }
  }

  return matches;
}

function clearMatches() {
  let cleared = false;
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      const matches = matches(row, col);
      if (matches.length >= 3) {
        cleared = true;
        for (const [r, c] of matches) {
          board[r][c] = EMPTY;
        }
      }
    }
  }
  return cleared;
}

function dropTiles() {
  for (let col = 0; col < COLS; col++) {
    let emptyRow = ROWS - 1;
    for (let row = ROWS - 1; row >= 0; row--) {
      if (board[row][col] !== EMPTY) {
        board[emptyRow][col] = board[row][col];
        if (emptyRow !== row) {
          board[row][col] = EMPTY;
        }
        emptyRow--;
      }
    }
  }
}

function fillBoard() {
  for (let col = 0; col < COLS; col++) {
    for (let row = 0; row < ROWS; row++) {
      if (board[row][col] === EMPTY) {
        board[row][col] = Math.floor(Math.random() * colors.length) + 1;
      }
    }
  }
}

function aiMove() {
  for (let row = 0; row < ROWS; row++) {
    for (let col = 0; col < COLS; col++) {
      const matches = matches(row, col);
      if (matches.length >= 3) {
        return;
      }
    }
  }

  const randomCol = Math.floor(Math.random() * COLS);
  const randomRow = Math.floor(Math.random() * ROWS);
  const randomTile = Math.floor(Math.random() * colors.length) + 1;

  board[randomRow][randomCol] = randomTile;
}

const fixedTimeStep = 1000 / 30;
let lastTime = 0;
let accumulator = 0;

function gameLoop(timestamp) {
  accumulator += timestamp - lastTime;
  lastTime = timestamp;

  while (accumulator >= fixedTimeStep) {
    accumulator -= fixedTimeStep;

    if (clearMatches()) {
      dropTiles();
      fillBoard();
    } else {
      aiMove();
      clearMatches();
      dropTiles();
      fillBoard();
    }
  }

  drawBoard();
