canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const player = { x: 400, y: 300, width: 20, height: 20, color: 'green' };
const enemies = [];
let enemySpawnRate = 1000; // milliseconds
let difficulty = 1;

function spawnEnemy() {
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height;
    enemies.push({ x, y, size: 10, color: 'red' });
    setTimeout(spawnEnemy, enemySpawnRate);
}

function updateDifficulty() {
    difficulty += 0.1;
    enemySpawnRate = Math.max(500, enemySpawnRate * 0.95);
    setTimeout(updateDifficulty, 30000); // Update difficulty every 30 seconds
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);

    enemies.forEach(enemy => {
        ctx.fillStyle = enemy.color;
        ctx.beginPath();
        ctx.arc(enemy.x, enemy.y, enemy.size, 0, Math.PI * 2);
        ctx.fill();
    });

    requestAnimationFrame(draw);
}

function gameLoop() {
    draw();
    spawnEnemy();
    updateDifficulty();
}

gameLoop();
