const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

const colors = ['#ff0000', '#00ff00', '#0000ff', '#ffff00', '#ff00ff', '#00ffff'];
let score = 0;
let wave = 1;
let tapThreshold = 100;
let tapSpeed = 5;
let tapTimer = 0;
let taps = [];
let gameRunning = true;

class Tap {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.color = colors[Math.floor(Math.random() * colors.length)];
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, 20, 0, Math.PI * 2);
        ctx.fillStyle = this.color;
        ctx.fill();
    }

    update() {
        this.y -= tapSpeed;
    }
}

function createTap() {
    if (Math.random() < 0.05) {
        taps.push(new Tap(Math.random() * canvas.width, canvas.height));
    }
}

function handleTap(event) {
    if (!gameRunning) return;
    const rect = canvas.getBoundingClientRect();
    const x = event.clientX - rect.left;
    const y = event.clientY - rect.top;

    for (let i = taps.length - 1; i >= 0; i--) {
        const tap = taps[i];
        if (Math.hypot(tap.x - x, tap.y - y) < 20) {
            taps.splice(i, 1);
            score++;
            tapThreshold = Math.max(50, tapThreshold - 5);
            break;
        }
    }
}

function update() {
    if (!gameRunning) return;
    tapTimer++;
    if (tapTimer >= tapThreshold) {
        createTap();
        tapTimer = 0;
    }

    for (let i = taps.length - 1; i >= 0; i--) {
        taps[i].update();
        if (taps[i].y < 0) {
            taps.splice(i, 1);
            wave++;
            tapThreshold = Math.max(50, tapThreshold - 5);
            if (wave > 10) {
                gameRunning = false;
                alert(`Game Over! Final Score: ${score}`);
            }
        }
    }
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Wave: ${wave}`, 10, 40);
    taps.forEach(tap => tap.draw());
}

function gameLoop() {
    if (!gameRunning) return;
    update();
    render();
    requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', handleTap);
requestAnimationFrame(gameLoop);
