    spawnEnemy();
    lastEnemySpawn = Date.now();
  }

  updateParticles();
  updateEnemies();

  // Collision detection
  enemies.forEach((enemy, index) => {
    const distance = Math.sqrt(
      Math.pow(enemy.x - tower.x, 2) + Math.pow(enemy.y - tower.y, 2)
    );
    if (distance < tower.radius + enemy.radius) {
      // Particle burst
      for (let i = 0; i < 50; i++) {
