const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let lastTime = 0;
let startTime = 0;
let endTime = 60; // 60 seconds countdown
let maze = [];
const cellSize = 20;
const cols = Math.floor(window.innerWidth / cellSize);
const rows = Math.floor(window.innerHeight / cellSize);
let player = { x: 0, y: 0 };
let goal = { x: cols - 1, y: rows - 1 };
let path = [];
let isGameOver = false;

function initMaze() {
  for (let y = 0; y < rows; y++) {
    maze[y] = [];
    for (let x = 0; x < cols; x++) {
      maze[y][x] = (Math.random() < 0.3);
    }
  }
  maze[player.y][player.x] = false;
  maze[goal.y][goal.x] = false;
  findPath(player.x, player.y, goal.x, goal.y);
}

function findPath(x, y, ex, ey) {
  if (x === ex && y === ey) {
    path.push({ x, y });
    return true;
  }
  maze[y][x] = true;
  if (x > 0 && !maze[y][x - 1] && findPath(x - 1, y, ex, ey)) {
    path.push({ x, y });
    return true;
  }
  if (y > 0 && !maze[y - 1][x] && findPath(x, y - 1, ex, ey)) {
    path.push({ x, y });
    return true;
  }
  if (x < cols - 1 && !maze[y][x + 1] && findPath(x + 1, y, ex, ey)) {
    path.push({ x, y });
    return true;
  }
  if (y < rows - 1 && !maze[y + 1][x] && findPath(x, y + 1, ex, ey)) {
    path.push({ x, y });
    return true;
  }
  return false;
}

function resizeCanvas() {
  canvas.width = window.innerWidth * devicePixelRatio;
  canvas.height = window.innerHeight * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'black';
  for (let y = 0; y < rows; y++) {
    for (let x = 0; x < cols; x++) {
      if (maze[y][x]) {
        ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
      }
    }
  }
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x * cellSize, player.y * cellSize, cellSize, cellSize);
  ctx.fillStyle = 'green';
  ctx.fillRect(goal.x * cellSize, goal.y * cellSize, cellSize, cellSize);
  ctx.fillStyle = 'white';
  ctx.font = '20px Arial';
  ctx.fillText(`Time: ${Math.ceil(endTime - (Date.now() - startTime) / 1000)}`, 10, 30);
  if (isGameOver) {
    ctx.fillStyle = 'red';
    ctx.font = '30px Arial';
    ctx.fillText('Game Over!', canvas.width / 2 - 100, canvas.height / 2);
  }
}

function update(deltaTime) {
  if (isGameOver) return;
  endTime -= deltaTime / 1000;
  if (endTime <= 0) {
    isGameOver = true;
    return;
  }
  const speed = 100; // pixels per second
  if (keys['ArrowUp'] && player.y > 0 && !maze[player.y - 1][player.x]) {
    player.y -= speed * deltaTime / 1000;
  }
  if (keys['ArrowDown'] && player.y < rows - 1 && !maze[player.y + 1][player.x]) {
    player.y += speed * deltaTime / 1000;
  }
  if (keys['ArrowLeft'] && player.x > 0 && !maze[player.y][player.x - 1]) {
    player.x -= speed * deltaTime / 1000;
  }
  if (keys['ArrowRight'] && player.x < cols - 1 && !maze[player.y][player.x + 1]) {
    player.x += speed * deltaTime / 1000;
  }
  if (Math.abs(player.x - goal.x) < cellSize / 2 && Math.abs(player.y - goal.y) < cellSize / 2) {
    isGameOver = true;
  }
}

function gameLoop(time) {
  const deltaTime = time - lastTime;
  lastTime = time;
  update(deltaTime);
  draw();
  requestAnimationFrame(gameLoop);
}

const keys = {};
window.addEventListener('keydown', (e) => keys[e.key] = true);
window.addEventListener('keyup', (e) => keys[e.key] = false);

resizeCanvas();
window.addEventListener('resize', resizeCanvas);
initMaze();
startTime = Date.now();
requestAnimationFrame(gameLoop);
