const bird = {
  x: 50,
  y: height / 2,
  radius: 10,
  velocity: 0,
  gravity: 0.5,
  lift: -10
};

const pipes = [];
const pipeGap = 150;
const pipeWidth = 50;
let pipeSpeed = 2;
let level = 1;

function createPipe() {
  const y = Math.random() * (height - pipeGap);
  pipes.push({ x: width, y });
}

function updateBird() {
  bird.velocity += bird.gravity;
  bird.y += bird.velocity;

  if (bird.y + bird.radius > height || bird.y - bird.radius < 0) {
    resetGame();
  }
}

function updatePipes() {
  pipes.forEach(pipe => {
    pipe.x -= pipeSpeed;
  });

  if (pipes.length === 0 || pipes[0].x < width - pipeWidth * 2) {
    createPipe();
  }

  pipes = pipes.filter(pipe => pipe.x + pipeWidth > 0);
}

function checkCollision() {
  const birdBox = {
    top: bird.y - bird.radius,
    bottom: bird.y + bird.radius,
    left: bird.x - bird.radius,
    right: bird.x + bird.radius
  };

  for (let pipe of pipes) {
    const pipeBox = {
      top: pipe.y,
      bottom: pipe.y + pipeGap,
      left: pipe.x,
      right: pipe.x + pipeWidth
    };

    if (
      birdBox.left < pipeBox.right &&
      birdBox.right > pipeBox.left &&
      birdBox.top < pipeBox.bottom &&
      birdBox.bottom > pipeBox.top
    ) {
      resetGame();
    }
  }
}

function drawBird() {
  ctx.beginPath();
  ctx.arc(bird.x, bird.y, bird.radius, 0, Math.PI * 2);
  ctx.fillStyle = 'yellow';
  ctx.fill();
}

function drawPipes() {
  pipes.forEach(pipe => {
    ctx.fillStyle = 'green';
    ctx.fillRect(pipe.x, 0, pipeWidth, pipe.y);
    ctx.fillRect(pipe.x, pipe.y + pipeGap, pipeWidth, height - pipe.y - pipeGap);
  });
}

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Level: ${level}`, 10, 30);
}

function updateLevel() {
