    level++;
    pipeSpeed += 0.2;
  }
}

function resetGame() {
  pipes.length = 0;
  bird.y = height / 2;
  bird.velocity = 0;
  level = 1;
  pipeSpeed = 2;
}

function gameLoop() {
  ctx.clearRect(0, 0, width, height);

  updateBird();
  updatePipes();
  checkCollision();
  updateLevel();

  drawBird();
  drawPipes();
  drawScore();

