const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const ballRadius = 10;
const powerUpRadius = 5;
const fixedTimestep = 1 / 60;
let lastTime = 0;

class Ball {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.vy = 0;
    }

    update() {
        this.vy += gravity;
        this.y += this.vy;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, ballRadius, 0, Math.PI * 2);
        ctx.fillStyle = 'blue';
        ctx.fill();
        ctx.closePath();
    }

    collidesWithPowerUp(powerUp) {
        const dx = this.x - powerUp.x;
        const dy = this.y - powerUp.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        return distance < ballRadius + powerUp.radius;
    }
}

class PowerUp {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.radius = powerUpRadius;
    }

    draw() {
        ctx.beginPath();
        ctx.arc(this.x, this.y, this.radius, 0, Math.PI * 2);
        ctx.fillStyle = 'red';
        ctx.fill();
        ctx.closePath();
    }
}

const ball = new Ball(canvas.width / 2, canvas.height / 2);
const powerUps = [
    new PowerUp(canvas.width / 4, canvas.height / 4),
    new PowerUp(3 * canvas.width / 4, 3 * canvas.height / 4)
];

function update(time) {
    const deltaTime = (time - lastTime) / 1000;
    const numSteps = Math.floor(deltaTime / fixedTimestep);
    for (let i = 0; i < numSteps; i++) {
        ball.update();
        powerUps.forEach(powerUp => {
            if (ball.collidesWithPowerUp(powerUp)) {
                // Handle power-up collection
                console.log('Power-up collected!');
                // Remove the power-up from the list
                powerUps.splice(powerUps.indexOf(powerUp), 1);
            }
        });
    }
    lastTime = time;
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ball.draw();
    powerUps.forEach(powerUp => powerUp.draw());
}

function mainLoop(time) {
    update(time);
    render();
    requestAnimationFrame(mainLoop);
}

requestAnimationFrame(mainLoop);
