  towerDefense.enemySpawnTimer += 16;

  spawnEnemies();
  moveEnemies();
  drawEnemies();
  moveBullets();
  drawBullets();
  checkCollisions();
  drawTowers();
  drawMoney();
  drawWave();

  if (towerDefense.enemySpawnTimer > towerDefense.enemySpawnInterval) {
    createEnemy();
    towerDefense.enemySpawnTimer = 0;
  }

  requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;
  placeTower(x, y);
});

gameLoop();
