const ASTEROID_COUNT = 10;
const ASTEROID_SPEED = 2;
const BULLET_SPEED = 10;
const SHIP_SPEED = 5;
const SHIP_SIZE = 20;
const BULLET_SIZE = 5;

let asteroids = [];
let bullets = [];
let ship = { x: canvas.width / 2, y: canvas.height / 2, angle: 0 };
let score = 0;
let highScore = localStorage.getItem('highScore') || 0;

function random(min, max) {
  return Math.random() * (max - min) + min;
}

function createAsteroid() {
  return {
    x: random(0, canvas.width),
    y: random(0, canvas.height),
    size: 20,
    speed: ASTEROID_SPEED,
    angle: random(0, 2 * Math.PI)
  };
}

for (let i = 0; i < ASTEROID_COUNT; i++) {
  asteroids.push(createAsteroid());
}

function updateShip() {
  if (keys['ArrowLeft']) ship.angle -= 0.05;
  if (keys['ArrowRight']) ship.angle += 0.05;
  if (keys['ArrowUp']) {
    ship.x += SHIP_SPEED * Math.cos(ship.angle);
    ship.y += SHIP_SPEED * Math.sin(ship.angle);
  }
  if (keys['ArrowDown']) {
    ship.x -= SHIP_SPEED * Math.cos(ship.angle);
    ship.y -= SHIP_SPEED * Math.sin(ship.angle);
  }
  ship.x = (ship.x + canvas.width) % canvas.width;
  ship.y = (ship.y + canvas.height) % canvas.height;
}

function updateBullets() {
  bullets.forEach(bullet => {
    bullet.x += BULLET_SPEED * Math.cos(bullet.angle);
    bullet.y += BULLET_SPEED * Math.sin(bullet.angle);
  });
  bullets = bullets.filter(bullet => bullet.x > 0 && bullet.x < canvas.width && bullet.y > 0 && bullet.y < canvas.height);
}

function updateAsteroids() {
  asteroids.forEach(asteroid => {
    asteroid.x += asteroid.speed * Math.cos(asteroid.angle);
    asteroid.y += asteroid.speed * Math.sin(asteroid.angle);
  });
  asteroids = asteroids.filter(asteroid => asteroid.x > 0 && asteroid.x < canvas.width && asteroid.y > 0 && asteroid.y < canvas.height);
}

function checkCollisions() {
  bullets.forEach(bullet => {
    asteroids = asteroids.filter(asteroid => {
      const distance = Math.sqrt((bullet.x - asteroid.x) ** 2 + (bullet.y - asteroid.y) ** 2);
      if (distance < asteroid.size / 2 + BULLET_SIZE / 2) {
        score++;
        return false;
      }
      return true;
    });
  });
  asteroids.forEach(asteroid => {
    const distance = Math.sqrt((ship.x - asteroid.x) ** 2 + (ship.y - asteroid.y) ** 2);
    if (distance < asteroid.size / 2 + SHIP_SIZE / 2) {
      resetGame();
    }
  });
}

function resetGame() {
  asteroids = [];
  for (let i = 0; i < ASTEROID_COUNT; i++) {
    asteroids.push(createAsteroid());
  }
  score = 0;
  ship = { x: canvas.width / 2, y: canvas.height / 2, angle: 0 };
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.save();
  ctx.translate(ship.x, ship.y);
  ctx.rotate(ship.angle);
  ctx.fillStyle = 'blue';
  ctx.beginPath();
  ctx.moveTo(SHIP_SIZE, 0);
  ctx.lineTo(-SHIP_SIZE / 2, SHIP_SIZE / 2);
  ctx.lineTo(-SHIP_SIZE / 2, -SHIP_SIZE / 2);
  ctx.closePath();
  ctx.fill();
  ctx.restore();

  ctx.fillStyle = 'red';
  bullets.forEach(bullet => {
    ctx.fillRect(bullet.x - BULLET_SIZE / 2, bullet.y - BULLET_SIZE / 2, BULLET_SIZE, BULLET_SIZE);
  });

  ctx.fillStyle = 'gray';
  asteroids.forEach(asteroid => {
    ctx.beginPath();
    ctx.arc(asteroid.x, asteroid.y, asteroid.size / 2, 0, 2 * Math.PI);
    ctx.fill();
  });

  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function gameLoop() {
  const start = performance.now();

  updateShip();
  updateBullets();
  updateAsteroids();
  checkCollisions();

  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }

  render();

  const elapsed = performance.now() - start;
  const delta = 16.67 - elapsed; // Aim for 60 FPS (16.67ms per frame)
  if (delta > 0) {
    setTimeout(gameLoop, delta);
  } else {
    requestAnimationFrame(gameLoop);
  }
}

const keys = {};
document.addEventListener('keydown', e => keys[e.key] = true);
document.addEventListener('keyup', e => keys[e.key] = false);
document.addEventListener('click', () => {
  const bullet = {
    x: ship.x + SHIP_SIZE * Math.cos(ship.angle),
    y: ship.y + SHIP_SIZE * Math.sin(ship.angle),
    angle: ship.angle
  };
  bullets.push(bullet);
});

gameLoop();
