    this.x = x;
    this.y = y;
    this.speed = speed;
    this.color = color;
    this.health = 100;
    this.comboMultiplier = 1;
  }

  update(dt) {
    // Simple movement for demonstration
    this.x += this.speed * dt;
    if (this.x > canvas.width) this.x = 0;
  }

  draw() {
    ctx.fillStyle = this.color;
    ctx.fillRect(this.x, this.y, 20, 20);
  }

  attack(target) {
    target.health -= 10 * this.comboMultiplier;
    this.comboMultiplier += 0.1;
    if (this.comboMultiplier > 3) this.comboMultiplier = 3;
  }
}

const player1 = new Entity(100, 100, 1, 'blue');
const player2 = new Entity(700, 500, -1, 'red');

function update(dt) {
  player1.update(dt);
  player2.update(dt);

  // Simple collision detection for attack
  if (Math.abs(player1.x - player2.x) < 20 && Math.abs(player1.y - player2.y) < 20) {
    player1.attack(player2);
    player2.attack(player1);
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  player1.draw();
  player2.draw();

  // Draw health bars
  ctx.fillStyle = 'green';
  ctx.fillRect(50, 50, player1.health, 10);
  ctx.fillRect(750 - player2.health, 50, player2.health, 10);
}

function gameLoop() {
  const now = performance.now();
  const dt = now - lastTime;
  lastTime = now;

  accumulator += dt;
  while (accumulator >= fixedTimeStep) {
    update(fixedTimeStep / 1000); // Convert to seconds
    accumulator -= fixedTimeStep;
  }

  render();

  requestAnimationFrame(gameLoop);
}

