// Tower Defense Skirmish with Countdown Timer

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
let width, height;

function resize() {
  width = window.innerWidth;
  height = window.innerHeight;
  canvas.width = width * devicePixelRatio;
  canvas.height = height * devicePixelRatio;
  ctx.scale(devicePixelRatio, devicePixelRatio);
  canvas.style.width = width + 'px';
  canvas.style.height = height + 'px';
}

window.addEventListener('resize', resize);
resize();

let gameLoop, countdown = 30;
const enemies = [], towers = [], projectiles = [];
const enemySpeed = 1, towerRange = 100, towerPower = 1, projectileSpeed = 5;

class Enemy {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.width = 20;
    this.height = 20;
  }

  update() {
    this.x -= enemySpeed;
    if (this.x + this.width < 0) {
      enemies.shift();
    }
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

class Tower {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.width = 30;
    this.height = 30;
  }

  update() {
    const target = enemies.find(e => Math.hypot(e.x - this.x, e.y - this.y) < towerRange);
    if (target) {
      projectiles.push(new Projectile(this.x + this.width / 2, this.y + this.height / 2, target));
    }
  }

  draw() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  }
}

class Projectile {
  constructor(x, y, target) {
    this.x = x;
    this.y = y;
    this.target = target;
  }

  update() {
    const angle = Math.atan2(this.target.y - this.y, this.target.x - this.x);
    this.x += Math.cos(angle) * projectileSpeed;
    this.y += Math.sin(angle) * projectileSpeed;

    if (Math.hypot(this.target.x - this.x, this.target.y - this.y) < 10) {
      enemies.splice(enemies.indexOf(this.target), 1);
      projectiles.splice(projectiles.indexOf(this), 1);
    }
  }

  draw() {
    ctx.fillStyle = 'green';
    ctx.beginPath();
    ctx.arc(this.x, this.y, 5, 0, Math.PI * 2);
    ctx.fill();
  }
}

function spawnEnemy() {
  const y = Math.random() * (height - 40);
  enemies.push(new Enemy(width, y));
}

setInterval(spawnEnemy, 2000);

function update() {
  ctx.clearRect(0, 0, width, height);

  enemies.forEach(e => e.update());
  enemies.forEach(e => e.draw());

  towers.forEach(t => t.update());
  towers.forEach(t => t.draw());

  projectiles.forEach(p => p.update());
  projectiles.forEach(p => p.draw());

  countdown -= 0.01666666666666666666666666666667; // Approx 1/60th of a second
  if (countdown <= 0) {
    clearInterval(gameLoop);
    ctx.fillStyle = 'black';
    ctx.font = '30px Arial';
    ctx.fillText('Game Over', width / 2 - 70, height / 2);
  } else {
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Time: ${Math.floor(countdown)}`, 10, 30);
  }
}

towers.push(new Tower(100, 100));
towers.push(new Tower(300, 300));

gameLoop = setInterval(update, 16.666666666666668); // Approx 60 FPS
