function update(deltaTime) {
  if (countdown > 0) {
    countdown -= deltaTime / 1000;
    if (countdown < 0) countdown = 0;
  } else {
    player.x += (keys['ArrowRight'] - keys['ArrowLeft']) * player.speed * deltaTime / 1000;
    player.y += (keys['ArrowDown'] - keys['ArrowUp']) * player.speed * deltaTime / 1000;

    bullets.forEach(bullet => {
      bullet.y -= bulletSpeed * deltaTime / 1000;
    });

    enemies.forEach(enemy => {
      enemy.x += (player.x - enemy.x) * enemy.speed * deltaTime / 1000;
      enemy.y += (player.y - enemy.y) * enemy.speed * deltaTime / 1000;
    });

    bullets.forEach(bullet => {
      enemies.forEach((enemy, index) => {
        if (bullet.x < enemy.x + enemy.width &&
            bullet.x + bullet.width > enemy.x &&
            bullet.y < enemy.y + enemy.height &&
            bullet.y + bullet.height > enemy.y) {
          enemies.splice(index, 1);
        }
      });
    });
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  if (countdown > 0) {
    ctx.fillStyle = 'black';
    ctx.font = '48px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(Math.ceil(countdown), canvas.width / 2, canvas.height / 2);
  } else {
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);

    enemies.forEach(enemy => {
      ctx.fillStyle = enemy.color;
      ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
    });

    bullets.forEach(bullet => {
      ctx.fillStyle = 'black';
      ctx.fillRect(bullet.x, bullet.y, 2, 10);
    });
  }
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTimestamp;
  lastTimestamp = timestamp;

  update(deltaTime);
  draw();

  requestAnimationFrame(gameLoop);
}

const keys = {};
window.addEventListener('keydown', (e) => { keys[e.key] = 1; });
window.addEventListener('keyup', (e) => { keys[e.key] = 0; });

window.addEventListener('click', (e) => {
  if (countdown <= 0) {
    bullets.push({
      x: player.x + player.width / 2 - 1,
      y: player.y
    });
  }
});

spawnEnemies();
gameLoop();
