const paddle = { x: canvas.width / 2 - 50, y: canvas.height - 20, width: 100, height: 10, speed: 5 };
const ball = { x: canvas.width / 2, y: canvas.height / 2, radius: 10, speedX: 5, speedY: -5 };
const bricks = [];
const rows = 5;
const cols = 10;
const brickWidth = canvas.width / cols - 5;
const brickHeight = 20;
const brickPadding = 10;
const brickOffsetTop = 30;
const brickOffsetLeft = 30;

for (let c = 0; c < cols; c++) {
  bricks[c] = [];
  for (let r = 0; r < rows; r++) {
    bricks[c][r] = { x: 0, y: 0, status: 1 };
  }
}

let score = 0;
let lives = 3;
let state = 'menu';

function drawPaddle() {
  ctx.fillStyle = '#0095DD';
  ctx.fillRect(paddle.x, paddle.y, paddle.width, paddle.height);
}

function drawBall() {
  ctx.beginPath();
  ctx.arc(ball.x, ball.y, ball.radius, 0, Math.PI * 2);
  ctx.fillStyle = '#0095DD';
  ctx.fill();
  ctx.closePath();
}

function drawBricks() {
  for (let c = 0; c < cols; c++) {
    for (let r = 0; r < rows; r++) {
      if (bricks[c][r].status === 1) {
        const brickX = (c * (brickWidth + brickPadding)) + brickOffsetLeft;
        const brickY = (r * (brickHeight + brickPadding)) + brickOffsetTop;
        bricks[c][r].x = brickX;
        bricks[c][r].y = brickY;
        ctx.beginPath();
        ctx.rect(brickX, brickY, brickWidth, brickHeight);
        ctx.fillStyle = '#0095DD';
        ctx.fill();
        ctx.closePath();
      }
    }
  }
}

function drawScore() {
  ctx.font = '16px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText(`Score: ${score}`, 8, 20);
}

function drawLives() {
  ctx.font = '16px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText(`Lives: ${lives}`, canvas.width - 65, 20);
}

function collisionDetection() {
  for (let c = 0; c < cols; c++) {
    for (let r = 0; r < rows; r++) {
      const b = bricks[c][r];
      if (b.status === 1) {
        if (ball.x > b.x && ball.x < b.x + brickWidth && ball.y > b.y && ball.y < b.y + brickHeight) {
          ball.speedY = -ball.speedY;
          b.status = 0;
          score++;
          if (score === rows * cols) {
            state = 'gameover';
          }
        }
      }
    }
  }
}

function drawMenu() {
  ctx.font = '24px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText('Press Space to Start', canvas.width / 2 - 100, canvas.height / 2);
}

function drawGameOver() {
  ctx.font = '24px Arial';
  ctx.fillStyle = '#0095DD';
  ctx.fillText('Game Over', canvas.width / 2 - 50, canvas.height / 2);
  ctx.fillText('Press Space to Restart', canvas.width / 2 - 100, canvas.height / 2 + 30);
}

function drawPaused() {
