const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let boardSize = 4;
let tileSpacing = 10;
let tileSize;
let board = Array.from({ length: boardSize }, () => Array(boardSize).fill(0));
let score = 0;

function resize() {
    const ratio = window.devicePixelRatio;
    canvas.width = window.innerWidth * ratio;
    canvas.height = window.innerHeight * ratio;
    canvas.style.width = `${window.innerWidth}px`;
    canvas.style.height = `${window.innerHeight}px`;
    tileSize = (Math.min(window.innerWidth, window.innerHeight) - (boardSize + 1) * tileSpacing) / boardSize;
    ctx.scale(ratio, ratio);
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            ctx.fillStyle = '#BBADA0';
            ctx.fillRect(x * (tileSize + tileSpacing) + tileSpacing, y * (tileSize + tileSpacing) + tileSpacing, tileSize, tileSize);
            if (board[y][x] !== 0) {
                ctx.fillStyle = board[y][x] === 2 ? '#EEE4DA' : board[y][x] === 4 ? '#EDE0C8' : '#F9F6F2';
                ctx.fillRect(x * (tileSize + tileSpacing) + tileSpacing, y * (tileSize + tileSpacing) + tileSpacing, tileSize, tileSize);
                ctx.fillStyle = '#776E65';
                ctx.font = `${Math.min(tileSize, 100)}px Arial`;
                ctx.textAlign = 'center';
                ctx.textBaseline = 'middle';
                ctx.fillText(board[y][x], x * (tileSize + tileSpacing) + tileSpacing + tileSize / 2, y * (tileSize + tileSpacing) + tileSpacing + tileSize / 2);
            }
        }
    }
}

function spawnTile() {
    const emptyTiles = [];
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            if (board[y][x] === 0) {
                emptyTiles.push({ x, y });
            }
        }
    }
    if (emptyTiles.length > 0) {
        const { x, y } = emptyTiles[Math.floor(Math.random() * emptyTiles.length)];
        board[y][x] = Math.random() < 0.9 ? 2 : 4;
    }
}

function move(direction) {
    let moved = false;
    let newBoard = Array.from({ length: boardSize }, () => Array(boardSize).fill(0));

    if (direction === 'up' || direction === 'left') {
        for (let y = 0; y < boardSize; y++) {
            let offset = 0;
            for (let x = (direction === 'left' ? 0 : boardSize - 1); (direction === 'left' ? x < boardSize : x >= 0); (direction === 'left' ? x++ : x--)) {
                if (board[y][x] !== 0) {
                    let newX = x;
                    if (direction === 'left') {
                        while (newX > 0 && board[y][newX - 1] === 0) {
                            newX--;
                        }
                    } else {
                        while (newX < boardSize - 1 && board[y][newX + 1] === 0) {
                            newX++;
                        }
                    }
                    if (newX !== x) {
                        moved = true;
                    }
                    if (newBoard[y][newX] === 0) {
                        newBoard[y][newX] = board[y][x];
                    } else if (newBoard[y][newX] === board[y][x]) {
                        newBoard[y][newX] *= 2;
                        score += newBoard[y][newX];
                        moved = true;
                    }
                }
            }
        }
    } else if (direction === 'down' || direction === 'right') {
        for (let x = 0; x < boardSize; x++) {
            let offset = 0;
            for (let y = (direction === 'down' ? 0 : boardSize - 1); (direction === 'down' ? y < boardSize : y >= 0); (direction === 'down' ? y++ : y--)) {
                if (board[y][x] !== 0) {
                    let newY = y;
                    if (direction === 'down') {
                        while (newY > 0 && board[newY - 1][x] === 0) {
                            newY--;
                        }
                    } else {
                        while (newY < boardSize - 1 && board[newY + 1][x] === 0) {
                            newY++;
                        }
                    }
                    if (newY !== y) {
                        moved = true;
                    }
                    if (newBoard[newY][x] === 0) {
                        newBoard[newY][x] = board[y][x];
                    } else if (newBoard[newY][x] === board[y][x]) {
                        newBoard[newY][x] *= 2;
                        score += newBoard[newY][x];
                        moved = true;
                    }
                }
            }
        }
    }

    board = newBoard;
    if (moved) {
        spawnTile();
    }
}

function aiMove() {
    const directions = ['up', 'down', 'left', 'right'];
    let bestMove = null;
    let bestScore = -Infinity;

    for (const direction of directions) {
        const testBoard = JSON.parse(JSON.stringify(board));
        move.call({ board: testBoard }, direction);
        const testScore = scoreBoard(testBoard);
        if (testScore > bestScore) {
            bestScore = testScore;
            bestMove = direction;
        }
    }

    if (bestMove) {
        move(bestMove);
    }
}

function scoreBoard(board) {
    let score = 0;
    for (let y = 0; y < boardSize; y++) {
        for (let x = 0; x < boardSize; x++) {
            score += board[y][x];
        }
    }
    return score;
}

function gameLoop() {
    resize();
    drawBoard();
    aiMove();
    requestAnimationFrame(gameLoop);
}

function startGame() {
    spawnTile();
    spawnTile();
    gameLoop();
}

window.addEventListener('resize', resize);
startGame();
