function handleCollisions() {
    asteroids.forEach(asteroid => {
        if (distance(player.x, player.y, asteroid.x, asteroid.y) < player.radius + asteroid.radius) {
            gameOver = true;
        }
        bullets.forEach(bullet => {
            if (!bullet.markedForDeletion && distance(bullet.x, bullet.y, asteroid.x, asteroid.y) < bullet.radius + asteroid.radius) {
                score += 10;
                bullet.markedForDeletion = true;
                asteroid.markedForDeletion = true;
            }
        });
    });
}

function distance(x1, y1, x2, y2) {
    return Math.sqrt((x2 - x1) ** 2 + (y2 - y1) ** 2);
}

function animate() {
