    asteroids = asteroids.filter(asteroid => !asteroid.markedForDeletion);
    bullets = bullets.filter(bullet => !bullet.markedForDeletion);

    ctx.font = '20px Arial';
    ctx.fillStyle = 'white';
    ctx.fillText(`Score: ${score}`, 10, 30);

    requestAnimationFrame(animate);
}

