// HTML5 Canvas Rhythm Tap Game with Collectible Power-Ups

// Get the canvas and context
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Constants
const FPS = 60;
const FIXED_TIMESTEP = 1000 / FPS;
const GRAVITY = 0.5;
const PLAYER_WIDTH = 50;
const PLAYER_HEIGHT = 50;
const POWER_UP_RADIUS = 10;
const TAP_THRESHOLD = 50;

// Game state
let player = {
    x: canvas.width / 2,
    y: canvas.height - PLAYER_HEIGHT,
    dx: 0,
    dy: 0,
    grounded: true
};

let powerUps = [];
let score = 0;
let lastTime = performance.now();
let accumulatedTime = 0;

// Functions
function getRandomInt(min, max) {
    return Math.floor(Math.random() * (max - min + 1)) + min;
}

function spawnPowerUp() {
    powerUps.push({
        x: getRandomInt(0, canvas.width),
        y: -POWER_UP_RADIUS,
        vy: getRandomInt(1, 3)
    });
}

function update(delta) {
    // Player movement
    if (player.grounded) {
        player.dx = 0;
    }
    player.x += player.dx * delta;
    player.y += player.dy * delta;
    player.dy += GRAVITY * delta;

    // Check for ground collision
    if (player.y + PLAYER_HEIGHT >= canvas.height) {
        player.y = canvas.height - PLAYER_HEIGHT;
        player.dy = 0;
        player.grounded = true;
    }

    // Power-up movement and collection
    for (let i = powerUps.length - 1; i >= 0; i--) {
        let powerUp = powerUps[i];
        powerUp.y += powerUp.vy * delta;

        // Check for collision with player
        if (Math.abs(player.x - powerUp.x) < TAP_THRESHOLD &&
            Math.abs(player.y - powerUp.y) < TAP_THRESHOLD) {
            score++;
            powerUps.splice(i, 1);
        }

        // Remove power-up if it goes off screen
        if (powerUp.y > canvas.height) {
            powerUps.splice(i, 1);
        }
    }

    // Spawn new power-up randomly
    if (Math.random() < 0.01) {
        spawnPowerUp();
    }
}

function render() {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw player
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, PLAYER_WIDTH, PLAYER_HEIGHT);

    // Draw power-ups
    ctx.fillStyle = 'red';
    powerUps.forEach(powerUp => {
        ctx.beginPath();
        ctx.arc(powerUp.x, powerUp.y, POWER_UP_RADIUS, 0, Math.PI * 2);
        ctx.fill();
    });

    // Draw score
    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText('Score: ' + score, 10, 30);
}

function gameLoop(timestamp) {
    accumulatedTime += timestamp - lastTime;
    lastTime = timestamp;

    while (accumulatedTime >= FIXED_TIMESTEP) {
        update(FIXED_TIMESTEP / 1000);
        accumulatedTime -= FIXED_TIMESTEP;
    }

    render();
    requestAnimationFrame(gameLoop);
}

// Event listeners
canvas.addEventListener('click', () => {
    if (player.grounded) {
        player.dy = -10;
        player.grounded = false;
    }
});

// Start game loop
requestAnimationFrame(gameLoop);
