  let dx = 0;
  let dy = 0;

  if (keys['ArrowUp'] || keys['w'] || (mousePressed && mouseY < player.y)) {
    dy = -1;
  }
  if (keys['ArrowDown'] || keys['s'] || (mousePressed && mouseY > player.y)) {
    dy = 1;
  }
  if (keys['ArrowLeft'] || keys['a'] || (mousePressed && mouseX < player.x)) {
    dx = -1;
  }
  if (keys['ArrowRight'] || keys['d'] || (mousePressed && mouseX > player.x)) {
    dx = 1;
  }

  if (dx !== 0 || dy !== 0) {
    const angle = Math.atan2(dy, dx);
    const moveX = Math.cos(angle) * player.speed * delta;
    const moveY = Math.sin(angle) * player.speed * delta;

    if (!collides(player.x + moveX, player.y, moveX)) {
      player.x += moveX;
    }
    if (!collides(player.x, player.y + moveY, moveY)) {
      player.y += moveY;
    }
  }
}

function collides(x, y, move) {
  const playerTileX = Math.floor((x + player.width / 2) / tileWidth);
  const playerTileY = Math.floor((y + player.height / 2) / tileHeight);
  const moveX = move > 0 ? 1 : move < 0 ? -1 : 0;
  const moveY = move > 0 ? 1 : move < 0 ? -1 : 0;

  return maze[playerTileY + moveY] && maze[playerTileY + moveY][playerTileX + moveX] === 1;
}

