// HTML5 Canvas Typing Speed Game with Finite State Machine

// Initialize canvas and context
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Game states
const states = {
  MENU: 'menu',
  PLAYING: 'playing',
  PAUSED: 'paused',
  GAMEOVER: 'gameover'
};

let currentState = states.MENU;
let targetText = '';
let inputText = '';
let startTime = 0;
let elapsedTime = 0;
let wordsTyped = 0;

// Generate a random target text
function generateTargetText() {
  const words = [
    'javascript', 'finite', 'state', 'machine', 'typing', 'speed', 'game',
    'canvas', 'requestAnimationFrame', 'developer', 'engineer'
  ];
  targetText = words[Math.floor(Math.random() * words.length)];
}

// Update game logic
function update() {
  switch (currentState) {
    case states.PLAYING:
      elapsedTime = Date.now() - startTime;
      if (inputText === targetText) {
        wordsTyped++;
        inputText = '';
        generateTargetText();
        startTime = Date.now();
      }
      break;
    // Other states don't require updates
  }
}

// Render the game
function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '24px Arial';
  ctx.fillStyle = 'black';

  switch (currentState) {
    case states.MENU:
      ctx.fillText('Typing Speed Game', canvas.width / 2 - 100, canvas.height / 2 - 20);
      ctx.fillText('Press any key to start', canvas.width / 2 - 100, canvas.height / 2 + 20);
      break;
    case states.PLAYING:
      ctx.fillText(`Type: "${targetText}"`, canvas.width / 2 - 100, canvas.height / 2 - 20);
      ctx.fillText(`Typed: "${inputText}"`, canvas.width / 2 - 100, canvas.height / 2);
      ctx.fillText(`Words Typed: ${wordsTyped}`, 10, 30);
      ctx.fillText(`Time: ${(elapsedTime / 1000).toFixed(2)}s`, 10, 60);
      break;
    case states.PAUSED:
      ctx.fillText('Paused', canvas.width / 2 - 30, canvas.height / 2);
      ctx.fillText('Press "P" to resume', canvas.width / 2 - 100, canvas.height / 2 + 30);
      break;
    case states.GAMEOVER:
      ctx.fillText('Game Over', canvas.width / 2 - 40, canvas.height / 2 - 20);
      ctx.fillText(`Final Words Typed: ${wordsTyped}`, canvas.width / 2 - 120, canvas.height / 2);
      ctx.fillText(`Final Time: ${(elapsedTime / 1000).toFixed(2)}s`, canvas.width / 2 - 100, canvas.height / 2 + 30);
      ctx.fillText('Press "R" to restart', canvas.width / 2 - 100, canvas.height / 2 + 60);
      break;
  }
}

// Handle keyboard input
function handleInput(event) {
  const key = event.key;
  switch (currentState) {
    case states.MENU:
      currentState = states.PLAYING;
      generateTargetText();
      startTime = Date.now();
      break;
    case states.PLAYING:
      if (key === 'Escape') {
        currentState = states.PAUSED;
      } else if (key !== 'Backspace') {
        inputText += key;
      } else if (inputText.length > 0) {
        inputText = inputText.slice(0, -1);
      }
      break;
    case states.PAUSED:
      if (key === 'p' || key === 'P') {
        currentState = states.PLAYING;
      }
      break;
    case states.GAMEOVER:
      if (key === 'r' || key === 'R') {
        currentState = states.PLAYING;
        inputText = '';
        wordsTyped = 0;
        generateTargetText();
        startTime = Date.now();
      }
      break;
  }
}

// Game loop
function gameLoop() {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

// Start the game loop
gameLoop();

// Add event listener for keyboard input
document.addEventListener('keydown', handleInput);
