  lastMouseY = Math.floor(e.offsetY / gridSize);
});

canvas.addEventListener('click', (e) => {
  const dir = getDirection(lastMouseX, lastMouseY);
  if (dir.x !== -direction.x && dir.y !== -direction.y) {
    direction = dir;
  }
