const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

// Game constants
const TILE_SIZE = 32;
const PATH_WIDTH = 3 * TILE_SIZE;
const ENEMY_SPEED = 1;
const TOWER_RANGE = 64;
const TOWER_DAMAGE = 10;
const TOWER_COST = 50;
const ENEMY_HEALTH = 50;
const ENEMY_WAVE_INTERVAL = 3000;

// Game state
let waves = 5;
let currentWave = 1;
let enemies = [];
let towers = [];
let score = 0;
let money = 100;
let path = [];
let towerPlacement = false;

// Path setup
function initPath() {
    path = [
        { x: 0, y: 5 * TILE_SIZE },
        { x: 3 * TILE_SIZE, y: 5 * TILE_SIZE },
        { x: 3 * TILE_SIZE, y: 2 * TILE_SIZE },
        { x: 7 * TILE_SIZE, y: 2 * TILE_SIZE },
        { x: 7 * TILE_SIZE, y: 5 * TILE_SIZE },
        { x: 10 * TILE_SIZE, y: 5 * TILE_SIZE }
    ];
}

// Draw path
function drawPath() {
    ctx.strokeStyle = 'brown';
    ctx.lineWidth = PATH_WIDTH;
    ctx.beginPath();
    ctx.moveTo(path[0].x, path[0].y);
    for (let i = 1; i < path.length; i++) {
        ctx.lineTo(path[i].x, path[i].y);
    }
    ctx.stroke();
}

// Enemy class
class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.health = ENEMY_HEALTH;
        this.pathIndex = 0;
    }

    update() {
        const target = path[this.pathIndex];
        const dx = target.x - this.x;
        const dy = target.y - this.y;
        const dist = Math.sqrt(dx * dx + dy * dy);

        if (dist < ENEMY_SPEED) {
            this.pathIndex++;
            if (this.pathIndex >= path.length) {
                // Enemy reached the end, lose health
                score -= 10;
                enemies.splice(enemies.indexOf(this), 1);
            }
        } else {
            this.x += (dx / dist) * ENEMY_SPEED;
            this.y += (dy / dist) * ENEMY_SPEED;
        }
    }

    draw() {
        ctx.fillStyle = 'red';
        ctx.fillRect(this.x, this.y, TILE_SIZE, TILE_SIZE);
    }
}

// Tower class
class Tower {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.range = TOWER_RANGE;
        this.damage = TOWER_DAMAGE;
        this.cooldown = 0;
    }

    update() {
        for (let enemy of enemies) {
            const dx = enemy.x - this.x;
            const dy = enemy.y - this.y;
            const dist = Math.sqrt(dx * dx + dy * dy);

            if (dist < this.range && this.cooldown <= 0) {
                enemy.health -= this.damage;
                if (enemy.health <= 0) {
                    score += 10;
                    enemies.splice(enemies.indexOf(enemy), 1);
                }
                this.cooldown = 10;
            }
        }
        if (this.cooldown > 0) this.cooldown--;
    }

    draw() {
        ctx.fillStyle = 'green';
        ctx.beginPath();
        ctx.arc(this.x + TILE_SIZE / 2, this.y + TILE_SIZE / 2, TOWER_RANGE, 0, Math.PI * 2);
        ctx.fill();
        ctx.fillStyle = 'blue';
        ctx.fillRect(this.x, this.y, TILE_SIZE, TILE_SIZE);
    }
}

// Spawn enemies
function spawnEnemies() {
    if (currentWave > waves) return;

    const waveCount = 5 + (currentWave - 1) * 2;
    for (let i = 0; i < waveCount; i++) {
        enemies.push(new Enemy(path[0].x, path[0].y));
    }

    setTimeout(() => {
        currentWave++;
        spawnEnemies();
    }, ENEMY_WAVE_INTERVAL);
}

// Game loop
function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    drawPath();
    for (let enemy of enemies) {
        enemy.update();
        enemy.draw();
    }

    for (let tower of towers) {
        tower.update();
        tower.draw();
    }

    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`Money: ${money}`, 10, 40);

    requestAnimationFrame(gameLoop);
}

// Place tower
canvas.addEventListener('click', (event) => {
    if (towerPlacement && money >= TOWER_COST) {
        const x = Math.floor(event.clientX / TILE_SIZE) * TILE_SIZE;
        const y = Math.floor(event.clientY / TILE_SIZE) * TILE_SIZE;
        towers.push(new Tower(x, y));
        money -= TOWER_COST;
        towerPlacement = false;
    }
});

// Start the game
initPath();
spawnEnemies();
gameLoop();

// Toggle tower placement
document.addEventListener('keydown', (event) => {
    if (event.key === 't') {
        towerPlacement = !towerPlacement;
    }
});
