  y: canvas.height / 2,
  radius: 10,
  speed: 5,
  color: 'blue'
};

const bullets = [];
const enemies = [];
const particles = [];

function createParticle(x, y, color, velocity) {
  particles.push({
    x,
    y,
    color,
    radius: Math.random() * 2 + 1,
    velocity: {
      x: velocity.x + (Math.random() - 0.5) * 2,
      y: velocity.y + (Math.random() - 0.5) * 2
    },
    alpha: 1
  });
}

function drawCircle(ctx, x, y, radius, color) {
  ctx.beginPath();
  ctx.arc(x, y, radius, 0, Math.PI * 2);
  ctx.fillStyle = color;
  ctx.fill();
}

function updatePlayer() {
  if (keys.w) player.y -= player.speed;
  if (keys.s) player.y += player.speed;
  if (keys.a) player.x -= player.speed;
  if (keys.d) player.x += player.speed;
}

function spawnEnemies() {
  setInterval(() => {
    enemies.push({
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height,
      radius: 10,
      color: 'red',
      velocity: {
        x: (Math.random() - 0.5) * 2,
        y: (Math.random() - 0.5) * 2
      }
    });
  }, 1000);
}

function updateBullets() {
  for (let i = bullets.length - 1; i >= 0; i--) {
    bullets[i].x += bullets[i].velocity.x;
    bullets[i].y += bullets[i].velocity.y;

    if (bullets[i].x < 0 || bullets[i].x > canvas.width || bullets[i].y < 0 || bullets[i].y > canvas.height) {
      bullets.splice(i, 1);
    }
  }
}

function updateEnemies() {
  for (let i = enemies.length - 1; i >= 0; i--) {
    enemies[i].x += enemies[i].velocity.x;
    enemies[i].y += enemies[i].velocity.y;

    if (enemies[i].x < 0 || enemies[i].x > canvas.width || enemies[i].y < 0 || enemies[i].y > canvas.height) {
      enemies.splice(i, 1);
    }
  }
}

function checkCollisions() {
  for (let i = bullets.length - 1; i >= 0; i--) {
    for (let j = enemies.length - 1; j >= 0; j--) {
      const dx = bullets[i].x - enemies[j].x;
      const dy = bullets[i].y - enemies[j].y;
      const distance = Math.sqrt(dx * dx + dy * dy);

      if (distance < bullets[i].radius + enemies[j].radius) {
        for (let k = 0; k < 5; k++) {
          createParticle(enemies[j].x, enemies[j].y, 'green', {
            x: (Math.random() - 0.5) * 5,
            y: (Math.random() - 0.5) * 5
          });
        }
        enemies.splice(j, 1);
        bullets.splice(i, 1);
        break;
      }
    }
  }
}

function updateParticles() {
  for (let i = particles.length - 1; i >= 0; i--) {
    particles[i].velocity.y += 0.1;
    particles[i].x += particles[i].velocity.x;
    particles[i].y += particles[i].velocity.y;
    particles[i].alpha -= 0.01;

    if (particles[i].alpha <= 0) {
      particles.splice(i, 1);
    }
  }
}

function drawParticles() {
  ctx.globalAlpha = 1;
  particles.forEach(particle => {
    ctx.globalAlpha = particle.alpha;
    drawCircle(ctx, particle.x, particle.y, particle.radius, particle.color);
  });
}

function draw() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  drawCircle(ctx, player.x, player.y, player.radius, player.color);

  bullets.forEach(bullet => {
    drawCircle(ctx, bullet.x, bullet.y, 3, 'white');
  });

  enemies.forEach(enemy => {
    drawCircle(ctx, enemy.x, enemy.y, enemy.radius, enemy.color);
  });

  drawParticles();
}

function update() {
  updatePlayer();
  updateBullets();
  updateEnemies();
  checkCollisions();
  updateParticles();
}

function animate() {
  update();
  draw();
  requestAnimationFrame(animate);
}

