const tileSize = 32;
const plotSize = 10;
const plot = Array.from({ length: plotSize }, () => Array(plotSize).fill(0));
const aiPlot = Array.from({ length: plotSize }, () => Array(plotSize).fill(0));

let playerScore = 0;
let aiScore = 0;
let playerTurn = true;

function drawPlot(plot, x, y, color) {
    for (let i = 0; i < plotSize; i++) {
        for (let j = 0; j < plotSize; j++) {
            ctx.fillStyle = plot[i][j] ? color : 'white';
            ctx.fillRect(x + j * tileSize, y + i * tileSize, tileSize, tileSize);
        }
    }
}

function drawScore() {
    ctx.fillStyle = 'black';
    ctx.font = '24px Arial';
    ctx.fillText(`Player: ${playerScore}`, 10, 30);
    ctx.fillText(`AI: ${aiScore}`, canvas.width - 100, 30);
}

function playerAction(x, y) {
    if (playerTurn && plot[y][x] === 0) {
        plot[y][x] = 1;
        playerScore++;
        playerTurn = false;
        aiTurn();
    }
}

function aiTurn() {
    let emptyCells = [];
    for (let i = 0; i < plotSize; i++) {
        for (let j = 0; j < plotSize; j++) {
            if (aiPlot[i][j] === 0) {
                emptyCells.push({ x: j, y: i });
            }
        }
    }
    if (emptyCells.length > 0) {
        const randomCell = emptyCells[Math.floor(Math.random() * emptyCells.length)];
        aiPlot[randomCell.y][randomCell.x] = 1;
        aiScore++;
        playerTurn = true;
    }
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawPlot(plot, 0, 0, 'green');
    drawPlot(aiPlot, canvas.width / 2, 0, 'red');
    drawScore();

    if (!playerTurn && !emptyCells.length) {
        // Game over logic
        ctx.fillStyle = 'black';
        ctx.font = '48px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(`Final Score - Player: ${playerScore}, AI: ${aiScore}`, canvas.width / 2, canvas.height / 2);
    }
}

canvas.addEventListener('click', (e) => {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / tileSize);
    const y = Math.floor((e.clientY - rect.top) / tileSize);
    if (x < plotSize && y < plotSize) {
        playerAction(x, y);
    }
});

function emptyCells() {
    let count = 0;
    for (let i = 0; i < plotSize; i++) {
        for (let j = 0; j < plotSize; j++) {
            if (plot[i][j] === 0) {
                count++;
            }
        }
    }
    return count;
}

