const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const FIXED_TIME_STEP = 1 / 60;
let accumulator = 0;
let lastTime = performance.now();

const player = {
    x: canvas.width / 2,
    y: canvas.height / 2,
    width: 20,
    height: 20,
    color: 'blue',
    speed: 200,
    bullets: []
};

const enemies = [];
const ENEMY_SPAWN_INTERVAL = 2000;
let lastEnemySpawnTime = performance.now();

const score = {
    value: 0,
    color: 'green',
    fontSize: '24px Arial',
    x: 10,
    y: 30
};

function spawnEnemy() {
    enemies.push({
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height,
        width: 15,
        height: 15,
        color: 'red',
        speed: 50
    });
}

function update(delta) {
    // Player movement
    if (keys['ArrowUp'] && player.y > 0) player.y -= player.speed * delta;
    if (keys['ArrowDown'] && player.y < canvas.height - player.height) player.y += player.speed * delta;
    if (keys['ArrowLeft'] && player.x > 0) player.x -= player.speed * delta;
    if (keys['ArrowRight'] && player.x < canvas.width - player.width) player.x += player.speed * delta;

    // Player bullet movement
    player.bullets.forEach((bullet, index) => {
        bullet.y -= 200 * delta;
        if (bullet.y < 0) player.bullets.splice(index, 1);
    });

    // Enemy movement
    enemies.forEach((enemy, index) => {
        enemy.y += enemy.speed * delta;
        if (enemy.y > canvas.height) enemies.splice(index, 1);
    });

    // Enemy spawning
    if (performance.now() - lastEnemySpawnTime > ENEMY_SPAWN_INTERVAL) {
        spawnEnemy();
        lastEnemySpawnTime = performance.now();
    }

    // Collision detection
    player.bullets.forEach((bullet, bulletIndex) => {
        enemies.forEach((enemy, enemyIndex) => {
            if (bullet.x < enemy.x + enemy.width &&
                bullet.x + bullet.width > enemy.x &&
                bullet.y < enemy.y + enemy.height &&
                bullet.y + bullet.height > enemy.y) {
                enemies.splice(enemyIndex, 1);
                player.bullets.splice(bulletIndex, 1);
                score.value++;
            }
        });
    });

    // Game over condition
    enemies.forEach((enemy) => {
        if (enemy.y + enemy.height > canvas.height) {
            // Game over logic
            alert('Game Over! Score: ' + score.value);
            document.location.reload();
        }
    });
}

function render() {
    // Clear canvas
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    // Draw player
    ctx.fillStyle = player.color;
    ctx.fillRect(player.x, player.y, player.width, player.height);

    // Draw bullets
    ctx.fillStyle = 'white';
    player.bullets.forEach((bullet) => {
        ctx.fillRect(bullet.x, bullet.y, 3, 10);
    });

    // Draw enemies
    ctx.fillStyle = enemies[0].color;
    enemies.forEach((enemy) => {
        ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height);
    });

    // Draw score
    ctx.fillStyle = score.color;
    ctx.font = score.fontSize;
    ctx.fillText('Score: ' + score.value, score.x, score.y);
}

function gameLoop(timestamp) {
    const currentTime = timestamp;
    let frameTime = (currentTime - lastTime) / 1000;
    if (frameTime > 0.25) frameTime = 0.25; // Cap the frame time
    lastTime = currentTime;

    accumulator += frameTime;
    while (accumulator >= FIXED_TIME_STEP) {
        update(FIXED_TIME_STEP);
        accumulator -= FIXED_TIME_STEP;
    }

    render();

    requestAnimationFrame(gameLoop);
}

const keys = {};
window.addEventListener('keydown', (e) => {
    keys[e.key] = true;
    if (e.key === ' ') {
        player.bullets.push({
            x: player.x + player.width / 2 - 1.5,
            y: player.y
        });
    }
});
window.addEventListener('keyup', (e) => {
    keys[e.key] = false;
});

gameLoop(performance.now());
