// Typing Speed Game with Particle Burst Effect

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let scale = window.devicePixelRatio;
let width = window.innerWidth;
let height = window.innerHeight;
canvas.width = width * scale;
canvas.height = height * scale;
ctx.scale(scale, scale);

const particles = [];
const maxParticles = 100;
const particleSize = 2;
const particleSpeed = 2;

function random(min, max) {
  return Math.random() * (max - min) + min;
}

function createParticle(x, y) {
  if (particles.length >= maxParticles) return;
  particles.push({
    x,
    y,
    vx: random(-particleSpeed, particleSpeed),
    vy: random(-particleSpeed, particleSpeed),
    size: random(particleSize, particleSize * 2)
  });
}

function updateParticles() {
  for (let i = particles.length - 1; i >= 0; i--) {
    let p = particles[i];
    p.x += p.vx;
    p.y += p.vy;
    p.vy += 0.1; // Gravity effect
    if (p.y > height || p.x < 0 || p.x > width) {
      particles.splice(i, 1);
    }
  }
}

function renderParticles() {
  ctx.fillStyle = 'rgba(255, 255, 255, 0.8)';
  for (let p of particles) {
    ctx.beginPath();
    ctx.arc(p.x, p.y, p.size, 0, Math.PI * 2);
    ctx.fill();
  }
}

function burstParticles(x, y) {
  for (let i = 0; i < 50; i++) {
    createParticle(x, y);
  }
}

function render() {
  ctx.clearRect(0, 0, width, height);
  updateParticles();
  renderParticles();
  requestAnimationFrame(render);
}

canvas.addEventListener('keydown', (e) => {
  burstParticles(e.clientX, e.clientY);
});

window.addEventListener('resize', () => {
  width = window.innerWidth;
  height = window.innerHeight;
  canvas.width = width * scale;
  canvas.height = height * scale;
  ctx.scale(scale, scale);
});

render();
