  canvas.height = window.innerHeight * dpr;
  ctx.scale(dpr, dpr);
}

function initializeGame() {
  cards = [];
  matchedPairs = 0;
  health = 100;
  isRespawning = false;

  cardImages.forEach(img => {
    cards.push({ img, matched: false, flipped: false });
    cards.push({ img, matched: false, flipped: false });
  });

  cards.sort(() => Math.random() - 0.5);

  requestAnimationFrame(gameLoop);
}

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  renderCards();
  renderHealthBar();
  if (isRespawning) {
    health -= 1;
    if (health <= 0) {
      initializeGame();
    }
  }
  requestAnimationFrame(gameLoop);
}

function renderCards() {
  for (let i = 0; i < cards.length; i++) {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const x = col * (cardWidth + margin) + margin;
    const y = row * (cardHeight + margin) + margin;

    ctx.strokeStyle = 'black';
    ctx.lineWidth = 2;

    if (cards[i].flipped || cards[i].matched) {
      const img = new Image();
      img.src = cards[i].img;
      img.onload = () => ctx.drawImage(img, x, y, cardWidth, cardHeight);
    } else {
      ctx.strokeRect(x, y, cardWidth, cardHeight);
    }
  }
}

function renderHealthBar() {
  ctx.fillStyle = 'red';
  ctx.fillRect(10, canvas.height - 30, health, 20);
  ctx.fillStyle = 'black';
  ctx.fillText(`Health: ${health}`, 15, canvas.height - 15);
}

function flipCard(cardIndex) {
  if (flippedCards.length >= 2 || cards[cardIndex].flipped || cards[cardIndex].matched) return;

  cards[cardIndex].flipped = true;
  flippedCards.push(cards[cardIndex]);

  if (flippedCards.length === 2) {
    setTimeout(checkForMatch, 500);
  }
}

function checkForMatch() {
  if (flippedCards[0].img === flippedCards[1].img) {
    flippedCards[0].matched = true;
    flippedCards[1].matched = true;
    matchedPairs++;

    if (matchedPairs === cardImages.length) {
      alert('You win!');
      initializeGame();
    }
  } else {
    isRespawning = true;
    setTimeout(() => {
      flippedCards.forEach(card => card.flipped = false);
      isRespawning = false;
    }, 500);
  }

  flippedCards.length = 0;
}

canvas.addEventListener('click', event => {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;

  for (let i = 0; i < cards.length; i++) {
    const col = i % cols;
    const row = Math.floor(i / cols);
    const cardX = col * (cardWidth + margin) + margin;
    const cardY = row * (cardHeight + margin) + margin;

    if (x >= cardX && x <= cardX + cardWidth && y >= cardY && y <= cardY + cardHeight) {
      flipCard(i);
      break;
    }
  }
});

window.addEventListener('resize', setCanvasSize);
setCanvasSize();
initializeGame();
