// Basic Rhythm Tap Game with AI Opponent

const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
document.body.appendChild(canvas);

let dpr = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * dpr;
canvas.height = window.innerHeight * dpr;
ctx.scale(dpr, dpr);

let playerScore = 0;
let aiScore = 0;
let hitRadius = 20;
let aiDelay = 200; // AI reaction time in milliseconds

let tapInterval = 1500; // Time between taps in milliseconds
let nextTapTime = Date.now() + tapInterval;
let tapPosition = { x: canvas.width / 2, y: canvas.height / 2 };

function getRandomPosition() {
    return {
        x: Math.random() * canvas.width,
        y: Math.random() * canvas.height
    };
}

function drawCircle(x, y, radius, color) {
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.closePath();
}

function update() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    if (Date.now() > nextTapTime) {
        tapPosition = getRandomPosition();
        nextTapTime = Date.now() + tapInterval;
    }

    drawCircle(tapPosition.x, tapPosition.y, hitRadius, 'blue');

    // AI opponent
    if (Date.now() > nextTapTime - aiDelay) {
        aiScore++;
        drawCircle(tapPosition.x, tapPosition.y, hitRadius, 'red');
    }

    requestAnimationFrame(update);
}

canvas.addEventListener('click', (e) => {
    let rect = canvas.getBoundingClientRect();
    let clickX = e.clientX - rect.left;
    let clickY = e.clientY - rect.top;

    if (Math.hypot(clickX - tapPosition.x, clickY - tapPosition.y) < hitRadius) {
        playerScore++;
    }
});

update();

window.addEventListener('resize', () => {
    dpr = window.devicePixelRatio || 1;
    canvas.width = window.innerWidth * dpr;
    canvas.height = window.innerHeight * dpr;
    ctx.scale(dpr, dpr);
});
