});

document.addEventListener('keyup', (e) => {
  switch (e.key) {
    case 'ArrowLeft':
    case 'ArrowRight':
      player.dx = 0;
      break;
    case 'ArrowUp':
    case 'ArrowDown':
      player.dy = 0;
      break;
  }
});

gameLoop();
