// Game state
const gameState = {
  playerHealth: 100,
  enemyHealth: 100,
  enemies: [],
  spawnRate: 2000,
  difficulty: 1,
  lastSpawnTime: 0,
  turn: 'player',
};

// Player and enemy definitions
const player = {
  x: canvas.width / 2,
  y: canvas.height - 50,
  width: 30,
  height: 30,
  color: 'blue',
};

const enemy = {
  x: 0,
  y: 0,
  width: 20,
  height: 20,
  color: 'red',
};

// Game loop
function gameLoop(timestamp) {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Handle enemy spawning
  if (timestamp - gameState.lastSpawnTime > gameState.spawnRate) {
    gameState.lastSpawnTime = timestamp;
    const newEnemy = {
      x: Math.random() * canvas.width,
      y: Math.random() * canvas.height / 2,
      width: enemy.width * gameState.difficulty,
      height: enemy.height * gameState.difficulty,
      color: enemy.color,
    };
    gameState.enemies.push(newEnemy);
  }

  // Draw player
  ctx.fillStyle = player.color;
  ctx.fillRect(player.x - player.width / 2, player.y - player.height / 2, player.width, player.height);

  // Draw enemies
  ctx.fillStyle = enemy.color;
  gameState.enemies.forEach((e) => {
    ctx.fillRect(e.x - e.width / 2, e.y - e.height / 2, e.width, e.height);
  });

  // Handle enemy movement and collision
  gameState.enemies.forEach((e, index) => {
    e.y += 1 + gameState.difficulty * 0.1;
    if (e.y + e.height > player.y - player.height / 2 && e.x + e.width > player.x - player.width / 2 && e.x - e.width < player.x + player.width / 2) {
      gameState.playerHealth -= 10;
      gameState.enemies.splice(index, 1);
    }
  });

  // Ramp difficulty
  if (gameState.playerHealth > 0 && timestamp - gameState.lastSpawnTime > gameState.spawnRate * 5) {
    gameState.difficulty += 0.1;
    gameState.spawnRate *= 0.95;
  }

  // Render health bars
  ctx.fillStyle = 'green';
  ctx.fillRect(10, 10, gameState.playerHealth, 10);
  ctx.fillStyle = 'red';
  ctx.fillRect(10, 30, gameState.enemyHealth, 10);

  // Check game over
  if (gameState.playerHealth <= 0) {
    alert('Game Over! You were defeated.');
    window.location.reload();
  }

  // Request next frame
  requestAnimationFrame(gameLoop);
}

// Start the game
requestAnimationFrame(gameLoop);
