const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const ROWS = 8;
const COLS = 8;
const BLOCK_SIZE = 50;
const COLORS = ['red', 'green', 'blue', 'yellow', 'purple', 'orange'];

let board = [];
let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore')) : 0;
let swapping = false;
let swapPos = null;

function initBoard() {
    for (let i = 0; i < ROWS; i++) {
        board[i] = [];
        for (let j = 0; j < COLS; j++) {
            board[i][j] = Math.floor(Math.random() * COLORS.length);
        }
    }
}

function drawBoard() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let i = 0; i < ROWS; i++) {
        for (let j = 0; j < COLS; j++) {
            ctx.fillStyle = COLORS[board[i][j]];
            ctx.fillRect(j * BLOCK_SIZE, i * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
            ctx.strokeStyle = 'black';
            ctx.strokeRect(j * BLOCK_SIZE, i * BLOCK_SIZE, BLOCK_SIZE, BLOCK_SIZE);
        }
    }
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 20);
    ctx.fillText(`High Score: ${highScore}`, 10, 40);
}

function getMatches() {
    const matches = [];
    for (let i = 0; i < ROWS; i++) {
        for (let j = 0; j < COLS - 2; j++) {
            if (board[i][j] === board[i][j + 1] && board[i][j] === board[i][j + 2]) {
                matches.push([[i, j], [i, j + 1], [i, j + 2]]);
                let k = j + 3;
                while (k < COLS && board[i][k] === board[i][j]) {
                    matches[matches.length - 1].push([i, k]);
                    k++;
                }
            }
        }
    }
    for (let j = 0; j < COLS; j++) {
        for (let i = 0; i < ROWS - 2; i++) {
            if (board[i][j] === board[i + 1][j] && board[i][j] === board[i + 2][j]) {
                matches.push([[i, j], [i + 1, j], [i + 2, j]]);
                let k = i + 3;
                while (k < ROWS && board[k][j] === board[i][j]) {
                    matches[matches.length - 1].push([k, j]);
                    k++;
                }
            }
        }
    }
    return matches;
}

function removeMatches(matches) {
    matches.forEach(match => {
        match.forEach(([i, j]) => {
            board[i][j] = -1;
        });
    });
    score += matches.length * 10;
    if (score > highScore) {
        highScore = score;
        localStorage.setItem('highScore', highScore);
    }
}

function dropBlocks() {
    for (let j = 0; j < COLS; j++) {
        let emptyRow = ROWS - 1;
        for (let i = ROWS - 1; i >= 0; i--) {
            if (board[i][j] === -1) {
                emptyRow--;
            } else {
                if (emptyRow !== i) {
                    board[emptyRow][j] = board[i][j];
                    board[i][j] = -1;
                }
                emptyRow--;
            }
        }
    }
}

function fillEmptySpaces() {
    for (let j = 0; j < COLS; j++) {
        for (let i = 0; i < ROWS; i++) {
            if (board[i][j] === -1) {
                board[i][j] = Math.floor(Math.random() * COLORS.length);
            }
        }
    }
}

function checkAndHandleMatches() {
    const matches = getMatches();
    if (matches.length > 0) {
        removeMatches(matches);
        dropBlocks();
        fillEmptySpaces();
        checkAndHandleMatches();
    }
}

function swapBlocks(pos1, pos2) {
    const [i1, j1] = pos1;
    const [i2, j2] = pos2;
    [board[i1][j1], board[i2][j2]] = [board[i2][j2], board[i1][j1]];
}

function onMouseDown(e) {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / BLOCK_SIZE);
    const y = Math.floor((e.clientY - rect.top) / BLOCK_SIZE);
    if (swapPos) {
        swapBlocks(swapPos, [y, x]);
        swapping = true;
    } else {
        swapPos = [y, x];
    }
}

function onMouseUp() {
    swapPos = null;
}

function gameLoop() {
    if (swapping) {
        checkAndHandleMatches();
        swapping = false;
    }
    drawBoard();
    requestAnimationFrame(gameLoop);
}

canvas.addEventListener('mousedown', onMouseDown);
canvas.addEventListener('mouseup', onMouseUp);

initBoard();
gameLoop();
