      board[i][j] = null;
    });
  });
}

function fillBoard() {
  for (let j = 0; j < boardSize; j++) {
    let nullCount = 0;
    for (let i = boardSize - 1; i >= 0; i--) {
      if (board[i][j] === null) {
        nullCount++;
      } else if (nullCount > 0) {
        board[i + nullCount][j] = board[i][j];
        board[i][j] = null;
      }
    }
    for (let i = nullCount - 1; i >= 0; i--) {
      board[i][j] = getRandomColor();
    }
  }
