  if (selected) {
    const [i, j] = selected;
    if (Math.abs(i - y) + Math.abs(j - x) === 1) {
      handleSwap(i, j, y, x);
    }
    selected = null;
  } else {
    selected = [y, x];
  }
});

function gameLoop() {
