function drawCircle(x, y, radius, color) {
    ctx.fillStyle = color;
    ctx.beginPath();
    ctx.arc(x, y, radius, 0, Math.PI * 2);
    ctx.fill();
}

function drawSnake() {
    snake.forEach(segment => drawRect(segment.x, segment.y, 10, 10, 'green'));
}

function drawFood() {
    drawCircle(food.x, food.y, 5, 'red');
}

function drawHealthBar() {
    const barWidth = (health / maxHealth) * 200;
    drawRect(10, 10, 200, 20, 'white');
    drawRect(10, 10, barWidth, 20, 'blue');
}

function updateSnake() {
    const head = { x: snake[0].x + dx, y: snake[0].y + dy };
    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
        food.x = Math.floor(Math.random() * 79) * 10;
        food.y = Math.floor(Math.random() * 59) * 10;
    } else {
        snake.pop();
    }

    if (head.x < 0 || head.x >= canvas.width || head.y < 0 || head.y >= canvas.height) {
        respawn();
    }

    for (let i = 1; i < snake.length; i++) {
        if (head.x === snake[i].x && head.y === snake[i].y) {
            respawn();
        }
    }
}

function respawn() {
    snake.length = 1;
    snake[0] = { x: 100, y: 100 };
    dx = 10;
    dy = 0;
    health -= 10;
    if (health <= 0) {
        health = maxHealth;
    }
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    updateSnake();
    drawSnake();
    drawFood();
    drawHealthBar();
    requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', event => {
    switch (event.key) {
        case 'ArrowUp':
            if (dy === 0) { dx = 0; dy = -10; }
            break;
        case 'ArrowDown':
            if (dy === 0) { dx = 0; dy = 10; }
            break;
        case 'ArrowLeft':
            if (dx === 0) { dx = -10; dy = 0; }
            break;
        case 'ArrowRight':
            if (dx === 0) { dx = 10; dy = 0; }
            break;
    }
});

