// Tower Defense Skirmish with Combo Multiplier

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let scale = window.devicePixelRatio;
let width = window.innerWidth;
let height = window.innerHeight;
canvas.width = width * scale;
canvas.height = height * scale;
ctx.scale(scale, scale);

const towerRange = 100;
const enemySpeed = 2;
const enemyHealth = 10;
const towerDamage = 1;
const towerCooldown = 500; // milliseconds

let enemies = [];
let towers = [];
let comboMultiplier = 1;
let combo = 0;
let lastHitTime = 0;

class Enemy {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.health = enemyHealth;
  }

  move() {
    this.x -= enemySpeed;
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.beginPath();
    ctx.arc(this.x, this.y, 10, 0, Math.PI * 2);
    ctx.fill();
  }

  isDead() {
    return this.health <= 0;
  }
}

class Tower {
  constructor(x, y) {
    this.x = x;
    this.y = y;
    this.cooldown = towerCooldown;
  }

  draw() {
    ctx.fillStyle = 'blue';
    ctx.beginPath();
    ctx.arc(this.x, this.y, 10, 0, Math.PI * 2);
    ctx.fill();
  }

  canAttack() {
    return this.cooldown <= 0;
  }

  attack() {
    this.cooldown = towerCooldown;
    for (let enemy of enemies) {
      let dx = enemy.x - this.x;
      let dy = enemy.y - this.y;
      let distance = Math.sqrt(dx * dx + dy * dy);
      if (distance < towerRange) {
        enemy.health -= towerDamage * comboMultiplier;
        if (enemy.isDead()) {
          enemies = enemies.filter(e => e !== enemy);
          combo++;
          comboMultiplier = Math.min(combo, 5); // Max combo multiplier of 5
          lastHitTime = Date.now();
        } else {
          combo = 0;
        }
        break;
      }
    }
  }

  updateCooldown() {
    if (this.cooldown > 0) {
      this.cooldown -= Date.now() - lastHitTime;
      lastHitTime = Date.now();
    }
  }
}

function spawnEnemy() {
  enemies.push(new Enemy(width, Math.random() * height));
}

function placeTower(x, y) {
  towers.push(new Tower(x, y));
}

canvas.addEventListener('click', (event) => {
  let rect = canvas.getBoundingClientRect();
  let x = (event.clientX - rect.left) * scale;
  let y = (event.clientY - rect.top) * scale;
  placeTower(x, y);
});

setInterval(() => {
  spawnEnemy();
}, 2000);

function update() {
  ctx.clearRect(0, 0, width, height);

  for (let tower of towers) {
    tower.draw();
    if (tower.canAttack()) {
      tower.attack();
    }
    tower.updateCooldown();
  }

  for (let enemy of enemies) {
    enemy.move();
    enemy.draw();
  }

  requestAnimationFrame(update);
}

update();
