// Falling Block Puzzle Game

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const BLOCK_SIZE = 30;
const PLAYER_WIDTH = 60;
const PLAYER_HEIGHT = 20;
const FALL_SPEED = 0.5;
const SPAWN_RATE = 1000; // milliseconds
const HEALTH_DECREMENT = 10;
const HEALTH_INCREMENT = 100;

let player = {
  x: canvas.width / 2 - PLAYER_WIDTH / 2,
  y: canvas.height - PLAYER_HEIGHT,
  width: PLAYER_WIDTH,
  height: PLAYER_HEIGHT,
  health: 100
};

let blocks = [];
let lastSpawnTime = 0;
let lastUpdateTime = 0;
let isGameOver = false;

function getRandomX() {
  return Math.random() * (canvas.width - BLOCK_SIZE);
}

function spawnBlock() {
  blocks.push({
    x: getRandomX(),
    y: -BLOCK_SIZE,
    width: BLOCK_SIZE,
    height: BLOCK_SIZE
  });
}

function updateBlocks(deltaTime) {
  blocks.forEach(block => {
    block.y += FALL_SPEED * deltaTime;
  });
  blocks = blocks.filter(block => block.y < canvas.height);
}

function checkCollision() {
  blocks.forEach(block => {
    if (block.x < player.x + player.width &&
        block.x + block.width > player.x &&
        block.y < player.y + player.height &&
        block.y + block.height > player.y) {
      player.health -= HEALTH_DECREMENT;
      if (player.health <= 0) {
        isGameOver = true;
      }
      respawnPlayer();
    }
  });
}

function respawnPlayer() {
  player.x = canvas.width / 2 - PLAYER_WIDTH / 2;
  player.y = canvas.height - PLAYER_HEIGHT;
  player.health = Math.min(player.health + HEALTH_INCREMENT, 100);
}

function drawPlayer() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);
}

function drawBlocks() {
  ctx.fillStyle = 'red';
  blocks.forEach(block => {
    ctx.fillRect(block.x, block.y, block.width, block.height);
  });
}

function drawHealthBar() {
  ctx.fillStyle = 'green';
  ctx.fillRect(10, 10, player.health, 20);
}

function gameLoop(timestamp) {
  if (isGameOver) {
    ctx.fillStyle = 'black';
    ctx.font = '50px Arial';
    ctx.fillText('Game Over', canvas.width / 2 - 100, canvas.height / 2);
    return;
  }

  const deltaTime = timestamp - lastUpdateTime;
  lastUpdateTime = timestamp;

  if (timestamp - lastSpawnTime > SPAWN_RATE) {
    spawnBlock();
    lastSpawnTime = timestamp;
  }

  updateBlocks(deltaTime);
  checkCollision();

  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawPlayer();
  drawBlocks();
  drawHealthBar();

  requestAnimationFrame(gameLoop);
}

function handleKeyDown(event) {
  if (event.key === 'ArrowLeft' && player.x > 0) {
    player.x -= 5;
  } else if (event.key === 'ArrowRight' && player.x + player.width < canvas.width) {
    player.x += 5;
  }
}

document.addEventListener('keydown', handleKeyDown);
requestAnimationFrame(gameLoop);
