```js
// Constants
const CANVAS_ID = 'farmingPlot';
const SEED_PRICE = 10;
const WATER_COST = 5;
const HARVEST_REWARD = 50;
const WAVE_DURATION = 10000; // 10 seconds per wave
const MAX_WAVES = 5;

// Game state
let canvas, ctx;
let plot = Array(10).fill().map(() => Array(10).fill(null));
let money = 100;
let wave = 0;
let waveStart = 0;
let isWaveActive = false;
let plotSize = 10; // 10x10 grid

// Initialize canvas
function initCanvas() {
    canvas = document.getElementById(CANVAS_ID);
    ctx = canvas.getContext('2d');
    const dpr = window.devicePixelRatio || 1;
    const width = window.innerWidth;
    const height = window.innerHeight;
    canvas.width = width * dpr;
    canvas.height = height * dpr;
    canvas.style.width = width + 'px';
    canvas.style.height = height + 'px';
    ctx.scale(dpr, dpr);
}

// Draw plot
function drawPlot() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    const cellSize = Math.min(canvas.width, canvas.height) / plotSize;
    for (let y = 0; y < plotSize; y++) {
        for (let x = 0; x < plotSize; x++) {
            ctx.fillStyle = '#7db96f'; // Green background
            ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            if (plot[y][x] === 'seed') {
                ctx.fillStyle = '#f5d76e'; // Yellow for seeds
                ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            } else if (plot[y][x] === 'grown') {
                ctx.fillStyle = '#4caf50'; // Green for grown plants
                ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
            }
        }
    }
}

// Handle click events
function handleClick(e) {
    const rect = canvas.getBoundingClientRect();
    const x = Math.floor((e.clientX - rect.left) / (rect.width / plotSize));
    const y = Math.floor((e.clientY - rect.top) / (rect.height / plotSize));
    if (money >= SEED_PRICE) {
        money -= SEED_PRICE;
        plot[y][x] = 'seed';
    }
}

// Update game state
function update() {
    if (isWaveActive && Date.now() - waveStart >= WAVE_DURATION) {
        wave++;
        waveStart = Date.now();
        isWaveActive = false;
        for (let y = 0; y < plotSize; y++) {
            for (let x = 0; x < plotSize; x++) {
                if (plot[y][x] === 'grown') {
                    money += HARVEST_REWARD;
                }
                plot[y][x] = null;
            }
        }
    }
    if (!isWaveActive && wave < MAX_WAVES) {
        isWaveActive = true;
        waveStart = Date.now();
    }
}

// Main loop
function main() {
    update();
    drawPlot();
    requestAnimationFrame(main);
}

// Start game
window.onload = () => {
    initCanvas();
    canvas.addEventListener('click', handleClick);
    main();
};
