const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const FixedTimestep = 16; // Approximately 60 FPS
let lastTime = performance.now();

const player = {
  x: canvas.width / 2,
  y: canvas.height - 50,
  radius: 20,
  speed: 5,
  color: 'blue',
};

const enemies = [];
const projectiles = [];

function spawnEnemy() {
  enemies.push({
    x: Math.random() * canvas.width,
    y: 0,
    radius: 15,
    speed: 2,
    color: 'red',
  });
}

function update() {
  const now = performance.now();
  const dt = (now - lastTime) / 1000;
  lastTime = now;

  // Handle player movement
  const moveSpeed = player.speed * dt;
  if (keys['ArrowLeft'] || keys['a']) player.x -= moveSpeed;
  if (keys['ArrowRight'] || keys['d']) player.x += moveSpeed;
  if (keys['ArrowUp'] || keys['w']) player.y -= moveSpeed;
  if (keys['ArrowDown'] || keys['s']) player.y += moveSpeed;

  // Spawn enemies
  if (Math.random() < 0.02) {
    spawnEnemy();
  }

  // Update enemies
  for (let i = enemies.length - 1; i >= 0; i--) {
    enemies[i].y += enemies[i].speed * dt;
    if (enemies[i].y > canvas.height) {
      enemies.splice(i, 1);
    }
  }

  // Update projectiles
  for (let i = projectiles.length - 1; i >= 0; i--) {
    projectiles[i].y -= projectiles[i].speed * dt;
    if (projectiles[i].y < 0) {
      projectiles.splice(i, 1);
    }
  }

  // Collision detection
  for (let i = enemies.length - 1; i >= 0; i--) {
    for (let j = projectiles.length - 1; j >= 0; j--) {
      if (
        Math.hypot(
          enemies[i].x - projectiles[j].x,
          enemies[i].y - projectiles[j].y
        ) < enemies[i].radius + projectiles[j].radius
      ) {
        enemies.splice(i, 1);
        projectiles.splice(j, 1);
        break;
      }
    }
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.beginPath();
  ctx.arc(player.x, player.y, player.radius, 0, Math.PI * 2);
  ctx.fillStyle = player.color;
  ctx.fill();

  // Draw enemies
  for (const enemy of enemies) {
    ctx.beginPath();
    ctx.arc(enemy.x, enemy.y, enemy.radius, 0, Math.PI * 2);
    ctx.fillStyle = enemy.color;
    ctx.fill();
  }

  // Draw projectiles
  for (const projectile of projectiles) {
    ctx.beginPath();
    ctx.arc(projectile.x, projectile.y, 2, 0, Math.PI * 2);
    ctx.fillStyle = 'green';
    ctx.fill();
  }
}

function gameLoop(timestamp) {
  requestAnimationFrame(gameLoop);
  update();
  render();
}

// Keyboard controls
const keys = {};
window.addEventListener('keydown', (e) => {
  keys[e.key] = true;
});
window.addEventListener('keyup', (e) => {
  keys[e.key] = false;
});

// Pointer controls
canvas.addEventListener('click', (e) => {
  const rect = canvas.getBoundingClientRect();
  const mouseX = e.clientX - rect.left;
  const mouseY = e.clientY - rect.top;

  projectiles.push({
    x: player.x,
    y: player.y,
    targetX: mouseX,
    targetY: mouseY,
    speed: 10,
  });
});

