const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const cellSize = 20;
const initialSnakeLength = 3;
const initialWaveSpeed = 100;
const waveSpeedDecrease = 20;
const waveSpeedLimit = 50;
const foodColor = '#FF0000';
const snakeColor = '#00FF00';
const backgroundColor = '#000000';

let snake = [];
let direction = { x: 0, y: 0 };
let food = { x: 0, y: 0 };
let wave = 1;
let waveSpeed = initialWaveSpeed;
let lastUpdate = 0;

function getRandomPosition() {
    return {
        x: Math.floor(Math.random() * (canvas.width / cellSize)) * cellSize,
        y: Math.floor(Math.random() * (canvas.height / cellSize)) * cellSize
    };
}

function drawRect(x, y, color) {
    ctx.fillStyle = color;
    ctx.fillRect(x, y, cellSize, cellSize);
}

function resetGame() {
    snake = Array.from({ length: initialSnakeLength }, (_, i) => ({
        x: i * cellSize,
        y: 0
    }));
    direction = { x: cellSize, y: 0 };
    food = getRandomPosition();
    wave = 1;
    waveSpeed = initialWaveSpeed;
}

function update(deltaTime) {
    if (snake.length === 0) {
        resetGame();
    }

    const head = { x: snake[0].x + direction.x, y: snake[0].y + direction.y };

    if (head.x < 0 || head.x >= canvas.width || head.y < 0 || head.y >= canvas.height || snake.some(segment => segment.x === head.x && segment.y === head.y)) {
        resetGame();
        return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
        food = getRandomPosition();
        wave++;
        waveSpeed = Math.max(waveSpeed - waveSpeedDecrease, waveSpeedLimit);
    } else {
        snake.pop();
    }
}

function render() {
    ctx.fillStyle = backgroundColor;
    ctx.fillRect(0, 0, canvas.width, canvas.height);

    drawRect(food.x, food.y, foodColor);

    snake.forEach(segment => drawRect(segment.x, segment.y, snakeColor));

    ctx.fillStyle = '#FFFFFF';
    ctx.font = '20px Arial';
    ctx.fillText(`Wave: ${wave}`, 10, 30);
}

function gameLoop(timestamp) {
    const deltaTime = timestamp - lastUpdate;
    lastUpdate = timestamp;

    update(deltaTime);
    render();

    requestAnimationFrame(gameLoop);
}

canvas.addEventListener('keydown', event => {
    switch (event.key) {
        case 'ArrowUp':
            if (direction.y === 0) direction = { x: 0, y: -cellSize };
            break;
        case 'ArrowDown':
            if (direction.y === 0) direction = { x: 0, y: cellSize };
            break;
        case 'ArrowLeft':
            if (direction.x === 0) direction = { x: -cellSize, y: 0 };
            break;
        case 'ArrowRight':
            if (direction.x === 0) direction = { x: cellSize, y: 0 };
            break;
    }
});

resetGame();
requestAnimationFrame(gameLoop);
