const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let dpr = window.devicePixelRatio;
canvas.width = window.innerWidth * dpr;
canvas.height = window.innerHeight * dpr;
ctx.scale(dpr, dpr);

const maze = {
  width: 20,
  height: 15,
  cellSize: 30,
  grid: [],
  generate() {
    for (let y = 0; y < this.height; y++) {
      this.grid[y] = [];
      for (let x = 0; x < this.width; x++) {
        this.grid[y][x] = (Math.random() > 0.7) ? 1 : 0;
      }
    }
  }
};

const player = {
  x: 1,
  y: 1,
  size: 20,
  color: 'blue',
  move(dx, dy) {
    if (this.x + dx >= 0 && this.x + dx < maze.width && !maze.grid[this.y][this.x + dx]) {
      this.x += dx;
    }
    if (this.y + dy >= 0 && this.y + dy < maze.height && !maze.grid[this.y + dy][this.x]) {
      this.y += dy;
    }
  }
};

const goal = {
  x: maze.width - 2,
  y: maze.height - 2,
  size: 20,
  color: 'green'
};

let score = 0;
let gameOver = false;

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw maze
  ctx.fillStyle = 'gray';
  for (let y = 0; y < maze.height; y++) {
    for (let x = 0; x < maze.width; x++) {
      if (maze.grid[y][x]) {
        ctx.fillRect(x * maze.cellSize, y * maze.cellSize, maze.cellSize, maze.cellSize);
      }
    }
  }

  // Draw player
  ctx.fillStyle = player.color;
  ctx.fillRect(player.x * maze.cellSize + (maze.cellSize - player.size) / 2, 
              player.y * maze.cellSize + (maze.cellSize - player.size) / 2, 
              player.size, player.size);

  // Draw goal
  ctx.fillStyle = goal.color;
  ctx.fillRect(goal.x * maze.cellSize + (maze.cellSize - goal.size) / 2, 
              goal.y * maze.cellSize + (maze.cellSize - goal.size) / 2, 
              goal.size, goal.size);

  // Draw score
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 30);

  if (gameOver) {
    ctx.fillStyle = 'red';
    ctx.fillText('Game Over', canvas.width / 2 - 50, canvas.height / 2);
  }
}

function update() {
  if (player.x === goal.x && player.y === goal.y) {
    score++;
    player.x = 1;
    player.y = 1;
    if (score >= 5) {
      gameOver = true;
    }
  }
}

function gameLoop() {
  if (!gameOver) {
    update();
  }
  draw();
  requestAnimationFrame(gameLoop);
}

maze.generate();
gameLoop();

document.addEventListener('keydown', (e) => {
