// Define constants for game dimensions and properties
const canvas = document.createElement('canvas');
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);

const gravity = 0.5;
const birdWidth = 34;
const birdHeight = 24;
const birdX = 50;
let birdY = canvas.height / 2;
let birdVelocity = 0;
let score = 0;
let gapHeight = 150;
let gapY = Math.random() * (canvas.height - gapHeight);
let enemyWidth = 50;
let enemyX = canvas.width;
let enemyY = 0;
let enemySpeed = 2;
let difficultyIncreaseInterval = 5000; // 5 seconds
let lastDifficultyIncrease = Date.now();

// Draw the bird
function drawBird() {
    ctx.fillStyle = 'yellow';
    ctx.fillRect(birdX, birdY, birdWidth, birdHeight);
}

// Draw the gap
function drawGap() {
    ctx.fillStyle = 'green';
    ctx.fillRect(enemyX, 0, enemyWidth, gapY);
    ctx.fillRect(enemyX, gapY + gapHeight, enemyWidth, canvas.height);
}

// Update bird position
function updateBird() {
    birdVelocity += gravity;
    birdY += birdVelocity;

    // Check for ground collision
    if (birdY + birdHeight > canvas.height) {
        birdY = canvas.height - birdHeight;
        birdVelocity = 0;
    }

    // Check for top collision
    if (birdY < 0) {
        birdY = 0;
        birdVelocity = 0;
    }
}

// Update enemy position
function updateEnemy() {
    enemyX -= enemySpeed;

    // Reset enemy if it goes off screen
    if (enemyX + enemyWidth < 0) {
        enemyX = canvas.width;
        gapY = Math.random() * (canvas.height - gapHeight);
        score++;
    }

    // Increase difficulty
    if (Date.now() - lastDifficultyIncrease > difficultyIncreaseInterval) {
        enemySpeed += 0.5;
        gapHeight -= 5;
        gapHeight = Math.max(gapHeight, 100); // Minimum gap height
        lastDifficultyIncrease = Date.now();
    }
}

// Check for collision
function checkCollision() {
    if (birdX + birdWidth > enemyX && birdX < enemyX + enemyWidth) {
        if (birdY < gapY || birdY + birdHeight > gapY + gapHeight) {
            return true;
        }
    }
    return false;
}

// Draw the score
function drawScore() {
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Score: ${score}`, 10, 30);
}

// Game loop
function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);

    updateBird();
    updateEnemy();

    drawBird();
    drawGap();
    drawScore();

    if (checkCollision()) {
        alert('Game Over! Your score: ' + score);
        // Reset game
        birdY = canvas.height / 2;
        birdVelocity = 0;
        score = 0;
        gapHeight = 150;
        enemySpeed = 2;
        lastDifficultyIncrease = Date.now();
    }

    requestAnimationFrame(gameLoop);
}

// Handle spacebar press to make the bird jump
document.addEventListener('keydown', function(event) {
    if (event.code === 'Space') {
        birdVelocity = -10;
    }
});

// Start the game loop
requestAnimationFrame(gameLoop);
