class Spawner {
  constructor(enemyPool) {
    this.enemyPool = enemyPool;
    this.spawnInterval = 2000; // 2 seconds
    this.lastSpawnTime = 0;
  }

  update(currentTime) {
    if (currentTime - this.lastSpawnTime >= this.spawnInterval) {
      this.lastSpawnTime = currentTime;
      this.spawnEnemy();
    }
  }

  spawnEnemy() {
    console.log('Spawning new enemy');
    this.enemyPool.addEnemy();
  }
}

class EnemyPool {
  constructor() {
    this.enemies = [];
    this.maxEnemies = 5;
  }

  addEnemy() {
    if (this.enemies.length < this.maxEnemies) {
      this.enemies.push(new Enemy());
      console.log('Enemy added to pool');
    } else {
      console.log('Enemy pool is full');
    }
  }

  removeEnemy(enemy) {
    const index = this.enemies.indexOf(enemy);
    if (index !== -1) {
      this.enemies.splice(index, 1);
      console.log('Enemy removed from pool');
    }
  }
}

class Enemy {
  constructor() {
    this.health = 100;
  }

  takeDamage(amount) {
    this.health -= amount;
    console.log(`Enemy took ${amount} damage, health remaining: ${this.health}`);
    if (this.health <= 0) {
      console.log('Enemy defeated');
      return true;
    }
    return false;
  }
}

class Score {
  constructor() {
    this.score = 0;
  }

  increaseScore(points) {
    this.score += points;
    console.log(`Score increased by ${points}, current score: ${this.score}`);
  }
}

class Coordinator {
  constructor() {
    this.enemyPool = new EnemyPool();
    this.spawner = new Spawner(this.enemyPool);
    this.score = new Score();
  }

  start() {
    console.log('Game started');
    this.update(0);
  }

  update(currentTime) {
    this.spawner.update(currentTime);

    // Simulate enemy taking damage
    this.enemyPool.enemies.forEach(enemy => {
      if (enemy.takeDamage(10)) {
        this.enemyPool.removeEnemy(enemy);
        this.score.increaseScore(50);
      }
    });

    // Continue updating
    requestAnimationFrame(timestamp => this.update(timestamp));
  }
}

