  ctx.fillStyle = 'white';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  for (let y = 0; y < boardHeight; y++) {
    for (let x = 0; x < boardWidth; x++) {
      ctx.fillStyle = (x + y) % 2 === 0 ? '#ddd' : '#aaa';
      ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
    }
  }
}

function drawEntities() {
  ctx.fillStyle = player.turn ? 'green' : 'blue';
  ctx.fillRect(player.x * tileSize, player.y * tileSize, tileSize, tileSize);

  ctx.fillStyle = enemy.turn ? 'green' : 'blue';
  ctx.fillRect(enemy.x * tileSize, enemy.y * tileSize, tileSize, tileSize);
}

function handleInput() {
  if (player.turn) {
    const move = { x: 0, y: 0 };

    if (keys['ArrowUp']) move.y = -1;
    if (keys['ArrowDown']) move.y = 1;
    if (keys['ArrowLeft']) move.x = -1;
    if (keys['ArrowRight']) move.x = 1;

    const newX = player.x + move.x;
    const newY = player.y + move.y;

    if (newX >= 0 && newX < boardWidth && newY >= 0 && newY < boardHeight) {
      player.x = newX;
      player.y = newY;
    }
  }
}

