// Constants
const CANVAS_WIDTH = 800;
const CANVAS_HEIGHT = 600;
const PLAYER_SPEED = 5;
const ENEMY_SPEED = 2;
const ENEMY_SPAWN_INTERVAL = 1000; // ms
const DIFFICULTY_INCREASE_INTERVAL = 15000; // ms
const ENEMY_SPEED_INCREASE = 0.5;

// Global Variables
let canvas;
let ctx;
let player;
let enemies = [];
let spawnInterval = ENEMY_SPAWN_INTERVAL;
let difficultyIncreaseInterval = DIFFICULTY_INCREASE_INTERVAL;
let lastSpawnTime = 0;
let lastDifficultyIncreaseTime = 0;

// Player Class
class Player {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = 20;
        this.height = 20;
    }

    draw() {
        ctx.fillStyle = 'blue';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }

    move(dx, dy) {
        this.x += dx;
        this.y += dy;

        // Boundary Check
        if (this.x < 0) this.x = 0;
        if (this.y < 0) this.y = 0;
        if (this.x + this.width > CANVAS_WIDTH) this.x = CANVAS_WIDTH - this.width;
        if (this.y + this.height > CANVAS_HEIGHT) this.y = CANVAS_HEIGHT - this.height;
    }
}

// Enemy Class
class Enemy {
    constructor(x, y) {
        this.x = x;
        this.y = y;
        this.width = 15;
        this.height = 15;
        this.speed = ENEMY_SPEED;
    }

    draw() {
        ctx.fillStyle = 'red';
        ctx.fillRect(this.x, this.y, this.width, this.height);
    }

    move() {
        this.y += this.speed;
        if (this.y + this.height > CANVAS_HEIGHT) {
            this.y = 0;
            this.x = Math.random() * (CANVAS_WIDTH - this.width);
        }
    }
}

// Initialize Game
function init() {
    canvas = document.createElement('canvas');
    canvas.width = CANVAS_WIDTH;
    canvas.height = CANVAS_HEIGHT;
    document.body.appendChild(canvas);
    ctx = canvas.getContext('2d');

    player = new Player(CANVAS_WIDTH / 2, CANVAS_HEIGHT - 30);

    document.addEventListener('keydown', (e) => {
        switch (e.key) {
            case 'ArrowLeft':
                player.move(-PLAYER_SPEED, 0);
                break;
            case 'ArrowRight':
                player.move(PLAYER_SPEED, 0);
                break;
            case 'ArrowUp':
                player.move(0, -PLAYER_SPEED);
                break;
            case 'ArrowDown':
                player.move(0, PLAYER_SPEED);
                break;
        }
    });

    requestAnimationFrame(gameLoop);
}

// Game Loop
function gameLoop(timestamp) {
    ctx.clearRect(0, 0, CANVAS_WIDTH, CANVAS_HEIGHT);

    // Spawn Enemies
    if (timestamp - lastSpawnTime > spawnInterval) {
        enemies.push(new Enemy(Math.random() * (CANVAS_WIDTH - 15), 0));
        lastSpawnTime = timestamp;
    }

    // Increase Difficulty
    if (timestamp - lastDifficultyIncreaseTime > difficultyIncreaseInterval) {
        spawnInterval *= 0.9; // Decrease spawn interval to increase difficulty
        lastDifficultyIncreaseTime = timestamp;
    }

    // Move and Draw Enemies
    enemies.forEach((enemy, index) => {
        enemy.move();
        enemy.draw();

        // Collision Detection
        if (player.x < enemy.x + enemy.width &&
            player.x + player.width > enemy.x &&
            player.y < enemy.y + enemy.height &&
            player.y + player.height > enemy.y) {
            alert('Game Over!');
            resetGame();
        }
    });

    // Draw Player
    player.draw();

    requestAnimationFrame(gameLoop);
}

// Reset Game
function resetGame() {
    enemies = [];
    lastSpawnTime = 0;
    lastDifficultyIncreaseTime = 0;
    spawnInterval = ENEMY_SPAWN_INTERVAL;
}

// Start Game
init();
