    spawnFish();

    fish.forEach(f => {
        f.y += f.speed;
        if (f.y > canvas.height) {
            f.y = 0;
            f.x = Math.random() * canvas.width;
        }
    });

    fish.forEach(f => {
        const dx = f.x - hook.x;
        const dy = f.y - hook.y;
        const distance = Math.sqrt(dx * dx + dy * dy);
        if (distance < f.size && hook.length > 0) {
            f.caught = true;
            score += 10 * level;
            hook.length = 0;
        }
    });

    if (hook.length > 0) {
        hook.length -= reelSpeed;
        if (hook.length < 0) hook.length = 0;
    }

