const ctx = canvas.getContext('2d');

// Game constants
const TPS = 60; // Ticks per second
const TICK_LENGTH = 1000 / TPS; // Milliseconds per tick
const MAZE_WIDTH = 20;
const MAZE_HEIGHT = 15;
const WALL_SIZE = 20;
const PLAYER_SIZE = 20;
const ENEMY_SIZE = 20;
const ENEMY_SPEED = 2;
const COUNTDOWN_DURATION = 15; // seconds

// Game state
let maze = [];
let player = { x: 0, y: 0 };
let enemies = [];
let countdown = COUNTDOWN_DURATION;
let lastTickTime = 0;
let gameOver = false;
let gameStarted = false;

// Initialize maze
function generateMaze() {
    for (let y = 0; y < MAZE_HEIGHT; y++) {
        maze[y] = [];
        for (let x = 0; x < MAZE_WIDTH; x++) {
            maze[y][x] = Math.random() > 0.7; // 30% chance of wall
        }
    }
    player = { x: 1, y: 1 }; // Start player at top-left
    enemies = [
        { x: MAZE_WIDTH - 2, y: 1 },
        { x: 1, y: MAZE_HEIGHT - 2 },
        { x: MAZE_WIDTH - 2, y: MAZE_HEIGHT - 2 }
    ];
}

// Render the maze
function drawMaze() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    for (let y = 0; y < MAZE_HEIGHT; y++) {
        for (let x = 0; x < MAZE_WIDTH; x++) {
            if (maze[y][x]) {
                ctx.fillStyle = 'black';
                ctx.fillRect(x * WALL_SIZE, y * WALL_SIZE, WALL_SIZE, WALL_SIZE);
            }
        }
    }
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x * WALL_SIZE, player.y * WALL_SIZE, PLAYER_SIZE, PLAYER_SIZE);
    ctx.fillStyle = 'red';
    enemies.forEach(enemy => {
        ctx.fillRect(enemy.x * WALL_SIZE, enemy.y * WALL_SIZE, ENEMY_SIZE, ENEMY_SIZE);
    });
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText(`Time: ${Math.floor(countdown)}`, 10, 30);
}

// Update game state
function update() {
    if (!gameStarted) {
        countdown -= TICK_LENGTH / 1000;
        if (countdown <= 0) {
            gameStarted = true;
            countdown = COUNTDOWN_DURATION;
        }
    } else if (!gameOver) {
        // Player movement
        if (keys['ArrowLeft'] && player.x > 0 && !maze[player.y][player.x - 1]) player.x--;
        if (keys['ArrowRight'] && player.x < MAZE_WIDTH - 1 && !maze[player.y][player.x + 1]) player.x++;
        if (keys['ArrowUp'] && player.y > 0 && !maze[player.y - 1][player.x]) player.y--;
        if (keys['ArrowDown'] && player.y < MAZE_HEIGHT - 1 && !maze[player.y + 1][player.x]) player.y++;

        // Enemy movement
        enemies.forEach(enemy => {
            const direction = Math.random() < 0.5 ? -1 : 1;
            if (Math.random() < 0.5) {
                if (enemy.x + direction >= 0 && enemy.x + direction < MAZE_WIDTH && !maze[enemy.y][enemy.x + direction]) {
                    enemy.x += direction;
                }
            } else {
                if (enemy.y + direction >= 0 && enemy.y + direction < MAZE_HEIGHT && !maze[enemy.y + direction][enemy.x]) {
                    enemy.y += direction;
                }
            }
        });

        // Check for collisions
        enemies.forEach(enemy => {
            if (player.x === enemy.x && player.y === enemy.y) {
                gameOver = true;
            }
        });

        countdown -= TICK_LENGTH / 1000;
        if (countdown <= 0) {
            gameOver = true;
        }
    }
}

// Main loop
function mainLoop(timestamp) {
    const delta = timestamp - lastTickTime;
    if (delta >= TICK_LENGTH) {
        lastTickTime = timestamp - (delta % TICK_LENGTH);
        update();
        drawMaze();
    }
    if (!gameOver) {
        requestAnimationFrame(mainLoop);
    } else {
        ctx.fillStyle = 'black';
        ctx.font = '40px Arial';
        ctx.fillText('Game Over!', canvas.width / 2 - 100, canvas.height / 2);
    }
}

// Key tracking
const keys = {};
window.addEventListener('keydown', e => keys[e.key] = true);
window.addEventListener('keyup', e => keys[e.key] = false);

// Start the game
generateMaze();
requestAnimationFrame(mainLoop);
