// Flappy-style gap dodger game with finite state machine

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

// Game states
const states = {
  MENU: 'menu',
  PLAYING: 'playing',
  PAUSED: 'paused',
  GAMEOVER: 'gameover'
};

let currentState = states.MENU;

// Player
const player = {
  x: 50,
  y: 200,
  width: 50,
  height: 50,
  speed: 5,
  velocity: 0,
  gravity: 0.5,
  jumpPower: -10
};

// Obstacles
const obstacles = [];
const obstacleWidth = 75;
const obstacleGap = 150;
let lastObstacleTime = 0;
const obstacleInterval = 1500; // milliseconds

// Game loop variables
let lastFrameTime = 0;

function update(deltaTime) {
  switch (currentState) {
    case states.PLAYING:
      player.velocity += player.gravity;
      player.y += player.velocity;

      // Collision detection with ground
      if (player.y + player.height > canvas.height) {
        player.y = canvas.height - player.height;
        player.velocity = 0;
        currentState = states.GAMEOVER;
      }

      // Obstacle movement
      obstacles.forEach(obstacle => {
        obstacle.x -= player.speed;
      });

      // Remove obstacles off screen
      while (obstacles.length > 0 && obstacles[0].x + obstacleWidth < 0) {
        obstacles.shift();
      }

      // Spawn new obstacle
      if (Date.now() - lastObstacleTime > obstacleInterval) {
        lastObstacleTime = Date.now();
        const obstacleY = Math.random() * (canvas.height - obstacleGap - obstacleWidth);
        obstacles.push({
          x: canvas.width,
          y: obstacleY,
          width: obstacleWidth,
          height: obstacleY
        });
        obstacles.push({
          x: canvas.width,
          y: obstacleY + obstacleGap + obstacleWidth,
          width: obstacleWidth,
          height: canvas.height - obstacleY - obstacleGap - obstacleWidth
        });
      }

      // Collision detection with obstacles
      obstacles.forEach(obstacle => {
        if (player.x < obstacle.x + obstacle.width &&
            player.x + player.width > obstacle.x &&
            player.y < obstacle.y + obstacle.height &&
            player.y + player.height > obstacle.y) {
          currentState = states.GAMEOVER;
        }
      });
      break;
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  switch (currentState) {
    case states.MENU:
      ctx.fillStyle = 'black';
      ctx.fillText('Press Space to Play', canvas.width / 2 - 100, canvas.height / 2);
      break;
    case states.PLAYING:
      // Draw player
      ctx.fillStyle = 'blue';
      ctx.fillRect(player.x, player.y, player.width, player.height);

      // Draw obstacles
      ctx.fillStyle = 'green';
      obstacles.forEach(obstacle => {
        ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
      });
      break;
    case states.PAUSED:
      ctx.fillStyle = 'black';
      ctx.fillText('Game Paused', canvas.width / 2 - 50, canvas.height / 2);
      break;
    case states.GAMEOVER:
      ctx.fillStyle = 'black';
      ctx.fillText('Game Over', canvas.width / 2 - 50, canvas.height / 2);
      ctx.fillText('Press Space to Restart', canvas.width / 2 - 100, canvas.height / 2 + 50);
      break;
  }
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastFrameTime;
  lastFrameTime = timestamp;

  update(deltaTime);
  draw();

  requestAnimationFrame(gameLoop);
}

// Input handling
canvas.addEventListener('keydown', (event) => {
  if (event.code === 'Space') {
    switch (currentState) {
      case states.MENU:
        currentState = states.PLAYING;
        player.velocity = 0;
        player.y = canvas.height / 2;
        obstacles.length = 0;
        lastObstacleTime = Date.now();
        break;
      case states.PLAYING:
        player.velocity = player.jumpPower;
        break;
      case states.PAUSED:
        currentState = states.PLAYING;
        break;
      case states.GAMEOVER:
        currentState = states.MENU;
        break;
    }
  } else if (event.code === 'KeyP') {
    if (currentState === states.PLAYING) {
      currentState = states.PAUSED;
    } else if (currentState === states.PAUSED) {
      currentState = states.PLAYING;
    }
  }
});

gameLoop(performance.now());
