  if (keys['ArrowDown'] && !checkCollision(player.x, player.y + player.size)) player.y += player.size;
  if (keys['ArrowLeft'] && !checkCollision(player.x - player.size, player.y)) player.x -= player.size;
  if (keys['ArrowRight'] && !checkCollision(player.x + player.size, player.y)) player.x += player.size;

  if (player.x >= target.x * player.size && player.x < (target.x + 1) * player.size &&
      player.y >= target.y * player.size && player.y < (target.y + 1) * player.size) {
    alert('You win!');
