  maze.forEach((row, y) => {
    row.forEach((cell, x) => {
      if (cell === 1) {
        ctx.fillStyle = 'black';
        ctx.fillRect(x * player.size, y * player.size, player.size, player.size);
      }
    });
  });

  ctx.fillStyle = player.color;
  ctx.fillRect(player.x, player.y, player.size, player.size);

  ctx.fillStyle = target.color;
  ctx.fillRect(target.x * player.size, target.y * player.size, player.size, player.size);
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

