canvas.height = window.innerHeight * devicePixelRatio;
const ctx = canvas.getContext('2d');

const particles = [];
const plotSize = 100;
const plotGridSize = 10;
const plotCellSize = plotSize / plotGridSize;

function createParticle(x, y, color) {
  return {
    x: x,
    y: y,
    color: color,
    size: Math.random() * 5 + 2,
    life: 100,
    dx: (Math.random() - 0.5) * 2,
    dy: (Math.random() - 0.5) * 2
  };
}

function emitParticles(x, y, color, count = 50) {
  for (let i = 0; i < count; i++) {
    particles.push(createParticle(x, y, color));
  }
}

function drawParticles() {
  ctx.globalCompositeOperation = 'lighter';
  particles.forEach((particle, index) => {
    ctx.beginPath();
    ctx.arc(particle.x, particle.y, particle.size, 0, Math.PI * 2);
    ctx.fillStyle = particle.color;
    ctx.fill();
    particle.x += particle.dx;
    particle.y += particle.dy;
    particle.life--;
    if (particle.life <= 0) {
      particles.splice(index, 1);
    }
  });
  ctx.globalCompositeOperation = 'source-over';
}

function drawPlot() {
  ctx.fillStyle = '#503E2C';
  ctx.fillRect(0, 0, plotSize * devicePixelRatio, plotSize * devicePixelRatio);

  ctx.strokeStyle = '#8B4513';
  ctx.lineWidth = 1 * devicePixelRatio;

  for (let i = 0; i <= plotGridSize; i++) {
    ctx.beginPath();
    ctx.moveTo(i * plotCellSize * devicePixelRatio, 0);
    ctx.lineTo(i * plotCellSize * devicePixelRatio, plotSize * devicePixelRatio);
    ctx.stroke();

    ctx.beginPath();
    ctx.moveTo(0, i * plotCellSize * devicePixelRatio);
    ctx.lineTo(plotSize * devicePixelRatio, i * plotCellSize * devicePixelRatio);
    ctx.stroke();
  }
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.scale(devicePixelRatio, devicePixelRatio);
  drawPlot();
  drawParticles();
  requestAnimationFrame(update);
}

function handleEvent(event, color) {
  emitParticles(event.clientX * devicePixelRatio, event.clientY * devicePixelRatio, color);
}

window.addEventListener('click', (event) => handleEvent(event, '#00FF00'));
window.addEventListener('keydown', (event) => {
  if (event.key === 's') {
    handleEvent(event, '#FF0000');
  }
});

