    ctx.fillRect(this.x, this.y, this.width, this.height);
  }

  moveDown() {
    this.y += 10;
  }
}

class PowerUp extends Block {
  constructor(x, y) {
    super(x, y, 'gold');
  }

  activate() {
    alert('Power-up activated!');
  }
}

const blocks = [];
const powerUps = [];
let playerX = canvas.width / 2 - 15;
let playerY = canvas.height - 40;
let playerWidth = 30;
let playerHeight = 30;
let fallingInterval;
let score = 0;

function createBlock() {
  const x = Math.floor(Math.random() * (canvas.width - 30));
  blocks.push(new Block(x, 0, 'blue'));
}

function createPowerUp() {
  const x = Math.floor(Math.random() * (canvas.width - 30));
  powerUps.push(new PowerUp(x, 0));
}

function movePlayer(direction) {
  if (direction === 'left' && playerX > 0) {
    playerX -= 10;
  } else if (direction === 'right' && playerX < canvas.width - playerWidth) {
    playerX += 10;
  }
}

function checkCollisions() {
  blocks.forEach((block, index) => {
    if (block.y + block.height > playerY &&
        block.x < playerX + playerWidth &&
        block.x + block.width > playerX) {
      alert(`Game Over! Score: ${score}`);
      resetGame();
    }
  });

  powerUps.forEach((powerUp, index) => {
    if (powerUp.y + powerUp.height > playerY &&
        powerUp.x < playerX + playerWidth &&
        powerUp.x + powerUp.width > playerX) {
      powerUp.activate();
      powerUps.splice(index, 1);
    }
  });
}

function resetGame() {
  blocks.length = 0;
  powerUps.length = 0;
  score = 0;
  playerX = canvas.width / 2 - 15;
  clearInterval(fallingInterval);
  fallingInterval = setInterval(() => {
    blocks.forEach(block => block.moveDown());
    powerUps.forEach(powerUp => powerUp.moveDown());
    checkCollisions();
    createBlock();
    if (Math.random() > 0.8) createPowerUp();
  }, 500);
}

function drawPlayer() {
  ctx.fillStyle = 'green';
  ctx.fillRect(playerX, playerY, playerWidth, playerHeight);
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  blocks.forEach(block => block.draw());
  powerUps.forEach(powerUp => powerUp.draw());
  drawPlayer();
  score++;
  requestAnimationFrame(draw);
}

document.addEventListener('keydown', (e) => {
  if (e.key === 'ArrowLeft') movePlayer('left');
  if (e.key === 'ArrowRight') movePlayer('right');
});

resetGame();
draw();
