const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const gravity = 0.5;
const ballRadius = 15;
const paddleWidth = 100;
const paddleHeight = 10;
const paddleSpeed = 5;
const aiPaddleSpeed = 3;
const ballSpeed = 5;

let ballX = canvas.width / 2;
let ballY = canvas.height / 2;
let ballDX = ballSpeed;
let ballDY = -ballSpeed;
let paddleX = (canvas.width - paddleWidth) / 2;
let aiPaddleX = (canvas.width - paddleWidth) / 2;

function drawBall() {
    ctx.beginPath();
    ctx.arc(ballX, ballY, ballRadius, 0, Math.PI*2);
    ctx.fillStyle = "#0095DD";
    ctx.fill();
    ctx.closePath();
}

function drawPaddle(x, y, width, height, color) {
    ctx.beginPath();
    ctx.rect(x, y, width, height);
    ctx.fillStyle = color;
    ctx.fill();
    ctx.closePath();
}

function updateAI() {
    const aiCenter = aiPaddleX + paddleWidth / 2;
    if (ballX > aiCenter) {
        aiPaddleX += Math.min(aiPaddleSpeed, ballX - aiCenter);
    } else {
        aiPaddleX -= Math.min(aiPaddleSpeed, aiCenter - ballX);
    }
    aiPaddleX = Math.max(0, Math.min(canvas.width - paddleWidth, aiPaddleX));
}

function updatePhysics() {
    ballX += ballDX;
    ballY += ballDY;

    if (ballX + ballDX > canvas.width - ballRadius || ballX + ballDX < ballRadius) {
        ballDX = -ballDX;
    }
    if (ballY + ballDY < ballRadius) {
        ballDY = -ballDY;
    } else if (ballY + ballDY > canvas.height - ballRadius) {
        if (ballX > paddleX && ballX < paddleX + paddleWidth) {
            ballDY = -ballDY;
        } else if (ballX > aiPaddleX && ballX < aiPaddleX + paddleWidth) {
            ballDY = -ballDY;
        } else {
            alert("Game Over");
            document.location.reload();
        }
    }
}

function draw() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBall();
    drawPaddle(paddleX, canvas.height - paddleHeight, paddleWidth, paddleHeight, "#0095DD");
    drawPaddle(aiPaddleX, 0, paddleWidth, paddleHeight, "#FF0000");
}

function movePaddle(event) {
    const relativeX = event.clientX - canvas.offsetLeft;
    if (relativeX > paddleWidth / 2 && relativeX < canvas.width - paddleWidth / 2) {
        paddleX = relativeX - paddleWidth / 2;
    }
}

document.addEventListener('mousemove', movePaddle);

function gameLoop(timestamp) {
    updateAI();
    updatePhysics();
    draw();
    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
