// Tower Defense Game
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
canvas.width = 800;
canvas.height = 600;
const ctx = canvas.getContext('2d');

const TPS = 60; // Ticks Per Second
const FIXED_TIMESTEP = 1000 / TPS;
let lastTime = Date.now();
let accumulator = 0;

class Entity {
  constructor(x, y) {
    this.x = x;
    this.y = y;
  }
}

class Enemy extends Entity {
  constructor(x, y, speed) {
    super(x, y);
    this.speed = speed;
  }

  update(dt) {
    this.x += this.speed * dt;
  }

  draw() {
    ctx.fillStyle = 'red';
    ctx.fillRect(this.x, this.y, 20, 20);
  }
}

class Tower extends Entity {
  constructor(x, y) {
    super(x, y);
    this.range = 100;
    this.damage = 1;
    this.cooldown = 1000; // milliseconds
    this.lastShot = 0;
  }

  update(enemies, dt) {
    if (Date.now() - this.lastShot > this.cooldown) {
      for (let enemy of enemies) {
        if (this.distanceTo(enemy) < this.range) {
          this.shoot(enemy);
          break;
        }
      }
    }
  }

  shoot(enemy) {
    enemy.x -= this.damage;
    this.lastShot = Date.now();
  }

  distanceTo(other) {
    return Math.sqrt((this.x - other.x) ** 2 + (this.y - other.y) ** 2);
  }

  draw() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, 20, 20);
  }
}

class Wave {
  constructor(enemies) {
    this.enemies = enemies;
    this.spawnedEnemies = [];
  }

  update(dt) {
    for (let enemy of this.enemies) {
      if (enemy.spawnTime <= Date.now()) {
        this.spawnedEnemies.push(new Enemy(enemy.x, enemy.y, enemy.speed));
      }
    }
    for (let enemy of this.spawnedEnemies) {
      enemy.update(dt);
    }
  }

  draw() {
    for (let enemy of this.spawnedEnemies) {
      enemy.draw();
    }
  }
}

const waves = [
  new Wave([
    { x: -50, y: 100, speed: 1, spawnTime: Date.now() },
    { x: -50, y: 200, speed: 1, spawnTime: Date.now() + 1000 }
  ]),
  new Wave([
    { x: -50, y: 300, speed: 1.5, spawnTime: Date.now() + 2000 },
    { x: -50, y: 400, speed: 1.5, spawnTime: Date.now() + 3000 }
  ])
];

const towers = [
  new Tower(100, 100),
  new Tower(100, 200)
];

function update(dt) {
  for (let wave of waves) {
    wave.update(dt);
  }
  for (let tower of towers) {
    tower.update(waves.flatMap(wave => wave.spawnedEnemies), dt);
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let wave of waves) {
    wave.draw();
  }
  for (let tower of towers) {
    tower.draw();
  }
}

function mainLoop() {
  const now = Date.now();
  const dt = now - lastTime;
  lastTime = now;
  accumulator += dt;

  while (accumulator >= FIXED_TIMESTEP) {
    update(FIXED_TIMESTEP / 1000);
    accumulator -= FIXED_TIMESTEP;
  }

  draw();
  requestAnimationFrame(mainLoop);
}

mainLoop();
