const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

canvas.width = 400;
canvas.height = 600;

const bird = {
  x: 50,
  y: 150,
  width: 30,
  height: 30,
  velocity: 0,
  jumpStrength: -10,
  gravity: 0.5,
  draw: function() {
    ctx.fillStyle = 'blue';
    ctx.fillRect(this.x, this.y, this.width, this.height);
  },
  update: function() {
    this.velocity += this.gravity;
    this.y += this.velocity;
    if (this.y + this.height > canvas.height) {
      this.y = canvas.height - this.height;
      this.velocity = 0;
    }
  },
  jump: function() {
    this.velocity = this.jumpStrength;
  }
};

const pipes = [];
const pipeWidth = 60;
const pipeGap = 150;
const pipeSpeed = 2;

function createPipe() {
  const height = Math.random() * (canvas.height - pipeGap);
  pipes.push({
    x: canvas.width,
    y: 0,
    width: pipeWidth,
    height: height,
    draw: function() {
      ctx.fillStyle = 'green';
      ctx.fillRect(this.x, this.y, this.width, this.height);
      ctx.fillRect(this.x, this.y + height + pipeGap, this.width, canvas.height);
    },
    update: function() {
      this.x -= pipeSpeed;
    },
    isColliding: function(bird) {
      return (
        bird.x < this.x + this.width &&
        bird.x + bird.width > this.x &&
        bird.y < this.y + this.height &&
        bird.y + bird.height > this.y ||
        bird.x < this.x + this.width &&
        bird.x + bird.width > this.x &&
        bird.y < this.y + this.height + pipeGap &&
        bird.y + bird.height > this.y + this.height + pipeGap
      );
    }
  });
}

let score = 0;
let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore'), 10) : 0;

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  bird.update();
  bird.draw();

  if (Math.random() < 0.02) createPipe();
  pipes.forEach(pipe => {
    pipe.update();
    pipe.draw();
    if (pipe.isColliding(bird)) {
      score = 0;
      pipes.length = 0;
      bird.y = 150;
      bird.velocity = 0;
    }
    if (pipe.x + pipe.width < 0) pipes.shift();
    if (pipe.x < bird.x && !pipe.passed) {
      score++;
      pipe.passed = true;
    }
  });

  drawScore();

  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }
}

function gameLoop(timestamp) {
  const deltaTime = timestamp - lastTime;
  if (deltaTime >= 1000 / 60) {
    lastTime = timestamp;
    update();
  }
  requestAnimationFrame(gameLoop);
}

let lastTime = 0;
requestAnimationFrame(gameLoop);

document.addEventListener('keydown', e => {
  if (e.code === 'Space') bird.jump();
});
