canvas.style.height = `${canvas.height}px`;
canvas.width *= DPR;
canvas.height *= DPR;
ctx.scale(DPR, DPR);

const ROOM_WIDTH = 20;
const ROOM_HEIGHT = 15;
const TILE_SIZE = 32;
const ENEMY_SPAWN_INTERVAL = 1000; // milliseconds
const MAX_ENEMIES = 10;

let enemies = [];
let spawnCount = 0;
let spawnInterval = ENEMY_SPAWN_INTERVAL;

function drawTile(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * TILE_SIZE, y * TILE_SIZE, TILE_SIZE, TILE_SIZE);
}

function drawRoom() {
  for (let y = 0; y < ROOM_HEIGHT; y++) {
    for (let x = 0; x < ROOM_WIDTH; x++) {
      drawTile(x, y, '#000');
    }
  }
}

function spawnEnemy() {
  if (enemies.length < MAX_ENEMIES) {
    enemies.push({
      x: Math.floor(Math.random() * ROOM_WIDTH),
      y: Math.floor(Math.random() * ROOM_HEIGHT),
      color: `hsl(${Math.random() * 360}, 100%, 50%)`
    });
  }
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  drawRoom();

  enemies.forEach(enemy => {
    drawTile(enemy.x, enemy.y, enemy.color);
  });

  spawnCount++;
  if (spawnCount >= spawnInterval / 16) { // 16 updates per second
    spawnEnemy();
    spawnCount = 0;
    spawnInterval = Math.max(ENEMY_SPAWN_INTERVAL - spawnCount * 50, 500); // Ramp up difficulty
  }

  requestAnimationFrame(update);
}

update();

window.addEventListener('resize', () => {
  canvas.width = window.innerWidth;
  canvas.height = window.innerHeight;

  const DPR = window.devicePixelRatio;
  canvas.style.width = `${canvas.width}px`;
  canvas.style.height = `${canvas.height}px`;
  canvas.width *= DPR;
  canvas.height *= DPR;
  ctx.scale(DPR, DPR);

  update();
});
