const canvas = document.createElement('canvas');
canvas.width = window.innerWidth;
canvas.height = window.innerHeight;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let balls = [];
let particles = [];

function Ball(x, y) {
  this.x = x;
  this.y = y;
  this.r = 15;
  this.vx = (Math.random() - 0.5) * 5;
  this.vy = 0;
  this.gravity = 0.5;
  this.bounce = -0.7;
}

Ball.prototype.update = function() {
  this.vy += this.gravity;
  this.x += this.vx;
  this.y += this.vy;

  if (this.y + this.r > canvas.height) {
    this.vy *= this.bounce;
    this.y = canvas.height - this.r;
    this.createParticles();
  }
};

Ball.prototype.draw = function() {
  ctx.beginPath();
  ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);
  ctx.fillStyle = '#0095DD';
  ctx.fill();
  ctx.closePath();
};

Ball.prototype.createParticles = function() {
  for (let i = 0; i < 10; i++) {
    particles.push(new Particle(this.x, this.y, this.vx, this.vy));
  }
};

function Particle(x, y, vx, vy) {
  this.x = x;
  this.y = y;
  this.r = Math.random() * 2 + 1;
  this.vx = (Math.random() - 0.5) * 3 + vx * 0.5;
  this.vy = (Math.random() - 0.5) * 3 + vy * 0.5;
  this.life = 100;
}

Particle.prototype.update = function() {
  this.vx *= 0.98;
  this.vy *= 0.98;
  this.x += this.vx;
  this.y += this.vy;
  this.life--;
};

Particle.prototype.draw = function() {
  ctx.beginPath();
  ctx.arc(this.x, this.y, this.r, 0, Math.PI * 2);
  ctx.fillStyle = `rgba(0, 149, 221, ${this.life / 100})`;
  ctx.fill();
  ctx.closePath();
};

function addBall() {
  balls.push(new Ball(canvas.width / 2, 50));
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  balls.forEach(ball => {
    ball.update();
    ball.draw();
  });

  particles = particles.filter(particle => particle.life > 0);
  particles.forEach(particle => {
    particle.update();
    particle.draw();
  });

  requestAnimationFrame(update);
}

update();

document.addEventListener('keydown', event => {
  if (event.key === ' ') {
    addBall();
  }
});
