let elapsedTime = 0;
let pausedTime = 0;
let gameOver = false;

function getRandomText() {
  const words = ['hello', 'world', 'javascript', 'finite', 'state', 'machine', 'typing', 'speed'];
  return words[Math.floor(Math.random() * words.length)];
}

function updateMenu(dt) {
  if (inputText.length > 0) {
    startGame();
  }
}

function updatePlaying(dt) {
  if (inputText === targetText) {
    gameOver = true;
    elapsedTime = Date.now() - startTime;
  }
  if (gameOver) {
    currentState = states.gameover;
  }
}

function updatePaused(dt) {
  pausedTime += dt;
}

function updateGameover(dt) {
  // Stay in gameover state
}

const updateFunctions = {
  [states.menu]: updateMenu,
  [states.playing]: updatePlaying,
  [states.paused]: updatePaused,
  [states.gameover]: updateGameover
};

function renderMenu() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '48px Arial';
  ctx.fillText('Type the word:', 50, 100);
  ctx.fillText(targetText, 50, 200);
  ctx.fillText('Start typing to begin...', 50, 300);
}

function renderPlaying() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '48px Arial';
  ctx.fillText('Type the word:', 50, 100);
  ctx.fillText(targetText, 50, 200);
  ctx.fillText(inputText, 50, 300);
  if (gameOver) {
    ctx.fillText('Game Over!', 50, 400);
    ctx.fillText(`Time: ${elapsedTime / 1000} seconds`, 50, 500);
  }
}

function renderPaused() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '48px Arial';
  ctx.fillText('Paused', 50, 100);
}

function renderGameover() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '48px Arial';
  ctx.fillText('Game Over!', 50, 100);
  ctx.fillText(`Time: ${elapsedTime / 1000} seconds`, 50, 200);
}

const renderFunctions = {
  [states.menu]: renderMenu,
  [states.playing]: renderPlaying,
  [states.paused]: renderPaused,
  [states.gameover]: renderGameover
};

function startGame() {
  currentState = states.playing;
  targetText = getRandomText();
  inputText = '';
  startTime = Date.now();
  elapsedTime = 0;
  gameOver = false;
}

function handleKeyPress(event) {
  if (currentState === states.playing && !gameOver) {
    if (event.key === 'Backspace') {
      inputText = inputText.slice(0, -1);
    } else if (event.key.length === 1) {
      inputText += event.key;
    }
  } else if (currentState === states.paused) {
    if (event.key === 'p') {
      currentState = states.playing;
    }
  } else if (currentState === states.gameover) {
    if (event.key === 'r') {
      currentState = states.menu;
      inputText = '';
    }
  }
}

canvas.addEventListener('keydown', handleKeyPress);

function gameLoop(timestamp) {
  const dt = timestamp - lastTime;
  lastTime = timestamp;
  accumulator += dt;

  while (accumulator >= fixedTimeStep) {
    updateFunctions[currentState](fixedTimeStep);
    accumulator -= fixedTimeStep;
  }

  renderFunctions[currentState]();
  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
