// Maze Chase Game with Combo Multiplier
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const player = {
  x: 100,
  y: 100,
  width: 20,
  height: 20,
  speed: 200,
  direction: { x: 0, y: 0 }
};

const enemies = [
  { x: 300, y: 300, width: 20, height: 20, speed: 150 },
  { x: 500, y: 500, width: 20, height: 20, speed: 150 }
];

const walls = [
  { x: 0, y: 0, width: canvas.width, height: 20 },
  { x: 0, y: 0, width: 20, height: canvas.height },
  { x: 0, y: canvas.height - 20, width: canvas.width, height: 20 },
  { x: canvas.width - 20, y: 0, width: 20, height: canvas.height }
];

let lastTime = performance.now();
let combo = 0;
const maxCombo = 10;
let comboMultiplier = 1;
const fixedTimeStep = 1 / 60;

function update(deltaTime) {
  const move = (entity, direction) => {
    entity.x += entity.speed * direction.x * deltaTime;
    entity.y += entity.speed * direction.y * deltaTime;
  };

  if (player.direction.x !== 0 || player.direction.y !== 0) {
    combo++;
    if (combo > maxCombo) combo = maxCombo;
    comboMultiplier = 1 + (combo / maxCombo);
  } else {
    combo = 0;
    comboMultiplier = 1;
  }

  move(player, player.direction);

  for (let enemy of enemies) {
    enemy.direction.x = (player.x - enemy.x) / Math.sqrt((player.x - enemy.x) ** 2 + (player.y - enemy.y) ** 2);
    enemy.direction.y = (player.y - enemy.y) / Math.sqrt((player.x - enemy.x) ** 2 + (player.y - enemy.y) ** 2);
    move(enemy, enemy.direction);
  }

  // Collision detection
  const checkCollision = (entity1, entity2) => {
    return (entity1.x < entity2.x + entity2.width &&
            entity1.x + entity1.width > entity2.x &&
            entity1.y < entity2.y + entity2.height &&
            entity1.y + entity1.height > entity2.y);
  };

  for (let wall of walls) {
    if (checkCollision(player, wall)) {
      player.x -= player.direction.x * player.speed * deltaTime;
      player.y -= player.direction.y * player.speed * deltaTime;
    }
  }

  for (let enemy of enemies) {
    if (checkCollision(player, enemy)) {
      alert('Game Over! Score: ' + (combo * comboMultiplier).toFixed(2));
      document.location.reload();
    }
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);
  ctx.fillStyle = 'red';
  enemies.forEach(enemy => ctx.fillRect(enemy.x, enemy.y, enemy.width, enemy.height));
  ctx.fillStyle = 'black';
  walls.forEach(wall => ctx.fillRect(wall.x, wall.y, wall.width, wall.height));
  ctx.fillStyle = 'green';
  ctx.font = '20px Arial';
  ctx.fillText('Combo: ' + combo + 'x', 10, 30);
  ctx.fillText('Multiplier: ' + comboMultiplier.toFixed(2), 10, 60);
}

function gameLoop(time) {
  const deltaTime = time - lastTime;
  lastTime = time;
  update(deltaTime * fixedTimeStep);
  render();
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', event => {
  switch (event.key) {
    case 'ArrowUp': player.direction.y = -1; break;
    case 'ArrowDown': player.direction.y = 1; break;
    case 'ArrowLeft': player.direction.x = -1; break;
    case 'ArrowRight': player.direction.x = 1; break;
  }
});

document.addEventListener('keyup', event => {
  switch (event.key) {
    case 'ArrowUp': player.direction.y = 0; break;
    case 'ArrowDown': player.direction.y = 0; break;
    case 'ArrowLeft': player.direction.x = 0; break;
    case 'ArrowRight': player.direction.x = 0; break;
  }
});

requestAnimationFrame(gameLoop);
