const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const TILE_SIZE = 32;
const ROOM_WIDTH = 20;
const ROOM_HEIGHT = 15;

let player = {
  x: TILE_SIZE,
  y: TILE_SIZE,
  width: TILE_SIZE,
  height: TILE_SIZE,
  speed: 5
};

let tiles = [];
let score = 0;
let gameOver = false;

function createRoom() {
  for (let y = 0; y < ROOM_HEIGHT; y++) {
    for (let x = 0; x < ROOM_WIDTH; x++) {
      let tile = {
        x: x * TILE_SIZE,
        y: y * TILE_SIZE,
        width: TILE_SIZE,
        height: TILE_SIZE,
        type: Math.random() < 0.1 ? 'enemy' : 'floor'
      };
      tiles.push(tile);
    }
  }
}

function drawTile(tile) {
  ctx.fillStyle = tile.type === 'enemy' ? 'red' : 'gray';
  ctx.fillRect(tile.x, tile.y, tile.width, tile.height);
}

function drawPlayer() {
  ctx.fillStyle = 'green';
  ctx.fillRect(player.x, player.y, player.width, player.height);
}

function drawScore() {
  ctx.fillStyle = 'black';
  ctx.font = '20px Arial';
  ctx.fillText('Score: ' + score, 10, 30);
}

function checkCollision(rect1, rect2) {
  return (
    rect1.x < rect2.x + rect2.width &&
    rect1.x + rect1.width > rect2.x &&
    rect1.y < rect2.y + rect2.height &&
    rect1.y + rect1.height > rect2.y
  );
}

function update() {
  if (gameOver) return;

  // Move player
  if (keys.right) player.x += player.speed;
  if (keys.left) player.x -= player.speed;
  if (keys.down) player.y += player.speed;
  if (keys.up) player.y -= player.speed;

  // Collision detection with walls
  player.x = Math.max(0, Math.min(canvas.width - player.width, player.x));
  player.y = Math.max(0, Math.min(canvas.height - player.height, player.y));

  // Collision detection with enemies
  tiles.forEach(tile => {
    if (tile.type === 'enemy' && checkCollision(player, tile)) {
      gameOver = true;
    }
  });

  // Collecting enemies (for scoring)
  tiles = tiles.filter(tile => {
    if (tile.type === 'enemy' && checkCollision(player, tile)) {
      score++;
      return false;
    }
    return true;
  });
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  tiles.forEach(drawTile);
  drawPlayer();
  drawScore();
}

function gameLoop() {
  update();
  draw();
  if (!gameOver) requestAnimationFrame(gameLoop);
}

const keys = {
  right: false,
  left: false,
  up: false,
  down: false
};

document.addEventListener('keydown', e => {
  switch (e.key) {
    case 'ArrowRight':
      keys.right = true;
      break;
    case 'ArrowLeft':
      keys.left = true;
      break;
    case 'ArrowUp':
      keys.up = true;
      break;
    case 'ArrowDown':
      keys.down = true;
      break;
  }
});

document.addEventListener('keyup', e => {
  switch (e.key) {
    case 'ArrowRight':
      keys.right = false;
      break;
    case 'ArrowLeft':
      keys.left = false;
      break;
    case 'ArrowUp':
      keys.up = false;
      break;
    case 'ArrowDown':
      keys.down = false;
      break;
  }
});

createRoom();
gameLoop();
