const ctx = canvas.getContext('2d');

const FPS = 60;
const TPS = 30;
const TPS_INTERVAL = 1000 / TPS;

let lastRenderTime = 0;
let lastUpdateTime = 0;

const states = {
  menu: {
    update: () => {},
    render: () => {
      ctx.fillStyle = 'black';
      ctx.fillRect(0, 0, canvas.width, canvas.height);
      ctx.fillStyle = 'white';
