const canvas = document.createElement('canvas');
canvas.width = 400;
canvas.height = 400;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const SIZE = 4;
const TILE_SIZE = 100;
const GAP = 10;
const FONT_SIZE = 50;

let board = Array.from({ length: SIZE }, () => Array(SIZE).fill(0));
let score = 0;
let gameOver = false;

function getRandomInt(max) {
  return Math.floor(Math.random() * max);
}

function spawnTile() {
  let emptyCells = [];
  for (let i = 0; i < SIZE; i++) {
    for (let j = 0; j < SIZE; j++) {
      if (board[i][j] === 0) {
        emptyCells.push({ i, j });
      }
    }
  }
  if (emptyCells.length > 0) {
    const { i, j } = emptyCells[getRandomInt(emptyCells.length)];
    board[i][j] = getRandomInt(10) === 0 ? 4 : 2;
  }
}

function drawBoard() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let i = 0; i < SIZE; i++) {
    for (let j = 0; j < SIZE; j++) {
      ctx.fillStyle = '#cdc1b4';
      ctx.fillRect(j * (TILE_SIZE + GAP), i * (TILE_SIZE + GAP), TILE_SIZE, TILE_SIZE);
      if (board[i][j] !== 0) {
        ctx.fillStyle = getTileColor(board[i][j]);
        ctx.fillRect(j * (TILE_SIZE + GAP) + 5, i * (TILE_SIZE + GAP) + 5, TILE_SIZE - 10, TILE_SIZE - 10);
        ctx.fillStyle = '#ffffff';
        ctx.font = `${FONT_SIZE}px Arial`;
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';
        ctx.fillText(board[i][j], j * (TILE_SIZE + GAP) + TILE_SIZE / 2, i * (TILE_SIZE + GAP) + TILE_SIZE / 2);
      }
    }
  }
  ctx.fillStyle = '#ffffff';
  ctx.font = '30px Arial';
  ctx.fillText(`Score: ${score}`, 200, 40);
}

function getTileColor(value) {
  switch (value) {
    case 2: return '#eee4da';
    case 4: return '#ede0c8';
    case 8: return '#f2b179';
    case 16: return '#f59563';
    case 32: return '#f67c5f';
    case 64: return '#f65e3b';
    case 128: return '#edcf72';
    case 256: return '#edcc61';
    case 512: return '#edc850';
    case 1024: return '#edc53f';
    case 2048: return '#edc22e';
    default: return '#3c3a32';
  }
}

function move(direction) {
  let moved = false;
  switch (direction) {
    case 'up':
      for (let j = 0; j < SIZE; j++) {
        let row = [];
        for (let i = 0; i < SIZE; i++) {
          if (board[i][j] !== 0) {
            row.push(board[i][j]);
            board[i][j] = 0;
          }
        }
        row = merge(row);
        for (let i = 0; i < row.length; i++) {
          board[i][j] = row[i];
        }
      }
      break;
    case 'down':
      for (let j = 0; j < SIZE; j++) {
        let row = [];
        for (let i = SIZE - 1; i >= 0; i--) {
          if (board[i][j] !== 0) {
            row.push(board[i][j]);
            board[i][j] = 0;
          }
        }
        row = merge(row);
        for (let i = SIZE - 1; i >= SIZE - row.length; i--) {
          board[i][j] = row[SIZE - 1 - i];
        }
      }
      break;
    case 'left':
      for (let i = 0; i < SIZE; i++) {
        let row = [];
        for (let j = 0; j < SIZE; j++) {
          if (board[i][j] !== 0) {
            row.push(board[i][j]);
            board[i][j] = 0;
          }
        }
        row = merge(row);
        for (let j = 0; j < row.length; j++) {
          board[i][j] = row[j];
        }
      }
      break;
    case 'right':
      for (let i = 0; i < SIZE; i++) {
        let row = [];
        for (let j = SIZE - 1; j >= 0; j--) {
          if (board[i][j] !== 0) {
            row.push(board[i][j]);
            board[i][j] = 0;
          }
        }
        row = merge(row);
        for (let j = SIZE - 1; j >= SIZE - row.length; j--) {
          board[i][j] = row[SIZE - 1 - j];
        }
      }
      break;
  }
  return moved;
}

function merge(row) {
  for (let i = 0; i < row.length - 1; i++) {
    if (row[i] === row[i + 1]) {
      row[i] *= 2;
      score += row[i];
      row.splice(i + 1, 1);
    }
  }
  return row;
}

function checkGameOver() {
  for (let i = 0; i < SIZE; i++) {
    for (let j = 0; j < SIZE; j++) {
      if (board[i][j] === 0) return false;
      if (i < SIZE - 1 && board[i][j] === board[i + 1][j]) return false;
      if (j < SIZE - 1 && board[i][j] === board[i][j + 1]) return false;
    }
  }
  return true;
}

function gameLoop() {
  if (gameOver) {
    ctx.fillStyle = 'rgba(0, 0, 0, 0.7)';
    ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = '#ffffff';
    ctx.font = '50px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2);
    return;
  }
  drawBoard();
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
  if (gameOver) return;
  let moved = false;
  switch (e.key) {
    case 'ArrowUp':
      moved = move('up');
      break;
    case 'ArrowDown':
      moved = move('down');
      break;
    case 'ArrowLeft':
      moved = move('left');
      break;
    case 'ArrowRight':
      moved = move('right');
      break;
  }
  if (moved) {
    spawnTile();
    gameOver = checkGameOver();
  }
});

spawnTile();
spawnTile();
gameLoop();
