const powerUp = new PowerUp(canvas.width / 4, canvas.height / 4);

let score = 0;
let powerUpActive = false;
let powerUpTimer = 0;

function handleInput(event) {
  if (event.key === ' ') {
    if (powerUpActive) {
      score += 10;
      fish.size += 5;
    } else if (Math.abs(fish.x - powerUp.x) < fish.size + powerUp.size && Math.abs(fish.y - powerUp.y) < fish.size + powerUp.size) {
      powerUp.collect();
      powerUpActive = true;
      powerUpTimer = 100;
    }
  }
}

function update() {
  fish.update();
  if (powerUpActive) {
    powerUpTimer--;
    if (powerUpTimer <= 0) {
      powerUpActive = false;
      fish.size = 20;
    }
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  fish.draw();
  powerUp.draw();
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 20);
  if (powerUpActive) {
    ctx.fillText('Power-Up Active!', 10, 40);
  }
}

function gameLoop() {
  update();
  draw();
  requestAnimationFrame(gameLoop);
}

