  ctx.fillText(`Final Score: ${score}`, canvas.width / 2 - 75, canvas.height / 2 + 40);
  ctx.fillText('Press SPACE to restart', canvas.width / 2 - 150, canvas.height / 2 + 80);
}

function updateMenu(dt) {
  if (keys.Space) {
    currentState = states.playing;
    keys.Space = false;
  }
}

function updatePlaying(dt) {
  if (keys.Space) {
    ball.vy = -10;
    keys.Space = false;
  }
  ball.vy += gravity;
  ball.y += ball.vy;
  if (ball.y + ball.radius > canvas.height) {
    ball.y = canvas.height - ball.radius;
    ball.vy = 0;
    score++;
  }
  if (keys.Escape) {
    currentState = states.paused;
    keys.Escape = false;
  }
}

function updatePaused(dt) {
  if (keys.Space) {
    currentState = states.playing;
    keys.Space = false;
  }
}

function updateGameOver(dt) {
  if (keys.Space) {
    currentState = states.menu;
    ball.y = 50;
    score = 0;
    keys.Space = false;
  }
}

function fixedUpdate(dt) {
  switch (currentState) {
    case states.menu:
      updateMenu(dt);
      break;
    case states.playing:
      updatePlaying(dt);
      break;
    case states.paused:
      updatePaused(dt);
      break;
    case states.gameover:
      updateGameOver(dt);
      break;
  }
}

function render() {
  switch (currentState) {
    case states.menu:
      drawMenu();
      break;
    case states.playing:
      drawPlaying();
      break;
    case states.paused:
      drawPaused();
      break;
    case states.gameover:
      drawGameOver();
      break;
  }
}

const keys = {};
document.addEventListener('keydown', (e) => { keys[e.key] = true; });
document.addEventListener('keyup', (e) => { keys[e.key] = false; });

function gameLoop(timestamp) {
  const dt = timestamp - lastTime;
  lastTime = timestamp;
  accumulator += dt;

  while (accumulator >= fixedTimeStep) {
    fixedUpdate(fixedTimeStep);
    accumulator -= fixedTimeStep;
  }

  render();
  requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
