```js
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const cardWidth = 100;
const cardHeight = 150;
const spacing = 20;
const cols = 4;
const rows = 3;
const totalCards = cols * rows;
const cardPairs = totalCards / 2;
const cards = [];
let flippedCards = [];
let state = 'menu';

class Card {
  constructor(x, y, value) {
    this.x = x;
    this.y = y;
    this.value = value;
    this.flipped = false;
    this.matched = false;
  }

  draw() {
    ctx.strokeStyle = 'black';
    ctx.lineWidth = 2;
    ctx.strokeRect(this.x, this.y, cardWidth, cardHeight);
    if (this.flipped && !this.matched) {
      ctx.fillStyle = 'lightblue';
      ctx.fillRect(this.x + 2, this.y + 2, cardWidth - 4, cardHeight - 4);
      ctx.font = '24px Arial';
      ctx.fillStyle = 'black';
      ctx.textAlign = 'center';
      ctx.textBaseline = 'middle';
      ctx.fillText(this.value, this.x + cardWidth / 2, this.y + cardHeight / 2);
    }
  }

  flip() {
    this.flipped = !this.flipped;
  }

  match(other) {
    return this.value === other.value;
  }
}

function createCards() {
  const values = [];
  for (let i = 0; i < cardPairs; i++) {
    values.push(i, i);
  }
  for (let i = 0; i < totalCards; i++) {
    const x = (i % cols) * (cardWidth + spacing);
    const y = Math.floor(i / cols) * (cardHeight + spacing);
    const value = values[i];
    cards.push(new Card(x, y, value));
  }
  shuffle(cards);
}

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}

function drawMenu() {
  ctx.fillStyle = 'black';
  ctx.font = '32px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Memory Game', canvas.width / 2, canvas.height / 2 - 50);
  ctx.font = '24px Arial';
  ctx.fillText('Click to Start', canvas.width / 2, canvas.height / 2 + 50);
}

function drawPlaying() {
  cards.forEach(card => card.draw());
}

function drawPaused() {
  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '32px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Paused', canvas.width / 2, canvas.height / 2);
}

function drawGameOver() {
  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '32px Arial';
  ctx.textAlign = 'center';
  ctx.textBaseline = 'middle';
  ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 50);
  ctx.font = '24px Arial';
  ctx.fillText('Click to Restart', canvas.width / 2, canvas.height / 2 + 50);
}

function update() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  switch (state) {
    case 'menu':
      drawMenu();
      break;
    case 'playing':
      drawPlaying();
      break;
    case 'paused':
      drawPlaying();
      drawPaused();
      break;
    case 'gameover':
      drawPlaying();
      drawGameOver();
      break;
  }
  requestAnimationFrame(update);
}

canvas.addEventListener('click', (event) => {
  const { offsetX, offsetY } = event;
  switch (state) {
    case 'menu':
      state = 'playing';
      createCards();
      break;
    case 'playing':
      const clickedCard = cards.find(card => 
        offsetX > card.x && offsetX < card.x + cardWidth &&
        offsetY > card.y && offsetY < card.y + cardHeight
      );
      if (clickedCard && !clickedCard.flipped && !clickedCard.matched) {
        clickedCard.flip();
        flippedCards.push(clickedCard);
        if (flippedCards.length === 2) {
          setTimeout(() => {
            const [card1, card2] = flippedCards;
            if (card1.match(card2)) {
              card1.matched = card2.matched = true;
            } else {
              card1.flip();
              card2.flip();
            }
            flippedCards = [];
            if (cards.every(card => card.matched)) {
              state = 'gameover';
            }
          }, 500);
        }
      }
      break;
    case 'paused':
      state = 'playing';
      break;
    case 'gameover':
      state = 'menu';
      cards.length = 0;
      break;
  }
});

canvas.addEventListener('keydown', (event) => {
  if (event.key === 'p' && (state === 'playing' || state === 'paused')) {
    state = state === 'playing' ? 'paused' : 'playing';
  }
});

update();
