            const cardX = j * (cardWidth + gap);
            const cardY = i * (cardHeight + gap);
            if (x > cardX && x < cardX + cardWidth && y > cardY && y < cardY + cardHeight) {
                const index = i * cols + j;
                if (!flippedCards.some(card => card.index === index)) {
                    flippedCards.push({ index, img: cardImages[index] });
                    break;
                }
            }
        }
    }
    if (flippedCards.length === 2) {
        isFlipping = true;
        lastFlipTime = Date.now();
    }
});

function gameLoop(timestamp) {
    const now = Date.now();
    const deltaTime = now - lastFlipTime;
    if (deltaTime >= 1000 && isFlipping) {
        checkForMatch();
    }
    drawBoard();
    requestAnimationFrame(gameLoop);
}

requestAnimationFrame(gameLoop);
