    if (keys['ArrowRight']) player.x += playerSpeed;
    if (keys['ArrowUp'] && !player.jumping) {
        player.velocityY = jumpSpeed;
        player.jumping = true;
    }

    // Apply gravity
    player.velocityY += gravity;
    player.y += player.velocityY;

