const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');
canvas.width = 800;
canvas.height = 600;

const mazeWidth = 10;
const mazeHeight = 10;
const cellSize = 50;

const maze = Array.from({ length: mazeHeight }, () =>
  Array(mazeWidth).fill(0)
);

function generateMaze() {
  for (let y = 0; y < mazeHeight; y++) {
    for (let x = 0; x < mazeWidth; x++) {
      maze[y][x] = Math.random() > 0.5 ? 1 : 0;
    }
  }
  maze[0][0] = 0; // Start point
  maze[mazeHeight - 1][mazeWidth - 1] = 0; // End point
}

const player = {
  x: 0,
  y: 0,
  size: cellSize * 0.8
};

const states = {
  MENU: 'menu',
  PLAYING: 'playing',
  PAUSED: 'paused',
  GAMEOVER: 'gameover'
};

let currentState = states.MENU;

function drawMaze() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (let y = 0; y < mazeHeight; y++) {
    for (let x = 0; x < mazeWidth; x++) {
      if (maze[y][x]) {
        ctx.fillStyle = 'black';
      } else {
        ctx.fillStyle = 'white';
      }
      ctx.fillRect(x * cellSize, y * cellSize, cellSize, cellSize);
    }
  }
}

function drawPlayer() {
  ctx.fillStyle = 'blue';
  ctx.fillRect(
    player.x * cellSize + (cellSize - player.size) / 2,
    player.y * cellSize + (cellSize - player.size) / 2,
    player.size,
    player.size
  );
}

function drawMenu() {
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.fillText('Press Space to Start', canvas.width / 2 - 100, canvas.height / 2);
}

function drawPaused() {
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.fillText('Paused', canvas.width / 2 - 50, canvas.height / 2);
}

function drawGameOver() {
  ctx.fillStyle = 'black';
  ctx.font = '24px Arial';
  ctx.fillText('Game Over', canvas.width / 2 - 50, canvas.height / 2);
  ctx.fillText('Press Space to Restart', canvas.width / 2 - 100, canvas.height / 2 + 30);
}

function update() {
  switch (currentState) {
    case states.PLAYING:
      if (player.x === mazeWidth - 1 && player.y === mazeHeight - 1) {
        currentState = states.GAMEOVER;
      }
      break;
  }
}

function handleInput(event) {
  switch (currentState) {
    case states.MENU:
      if (event.code === 'Space') {
        generateMaze();
        currentState = states.PLAYING;
      }
      break;
    case states.PLAYING:
      if (event.code === 'Space') {
        currentState = states.PAUSED;
      }
      break;
    case states.PAUSED:
      if (event.code === 'Space') {
        currentState = states.PLAYING;
      }
      break;
    case states.GAMEOVER:
      if (event.code === 'Space') {
        currentState = states.MENU;
      }
      break;
  }
}

function movePlayer(event) {
  switch (event.code) {
    case 'ArrowUp':
      if (player.y > 0 && maze[player.y - 1][player.x] === 0) {
        player.y--;
      }
      break;
    case 'ArrowDown':
      if (player.y < mazeHeight - 1 && maze[player.y + 1][player.x] === 0) {
        player.y++;
      }
      break;
    case 'ArrowLeft':
      if (player.x > 0 && maze[player.y][player.x - 1] === 0) {
        player.x--;
      }
      break;
    case 'ArrowRight':
      if (player.x < mazeWidth - 1 && maze[player.y][player.x + 1] === 0) {
        player.x++;
      }
      break;
  }
}

function gameLoop() {
  update();
  drawMaze();
  drawPlayer();
  switch (currentState) {
    case states.MENU:
      drawMenu();
      break;
    case states.PAUSED:
      drawPaused();
      break;
    case states.GAMEOVER:
      drawGameOver();
      break;
  }
  requestAnimationFrame(gameLoop);
}

window.addEventListener('keydown', handleInput);
window.addEventListener('keydown', movePlayer);

gameLoop();
