  'https://via.placeholder.com/100x100?text=6',
  'https://via.placeholder.com/100x100?text=7',
  'https://via.placeholder.com/100x100?text=8'
];

function setCanvasSize() {
  const dpr = window.devicePixelRatio || 1;
  const rect = canvas.getBoundingClientRect();
  canvas.width = rect.width * dpr;
  canvas.height = rect.height * dpr;
  ctx.scale(dpr, dpr);
}

function loadHighScore() {
  const savedScore = localStorage.getItem('highScore');
  if (savedScore) {
    highScore = parseInt(savedScore, 10);
  }
}

function saveHighScore() {
  if (score > highScore) {
    highScore = score;
    localStorage.setItem('highScore', highScore);
  }
}

function createCards() {
  const allImages = cardImages.concat(cardImages);
  allImages.sort(() => Math.random() - 0.5);
  for (let i = 0; i < allImages.length; i++) {
    cards.push({
      x: (i % 8) * 110,
      y: Math.floor(i / 8) * 110,
      image: allImages[i],
      flipped: false
    });
  }
}

function drawCard(card) {
  ctx.fillStyle = card.flipped ? 'white' : 'gray';
  ctx.fillRect(card.x, card.y, 100, 100);
  if (card.flipped) {
    ctx.drawImage(new Image(), card.x, card.y, 100, 100);
  }
}

function draw() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  cards.forEach(drawCard);
  ctx.font = '24px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 10, 20);
  ctx.fillText(`High Score: ${highScore}`, 10, 50);
}

function checkForMatch() {
  if (flippedCards.length === 2) {
    if (flippedCards[0].image === flippedCards[1].image) {
      score += 10;
    } else {
      flippedCards.forEach(card => card.flipped = false);
    }
    flippedCards.length = 0;
    saveHighScore();
  }
}

function flipCard(x, y) {
  const card = cards.find(c => x > c.x && x < c.x + 100 && y > c.y && y < c.y + 100);
  if (card && !card.flipped && flippedCards.length < 2) {
    card.flipped = true;
    flippedCards.push(card);
    checkForMatch();
  }
}

function handleResize() {
  setCanvasSize();
  draw();
}

function handleClick(event) {
  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;
  flipCard(x, y);
  draw();
}

window.addEventListener('resize', handleResize);
canvas.addEventListener('click', handleClick);

setCanvasSize();
loadHighScore();
createCards();
draw();
