};

const bullets = [];
const asteroids = [];
const maxAsteroids = 10;

const asteroidSpeed = 1;
const bulletSpeed = 5;

function createAsteroid() {
    const size = Math.random() * 40 + 20;
    const x = Math.random() * canvas.width;
    const y = Math.random() * canvas.height;
    const angle = Math.random() * Math.PI * 2;
    asteroids.push({ x, y, size, angle, speed: asteroidSpeed });
}

function spawnAsteroids() {
    if (asteroids.length < maxAsteroids) {
        createAsteroid();
    }
}

function updatePlayer() {
    if (keys.ArrowLeft) player.angle -= 0.05;
    if (keys.ArrowRight) player.angle += 0.05;
    if (keys.ArrowUp) {
        player.x += Math.cos(player.angle) * player.speed;
        player.y += Math.sin(player.angle) * player.speed;
    }

    if (keys.Space) {
        bullets.push({
            x: player.x + Math.cos(player.angle) * player.radius,
            y: player.y + Math.sin(player.angle) * player.radius,
            angle: player.angle,
            speed: bulletSpeed
        });
    }
}

function updateBullets() {
    bullets.forEach(bullet => {
        bullet.x += Math.cos(bullet.angle) * bullet.speed;
        bullet.y += Math.sin(bullet.angle) * bullet.speed;
    });
}

function updateAsteroids() {
    asteroids.forEach(asteroid => {
        asteroid.x += Math.cos(asteroid.angle) * asteroid.speed;
        asteroid.y += Math.sin(asteroid.angle) * asteroid.speed;
    });
}

function detectCollisions() {
    asteroids.forEach((asteroid, i) => {
        bullets.forEach((bullet, j) => {
            const distX = asteroid.x - bullet.x;
            const distY = asteroid.y - bullet.y;
            const distance = Math.sqrt(distX * distX + distY * distY);
            if (distance < asteroid.size / 2) {
                asteroids.splice(i, 1);
                bullets.splice(j, 1);
                createAsteroid();
                return;
            }
        });
        const distX = asteroid.x - player.x;
        const distY = asteroid.y - player.y;
        const distance = Math.sqrt(distX * distX + distY * distY);
        if (distance < asteroid.size / 2) {
            player.health -= 10;
            if (player.health <= 0) {
                resetGame();
            }
        }
    });
}

function resetGame() {
    player.health = 100;
    player.x = canvas.width / 2;
    player.y = canvas.height / 2;
    bullets.length = 0;
    asteroids.length = 0;
    spawnAsteroids();
}

function drawPlayer() {
    ctx.save();
    ctx.translate(player.x, player.y);
    ctx.rotate(player.angle);
    ctx.beginPath();
    ctx.arc(0, 0, player.radius, 0, Math.PI * 2);
    ctx.fillStyle = 'blue';
    ctx.fill();
    ctx.restore();
}

function drawBullets() {
