```js
const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const cardWidth = 100;
const cardHeight = 150;
const cardPadding = 10;
const numColumns = Math.floor(canvas.width / (cardWidth + cardPadding));
const numRows = Math.floor(canvas.height / (cardHeight + cardPadding));
const totalCards = numColumns * numRows;

const cards = [];
const revealedCards = [];
const particles = [];

let gameStarted = false;
let flipTime = 1000;
let flipTimer = 0;
let currentFlips = [];

function Particle(x, y, vx, vy, color) {
  this.x = x;
  this.y = y;
  this.vx = vx;
  this.vy = vy;
  this.color = color;
  this.size = Math.random() * 3 + 1;
  this.life = 100;
}

Particle.prototype.update = function() {
  this.x += this.vx;
  this.y += this.vy;
  this.vy += 0.1;
  this.life--;
};

Particle.prototype.draw = function() {
  ctx.fillStyle = this.color;
  ctx.fillRect(this.x, this.y, this.size, this.size);
};

function createParticles(x, y, color) {
  for (let i = 0; i < 50; i++) {
    particles.push(new Particle(x, y, (Math.random() - 0.5) * 4, (Math.random() - 0.5) * 4, color));
  }
}

function initCards() {
  const cardValues = [];
  for (let i = 0; i < totalCards / 2; i++) {
    cardValues.push(i + 1, i + 1);
  }
  shuffle(cardValues);
  for (let i = 0; i < numRows; i++) {
    for (let j = 0; j < numColumns; j++) {
      const value = cardValues.shift();
      cards.push({
        x: j * (cardWidth + cardPadding),
        y: i * (cardHeight + cardPadding),
        value,
        revealed: false,
        matched: false
      });
    }
  }
}

function shuffle(array) {
  for (let i = array.length - 1; i > 0; i--) {
    const j = Math.floor(Math.random() * (i + 1));
    [array[i], array[j]] = [array[j], array[i]];
  }
}

function drawCard(card) {
  ctx.fillStyle = '#fff';
  ctx.strokeStyle = '#000';
  ctx.fillRect(card.x, card.y, cardWidth, cardHeight);
  ctx.strokeRect(card.x, card.y, cardWidth, cardHeight);
  if (card.revealed) {
    ctx.fillStyle = '#000';
    ctx.font = '20px Arial';
    ctx.textAlign = 'center';
    ctx.textBaseline = 'middle';
    ctx.fillText(card.value, card.x + cardWidth / 2, card.y + cardHeight / 2);
  }
}

function drawParticles() {
  for (let i = particles.length - 1; i >= 0; i--) {
    const particle = particles[i];
    if (particle.life <= 0) {
      particles.splice(i, 1);
    } else {
      particle.update();
      particle.draw();
    }
  }
}

function checkForMatch() {
  if (currentFlips.length === 2) {
    const [card1, card2] = currentFlips;
    if (card1.value === card2.value) {
      card1.matched = true;
      card2.matched = true;
      createParticles(card1.x + cardWidth / 2, card1.y + cardHeight / 2, '#0f0');
      createParticles(card2.x + cardWidth / 2, card2.y + cardHeight / 2, '#0f0');
    } else {
      flipTimer = flipTime;
    }
    currentFlips.length = 0;
  }
}

function update() {
  if (flipTimer > 0) {
    flipTimer -= 16;
  } else {
    for (const card of currentFlips) {
      card.revealed = false;
    }
    currentFlips.length = 0;
  }

  for (const card of cards) {
    if (card.revealed && !card.matched) {
      drawCard(card);
    }
  }

  drawParticles();
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  for (const card of cards) {
    drawCard(card);
  }
  drawParticles();
}

function handleClick(event) {
  if (flipTimer > 0) return;
  if (currentFlips.length >= 2) return;

  const rect = canvas.getBoundingClientRect();
  const x = event.clientX - rect.left;
  const y = event.clientY - rect.top;

  for (const card of cards) {
    if (x > card.x && x < card.x + cardWidth && y > card.y && y < card.y + cardHeight) {
      if (!card.revealed && !card.matched) {
        card.revealed = true;
        currentFlips.push(card);
        createParticles(card.x + cardWidth / 2, card.y + cardHeight / 2, '#f00');
        break;
      }
    }
  }
  checkForMatch();
}

canvas.addEventListener('click', handleClick);

function gameLoop(timestamp) {
  update();
  render();
  requestAnimationFrame(gameLoop);
}

initCards();
requestAnimationFrame(gameLoop);
