// Fishing Mini-game with Finite State Machine

const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const states = {
  MENU: 'menu',
  PLAYING: 'playing',
  PAUSED: 'paused',
  GAMEOVER: 'gameover'
};

let currentState = states.MENU;
let score = 0;
let fishPosition = { x: 400, y: 300 };
let rodPosition = { x: 400, y: 550 };
let fishingRodAngle = 0;
let catchTimer = null;
let gameInterval = null;

function drawMenu() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '36px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.fillText('Fishing Game', canvas.width / 2, canvas.height / 2 - 20);
  ctx.fillText('Click to Start', canvas.width / 2, canvas.height / 2 + 20);
}

function drawPlaying() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '24px Arial';
  ctx.fillStyle = 'black';
  ctx.fillText(`Score: ${score}`, 20, 30);
  ctx.beginPath();
  ctx.arc(fishPosition.x, fishPosition.y, 20, 0, Math.PI * 2);
  ctx.fillStyle = 'blue';
  ctx.fill();
  ctx.beginPath();
  ctx.moveTo(rodPosition.x, rodPosition.y);
  ctx.lineTo(rodPosition.x + Math.cos(fishingRodAngle) * 150, rodPosition.y + Math.sin(fishingRodAngle) * 150);
  ctx.strokeStyle = 'orange';
  ctx.lineWidth = 5;
  ctx.stroke();
}

function drawPaused() {
  ctx.font = '36px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.fillText('Paused', canvas.width / 2, canvas.height / 2);
}

function drawGameOver() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  ctx.font = '36px Arial';
  ctx.fillStyle = 'black';
  ctx.textAlign = 'center';
  ctx.fillText('Game Over', canvas.width / 2, canvas.height / 2 - 20);
  ctx.fillText(`Final Score: ${score}`, canvas.width / 2, canvas.height / 2 + 20);
}

function updatePlaying() {
  if (catchTimer) {
    const elapsed = Date.now() - catchTimer;
    if (elapsed > 2000) {
      score += 10;
      catchTimer = null;
      fishPosition = { x: Math.random() * canvas.width, y: Math.random() * (canvas.height - 200) + 100 };
    }
  }
}

function handleInput(event) {
  switch (currentState) {
    case states.MENU:
      if (event.type === 'click') {
        currentState = states.PLAYING;
      }
      break;
    case states.PLAYING:
      if (event.type === 'keydown' && event.code === 'Space') {
        currentState = states.PAUSED;
      }
      break;
    case states.PAUSED:
      if (event.type === 'keydown' && event.code === 'Space') {
        currentState = states.PLAYING;
      }
      break;
    case states.GAMEOVER:
      if (event.type === 'click') {
        currentState = states.MENU;
        score = 0;
      }
      break;
  }
}

function update() {
  switch (currentState) {
    case states.PLAYING:
      updatePlaying();
      break;
  }
  requestAnimationFrame(update);
}

function render() {
  switch (currentState) {
    case states.MENU:
      drawMenu();
      break;
    case states.PLAYING:
      drawPlaying();
      break;
    case states.PAUSED:
      drawPlaying();
      drawPaused();
      break;
    case states.GAMEOVER:
      drawGameOver();
      break;
  }
  requestAnimationFrame(render);
}

canvas.addEventListener('click', handleInput);
document.addEventListener('keydown', handleInput);

update();
render();
