const player = {
  x: 100,
  y: 100,
  width: 50,
  height: 50,
  velocityX: 0,
  velocityY: 0,
  grounded: false,
};

const platforms = [
  { x: 0, y: 550, width: 800, height: 50 },
  { x: 200, y: 400, width: 200, height: 20 },
  { x: 500, y: 300, width: 100, height: 20 },
];

let highScore = localStorage.getItem('highScore') ? parseInt(localStorage.getItem('highScore'), 10) : 0;

function updatePlayer(input, dt) {
  player.velocityX = input.left ? -5 : input.right ? 5 : 0;

  if (input.up && player.grounded) {
    player.velocityY = -10;
    player.grounded = false;
  }

  player.velocityY += gravity;
  player.x += player.velocityX * dt;
  player.y += player.velocityY * dt;

  if (player.x < 0) player.x = 0;
  if (player.x > canvas.width - player.width) player.x = canvas.width - player.width;

  for (const platform of platforms) {
    if (
      player.x < platform.x + platform.width &&
      player.x + player.width > platform.x &&
      player.y < platform.y + platform.height &&
      player.y + player.height > platform.y
    ) {
      if (player.velocityY > 0) {
        player.y = platform.y - player.height;
        player.velocityY = 0;
        player.grounded = true;
      }
    }
  }

  if (player.y > canvas.height) {
    highScore = Math.max(highScore, player.x);
    localStorage.setItem('highScore', highScore.toString());
    resetPlayer();
  }
}

function resetPlayer() {
  player.x = 100;
  player.y = 100;
  player.velocityX = 0;
  player.velocityY = 0;
  player.grounded = false;
}

function update(dt) {
  const input = {
    left: keys['ArrowLeft'] || keys['a'],
    right: keys['ArrowRight'] || keys['d'],
    up: keys['ArrowUp'] || keys['w'],
  };

  updatePlayer(input, dt);
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'green';
  for (const platform of platforms) {
    ctx.fillRect(platform.x, platform.y, platform.width, platform.height);
  }

  ctx.fillStyle = 'blue';
  ctx.fillRect(player.x, player.y, player.width, player.height);

  ctx.fillStyle = 'black';
  ctx.fillText(`High Score: ${highScore}`, 10, 20);
}

const keys = {};
window.addEventListener('keydown', (e) => (keys[e.key] = true));
window.addEventListener('keyup', (e) => (keys[e.key] = false));

function mainLoop(timestamp) {
  const dt = timestamp - lastTimestamp;
  lastTimestamp = timestamp;
  accumulator += dt;

  while (accumulator >= fixedTimestep) {
    update(fixedTimestep);
    accumulator -= fixedTimestep;
  }

  render();
  requestAnimationFrame(mainLoop);
}

