  canvas.width = roomWidth * tileSize * dpr;
  canvas.height = roomHeight * tileSize * dpr;
  canvas.style.width = `${roomWidth * tileSize}px`;
  canvas.style.height = `${roomHeight * tileSize}px`;
  ctx.scale(dpr, dpr);
}

window.addEventListener('resize', setCanvasSize);
setCanvasSize();

const player = { x: 1, y: 1 };
const ai = { x: 8, y: 8 };
const walls = [
  { x: 0, y: 0, width: roomWidth, height: 1 },
  { x: 0, y: 0, width: 1, height: roomHeight },
  { x: 0, y: roomHeight - 1, width: roomWidth, height: 1 },
  { x: roomWidth - 1, y: 0, width: 1, height: roomHeight }
];

function drawTile(x, y, color) {
  ctx.fillStyle = color;
  ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
}

function drawRoom() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  walls.forEach(wall => {
    ctx.fillStyle = 'gray';
    ctx.fillRect(wall.x * tileSize, wall.y * tileSize, wall.width * tileSize, wall.height * tileSize);
  });
  drawTile(player.x, player.y, 'blue');
  drawTile(ai.x, ai.y, 'red');
}

function moveEntity(entity, dx, dy) {
  const newX = entity.x + dx;
  const newY = entity.y + dy;
  if (!walls.some(wall => 
      newX + 1 > wall.x && newX < wall.x + wall.width &&
      newY + 1 > wall.y && newY < wall.y + wall.height
    )) {
    entity.x = newX;
    entity.y = newY;
  }
}

function aiMove() {
  const dx = player.x - ai.x;
  const dy = player.y - ai.y;
  if (dx > 0) moveEntity(ai, 1, 0);
  else if (dx < 0) moveEntity(ai, -1, 0);
  if (dy > 0) moveEntity(ai, 0, 1);
  else if (dy < 0) moveEntity(ai, 0, -1);
}

function gameLoop() {
  aiMove();
  drawRoom();
  requestAnimationFrame(gameLoop);
}

document.addEventListener('keydown', (e) => {
  switch (e.key) {
    case 'ArrowUp': moveEntity(player, 0, -1); break;
    case 'ArrowDown': moveEntity(player, 0, 1); break;
    case 'ArrowLeft': moveEntity(player, -1, 0); break;
    case 'ArrowRight': moveEntity(player, 1, 0); break;
  }
  drawRoom();
});

