  ctx.fillText(`Final Score: ${score}`, canvas.width / 2 - 100, canvas.height / 2 + 20);
  ctx.fillText('Press Space to Restart', canvas.width / 2 - 130, canvas.height / 2 + 50);
}

function updateMenu(delta) {
  if (isKeyPressed(' ')) {
    currentState = states.PLAYING;
    isFishing = true;
  }
}

function updatePlaying(delta) {
  if (isKeyPressed(' ')) {
    currentState = states.PAUSED;
    isFishing = false;
  } else {
    if (isFishing) {
      fish.y -= fish.speed;
      if (fish.y < 0) {
        fishCaught++;
        score += 10;
        fish.y = canvas.height;
        isFishing = false;
      }
    }
  }
}

function updatePaused(delta) {
  if (isKeyPressed(' ')) {
    currentState = states.PLAYING;
    isFishing = true;
  }
}

function updateGameOver(delta) {
  if (isKeyPressed(' ')) {
    currentState = states.MENU;
    score = 0;
    fishCaught = 0;
  }
}

function render() {
  switch (currentState) {
    case states.MENU:
      drawMenu();
      break;
    case states.PLAYING:
      drawPlaying();
      break;
    case states.PAUSED:
      drawPaused();
      break;
    case states.GAMEOVER:
      drawGameOver();
      break;
  }
}

function update(delta) {
  switch (currentState) {
    case states.MENU:
      updateMenu(delta);
      break;
    case states.PLAYING:
      updatePlaying(delta);
      break;
    case states.PAUSED:
      updatePaused(delta);
      break;
    case states.GAMEOVER:
      updateGameOver(delta);
      break;
  }
}

function gameLoop() {
  const now = performance.now();
  const delta = now - lastTime;
  lastTime = now;

  update(delta);
  render();

  requestAnimationFrame(gameLoop);
}

function isKeyPressed(key) {
  const keys = {
    ' ': 32
  };
  return keys[key] && keys[key] === true;
