    ctx.fillText('Press Enter to Restart', 80, 300);
}

function render() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    if (state === 'playing') {
        drawSnake();
        drawFood();
        drawScore();
    } else if (state === 'menu') {
        renderMenu();
    } else if (state === 'gameover') {
        renderGameOver();
    }
}

