const TPS = 60;
const MS_PER_TICK = 1000 / TPS;
let lastFrameTime = 0;
let accumulatedTime = 0;

const player = {
  health: 100,
  maxHealth: 100,
  x: canvas.width / 2,
  y: canvas.height - 50,
  width: 30,
  height: 30,
  respawnCooldown: 0,
  respawnTime: 3000 // 3 seconds
};

const enemies = [];
const enemySpawnInterval = 1000; // 1 second
let lastEnemySpawnTime = 0;

function mainLoop(currentTime) {
  const dt = currentTime - lastFrameTime;
  lastFrameTime = currentTime;
  accumulatedTime += dt;

  while (accumulatedTime >= MS_PER_TICK) {
    update(MS_PER_TICK);
    accumulatedTime -= MS_PER_TICK;
  }

  render();
  requestAnimationFrame(mainLoop);
}

function update(dt) {
  if (player.respawnCooldown > 0) {
    player.respawnCooldown -= dt;
    if (player.respawnCooldown <= 0) {
      player.respawn();
    }
  } else {
    // Player movement (simple example)
    if (keys['ArrowLeft']) player.x -= 2;
    if (keys['ArrowRight']) player.x += 2;
  }

  // Enemy spawning
  if (currentTime - lastEnemySpawnTime >= enemySpawnInterval) {
    spawnEnemy();
    lastEnemySpawnTime = currentTime;
  }

  // Update enemies
  for (let i = enemies.length - 1; i >= 0; i--) {
    const enemy = enemies[i];
    enemy.x += 1; // Simple enemy movement
    if (enemy.x > canvas.width) {
      enemies.splice(i, 1);
    }
    checkCollision(player, enemy);
  }
}

function render() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);

  // Draw player
  ctx.fillStyle = player.health > 0 ? 'green' : 'red';
  ctx.fillRect(player.x, player.y, player.width, player.height);

  // Draw enemies
  ctx.fillStyle = 'red';
  enemies.forEach(enemy => {
    ctx.fillRect(enemy.x, enemy.y, 20, 20);
  });

  // Draw health bar
  ctx.fillStyle = 'white';
  ctx.fillRect(10, 10, 100, 10);
  ctx.fillStyle = 'green';
  ctx.fillRect(10, 10, (player.health / player.maxHealth) * 100, 10);
}

function spawnEnemy() {
  enemies.push({
    x: -20,
    y: Math.random() * (canvas.height - 20),
    width: 20,
    height: 20
  });
}

function checkCollision(player, enemy) {
  if (player.health > 0 &&
      player.x < enemy.x + enemy.width &&
      player.x + player.width > enemy.x &&
      player.y < enemy.y + enemy.height &&
      player.y + player.height > enemy.y) {
    player.takeDamage(10);
  }
}

player.takeDamage = function(amount) {
  this.health -= amount;
  if (this.health <= 0) {
    this.respawnCooldown = this.respawnTime;
