        ctx.arc(powerUp.x, powerUp.y, powerUp.radius, 0, Math.PI * 2);
        ctx.fillStyle = powerUp.color;
        ctx.fill();

        if (player.x < powerUp.x + powerUp.radius &&
            player.x + player.width > powerUp.x &&
            player.y < powerUp.y + powerUp.radius &&
