      this.y = canvas.height - this.height;
      this.speed = 0;
    }
  },
  jump() {
    this.speed = this.jump;
  }
};

const pipes = [];
const pipeWidth = 50;
const pipeGap = 150;
const pipeSpeed = 2;

function createPipe() {
  const height = Math.random() * (canvas.height - pipeGap);
  pipes.push({ x: canvas.width, y: 0, height, width: pipeWidth });
  pipes.push({ x: canvas.width, y: height + pipeGap, height: canvas.height - height - pipeGap, width: pipeWidth });
}

function updatePipes() {
  pipes.forEach(pipe => pipe.x -= pipeSpeed);
  if (pipes[0] && pipes[0].x + pipeWidth < 0) {
    pipes.shift();
    pipes.shift();
    createPipe();
    combo = 0;
  }
}

function drawPipes() {
  ctx.fillStyle = 'green';
  pipes.forEach(pipe => ctx.fillRect(pipe.x, pipe.y, pipe.width, pipe.height));
}

let combo = 0;
let score = 0;
let gameLoop;
let gameOver = false;

function collisionCheck() {
  pipes.forEach(pipe => {
    if (bird.x < pipe.x + pipe.width && bird.x + bird.width > pipe.x && bird.y < pipe.y + pipe.height && bird.y + bird.height > pipe.y) {
      gameOver = true;
    }
  });
  if (bird.y + bird.height > canvas.height) {
    gameOver = true;
  }
}

function updateScore() {
