// One-button endless runner with a basic AI opponent
const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

// Device pixel ratio handling
const dpr = window.devicePixelRatio || 1;
canvas.width = window.innerWidth * dpr;
canvas.height = window.innerHeight * dpr;
ctx.scale(dpr, dpr);

let player = { x: 50, y: 50, width: 20, height: 20, speed: 5 };
let ai = { x: 50, y: 100, width: 20, height: 20, speed: 3, targetX: 0 };
let obstacles = [];
let score = 0;
let gameOver = false;

function createObstacle() {
    obstacles.push({
        x: canvas.width,
        y: Math.random() * (canvas.height - 50) + 25,
        width: 30,
        height: 30,
        speed: 4
    });
}

function updateAI() {
    ai.targetX = player.x;
    if (ai.x < ai.targetX) {
        ai.x += ai.speed;
    } else if (ai.x > ai.targetX) {
        ai.x -= ai.speed;
    }
}

function updateGame() {
    if (!gameOver) {
        updateAI();
        player.x = Math.min(player.x + player.speed, canvas.width - player.width);
        obstacles.forEach(obstacle => {
            obstacle.x -= obstacle.speed;
            if (obstacle.x + obstacle.width < 0) {
                obstacles.shift();
                score++;
            }
        });
        checkCollisions();
    }
}

function checkCollisions() {
    const playerRect = { x: player.x, y: player.y, width: player.width, height: player.height };
    const aiRect = { x: ai.x, y: ai.y, width: ai.width, height: ai.height };
    if (rectIntersects(playerRect, aiRect)) {
        gameOver = true;
    }
    obstacles.forEach(obstacle => {
        if (rectIntersects(playerRect, obstacle)) {
            gameOver = true;
        }
    });
}

function rectIntersects(rect1, rect2) {
    return !(rect1.x + rect1.width < rect2.x ||
             rect1.x > rect2.x + rect2.width ||
             rect1.y + rect1.height < rect2.y ||
             rect1.y > rect2.y + rect2.height);
}

function drawGame() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = 'blue';
    ctx.fillRect(player.x, player.y, player.width, player.height);
    ctx.fillStyle = 'green';
    ctx.fillRect(ai.x, ai.y, ai.width, ai.height);
    ctx.fillStyle = 'red';
    obstacles.forEach(obstacle => {
        ctx.fillRect(obstacle.x, obstacle.y, obstacle.width, obstacle.height);
    });
    ctx.fillStyle = 'black';
    ctx.font = '20px Arial';
    ctx.fillText('Score: ' + score, 10, 30);
    if (gameOver) {
        ctx.fillText('Game Over', canvas.width / 2 - 50, canvas.height / 2);
    }
}

function gameLoop() {
    updateGame();
    drawGame();
    requestAnimationFrame(gameLoop);
}

canvas.addEventListener('click', () => {
    if (gameOver) {
        player = { x: 50, y: 50, width: 20, height: 20, speed: 5 };
        ai = { x: 50, y: 100, width: 20, height: 20, speed: 3, targetX: 0 };
        obstacles = [];
        score = 0;
        gameOver = false;
    }
});

setInterval(createObstacle, 1500);
gameLoop();
