const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const scale = 20;
const rows = 32;
const columns = 40;

canvas.width = columns * scale;
canvas.height = rows * scale;

let snake;
let food;
let score = 0;
let highScore = 0;
let lastTime = 0;
const speed = 10;

const directions = {
  UP: { x: 0, y: -1 },
  DOWN: { x: 0, y: 1 },
  LEFT: { x: -1, y: 0 },
  RIGHT: { x: 1, y: 0 }
};

let currentDirection = directions.RIGHT;

document.addEventListener('keydown', event => {
  switch (event.key) {
    case 'ArrowUp':
      if (currentDirection !== directions.DOWN) currentDirection = directions.UP;
      break;
    case 'ArrowDown':
      if (currentDirection !== directions.UP) currentDirection = directions.DOWN;
      break;
    case 'ArrowLeft':
      if (currentDirection !== directions.RIGHT) currentDirection = directions.LEFT;
      break;
    case 'ArrowRight':
      if (currentDirection !== directions.LEFT) currentDirection = directions.RIGHT;
      break;
  }
});

function getHighScore() {
  return localStorage.getItem('snakeHighScore') || 0;
}

function setHighScore(newHighScore) {
  localStorage.setItem('snakeHighScore', newHighScore);
}

function init() {
  snake = [{ x: 10, y: 10 }];
  food = { x: Math.floor(Math.random() * columns), y: Math.floor(Math.random() * rows) };
  score = 0;
  highScore = getHighScore();
  lastTime = 0;
}

function getRandomFoodPosition() {
  let newFood;
  do {
    newFood = { x: Math.floor(Math.random() * columns), y: Math.floor(Math.random() * rows) };
  } while (snake.some(segment => segment.x === newFood.x && segment.y === newFood.y));
  return newFood;
}

function update(time) {
  const delta = time - lastTime;

  if (delta > 1000 / speed) {
    const head = { x: snake[0].x + currentDirection.x, y: snake[0].y + currentDirection.y };

    if (head.x < 0 || head.x >= columns || head.y < 0 || head.y >= rows || snake.some(segment => segment.x === head.x && segment.y === head.y)) {
      if (score > highScore) {
        setHighScore(score);
        highScore = score;
      }
      init();
      return;
    }

    snake.unshift(head);

    if (head.x === food.x && head.y === food.y) {
      score++;
      food = getRandomFoodPosition();
    } else {
      snake.pop();
    }

    lastTime = time;
  }

  requestAnimationFrame(update);
}

function draw() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);

  ctx.fillStyle = 'lime';
  snake.forEach(segment => ctx.fillRect(segment.x * scale, segment.y * scale, scale, scale));

  ctx.fillStyle = 'red';
  ctx.fillRect(food.x * scale, food.y * scale, scale, scale);

  ctx.fillStyle = 'white';
  ctx.font = '20px Arial';
  ctx.fillText(`Score: ${score}`, 10, 30);
  ctx.fillText(`High Score: ${highScore}`, 10, 60);
}

init();
update(0);
setInterval(draw, 100);
