// Quest System
class Quest {
  constructor() {
    this.quests = [];
  }

  addQuest(quest) {
    this.quests.push(quest);
    console.log(`Quest added: ${quest.name}`);
  }

  completeQuest(questName) {
    const quest = this.quests.find(q => q.name === questName);
    if (quest) {
      quest.completed = true;
      console.log(`Quest completed: ${questName}`);
      return quest;
    }
    console.log(`Quest not found: ${questName}`);
    return null;
  }
}

// Reward System
class Reward {
  constructor() {
    this.rewards = [];
  }

  addReward(reward) {
    this.rewards.push(reward);
    console.log(`Reward added: ${reward.name}`);
  }

  grantReward(rewardName) {
    const reward = this.rewards.find(r => r.name === rewardName);
    if (reward) {
      console.log(`Reward granted: ${rewardName}`);
      return reward;
    }
    console.log(`Reward not found: ${rewardName}`);
    return null;
  }
}

// Inventory System
class Inventory {
  constructor() {
    this.items = [];
  }

  addItem(item) {
    this.items.push(item);
    console.log(`Item added to inventory: ${item.name}`);
  }

  removeItem(itemName) {
    const itemIndex = this.items.findIndex(i => i.name === itemName);
    if (itemIndex !== -1) {
      const item = this.items.splice(itemIndex, 1)[0];
      console.log(`Item removed from inventory: ${itemName}`);
      return item;
    }
    console.log(`Item not found in inventory: ${itemName}`);
    return null;
  }
}

// Coordinator System
class Coordinator {
  constructor() {
    this.questSystem = new Quest();
    this.rewardSystem = new Reward();
    this.inventorySystem = new Inventory();

    // Wire up the systems
    this.questSystem.addEventListener('questCompleted', (event) => {
      const quest = event.detail;
      if (quest.reward) {
        this.rewardSystem.grantReward(quest.reward);
      }
    });

    this.rewardSystem.addEventListener('rewardGranted', (event) => {
      const reward = event.detail;
      if (reward.item) {
        this.inventorySystem.addItem(reward.item);
      }
    });
  }

  addQuest(quest) {
    this.questSystem.addQuest(quest);
  }

  completeQuest(questName) {
    const quest = this.questSystem.completeQuest(questName);
    if (quest && quest.reward) {
      const rewardEvent = new CustomEvent('questCompleted', { detail: quest });
      document.dispatchEvent(rewardEvent);
    }
  }

  addReward(reward) {
    this.rewardSystem.addReward(reward);
  }

  grantReward(rewardName) {
    const reward = this.rewardSystem.grantReward(rewardName);
    if (reward && reward.item) {
      const itemEvent = new CustomEvent('rewardGranted', { detail: reward });
      document.dispatchEvent(itemEvent);
    }
  }

  addItem(item) {
    this.inventorySystem.addItem(item);
  }

  removeItem(itemName) {
    this.inventorySystem.removeItem(itemName);
  }
}

