// Memory Card Flip Game

const canvas = document.createElement('canvas');
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

let canvasWidth = window.innerWidth;
let canvasHeight = window.innerHeight;
const devicePixelRatio = window.devicePixelRatio;

canvas.width = canvasWidth * devicePixelRatio;
canvas.height = canvasHeight * devicePixelRatio;
ctx.scale(devicePixelRatio, devicePixelRatio);

const cardSize = 100;
const margin = 10;
const cols = Math.floor(canvasWidth / (cardSize + margin));
const rows = Math.floor(canvasHeight / (cardSize + margin));
const totalCards = cols * rows;
const cardImages = [];
let flippedCards = [];
let score = 0;
let gameOver = false;

function loadImages() {
    for (let i = 0; i < totalCards / 2; i++) {
        const img = new Image();
        img.src = `https://via.placeholder.com/100/${Math.random().toString(16).slice(2, 8)}`;
        cardImages.push(img, img);
    }
}

function shuffle(array) {
    for (let i = array.length - 1; i > 0; i--) {
        const j = Math.floor(Math.random() * (i + 1));
        [array[i], array[j]] = [array[j], array[i]];
    }
}

function drawCard(x, y, img) {
    ctx.fillStyle = 'white';
    ctx.fillRect(x, y, cardSize, cardSize);
    ctx.strokeStyle = 'black';
    ctx.strokeRect(x, y, cardSize, cardSize);
    if (img) {
        ctx.drawImage(img, x, y, cardSize, cardSize);
    }
}

function drawBoard() {
    for (let i = 0; i < rows; i++) {
        for (let j = 0; j < cols; j++) {
            const index = i * cols + j;
            const x = j * (cardSize + margin);
            const y = i * (cardSize + margin);
            const img = cardImages[index];
            drawCard(x, y, flippedCards.includes(index) ? img : null);
        }
    }
}

function checkMatch() {
    if (flippedCards.length === 2) {
        const [card1, card2] = flippedCards;
        if (cardImages[card1] === cardImages[card2]) {
            score++;
            if (score === totalCards / 2) {
                gameOver = true;
            }
        } else {
            setTimeout(() => {
                flippedCards = [];
            }, 1000);
        }
        flippedCards = [];
    }
}

function gameLoop() {
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    drawBoard();
    ctx.fillStyle = 'black';
    ctx.fillText(`Score: ${score}`, 10, 20);
    if (gameOver) {
        ctx.fillText('Game Over!', canvasWidth / 2 - 50, canvasHeight / 2);
    } else {
        requestAnimationFrame(gameLoop);
    }
}

canvas.addEventListener('click', (event) => {
    if (flippedCards.length < 2 && !gameOver) {
        const rect = canvas.getBoundingClientRect();
        const x = Math.floor((event.clientX - rect.left) / (cardSize + margin));
        const y = Math.floor((event.clientY - rect.top) / (cardSize + margin));
        const index = y * cols + x;
        if (!flippedCards.includes(index)) {
            flippedCards.push(index);
            checkMatch();
        }
    }
});

window.addEventListener('resize', () => {
    canvasWidth = window.innerWidth;
    canvasHeight = window.innerHeight;
    canvas.width = canvasWidth * devicePixelRatio;
    canvas.height = canvasHeight * devicePixelRatio;
    ctx.scale(devicePixelRatio, devicePixelRatio);
});

loadImages();
shuffle(cardImages);
gameLoop();
