const canvas = document.createElement('canvas');
canvas.width = 800;
canvas.height = 600;
document.body.appendChild(canvas);
const ctx = canvas.getContext('2d');

const tileSize = 32;
const roomWidth = 20;
const roomHeight = 15;

const states = {
  MENU: 'menu',
  PLAYING: 'playing',
  PAUSED: 'paused',
  GAMEOVER: 'gameover'
};

let currentState = states.MENU;
let player = { x: 1, y: 1 };
let tiles = [];

function initializeTiles() {
  tiles = Array.from({ length: roomHeight }, () =>
    Array.from({ length: roomWidth }, () => Math.random() > 0.5 ? 1 : 0)
  );
}

function drawMenu() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '32px Arial';
  ctx.fillText('Press SPACE to Start', canvas.width / 2 - 150, canvas.height / 2);
}

function drawPlaying() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  tiles.forEach((row, y) => {
    row.forEach((tile, x) => {
      ctx.fillStyle = tile ? 'gray' : 'lightgray';
      ctx.fillRect(x * tileSize, y * tileSize, tileSize, tileSize);
    });
  });
  ctx.fillStyle = 'white';
  ctx.fillRect(player.x * tileSize, player.y * tileSize, tileSize, tileSize);
}

function drawPaused() {
  ctx.fillStyle = 'rgba(0, 0, 0, 0.5)';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '32px Arial';
  ctx.fillText('Paused', canvas.width / 2 - 60, canvas.height / 2);
}

function drawGameOver() {
  ctx.fillStyle = 'black';
  ctx.fillRect(0, 0, canvas.width, canvas.height);
  ctx.fillStyle = 'white';
  ctx.font = '32px Arial';
  ctx.fillText('Game Over', canvas.width / 2 - 80, canvas.height / 2);
  ctx.fillText('Press R to Restart', canvas.width / 2 - 150, canvas.height / 2 + 40);
}

function updatePlaying() {
  if (keys['ArrowUp'] && player.y > 0) player.y--;
  if (keys['ArrowDown'] && player.y < roomHeight - 1) player.y++;
  if (keys['ArrowLeft'] && player.x > 0) player.x--;
  if (keys['ArrowRight'] && player.x < roomWidth - 1) player.x++;
}

const keys = {};
window.addEventListener('keydown', e => {
  keys[e.key] = true;
  if (currentState === states.MENU && keys[' ']) {
    currentState = states.PLAYING;
    initializeTiles();
  } else if (currentState === states.PLAYING && keys['Escape']) {
    currentState = states.PAUSED;
  } else if (currentState === states.PAUSED && keys['Escape']) {
    currentState = states.PLAYING;
  } else if (currentState === states.GAMEOVER && keys['r']) {
    currentState = states.PLAYING;
    initializeTiles();
  }
});

window.addEventListener('keyup', e => {
  delete keys[e.key];
});

function gameLoop() {
  ctx.clearRect(0, 0, canvas.width, canvas.height);
  if (currentState === states.PLAYING) {
    updatePlaying();
    drawPlaying();
  } else if (currentState === states.MENU) {
    drawMenu();
  } else if (currentState === states.PAUSED) {
    drawPaused();
  } else if (currentState === states.GAMEOVER) {
    drawGameOver();
  }
  requestAnimationFrame(gameLoop);
}

gameLoop();
